[CmdletBinding()]
param(
    [switch]$LoadFunctionsOnly,
    [string]$BlueprintRoot
)

$ErrorActionPreference = 'Stop'

if ([string]::IsNullOrWhiteSpace($BlueprintRoot)) {
    $BlueprintRoot = Split-Path -Parent $MyInvocation.MyCommand.Path
}

function Test-ValuePresent {
    param($Value)

    if ($null -eq $Value) { return $false }
    if ($Value -is [string]) { return -not [string]::IsNullOrWhiteSpace($Value) }
    if ($Value -is [System.Collections.IEnumerable] -and $Value -isnot [string]) {
        foreach ($item in @($Value)) {
            if (Test-ValuePresent $item) { return $true }
        }
        return $false
    }
    return $true
}

function Test-Sha256Token {
    param($Value)
    return $Value -is [string] -and [string]$Value -cmatch '^sha256:[0-9a-f]{64}$'
}

function Test-NonBlankString {
    param($Value)

    return $Value -is [string] -and -not [string]::IsNullOrWhiteSpace([string]$Value)
}

function Test-IsWindowsRuntime {
    # Platform security semantics must come from the runtime, never from the
    # mutable OS environment variable supplied by a caller or CI job.
    return [Environment]::OSVersion.Platform -eq [PlatformID]::Win32NT
}

function Initialize-BlueprintTimestampInterop {
    if ('OperationsBlueprint.StrictRfc3339' -as [type]) { return $true }
    try {
        Add-Type -TypeDefinition @'
using System;
using System.Globalization;
using System.Text.RegularExpressions;

namespace OperationsBlueprint {
    public static class StrictRfc3339 {
        private static readonly Regex Shape = new Regex(
            @"^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(?:\.[0-9]{1,7})?(?:Z|[+-][0-9]{2}:[0-9]{2})$",
            RegexOptions.CultureInvariant);
        private static readonly string[] Formats = new[] {
            "yyyy-MM-dd'T'HH:mm:ss'Z'",
            "yyyy-MM-dd'T'HH:mm:ss.FFFFFFF'Z'",
            "yyyy-MM-dd'T'HH:mm:sszzz",
            "yyyy-MM-dd'T'HH:mm:ss.FFFFFFFzzz"
        };
        public static bool TryParse(string value, out DateTimeOffset result) {
            result = DateTimeOffset.MinValue;
            if (String.IsNullOrEmpty(value) || !Shape.IsMatch(value)) { return false; }
            return DateTimeOffset.TryParseExact(
                value,
                Formats,
                CultureInfo.InvariantCulture,
                DateTimeStyles.AssumeUniversal | DateTimeStyles.AdjustToUniversal,
                out result);
        }
    }

    public static class StrictIsoDate {
        private static readonly Regex Shape = new Regex(
            @"^[0-9]{4}-[0-9]{2}-[0-9]{2}$",
            RegexOptions.CultureInvariant);
        public static bool TryParse(string value, out DateTimeOffset result) {
            result = DateTimeOffset.MinValue;
            if (String.IsNullOrEmpty(value) || !Shape.IsMatch(value)) { return false; }
            DateTime date;
            if (!DateTime.TryParseExact(
                value,
                "yyyy-MM-dd",
                CultureInfo.InvariantCulture,
                DateTimeStyles.None,
                out date)) { return false; }
            result = new DateTimeOffset(DateTime.SpecifyKind(date, DateTimeKind.Utc));
            return true;
        }
    }
}
'@ -ErrorAction Stop
        return $null -ne ('OperationsBlueprint.StrictRfc3339' -as [type])
    }
    catch { return $false }
}

if (-not (Initialize-BlueprintTimestampInterop)) {
    throw 'Strict timestamp parser initialization failed.'
}

function Initialize-BlueprintWindowsFileSystemInterop {
    if ('OperationsBlueprint.NativeFileSystemSecurity' -as [type]) { return $true }
    if (-not (Test-IsWindowsRuntime)) { return $false }

    try {
        Add-Type -TypeDefinition @'
using System;
using System.Collections.Generic;
using System.ComponentModel;
using System.IO;
using System.Runtime.InteropServices;
using System.Security.Cryptography;
using System.Text;
using Microsoft.Win32.SafeHandles;

namespace OperationsBlueprint {
    public static class NativeFileSystemSecurity {
        private const uint FILE_READ_ATTRIBUTES = 0x80;
        private const uint FILE_WRITE_DATA = 0x2;
        private const uint FILE_APPEND_DATA = 0x4;
        private const uint FILE_WRITE_EA = 0x10;
        private const uint FILE_DELETE_CHILD = 0x40;
        private const uint FILE_WRITE_ATTRIBUTES = 0x100;
        private const uint DELETE_ACCESS = 0x00010000;
        private const uint WRITE_DAC = 0x00040000;
        private const uint WRITE_OWNER = 0x00080000;
        private const uint FILE_SHARE_READ = 0x1;
        private const uint FILE_SHARE_WRITE = 0x2;
        private const uint FILE_SHARE_DELETE = 0x4;
        private const uint OPEN_EXISTING = 3;
        private const uint FILE_FLAG_BACKUP_SEMANTICS = 0x02000000;
        private const uint TOKEN_QUERY = 0x0008;
        private const uint TOKEN_DUPLICATE = 0x0002;
        private const uint MAXIMUM_ALLOWED = 0x02000000;
        private const int SECURITY_IMPERSONATION = 2;
        private const int SE_FILE_OBJECT = 1;
        private const uint OWNER_GROUP_DACL_SECURITY_INFORMATION = 0x00000007;
        private const uint ERROR_INSUFFICIENT_BUFFER = 122;
        private const int FileCaseSensitiveInfo = 23;
        private const uint FILE_CS_FLAG_CASE_SENSITIVE_DIR = 0x1;
        private const uint DRIVE_FIXED = 3;

        [StructLayout(LayoutKind.Sequential)]
        private struct FILE_CASE_SENSITIVE_INFO {
            public uint Flags;
        }

        [StructLayout(LayoutKind.Sequential)]
        private struct GENERIC_MAPPING {
            public uint GenericRead;
            public uint GenericWrite;
            public uint GenericExecute;
            public uint GenericAll;
        }

        [DllImport("kernel32.dll", CharSet = CharSet.Unicode, SetLastError = true)]
        private static extern SafeFileHandle CreateFileW(
            string fileName,
            uint desiredAccess,
            uint shareMode,
            IntPtr securityAttributes,
            uint creationDisposition,
            uint flagsAndAttributes,
            IntPtr templateFile);

        [DllImport("kernel32.dll", SetLastError = true)]
        [return: MarshalAs(UnmanagedType.Bool)]
        private static extern bool GetFileInformationByHandleEx(
            SafeFileHandle file,
            int fileInformationClass,
            out FILE_CASE_SENSITIVE_INFO fileInformation,
            uint bufferSize);

        [DllImport("kernel32.dll", CharSet = CharSet.Unicode, SetLastError = true)]
        private static extern uint GetDriveTypeW(string rootPathName);

        [DllImport("kernel32.dll", CharSet = CharSet.Unicode, SetLastError = true)]
        private static extern uint QueryDosDeviceW(
            string deviceName,
            StringBuilder targetPath,
            int maximumLength);

        [DllImport("kernel32.dll", CharSet = CharSet.Unicode, SetLastError = true)]
        private static extern uint GetFinalPathNameByHandleW(
            SafeFileHandle file,
            StringBuilder filePath,
            uint filePathSize,
            uint flags);

        [DllImport("kernel32.dll", CharSet = CharSet.Unicode, SetLastError = true)]
        [return: MarshalAs(UnmanagedType.Bool)]
        private static extern bool GetVolumeInformationW(
            string rootPathName,
            StringBuilder volumeNameBuffer,
            uint volumeNameSize,
            out uint volumeSerialNumber,
            out uint maximumComponentLength,
            out uint fileSystemFlags,
            StringBuilder fileSystemNameBuffer,
            uint fileSystemNameSize);

        [DllImport("kernel32.dll")]
        private static extern IntPtr GetCurrentProcess();

        [DllImport("kernel32.dll", SetLastError = true)]
        [return: MarshalAs(UnmanagedType.Bool)]
        private static extern bool CloseHandle(IntPtr handle);

        [DllImport("kernel32.dll")]
        private static extern IntPtr LocalFree(IntPtr memory);

        [DllImport("advapi32.dll", SetLastError = true)]
        [return: MarshalAs(UnmanagedType.Bool)]
        private static extern bool OpenProcessToken(
            IntPtr processHandle,
            uint desiredAccess,
            out IntPtr tokenHandle);

        [DllImport("advapi32.dll", SetLastError = true)]
        [return: MarshalAs(UnmanagedType.Bool)]
        private static extern bool DuplicateToken(
            IntPtr existingTokenHandle,
            int impersonationLevel,
            out IntPtr duplicateTokenHandle);

        [DllImport("advapi32.dll", CharSet = CharSet.Unicode)]
        private static extern uint GetNamedSecurityInfoW(
            string objectName,
            int objectType,
            uint securityInfo,
            out IntPtr owner,
            out IntPtr group,
            out IntPtr dacl,
            out IntPtr sacl,
            out IntPtr securityDescriptor);

        [DllImport("advapi32.dll", SetLastError = true)]
        [return: MarshalAs(UnmanagedType.Bool)]
        private static extern bool AccessCheck(
            IntPtr securityDescriptor,
            IntPtr clientToken,
            uint desiredAccess,
            ref GENERIC_MAPPING genericMapping,
            IntPtr privilegeSet,
            ref uint privilegeSetLength,
            out uint grantedAccess,
            [MarshalAs(UnmanagedType.Bool)] out bool accessStatus);

        // -1 means the directory could not be independently queried; callers
        // must fail closed. 0 is case-insensitive, 1 is case-sensitive.
        public static int GetDirectoryCaseSensitivity(string path) {
            using (SafeFileHandle handle = CreateFileW(
                path,
                FILE_READ_ATTRIBUTES,
                FILE_SHARE_READ | FILE_SHARE_WRITE | FILE_SHARE_DELETE,
                IntPtr.Zero,
                OPEN_EXISTING,
                FILE_FLAG_BACKUP_SEMANTICS,
                IntPtr.Zero)) {
                if (handle == null || handle.IsInvalid) { return -1; }
                FILE_CASE_SENSITIVE_INFO info;
                if (!GetFileInformationByHandleEx(
                    handle,
                    FileCaseSensitiveInfo,
                    out info,
                    (uint)Marshal.SizeOf(typeof(FILE_CASE_SENSITIVE_INFO)))) {
                    return -1;
                }
                return (info.Flags & FILE_CS_FLAG_CASE_SENSITIVE_DIR) == 0 ? 0 : 1;
            }
        }

        public static bool IsFixedSupportedVolume(string rootPath) {
            if (String.IsNullOrWhiteSpace(rootPath) || GetDriveTypeW(rootPath) != DRIVE_FIXED) {
                return false;
            }
            StringBuilder volumeName = new StringBuilder(261);
            StringBuilder fileSystemName = new StringBuilder(261);
            uint serial;
            uint maximumComponentLength;
            uint flags;
            if (!GetVolumeInformationW(
                rootPath,
                volumeName,
                (uint)volumeName.Capacity,
                out serial,
                out maximumComponentLength,
                out flags,
                fileSystemName,
                (uint)fileSystemName.Capacity)) {
                return false;
            }
            string fileSystem = fileSystemName.ToString();
            return String.Equals(fileSystem, "NTFS", StringComparison.OrdinalIgnoreCase) ||
                String.Equals(fileSystem, "ReFS", StringComparison.OrdinalIgnoreCase);
        }

        public static string GetDosDeviceTarget(string deviceName) {
            if (String.IsNullOrWhiteSpace(deviceName)) { return null; }
            StringBuilder target = new StringBuilder(32768);
            uint length = QueryDosDeviceW(deviceName, target, target.Capacity);
            if (length == 0) { return null; }
            return target.ToString();
        }

        public static string GetFinalPath(string path) {
            using (SafeFileHandle handle = CreateFileW(
                path,
                FILE_READ_ATTRIBUTES,
                FILE_SHARE_READ | FILE_SHARE_WRITE | FILE_SHARE_DELETE,
                IntPtr.Zero,
                OPEN_EXISTING,
                FILE_FLAG_BACKUP_SEMANTICS,
                IntPtr.Zero)) {
                if (handle == null || handle.IsInvalid) { return null; }
                StringBuilder finalPath = new StringBuilder(32768);
                uint length = GetFinalPathNameByHandleW(
                    handle,
                    finalPath,
                    (uint)finalPath.Capacity,
                    0);
                if (length == 0 || length >= finalPath.Capacity) { return null; }
                return finalPath.ToString();
            }
        }

        private sealed class RuntimeFileEntry {
            public string Path;
            public string FullPath;
            public long Length;
            public byte[] Digest;
            public FileStream Stream;
        }

        private sealed class RuntimeDirectoryEntry {
            public string FullPath;
            public SafeFileHandle Handle;
        }

        private static void WriteInt32BigEndian(Stream stream, int value) {
            byte[] bytes = BitConverter.GetBytes(value);
            if (BitConverter.IsLittleEndian) { Array.Reverse(bytes); }
            stream.Write(bytes, 0, bytes.Length);
        }

        private static void WriteInt64BigEndian(Stream stream, long value) {
            byte[] bytes = BitConverter.GetBytes(value);
            if (BitConverter.IsLittleEndian) { Array.Reverse(bytes); }
            stream.Write(bytes, 0, bytes.Length);
        }

        private static string NormalizeFullPath(string path) {
            string fullPath = Path.GetFullPath(path);
            string volumeRoot = Path.GetPathRoot(fullPath);
            if (String.Equals(fullPath, volumeRoot, StringComparison.OrdinalIgnoreCase)) {
                return volumeRoot;
            }
            return fullPath.TrimEnd(
                Path.DirectorySeparatorChar,
                Path.AltDirectorySeparatorChar);
        }

        private static string NormalizeFinalPath(string path) {
            if (String.IsNullOrEmpty(path)) { return null; }
            string normalized = path;
            if (normalized.StartsWith(@"\\?\UNC\", StringComparison.OrdinalIgnoreCase)) {
                normalized = @"\\" + normalized.Substring(8);
            }
            else if (normalized.StartsWith(@"\\?\", StringComparison.OrdinalIgnoreCase)) {
                normalized = normalized.Substring(4);
            }
            try {
                return NormalizeFullPath(normalized);
            }
            catch { return null; }
        }

        private static string GetHandleFinalPath(SafeFileHandle handle) {
            if (handle == null || handle.IsInvalid || handle.IsClosed) { return null; }
            StringBuilder finalPath = new StringBuilder(32768);
            uint length = GetFinalPathNameByHandleW(
                handle,
                finalPath,
                (uint)finalPath.Capacity,
                0);
            if (length == 0 || length >= finalPath.Capacity) { return null; }
            return NormalizeFinalPath(finalPath.ToString());
        }

        private static byte[] HashOpenStream(FileStream stream) {
            stream.Position = 0;
            byte[] digest;
            using (SHA256 sha = SHA256.Create()) { digest = sha.ComputeHash(stream); }
            stream.Position = 0;
            return digest;
        }

        private static string BuildRuntimeTreeDigest(List<RuntimeFileEntry> rows) {
            rows.Sort(delegate(RuntimeFileEntry left, RuntimeFileEntry right) {
                return StringComparer.Ordinal.Compare(left.Path, right.Path);
            });
            using (MemoryStream manifest = new MemoryStream()) {
                byte[] header = Encoding.ASCII.GetBytes("operations-blueprint-git-runtime-tree/1.0.0\0");
                manifest.Write(header, 0, header.Length);
                foreach (RuntimeFileEntry row in rows) {
                    byte[] pathBytes = Encoding.UTF8.GetBytes(row.Path);
                    WriteInt32BigEndian(manifest, pathBytes.Length);
                    manifest.Write(pathBytes, 0, pathBytes.Length);
                    WriteInt64BigEndian(manifest, row.Length);
                    manifest.Write(row.Digest, 0, row.Digest.Length);
                }
                manifest.Position = 0;
                using (SHA256 aggregate = SHA256.Create()) {
                    byte[] digest = aggregate.ComputeHash(manifest);
                    return BitConverter.ToString(digest).Replace("-", "").ToLowerInvariant();
                }
            }
        }

        // Returns 0 only when the effective process token is conclusively
        // denied every mutation right. Any API/query failure returns -1 so a
        // sharing violation or transient filesystem error can never masquerade
        // as an immutable ACL.
        private static int GetEffectiveTokenMutationAccess(
            string path,
            bool directory,
            bool protectChildNamespace) {
            IntPtr processToken = IntPtr.Zero;
            IntPtr impersonationToken = IntPtr.Zero;
            IntPtr securityDescriptor = IntPtr.Zero;
            IntPtr privilegeSet = IntPtr.Zero;
            try {
                if (!OpenProcessToken(
                    GetCurrentProcess(),
                    TOKEN_QUERY | TOKEN_DUPLICATE,
                    out processToken) || processToken == IntPtr.Zero) { return -1; }
                if (!DuplicateToken(
                    processToken,
                    SECURITY_IMPERSONATION,
                    out impersonationToken) || impersonationToken == IntPtr.Zero) { return -1; }

                IntPtr owner;
                IntPtr group;
                IntPtr dacl;
                IntPtr sacl;
                uint securityResult = GetNamedSecurityInfoW(
                    path,
                    SE_FILE_OBJECT,
                    OWNER_GROUP_DACL_SECURITY_INFORMATION,
                    out owner,
                    out group,
                    out dacl,
                    out sacl,
                    out securityDescriptor);
                if (securityResult != 0 || securityDescriptor == IntPtr.Zero || dacl == IntPtr.Zero) {
                    return -1;
                }

                uint mutationMask = directory
                    ? (protectChildNamespace
                        ? FILE_WRITE_DATA | FILE_APPEND_DATA | FILE_WRITE_EA | FILE_DELETE_CHILD | FILE_WRITE_ATTRIBUTES | DELETE_ACCESS | WRITE_DAC | WRITE_OWNER
                        : FILE_WRITE_EA | FILE_DELETE_CHILD | FILE_WRITE_ATTRIBUTES | DELETE_ACCESS | WRITE_DAC | WRITE_OWNER)
                    : FILE_WRITE_DATA | FILE_APPEND_DATA | FILE_WRITE_EA | FILE_WRITE_ATTRIBUTES | DELETE_ACCESS | WRITE_DAC | WRITE_OWNER;
                GENERIC_MAPPING mapping = new GENERIC_MAPPING {
                    GenericRead = 0x00120089,
                    GenericWrite = 0x00120116,
                    GenericExecute = 0x001200A0,
                    GenericAll = 0x001F01FF
                };
                privilegeSet = Marshal.AllocHGlobal(1024);
                uint privilegeSetLength = 1024;
                uint grantedAccess;
                bool accessStatus;
                bool checkedAccess = AccessCheck(
                    securityDescriptor,
                    impersonationToken,
                    MAXIMUM_ALLOWED,
                    ref mapping,
                    privilegeSet,
                    ref privilegeSetLength,
                    out grantedAccess,
                    out accessStatus);
                if (!checkedAccess || !accessStatus) { return -1; }
                return (grantedAccess & mutationMask) == 0 ? 0 : 1;
            }
            catch { return -1; }
            finally {
                if (privilegeSet != IntPtr.Zero) { Marshal.FreeHGlobal(privilegeSet); }
                if (securityDescriptor != IntPtr.Zero) { LocalFree(securityDescriptor); }
                if (impersonationToken != IntPtr.Zero) { CloseHandle(impersonationToken); }
                if (processToken != IntPtr.Zero) { CloseHandle(processToken); }
            }
        }

        // Holds every runtime file, runtime directory, and ancestor through the
        // volume root without write/delete sharing. The handles remain live from
        // the byte digest through child-process exit, then all identities and
        // bytes are independently revalidated before authorization continues.
        public sealed class RuntimeTreeGuard : IDisposable {
            private readonly string rootPath;
            private readonly string rootPrefix;
            private readonly List<RuntimeDirectoryEntry> directories = new List<RuntimeDirectoryEntry>();
            private readonly List<RuntimeFileEntry> files = new List<RuntimeFileEntry>();
            private readonly HashSet<string> runtimeDirectoryPaths = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            private bool disposed;
            public string Digest { get; private set; }

            internal RuntimeTreeGuard(string root) {
                rootPath = NormalizeFullPath(root);
                rootPrefix = rootPath + Path.DirectorySeparatorChar;
            }

            private bool HoldDirectory(
                string path,
                HashSet<string> held,
                bool protectChildNamespace) {
                string fullPath = NormalizeFullPath(path);
                if (!held.Add(fullPath)) { return true; }
                FileAttributes attributes = File.GetAttributes(fullPath);
                if ((attributes & FileAttributes.Directory) == 0 ||
                    (attributes & FileAttributes.ReparsePoint) != 0 ||
                    GetDirectoryCaseSensitivity(fullPath) != 0 ||
                    GetEffectiveTokenMutationAccess(fullPath, true, protectChildNamespace) != 0) { return false; }
                SafeFileHandle handle = CreateFileW(
                    fullPath,
                    FILE_READ_ATTRIBUTES,
                    FILE_SHARE_READ,
                    IntPtr.Zero,
                    OPEN_EXISTING,
                    FILE_FLAG_BACKUP_SEMANTICS,
                    IntPtr.Zero);
                if (handle == null || handle.IsInvalid) {
                    if (handle != null) { handle.Dispose(); }
                    return false;
                }
                string finalPath = GetHandleFinalPath(handle);
                if (!String.Equals(finalPath, fullPath, StringComparison.OrdinalIgnoreCase)) {
                    handle.Dispose();
                    return false;
                }
                directories.Add(new RuntimeDirectoryEntry { FullPath = fullPath, Handle = handle });
                if (protectChildNamespace) { runtimeDirectoryPaths.Add(fullPath); }
                return true;
            }

            internal bool OpenAndHash() {
                HashSet<string> heldDirectories = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                DirectoryInfo ancestor = Directory.GetParent(rootPath);
                while (ancestor != null) {
                    if (!HoldDirectory(ancestor.FullName, heldDirectories, false)) { return false; }
                    ancestor = ancestor.Parent;
                }

                HashSet<string> paths = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                Stack<string> pending = new Stack<string>();
                pending.Push(rootPath);
                while (pending.Count > 0) {
                    string directory = pending.Pop();
                    if (!HoldDirectory(directory, heldDirectories, true)) { return false; }
                    foreach (string entry in Directory.EnumerateFileSystemEntries(directory)) {
                        string entryPath = Path.GetFullPath(entry);
                        if (!entryPath.StartsWith(rootPrefix, StringComparison.OrdinalIgnoreCase)) { return false; }
                        FileAttributes attributes = File.GetAttributes(entryPath);
                        if ((attributes & FileAttributes.ReparsePoint) != 0) { return false; }
                        if ((attributes & FileAttributes.Directory) != 0) {
                            if (!HoldDirectory(entryPath, heldDirectories, true)) { return false; }
                            pending.Push(entryPath);
                            continue;
                        }
                        string relativePath = entryPath.Substring(rootPrefix.Length).Replace('\\', '/');
                        if (String.IsNullOrWhiteSpace(relativePath) || !paths.Add(relativePath)) { return false; }
                        FileStream stream = new FileStream(
                            entryPath,
                            FileMode.Open,
                            FileAccess.Read,
                            FileShare.Read);
                        string finalPath = GetHandleFinalPath(stream.SafeFileHandle);
                        if (!String.Equals(finalPath, entryPath, StringComparison.OrdinalIgnoreCase) ||
                            (File.GetAttributes(entryPath) & FileAttributes.ReparsePoint) != 0) {
                            stream.Dispose();
                            return false;
                        }
                        long length = stream.Length;
                        byte[] digest = HashOpenStream(stream);
                        files.Add(new RuntimeFileEntry {
                            Path = relativePath,
                            FullPath = entryPath,
                            Length = length,
                            Digest = digest,
                            Stream = stream
                        });
                    }
                }
                Digest = BuildRuntimeTreeDigest(files);
                return !String.IsNullOrEmpty(Digest);
            }

            public bool Validate(string expectedDigest) {
                if (disposed || String.IsNullOrEmpty(expectedDigest) ||
                    !String.Equals(Digest, expectedDigest, StringComparison.Ordinal)) { return false; }
                try {
                    foreach (RuntimeDirectoryEntry directory in directories) {
                        if (!String.Equals(
                            GetHandleFinalPath(directory.Handle),
                            directory.FullPath,
                            StringComparison.OrdinalIgnoreCase) ||
                            (File.GetAttributes(directory.FullPath) & FileAttributes.ReparsePoint) != 0) {
                            return false;
                        }
                    }

                    HashSet<string> currentPaths = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                    HashSet<string> currentDirectoryPaths = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                    Stack<string> pending = new Stack<string>();
                    pending.Push(rootPath);
                    while (pending.Count > 0) {
                        string directory = pending.Pop();
                        if (!currentDirectoryPaths.Add(directory)) { return false; }
                        foreach (string entry in Directory.EnumerateFileSystemEntries(directory)) {
                            string entryPath = Path.GetFullPath(entry);
                            if (!entryPath.StartsWith(rootPrefix, StringComparison.OrdinalIgnoreCase)) { return false; }
                            FileAttributes attributes = File.GetAttributes(entryPath);
                            if ((attributes & FileAttributes.ReparsePoint) != 0) { return false; }
                            if ((attributes & FileAttributes.Directory) != 0) {
                                pending.Push(entryPath);
                                continue;
                            }
                            string relativePath = entryPath.Substring(rootPrefix.Length).Replace('\\', '/');
                            if (!currentPaths.Add(relativePath)) { return false; }
                        }
                    }
                    if (currentPaths.Count != files.Count ||
                        currentDirectoryPaths.Count != runtimeDirectoryPaths.Count ||
                        !currentDirectoryPaths.SetEquals(runtimeDirectoryPaths)) { return false; }

                    List<RuntimeFileEntry> currentRows = new List<RuntimeFileEntry>();
                    foreach (RuntimeFileEntry file in files) {
                        if (!currentPaths.Contains(file.Path) ||
                            !String.Equals(
                                GetHandleFinalPath(file.Stream.SafeFileHandle),
                                file.FullPath,
                                StringComparison.OrdinalIgnoreCase) ||
                            (File.GetAttributes(file.FullPath) & FileAttributes.ReparsePoint) != 0 ||
                            file.Stream.Length != file.Length) { return false; }
                        currentRows.Add(new RuntimeFileEntry {
                            Path = file.Path,
                            FullPath = file.FullPath,
                            Length = file.Stream.Length,
                            Digest = HashOpenStream(file.Stream),
                            Stream = file.Stream
                        });
                    }
                    return String.Equals(
                        BuildRuntimeTreeDigest(currentRows),
                        expectedDigest,
                        StringComparison.Ordinal);
                }
                catch { return false; }
            }

            public void Dispose() {
                if (disposed) { return; }
                disposed = true;
                foreach (RuntimeFileEntry file in files) {
                    if (file.Stream != null) { file.Stream.Dispose(); }
                }
                foreach (RuntimeDirectoryEntry directory in directories) {
                    if (directory.Handle != null) { directory.Handle.Dispose(); }
                }
            }
        }

        // Digest profile operations-blueprint-git-runtime-tree/1.0.0:
        // SHA-256(header NUL, then for every ordinally sorted relative UTF-8
        // path: big-endian path length, path bytes, big-endian file length,
        // and the file SHA-256 bytes). Reparse entries and case-colliding paths
        // fail closed before a digest is returned.
        public static RuntimeTreeGuard OpenRuntimeTreeGuard(string root) {
            RuntimeTreeGuard guard = null;
            try {
                guard = new RuntimeTreeGuard(root);
                if (!guard.OpenAndHash()) {
                    guard.Dispose();
                    return null;
                }
                return guard;
            }
            catch {
                if (guard != null) { guard.Dispose(); }
                return null;
            }
        }

        public static string GetRuntimeTreeSha256(string root) {
            using (RuntimeTreeGuard guard = OpenRuntimeTreeGuard(root)) {
                return guard == null ? null : guard.Digest;
            }
        }
    }
}
'@ -ErrorAction Stop
        return $null -ne ('OperationsBlueprint.NativeFileSystemSecurity' -as [type])
    }
    catch { return $false }
}

function Test-TrustedWindowsPathBoundary {
    param(
        [Parameter(Mandatory = $true)][string]$Path,
        [switch]$RequireLeaf
    )

    if (-not (Test-IsWindowsRuntime) -or -not (Initialize-BlueprintWindowsFileSystemInterop)) {
        return $false
    }
    try {
        $fullPath = [IO.Path]::GetFullPath($Path)
        $entry = Get-Item -LiteralPath $fullPath -Force -ErrorAction Stop
        if (($RequireLeaf -and $entry.PSIsContainer) -or
            (([IO.FileAttributes]$entry.Attributes -band [IO.FileAttributes]::ReparsePoint) -ne 0)) {
            return $false
        }
        $volumeRoot = [IO.Path]::GetPathRoot($fullPath)
        if ([string]::IsNullOrWhiteSpace($volumeRoot) -or
            -not [OperationsBlueprint.NativeFileSystemSecurity]::IsFixedSupportedVolume($volumeRoot)) {
            return $false
        }
        $dosDeviceName = $volumeRoot.TrimEnd('\', '/')
        if ($dosDeviceName -cnotmatch '^[A-Za-z]:$') { return $false }
        $dosDeviceTargetBefore = [OperationsBlueprint.NativeFileSystemSecurity]::GetDosDeviceTarget($dosDeviceName)
        if ([string]::IsNullOrWhiteSpace($dosDeviceTargetBefore) -or
            [string]$dosDeviceTargetBefore -cnotmatch '^\\Device\\HarddiskVolume[0-9]+$') {
            return $false
        }
        $finalPath = [OperationsBlueprint.NativeFileSystemSecurity]::GetFinalPath($fullPath)
        if ([string]::IsNullOrWhiteSpace($finalPath) -or
            -not $finalPath.StartsWith('\\?\', [StringComparison]::Ordinal)) {
            return $false
        }
        $finalPath = $finalPath.Substring(4)
        if ($finalPath.StartsWith('UNC\', [StringComparison]::OrdinalIgnoreCase)) { return $false }
        $expectedCanonicalPath = $fullPath.TrimEnd('\', '/')
        $observedCanonicalPath = $finalPath.TrimEnd('\', '/')
        if ($expectedCanonicalPath.Length -eq 2 -and $expectedCanonicalPath[1] -eq ':') { $expectedCanonicalPath += '\' }
        if ($observedCanonicalPath.Length -eq 2 -and $observedCanonicalPath[1] -eq ':') { $observedCanonicalPath += '\' }
        if (-not $expectedCanonicalPath.Equals($observedCanonicalPath, [StringComparison]::OrdinalIgnoreCase)) {
            return $false
        }
        $directory = if ($entry.PSIsContainer) { [IO.DirectoryInfo]$entry } else { $entry.Directory }
        while ($null -ne $directory) {
            $directory.Refresh()
            if (-not $directory.Exists -or
                (([IO.FileAttributes]$directory.Attributes -band [IO.FileAttributes]::ReparsePoint) -ne 0) -or
                [OperationsBlueprint.NativeFileSystemSecurity]::GetDirectoryCaseSensitivity($directory.FullName) -ne 0) {
                return $false
            }
            $directory = $directory.Parent
        }
        $dosDeviceTargetAfter = [OperationsBlueprint.NativeFileSystemSecurity]::GetDosDeviceTarget($dosDeviceName)
        if ([string]$dosDeviceTargetAfter -cne [string]$dosDeviceTargetBefore) { return $false }
        return $true
    }
    catch { return $false }
}

function Test-NumberValue {
    param($Value)

    return $Value -is [sbyte] -or $Value -is [byte] -or
        $Value -is [int16] -or $Value -is [uint16] -or
        $Value -is [int32] -or $Value -is [uint32] -or
        $Value -is [int64] -or $Value -is [uint64] -or
        $Value -is [single] -or $Value -is [double] -or $Value -is [decimal]
}

function Test-CanonicalJsonRuntimeDomain {
    param(
        [AllowNull()]$Value,
        [int]$Depth = 0
    )

    # JSON Schema's integer type is mathematically unbounded, but the two
    # supported PowerShell hosts materialize out-of-Int64 tokens differently
    # (BigInteger versus floating/decimal values). Reject that ambiguous domain
    # before hashing so hostile input produces a structured HOLD, never a host-
    # specific digest or an unhandled canonicalization exception.
    if ($Depth -gt 128) { return $false }
    if ($null -eq $Value -or $Value -is [string] -or $Value -is [bool]) { return $true }
    $typeName = $Value.GetType().FullName
    if ($typeName -in @(
            'System.SByte','System.Byte','System.Int16','System.UInt16','System.Int32',
            'System.UInt32','System.Int64'
        )) { return $true }
    if ($typeName -ceq 'System.UInt64') {
        return [uint64]$Value -le [uint64][int64]::MaxValue
    }
    if ($typeName -ceq 'System.Decimal') {
        $decimalValue = [decimal]$Value
        return $decimalValue -ge [decimal][int64]::MinValue -and
            $decimalValue -le [decimal][int64]::MaxValue
    }
    if ($typeName -ceq 'System.Double') {
        $doubleValue = [double]$Value
        if ([double]::IsNaN($doubleValue) -or [double]::IsInfinity($doubleValue)) { return $false }
        $positiveExclusive = [double]::Parse('9223372036854775808', [Globalization.CultureInfo]::InvariantCulture)
        $negativeInclusive = [double]::Parse('-9223372036854775808', [Globalization.CultureInfo]::InvariantCulture)
        return $doubleValue -ge $negativeInclusive -and $doubleValue -lt $positiveExclusive
    }
    # Single, BigInteger, DateTime, Guid, and arbitrary CLR objects are outside
    # the frozen cross-host JSON runtime domain.
    if ($Value -is [System.Collections.IDictionary]) {
        $keys = [System.Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
        foreach ($key in $Value.Keys) {
            if ($key -isnot [string] -or -not $keys.Add([string]$key) -or
                -not (Test-CanonicalJsonRuntimeDomain -Value $Value[$key] -Depth ($Depth + 1))) {
                return $false
            }
        }
        return $true
    }
    if ($typeName -ceq 'System.Management.Automation.PSCustomObject') {
        $names = [System.Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
        foreach ($property in $Value.PSObject.Properties) {
            if (-not $names.Add([string]$property.Name) -or
                -not (Test-CanonicalJsonRuntimeDomain -Value $property.Value -Depth ($Depth + 1))) {
                return $false
            }
        }
        return $true
    }
    if ($Value -is [System.Collections.IEnumerable]) {
        foreach ($item in $Value) {
            if (-not (Test-CanonicalJsonRuntimeDomain -Value $item -Depth ($Depth + 1))) { return $false }
        }
        return $true
    }
    return $false
}

function Test-ExactIsoDate {
    param($Value, [ref]$ParsedDate)

    if ($Value -isnot [string] -or [string]$Value -cnotmatch '^\d{4}-\d{2}-\d{2}$') { return $false }
    [DateTime]$date = [DateTime]::MinValue
    $valid = [DateTime]::TryParseExact(
        [string]$Value,
        'yyyy-MM-dd',
        [Globalization.CultureInfo]::InvariantCulture,
        [Globalization.DateTimeStyles]::None,
        [ref]$date
    )
    if ($valid -and $null -ne $ParsedDate) { $ParsedDate.Value = $date }
    return $valid
}

function Test-ObservationWindow {
    param($Value, [DateTimeOffset]$EvaluationTime)

    if ($Value -isnot [string] -or [string]$Value -cnotmatch '^(\d{4}-\d{2}-\d{2})/(\d{4}-\d{2}-\d{2})$') { return $false }
    [DateTimeOffset]$start = [DateTimeOffset]::MinValue
    [DateTimeOffset]$end = [DateTimeOffset]::MinValue
    if (-not [OperationsBlueprint.StrictIsoDate]::TryParse($Matches[1], [ref]$start) -or
        -not [OperationsBlueprint.StrictIsoDate]::TryParse($Matches[2], [ref]$end)) { return $false }
    return $start -le $end -and $end -le $EvaluationTime
}

function Get-Sha256TokenFromText {
    param([Parameter(Mandatory = $true)][string]$Text)

    $sha256 = [Security.Cryptography.SHA256]::Create()
    try { $hashBytes = $sha256.ComputeHash([Text.Encoding]::UTF8.GetBytes($Text)) }
    finally { $sha256.Dispose() }
    return 'sha256:' + ([BitConverter]::ToString($hashBytes)).Replace('-', '').ToLowerInvariant()
}

function ConvertTo-CanonicalJsonValue {
    param([AllowNull()]$Value)

    if ($null -eq $Value) { return $null }
    if ($Value -is [string] -or $Value -is [bool]) { return $Value }
    if (Test-NumberValue $Value) {
        if (($Value -is [double] -and ([double]::IsNaN([double]$Value) -or [double]::IsInfinity([double]$Value))) -or
            ($Value -is [single] -and ([single]::IsNaN([single]$Value) -or [single]::IsInfinity([single]$Value)))) {
            throw 'Canonical JSON numbers must be finite.'
        }
        return $Value
    }
    if ($Value -is [System.Collections.IDictionary]) {
        $keys = New-Object System.Collections.ArrayList
        $caseInsensitiveKeys = [System.Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
        foreach ($key in $Value.Keys) {
            if ($key -isnot [string]) { throw 'Canonical JSON object keys must be strings.' }
            if (-not $caseInsensitiveKeys.Add([string]$key)) {
                throw 'Canonical JSON object keys must be unique under the PowerShell case-insensitive object model.'
            }
            [void]$keys.Add([string]$key)
        }
        [string[]]$keys = @($keys)
        [Array]::Sort($keys, [System.StringComparer]::Ordinal)
        for ($keyIndex = 1; $keyIndex -lt $keys.Length; $keyIndex++) {
            if ([StringComparer]::Ordinal.Equals($keys[$keyIndex - 1], $keys[$keyIndex])) {
                throw 'Canonical JSON object keys must be ordinally unique.'
            }
        }
        $ordered = [ordered]@{}
        foreach ($key in $keys) { $ordered[$key] = ConvertTo-CanonicalJsonValue $Value[$key] }
        return [pscustomobject]$ordered
    }
    if ($Value.GetType().FullName -ceq 'System.Management.Automation.PSCustomObject') {
        $names = [string[]]@($Value.PSObject.Properties | ForEach-Object { [string]$_.Name })
        $caseInsensitiveNames = [System.Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
        foreach ($name in $names) {
            if (-not $caseInsensitiveNames.Add([string]$name)) {
                throw 'Canonical JSON object keys must be unique under the PowerShell case-insensitive object model.'
            }
        }
        [Array]::Sort($names, [System.StringComparer]::Ordinal)
        for ($nameIndex = 1; $nameIndex -lt $names.Length; $nameIndex++) {
            if ([StringComparer]::Ordinal.Equals($names[$nameIndex - 1], $names[$nameIndex])) {
                throw 'Canonical JSON object keys must be ordinally unique.'
            }
        }
        $ordered = [ordered]@{}
        foreach ($name in $names) { $ordered[$name] = ConvertTo-CanonicalJsonValue $Value.PSObject.Properties[$name].Value }
        return [pscustomobject]$ordered
    }
    if ($Value -is [System.Collections.IEnumerable]) {
        $items = New-Object System.Collections.ArrayList
        foreach ($item in $Value) { [void]$items.Add((ConvertTo-CanonicalJsonValue $item)) }
        return ,@($items)
    }
    throw "Unsupported canonical JSON runtime type: $($Value.GetType().FullName)."
}

function ConvertTo-DeterministicJsonStringToken {
    param([Parameter(Mandatory = $true)][AllowEmptyString()][string]$Value)

    $builder = New-Object System.Text.StringBuilder
    [void]$builder.Append('"')
    $characters = $Value.ToCharArray()
    for ($characterIndex = 0; $characterIndex -lt $characters.Length; $characterIndex++) {
        $character = $characters[$characterIndex]
        $codePoint = [int][char]$character
        if ([char]::IsHighSurrogate($character)) {
            if ($characterIndex + 1 -ge $characters.Length -or -not [char]::IsLowSurrogate($characters[$characterIndex + 1])) {
                throw 'Canonical JSON strings cannot contain an unpaired UTF-16 high surrogate.'
            }
            [void]$builder.Append($character)
            $characterIndex++
            [void]$builder.Append($characters[$characterIndex])
            continue
        }
        if ([char]::IsLowSurrogate($character)) {
            throw 'Canonical JSON strings cannot contain an unpaired UTF-16 low surrogate.'
        }
        if ($codePoint -eq 8) { [void]$builder.Append('\b'); continue }
        if ($codePoint -eq 9) { [void]$builder.Append('\t'); continue }
        if ($codePoint -eq 10) { [void]$builder.Append('\n'); continue }
        if ($codePoint -eq 12) { [void]$builder.Append('\f'); continue }
        if ($codePoint -eq 13) { [void]$builder.Append('\r'); continue }
        if ($codePoint -eq 34) { [void]$builder.Append('\"'); continue }
        if ($codePoint -eq 92) { [void]$builder.Append('\\'); continue }
        if ($codePoint -lt 32 -or $codePoint -eq 0x2028 -or $codePoint -eq 0x2029) {
            [void]$builder.Append('\u')
            [void]$builder.Append($codePoint.ToString('x4', [Globalization.CultureInfo]::InvariantCulture))
        }
        else {
            [void]$builder.Append($character)
        }
    }
    [void]$builder.Append('"')
    return $builder.ToString()
}

function Normalize-DeterministicJsonNumberText {
    param([Parameter(Mandatory = $true)][string]$NumberText)

    $numberText = $NumberText.Replace('e', 'E')
    if ($numberText -match '^(.*)E([+-]?)([0-9]+)$') {
        $mantissa = $Matches[1]
        $sign = $Matches[2]
        $exponent = $Matches[3].TrimStart('0')
        if ([string]::IsNullOrEmpty($exponent)) { $exponent = '0' }
        $numberText = $mantissa + 'E' + $sign + $exponent
    }
    if ($numberText -notmatch '[.E]') { $numberText += '.0' }
    return $numberText
}

function ConvertTo-DeterministicJsonDecimalToken {
    param([Parameter(Mandatory = $true)][decimal]$Value)

    if ($Value -eq 0) { return '0.0' }
    $candidate = $Value.ToString('G15', [Globalization.CultureInfo]::InvariantCulture)
    [decimal]$roundTrip = 0
    if (-not [decimal]::TryParse(
            $candidate,
            [Globalization.NumberStyles]::Float,
            [Globalization.CultureInfo]::InvariantCulture,
            [ref]$roundTrip
        ) -or $roundTrip -ne $Value) {
        throw 'Canonical JSON fractional numbers must fit the cross-host exact 15-significant-digit domain.'
    }
    return Normalize-DeterministicJsonNumberText -NumberText $candidate
}

function ConvertTo-DeterministicJsonDoubleToken {
    param([Parameter(Mandatory = $true)][double]$Value)

    if ([double]::IsNaN($Value) -or [double]::IsInfinity($Value)) {
        throw 'Canonical JSON numbers must be finite.'
    }
    if ($Value -eq 0) { return '0.0' }
    $candidate = $Value.ToString('G15', [Globalization.CultureInfo]::InvariantCulture)
    [double]$roundTrip = 0
    if (-not [double]::TryParse(
            $candidate,
            [Globalization.NumberStyles]::Float,
            [Globalization.CultureInfo]::InvariantCulture,
            [ref]$roundTrip
        ) -or [BitConverter]::DoubleToInt64Bits($roundTrip) -ne [BitConverter]::DoubleToInt64Bits($Value)) {
        throw 'Canonical JSON fractional numbers must fit the cross-host exact 15-significant-digit domain.'
    }
    [decimal]$commonValue = 0
    if (-not [decimal]::TryParse(
            $candidate,
            [Globalization.NumberStyles]::Float,
            [Globalization.CultureInfo]::InvariantCulture,
            [ref]$commonValue
        )) {
        throw 'Canonical JSON fractional number is outside the cross-host Decimal range.'
    }
    if ($Value -ne [double]0 -and $commonValue -eq [decimal]0) {
        # Decimal is the common fractional-number domain shared by Windows
        # PowerShell and PowerShell Core.  A nonzero Double such as Epsilon can
        # round-trip as Double yet underflow to Decimal zero.  Reject it instead
        # of colliding with the canonical representation of positive/negative
        # zero.
        throw 'Canonical JSON fractional number underflows the cross-host Decimal domain.'
    }
    return ConvertTo-DeterministicJsonDecimalToken -Value $commonValue
}

function ConvertTo-DeterministicJsonText {
    param([AllowNull()]$Value)

    if ($null -eq $Value) { return 'null' }
    if ($Value -is [string]) {
        return ConvertTo-DeterministicJsonStringToken -Value ([string]$Value)
    }
    if ($Value -is [bool]) {
        if ($Value) { return 'true' }
        return 'false'
    }

    $typeName = $Value.GetType().FullName
    switch ($typeName) {
        { $_ -in @(
            'System.SByte','System.Byte','System.Int16','System.UInt16','System.Int32',
            'System.UInt32','System.Int64','System.UInt64'
        ) } {
            return ([IFormattable]$Value).ToString($null, [Globalization.CultureInfo]::InvariantCulture)
        }
        'System.Decimal' {
            return ConvertTo-DeterministicJsonDecimalToken -Value ([decimal]$Value)
        }
        'System.Double' {
            return ConvertTo-DeterministicJsonDoubleToken -Value ([double]$Value)
        }
        'System.Single' {
            throw 'Unsupported canonical JSON runtime type: System.Single.'
        }
    }

    if ($Value -is [System.Collections.IDictionary]) {
        $members = New-Object System.Collections.ArrayList
        foreach ($key in $Value.Keys) {
            $member = (ConvertTo-DeterministicJsonStringToken -Value ([string]$key)) + ':' +
                (ConvertTo-DeterministicJsonText -Value $Value[$key])
            [void]$members.Add($member)
        }
        return '{' + (@($members) -join ',') + '}'
    }
    if ($Value.GetType().FullName -ceq 'System.Management.Automation.PSCustomObject') {
        $members = New-Object System.Collections.ArrayList
        foreach ($property in $Value.PSObject.Properties) {
            $member = (ConvertTo-DeterministicJsonStringToken -Value ([string]$property.Name)) + ':' +
                (ConvertTo-DeterministicJsonText -Value $property.Value)
            [void]$members.Add($member)
        }
        return '{' + (@($members) -join ',') + '}'
    }
    if ($Value -is [System.Collections.IEnumerable]) {
        $items = New-Object System.Collections.ArrayList
        foreach ($item in $Value) { [void]$items.Add((ConvertTo-DeterministicJsonText -Value $item)) }
        return '[' + (@($items) -join ',') + ']'
    }

    throw "Unsupported canonical JSON runtime type: $typeName."
}

function Get-CanonicalPayloadDigest {
    param([Parameter(Mandatory = $true)]$Payload)

    if (-not (Test-CanonicalJsonRuntimeDomain -Value $Payload)) { return 'INVALID_CANONICAL_JSON_RUNTIME_DOMAIN' }
    try {
        $canonical = ConvertTo-CanonicalJsonValue $Payload
        return Get-Sha256TokenFromText -Text (ConvertTo-DeterministicJsonText -Value $canonical)
    }
    catch {
        # Never forward exception text and never let hostile runtime values tear
        # down a semantic validation. The non-SHA sentinel cannot satisfy any
        # schema-valid digest binding, so callers fail closed with their stable
        # mismatch reason.
        return 'INVALID_CANONICAL_JSON_RUNTIME_DOMAIN'
    }
}

function Get-CanonicalEnvelopeCoreDigest {
    param([Parameter(Mandatory = $true)]$Record)

    $core = [ordered]@{
        recordId = [string]$Record.recordId
        recordType = [string]$Record.recordType
        contentDigest = [string]$Record.contentDigest
        validated = $Record.validated
        freshness = [string]$Record.freshness
        validFrom = [string]$Record.validFrom
        validUntil = [string]$Record.validUntil
        pointers = @($Record.pointers)
        immutableArtifactRef = [string]$Record.immutableArtifactRef
    }
    return Get-CanonicalPayloadDigest -Payload ([pscustomobject]$core)
}

function Get-DuplicateJsonPropertyNames {
    param([Parameter(Mandatory = $true)][string]$JsonText)

    $duplicates = New-Object System.Collections.ArrayList
    $contexts = New-Object System.Collections.ArrayList
    $index = 0
    while ($index -lt $JsonText.Length) {
        $character = $JsonText[$index]
        if ([char]::IsWhiteSpace($character)) { $index++; continue }

        if ($character -eq '"') {
            $start = $index
            $index++
            $escaped = $false
            while ($index -lt $JsonText.Length) {
                $currentCharacter = $JsonText[$index]
                if ($escaped) { $escaped = $false; $index++; continue }
                if ($currentCharacter -eq '\') { $escaped = $true; $index++; continue }
                if ($currentCharacter -eq '"') { break }
                $index++
            }
            if ($index -ge $JsonText.Length) { throw 'Strict JSON duplicate-property inspection found an unterminated string.' }
            $jsonString = $JsonText.Substring($start, ($index - $start + 1))
            $decoded = [string](ConvertFrom-Json -InputObject $jsonString)
            if ($contexts.Count -gt 0) {
                $context = $contexts[$contexts.Count - 1]
                if ([string]$context.Kind -ceq 'Object' -and [string]$context.State -ceq 'KeyOrEnd') {
                    if (-not $context.Names.Add($decoded)) {
                        [void]$duplicates.Add([pscustomobject]@{ Name = $decoded; Path = "object-depth-$($contexts.Count)" })
                    }
                    $context.State = 'Colon'
                }
                elseif (([string]$context.Kind -ceq 'Object' -and [string]$context.State -ceq 'Value') -or
                        ([string]$context.Kind -ceq 'Array' -and [string]$context.State -ceq 'ValueOrEnd')) {
                    $context.State = 'CommaOrEnd'
                }
            }
            $index++
            continue
        }

        if ($character -eq '{' -or $character -eq '[') {
            if ($contexts.Count -gt 0) {
                $parent = $contexts[$contexts.Count - 1]
                if (([string]$parent.Kind -ceq 'Object' -and [string]$parent.State -ceq 'Value') -or
                    ([string]$parent.Kind -ceq 'Array' -and [string]$parent.State -ceq 'ValueOrEnd')) {
                    $parent.State = 'CommaOrEnd'
                }
            }
            if ($character -eq '{') {
                [void]$contexts.Add([pscustomobject]@{
                    Kind = 'Object'
                    State = 'KeyOrEnd'
                    Names = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
                })
            }
            else {
                [void]$contexts.Add([pscustomobject]@{ Kind = 'Array'; State = 'ValueOrEnd'; Names = $null })
            }
            $index++
            continue
        }

        if ($character -eq '}' -or $character -eq ']') {
            if ($contexts.Count -gt 0) { $contexts.RemoveAt($contexts.Count - 1) }
            $index++
            continue
        }

        if ($character -eq ':') {
            if ($contexts.Count -gt 0) {
                $context = $contexts[$contexts.Count - 1]
                if ([string]$context.Kind -ceq 'Object' -and [string]$context.State -ceq 'Colon') { $context.State = 'Value' }
            }
            $index++
            continue
        }

        if ($character -eq ',') {
            if ($contexts.Count -gt 0) {
                $context = $contexts[$contexts.Count - 1]
                if ([string]$context.Kind -ceq 'Object') { $context.State = 'KeyOrEnd' }
                else { $context.State = 'ValueOrEnd' }
            }
            $index++
            continue
        }

        $primitiveStart = $index
        while ($index -lt $JsonText.Length -and
            -not [char]::IsWhiteSpace($JsonText[$index]) -and
            $JsonText[$index] -notin @(',', '}', ']')) { $index++ }
        if ($index -eq $primitiveStart) { $index++; continue }
        if ($contexts.Count -gt 0) {
            $context = $contexts[$contexts.Count - 1]
            if (([string]$context.Kind -ceq 'Object' -and [string]$context.State -ceq 'Value') -or
                ([string]$context.Kind -ceq 'Array' -and [string]$context.State -ceq 'ValueOrEnd')) {
                $context.State = 'CommaOrEnd'
            }
        }
    }
    return @($duplicates)
}

function Test-AllowedProperties {
    param(
        [AllowNull()]$Object,
        [Parameter(Mandatory = $true)][string[]]$Names,
        [Parameter(Mandatory = $true)][string]$Context,
        [Parameter(Mandatory = $true)][AllowEmptyCollection()][System.Collections.ArrayList]$Errors
    )

    if ($null -eq $Object) { return }
    foreach ($property in @($Object.PSObject.Properties)) {
        if ($Names -cnotcontains [string]$property.Name) {
            Add-BlueprintError -Errors $Errors -Code 'UNEXPECTED_CONTRACT_FIELD' -Message "$Context contains unexpected field $($property.Name)."
        }
    }
}

function Get-LeadershipTemplatePolicyDigest {
    param([Parameter(Mandatory = $true)]$Chain)

    $payload = [ordered]@{
        chainVersion = [string]$Chain.chainVersion
        documentType = [string]$Chain.documentType
        portableContractRefs = @($Chain.portableContractRefs)
        validatorReleaseRef = [string]$Chain.lineage.validatorReleaseRef
        requiredLeadershipLinks = @($Chain.requiredLeadershipLinks)
        currentFleetRequiredDimensions = @($Chain.currentFleetRequiredDimensions)
        readinessRules = @($Chain.readinessRules)
    }
    return Get-Sha256TokenFromText -Text (ConvertTo-DeterministicJsonText -Value (ConvertTo-CanonicalJsonValue $payload))
}

function Get-ToolBindingPolicyDigest {
    param(
        [Parameter(Mandatory = $true)][object[]]$Bindings,
        [Parameter(Mandatory = $true)][string[]]$ToolOrder
    )

    $policyRecords = @(
        foreach ($toolId in $ToolOrder) {
            $binding = @($Bindings | Where-Object { [string]$_.toolId -ceq $toolId })
            if ($binding.Count -ne 1) { continue }
            $item = $binding[0]
            [ordered]@{
                toolId = [string]$item.toolId
                product = [string]$item.product
                provider = [string]$item.provider
                status = [string]$item.status
                category = [string]$item.category
                ownerRole = [string]$item.ownerRole
                roles = @($item.roles)
                leadershipLanes = @($item.leadershipLanes)
                authorityClasses = @($item.authorityClasses)
                inputs = @($item.inputs)
                outputs = @($item.outputs)
                writeScope = [string]$item.writeScope
                readback = [ordered]@{
                    required = $item.readback.required
                    viaToolRef = $item.readback.viaToolRef
                    viaToolRefs = @($item.readback.viaToolRefs)
                    scopeRule = $item.readback.scopeRule
                    mismatchDisposition = $item.readback.mismatchDisposition
                }
                identityRole = $item.identityRole
                identityBoundary = [string]$item.identityBoundary
                dataClasses = @($item.dataClasses)
                prohibitedUses = @($item.prohibitedUses)
                replaceable = $item.replaceable
                versionPolicy = [string]$item.versionPolicy
                failureMode = [string]$item.failureMode
                replacementRule = [string]$item.replacementRule
            }
        }
    )
    return Get-Sha256TokenFromText -Text (ConvertTo-DeterministicJsonText -Value $policyRecords)
}

function Get-ControlPolicyDigest {
    param(
        [Parameter(Mandatory = $true)]$Matrix,
        [Parameter(Mandatory = $true)][string[]]$ControlOrder
    )

    $roleRecords = @(
        foreach ($role in @($Matrix.roleCatalog.roles)) {
            [ordered]@{
                roleId = [string]$role.roleId
                dutyClass = [string]$role.dutyClass
                description = [string]$role.description
            }
        }
    )
    $controlRecords = @(
        foreach ($controlId in $ControlOrder) {
            $matching = @($Matrix.controls | Where-Object { [string]$_.controlId -ceq $controlId })
            if ($matching.Count -ne 1) { continue }
            $control = $matching[0]
            [ordered]@{
                controlId = [string]$control.controlId
                objective = [string]$control.objective
                ownerRole = [string]$control.ownerRole
                approverRole = [string]$control.approverRole
                toolRefs = @($control.toolRefs)
                evidenceOutputs = @($control.evidenceOutputs)
                failureState = [string]$control.failureState
                failClosed = [ordered]@{
                    missing = [string]$control.failClosed.missing
                    stale = [string]$control.failClosed.stale
                    unknown = [string]$control.failClosed.unknown
                    mismatch = [string]$control.failClosed.mismatch
                }
                exceptionRule = [string]$control.exceptionRule
                monitoring = [string]$control.monitoring
                readbackRef = [string]$control.readbackRef
                rollbackRef = [string]$control.rollbackRef
                writesIntune = $control.writesIntune
            }
        }
    )
    $payload = [ordered]@{
        matrixVersion = [string]$Matrix.matrixVersion
        roleCatalog = [ordered]@{
            policyVersion = [string]$Matrix.roleCatalog.policyVersion
            activationState = [string]$Matrix.roleCatalog.activationState
            privatePrincipalBindingRef = $Matrix.roleCatalog.privatePrincipalBindingRef
            roles = $roleRecords
            rules = @($Matrix.roleCatalog.rules)
        }
        controls = $controlRecords
    }
    return Get-Sha256TokenFromText -Text (ConvertTo-DeterministicJsonText -Value $payload)
}

function Get-SemanticValidationResultDigest {
    param([Parameter(Mandatory = $true)]$SemanticRecord)

    [string[]]$sourceRefs = @()
    if (@($SemanticRecord.sourceRecordRefs).Count -gt 0) {
        $sourceRefs = [string[]]@($SemanticRecord.sourceRecordRefs | ForEach-Object { [string]$_ })
        [Array]::Sort($sourceRefs, [StringComparer]::Ordinal)
    }
    return Get-CanonicalPayloadDigest -Payload ([pscustomobject][ordered]@{
        inputDigest = [string]$SemanticRecord.inputDigest
        validatorReleaseRef = [string]$SemanticRecord.validatorReleaseRef
        validatorReleaseDigest = [string]$SemanticRecord.validatorReleaseDigest
        sourceRecordSetDigest = [string]$SemanticRecord.sourceRecordSetDigest
        sourceRecordRefs = @($sourceRefs)
        validationResult = [string]$SemanticRecord.validationResult
        evaluationTime = [string]$SemanticRecord.evaluationTime
    })
}

function Get-LeadershipSemanticInputDigest {
    param(
        [Parameter(Mandatory = $true)]$Chain,
        [Parameter(Mandatory = $true)]$RecordMap,
        [switch]$ReturnSourceRecordRefs
    )

    $references = @(
        $Chain.personaNeed.manifestRef, $Chain.personaNeed.personaVerdictPointer,
        $Chain.personaNeed.capacityWaterfallPointer, $Chain.personaNeed.evidenceReleaseRef,
        $Chain.currentFleetIssue.incumbentControlRef, $Chain.currentFleetIssue.cohortRef,
        $Chain.currentFleetIssue.fleetPortfolioRef, $Chain.currentFleetIssue.fleetPortfolioCohortPointer,
        $Chain.currentFleetIssue.evidenceReleaseRef,
        $Chain.candidateComparison.candidateRef,
        $Chain.candidateComparison.incumbentControlRef, $Chain.candidateComparison.siblingControlRef,
        $Chain.candidateComparison.testPlanRef, $Chain.candidateComparison.evidenceReleaseRef,
        $Chain.businessEffect.businessEffectRef, $Chain.businessEffect.businessEffectPointer,
        $Chain.businessEffect.evidenceReleaseRef, $Chain.businessEffect.candidateQuoteRef,
        $Chain.businessEffect.controlQuoteRef, $Chain.businessEffect.calculationPointer,
        $Chain.recommendation.verdictRef, $Chain.recommendation.fleetVerdictPointer,
        $Chain.recommendation.personaVerdictPointer, $Chain.recommendation.procurementEnvelopePointer
    )
    $references += @($Chain.personaNeed.evidenceRefs)
    $references += @($Chain.currentFleetIssue.evidenceRefs)
    $references += @($Chain.candidateComparison.evidenceRefs)
    $references += @($Chain.businessEffect.evidenceRefs)
    foreach ($linkName in @('personaNeed', 'currentFleetIssue', 'candidateComparison', 'businessEffect', 'recommendation')) {
        $references += @($Chain.$linkName.freshness.policyRef, $Chain.$linkName.freshness.dependencySnapshotRef)
    }

    $sourceIds = [System.Collections.Generic.Dictionary[string,bool]]::new([System.StringComparer]::Ordinal)
    foreach ($reference in $references) {
        if ($reference -isnot [string] -or [string]::IsNullOrWhiteSpace([string]$reference)) { continue }
        $recordId = ([string]$reference).Split('#', 2)[0]
        if ($RecordMap.ContainsKey($recordId) -and -not $sourceIds.ContainsKey($recordId)) {
            [void]$sourceIds.Add($recordId, $true)
        }
    }

    # Bind the semantic validation to canonical records reached through the
    # decision inputs, not only the first-hop records named by the rendered
    # chain. Otherwise a caller could replace and re-attest a distribution or
    # T2 corroboration record without invalidating the semantic-input digest.
    $pendingIds = [System.Collections.Generic.Queue[string]]::new()
    foreach ($recordId in @($sourceIds.Keys)) { $pendingIds.Enqueue([string]$recordId) }
    while ($pendingIds.Count -gt 0) {
        $recordId = $pendingIds.Dequeue()
        $record = $RecordMap[$recordId]
        if ($null -eq $record -or $null -eq $record.payload) { continue }

        $transitiveReferences = @()
        if ($null -ne $record.PSObject.Properties['portableProjectionRecord']) {
            $transitiveReferences += @($record.portableProjectionRecord.validationRecordRef)
        }
        switch ([string]$record.recordType) {
            'candidate-manifest' {
                $transitiveReferences += @($record.testPlanRef, $record.thresholdPolicyRef)
            }
            'test-plan' {
                $transitiveReferences += @($record.manifestRef, $record.thresholdPolicyRef, $record.dependencyReviewRef)
            }
            'evidence-release' {
                $transitiveReferences += @($record.payload.memberRecordIds)
            }
            'evidence-record' {
                $transitiveReferences += @($record.payload.distributionRef)
                if ($record.payload.corroborationRef -is [pscustomobject]) {
                    $transitiveReferences += @($record.payload.corroborationRef.recordRef)
                }
                if ($record.payload.result -is [pscustomobject]) {
                    foreach ($capacityInputBinding in @($record.payload.result.capacityInputBindings)) {
                        if ($capacityInputBinding -is [pscustomobject]) {
                            $transitiveReferences += @($capacityInputBinding.recordRef)
                        }
                    }
                }
            }
            'verdict-record' {
                $transitiveReferences += @($record.manifestRef, $record.payload.evidenceReleases)
                $transitiveReferences += @(
                    $record.pilotPopulationPlanRef,
                    $record.qualificationAuthorityApprovalRef,
                    $record.arbitrationAuthorityApprovalRef,
                    $record.deadlineAuthorityApprovalRef,
                    $record.pilotNotRequiredApprovalRef,
                    $record.pilotAuthorizationRecordRef
                )
                if ($record.arbitration -is [pscustomobject]) {
                    $transitiveReferences += @($record.arbitration.evidenceRefs)
                }
                if ($record.deadlineDecision -is [pscustomobject]) {
                    $transitiveReferences += @($record.deadlineDecision.authorityApprovalRef)
                }
                if ($record.pilotAuthorization -is [pscustomobject]) {
                    $transitiveReferences += @(
                        $record.pilotAuthorization.phase2ApprovalRef,
                        $record.pilotAuthorization.provisionalVerdictRef,
                        $record.pilotAuthorization.stopConditionsRef,
                        $record.pilotAuthorization.rollbackPlanRef
                    )
                    if ($record.pilotAuthorization.operationalReadiness -is [pscustomobject]) {
                        $transitiveReferences += @(
                            $record.pilotAuthorization.operationalReadiness.severityModelRef,
                            $record.pilotAuthorization.operationalReadiness.maxIncidentRateThresholdRef,
                            $record.pilotAuthorization.operationalReadiness.deviceSwapProcessRef,
                            $record.pilotAuthorization.operationalReadiness.sparePoolPlanRef,
                            $record.pilotAuthorization.operationalReadiness.serviceDeskBriefingRef,
                            $record.pilotAuthorization.operationalReadiness.minEvidenceCoverageThresholdRef
                        )
                    }
                }
                if ($record.pilotCompletion -is [pscustomobject]) {
                    $transitiveReferences += @(
                        $record.pilotCompletion.pilotEvidenceReleaseRef,
                        $record.pilotCompletion.coverageEvidenceRef,
                        $record.pilotCompletion.authorityApprovalRef
                    )
                }
                foreach ($personaVerdict in @($record.personaVerdicts)) {
                    if ($personaVerdict.capacityWaterfall -is [pscustomobject]) {
                        $transitiveReferences += @(
                            $personaVerdict.capacityWaterfall.thresholdPolicyRef,
                            $personaVerdict.capacityWaterfall.calculationEvidenceRef
                        )
                    }
                }
                foreach ($assessment in @($record.procurementEnvelope.substitutionAssessments)) {
                    $transitiveReferences += @($assessment.deltaQualificationRef)
                }
            }
            'qualification-authority-approval-record' {
                $transitiveReferences += @(
                    $record.manifestRef, $record.verdictRef, $record.roleBindingRef,
                    $record.roleBindingReadbackRef, $record.roleBindingReadbackPolicyRef,
                    $record.freshnessBinding.dependencySnapshotRef
                )
            }
            'distribution-record' {
                $transitiveReferences += @($record.payload.sourceEvidenceRef)
                $transitiveReferences += @($record.payload.sourceEvidenceReleaseRef)
                $transitiveReferences += @($record.payload.phase0TestPlanRef)
                $transitiveReferences += @($record.payload.compatibilityCacheAdmissionRef)
            }
            'compatibility-cache-admission-record' {
                $transitiveReferences += @(
                    $record.cachedEvidenceRef, $record.historicalEvidenceReleaseRef,
                    $record.currentManifestRef, $record.currentTestPlanRef,
                    $record.currentThresholdPolicyRef, $record.dependencySnapshotRef,
                    $record.currentConsumerRef, $record.currentEvidenceReleaseRef,
                    $record.freshnessPolicyRef, $record.roleBindingRef,
                    $record.roleBindingReadbackRef, $record.roleBindingReadbackPolicyRef
                )
                foreach ($binding in @($record.bridgeEvidenceBindings)) {
                    $transitiveReferences += @($binding.recordRef)
                }
                foreach ($binding in @($record.bridgeDistributionBindings)) {
                    $transitiveReferences += @($binding.recordRef)
                }
            }
            'business-impact-record' {
                $transitiveReferences += @(
                    $record.payload.candidateQuoteRef, $record.payload.controlQuoteRef,
                    $record.payload.distributionRef
                )
                foreach ($sourceBinding in @($record.payload.sourceRecordBindings)) {
                    $transitiveReferences += @($sourceBinding.recordRef)
                }
            }
            'fleet-portfolio-record' {
                foreach ($releaseBinding in @($record.payload.sourceEvidenceReleaseBindings)) {
                    $transitiveReferences += @($releaseBinding.recordRef)
                }
                foreach ($configurationCohort in @($record.payload.configurationCohorts)) {
                    $transitiveReferences += @($configurationCohort.configurationRef, $configurationCohort.cohortRef)
                    $transitiveReferences += @($configurationCohort.lifecycleEvidenceRefs)
                    $transitiveReferences += @($configurationCohort.platformEvidenceRefs)
                    $transitiveReferences += @($configurationCohort.issueEvidenceRefs)
                }
                if ($record.payload.dimensionCoverage -is [pscustomobject]) {
                    foreach ($dimensionProperty in @($record.payload.dimensionCoverage.PSObject.Properties | Where-Object {
                        $_.Value -is [pscustomobject] -and $_.Value.PSObject.Properties['claimBindings']
                    })) {
                        foreach ($claim in @($dimensionProperty.Value.claimBindings)) {
                            $transitiveReferences += @($claim.queryPackRef, $claim.distributionRef, $claim.structuredSummaryRef)
                            $transitiveReferences += @($claim.corroborationRefs)
                            $transitiveReferences += @($claim.requalificationTriggerRefs)
                            foreach ($releaseBinding in @($claim.evidenceReleaseBindings)) { $transitiveReferences += @($releaseBinding.recordRef) }
                            foreach ($sourceBinding in @($claim.sourceRecordBindings)) { $transitiveReferences += @($sourceBinding.recordRef) }
                            foreach ($sourcePointer in @($claim.sourcePointers)) { $transitiveReferences += @($sourcePointer.recordRef) }
                        }
                    }
                }
            }
        }
        foreach ($reference in $transitiveReferences) {
            if ($reference -isnot [string] -or [string]::IsNullOrWhiteSpace([string]$reference)) { continue }
            $transitiveId = ([string]$reference).Split('#', 2)[0]
            if ($RecordMap.ContainsKey($transitiveId) -and -not $sourceIds.ContainsKey($transitiveId)) {
                [void]$sourceIds.Add($transitiveId, $true)
                $pendingIds.Enqueue($transitiveId)
            }
        }
    }
    [string[]]$sortedIds = @()
    if ($sourceIds.Count -gt 0) {
        $sortedIds = [string[]]@($sourceIds.Keys)
        [Array]::Sort($sortedIds, [System.StringComparer]::Ordinal)
    }
    if ($ReturnSourceRecordRefs) { return [string[]]@($sortedIds) }
    $sourceRecords = @(
        foreach ($recordId in $sortedIds) {
            $record = $RecordMap[$recordId]
            [ordered]@{
                recordId = [string]$record.recordId
                recordType = [string]$record.recordType
                contentDigest = [string]$record.contentDigest
            }
        }
    )
    $payload = [ordered]@{
        chainVersion = [string]$Chain.chainVersion
        documentType = [string]$Chain.documentType
        status = [string]$Chain.status
        portableContractRefs = @($Chain.portableContractRefs)
        personaNeed = $Chain.personaNeed
        currentFleetIssue = $Chain.currentFleetIssue
        candidateComparison = $Chain.candidateComparison
        businessEffect = $Chain.businessEffect
        recommendation = $Chain.recommendation
        issuanceContext = [ordered]@{
            generatedAt = [string]$Chain.lineage.generatedAt
            validatorReleaseRef = [string]$Chain.lineage.validatorReleaseRef
            derivedDocumentsAreEvidence = [bool]$Chain.lineage.derivedDocumentsAreEvidence
        }
        sourceRecords = $sourceRecords
    }
    return Get-Sha256TokenFromText -Text (ConvertTo-DeterministicJsonText -Value $payload)
}

function Get-EvidenceReleaseSubjectDigest {
    param([Parameter(Mandatory = $true)]$ReleaseRecord)

    $releasePayload = if ($ReleaseRecord.payload -is [pscustomobject]) { $ReleaseRecord.payload } else { $ReleaseRecord }
    $subject = [ordered]@{}
    foreach ($property in @($releasePayload.PSObject.Properties)) {
        if (@('memberRecordIds','memberRecordBindings','releaseSubjectDigest') -ccontains [string]$property.Name) { continue }
        $subject[[string]$property.Name] = $property.Value
    }
    return Get-CanonicalPayloadDigest -Payload ([pscustomobject]$subject)
}

function Test-EvidenceReleaseBinding {
    param(
        $ReleaseRecord,
        [object[]]$EvidenceRecords,
        [Parameter(Mandatory = $true)]$RecordMap,
        [Parameter(Mandatory = $true)][DateTimeOffset]$EvaluationTime,
        [AllowNull()]$ConsumerRecord,
        [AllowNull()]$Manifest,
        [AllowNull()]$Phase0TestPlan,
        [AllowNull()]$ThresholdPolicy,
        [ValidateSet('TEST','PRODUCTION')][string]$ValidationProfile = 'PRODUCTION',
        [switch]$HistoricalCacheRelease,
        [switch]$CacheAdmissionSemanticsAlreadyValidated,
        [Parameter(Mandatory = $true)][string]$Context,
        [Parameter(Mandatory = $true)][AllowEmptyCollection()][System.Collections.ArrayList]$Errors
    )

    if ($null -eq $ReleaseRecord) { return }
    Test-RequiredProperties -Object $ReleaseRecord -Names @(
        'memberRecordIds', 'memberRecordBindings', 'releaseSubjectDigest', 'semanticGateStatus', 'samplingFloorStatus',
        'distributionStatus', 'coverageStatus', 'releasedAt', 'freshnessBinding'
    ) -Context "$Context evidence release" -Errors $Errors
    $memberIds = @($ReleaseRecord.memberRecordIds)
    $memberBindings = @($ReleaseRecord.memberRecordBindings)
    $memberRefs = [System.Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal)
    $membershipValid = (Test-Sha256Token $ReleaseRecord.releaseSubjectDigest) -and
        [string]$ReleaseRecord.releaseSubjectDigest -ceq [string](Get-EvidenceReleaseSubjectDigest -ReleaseRecord $ReleaseRecord) -and
        $ReleaseRecord.memberRecordIds -is [System.Collections.IList] -and
        $ReleaseRecord.memberRecordBindings -is [System.Collections.IList] -and
        $memberIds.Count -gt 0 -and $memberIds.Count -eq $memberBindings.Count
    for ($memberIndex = 0; $memberIndex -lt $memberBindings.Count; $memberIndex++) {
        $binding = $memberBindings[$memberIndex]
        if ($binding -isnot [pscustomobject]) { $membershipValid = $false; continue }
        Test-RequiredProperties -Object $binding -Names @('recordRef','contentDigest') -Context "$Context evidence release member binding" -Errors $Errors
        Test-AllowedProperties -Object $binding -Names @('recordRef','contentDigest') -Context "$Context evidence release member binding" -Errors $Errors
        $memberRef = [string]$binding.recordRef
        if (-not (Test-NonBlankString $memberRef) -or $memberRef.Contains('#') -or
            $memberRef -ceq [string]$ReleaseRecord.recordId -or -not $memberRefs.Add($memberRef) -or
            $memberIndex -ge $memberIds.Count -or [string]$memberIds[$memberIndex] -cne $memberRef -or
            -not (Test-Sha256Token $binding.contentDigest) -or -not $RecordMap.ContainsKey($memberRef) -or
            ($RecordMap.ContainsKey($memberRef) -and
             [string]$RecordMap[$memberRef].contentDigest -cne [string]$binding.contentDigest)) {
            $membershipValid = $false
        }
    }
    if (-not $membershipValid) {
        Add-BlueprintError -Errors $Errors -Code 'EVIDENCE_RELEASE_MEMBER_BINDING_INVALID' -Message "$Context evidence release does not bind one ordered, unique, whole-record content digest for every member ID."
    }

    [DateTimeOffset]$releasedAt = [DateTimeOffset]::MinValue
    [DateTimeOffset]$releaseFreshnessObservedAt = [DateTimeOffset]::MinValue
    [DateTimeOffset]$releaseFreshnessAdmittedAt = [DateTimeOffset]::MinValue
    $chronologyValid = [OperationsBlueprint.StrictRfc3339]::TryParse([string]$ReleaseRecord.releasedAt, [ref]$releasedAt) -and
        [OperationsBlueprint.StrictRfc3339]::TryParse([string]$ReleaseRecord.freshnessBinding.observedAt, [ref]$releaseFreshnessObservedAt) -and
        [OperationsBlueprint.StrictRfc3339]::TryParse([string]$ReleaseRecord.freshnessBinding.admittedAt, [ref]$releaseFreshnessAdmittedAt) -and
        $releaseFreshnessObservedAt -le $releaseFreshnessAdmittedAt -and
        $releaseFreshnessAdmittedAt -lt $releasedAt -and $releasedAt -le $EvaluationTime
    $releaseFreshnessEvaluationTime = if ($HistoricalCacheRelease) { $releasedAt } else { $EvaluationTime }
    [void](Test-PortableContractFreshnessBinding -Freshness $ReleaseRecord.freshnessBinding `
        -EvaluationTime $releaseFreshnessEvaluationTime -Context "$Context evidence release freshness" -Errors $Errors)

    $cacheAdmissionMemberRefs = [System.Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal)
    $cacheConsumerMembers = New-Object System.Collections.ArrayList
    foreach ($memberRef in @($memberRefs)) {
        if (-not $RecordMap.ContainsKey([string]$memberRef)) { $chronologyValid = $false; continue }
        $member = $RecordMap[[string]$memberRef]
        if ([string]$member.recordType -ceq 'compatibility-cache-admission-record') {
            [void]$cacheAdmissionMemberRefs.Add([string]$member.recordId)
            [DateTimeOffset]$cacheAdmittedAt = [DateTimeOffset]::MinValue
            [DateTimeOffset]$cacheIssuedAt = [DateTimeOffset]::MinValue
            if (-not [OperationsBlueprint.StrictRfc3339]::TryParse([string]$member.admittedAt, [ref]$cacheAdmittedAt) -or
                -not [OperationsBlueprint.StrictRfc3339]::TryParse([string]$member.issuedAt, [ref]$cacheIssuedAt) -or
                $cacheAdmittedAt -gt $cacheIssuedAt -or $cacheIssuedAt -ge $releasedAt) {
                $chronologyValid = $false
            }
            continue
        }
        if ([string]$member.recordType -ceq 'distribution-record' -and
            (Test-NonBlankString $member.compatibilityCacheAdmissionRef)) {
            [void]$cacheConsumerMembers.Add($member)
            $cacheAdmissionRef = [string]$member.compatibilityCacheAdmissionRef
            $cacheAdmission = if (-not $cacheAdmissionRef.Contains('#') -and $RecordMap.ContainsKey($cacheAdmissionRef)) {
                $RecordMap[$cacheAdmissionRef]
            }
            else { $null }
            [DateTimeOffset]$cacheAdmissionIssuedAt = [DateTimeOffset]::MinValue
            [DateTimeOffset]$cacheDistributionCreatedAt = [DateTimeOffset]::MinValue
            if ($null -eq $cacheAdmission -or
                [string]$cacheAdmission.recordType -cne 'compatibility-cache-admission-record' -or
                [string]$cacheAdmission.currentConsumerRef -cne [string]$member.recordId -or
                [string]$cacheAdmission.contentDigest -cne [string]$member.compatibilityCacheAdmissionDigest -or
                -not $memberRefs.Contains($cacheAdmissionRef) -or
                -not [OperationsBlueprint.StrictRfc3339]::TryParse([string]$cacheAdmission.issuedAt, [ref]$cacheAdmissionIssuedAt) -or
                -not [OperationsBlueprint.StrictRfc3339]::TryParse([string]$member.validFrom, [ref]$cacheDistributionCreatedAt) -or
                $cacheAdmissionIssuedAt -ge $cacheDistributionCreatedAt -or
                $cacheDistributionCreatedAt -ge $releasedAt) {
                $chronologyValid = $false
            }
            continue
        }
        $memberEvidence = if ([string]$member.recordType -ceq 'evidence-record') {
            $member
        }
        elseif ([string]$member.recordType -ceq 'distribution-record' -and
            (Test-NonBlankString $member.sourceEvidenceRef) -and
            -not ([string]$member.sourceEvidenceRef).Contains('#') -and
            $RecordMap.ContainsKey([string]$member.sourceEvidenceRef) -and
            @($ReleaseRecord.memberRecordIds) -ccontains [string]$member.sourceEvidenceRef) {
            $RecordMap[[string]$member.sourceEvidenceRef]
        }
        else { $null }
        [DateTimeOffset]$memberObservedAt = [DateTimeOffset]::MinValue
        [DateTimeOffset]$memberAdmittedAt = [DateTimeOffset]::MinValue
        [DateTimeOffset]$memberDistributionCreatedAt = [DateTimeOffset]::MinValue
        $memberIsDistribution = [string]$member.recordType -ceq 'distribution-record'
        if ($null -eq $memberEvidence -or [string]$memberEvidence.recordType -cne 'evidence-record' -or
            -not [OperationsBlueprint.StrictRfc3339]::TryParse([string]$memberEvidence.timestamp, [ref]$memberObservedAt) -or
            $memberEvidence.admission -isnot [pscustomobject] -or
            -not [OperationsBlueprint.StrictRfc3339]::TryParse([string]$memberEvidence.admission.admittedAt, [ref]$memberAdmittedAt) -or
            $memberObservedAt -gt $memberAdmittedAt -or
            ($memberIsDistribution -and
             (-not [OperationsBlueprint.StrictRfc3339]::TryParse([string]$member.validFrom, [ref]$memberDistributionCreatedAt) -or
              $memberAdmittedAt -ge $memberDistributionCreatedAt -or $memberDistributionCreatedAt -ge $releasedAt)) -or
            (-not $memberIsDistribution -and $memberAdmittedAt -ge $releasedAt)) {
            $chronologyValid = $false
        }
    }
    foreach ($cacheAdmissionMemberRef in @($cacheAdmissionMemberRefs)) {
        if (@($cacheConsumerMembers | Where-Object {
            [string]$_.compatibilityCacheAdmissionRef -ceq [string]$cacheAdmissionMemberRef
        }).Count -ne 1) {
            $membershipValid = $false
            Add-BlueprintError -Errors $Errors -Code 'COMPATIBILITY_CACHE_ADMISSION_INVALID' -Message 'A current evidence release cache admission must be referenced by exactly one current consumer distribution.'
        }
    }
    foreach ($cacheConsumerMember in @($cacheConsumerMembers)) {
        if (-not $cacheAdmissionMemberRefs.Contains([string]$cacheConsumerMember.compatibilityCacheAdmissionRef)) {
            $membershipValid = $false
            Add-BlueprintError -Errors $Errors -Code 'COMPATIBILITY_CACHE_ADMISSION_INVALID' -Message 'A current cache consumer distribution must bind an admission member of the same release.'
            continue
        }
        if ($CacheAdmissionSemanticsAlreadyValidated) { continue }
        if ($null -eq $Manifest -or $null -eq $Phase0TestPlan -or $null -eq $ThresholdPolicy -or
            -not (Test-NonBlankString $cacheConsumerMember.sourceEvidenceRef) -or
            ([string]$cacheConsumerMember.sourceEvidenceRef).Contains('#') -or
            -not $RecordMap.ContainsKey([string]$cacheConsumerMember.sourceEvidenceRef) -or
            [string]$RecordMap[[string]$cacheConsumerMember.sourceEvidenceRef].recordType -cne 'evidence-record') {
            Add-BlueprintError -Errors $Errors -Code 'COMPATIBILITY_CACHE_ADMISSION_INVALID' -Message 'A cache-bearing release requires exact current manifest, test-plan, threshold-policy, source-evidence, and admission authorities.'
            continue
        }
        [void](Test-CompatibilityCacheAdmissionSemantics -Distribution $cacheConsumerMember `
            -CachedEvidence $RecordMap[[string]$cacheConsumerMember.sourceEvidenceRef] `
            -Manifest $Manifest -Phase0TestPlan $Phase0TestPlan -ThresholdPolicy $ThresholdPolicy `
            -RecordMap $RecordMap -CurrentRelease $ReleaseRecord -EvaluationTime $EvaluationTime `
            -ValidationProfile $ValidationProfile -Errors $Errors)
    }
    if ($null -ne $ConsumerRecord) {
        [DateTimeOffset]$consumerAt = [DateTimeOffset]::MinValue
        $consumerTimestamp = if (Test-ValuePresent $ConsumerRecord.immutableAt) { [string]$ConsumerRecord.immutableAt }
            elseif (Test-ValuePresent $ConsumerRecord.validatedAt) { [string]$ConsumerRecord.validatedAt }
            elseif (Test-ValuePresent $ConsumerRecord.approvedAt) { [string]$ConsumerRecord.approvedAt }
            elseif (Test-ValuePresent $ConsumerRecord.authorizedAt) { [string]$ConsumerRecord.authorizedAt }
            elseif (Test-ValuePresent $ConsumerRecord.issuedAt) { [string]$ConsumerRecord.issuedAt }
            elseif (Test-ValuePresent $ConsumerRecord.validFrom) { [string]$ConsumerRecord.validFrom }
            else { '' }
        if (-not [OperationsBlueprint.StrictRfc3339]::TryParse($consumerTimestamp, [ref]$consumerAt) -or
            $releasedAt -ge $consumerAt -or $consumerAt -gt $EvaluationTime) {
            $chronologyValid = $false
        }
    }
    if (-not $chronologyValid) {
        Add-BlueprintError -Errors $Errors -Code 'EVIDENCE_RELEASE_CHRONOLOGY_INVALID' -Message "$Context release must be fresh, strictly later than every member observation/admission, and strictly earlier than its consuming verdict or semantic validation."
    }
    foreach ($statusName in @('semanticGateStatus', 'samplingFloorStatus', 'distributionStatus', 'coverageStatus')) {
        if ([string]$ReleaseRecord.$statusName -cne 'PASS') {
            Add-BlueprintError -Errors $Errors -Code 'EVIDENCE_RELEASE_GATE_NOT_PASSED' -Message "$Context evidence release $statusName is not PASS."
        }
    }
    foreach ($evidenceRecord in @($EvidenceRecords)) {
        if ($null -ne $evidenceRecord -and @($ReleaseRecord.memberRecordIds) -cnotcontains [string]$evidenceRecord.recordId) {
            Add-BlueprintError -Errors $Errors -Code 'EVIDENCE_NOT_IN_RELEASE' -Message "$Context evidence $($evidenceRecord.recordId) is absent from the validated release membership."
        }
        if ($null -ne $evidenceRecord -and [string]$evidenceRecord.provenance -ceq 'T2') {
            $corroborationRecordRef = if ($evidenceRecord.corroborationRef -is [pscustomobject]) {
                [string]$evidenceRecord.corroborationRef.recordRef
            }
            else { '' }
            if (@($ReleaseRecord.memberRecordIds) -cnotcontains $corroborationRecordRef) {
                Add-BlueprintError -Errors $Errors -Code 'T2_CORROBORATION_NOT_IN_RELEASE' -Message "$Context T2 corroboration is absent from the same validated evidence release."
            }
        }
    }
}

function Get-PortableContractMetadata {
    param([Parameter(Mandatory = $true)][string]$PortableRecordType)

    switch ($PortableRecordType) {
        'CANDIDATE_MANIFEST' {
            return [pscustomobject]@{ LegacyType = 'candidate-manifest'; IdPointer = '/manifestId'; SchemaUri = 'urn:laptop-qual:candidate-manifest:2.0.1'; SchemaDigest = 'sha256:67b5524a7b6cf2fd04755569d06395455f72ff48d4d0c0f610a381c61e889a96' }
        }
        'TEST_PLAN' {
            return [pscustomobject]@{ LegacyType = 'test-plan'; IdPointer = '/planId'; SchemaUri = 'urn:laptop-qual:test-plan:2.0.1'; SchemaDigest = 'sha256:532533504ff719aecdcd105c9dc5e0440cb6a9d786b08ff4319a3c236fd40c8e' }
        }
        'EVIDENCE_RECORD' {
            return [pscustomobject]@{ LegacyType = 'evidence-record'; IdPointer = '/recordId'; SchemaUri = 'urn:laptop-qual:evidence-record:2.0.1'; SchemaDigest = 'sha256:c998f6f60fcc2e7b07843fe434030533583f523cf8964186aff687c7f50fc166' }
        }
        'THRESHOLD_POLICY' {
            return [pscustomobject]@{ LegacyType = 'threshold-policy'; IdPointer = '/policyId'; SchemaUri = 'urn:laptop-qual:threshold-policy:2.0.1'; SchemaDigest = 'sha256:649c05cdf0c30ed88466c365361984c1715cfb089371f0a958386825601f1f1e' }
        }
        'VERDICT_RECORD' {
            return [pscustomobject]@{ LegacyType = 'verdict-record'; IdPointer = '/verdictId'; SchemaUri = 'urn:laptop-qual:verdict-record:2.0.1'; SchemaDigest = 'sha256:9a6a0e948ab42974e4d880ebc101b11199af36207dd68640dceb36f97b100492' }
        }
        default { return $null }
    }
}

function Get-PortableProjectionFieldContract {
    param([Parameter(Mandatory = $true)][string]$PortableRecordType)

    # Frozen v1 mapping profile: portable root properties bind to /<field>;
    # operations-only projections bind beneath /extensions/operationsBlueprintV1/<field>.
    $mappingProfile = 'OPERATIONS_BLUEPRINT_PORTABLE_PROJECTION_POINTERS_V1'
    switch ($PortableRecordType) {
        'CANDIDATE_MANIFEST' {
            $rootFields = @('schemaVersion','status','frozenAt','qualificationAuthority','testPlanRef','thresholdPolicyRef','hardwareEnvelope','platformBaseline','personas','candidateDevices','controls','docksAndPeripherals','pilotPopulationPlan','procurementDeadline','evaluationOwner','programCost','openItems','evidencePath','approvedBy','tier')
            $extensionFields = @('tenantBoundaryRef','targetEnvironmentRef')
            return [pscustomobject]@{
                Required = @('schemaVersion','status','frozenAt','qualificationAuthority','testPlanRef','thresholdPolicyRef','tenantBoundaryRef','targetEnvironmentRef')
                Allowed = @($rootFields + $extensionFields)
                RootFields = $rootFields
                OperationsExtensionFields = $extensionFields
                MappingProfile = $mappingProfile
            }
        }
        'TEST_PLAN' {
            $fields = @('schemaVersion','status','qualificationTier','manifestRef','thresholdPolicyRef','dependencyReviewRef','omittedClasses','frozenAt','approvedBy','samplingFloors','evidenceReusePolicy','tests')
            return [pscustomobject]@{ Required = $fields; Allowed = $fields; RootFields = $fields; OperationsExtensionFields = @(); MappingProfile = $mappingProfile }
        }
        'EVIDENCE_RECORD' {
            $rootFields = @('schemaVersion','provenance','testRef','conditionRef','testPackVersion','tool','result','distribution','coverage','artifacts','recordKind','evidenceUse','corroborationRef','subject','baseline','timestamp','admission','dataQuality','knownLimitations','stale')
            $extensionFields = @('claimId','personaId','capacityWaterfallPointer','evidenceReleaseRef','coverageStatus','cohortRef','observationWindow','distributionRef','attributionClass','issueStatement','businessEffectRef','testPlanRef','metricId','unit','statisticDirection','freshnessBinding')
            $nestedRootFieldPointers = [pscustomobject][ordered]@{
                subjectRef = '/subject/manifestRef'
                controlRole = '/subject/role'
                baselineFingerprint = '/baseline/baselineFingerprintSha256'
            }
            return [pscustomobject]@{
                Required = @('schemaVersion','recordKind','provenance','evidenceUse','testRef','conditionRef','testPackVersion','timestamp','admission','tool','result','coverage','dataQuality','artifacts','knownLimitations')
                Allowed = @($rootFields + $extensionFields + @($nestedRootFieldPointers.PSObject.Properties.Name))
                RootFields = $rootFields
                OperationsExtensionFields = $extensionFields
                NestedRootFieldPointers = $nestedRootFieldPointers
                MappingProfile = $mappingProfile
            }
        }
        'THRESHOLD_POLICY' {
            $rootFields = @('schemaVersion','version','status','frozenAt','approvedBy','thresholds','reserves','revisionPolicy','nonComparableAfterRevision','extensions')
            return [pscustomobject]@{
                Required = @('schemaVersion','version','status','frozenAt','approvedBy','thresholds')
                Allowed = $rootFields
                RootFields = $rootFields
                OperationsExtensionFields = @()
                MappingProfile = $mappingProfile
            }
        }
        'VERDICT_RECORD' {
            $rootFields = @('schemaVersion','recordStage','status','immutableAt','manifestRef','qualificationAuthority','approvers','evidenceReleases','pilotPopulationPlanRef','privacyOwner','pilotAuthorizationRecordRef','provisionalLabVerdict','pilotAuthorization','pilotCompletion','fleetVerdict','fleetDeploymentDisposition','personaVerdicts','conditions','exceptions','arbitration','deadlineDecision','procurementEnvelope','procurementDisposition','residualRisks','requalificationTriggers')
            $extensionFields = @('qualificationAuthorityApprovalRef','qualificationAuthorityApprovalDigest','pilotAuthorizationRecordDigest','pilotNotRequiredApprovalRef','pilotNotRequiredApprovalDigest','arbitrationAuthorityApprovalRef','arbitrationAuthorityApprovalDigest','deadlineAuthorityApprovalRef','deadlineAuthorityApprovalDigest')
            return [pscustomobject]@{
                Required = @('schemaVersion','recordStage','status','immutableAt','manifestRef','qualificationAuthority','approvers','evidenceReleases','qualificationAuthorityApprovalRef','qualificationAuthorityApprovalDigest')
                Allowed = @($rootFields + $extensionFields)
                RootFields = $rootFields
                OperationsExtensionFields = $extensionFields
                MappingProfile = $mappingProfile
            }
        }
        default { return $null }
    }
}

function Get-PortableProjectionFieldPointer {
    param(
        [Parameter(Mandatory = $true)]$FieldContract,
        [Parameter(Mandatory = $true)][string]$ProjectionField
    )

    $nestedPointerProperty = if ($FieldContract.PSObject.Properties['NestedRootFieldPointers'] -and
        $FieldContract.NestedRootFieldPointers -is [pscustomobject]) {
        $FieldContract.NestedRootFieldPointers.PSObject.Properties[$ProjectionField]
    }
    else { $null }
    if ($null -ne $nestedPointerProperty) { return [string]$nestedPointerProperty.Value }
    $escapedField = $ProjectionField.Replace('~', '~0').Replace('/', '~1')
    if (@($FieldContract.RootFields) -ccontains $ProjectionField) { return '/' + $escapedField }
    if (@($FieldContract.OperationsExtensionFields) -ccontains $ProjectionField) {
        return '/extensions/operationsBlueprintV1/' + $escapedField
    }
    return $null
}

function Get-PortableContractValidationInputDigest {
    param([Parameter(Mandatory = $true)]$ValidationRecord)

    return Get-CanonicalPayloadDigest -Payload ([pscustomobject][ordered]@{
        portableRecordType = [string]$ValidationRecord.portableRecordType
        sourceRecordRef = [string]$ValidationRecord.sourceRecordRef
        sourceRecordDigest = [string]$ValidationRecord.sourceRecordDigest
        schemaUri = [string]$ValidationRecord.schemaUri
        schemaDigest = [string]$ValidationRecord.schemaDigest
        validatorReleaseRef = [string]$ValidationRecord.validatorReleaseRef
        validatorReleaseDigest = [string]$ValidationRecord.validatorReleaseDigest
    })
}

function Get-PortableContractValidationResultDigest {
    param([Parameter(Mandatory = $true)]$ValidationRecord)

    return Get-CanonicalPayloadDigest -Payload ([pscustomobject][ordered]@{
        status = [string]$ValidationRecord.status
        validationInputDigest = [string]$ValidationRecord.validationInputDigest
        validationIssueCount = $ValidationRecord.validationIssueCount
        validationIssueSetDigest = [string]$ValidationRecord.validationIssueSetDigest
        validatedAt = [string]$ValidationRecord.validatedAt
        resolverStatus = [string]$ValidationRecord.resolverStatus
    })
}

function Get-PortableContractProjectionDigest {
    param([Parameter(Mandatory = $true)][AllowEmptyCollection()][object[]]$Bindings)
    return Get-CanonicalPayloadDigest -Payload @($Bindings)
}

function Test-PortableContractFreshnessBinding {
    param(
        [AllowNull()]$Freshness,
        [Parameter(Mandatory = $true)][DateTimeOffset]$EvaluationTime,
        [Parameter(Mandatory = $true)][string]$Context,
        [Parameter(Mandatory = $true)][AllowEmptyCollection()][System.Collections.ArrayList]$Errors
    )

    $fields = @('observedAt','admittedAt','policyRef','maxAgeDays','dependencySnapshotRef','dependencySnapshotDigest','dependencyStatus')
    if ($Freshness -isnot [pscustomobject]) {
        Add-BlueprintError -Errors $Errors -Code 'PORTABLE_CONTRACT_FRESHNESS_INVALID' -Message "$Context requires an exact current portable-contract freshness binding."
        return $false
    }
    Test-RequiredProperties -Object $Freshness -Names $fields -Context $Context -Errors $Errors
    Test-AllowedProperties -Object $Freshness -Names $fields -Context $Context -Errors $Errors
    [DateTimeOffset]$observedAt = [DateTimeOffset]::MinValue
    [DateTimeOffset]$admittedAt = [DateTimeOffset]::MinValue
    $valid = [OperationsBlueprint.StrictRfc3339]::TryParse([string]$Freshness.observedAt, [ref]$observedAt) -and
        [OperationsBlueprint.StrictRfc3339]::TryParse([string]$Freshness.admittedAt, [ref]$admittedAt) -and
        $observedAt -le $admittedAt -and $admittedAt -le $EvaluationTime -and
        ($Freshness.maxAgeDays -is [int] -or $Freshness.maxAgeDays -is [long]) -and
        [int64]$Freshness.maxAgeDays -ge 1 -and [int64]$Freshness.maxAgeDays -le 3650 -and
        ($EvaluationTime - $observedAt).TotalDays -le [int64]$Freshness.maxAgeDays -and
        (Test-NonBlankString $Freshness.policyRef) -and
        (Test-NonBlankString $Freshness.dependencySnapshotRef) -and
        (Test-Sha256Token $Freshness.dependencySnapshotDigest) -and
        [string]$Freshness.dependencyStatus -ceq 'MATCH'
    if (-not $valid) {
        Add-BlueprintError -Errors $Errors -Code 'PORTABLE_CONTRACT_FRESHNESS_INVALID' -Message "$Context is stale, future-dated, mismatched, unbounded, or lacks its exact policy and dependency snapshot."
    }
    return $valid
}

function New-PortableProjectionSourcePayload {
    param(
        [Parameter(Mandatory = $true)][AllowEmptyCollection()][object[]]$Bindings,
        [Parameter(Mandatory = $true)][AllowEmptyCollection()][System.Collections.ArrayList]$Errors,
        [Parameter(Mandatory = $true)][string]$Context
    )

    $root = [pscustomobject][ordered]@{}
    # Materialize parents before descendants. The frozen projection profile
    # deliberately binds portable root objects such as /subject and also binds
    # security-relevant descendants such as /subject/manifestRef. An overlap is
    # valid only when the descendant is already present in the authenticated
    # parent value and is canonically identical; it is never an overwrite.
    $orderedBindings = @($Bindings | Sort-Object { ([regex]::Matches([string]$_.pointer, '/')).Count })
    foreach ($binding in $orderedBindings) {
        if (-not (Test-StrictJsonPointerSyntax -Pointer $binding.pointer)) { continue }
        $tokens = @(
            foreach ($encodedToken in ([string]$binding.pointer).Substring(1).Split('/')) {
                (ConvertFrom-StrictJsonPointerToken -EncodedToken $encodedToken).Value
            }
        )
        if ($tokens.Count -eq 0 -or @($tokens | Where-Object { [string]::IsNullOrEmpty([string]$_) }).Count -gt 0) {
            Add-BlueprintError -Errors $Errors -Code 'PORTABLE_CONTRACT_PROJECTION_INVALID' -Message "$Context contains a projection pointer that cannot be represented as a closed named view."
            continue
        }
        $current = $root
        for ($tokenIndex = 0; $tokenIndex -lt $tokens.Count; $tokenIndex++) {
            $token = [string]$tokens[$tokenIndex]
            $caseInsensitiveMatches = @($current.PSObject.Properties | Where-Object { [string]$_.Name -ieq $token })
            $exactMatches = @($caseInsensitiveMatches | Where-Object { [string]$_.Name -ceq $token })
            $last = $tokenIndex -eq ($tokens.Count - 1)
            if ($last) {
                if ($caseInsensitiveMatches.Count -gt 0) {
                    if ($caseInsensitiveMatches.Count -eq 1 -and $exactMatches.Count -eq 1 -and
                        (Test-CanonicalValueEqual $exactMatches[0].Value $binding.value)) {
                        continue
                    }
                    Add-BlueprintError -Errors $Errors -Code 'PORTABLE_CONTRACT_PROJECTION_INVALID' -Message "$Context has a duplicate, case-colliding, or contradictory overlapping source pointer."
                    break
                }
                $current | Add-Member -NotePropertyName $token -NotePropertyValue $binding.value
                continue
            }
            if ($caseInsensitiveMatches.Count -eq 0) {
                $child = [pscustomobject][ordered]@{}
                $current | Add-Member -NotePropertyName $token -NotePropertyValue $child
                $current = $child
            }
            elseif ($exactMatches.Count -eq 1 -and $exactMatches[0].Value -is [pscustomobject]) {
                $current = $exactMatches[0].Value
            }
            else {
                Add-BlueprintError -Errors $Errors -Code 'PORTABLE_CONTRACT_PROJECTION_INVALID' -Message "$Context has a case-colliding or contradictory overlapping source pointer."
                break
            }
        }
    }
    return $root
}

function Initialize-PortableContractProjectionViews {
    param(
        [Parameter(Mandatory = $true)]$RecordMap,
        [Parameter(Mandatory = $true)][DateTimeOffset]$EvaluationTime,
        [ValidateSet('TEST','PRODUCTION')][string]$ValidationProfile,
        [Parameter(Mandatory = $true)][AllowEmptyCollection()][System.Collections.ArrayList]$Errors
    )

    $projectionRecords = @($RecordMap.Values | Where-Object { [string]$_.recordType -ceq 'portable-contract-projection-record' })
    $sourceProjectionSet = [System.Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal)
    foreach ($projectionRecord in $projectionRecords) {
        $context = "portable projection $($projectionRecord.recordId)"
        $metadata = Get-PortableContractMetadata -PortableRecordType ([string]$projectionRecord.portableRecordType)
        $fieldContract = Get-PortableProjectionFieldContract -PortableRecordType ([string]$projectionRecord.portableRecordType)
        $validationRecord = if ((Test-NonBlankString $projectionRecord.validationRecordRef) -and
            $RecordMap.ContainsKey(([string]$projectionRecord.validationRecordRef).Split('#',2)[0])) {
            $RecordMap[([string]$projectionRecord.validationRecordRef).Split('#',2)[0]]
        }
        else { $null }
        if ($null -eq $validationRecord -or [string]$validationRecord.recordType -cne 'portable-contract-validation-record') {
            Add-BlueprintError -Errors $Errors -Code 'PORTABLE_CONTRACT_VALIDATION_UNRESOLVED' -Message "$context lacks one exact portable-contract validation record."
            continue
        }

        $validationInputDigest = Get-PortableContractValidationInputDigest -ValidationRecord $validationRecord
        $validationResultDigest = Get-PortableContractValidationResultDigest -ValidationRecord $validationRecord
        $emptyIssueSetDigest = Get-CanonicalPayloadDigest -Payload @()
        [DateTimeOffset]$validatedAt = [DateTimeOffset]::MinValue
        [DateTimeOffset]$projectedAt = [DateTimeOffset]::MinValue
        $validationFresh = Test-PortableContractFreshnessBinding -Freshness $validationRecord.freshnessBinding `
            -EvaluationTime $EvaluationTime -Context "$context validation freshness" -Errors $Errors
        $projectionFresh = Test-PortableContractFreshnessBinding -Freshness $projectionRecord.freshnessBinding `
            -EvaluationTime $EvaluationTime -Context "$context projection freshness" -Errors $Errors
        $validationValid = $null -ne $metadata -and $null -ne $fieldContract -and
            [string]$validationRecord.schemaVersion -ceq '1.0.0' -and
            [string]$validationRecord.recordStage -ceq 'PORTABLE_CONTRACT_VALIDATION' -and
            [string]$validationRecord.status -ceq 'VERIFIED' -and
            [string]$validationRecord.portableRecordType -ceq [string]$projectionRecord.portableRecordType -and
            [string]$validationRecord.sourceRecordRef -ceq [string]$projectionRecord.sourceRecordRef -and
            (Test-NonBlankString $validationRecord.sourceRecordRef) -and
            -not ([string]$validationRecord.sourceRecordRef).Contains('#') -and
            [string]$validationRecord.sourceRecordDigest -ceq [string]$projectionRecord.sourceRecordDigest -and
            (Test-Sha256Token $validationRecord.sourceRecordDigest) -and
            [string]$validationRecord.schemaUri -ceq [string]$metadata.SchemaUri -and
            [string]$validationRecord.schemaDigest -ceq [string]$metadata.SchemaDigest -and
            [string]$validationRecord.validationInputDigest -ceq [string]$validationInputDigest -and
            ($validationRecord.validationIssueCount -is [int] -or $validationRecord.validationIssueCount -is [long]) -and
            [int64]$validationRecord.validationIssueCount -eq 0 -and
            [string]$validationRecord.validationIssueSetDigest -ceq [string]$emptyIssueSetDigest -and
            [string]$validationRecord.validationResultDigest -ceq [string]$validationResultDigest -and
            [string]$validationRecord.protectedAttestationSubjectDigest -ceq [string]$validationResultDigest -and
            (Test-Sha256Token $validationRecord.protectedAttestationDigest) -and
            (Test-Sha256Token $validationRecord.validatorReleaseDigest) -and
            [string]$validationRecord.authorizationEffect -ceq 'NONE' -and
            [OperationsBlueprint.StrictRfc3339]::TryParse([string]$validationRecord.validatedAt, [ref]$validatedAt) -and
            $validatedAt -le $EvaluationTime -and $validationFresh
        if ([string]$ValidationProfile -ceq 'TEST') {
            $validationValid = $validationValid -and
                [string]$validationRecord.validationMode -ceq 'TEST' -and
                [string]$validationRecord.resolverStatus -ceq 'SYNTHETIC' -and
                [string]$validationRecord.protectedAttestationStatus -ceq 'SYNTHETIC'
        }
        else {
            $validationValid = $validationValid -and
                [string]$validationRecord.validationMode -ceq 'PRODUCTION' -and
                [string]$validationRecord.resolverStatus -ceq 'AUTHENTICATED' -and
                [string]$validationRecord.protectedAttestationStatus -ceq 'VERIFIED'
            Add-BlueprintError -Errors $Errors -Code 'PORTABLE_CONTRACT_PRIVATE_SOURCE_UNVERIFIED' -Message "$context cannot authorize production without the protected authenticated source/schema/attestation resolver."
        }
        if (-not $validationValid) {
            Add-BlueprintError -Errors $Errors -Code 'PORTABLE_CONTRACT_VALIDATION_INVALID' -Message "$context validation does not bind the exact source, frozen schema, validator release, zero-issue result, attestation subject, mode, and current dependency state."
        }

        if ($projectionRecord.projection -isnot [pscustomobject]) {
            Add-BlueprintError -Errors $Errors -Code 'PORTABLE_CONTRACT_PROJECTION_INVALID' -Message "$context lacks one closed typed projection object."
            continue
        }
        Test-RequiredProperties -Object $projectionRecord.projection -Names @('projectionType','bindings') -Context "$context projection" -Errors $Errors
        Test-AllowedProperties -Object $projectionRecord.projection -Names @('projectionType','bindings') -Context "$context projection" -Errors $Errors
        $bindings = @($projectionRecord.projection.bindings)
        $fieldSet = [System.Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
        $pointerSet = [System.Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal)
        $bindingsValid = $bindings.Count -gt 0 -and $null -ne $fieldContract -and
            [string]$fieldContract.MappingProfile -ceq 'OPERATIONS_BLUEPRINT_PORTABLE_PROJECTION_POINTERS_V1'
        foreach ($binding in $bindings) {
            if ($binding -isnot [pscustomobject]) { $bindingsValid = $false; continue }
            Test-RequiredProperties -Object $binding -Names @('projectionField','pointer','valueDigest') -Context "$context binding" -Errors $Errors
            if ($null -eq $binding.PSObject.Properties['value']) {
                Add-BlueprintError -Errors $Errors -Code 'MISSING_REQUIRED_FIELD' -Message "$context binding requires the value property, which may contain a schema-valid empty array or object."
                $bindingsValid = $false
            }
            Test-AllowedProperties -Object $binding -Names @('projectionField','pointer','value','valueDigest') -Context "$context binding" -Errors $Errors
            $expectedPointer = if ($null -ne $fieldContract -and (Test-NonBlankString $binding.projectionField)) {
                Get-PortableProjectionFieldPointer -FieldContract $fieldContract -ProjectionField ([string]$binding.projectionField)
            }
            else { $null }
            if (-not (Test-NonBlankString $binding.projectionField) -or
                $null -eq $fieldContract -or
                @($fieldContract.Allowed) -cnotcontains [string]$binding.projectionField -or
                -not $fieldSet.Add([string]$binding.projectionField) -or
                -not (Test-StrictJsonPointerSyntax -Pointer $binding.pointer) -or
                $null -eq $expectedPointer -or [string]$binding.pointer -cne [string]$expectedPointer -or
                -not $pointerSet.Add([string]$binding.pointer) -or
                [string]$binding.valueDigest -cne [string](Get-CanonicalPayloadDigest -Payload $binding.value)) {
                $bindingsValid = $false
            }
        }
        if ($null -ne $fieldContract) {
            foreach ($requiredField in @($fieldContract.Required)) {
                if (-not $fieldSet.Contains([string]$requiredField)) { $bindingsValid = $false }
            }
        }
        $bindingPointers = @($bindings | ForEach-Object { [string]$_.pointer })
        $projectionPointers = @($projectionRecord.projectionPointers | ForEach-Object { [string]$_ })
        $projectionDigest = Get-PortableContractProjectionDigest -Bindings $bindings
        $projectionValid = $validationValid -and $bindingsValid -and
            [string]$projectionRecord.schemaVersion -ceq '1.0.0' -and
            [string]$projectionRecord.recordStage -ceq 'PORTABLE_CONTRACT_PROJECTION' -and
            [string]$projectionRecord.status -ceq 'VERIFIED' -and
            [string]$projectionRecord.projection.projectionType -ceq [string]$projectionRecord.portableRecordType -and
            (Test-NonBlankString $projectionRecord.sourceRecordRef) -and
            -not ([string]$projectionRecord.sourceRecordRef).Contains('#') -and
            (Test-Sha256Token $projectionRecord.sourceRecordDigest) -and
            [string]$projectionRecord.sourceCanonicalIdPointer -ceq [string]$metadata.IdPointer -and
            [string]$projectionRecord.sourceCanonicalIdValue -ceq [string]$projectionRecord.recordId -and
            [string]$projectionRecord.validationRecordDigest -ceq [string]$validationRecord.contentDigest -and
            [string]$projectionRecord.validationRecordRef -ceq [string]$validationRecord.recordId -and
            (Test-CanonicalValueEqual $projectionPointers $bindingPointers) -and
            [string]$projectionRecord.projectionDigest -ceq [string]$projectionDigest -and
            [string]$projectionRecord.validationMode -ceq [string]$validationRecord.validationMode -and
            [string]$projectionRecord.resolverStatus -ceq [string]$validationRecord.resolverStatus -and
            [string]$projectionRecord.authorizationEffect -ceq 'NONE' -and
            [OperationsBlueprint.StrictRfc3339]::TryParse([string]$projectionRecord.projectedAt, [ref]$projectedAt) -and
            $projectedAt -ge $validatedAt -and $projectedAt -le $EvaluationTime -and $projectionFresh -and
            (Test-CanonicalValueEqual $projectionRecord.freshnessBinding $validationRecord.freshnessBinding)
        $sourceProjectionKey = ([string]$projectionRecord.portableRecordType) + [char]0 +
            ([string]$projectionRecord.sourceRecordRef) + [char]0 + ([string]$projectionRecord.sourceRecordDigest)
        if (-not $sourceProjectionSet.Add($sourceProjectionKey)) { $projectionValid = $false }
        $provenanceBinding = @($bindings | Where-Object { [string]$_.projectionField -ceq 'provenance' })
        $corroborationBinding = @($bindings | Where-Object { [string]$_.projectionField -ceq 'corroborationRef' })
        $portableDistributionBinding = @($bindings | Where-Object { [string]$_.projectionField -ceq 'distribution' })
        if ([string]$projectionRecord.portableRecordType -ceq 'EVIDENCE_RECORD') {
            $projectionValid = $projectionValid -and $provenanceBinding.Count -eq 1 -and
                [string]$projectionRecord.provenance -ceq [string]$provenanceBinding[0].value
            if ([string]$projectionRecord.provenance -ceq 'T0') {
                $projectionValid = $projectionValid -and $portableDistributionBinding.Count -eq 1
                foreach ($requiredT0Field in @('subjectRef','controlRole','baselineFingerprint','distributionRef')) {
                    $projectionValid = $projectionValid -and $fieldSet.Contains($requiredT0Field)
                }
            }
            if ([string]$projectionRecord.provenance -ceq 'T2') {
                $projectionValid = $projectionValid -and $corroborationBinding.Count -eq 1 -and
                    $projectionRecord.corroborationRef -is [pscustomobject] -and
                    (Test-CanonicalValueEqual $projectionRecord.corroborationRef $corroborationBinding[0].value)
            }
            else {
                $projectionValid = $projectionValid -and $corroborationBinding.Count -eq 0 -and
                    $null -eq $projectionRecord.PSObject.Properties['corroborationRef']
            }
        }
        if (-not $projectionValid) {
            Add-BlueprintError -Errors $Errors -Code 'PORTABLE_CONTRACT_PROJECTION_INVALID' -Message "$context does not bind one exact validated portable source, canonical ID, closed ordered pointer/value set, projection digest, mode, freshness, and T2 corroboration contract."
            continue
        }

        $sourcePayload = New-PortableProjectionSourcePayload -Bindings $bindings -Errors $Errors -Context $context
        $view = [pscustomobject][ordered]@{
            recordId = [string]$projectionRecord.recordId
            recordType = [string]$metadata.LegacyType
            contentDigest = [string]$projectionRecord.contentDigest
            validated = $projectionRecord.validated
            freshness = [string]$projectionRecord.freshness
            validFrom = [string]$projectionRecord.validFrom
            validUntil = [string]$projectionRecord.validUntil
            pointers = @($projectionRecord.projectionPointers)
            immutableArtifactRef = [string]$projectionRecord.immutableArtifactRef
            envelopeProfile = [string]$projectionRecord.envelopeProfile
            envelopeCoreDigest = [string]$projectionRecord.envelopeCoreDigest
            attestationRef = [string]$projectionRecord.attestationRef
            attestationDigest = [string]$projectionRecord.attestationDigest
            attestationSubjectDigest = [string]$projectionRecord.attestationSubjectDigest
            attestationStatus = [string]$projectionRecord.attestationStatus
            payload = $sourcePayload
            portableRecordType = [string]$projectionRecord.portableRecordType
            sourceRecordRef = [string]$projectionRecord.sourceRecordRef
            sourceRecordDigest = [string]$projectionRecord.sourceRecordDigest
            portableProjectionRecord = $projectionRecord
            portableValidationRecord = $validationRecord
        }
        $canonicalIdName = ([string]$metadata.IdPointer).Substring(1)
        if ($null -ne $view.PSObject.Properties[$canonicalIdName]) {
            if ([string]$view.$canonicalIdName -cne [string]$projectionRecord.sourceCanonicalIdValue) {
                Add-BlueprintError -Errors $Errors -Code 'PORTABLE_CONTRACT_PROJECTION_INVALID' -Message "$context canonical source ID conflicts with canonical envelope identity."
                $projectionValid = $false
            }
        }
        else {
            $view | Add-Member -NotePropertyName $canonicalIdName -NotePropertyValue ([string]$projectionRecord.sourceCanonicalIdValue)
        }
        foreach ($binding in $bindings) {
            $fieldName = [string]$binding.projectionField
            if ($null -ne $view.PSObject.Properties[$fieldName]) {
                Add-BlueprintError -Errors $Errors -Code 'PORTABLE_CONTRACT_PROJECTION_INVALID' -Message "$context projection field conflicts with canonical envelope metadata."
                $projectionValid = $false
                continue
            }
            $view | Add-Member -NotePropertyName $fieldName -NotePropertyValue $binding.value
        }
        if ($projectionValid) { $RecordMap[[string]$projectionRecord.recordId] = $view }
    }
}

function Get-CanonicalRecordMap {
    param(
        [object[]]$RecordIndex,
        [Parameter(Mandatory = $true)][AllowEmptyCollection()][System.Collections.ArrayList]$Errors,
        [Parameter(Mandatory = $true)][string]$Context,
        [DateTimeOffset]$EvaluationTime = [DateTimeOffset]::UtcNow,
        [ValidateSet('TEST', 'PRODUCTION')][string]$ValidationProfile = 'PRODUCTION'
    )

    $ValidationProfile = ([string]$ValidationProfile).ToUpperInvariant()
    $records = [System.Collections.Generic.Dictionary[string,object]]::new([System.StringComparer]::Ordinal)
    if (@($RecordIndex).Count -eq 0) {
        Add-BlueprintError -Errors $Errors -Code 'RECORD_INDEX_REQUIRED' -Message "$Context requires a typed canonical record index."
        return ,$records
    }

    $allowedTypes = @(
        'portable-contract-validation-record', 'portable-contract-projection-record',
        'qualification-authority-approval-record', 'evidence-release', 'cohort-record', 'business-impact-record',
        'commercial-quote-record', 'distribution-record', 'decision-claim-record', 'semantic-validation-record',
        'pilot-authorization-record', 'stop-conditions-record', 'rollback-record',
        'procurement-envelope-record', 'readback-record', 'condition-record',
        'activation-record', 'approval-record', 'write-operation-record',
        'transport-ownership-record', 'reviewed-plan-record', 'exception-record',
        'compensating-control-record', 'platform-baseline-record', 'fleet-portfolio-record',
        'rollout-monitoring-record', 'query-pack-record', 'telemetry-baseline-record',
        'coverage-policy-record', 'requalification-plan-record', 'stop-condition-record',
        'package-verification-record', 'write-authorization-record', 'phase2-approval-record',
        'render-manifest-record', 'authorization-consumption-record',
        'authorization-consumption-ledger-readback-record', 'security-freshness-policy-record',
        'identity-governance-root-authority-record', 'role-binding-record',
        'role-binding-approval-record', 'role-binding-readback-record', 'azure-deployment-operation-record',
        'atmos-stack-render-record'
    )

    foreach ($record in @($RecordIndex)) {
        if ($record -is [string] -or $record -isnot [pscustomobject]) {
            Add-BlueprintError -Errors $Errors -Code 'UNTYPED_RECORD_INDEX_ENTRY' -Message "$Context record index entries must be typed objects; bare identifiers are forbidden."
            continue
        }
        if (-not (Test-CanonicalJsonRuntimeDomain -Value $record)) {
            Add-BlueprintError -Errors $Errors -Code 'CANONICAL_JSON_RUNTIME_DOMAIN_INVALID' -Message "$Context record contains a value outside the frozen cross-host JSON runtime domain."
            continue
        }

        Test-RequiredProperties -Object $record -Names @(
            'recordId', 'recordType', 'contentDigest', 'validated', 'freshness',
            'validFrom', 'validUntil', 'pointers', 'payload', 'immutableArtifactRef',
            'envelopeProfile', 'envelopeCoreDigest', 'attestationRef', 'attestationDigest',
            'attestationSubjectDigest', 'attestationStatus'
        ) -Context "$Context record" -Errors $Errors
        Test-AllowedProperties -Object $record -Names @(
            'recordId', 'recordType', 'contentDigest', 'validated', 'freshness',
            'validFrom', 'validUntil', 'pointers', 'payload', 'immutableArtifactRef',
            'envelopeProfile', 'envelopeCoreDigest', 'attestationRef', 'attestationDigest',
            'attestationSubjectDigest', 'attestationStatus'
        ) -Context "$Context canonical record envelope" -Errors $Errors

        $recordId = [string]$record.recordId
        if ([string]::IsNullOrWhiteSpace($recordId)) { continue }
        if ($records.ContainsKey($recordId)) {
            Add-BlueprintError -Errors $Errors -Code 'DUPLICATE_RECORD_INDEX_ID' -Message "$Context record index repeats $recordId."
            continue
        }

        if ([string]$record.recordType -cnotin $allowedTypes) {
            Add-BlueprintError -Errors $Errors -Code 'INVALID_RECORD_TYPE' -Message "$recordId has an unsupported recordType."
        }
        if (-not (Test-Sha256Token $record.contentDigest)) {
            Add-BlueprintError -Errors $Errors -Code 'INVALID_RECORD_DIGEST' -Message "$recordId lacks a SHA-256 content digest."
        }
        if ($record.payload -isnot [pscustomobject]) {
            Add-BlueprintError -Errors $Errors -Code 'CANONICAL_PAYLOAD_REQUIRED' -Message "$recordId lacks an embedded canonical object payload."
        }
        else {
            $calculatedDigest = Get-CanonicalPayloadDigest -Payload $record.payload
            if ([string]$calculatedDigest -cne [string]$record.contentDigest) {
                Add-BlueprintError -Errors $Errors -Code 'CANONICAL_PAYLOAD_DIGEST_MISMATCH' -Message "$recordId payload bytes do not match contentDigest."
            }
        }
        if (-not (Test-ValuePresent $record.immutableArtifactRef) -or
            -not (([string]$record.immutableArtifactRef).StartsWith('private://', [System.StringComparison]::Ordinal) -or
                  ([string]$record.immutableArtifactRef).StartsWith('fixture://', [System.StringComparison]::Ordinal))) {
            Add-BlueprintError -Errors $Errors -Code 'IMMUTABLE_ARTIFACT_REF_REQUIRED' -Message "$recordId lacks a bounded immutable artifact reference."
        }
        if ([string]$record.envelopeProfile -cne 'operations-canonical-envelope/1.0.0') {
            Add-BlueprintError -Errors $Errors -Code 'CANONICAL_ENVELOPE_PROFILE_INVALID' -Message "$recordId does not use the frozen canonical-envelope profile."
        }
        $calculatedEnvelopeCoreDigest = Get-CanonicalEnvelopeCoreDigest -Record $record
        if (-not (Test-Sha256Token $record.envelopeCoreDigest) -or
            [string]$record.envelopeCoreDigest -cne [string]$calculatedEnvelopeCoreDigest) {
            Add-BlueprintError -Errors $Errors -Code 'CANONICAL_ENVELOPE_CORE_DIGEST_MISMATCH' -Message "$recordId envelope identity, type, validity, freshness, pointers, artifact, or payload digest differs from its attested core."
        }
        if (-not (Test-ValuePresent $record.attestationRef) -or
            -not (([string]$record.attestationRef).StartsWith('private://', [System.StringComparison]::Ordinal) -or
                  ([string]$record.attestationRef).StartsWith('fixture://', [System.StringComparison]::Ordinal)) -or
            -not (Test-Sha256Token $record.attestationDigest) -or
            -not (Test-Sha256Token $record.attestationSubjectDigest) -or
            [string]$record.attestationSubjectDigest -cne [string]$calculatedEnvelopeCoreDigest -or
            [string]$record.attestationStatus -cne 'VERIFIED') {
            Add-BlueprintError -Errors $Errors -Code 'RELEASE_ATTESTATION_BINDING_INVALID' -Message "$recordId lacks a verified attestation bound to its recomputed canonical-envelope core."
        }
        if ([string]$ValidationProfile -ceq 'PRODUCTION' -and
            (([string]$record.immutableArtifactRef).StartsWith('fixture://', [System.StringComparison]::Ordinal) -or
             ([string]$record.attestationRef).StartsWith('fixture://', [System.StringComparison]::Ordinal))) {
            Add-BlueprintError -Errors $Errors -Code 'FIXTURE_RECORD_FORBIDDEN_IN_PRODUCTION' -Message "$recordId uses a test fixture or local synthetic attestation in the production validation profile."
        }
        if ($record.validated -isnot [bool] -or -not $record.validated) {
            Add-BlueprintError -Errors $Errors -Code 'UNVALIDATED_RECORD' -Message "$recordId is not a validated canonical record."
        }
        if ([string]$record.freshness -cne 'CURRENT') {
            Add-BlueprintError -Errors $Errors -Code 'STALE_CANONICAL_RECORD' -Message "$recordId is not CURRENT."
        }

        [DateTimeOffset]$validFrom = [DateTimeOffset]::MinValue
        [DateTimeOffset]$validUntil = [DateTimeOffset]::MinValue
        if (-not [OperationsBlueprint.StrictRfc3339]::TryParse([string]$record.validFrom, [ref]$validFrom) -or
            -not [OperationsBlueprint.StrictRfc3339]::TryParse([string]$record.validUntil, [ref]$validUntil) -or
            $validFrom -gt $EvaluationTime -or $validUntil -le $EvaluationTime -or $validUntil -le $validFrom) {
            Add-BlueprintError -Errors $Errors -Code 'RECORD_VALIDITY_WINDOW_INVALID' -Message "$recordId is outside its explicit validity window."
        }

        $pointers = @($record.pointers)
        if ($pointers.Count -eq 0) {
            Add-BlueprintError -Errors $Errors -Code 'EMPTY_RECORD_POINTER_INVENTORY' -Message "$recordId has no pointer inventory."
        }
        foreach ($pointer in $pointers) {
            if ($pointer -isnot [string] -or -not ([string]$pointer).StartsWith('/', [System.StringComparison]::Ordinal)) {
                Add-BlueprintError -Errors $Errors -Code 'INVALID_RECORD_POINTER' -Message "$recordId contains an invalid pointer inventory entry."
            }
            elseif ($record.payload -is [pscustomobject] -and -not (Test-JsonPointerExists -Document $record.payload -Pointer ([string]$pointer))) {
                Add-BlueprintError -Errors $Errors -Code 'UNRESOLVED_RECORD_POINTER' -Message "$recordId inventory pointer $pointer does not exist in the canonical payload."
            }
        }
        foreach ($group in @($pointers | Group-Object -CaseSensitive)) {
            if ($group.Count -gt 1) {
                Add-BlueprintError -Errors $Errors -Code 'DUPLICATE_RECORD_POINTER' -Message "$recordId repeats pointer $($group.Name)."
            }
        }

        $verifiedRecord = [pscustomobject][ordered]@{
            recordId = $recordId
            recordType = [string]$record.recordType
            contentDigest = [string]$record.contentDigest
            validated = $record.validated
            freshness = [string]$record.freshness
            validFrom = [string]$record.validFrom
            validUntil = [string]$record.validUntil
            pointers = @($record.pointers)
            immutableArtifactRef = [string]$record.immutableArtifactRef
            envelopeProfile = [string]$record.envelopeProfile
            envelopeCoreDigest = [string]$record.envelopeCoreDigest
            attestationRef = [string]$record.attestationRef
            attestationDigest = [string]$record.attestationDigest
            attestationSubjectDigest = [string]$record.attestationSubjectDigest
            attestationStatus = [string]$record.attestationStatus
            payload = $record.payload
        }
        if ($record.payload -is [pscustomobject]) {
            foreach ($payloadProperty in $record.payload.PSObject.Properties) {
                $existing = $verifiedRecord.PSObject.Properties[[string]$payloadProperty.Name]
                if ($null -ne $existing) {
                    $existingJson = ConvertTo-DeterministicJsonText -Value (ConvertTo-CanonicalJsonValue $existing.Value)
                    $payloadJson = ConvertTo-DeterministicJsonText -Value (ConvertTo-CanonicalJsonValue $payloadProperty.Value)
                    if ($existingJson -cne $payloadJson) {
                        Add-BlueprintError -Errors $Errors -Code 'CANONICAL_ENVELOPE_PAYLOAD_CONFLICT' -Message "$recordId payload conflicts with envelope field $($payloadProperty.Name)."
                    }
                    continue
                }
                $verifiedRecord | Add-Member -NotePropertyName ([string]$payloadProperty.Name) -NotePropertyValue $payloadProperty.Value
            }
        }
        [void]$records.Add($recordId, $verifiedRecord)

    }

    Initialize-PortableContractProjectionViews -RecordMap $records -EvaluationTime $EvaluationTime `
        -ValidationProfile $ValidationProfile -Errors $Errors

    foreach ($record in @($records.Values | Where-Object { [string]$_.recordType -ceq 'evidence-record' })) {
        Test-RequiredProperties -Object $record -Names @('claimId', 'provenance') -Context "evidence record $($record.recordId)" -Errors $Errors
        if ([string]$record.provenance -cnotin @('T0', 'T1', 'T2')) {
            Add-BlueprintError -Errors $Errors -Code 'INVALID_PROVENANCE' -Message "$($record.recordId) has unsupported provenance."
        }
    }

    foreach ($record in @($records.Values | Where-Object { [string]$_.recordType -ceq 'evidence-record' -and [string]$_.provenance -ceq 'T2' })) {
        $corroborationBinding = $record.corroborationRef
        if ($corroborationBinding -isnot [pscustomobject]) {
            Add-BlueprintError -Errors $Errors -Code 'T2_CORROBORATION_REQUIRED' -Message "$($record.recordId) requires a structured same-claim T0 or T1 corroboration binding."
            continue
        }
        Test-RequiredProperties -Object $corroborationBinding -Names @('recordRef','expectedProvenance','claimScope') -Context 'T2 corroboration binding' -Errors $Errors
        Test-AllowedProperties -Object $corroborationBinding -Names @('recordRef','expectedProvenance','claimScope') -Context 'T2 corroboration binding' -Errors $Errors
        $corroborationId = [string]$corroborationBinding.recordRef
        if (-not $records.ContainsKey($corroborationId)) {
            Add-BlueprintError -Errors $Errors -Code 'T2_CORROBORATION_UNRESOLVED' -Message "$($record.recordId) corroboration does not resolve."
            continue
        }
        $corroboration = $records[$corroborationId]
        if ([string]$corroboration.recordType -cne 'evidence-record' -or
            [string]$corroboration.claimId -cne [string]$record.claimId -or
            [string]$corroborationBinding.claimScope -cne [string]$record.claimId -or
            [string]$corroborationBinding.expectedProvenance -cnotin @('T0', 'T1') -or
            [string]$corroboration.provenance -cne [string]$corroborationBinding.expectedProvenance) {
            Add-BlueprintError -Errors $Errors -Code 'T2_CORROBORATION_MISMATCH' -Message "$($record.recordId) lacks exact same-claim T0 or T1 corroboration matching its declared scope and expected provenance."
        }
    }

    $azureOperationValidity = [System.Collections.Generic.Dictionary[string,object]]::new([StringComparer]::Ordinal)
    foreach ($operation in @($records.Values | Where-Object { [string]$_.recordType -ceq 'azure-deployment-operation-record' })) {
        $azureValidation = Test-AzureDeploymentOperationSemantics -Operation $operation -RecordMap $records `
            -EvaluationTime $EvaluationTime -Errors $Errors
        $azureOperationValidity[[string]$operation.recordId] = $azureValidation
    }

    foreach ($record in @($records.Values | Where-Object {
        [string]$_.recordType -ceq 'readback-record' -and [string]$_.readbackKind -ceq 'AZURE_RESOURCE_STATE'
    })) {
        Test-RequiredProperties -Object $record -Names @(
            'schemaVersion','recordStage','status','readbackKind','readerToolRef','readIdentityRef',
            'tenantBoundaryRef','subscriptionBoundaryRef','targetEnvironmentRef','targetScopeRef',
            'resourceType','resourceIdRef','apiVersion','sourceCommit','desiredStateRevision',
            'deploymentOperationRef','deploymentOperationDigest','deploymentOperationId','readbackProjectionRef',
            'readbackProjectionDigest','expectedStateDigest','observedStateDigest','httpStatus',
            'responseBodyPresent','stateMatched','collectedAt','freshnessPolicyRef','freshnessPolicyDigest',
            'freshnessMaxAgeMinutes','freshnessBinding'
        ) -Context 'Azure resource-state readback' -Errors $Errors
        $azureOperation = Resolve-CanonicalRecord -RecordMap $records -Reference $record.deploymentOperationRef `
            -ExpectedTypes @('azure-deployment-operation-record') -Context 'Azure resource-state deployment operation' -Errors $Errors
        [int64]$azureFreshnessMaxAge = if (($record.freshnessMaxAgeMinutes -is [int] -or $record.freshnessMaxAgeMinutes -is [long]) -and [int64]$record.freshnessMaxAgeMinutes -gt 0) {
            [int64]$record.freshnessMaxAgeMinutes
        }
        else { 0 }
        $azureFreshnessPolicy = Test-SecurityFreshnessPolicyBinding -RecordMap $records `
            -Reference $record.freshnessPolicyRef -Digest $record.freshnessPolicyDigest `
            -ExpectedKind 'READBACK_FRESHNESS' -ExpectedMaximumAgeMinutes $azureFreshnessMaxAge `
            -ExpectedTenantBoundaryRef ([string]$record.tenantBoundaryRef) `
            -ExpectedTargetEnvironmentRef ([string]$record.targetEnvironmentRef) `
            -ExpectedRoleBindingRef ([string]$azureOperation.roleBindingRef) `
            -ExpectedRoleBindingDigest ([string]$azureOperation.roleBindingDigest) `
            -ExpectedRoleBindingReadbackRef ([string]$azureOperation.roleBindingReadbackRef) `
            -ExpectedRoleBindingReadbackDigest ([string]$azureOperation.roleBindingReadbackDigest) `
            -EvaluationTime $EvaluationTime -Errors $Errors
        [DateTimeOffset]$azureReadbackAt = [DateTimeOffset]::MinValue
        [DateTimeOffset]$azureFreshnessObservedAt = [DateTimeOffset]::MinValue
        [DateTimeOffset]$azureFreshnessAdmittedAt = [DateTimeOffset]::MinValue
        [DateTimeOffset]$azureOperationCompletedAt = [DateTimeOffset]::MinValue
        [DateTimeOffset]$azurePolicyApprovedAt = [DateTimeOffset]::MinValue
        $azureHttpStatusValid = ($record.httpStatus -is [int] -or $record.httpStatus -is [long]) -and
            [int64]$record.httpStatus -ge 200 -and [int64]$record.httpStatus -le 299
        $freshness = $record.freshnessBinding
        if ($freshness -is [pscustomobject]) {
            Test-RequiredProperties -Object $freshness -Names @(
                'observedAt','admittedAt','policyRef','maxAgeDays','dependencySnapshotRef',
                'dependencySnapshotDigest','dependencyStatus'
            ) -Context 'Azure resource-state freshness binding' -Errors $Errors
        }
        $azureTimesValid = [OperationsBlueprint.StrictRfc3339]::TryParse([string]$record.collectedAt, [ref]$azureReadbackAt) -and
            [OperationsBlueprint.StrictRfc3339]::TryParse([string]$freshness.observedAt, [ref]$azureFreshnessObservedAt) -and
            [OperationsBlueprint.StrictRfc3339]::TryParse([string]$freshness.admittedAt, [ref]$azureFreshnessAdmittedAt) -and
            $null -ne $azureOperation -and
            [OperationsBlueprint.StrictRfc3339]::TryParse([string]$azureOperation.completedAt, [ref]$azureOperationCompletedAt) -and
            $null -ne $azureFreshnessPolicy -and
            [OperationsBlueprint.StrictRfc3339]::TryParse([string]$azureFreshnessPolicy.approvedAt, [ref]$azurePolicyApprovedAt)
        [int64]$expectedFreshnessDays = if ($azureFreshnessMaxAge -gt 0) {
            [int64][Math]::Ceiling([double]$azureFreshnessMaxAge / 1440.0)
        }
        else { 0 }
        $azureOperationValidation = if ($null -ne $azureOperation -and
            $azureOperationValidity.ContainsKey([string]$azureOperation.recordId)) {
            $azureOperationValidity[[string]$azureOperation.recordId]
        }
        else { $null }
        $azureReaderRoleValid = $false
        if ($null -ne $azureOperationValidation -and $null -ne $azureOperationValidation.RoleClosure) {
            $closure = $azureOperationValidation.RoleClosure
            $readerAlias = [string]$record.readIdentityRef
            if ($closure.AliasMap.ContainsKey($readerAlias) -and $closure.RoleMap.ContainsKey($readerAlias) -and
                [string]$closure.RoleMap[$readerAlias] -ceq 'ROLE_CLOUD_RESOURCE_READBACK_OWNER') {
                $readerCanonicalId = [string]$closure.AliasMap[$readerAlias]
                $azureReaderRoleValid = $readerCanonicalId -cmatch '^private://canonical-principals/sha256/[0-9a-f]{64}$' -and
                    @($azureOperationValidation.CanonicalPrincipalIds) -cnotcontains $readerCanonicalId
            }
        }
        if (-not $azureReaderRoleValid) {
            Add-BlueprintError -Errors $Errors -Code 'AZURE_RESOURCE_READBACK_ROLE_BINDING_INVALID' -Message 'Azure resource readback must use a distinct canonical principal bound to ROLE_CLOUD_RESOURCE_READBACK_OWNER.'
        }
        if ([string]$record.schemaVersion -cne '1.0.0' -or
            [string]$record.recordStage -cne 'AZURE_RESOURCE_STATE_READBACK' -or
            [string]$record.status -cne 'VERIFIED' -or
            [string]$record.readerToolRef -cne 'azure-resource-manager-readback' -or
            @('readIdentityRef','tenantBoundaryRef','subscriptionBoundaryRef','targetEnvironmentRef','targetScopeRef','resourceIdRef','readbackProjectionRef' | Where-Object { [string]$record.$_ -cnotmatch '^private://' }).Count -gt 0 -or
            -not (Test-NonBlankString $record.resourceType) -or -not (Test-NonBlankString $record.apiVersion) -or
            [string]$record.sourceCommit -cnotmatch '^[0-9a-f]{40}([0-9a-f]{24})?$' -or
            @('desiredStateRevision','deploymentOperationDigest','readbackProjectionDigest','expectedStateDigest','observedStateDigest','freshnessPolicyDigest' | Where-Object { -not (Test-Sha256Token $record.$_) }).Count -gt 0 -or
            [string]$record.expectedStateDigest -cne [string]$record.observedStateDigest -or
            -not $azureHttpStatusValid -or $record.responseBodyPresent -ne $true -or $record.stateMatched -ne $true -or
            $azureFreshnessMaxAge -le 0 -or $freshness -isnot [pscustomobject] -or
            $null -eq $azureOperation -or $null -eq $azureFreshnessPolicy -or -not $azureReaderRoleValid -or
            ($null -ne $azureOperation -and
                (-not $azureOperationValidity.ContainsKey([string]$azureOperation.recordId) -or
                 -not [bool]$azureOperationValidity[[string]$azureOperation.recordId].Valid)) -or
            ($null -ne $azureOperation -and
                ([string]$record.deploymentOperationDigest -cne [string]$azureOperation.contentDigest -or
                 [string]$record.deploymentOperationId -cne [string]$azureOperation.operationId -or
                 [string]$record.tenantBoundaryRef -cne [string]$azureOperation.tenantBoundaryRef -or
                 [string]$record.subscriptionBoundaryRef -cne [string]$azureOperation.subscriptionBoundaryRef -or
                 [string]$record.targetEnvironmentRef -cne [string]$azureOperation.targetEnvironmentRef -or
                 [string]$record.targetScopeRef -cne [string]$azureOperation.targetScopeRef -or
                 [string]$record.resourceType -cne [string]$azureOperation.resourceType -or
                 [string]$record.resourceIdRef -cne [string]$azureOperation.resourceIdRef -or
                 [string]$record.apiVersion -cne [string]$azureOperation.apiVersion -or
                 [string]$record.sourceCommit -cne [string]$azureOperation.sourceCommit -or
                 [string]$record.desiredStateRevision -cne [string]$azureOperation.desiredStateRevision -or
                 [string]$record.readbackProjectionRef -cne [string]$azureOperation.expectedStateProjectionRef -or
                 [string]$record.readbackProjectionDigest -cne [string]$azureOperation.expectedStateProjectionDigest -or
                 [string]$record.expectedStateDigest -cne [string]$azureOperation.expectedStateDigest -or
                 [string]$record.readIdentityRef -ceq [string]$azureOperation.writeIdentityRef -or
                 [string]$record.readIdentityRef -ceq [string]$azureOperation.applyOperatorIdentityRef)) -or
            [string]$freshness.policyRef -cne [string]$record.freshnessPolicyRef -or
            [string]$freshness.dependencySnapshotRef -cne [string]$record.deploymentOperationRef -or
            [string]$freshness.dependencySnapshotDigest -cne [string]$record.deploymentOperationDigest -or
            [string]$freshness.dependencyStatus -cne 'MATCH' -or
            ($freshness.maxAgeDays -isnot [int] -and $freshness.maxAgeDays -isnot [long]) -or
            [int64]$freshness.maxAgeDays -ne $expectedFreshnessDays -or
            -not $azureTimesValid -or
            $azureReadbackAt -ne $azureFreshnessObservedAt -or
            $azureOperationCompletedAt -gt $azureReadbackAt -or
            $azurePolicyApprovedAt -gt $azureReadbackAt -or
            $azureFreshnessAdmittedAt -lt $azureReadbackAt -or $azureFreshnessAdmittedAt -gt $EvaluationTime -or
            $azureReadbackAt -gt $EvaluationTime -or
            ($EvaluationTime - $azureReadbackAt).TotalMinutes -gt $azureFreshnessMaxAge) {
            Add-BlueprintError -Errors $Errors -Code 'AZURE_RESOURCE_STATE_READBACK_INVALID' -Message 'Azure resource-state readback must be a fresh authenticated independent 2xx observation with MATCH dependency status and exact deployment, policy, tenant, subscription, environment, operation, resource, projection, revision, and state-digest closure.'
        }
    }

    foreach ($record in @($records.Values | Where-Object { [string]$_.recordType -ceq 'business-impact-record' })) {
        Test-BusinessImpactRecordSemantics -Record $record -RecordMap $records -EvaluationTime $EvaluationTime -Errors $Errors
    }

    foreach ($record in @($records.Values | Where-Object { [string]$_.recordType -ceq 'atmos-stack-render-record' })) {
        Test-AtmosStackRenderRecordSemantics -Record $record -EvaluationTime $EvaluationTime -Errors $Errors
    }

    return ,$records
}

function Test-CanonicalRecordPointerCoverage {
    param(
        [AllowNull()]$Record,
        [AllowNull()]$Pointer
    )

    if ($null -eq $Record -or -not (Test-StrictJsonPointerSyntax -Pointer $Pointer)) { return $false }
    $inventoryContainsPointer = @($Record.pointers) -ccontains [string]$Pointer
    if (-not $inventoryContainsPointer -and $null -ne $Record.PSObject.Properties['portableProjectionRecord']) {
        foreach ($projectedPointer in @($Record.pointers)) {
            if ($projectedPointer -is [string] -and
                ([string]$Pointer).StartsWith(([string]$projectedPointer + '/'), [System.StringComparison]::Ordinal)) {
                $inventoryContainsPointer = $true
                break
            }
        }
    }
    return $inventoryContainsPointer -and (Test-JsonPointerExists -Document $Record.payload -Pointer ([string]$Pointer))
}

function Resolve-CanonicalRecord {
    param(
        [Parameter(Mandatory = $true)]$RecordMap,
        [Parameter(Mandatory = $true)][AllowNull()]$Reference,
        [Parameter(Mandatory = $true)][string[]]$ExpectedTypes,
        [Parameter(Mandatory = $true)][string]$Context,
        [Parameter(Mandatory = $true)][AllowEmptyCollection()][System.Collections.ArrayList]$Errors
    )

    if ($Reference -isnot [string] -or [string]::IsNullOrWhiteSpace([string]$Reference)) {
        Add-BlueprintError -Errors $Errors -Code 'INVALID_RECORD_REF' -Message "$Context has a null or blank record reference."
        return $null
    }
    $parts = ([string]$Reference).Split('#', 2)
    $recordId = $parts[0]
    if (-not $RecordMap.ContainsKey($recordId)) {
        Add-BlueprintError -Errors $Errors -Code 'UNRESOLVED_RECORD_REF' -Message "$Context reference $Reference does not resolve in the typed canonical index."
        return $null
    }
    $record = $RecordMap[$recordId]
    if ([string]$record.recordType -cnotin $ExpectedTypes) {
        Add-BlueprintError -Errors $Errors -Code 'RECORD_TYPE_MISMATCH' -Message "$Context reference $Reference resolves to $($record.recordType), not $($ExpectedTypes -join ' or ')."
    }
    if ($parts.Count -eq 2) {
        $pointer = $parts[1]
        if (-not (Test-CanonicalRecordPointerCoverage -Record $record -Pointer $pointer)) {
            Add-BlueprintError -Errors $Errors -Code 'UNRESOLVED_RECORD_POINTER' -Message "$Context pointer $Reference is absent from the record pointer inventory."
        }
    }
    return $record
}

function ConvertFrom-StrictJsonPointerToken {
    param([Parameter(Mandatory = $true)][AllowEmptyString()][string]$EncodedToken)

    if ($EncodedToken -cmatch '~(?![01])') {
        return [pscustomobject]@{ Valid = $false; Value = '' }
    }
    return [pscustomobject]@{
        Valid = $true
        Value = $EncodedToken.Replace('~1', '/').Replace('~0', '~')
    }
}

function Test-StrictJsonPointerSyntax {
    param([AllowNull()]$Pointer)

    if ($Pointer -isnot [string] -or -not ([string]$Pointer).StartsWith('/', [System.StringComparison]::Ordinal)) {
        return $false
    }
    foreach ($encodedToken in ([string]$Pointer).Substring(1).Split('/')) {
        if (-not (ConvertFrom-StrictJsonPointerToken -EncodedToken $encodedToken).Valid) { return $false }
    }
    return $true
}

function Test-JsonPointerExists {
    param($Document, [string]$Pointer)

    if ([string]::IsNullOrEmpty($Pointer)) { return $true }
    if (-not (Test-StrictJsonPointerSyntax -Pointer $Pointer)) { return $false }
    $current = $Document
    foreach ($encodedToken in $Pointer.Substring(1).Split('/')) {
        $tokenResult = ConvertFrom-StrictJsonPointerToken -EncodedToken $encodedToken
        if (-not $tokenResult.Valid) { return $false }
        $token = [string]$tokenResult.Value
        if ($current -is [System.Collections.IList] -and $current -isnot [string]) {
            [int]$index = -1
            if ($token -cnotmatch '^(?:0|[1-9][0-9]*)$' -or
                -not [int]::TryParse($token, [Globalization.NumberStyles]::None, [Globalization.CultureInfo]::InvariantCulture, [ref]$index) -or
                $index -lt 0 -or $index -ge @($current).Count) { return $false }
            $current = @($current)[$index]
        }
        elseif ($current -is [pscustomobject]) {
            $property = @($current.PSObject.Properties | Where-Object { [string]$_.Name -ceq $token })
            if ($property.Count -ne 1) { return $false }
            $current = $property[0].Value
        }
        else { return $false }
    }
    return $true
}

function Get-JsonPointerValue {
    param($Document, [string]$Pointer, [Parameter(Mandatory = $true)][ref]$Found)

    $Found.Value = $false
    if ([string]::IsNullOrEmpty($Pointer)) { $Found.Value = $true; return $Document }
    if (-not (Test-StrictJsonPointerSyntax -Pointer $Pointer)) { return $null }
    $current = $Document
    foreach ($encodedToken in $Pointer.Substring(1).Split('/')) {
        $tokenResult = ConvertFrom-StrictJsonPointerToken -EncodedToken $encodedToken
        if (-not $tokenResult.Valid) { return $null }
        $token = [string]$tokenResult.Value
        if ($current -is [System.Collections.IList] -and $current -isnot [string]) {
            [int]$index = -1
            if ($token -cnotmatch '^(?:0|[1-9][0-9]*)$' -or
                -not [int]::TryParse($token, [Globalization.NumberStyles]::None, [Globalization.CultureInfo]::InvariantCulture, [ref]$index) -or
                $index -lt 0 -or $index -ge @($current).Count) { return $null }
            $current = @($current)[$index]
        }
        elseif ($current -is [pscustomobject]) {
            $property = @($current.PSObject.Properties | Where-Object { [string]$_.Name -ceq $token })
            if ($property.Count -ne 1) { return $null }
            $current = $property[0].Value
        }
        else { return $null }
    }
    $Found.Value = $true
    return $current
}

function Test-LeadershipDependencySnapshot {
    param(
        [AllowNull()]$Snapshot,
        [Parameter(Mandatory = $true)][string]$Context,
        [Parameter(Mandatory = $true)][AllowEmptyCollection()][System.Collections.ArrayList]$Errors
    )

    $requiredFields = @(
        'windowsBuild', 'biosVersion', 'driverPackVersion', 'corporateImageVersion',
        'securityAgentSetDigest', 'conditionSetDigest', 'testPackVersion'
    )
    if ($Snapshot -isnot [pscustomobject]) {
        Add-BlueprintError -Errors $Errors -Code 'FRESHNESS_DEPENDENCY_SNAPSHOT_INVALID' -Message "$Context requires a structured dependency snapshot."
        return
    }
    Test-RequiredProperties -Object $Snapshot -Names $requiredFields -Context "$Context dependency snapshot" -Errors $Errors
    Test-AllowedProperties -Object $Snapshot -Names $requiredFields -Context "$Context dependency snapshot" -Errors $Errors
    foreach ($field in $requiredFields) {
        if (-not (Test-ValuePresent $Snapshot.$field)) {
            Add-BlueprintError -Errors $Errors -Code 'FRESHNESS_DEPENDENCY_SNAPSHOT_INVALID' -Message "$Context dependency snapshot lacks $field."
        }
    }
    foreach ($digestField in @('securityAgentSetDigest', 'conditionSetDigest')) {
        if (-not (Test-Sha256Token $Snapshot.$digestField)) {
            Add-BlueprintError -Errors $Errors -Code 'FRESHNESS_DEPENDENCY_SNAPSHOT_INVALID' -Message "$Context dependency snapshot $digestField must be SHA-256."
        }
    }
}

function Test-LeadershipFreshnessBinding {
    param(
        [Parameter(Mandatory = $true)]$Link,
        [Parameter(Mandatory = $true)][string]$LinkName,
        [Parameter(Mandatory = $true)]$RecordMap,
        [Parameter(Mandatory = $true)][string]$ExpectedPolicyRef,
        [Parameter(Mandatory = $true)][string]$ExpectedPolicyDigest,
        [Parameter(Mandatory = $true)][AllowNull()][AllowEmptyCollection()][object[]]$SourceRecords,
        [Parameter(Mandatory = $true)][DateTimeOffset]$EvaluationTime,
        [Parameter(Mandatory = $true)][DateTimeOffset]$LineageGeneratedAt,
        [AllowNull()][string]$ObservationWindow,
        [Parameter(Mandatory = $true)][AllowEmptyCollection()][System.Collections.ArrayList]$Errors
    )

    $freshness = $Link.freshness
    $freshnessFields = @(
        'status', 'observedAt', 'admittedAt', 'evaluatedAt', 'maxAgeDays', 'policyRef',
        'dependencySnapshotRef', 'dependencySnapshot', 'dependencySnapshotDigest', 'dependencyStatus'
    )
    if ($freshness -isnot [pscustomobject]) {
        Add-BlueprintError -Errors $Errors -Code 'LEADERSHIP_FRESHNESS_BINDING_REQUIRED' -Message "$LinkName requires structured freshness evidence; a caller-supplied label is insufficient."
        return
    }
    Test-RequiredProperties -Object $freshness -Names $freshnessFields -Context "$LinkName freshness" -Errors $Errors
    Test-AllowedProperties -Object $freshness -Names $freshnessFields -Context "$LinkName freshness" -Errors $Errors
    Test-LeadershipDependencySnapshot -Snapshot $freshness.dependencySnapshot -Context $LinkName -Errors $Errors

    if ([string]$freshness.status -cne 'CURRENT') {
        Add-BlueprintError -Errors $Errors -Code 'STALE_LEADERSHIP_LINK' -Message "$LinkName is not CURRENT."
    }
    if ([string]$freshness.dependencyStatus -cne 'MATCH') {
        Add-BlueprintError -Errors $Errors -Code 'FRESHNESS_DEPENDENCY_MISMATCH' -Message "$LinkName dependency state is not MATCH."
    }
    $calculatedSnapshotDigest = if ($freshness.dependencySnapshot -is [pscustomobject]) {
        Get-CanonicalPayloadDigest -Payload $freshness.dependencySnapshot
    }
    else { '' }
    if (-not (Test-Sha256Token $freshness.dependencySnapshotDigest) -or
        [string]$freshness.dependencySnapshotDigest -cne [string]$calculatedSnapshotDigest) {
        Add-BlueprintError -Errors $Errors -Code 'FRESHNESS_DEPENDENCY_DIGEST_MISMATCH' -Message "$LinkName dependency snapshot does not match its SHA-256 digest."
    }

    [DateTimeOffset]$observedAt = [DateTimeOffset]::MinValue
    [DateTimeOffset]$admittedAt = [DateTimeOffset]::MinValue
    [DateTimeOffset]$evaluatedAt = [DateTimeOffset]::MinValue
    $timesValid = [OperationsBlueprint.StrictRfc3339]::TryParse([string]$freshness.observedAt, [ref]$observedAt) -and
        [OperationsBlueprint.StrictRfc3339]::TryParse([string]$freshness.admittedAt, [ref]$admittedAt) -and
        [OperationsBlueprint.StrictRfc3339]::TryParse([string]$freshness.evaluatedAt, [ref]$evaluatedAt)
    if (-not $timesValid -or $observedAt -gt $admittedAt -or $admittedAt -gt $evaluatedAt -or
        $evaluatedAt -ne $LineageGeneratedAt -or $evaluatedAt -gt $EvaluationTime) {
        Add-BlueprintError -Errors $Errors -Code 'FRESHNESS_CHRONOLOGY_INVALID' -Message "$LinkName requires observation <= admission <= chain generation <= evaluation time."
    }
    $maxAgeValid = ($freshness.maxAgeDays -is [int] -or $freshness.maxAgeDays -is [long]) -and
        [int64]$freshness.maxAgeDays -ge 1 -and [int64]$freshness.maxAgeDays -le 3650
    if (-not $maxAgeValid) {
        Add-BlueprintError -Errors $Errors -Code 'FRESHNESS_MAX_AGE_INVALID' -Message "$LinkName requires a bounded integer maxAgeDays from 1 through 3650."
    }
    elseif ($timesValid -and ($EvaluationTime - $observedAt).TotalDays -gt [int64]$freshness.maxAgeDays) {
        Add-BlueprintError -Errors $Errors -Code 'STALE_LEADERSHIP_LINK' -Message "$LinkName observation exceeds its frozen maximum age."
    }

    if (-not [string]::IsNullOrWhiteSpace($ObservationWindow) -and $timesValid -and
        [string]$ObservationWindow -cmatch '^\d{4}-\d{2}-\d{2}/(\d{4}-\d{2}-\d{2})$') {
        [DateTimeOffset]$windowEnd = [DateTimeOffset]::MinValue
        if (-not [OperationsBlueprint.StrictIsoDate]::TryParse([string]$Matches[1], [ref]$windowEnd) -or
            $observedAt.UtcDateTime.Date -ne $windowEnd.UtcDateTime.Date) {
            Add-BlueprintError -Errors $Errors -Code 'FRESHNESS_OBSERVATION_WINDOW_MISMATCH' -Message "$LinkName observedAt must be the end date of its declared observation window."
        }
    }

    $policyRecord = Resolve-CanonicalRecord -RecordMap $RecordMap -Reference $freshness.policyRef -ExpectedTypes @('threshold-policy') -Context "$LinkName freshness policy" -Errors $Errors
    if ($null -ne $policyRecord) {
        $policyParts = ([string]$freshness.policyRef).Split('#', 2)
        if ([string]$policyParts[0] -cne [string]$ExpectedPolicyRef -or
            [string]$policyRecord.recordId -cne [string]$ExpectedPolicyRef -or
            [string]$policyRecord.contentDigest -cne [string]$ExpectedPolicyDigest) {
            Add-BlueprintError -Errors $Errors -Code 'FRESHNESS_POLICY_AUTHORITY_MISMATCH' -Message "$LinkName freshness policy is not a branch of the exact threshold policy frozen by the Phase 0 manifest and test plan."
        }
        $policyFound = $false
        $policyValue = if ($policyParts.Count -eq 2) { Get-JsonPointerValue -Document $policyRecord.payload -Pointer $policyParts[1] -Found ([ref]$policyFound) } else { $null }
        $requiredDependencyFields = @(
            'windowsBuild', 'biosVersion', 'driverPackVersion', 'corporateImageVersion',
            'securityAgentSetDigest', 'conditionSetDigest', 'testPackVersion'
        )
        if (-not $policyFound -or $policyValue -isnot [pscustomobject]) {
            Add-BlueprintError -Errors $Errors -Code 'FRESHNESS_POLICY_BINDING_MISMATCH' -Message "$LinkName freshness policy pointer does not resolve to a structured policy."
        }
        else {
            Test-RequiredProperties -Object $policyValue -Names @('maxAgeDays', 'requiredDependencyFields') -Context "$LinkName freshness policy" -Errors $Errors
            Test-AllowedProperties -Object $policyValue -Names @('maxAgeDays', 'requiredDependencyFields') -Context "$LinkName freshness policy" -Errors $Errors
            if (($policyValue.maxAgeDays -isnot [int] -and $policyValue.maxAgeDays -isnot [long]) -or
                [string]$policyValue.maxAgeDays -cne [string]$freshness.maxAgeDays -or
                @($policyValue.requiredDependencyFields).Count -ne $requiredDependencyFields.Count) {
                Add-BlueprintError -Errors $Errors -Code 'FRESHNESS_POLICY_BINDING_MISMATCH' -Message "$LinkName maximum age or dependency-field policy differs from the frozen threshold record."
            }
            foreach ($field in $requiredDependencyFields) {
                if (@($policyValue.requiredDependencyFields) -cnotcontains $field) {
                    Add-BlueprintError -Errors $Errors -Code 'FRESHNESS_POLICY_BINDING_MISMATCH' -Message "$LinkName freshness policy omits dependency $field."
                }
            }
        }
    }

    $baselineRecord = Resolve-CanonicalRecord -RecordMap $RecordMap -Reference $freshness.dependencySnapshotRef -ExpectedTypes @('platform-baseline-record') -Context "$LinkName dependency baseline" -Errors $Errors
    if ($null -ne $baselineRecord) {
        $baselineParts = ([string]$freshness.dependencySnapshotRef).Split('#', 2)
        $snapshotFound = $false
        $baselineSnapshot = if ($baselineParts.Count -eq 2) { Get-JsonPointerValue -Document $baselineRecord.payload -Pointer $baselineParts[1] -Found ([ref]$snapshotFound) } else { $null }
        $linkSnapshotJson = ConvertTo-DeterministicJsonText -Value (ConvertTo-CanonicalJsonValue $freshness.dependencySnapshot)
        $baselineSnapshotJson = ConvertTo-DeterministicJsonText -Value (ConvertTo-CanonicalJsonValue $baselineSnapshot)
        if (-not $snapshotFound -or [string]$baselineRecord.dependencySnapshotDigest -cne [string]$freshness.dependencySnapshotDigest -or
            [string]$baselineRecord.dependencyStatus -cne 'CURRENT' -or $baselineSnapshotJson -cne $linkSnapshotJson) {
            Add-BlueprintError -Errors $Errors -Code 'FRESHNESS_DEPENDENCY_MISMATCH' -Message "$LinkName dependency snapshot differs from the current canonical platform baseline."
        }
    }

    $sources = @($SourceRecords | Where-Object { $null -ne $_ })
    if ($sources.Count -eq 0) {
        Add-BlueprintError -Errors $Errors -Code 'FRESHNESS_SOURCE_RECORD_REQUIRED' -Message "$LinkName freshness requires at least one canonical source record."
        return
    }
    [DateTimeOffset]$oldestSourceObservation = [DateTimeOffset]::MaxValue
    [DateTimeOffset]$latestSourceAdmission = [DateTimeOffset]::MinValue
    foreach ($source in $sources) {
        $binding = $source.freshnessBinding
        $usesPortableProjectionFreshness = $false
        if ($binding -isnot [pscustomobject] -and [string]$source.recordType -ceq 'verdict-record' -and
            $source.portableProjectionRecord -is [pscustomobject] -and
            $source.portableProjectionRecord.freshnessBinding -is [pscustomobject]) {
            # Portable verdicts have no operations-only freshness field in the
            # frozen source contract. Their projection freshness is separately
            # schema-validated, attested, and digest-bound to the full source.
            $binding = $source.portableProjectionRecord.freshnessBinding
            $usesPortableProjectionFreshness = $true
        }
        $bindingFields = @(
            'observedAt', 'admittedAt', 'policyRef', 'maxAgeDays', 'dependencySnapshotRef',
            'dependencySnapshotDigest', 'dependencyStatus'
        )
        if ($binding -isnot [pscustomobject]) {
            Add-BlueprintError -Errors $Errors -Code 'SOURCE_FRESHNESS_BINDING_REQUIRED' -Message "$LinkName source $($source.recordId) lacks structured freshness evidence."
            continue
        }
        Test-RequiredProperties -Object $binding -Names $bindingFields -Context "$LinkName source freshness" -Errors $Errors
        Test-AllowedProperties -Object $binding -Names $bindingFields -Context "$LinkName source freshness" -Errors $Errors
        if ([string]$binding.policyRef -cne [string]$freshness.policyRef -or
            [string]$binding.maxAgeDays -cne [string]$freshness.maxAgeDays -or
            [string]$binding.dependencySnapshotRef -cne [string]$freshness.dependencySnapshotRef -or
            [string]$binding.dependencySnapshotDigest -cne [string]$freshness.dependencySnapshotDigest -or
            [string]$binding.dependencyStatus -cne 'MATCH') {
            Add-BlueprintError -Errors $Errors -Code 'SOURCE_FRESHNESS_BINDING_MISMATCH' -Message "$LinkName source $($source.recordId) differs from the frozen age or dependency binding."
        }
        [DateTimeOffset]$sourceObservedAt = [DateTimeOffset]::MinValue
        [DateTimeOffset]$sourceAdmittedAt = [DateTimeOffset]::MinValue
        $sourceTimesValid = [OperationsBlueprint.StrictRfc3339]::TryParse([string]$binding.observedAt, [ref]$sourceObservedAt) -and
            [OperationsBlueprint.StrictRfc3339]::TryParse([string]$binding.admittedAt, [ref]$sourceAdmittedAt)
        if (-not $sourceTimesValid -or $sourceObservedAt -gt $sourceAdmittedAt -or $sourceAdmittedAt -gt $evaluatedAt -or
            ($maxAgeValid -and ($EvaluationTime - $sourceObservedAt).TotalDays -gt [int64]$freshness.maxAgeDays)) {
            Add-BlueprintError -Errors $Errors -Code 'SOURCE_FRESHNESS_CHRONOLOGY_INVALID' -Message "$LinkName source $($source.recordId) is future, stale, or admitted before observation."
        }
        elseif ($sourceObservedAt -lt $oldestSourceObservation) { $oldestSourceObservation = $sourceObservedAt }
        if ($sourceTimesValid -and $sourceAdmittedAt -gt $latestSourceAdmission) { $latestSourceAdmission = $sourceAdmittedAt }

        if ($usesPortableProjectionFreshness -and [string]$source.recordType -ceq 'verdict-record') {
            [DateTimeOffset]$portableVerdictImmutableAt = [DateTimeOffset]::MinValue
            if (-not [OperationsBlueprint.StrictRfc3339]::TryParse([string]$source.immutableAt, [ref]$portableVerdictImmutableAt) -or
                -not $sourceTimesValid -or $portableVerdictImmutableAt -ne $sourceObservedAt) {
                Add-BlueprintError -Errors $Errors -Code 'PORTABLE_VERDICT_FRESHNESS_CROSSWALK_INVALID' -Message "$LinkName portable verdict immutable time does not equal its authenticated projection observation time."
            }
        }

        if ([string]$source.recordType -ceq 'evidence-record') {
            [DateTimeOffset]$portableTimestamp = [DateTimeOffset]::MinValue
            [DateTimeOffset]$portableAdmittedAt = [DateTimeOffset]::MinValue
            $portableFreshnessValid = $source.admission -is [pscustomobject] -and
                [string]$source.admission.mode -cin @('fresh','compatibility-cache') -and
                [OperationsBlueprint.StrictRfc3339]::TryParse([string]$source.timestamp, [ref]$portableTimestamp) -and
                [OperationsBlueprint.StrictRfc3339]::TryParse([string]$source.admission.admittedAt, [ref]$portableAdmittedAt) -and
                [string]$source.timestamp -ceq [string]$binding.observedAt -and
                [string]$source.admission.admittedAt -ceq [string]$binding.admittedAt -and
                $portableTimestamp -le $portableAdmittedAt -and
                ($null -eq $source.PSObject.Properties['stale'] -or
                 ($source.stale -is [pscustomobject] -and $source.stale.isStale -eq $false))
            if (-not $portableFreshnessValid) {
                Add-BlueprintError -Errors $Errors -Code 'PORTABLE_EVIDENCE_FRESHNESS_CROSSWALK_INVALID' -Message "$LinkName portable evidence timestamp, admission, stale state, and governed operations freshness binding do not agree exactly."
            }
        }
    }
    if ($timesValid -and ($oldestSourceObservation -ne $observedAt -or $latestSourceAdmission -ne $admittedAt)) {
        Add-BlueprintError -Errors $Errors -Code 'FRESHNESS_SOURCE_SUMMARY_MISMATCH' -Message "$LinkName must report the oldest source observation and latest source admission exactly."
    }
}

function Get-ExpectedRecommendation {
    param(
        [Parameter(Mandatory = $true)]$VerdictPayload,
        [Parameter(Mandatory = $true)]$PersonaVerdict,
        [Parameter(Mandatory = $true)][string]$VerdictRef
    )

    $riskAcceptedInconclusive = [string]$VerdictPayload.fleetVerdict -ceq 'INCONCLUSIVE' -and
        [string]$VerdictPayload.deadlineDecision.deadlineStatus -ceq 'deadline-reached' -and
        [string]$VerdictPayload.deadlineDecision.evidenceState -ceq 'inconclusive' -and
        [string]$VerdictPayload.deadlineDecision.decision -ceq 'risk-accepted-expiring-exception'
    $fleetPermits = (([string]$VerdictPayload.fleetVerdict -cin @('QUALIFY', 'QUALIFY_WITH_CONDITIONS')) -or $riskAcceptedInconclusive) -and
        [string]$VerdictPayload.fleetDeploymentDisposition -cin @('APPROVED', 'APPROVED_WITH_CONDITIONS')
    $personaPermits = [string]$PersonaVerdict.verdict -cin @('QUALIFY', 'QUALIFY_WITH_CONDITIONS') -and
        [string]$PersonaVerdict.assignmentDisposition -cin @('APPROVED', 'APPROVED_WITH_CONDITIONS')
    $procurementPermits = [string]$VerdictPayload.procurementDisposition -cin @('APPROVED', 'APPROVED_WITH_CONDITIONS')
    $quantityScope = [string]$VerdictPayload.procurementEnvelope.quantityScope
    $persona = [string]$PersonaVerdict.persona
    if (-not $fleetPermits -or -not $personaPermits -or -not $procurementPermits) {
        return [pscustomobject]@{
            Action = 'DO_NOT_BUY'
            Statement = "DO_NOT_BUY: The issued fleet, persona, or procurement disposition blocks purchase for persona $persona."
        }
    }
    $conditional = $riskAcceptedInconclusive -or [bool]$PersonaVerdict.conflictsWithFleetConditions -or
        [string]$VerdictPayload.fleetVerdict -ceq 'QUALIFY_WITH_CONDITIONS' -or
        [string]$PersonaVerdict.verdict -ceq 'QUALIFY_WITH_CONDITIONS' -or
        [string]$VerdictPayload.procurementDisposition -ceq 'APPROVED_WITH_CONDITIONS'
    if ($conditional) {
        [string[]]$conditionIds = @()
        $conditionValues = @(
            @($VerdictPayload.conditions | ForEach-Object { [string]$_.conditionId }) +
            @($PersonaVerdict.conditionRefs | ForEach-Object { [string]$_ }) |
                Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_) } |
                Select-Object -Unique
        )
        if ($conditionValues.Count -gt 0) {
            $conditionIds = [string[]]$conditionValues
            [Array]::Sort($conditionIds, [System.StringComparer]::Ordinal)
        }
        return [pscustomobject]@{
            Action = 'BUY_WITH_CONDITIONS'
            Statement = "BUY_WITH_CONDITIONS: Approve $quantityScope within $VerdictRef#/procurementEnvelope for persona $persona, subject to conditions $($conditionIds -join ',')."
        }
    }
    return [pscustomobject]@{
        Action = 'BUY'
        Statement = "BUY: Approve $quantityScope within $VerdictRef#/procurementEnvelope for persona $persona."
    }
}

function Test-CommercialBasis {
    param(
        [Parameter(Mandatory = $true)]$Chain,
        [Parameter(Mandatory = $true)]$RecordMap,
        [Parameter(Mandatory = $true)][DateTimeOffset]$EvaluationTime,
        [Parameter(Mandatory = $true)][AllowEmptyCollection()][System.Collections.ArrayList]$Errors
    )

    $candidateQuote = Resolve-CanonicalRecord -RecordMap $RecordMap -Reference $Chain.businessEffect.candidateQuoteRef -ExpectedTypes @('commercial-quote-record') -Context 'candidate quote' -Errors $Errors
    $controlQuote = Resolve-CanonicalRecord -RecordMap $RecordMap -Reference $Chain.businessEffect.controlQuoteRef -ExpectedTypes @('commercial-quote-record') -Context 'control quote' -Errors $Errors
    if ([string]$Chain.businessEffect.currency -cnotmatch '^[A-Z]{3}$' -or
        ($Chain.businessEffect.quantity -isnot [int] -and $Chain.businessEffect.quantity -isnot [long] -and $Chain.businessEffect.quantity -isnot [double] -and $Chain.businessEffect.quantity -isnot [decimal]) -or
        [decimal]$Chain.businessEffect.quantity -le 0) {
        Add-BlueprintError -Errors $Errors -Code 'COMMERCIAL_BASIS_INVALID' -Message 'Commercial basis requires an ISO currency and positive numeric quantity.'
    }
    [DateTimeOffset]$quoteValidUntil = [DateTimeOffset]::MinValue
    if (-not [OperationsBlueprint.StrictRfc3339]::TryParse([string]$Chain.businessEffect.quoteValidUntil, [ref]$quoteValidUntil) -or $quoteValidUntil -le $EvaluationTime) {
        Add-BlueprintError -Errors $Errors -Code 'COMMERCIAL_QUOTE_EXPIRED_OR_INVALID' -Message 'Leadership buying input requires dated candidate and incumbent quotes valid at evaluation time.'
    }
    foreach ($quoteRecord in @($candidateQuote, $controlQuote)) {
        if ($null -eq $quoteRecord) { continue }
        Test-RequiredProperties -Object $quoteRecord -Names @(
            'subjectRef', 'configurationEnvelopePointer', 'currency', 'quantity',
            'unitPrice', 'totalPrice', 'quotedAt', 'validUntil'
        ) -Context "quote $($quoteRecord.recordId)" -Errors $Errors
        if ([string]$quoteRecord.currency -cne [string]$Chain.businessEffect.currency -or
            [string]$quoteRecord.quantity -cne [string]$Chain.businessEffect.quantity) {
            Add-BlueprintError -Errors $Errors -Code 'COMMERCIAL_QUOTE_BINDING_MISMATCH' -Message 'Candidate/incumbent quote currency or quantity differs from the buying decision.'
        }
        [DateTimeOffset]$quotedAt = [DateTimeOffset]::MinValue
        [DateTimeOffset]$recordValidUntil = [DateTimeOffset]::MinValue
        if (-not [OperationsBlueprint.StrictRfc3339]::TryParse([string]$quoteRecord.quotedAt, [ref]$quotedAt) -or
            $quotedAt -gt $EvaluationTime -or
            -not [OperationsBlueprint.StrictRfc3339]::TryParse([string]$quoteRecord.validUntil, [ref]$recordValidUntil) -or
            $recordValidUntil -le $EvaluationTime -or
            ($quoteRecord.unitPrice -isnot [int] -and $quoteRecord.unitPrice -isnot [long] -and $quoteRecord.unitPrice -isnot [double] -and $quoteRecord.unitPrice -isnot [decimal]) -or
            ($quoteRecord.totalPrice -isnot [int] -and $quoteRecord.totalPrice -isnot [long] -and $quoteRecord.totalPrice -isnot [double] -and $quoteRecord.totalPrice -isnot [decimal]) -or
            [Math]::Abs([double]$quoteRecord.totalPrice - ([double]$quoteRecord.unitPrice * [double]$quoteRecord.quantity)) -gt 0.005) {
            Add-BlueprintError -Errors $Errors -Code 'COMMERCIAL_QUOTE_ARITHMETIC_INVALID' -Message "$($quoteRecord.recordId) lacks a dated numeric unit/total price consistent with quantity."
        }
    }
    if ($null -ne $candidateQuote -and
        ([string]$candidateQuote.subjectRef -cne [string]$Chain.candidateComparison.candidateRef -or
         [string]$candidateQuote.configurationEnvelopePointer -cne [string]$Chain.recommendation.procurementEnvelopePointer)) {
        Add-BlueprintError -Errors $Errors -Code 'COMMERCIAL_QUOTE_SUBJECT_MISMATCH' -Message 'Candidate quote does not bind the compared candidate and approved procurement envelope.'
    }
    if ($null -ne $controlQuote -and
        ([string]$controlQuote.subjectRef -cne [string]$Chain.candidateComparison.incumbentControlRef -or
         [string]$controlQuote.configurationEnvelopePointer -cne [string]$Chain.candidateComparison.incumbentControlRef)) {
        Add-BlueprintError -Errors $Errors -Code 'COMMERCIAL_QUOTE_SUBJECT_MISMATCH' -Message 'Incumbent quote does not bind the compared incumbent configuration projection.'
    }
    if ($null -ne $candidateQuote -and $null -ne $controlQuote) {
        [DateTimeOffset]$candidateValidUntil = [DateTimeOffset]::MinValue
        [DateTimeOffset]$controlValidUntil = [DateTimeOffset]::MinValue
        if ([OperationsBlueprint.StrictRfc3339]::TryParse([string]$candidateQuote.validUntil, [ref]$candidateValidUntil) -and
            [OperationsBlueprint.StrictRfc3339]::TryParse([string]$controlQuote.validUntil, [ref]$controlValidUntil)) {
            $commercialBasisValidUntil = if ($candidateValidUntil -le $controlValidUntil) { $candidateValidUntil } else { $controlValidUntil }
            if ($commercialBasisValidUntil -ne $quoteValidUntil) {
                Add-BlueprintError -Errors $Errors -Code 'COMMERCIAL_QUOTE_BINDING_MISMATCH' -Message 'Decision quoteValidUntil must equal the earliest candidate or incumbent quote expiration.'
            }
        }
    }
    return [pscustomobject]@{ Candidate = $candidateQuote; Control = $controlQuote }
}

function Test-LocalControlReference {
    param(
        [Parameter(Mandatory = $true)][string]$Reference,
        [Parameter(Mandatory = $true)][string]$Root,
        [Parameter(Mandatory = $true)][string[]]$KnownToolIds
    )

    if ($Reference.StartsWith('private://', [System.StringComparison]::Ordinal)) { return $true }
    if ($KnownToolIds -ccontains $Reference) { return $true }

    $parts = $Reference.Split('#', 2)
    $relativePath = $parts[0]
    if ([IO.Path]::IsPathRooted($relativePath) -or $relativePath -match '(^|[\\/])\.\.([\\/]|$)') { return $false }
    $path = Join-Path $Root $relativePath
    if (-not (Test-Path -LiteralPath $path -PathType Leaf)) { return $false }
    if ($parts.Count -eq 1) { return $true }

    $fragment = $parts[1]
    if ([IO.Path]::GetExtension($path) -ceq '.json') {
        try {
            $document = Get-Content -LiteralPath $path -Raw | ConvertFrom-Json
            return Test-JsonPointerExists -Document $document -Pointer $fragment
        }
        catch { return $false }
    }
    if ([IO.Path]::GetExtension($path) -ceq '.md') {
        $anchors = New-Object System.Collections.ArrayList
        foreach ($line in @(Get-Content -LiteralPath $path)) {
            if ($line -match '^#{1,6}\s+(.+?)\s*$') {
                $anchor = $Matches[1].Trim().ToLowerInvariant()
                $anchor = [regex]::Replace($anchor, '[^\p{L}\p{Nd}\s-]', '')
                $anchor = [regex]::Replace($anchor, '\s+', '-')
                [void]$anchors.Add($anchor)
            }
        }
        return @($anchors) -ccontains $fragment
    }
    return $false
}

function Get-UnsafeGitEnvironmentVariableNames {
    # Reject the entire Git namespace.  Even variables that appear diagnostic
    # can select trace sinks, alternate config, helpers, repositories, or object
    # stores.  Native-loader and OpenSSL module selectors can substitute code
    # before the pinned executable starts.
    $unsafeNamePattern = '^(GIT_.+|LD_.+|DYLD_.+|OPENSSL_CONF|OPENSSL_CONF_INCLUDE|OPENSSL_MODULES|OPENSSL_ENGINES)$'
    return @(
        Get-ChildItem Env: | Where-Object {
            # Presence is enough to be unsafe.  Whitespace is a valid path
            # component on supported hosts and must not bypass repository or
            # object-store selection controls.
            [string]$_.Name -match $unsafeNamePattern
        } | ForEach-Object { [string]$_.Name }
    )
}

function Test-RegularNonReparsePathChain {
    param(
        [Parameter(Mandatory = $true)][string]$Path,
        [switch]$RequireLeaf
    )

    try {
        $fullPath = [IO.Path]::GetFullPath($Path)
        $entry = Get-Item -LiteralPath $fullPath -Force -ErrorAction Stop
        if ($RequireLeaf -and $entry.PSIsContainer) { return $false }
        if ((([IO.FileAttributes]$entry.Attributes -band [IO.FileAttributes]::ReparsePoint) -ne 0)) {
            return $false
        }
        $directory = if ($entry.PSIsContainer) { [IO.DirectoryInfo]$entry } else { $entry.Directory }
        while ($null -ne $directory) {
            if ((([IO.FileAttributes]$directory.Attributes -band [IO.FileAttributes]::ReparsePoint) -ne 0)) {
                return $false
            }
            $directory = $directory.Parent
        }
        return $true
    }
    catch { return $false }
}

function Open-PinnedExecutableReadGuard {
    param(
        [Parameter(Mandatory = $true)][string]$Path,
        [Parameter(Mandatory = $true)][string]$ExpectedSha256
    )

    if ($ExpectedSha256 -cnotmatch '^[0-9a-f]{64}$' -or
        -not (Test-RegularNonReparsePathChain -Path $Path -RequireLeaf)) { return $null }
    $stream = $null
    $sha256 = [Security.Cryptography.SHA256]::Create()
    try {
        # FileShare.Read denies write/delete replacement on Windows while the
        # verified executable is launched. The path chain is checked again
        # after the handle is acquired to reject link/junction retargeting.
        $stream = [IO.File]::Open($Path, [IO.FileMode]::Open, [IO.FileAccess]::Read, [IO.FileShare]::Read)
        $actualDigest = ([BitConverter]::ToString($sha256.ComputeHash($stream))).Replace('-', '').ToLowerInvariant()
        $stream.Position = 0
        if ($actualDigest -cne $ExpectedSha256 -or
            -not (Test-RegularNonReparsePathChain -Path $Path -RequireLeaf)) {
            $stream.Dispose()
            return $null
        }
        return $stream
    }
    catch {
        if ($null -ne $stream) { $stream.Dispose() }
        return $null
    }
    finally { $sha256.Dispose() }
}

function Get-TrustedGitRuntimeTreeSha256 {
    param([Parameter(Mandatory = $true)][string]$Root)

    $guard = Open-TrustedGitRuntimeTreeGuard -Root $Root
    if ($null -eq $guard) { return '' }
    try {
        return [string]$guard.Digest
    }
    finally { $guard.Dispose() }
}

function Open-TrustedGitRuntimeTreeGuard {
    param([Parameter(Mandatory = $true)][string]$Root)

    $guard = $null
    try {
        if (-not (Test-IsWindowsRuntime) -or -not [IO.Path]::IsPathRooted($Root)) { return $null }
        $rootPath = [IO.Path]::GetFullPath($Root).TrimEnd(
            [IO.Path]::DirectorySeparatorChar,
            [IO.Path]::AltDirectorySeparatorChar
        )
        if (-not (Test-Path -LiteralPath $rootPath -PathType Container) -or
            -not (Test-RegularNonReparsePathChain -Path $rootPath) -or
            -not (Test-TrustedWindowsPathBoundary -Path $rootPath)) { return $null }
        $guard = [OperationsBlueprint.NativeFileSystemSecurity]::OpenRuntimeTreeGuard($rootPath)
        if ($null -eq $guard -or
            [string]$guard.Digest -cnotmatch '^[0-9a-f]{64}$' -or
            -not (Test-TrustedWindowsPathBoundary -Path $rootPath)) {
            if ($null -ne $guard) { $guard.Dispose() }
            return $null
        }
        return $guard
    }
    catch {
        if ($null -ne $guard) { $guard.Dispose() }
        return $null
    }
}

function Get-TrustedGitExecutionPath {
    param(
        [Parameter(Mandatory = $true)][string]$GitRoot,
        [Parameter(Mandatory = $true)][string]$GitPath
    )

    try {
        $systemDirectory = [Environment]::GetFolderPath([Environment+SpecialFolder]::System)
        $candidates = @(
            [IO.Path]::GetDirectoryName($GitPath),
            (Join-Path $GitRoot 'mingw64\bin'),
            (Join-Path $GitRoot 'usr\bin'),
            $systemDirectory
        )
        $paths = New-Object System.Collections.ArrayList
        $seen = [System.Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
        foreach ($candidate in $candidates) {
            if ([string]::IsNullOrWhiteSpace([string]$candidate)) { return '' }
            $fullCandidate = [IO.Path]::GetFullPath([string]$candidate)
            if (-not (Test-Path -LiteralPath $fullCandidate -PathType Container) -or
                -not (Test-RegularNonReparsePathChain -Path $fullCandidate) -or
                -not (Test-TrustedWindowsPathBoundary -Path $fullCandidate)) { return '' }
            if ($seen.Add($fullCandidate)) { [void]$paths.Add($fullCandidate) }
        }
        return @($paths) -join [IO.Path]::PathSeparator
    }
    catch { return '' }
}

function Get-GitBlobObjectIdFromFile {
    param(
        [Parameter(Mandatory = $true)][string]$Path,
        [Parameter(Mandatory = $true)][ValidateSet(40, 64)][int]$ObjectIdLength
    )

    $stream = $null
    $hash = $null
    try {
        if (-not (Test-RegularNonReparsePathChain -Path $Path -RequireLeaf) -or
            -not (Test-TrustedWindowsPathBoundary -Path $Path -RequireLeaf)) { return '' }
        $stream = [IO.File]::Open($Path, [IO.FileMode]::Open, [IO.FileAccess]::Read, [IO.FileShare]::Read)
        $hash = if ($ObjectIdLength -eq 40) { [Security.Cryptography.SHA1]::Create() } else { [Security.Cryptography.SHA256]::Create() }
        $header = [Text.Encoding]::ASCII.GetBytes("blob $($stream.Length)`0")
        [void]$hash.TransformBlock($header, 0, $header.Length, $header, 0)
        $buffer = New-Object byte[] 65536
        while (($read = $stream.Read($buffer, 0, $buffer.Length)) -gt 0) {
            [void]$hash.TransformBlock($buffer, 0, $read, $buffer, 0)
        }
        [void]$hash.TransformFinalBlock((New-Object byte[] 0), 0, 0)
        if (-not (Test-RegularNonReparsePathChain -Path $Path -RequireLeaf)) { return '' }
        return ([BitConverter]::ToString($hash.Hash)).Replace('-', '').ToLowerInvariant()
    }
    catch { return '' }
    finally {
        if ($null -ne $stream) { $stream.Dispose() }
        if ($null -ne $hash) { $hash.Dispose() }
    }
}

function Get-TrustedGitApplication {
    if (@(Get-UnsafeGitEnvironmentVariableNames).Count -gt 0) { return $null }
    $configuredPath = [string]$env:OPERATIONS_BLUEPRINT_GIT_PATH
    $configuredDigest = [string]$env:OPERATIONS_BLUEPRINT_GIT_SHA256
    $configuredRoot = [string]$env:OPERATIONS_BLUEPRINT_GIT_ROOT
    $configuredTreeDigest = [string]$env:OPERATIONS_BLUEPRINT_GIT_TREE_SHA256
    if ([string]::IsNullOrWhiteSpace($configuredPath) -or
        [string]::IsNullOrWhiteSpace($configuredRoot) -or
        -not [IO.Path]::IsPathRooted($configuredPath) -or
        -not [IO.Path]::IsPathRooted($configuredRoot) -or
        $configuredDigest -cnotmatch '^[0-9a-f]{64}$' -or
        $configuredTreeDigest -cnotmatch '^[0-9a-f]{64}$') { return $null }

    try {
        $gitPath = [IO.Path]::GetFullPath($configuredPath)
        $gitRoot = [IO.Path]::GetFullPath($configuredRoot).TrimEnd(
            [IO.Path]::DirectorySeparatorChar,
            [IO.Path]::AltDirectorySeparatorChar
        )
    }
    catch { return $null }
    $gitRootPrefix = $gitRoot + [IO.Path]::DirectorySeparatorChar
    if (-not [IO.File]::Exists($gitPath) -or
        -not $gitPath.StartsWith($gitRootPrefix, [StringComparison]::OrdinalIgnoreCase) -or
        -not (Test-RegularNonReparsePathChain -Path $gitPath -RequireLeaf) -or
        -not (Test-RegularNonReparsePathChain -Path $gitRoot) -or
        -not (Test-TrustedWindowsPathBoundary -Path $gitPath -RequireLeaf) -or
        -not (Test-TrustedWindowsPathBoundary -Path $gitRoot) -or
        -not (Test-TrustedWindowsPathBoundary -Path $BlueprintRoot)) { return $null }

    # A checked-in executable is not an external trust anchor, even if its bytes
    # happen to match a supplied digest.
    try {
        $candidateRoot = [IO.DirectoryInfo]::new((Resolve-Path -LiteralPath $BlueprintRoot).Path)
        while ($null -ne $candidateRoot -and -not (Test-Path -LiteralPath (Join-Path $candidateRoot.FullName '.git') -PathType Any)) {
            $candidateRoot = $candidateRoot.Parent
        }
        if ($null -ne $candidateRoot) {
            $repositoryPath = [IO.Path]::GetFullPath($candidateRoot.FullName).TrimEnd([IO.Path]::DirectorySeparatorChar, [IO.Path]::AltDirectorySeparatorChar)
            $repositoryPrefix = $repositoryPath + [IO.Path]::DirectorySeparatorChar
            $comparison = if (Test-IsWindowsRuntime) {
                [StringComparison]::OrdinalIgnoreCase
            }
            else { [StringComparison]::Ordinal }
            if ($gitPath.Equals($repositoryPath, $comparison) -or $gitPath.StartsWith($repositoryPrefix, $comparison)) {
                return $null
            }
        }
    }
    catch { return $null }

    $trustedExecutionPath = Get-TrustedGitExecutionPath -GitRoot $gitRoot -GitPath $gitPath
    if ([string]::IsNullOrWhiteSpace($trustedExecutionPath)) { return $null }
    $versionRuntimeGuard = Open-TrustedGitRuntimeTreeGuard -Root $gitRoot
    if ($null -eq $versionRuntimeGuard -or [string]$versionRuntimeGuard.Digest -cne $configuredTreeDigest) {
        if ($null -ne $versionRuntimeGuard) { $versionRuntimeGuard.Dispose() }
        return $null
    }
    $versionGuard = Open-PinnedExecutableReadGuard -Path $gitPath -ExpectedSha256 $configuredDigest
    if ($null -eq $versionGuard) {
        $versionRuntimeGuard.Dispose()
        return $null
    }

    if (Test-IsWindowsRuntime) {
        try {
            $signature = Get-AuthenticodeSignature -LiteralPath $gitPath -ErrorAction Stop
            $versionInfo = [Diagnostics.FileVersionInfo]::GetVersionInfo($gitPath)
        }
        catch {
            $versionGuard.Dispose()
            $versionRuntimeGuard.Dispose()
            return $null
        }
        if ([string]$signature.Status -cne 'Valid' -or
            [string]$versionInfo.OriginalFilename -cne 'git.exe' -or
            [string]$versionInfo.ProductName -cne 'Git') {
            $versionGuard.Dispose()
            $versionRuntimeGuard.Dispose()
            return $null
        }
    }

    $savedPreference = $ErrorActionPreference
    $hadGitConfigNoSystem = Test-Path -LiteralPath 'Env:\GIT_CONFIG_NOSYSTEM'
    $hadGitConfigGlobal = Test-Path -LiteralPath 'Env:\GIT_CONFIG_GLOBAL'
    $hadGitConfigSystem = Test-Path -LiteralPath 'Env:\GIT_CONFIG_SYSTEM'
    $hadGitNoLazyFetch = Test-Path -LiteralPath 'Env:\GIT_NO_LAZY_FETCH'
    $hadGitNoReplaceObjects = Test-Path -LiteralPath 'Env:\GIT_NO_REPLACE_OBJECTS'
    $hadGitOptionalLocks = Test-Path -LiteralPath 'Env:\GIT_OPTIONAL_LOCKS'
    $hadGitTerminalPrompt = Test-Path -LiteralPath 'Env:\GIT_TERMINAL_PROMPT'
    $hadGitProtocolFromUser = Test-Path -LiteralPath 'Env:\GIT_PROTOCOL_FROM_USER'
    $savedGitConfigNoSystem = $env:GIT_CONFIG_NOSYSTEM
    $savedGitConfigGlobal = $env:GIT_CONFIG_GLOBAL
    $savedGitConfigSystem = $env:GIT_CONFIG_SYSTEM
    $savedGitNoLazyFetch = $env:GIT_NO_LAZY_FETCH
    $savedGitNoReplaceObjects = $env:GIT_NO_REPLACE_OBJECTS
    $savedGitOptionalLocks = $env:GIT_OPTIONAL_LOCKS
    $savedGitTerminalPrompt = $env:GIT_TERMINAL_PROMPT
    $savedGitProtocolFromUser = $env:GIT_PROTOCOL_FROM_USER
    $savedPath = $env:PATH
    $savedLocation = Get-Location
    $versionInvocationFailed = $false
    $versionRuntimeValid = $false
    try {
        $ErrorActionPreference = 'Continue'
        $gitNullDevice = if (Test-IsWindowsRuntime) { 'NUL' } else { '/dev/null' }
        $env:GIT_CONFIG_NOSYSTEM = '1'
        $env:GIT_CONFIG_GLOBAL = $gitNullDevice
        $env:GIT_CONFIG_SYSTEM = $gitNullDevice
        $env:GIT_NO_LAZY_FETCH = '1'
        $env:GIT_NO_REPLACE_OBJECTS = '1'
        $env:GIT_OPTIONAL_LOCKS = '0'
        $env:GIT_TERMINAL_PROMPT = '0'
        $env:GIT_PROTOCOL_FROM_USER = '0'
        $env:PATH = $trustedExecutionPath
        Set-Location -LiteralPath $gitRoot
        $versionOutput = @(& $gitPath '--version' 2>&1)
        $versionExitCode = $LASTEXITCODE
    }
    catch { $versionInvocationFailed = $true }
    finally {
        try { $versionRuntimeValid = [bool]$versionRuntimeGuard.Validate($configuredTreeDigest) }
        catch { $versionRuntimeValid = $false }
        if ($hadGitConfigNoSystem) { Set-Item -LiteralPath 'Env:\GIT_CONFIG_NOSYSTEM' -Value $savedGitConfigNoSystem }
        else { Remove-Item -LiteralPath 'Env:\GIT_CONFIG_NOSYSTEM' -ErrorAction SilentlyContinue }
        if ($hadGitConfigGlobal) { Set-Item -LiteralPath 'Env:\GIT_CONFIG_GLOBAL' -Value $savedGitConfigGlobal }
        else { Remove-Item -LiteralPath 'Env:\GIT_CONFIG_GLOBAL' -ErrorAction SilentlyContinue }
        if ($hadGitConfigSystem) { Set-Item -LiteralPath 'Env:\GIT_CONFIG_SYSTEM' -Value $savedGitConfigSystem }
        else { Remove-Item -LiteralPath 'Env:\GIT_CONFIG_SYSTEM' -ErrorAction SilentlyContinue }
        if ($hadGitNoLazyFetch) { Set-Item -LiteralPath 'Env:\GIT_NO_LAZY_FETCH' -Value $savedGitNoLazyFetch }
        else { Remove-Item -LiteralPath 'Env:\GIT_NO_LAZY_FETCH' -ErrorAction SilentlyContinue }
        if ($hadGitNoReplaceObjects) { Set-Item -LiteralPath 'Env:\GIT_NO_REPLACE_OBJECTS' -Value $savedGitNoReplaceObjects }
        else { Remove-Item -LiteralPath 'Env:\GIT_NO_REPLACE_OBJECTS' -ErrorAction SilentlyContinue }
        if ($hadGitOptionalLocks) { Set-Item -LiteralPath 'Env:\GIT_OPTIONAL_LOCKS' -Value $savedGitOptionalLocks }
        else { Remove-Item -LiteralPath 'Env:\GIT_OPTIONAL_LOCKS' -ErrorAction SilentlyContinue }
        if ($hadGitTerminalPrompt) { Set-Item -LiteralPath 'Env:\GIT_TERMINAL_PROMPT' -Value $savedGitTerminalPrompt }
        else { Remove-Item -LiteralPath 'Env:\GIT_TERMINAL_PROMPT' -ErrorAction SilentlyContinue }
        if ($hadGitProtocolFromUser) { Set-Item -LiteralPath 'Env:\GIT_PROTOCOL_FROM_USER' -Value $savedGitProtocolFromUser }
        else { Remove-Item -LiteralPath 'Env:\GIT_PROTOCOL_FROM_USER' -ErrorAction SilentlyContinue }
        $env:PATH = $savedPath
        Set-Location -LiteralPath $savedLocation.Path
        $versionRuntimeGuard.Dispose()
        $versionGuard.Dispose()
        $ErrorActionPreference = $savedPreference
    }
    if ($versionInvocationFailed -or -not $versionRuntimeValid -or
        $versionExitCode -ne 0 -or $versionOutput.Count -ne 1 -or
        [string]$versionOutput[0] -cnotmatch '^git version [0-9]+\.[0-9]+') { return $null }
    return $gitPath
}

function Test-TrustedGitRepositoryHistoryState {
    param([Parameter(Mandatory = $true)][string]$GitDirectory)

    try {
        $gitDirectoryPath = [IO.Path]::GetFullPath($GitDirectory)
        if (-not (Test-Path -LiteralPath $gitDirectoryPath -PathType Container) -or
            -not (Test-RegularNonReparsePathChain -Path $gitDirectoryPath)) { return $false }

        foreach ($relativePath in @(
            'shallow',
            'info\grafts',
            'objects\info\alternates',
            'objects\info\http-alternates'
        )) {
            if (Test-Path -LiteralPath (Join-Path $gitDirectoryPath $relativePath) -PathType Any) {
                return $false
            }
        }

        $replaceRoot = Join-Path $gitDirectoryPath 'refs\replace'
        if (Test-Path -LiteralPath $replaceRoot -PathType Any) {
            $replaceItem = Get-Item -LiteralPath $replaceRoot -Force -ErrorAction Stop
            if (-not $replaceItem.PSIsContainer -or
                (([IO.FileAttributes]$replaceItem.Attributes -band [IO.FileAttributes]::ReparsePoint) -ne 0) -or
                @(Get-ChildItem -LiteralPath $replaceRoot -Force -Recurse -ErrorAction Stop).Count -gt 0) {
                return $false
            }
        }

        $packedRefsPath = Join-Path $gitDirectoryPath 'packed-refs'
        if (Test-Path -LiteralPath $packedRefsPath -PathType Leaf) {
            $packedRefsItem = Get-Item -LiteralPath $packedRefsPath -Force -ErrorAction Stop
            if ((([IO.FileAttributes]$packedRefsItem.Attributes -band [IO.FileAttributes]::ReparsePoint) -ne 0) -or
                $null -ne (Select-String -LiteralPath $packedRefsPath -Pattern ' refs/replace/' -CaseSensitive -ErrorAction Stop)) {
                return $false
            }
        }

        # A partial/promisor repository is not a self-contained immutable
        # history authority. GIT_NO_LAZY_FETCH is also forced for defense in
        # depth, but the repository state itself remains inadmissible.
        $configPath = Join-Path $gitDirectoryPath 'config'
        if (Test-Path -LiteralPath $configPath -PathType Leaf) {
            $configItem = Get-Item -LiteralPath $configPath -Force -ErrorAction Stop
            if ((([IO.FileAttributes]$configItem.Attributes -band [IO.FileAttributes]::ReparsePoint) -ne 0)) {
                return $false
            }
            $configText = Get-Content -LiteralPath $configPath -Raw -ErrorAction Stop
            if ([string]$configText -cmatch '(?im)^\s*(promisor|partialclone(?:filter)?)\s*=') {
                return $false
            }
        }
        return $true
    }
    catch { return $false }
}

function Test-GitReadArgumentShape {
    param([Parameter(Mandatory = $true)][string[]]$Arguments)

    $releasePath = 'deliverables/laptop-qualification-program/v2.0.1'
    $baselineCommit = '53c2ae12891521e4c2491528a50657b74b979e8c'
    $treeId = 'ee333ff4ee0a02a1571bfc631d3537ba91028256'
    if ($Arguments.Count -eq 2 -and [string]$Arguments[0] -ceq 'rev-parse') {
        return [string]$Arguments[1] -ceq "HEAD:$releasePath" -or
            [string]$Arguments[1] -ceq "${baselineCommit}:$releasePath"
    }
    if ($Arguments.Count -eq 4 -and
        [string]$Arguments[0] -ceq 'ls-tree' -and
        [string]$Arguments[1] -ceq '-r' -and
        [string]$Arguments[2] -ceq '--name-only') {
        return [string]$Arguments[3] -ceq $treeId
    }
    if ($Arguments.Count -eq 3 -and
        [string]$Arguments[0] -ceq 'ls-tree' -and
        [string]$Arguments[1] -ceq '-r') {
        return [string]$Arguments[2] -ceq $treeId
    }
    if ($Arguments.Count -eq 4 -and
        [string]$Arguments[0] -ceq 'merge-base' -and
        [string]$Arguments[1] -ceq '--is-ancestor') {
        return [string]$Arguments[2] -ceq $baselineCommit -and
            [string]$Arguments[3] -ceq 'HEAD'
    }
    if ($Arguments.Count -eq 8 -and
        [string]$Arguments[0] -ceq 'log' -and
        [string]$Arguments[1] -ceq '--no-show-signature' -and
        [string]$Arguments[2] -ceq '-n' -and
        [string]$Arguments[3] -ceq '1' -and
        [string]$Arguments[4] -ceq '--format=%H' -and
        [string]$Arguments[5] -ceq 'HEAD' -and
        [string]$Arguments[6] -ceq '--') {
        # Keep this condition explicit even though Count protects the final
        # slot; no trailing caller option may reactivate signatures, diffs,
        # textconv, external diff, or another helper-bearing behavior.
        return [string]$Arguments[7] -ceq $releasePath
    }
    return $false
}

function Invoke-GitRead {
    param([Parameter(Mandatory = $true)][string[]]$Arguments)

    if (-not (Test-GitReadArgumentShape -Arguments $Arguments)) {
        return [pscustomobject]@{ ExitCode = 124; Lines = @(); Error = 'Trusted Git invocation shape is not allowlisted.' }
    }

    $gitPath = Get-TrustedGitApplication
    if ([string]::IsNullOrWhiteSpace([string]$gitPath)) {
        return [pscustomobject]@{ ExitCode = 127; Lines = @(); Error = 'No trusted Git application was resolved.' }
    }

    try {
        $repository = [IO.DirectoryInfo]::new((Resolve-Path -LiteralPath $BlueprintRoot -ErrorAction Stop).Path)
        while ($null -ne $repository -and -not (Test-Path -LiteralPath (Join-Path $repository.FullName '.git') -PathType Container)) {
            $repository = $repository.Parent
        }
        if ($null -eq $repository) { throw 'repository unavailable' }
        $repositoryRoot = [IO.Path]::GetFullPath($repository.FullName)
        $gitDirectory = [IO.Path]::GetFullPath((Join-Path $repositoryRoot '.git'))
        $gitDirectoryItem = Get-Item -LiteralPath $gitDirectory -Force -ErrorAction Stop
        if (-not $gitDirectoryItem.PSIsContainer -or
            (([IO.FileAttributes]$gitDirectoryItem.Attributes -band [IO.FileAttributes]::ReparsePoint) -ne 0)) {
            throw 'repository metadata is not a regular directory'
        }
        if (-not (Test-TrustedGitRepositoryHistoryState -GitDirectory $gitDirectory)) {
            throw 'repository history state is not self-contained'
        }
    }
    catch {
        return [pscustomobject]@{ ExitCode = 125; Lines = @(); Error = 'Trusted Git repository context could not be established.' }
    }

    $savedPreference = $ErrorActionPreference
    $hadGitConfigNoSystem = Test-Path -LiteralPath 'Env:\GIT_CONFIG_NOSYSTEM'
    $hadGitConfigGlobal = Test-Path -LiteralPath 'Env:\GIT_CONFIG_GLOBAL'
    $hadGitConfigSystem = Test-Path -LiteralPath 'Env:\GIT_CONFIG_SYSTEM'
    $hadGitNoLazyFetch = Test-Path -LiteralPath 'Env:\GIT_NO_LAZY_FETCH'
    $hadGitNoReplaceObjects = Test-Path -LiteralPath 'Env:\GIT_NO_REPLACE_OBJECTS'
    $hadGitOptionalLocks = Test-Path -LiteralPath 'Env:\GIT_OPTIONAL_LOCKS'
    $hadGitTerminalPrompt = Test-Path -LiteralPath 'Env:\GIT_TERMINAL_PROMPT'
    $hadGitProtocolFromUser = Test-Path -LiteralPath 'Env:\GIT_PROTOCOL_FROM_USER'
    $hadGitGraftFile = Test-Path -LiteralPath 'Env:\GIT_GRAFT_FILE'
    $hadGitShallowFile = Test-Path -LiteralPath 'Env:\GIT_SHALLOW_FILE'
    $savedGitConfigNoSystem = $env:GIT_CONFIG_NOSYSTEM
    $savedGitConfigGlobal = $env:GIT_CONFIG_GLOBAL
    $savedGitConfigSystem = $env:GIT_CONFIG_SYSTEM
    $savedGitNoLazyFetch = $env:GIT_NO_LAZY_FETCH
    $savedGitNoReplaceObjects = $env:GIT_NO_REPLACE_OBJECTS
    $savedGitOptionalLocks = $env:GIT_OPTIONAL_LOCKS
    $savedGitTerminalPrompt = $env:GIT_TERMINAL_PROMPT
    $savedGitProtocolFromUser = $env:GIT_PROTOCOL_FROM_USER
    $savedGitGraftFile = $env:GIT_GRAFT_FILE
    $savedGitShallowFile = $env:GIT_SHALLOW_FILE
    $savedPath = $env:PATH
    $savedLocation = Get-Location
    try { $gitRoot = [IO.Path]::GetFullPath([string]$env:OPERATIONS_BLUEPRINT_GIT_ROOT) }
    catch { return [pscustomobject]@{ ExitCode = 127; Lines = @(); Error = 'Trusted Git runtime root is invalid.' } }
    $trustedExecutionPath = Get-TrustedGitExecutionPath -GitRoot $gitRoot -GitPath $gitPath
    if ([string]::IsNullOrWhiteSpace($trustedExecutionPath)) {
        return [pscustomobject]@{ ExitCode = 127; Lines = @(); Error = 'Trusted Git runtime tree changed before execution.' }
    }
    $runtimeGuard = Open-TrustedGitRuntimeTreeGuard -Root $gitRoot
    if ($null -eq $runtimeGuard -or
        [string]$runtimeGuard.Digest -cne [string]$env:OPERATIONS_BLUEPRINT_GIT_TREE_SHA256) {
        if ($null -ne $runtimeGuard) { $runtimeGuard.Dispose() }
        return [pscustomobject]@{ ExitCode = 127; Lines = @(); Error = 'Trusted Git runtime tree changed before execution.' }
    }
    $executionGuard = Open-PinnedExecutableReadGuard -Path $gitPath -ExpectedSha256 ([string]$env:OPERATIONS_BLUEPRINT_GIT_SHA256)
    if ($null -eq $executionGuard) {
        $runtimeGuard.Dispose()
        return [pscustomobject]@{ ExitCode = 127; Lines = @(); Error = 'Trusted Git application changed before execution.' }
    }
    $invocationFailed = $false
    $runtimeValid = $false
    $repositoryStateValid = $false
    try {
        $ErrorActionPreference = 'Continue'
        $gitNullDevice = if (Test-IsWindowsRuntime) { 'NUL' } else { '/dev/null' }
        $env:GIT_CONFIG_NOSYSTEM = '1'
        $env:GIT_CONFIG_GLOBAL = $gitNullDevice
        $env:GIT_CONFIG_SYSTEM = $gitNullDevice
        $env:GIT_NO_LAZY_FETCH = '1'
        $env:GIT_NO_REPLACE_OBJECTS = '1'
        $env:GIT_OPTIONAL_LOCKS = '0'
        $env:GIT_TERMINAL_PROMPT = '0'
        $env:GIT_PROTOCOL_FROM_USER = '0'
        $env:GIT_GRAFT_FILE = $gitNullDevice
        $env:GIT_SHALLOW_FILE = $gitNullDevice
        $env:PATH = $trustedExecutionPath
        Set-Location -LiteralPath $gitRoot
        # Local, global, or system Git configuration is not a trust anchor.
        # These command-line overrides prevent status/read commands from
        # executing a configured filesystem monitor or hook helper.
        $safeArguments = @(
            '--no-pager', '--no-replace-objects', '--literal-pathspecs',
            "--git-dir=$gitDirectory", "--work-tree=$repositoryRoot",
            '-c', 'core.fsmonitor=false',
            '-c', 'core.untrackedCache=false',
            '-c', 'core.hooksPath=',
            '-c', 'log.showSignature=false',
            '-c', 'gpg.program=',
            '-c', 'gpg.openpgp.program=',
            '-c', 'gpg.x509.program=',
            '-c', 'gpg.ssh.program=',
            '-c', "core.worktree=$repositoryRoot",
            '-c', 'core.bare=false'
        ) + @($Arguments)
        $records = @(& $gitPath @safeArguments 2>&1)
        $exitCode = $LASTEXITCODE
    }
    catch {
        $invocationFailed = $true
    }
    finally {
        try { $runtimeValid = [bool]$runtimeGuard.Validate([string]$env:OPERATIONS_BLUEPRINT_GIT_TREE_SHA256) }
        catch { $runtimeValid = $false }
        try { $repositoryStateValid = Test-TrustedGitRepositoryHistoryState -GitDirectory $gitDirectory }
        catch { $repositoryStateValid = $false }
        if ($hadGitConfigNoSystem) { Set-Item -LiteralPath 'Env:\GIT_CONFIG_NOSYSTEM' -Value $savedGitConfigNoSystem }
        else { Remove-Item -LiteralPath 'Env:\GIT_CONFIG_NOSYSTEM' -ErrorAction SilentlyContinue }
        if ($hadGitConfigGlobal) { Set-Item -LiteralPath 'Env:\GIT_CONFIG_GLOBAL' -Value $savedGitConfigGlobal }
        else { Remove-Item -LiteralPath 'Env:\GIT_CONFIG_GLOBAL' -ErrorAction SilentlyContinue }
        if ($hadGitConfigSystem) { Set-Item -LiteralPath 'Env:\GIT_CONFIG_SYSTEM' -Value $savedGitConfigSystem }
        else { Remove-Item -LiteralPath 'Env:\GIT_CONFIG_SYSTEM' -ErrorAction SilentlyContinue }
        if ($hadGitNoLazyFetch) { Set-Item -LiteralPath 'Env:\GIT_NO_LAZY_FETCH' -Value $savedGitNoLazyFetch }
        else { Remove-Item -LiteralPath 'Env:\GIT_NO_LAZY_FETCH' -ErrorAction SilentlyContinue }
        if ($hadGitNoReplaceObjects) { Set-Item -LiteralPath 'Env:\GIT_NO_REPLACE_OBJECTS' -Value $savedGitNoReplaceObjects }
        else { Remove-Item -LiteralPath 'Env:\GIT_NO_REPLACE_OBJECTS' -ErrorAction SilentlyContinue }
        if ($hadGitOptionalLocks) { Set-Item -LiteralPath 'Env:\GIT_OPTIONAL_LOCKS' -Value $savedGitOptionalLocks }
        else { Remove-Item -LiteralPath 'Env:\GIT_OPTIONAL_LOCKS' -ErrorAction SilentlyContinue }
        if ($hadGitTerminalPrompt) { Set-Item -LiteralPath 'Env:\GIT_TERMINAL_PROMPT' -Value $savedGitTerminalPrompt }
        else { Remove-Item -LiteralPath 'Env:\GIT_TERMINAL_PROMPT' -ErrorAction SilentlyContinue }
        if ($hadGitProtocolFromUser) { Set-Item -LiteralPath 'Env:\GIT_PROTOCOL_FROM_USER' -Value $savedGitProtocolFromUser }
        else { Remove-Item -LiteralPath 'Env:\GIT_PROTOCOL_FROM_USER' -ErrorAction SilentlyContinue }
        if ($hadGitGraftFile) { Set-Item -LiteralPath 'Env:\GIT_GRAFT_FILE' -Value $savedGitGraftFile }
        else { Remove-Item -LiteralPath 'Env:\GIT_GRAFT_FILE' -ErrorAction SilentlyContinue }
        if ($hadGitShallowFile) { Set-Item -LiteralPath 'Env:\GIT_SHALLOW_FILE' -Value $savedGitShallowFile }
        else { Remove-Item -LiteralPath 'Env:\GIT_SHALLOW_FILE' -ErrorAction SilentlyContinue }
        $env:PATH = $savedPath
        Set-Location -LiteralPath $savedLocation.Path
        $runtimeGuard.Dispose()
        $executionGuard.Dispose()
        $ErrorActionPreference = $savedPreference
    }

    if ($invocationFailed) {
        return [pscustomobject]@{ ExitCode = 126; Lines = @(); Error = 'Trusted Git invocation failed.' }
    }
    if (-not $runtimeValid -or -not $repositoryStateValid) {
        return [pscustomobject]@{ ExitCode = 127; Lines = @(); Error = 'Trusted Git runtime or repository history state changed during execution.' }
    }

    $lines = if ($exitCode -eq 0) { @($records | ForEach-Object { [string]$_ }) } else { @() }
    # Git diagnostics can contain repository paths, helper command lines, and
    # identity-bearing configuration.  Never propagate subprocess text into a
    # validation result; callers receive only a stable failure class.
    $errorText = if ($exitCode -ne 0) { 'Trusted Git command returned a nonzero exit code.' } else { '' }
    return [pscustomobject]@{ ExitCode = $exitCode; Lines = $lines; Error = $errorText }
}

function Get-DiagnosticAliasToken {
    param([Parameter(Mandatory = $true)][string]$Value)

    if ($null -eq $script:OperationsBlueprintDiagnosticAliasKey) {
        $script:OperationsBlueprintDiagnosticAliasKey = New-Object byte[] 32
        $random = [Security.Cryptography.RandomNumberGenerator]::Create()
        try { $random.GetBytes($script:OperationsBlueprintDiagnosticAliasKey) }
        finally { $random.Dispose() }
    }
    $hmac = New-Object Security.Cryptography.HMACSHA256
    $hmac.Key = $script:OperationsBlueprintDiagnosticAliasKey
    try { $digest = $hmac.ComputeHash([Text.Encoding]::UTF8.GetBytes($Value)) }
    finally { $hmac.Dispose() }
    return ([BitConverter]::ToString($digest)).Replace('-', '').ToLowerInvariant().Substring(0, 12)
}

function ConvertTo-SafeDiagnosticMessage {
    param([Parameter(Mandatory = $true)][AllowEmptyString()][string]$Message)

    # A diagnostic is rendered into CI logs and review artifacts. Replace every
    # character category that can create a second line, alter display order,
    # disappear, or carry private-use/surrogate data. Collapse a consecutive
    # unsafe run to one visible token so attacker-controlled text cannot amplify
    # the output before the fixed post-redaction length cap is applied.
    $unsafeCategories = @(
        [Globalization.UnicodeCategory]::Control,
        [Globalization.UnicodeCategory]::Format,
        [Globalization.UnicodeCategory]::Surrogate,
        [Globalization.UnicodeCategory]::PrivateUse,
        [Globalization.UnicodeCategory]::LineSeparator,
        [Globalization.UnicodeCategory]::ParagraphSeparator
    )
    $builder = New-Object Text.StringBuilder
    $insideUnsafeRun = $false
    foreach ($character in $Message.ToCharArray()) {
        $category = [Globalization.CharUnicodeInfo]::GetUnicodeCategory([char]$character)
        if ($unsafeCategories -contains $category) {
            if (-not $insideUnsafeRun) { [void]$builder.Append('[unsafe-unicode]') }
            $insideUnsafeRun = $true
            continue
        }
        $insideUnsafeRun = $false
        [void]$builder.Append($character)
    }

    $singleLine = $builder.ToString().Trim()
    $maximumLength = 512
    $truncationMarker = '[truncated]'
    if ($singleLine.Length -gt $maximumLength) {
        $singleLine = $singleLine.Substring(0, $maximumLength - $truncationMarker.Length) + $truncationMarker
    }
    if ([string]::IsNullOrWhiteSpace($singleLine)) { return '[diagnostic-redacted]' }
    return $singleLine
}

function Add-BlueprintError {
    param(
        [Parameter(Mandatory = $true)][AllowEmptyCollection()][System.Collections.ArrayList]$Errors,
        [Parameter(Mandatory = $true)][string]$Code,
        [Parameter(Mandatory = $true)][string]$Message
    )

    # Public/CI diagnostics are code-led only. Caller-controlled identifiers,
    # property names, paths, hostnames, serials, principals, and exception text
    # must never become public output, even in keyed or partially redacted form.
    # Restricted debugging belongs to the authenticated private runner, not this
    # shareable validator. The supplied Message is intentionally never rendered.
    $safeCode = if ($Code -cmatch '^[A-Z][A-Z0-9_]{2,127}$') { [string]$Code } else { 'VALIDATION_ERROR' }
    $safeMessage = ConvertTo-SafeDiagnosticMessage -Message "Validation failed: $safeCode."
    [void]$Errors.Add([pscustomobject]@{ code = $safeCode; message = $safeMessage })
}

function New-BlueprintResult {
    param(
        [Parameter(Mandatory = $true)][AllowEmptyCollection()][System.Collections.ArrayList]$Errors,
        [string]$State = ''
    )

    $codes = @($Errors | ForEach-Object { $_.code } | Select-Object -Unique)
    $effectiveState = if ([string]::IsNullOrWhiteSpace($State)) { if ($Errors.Count -eq 0) { 'VALID' } else { 'BLOCKED' } } else { $State }
    [pscustomobject]@{
        Valid = ($Errors.Count -eq 0)
        Allowed = ($Errors.Count -eq 0 -and -not $effectiveState.StartsWith('TEST_', [StringComparison]::Ordinal))
        State = $effectiveState
        ReasonCodes = $codes
        Errors = @($Errors)
    }
}

function Test-RequiredProperties {
    param(
        [Parameter(Mandatory = $true)][AllowNull()]$Object,
        [Parameter(Mandatory = $true)][string[]]$Names,
        [Parameter(Mandatory = $true)][string]$Context,
        [Parameter(Mandatory = $true)][AllowEmptyCollection()][System.Collections.ArrayList]$Errors
    )

    foreach ($name in $Names) {
        $property = $Object.PSObject.Properties[$name]
        if ($null -eq $property -or -not (Test-ValuePresent $property.Value)) {
            Add-BlueprintError -Errors $Errors -Code 'MISSING_REQUIRED_FIELD' -Message "$Context requires $name."
        }
    }
}

function Test-ToolRegistry {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]$Registry,
        [DateTimeOffset]$EvaluationTime = [DateTimeOffset]::UtcNow
    )

    $errors = New-Object System.Collections.ArrayList
    if ($null -eq $Registry) {
        Add-BlueprintError -Errors $errors -Code 'NULL_REGISTRY' -Message 'Tool registry is null.'
        return New-BlueprintResult -Errors $errors
    }
    if (-not (Test-CanonicalJsonRuntimeDomain -Value $Registry)) {
        Add-BlueprintError -Errors $errors -Code 'CANONICAL_JSON_RUNTIME_DOMAIN_INVALID' -Message 'Tool registry contains a value outside the frozen cross-host JSON runtime domain.'
        return New-BlueprintResult -Errors $errors -State 'BLOCKED'
    }

    Test-RequiredProperties -Object $Registry -Names @('registryVersion', 'documentType', 'status', 'activation', 'immutableRelease', 'portableContractRefs', 'endpointWriteOwnership', 'intuneTransportOwnership', 'bindings') -Context 'tool registry' -Errors $errors
    Test-AllowedProperties -Object $Registry -Names @(
        'registryVersion', 'documentType', 'status', 'activation', 'portableContractRefs',
        'immutableRelease', 'endpointWriteOwnership', 'intuneTransportOwnership', 'bindings'
    ) -Context 'tool registry' -Errors $errors
    if ([string]$Registry.registryVersion -cne '1.0.0') {
        Add-BlueprintError -Errors $errors -Code 'REGISTRY_VERSION_MISMATCH' -Message 'Tool registry must use the frozen v1.0.0 policy.'
    }
    if ($Registry.documentType -cne 'qualification-tool-registry') {
        Add-BlueprintError -Errors $errors -Code 'INVALID_DOCUMENT_TYPE' -Message 'Tool registry documentType must be qualification-tool-registry.'
    }
    if ($Registry.status -cne 'NON_NORMATIVE') {
        Add-BlueprintError -Errors $errors -Code 'PORTABLE_BOUNDARY_VIOLATION' -Message 'Tool registry must remain NON_NORMATIVE.'
    }
    $requiredRegistryPortableRefs = @(
        '../../v2.0.1/NEW_LAPTOP_EVALUATION_PLAYBOOK_v2.md',
        '../../v2.0.1/schemas/candidate-manifest.schema.json',
        '../../v2.0.1/schemas/test-plan.schema.json',
        '../../v2.0.1/schemas/evidence-record.schema.json',
        '../../v2.0.1/schemas/threshold-policy.schema.json',
        '../../v2.0.1/schemas/verdict-record.schema.json'
    )
    if (@($Registry.portableContractRefs).Count -ne $requiredRegistryPortableRefs.Count) {
        Add-BlueprintError -Errors $errors -Code 'PORTABLE_CONTRACT_SET_MISMATCH' -Message 'Tool registry must bind the exact Playbook v2.0.1 portable contract set.'
    }
    foreach ($portableRef in $requiredRegistryPortableRefs) {
        if (@($Registry.portableContractRefs) -cnotcontains $portableRef) {
            Add-BlueprintError -Errors $errors -Code 'PORTABLE_CONTRACT_SET_MISMATCH' -Message "Tool registry omits portable contract $portableRef."
        }
    }
    if ($null -ne $Registry.immutableRelease) {
        Test-RequiredProperties -Object $Registry.immutableRelease -Names @('path', 'baselineCommit', 'gitTreeId', 'fileCount') -Context 'immutable release boundary' -Errors $errors
        Test-AllowedProperties -Object $Registry.immutableRelease -Names @('path', 'baselineCommit', 'gitTreeId', 'fileCount') -Context 'immutable release boundary' -Errors $errors
        if ([string]$Registry.immutableRelease.path -cne 'deliverables/laptop-qualification-program/v2.0.1') {
            Add-BlueprintError -Errors $errors -Code 'IMMUTABLE_RELEASE_PATH_MISMATCH' -Message 'The v1.0.0 blueprint is pinned to the v2.0.1 release path.'
        }
        if ([string]$Registry.immutableRelease.baselineCommit -cne '53c2ae12891521e4c2491528a50657b74b979e8c') {
            Add-BlueprintError -Errors $errors -Code 'IMMUTABLE_RELEASE_BASELINE_MISMATCH' -Message 'The immutable release baseline commit differs from the validator trust anchor.'
        }
        if ([string]$Registry.immutableRelease.gitTreeId -cne 'ee333ff4ee0a02a1571bfc631d3537ba91028256') {
            Add-BlueprintError -Errors $errors -Code 'IMMUTABLE_RELEASE_CHANGED' -Message 'The immutable release tree declaration differs from the validator trust anchor.'
        }
        if (($Registry.immutableRelease.fileCount -isnot [int] -and $Registry.immutableRelease.fileCount -isnot [long]) -or
            [int64]$Registry.immutableRelease.fileCount -ne 15) {
            Add-BlueprintError -Errors $errors -Code 'IMMUTABLE_RELEASE_FILE_COUNT_MISMATCH' -Message 'The immutable release file-count declaration differs from the validator trust anchor.'
        }
    }
    if ($null -ne $Registry.activation) {
        Test-RequiredProperties -Object $Registry.activation -Names @('state', 'reason') -Context 'activation status' -Errors $errors
        Test-AllowedProperties -Object $Registry.activation -Names @('state', 'reason', 'blockingDecisions') -Context 'activation status' -Errors $errors
        if ($null -eq $Registry.activation.PSObject.Properties['blockingDecisions']) {
            Add-BlueprintError -Errors $errors -Code 'MISSING_REQUIRED_FIELD' -Message 'activation status requires blockingDecisions.'
        }
    }

    $bindings = @($Registry.bindings)
    if ($bindings.Count -eq 0) {
        Add-BlueprintError -Errors $errors -Code 'EMPTY_TOOL_REGISTRY' -Message 'Tool registry has no bindings.'
        return New-BlueprintResult -Errors $errors
    }

    $requiredBindingFields = @(
        'toolId', 'product', 'provider', 'status', 'category', 'roles',
        'leadershipLanes', 'authorityClasses', 'inputs', 'outputs', 'writeScope',
        'readback', 'prohibitedUses', 'replaceable', 'ownerRole', 'versionPolicy',
        'identityBoundary', 'dataClasses', 'failureMode', 'replacementRule'
    )
    foreach ($binding in $bindings) {
        Test-RequiredProperties -Object $binding -Names $requiredBindingFields -Context "tool binding $($binding.toolId)" -Errors $errors
        Test-AllowedProperties -Object $binding -Names @($requiredBindingFields + 'identityRole') -Context "tool binding $($binding.toolId)" -Errors $errors
        if ([string]$binding.status -cnotin @('DESIGN_SELECTED', 'LOCAL_VERIFIED', 'CANDIDATE', 'REQUIRED_SELECTION')) {
            Add-BlueprintError -Errors $errors -Code 'INVALID_TOOL_STATUS' -Message "$($binding.toolId) has an unsupported status."
        }
        if ([string]$binding.ownerRole -cnotmatch '^ROLE_[A-Z0-9_]+$') {
            Add-BlueprintError -Errors $errors -Code 'INVALID_TOOL_OWNER_ROLE' -Message "$($binding.toolId) ownerRole must use an exact canonical ROLE_* identifier."
        }
        if ($null -ne $binding.readback) {
            Test-RequiredProperties -Object $binding.readback -Names @('required', 'mismatchDisposition') -Context "readback for $($binding.toolId)" -Errors $errors
            Test-AllowedProperties -Object $binding.readback -Names @('required', 'viaToolRef', 'viaToolRefs', 'scopeRule', 'mismatchDisposition') -Context "readback for $($binding.toolId)" -Errors $errors
        }
    }

    $toolIds = @($bindings | ForEach-Object { [string]$_.toolId })
    foreach ($group in @($toolIds | Group-Object -CaseSensitive)) {
        if ($group.Count -gt 1) {
            Add-BlueprintError -Errors $errors -Code 'DUPLICATE_TOOL_ID' -Message "Duplicate toolId $($group.Name)."
        }
    }

    $requiredToolIds = @(
        'git', 'github-review', 'enterprise-ci', 'terraform', 'atmos',
        'msgraph-terraform-provider', 'entra-workload-identity', 'azure-key-vault',
        'terraform-state', 'evidence-store', 'authorization-consumption-ledger',
        'authorization-consumption-ledger-readback', 'intune', 'microsoft-graph-write',
        'microsoft-graph-readback', 'azure-resource-manager-readback', 'microsoft-graph-directory-readback', 'windows-autopilot', 'windows-update-service',
        'systrack', 'servicenow', 'fabric-onelake', 'power-bi', 'ansible',
        'collector', 'agent-classification', 'hp-cmsl', 'hp-hpia',
        'windows-native-telemetry', 'windows-powershell', 'powershell-core',
        'pester', 'nodejs', 'ajv', 'ajv-formats', 'semantic-validator',
        'test-harness-catalog', 'survey-platform', 'procurement-system',
        'vendor-change-feed', 'policy-as-code', 'iac-quality-security',
        'artifact-signing', 'decision-packet-renderer', 'alert-channel',
        'claude-code-review', 'group-policy', 'configuration-manager',
        'defender-security-settings-management', 'oem-endpoint-management',
        'emergency-endpoint-automation', 'conditional-access', 'organization-security-stack'
    )
    foreach ($requiredToolId in $requiredToolIds) {
        if ($toolIds -cnotcontains $requiredToolId) {
            Add-BlueprintError -Errors $errors -Code 'REQUIRED_TOOL_MISSING' -Message "Required tool binding $requiredToolId is absent."
        }
    }
    foreach ($toolId in $toolIds) {
        if ($requiredToolIds -cnotcontains $toolId) {
            Add-BlueprintError -Errors $errors -Code 'UNAPPROVED_TOOL_BINDING' -Message "Tool binding $toolId is outside the frozen v1.0.0 inventory."
        }
    }

    if ($toolIds.Count -eq $requiredToolIds.Count -and @($toolIds | Select-Object -Unique).Count -eq $requiredToolIds.Count) {
        $bindingPolicyDigest = Get-ToolBindingPolicyDigest -Bindings $bindings -ToolOrder $requiredToolIds
        if ($bindingPolicyDigest -cne 'sha256:ea18ef7e1a18fcabe42efdcafc44e47b71c444b06c20c2311fa7d7d2f6a8693d') {
            Add-BlueprintError -Errors $errors -Code 'BINDING_POLICY_DRIFT' -Message 'A frozen tool binding identity, version, data class, authority, role, scope, readback, failure, replacement, or prohibited-use field changed; v1.0.0 requires review and a new digest/version.'
        }
    }

    $expectedClassifications = [ordered]@{
        'git' = 'BOUNDED_EXTERNAL_AUTHORITY'; 'github-review' = 'BOUNDED_EXTERNAL_AUTHORITY';
        'enterprise-ci' = 'ORCHESTRATION_ONLY'; 'terraform' = 'ORCHESTRATION_ONLY'; 'atmos' = 'ORCHESTRATION_ONLY';
        'msgraph-terraform-provider' = 'TRANSPORT_ONLY'; 'entra-workload-identity' = 'BOUNDED_EXTERNAL_AUTHORITY';
        'azure-key-vault' = 'BOUNDED_EXTERNAL_AUTHORITY'; 'terraform-state' = 'BOUNDED_EXTERNAL_AUTHORITY';
        'evidence-store' = 'BOUNDED_EXTERNAL_AUTHORITY';
        'authorization-consumption-ledger' = 'BOUNDED_EXTERNAL_AUTHORITY';
        'authorization-consumption-ledger-readback' = 'TRANSPORT_ONLY'; 'intune' = 'INTUNE_ENFORCEMENT';
        'microsoft-graph-write' = 'TRANSPORT_ONLY'; 'microsoft-graph-readback' = 'TRANSPORT_ONLY';
        'microsoft-graph-directory-readback' = 'TRANSPORT_ONLY';
        'azure-resource-manager-readback' = 'TRANSPORT_ONLY';
        'windows-autopilot' = 'INTUNE_DELEGATED_PATH'; 'windows-update-service' = 'INTUNE_DELEGATED_PATH';
        'systrack' = 'NONE'; 'servicenow' = 'BOUNDED_EXTERNAL_AUTHORITY'; 'fabric-onelake' = 'BOUNDED_EXTERNAL_AUTHORITY';
        'power-bi' = 'NONE'; 'ansible' = 'BENCH_OR_NON_INTUNE_ONLY'; 'collector' = 'NONE';
        'agent-classification' = 'NONE'; 'hp-cmsl' = 'NONE'; 'hp-hpia' = 'NONE'; 'windows-native-telemetry' = 'NONE';
        'windows-powershell' = 'NONE'; 'powershell-core' = 'NONE'; 'pester' = 'NONE'; 'nodejs' = 'NONE';
        'ajv' = 'NONE'; 'ajv-formats' = 'NONE'; 'semantic-validator' = 'NONE';
        'test-harness-catalog' = 'BENCH_OR_NON_INTUNE_ONLY'; 'survey-platform' = 'BOUNDED_EXTERNAL_AUTHORITY';
        'procurement-system' = 'BOUNDED_EXTERNAL_AUTHORITY'; 'vendor-change-feed' = 'NONE';
        'policy-as-code' = 'NONE'; 'iac-quality-security' = 'NONE'; 'artifact-signing' = 'BOUNDED_EXTERNAL_AUTHORITY';
        'decision-packet-renderer' = 'BOUNDED_EXTERNAL_AUTHORITY'; 'alert-channel' = 'BOUNDED_EXTERNAL_AUTHORITY';
        'claude-code-review' = 'BOUNDED_EXTERNAL_AUTHORITY'; 'group-policy' = 'BENCH_OR_NON_INTUNE_ONLY';
        'configuration-manager' = 'BENCH_OR_NON_INTUNE_ONLY';
        'defender-security-settings-management' = 'INTUNE_DELEGATED_PATH';
        'oem-endpoint-management' = 'BENCH_OR_NON_INTUNE_ONLY';
        'emergency-endpoint-automation' = 'BENCH_OR_NON_INTUNE_ONLY';
        'conditional-access' = 'BOUNDED_EXTERNAL_AUTHORITY'; 'organization-security-stack' = 'NONE'
    }
    if ($null -ne $Registry.endpointWriteOwnership) {
        Test-RequiredProperties -Object $Registry.endpointWriteOwnership -Names @(
            'policyVersion', 'activationState', 'singleEnforcementPlaneToolId',
            'intuneOwnedEndpointDomains', 'classificationDefinitions', 'toolClassifications', 'rules'
        ) -Context 'endpoint write ownership policy' -Errors $errors
        Test-AllowedProperties -Object $Registry.endpointWriteOwnership -Names @(
            'policyVersion', 'activationState', 'singleEnforcementPlaneToolId',
            'intuneOwnedEndpointDomains', 'classificationDefinitions', 'toolClassifications', 'rules'
        ) -Context 'endpoint write ownership policy' -Errors $errors
        if ((Get-CanonicalPayloadDigest -Payload $Registry.endpointWriteOwnership) -cne 'sha256:da23e1948dd2d50d2475e0f533d535a9d4818ba1d81b0bdc39fe6648894bafa7') {
            Add-BlueprintError -Errors $errors -Code 'ENDPOINT_WRITE_POLICY_DRIFT' -Message 'The frozen endpoint writer classification, domain, or rule set changed.'
        }
        if ([string]$Registry.endpointWriteOwnership.activationState -cne 'HOLD' -or
            [string]$Registry.endpointWriteOwnership.singleEnforcementPlaneToolId -cne 'intune') {
            Add-BlueprintError -Errors $errors -Code 'ENDPOINT_WRITE_POLICY_NOT_HELD' -Message 'The public endpoint write policy must remain HOLD with Intune as its sole enforcement plane.'
        }
        $requiredDomains = @(
            'configuration-settings', 'applications', 'scripts-and-remediations', 'compliance-policies',
            'security-policies', 'update-policies', 'enrollment-and-autopilot', 'assignments-and-rings'
        )
        foreach ($domain in $requiredDomains) {
            if (@($Registry.endpointWriteOwnership.intuneOwnedEndpointDomains) -cnotcontains $domain) {
                Add-BlueprintError -Errors $errors -Code 'INTUNE_OWNED_DOMAIN_MISSING' -Message "Intune-owned endpoint domain $domain is absent."
            }
        }

        $classificationProperties = @($Registry.endpointWriteOwnership.toolClassifications.PSObject.Properties)
        foreach ($expectedToolId in $expectedClassifications.Keys) {
            $property = $classificationProperties | Where-Object { [string]$_.Name -ceq [string]$expectedToolId }
            if (@($property).Count -ne 1) {
                Add-BlueprintError -Errors $errors -Code 'TOOL_WRITE_CLASSIFICATION_MISSING' -Message "$expectedToolId lacks one exact endpoint-write classification."
            }
            elseif ([string]$property[0].Value -cne [string]$expectedClassifications[$expectedToolId]) {
                Add-BlueprintError -Errors $errors -Code 'TOOL_WRITE_CLASSIFICATION_MISMATCH' -Message "$expectedToolId has an unauthorized endpoint-write classification."
            }
        }
        foreach ($property in $classificationProperties) {
            if ($expectedClassifications.Keys -cnotcontains [string]$property.Name) {
                Add-BlueprintError -Errors $errors -Code 'UNAPPROVED_TOOL_WRITE_CLASSIFICATION' -Message "$($property.Name) is not in the frozen endpoint-write inventory."
            }
        }
        $enforcementClassifications = @($classificationProperties | Where-Object { [string]$_.Value -ceq 'INTUNE_ENFORCEMENT' })
        if ($enforcementClassifications.Count -ne 1 -or [string]$enforcementClassifications[0].Name -cne 'intune') {
            Add-BlueprintError -Errors $errors -Code 'INTUNE_WRITE_CLASSIFICATION_NOT_UNIQUE' -Message 'Exactly one binding must be classified INTUNE_ENFORCEMENT and it must be Intune.'
        }
    }
    if ($null -ne $Registry.intuneTransportOwnership) {
        Test-RequiredProperties -Object $Registry.intuneTransportOwnership -Names @(
            'policyVersion', 'activationState', 'desiredStateEngineToolId', 'defaultTransportToolId',
            'exceptionTransportToolId', 'independentReadbackToolId', 'rules'
        ) -Context 'Intune transport ownership policy' -Errors $errors
        Test-AllowedProperties -Object $Registry.intuneTransportOwnership -Names @(
            'policyVersion', 'activationState', 'desiredStateEngineToolId', 'defaultTransportToolId',
            'exceptionTransportToolId', 'independentReadbackToolId', 'objectTypeOwnership', 'rules'
        ) -Context 'Intune transport ownership policy' -Errors $errors
        if ((Get-CanonicalPayloadDigest -Payload $Registry.intuneTransportOwnership) -cne 'sha256:eea53738820fe79bc2eed2888d4b96e05dccc537e543474cda9ad5150bf53565') {
            Add-BlueprintError -Errors $errors -Code 'TRANSPORT_POLICY_DRIFT' -Message 'The frozen public Intune transport ownership boundary changed.'
        }
        if ($null -eq $Registry.intuneTransportOwnership.PSObject.Properties['objectTypeOwnership']) {
            Add-BlueprintError -Errors $errors -Code 'MISSING_REQUIRED_FIELD' -Message 'Intune transport ownership policy requires objectTypeOwnership.'
        }
        if ([string]$Registry.intuneTransportOwnership.activationState -cne 'HOLD' -or
            [string]$Registry.intuneTransportOwnership.desiredStateEngineToolId -cne 'terraform' -or
            [string]$Registry.intuneTransportOwnership.defaultTransportToolId -cne 'msgraph-terraform-provider' -or
            [string]$Registry.intuneTransportOwnership.exceptionTransportToolId -cne 'microsoft-graph-write' -or
            [string]$Registry.intuneTransportOwnership.independentReadbackToolId -cne 'microsoft-graph-readback' -or
            @($Registry.intuneTransportOwnership.objectTypeOwnership).Count -ne 0) {
            Add-BlueprintError -Errors $errors -Code 'PUBLIC_TRANSPORT_OWNERSHIP_NOT_HELD' -Message 'Public transport ownership must remain HOLD with an empty private object-type inventory and the frozen engine/transport/readback roles.'
        }
    }

    $forbiddenAuthorities = @('portable-method-authority', 'verdict-authority', 'evidence-origin')
    foreach ($binding in $bindings) {
        foreach ($authority in @($binding.authorityClasses)) {
            if ($forbiddenAuthorities -ccontains $authority) {
                Add-BlueprintError -Errors $errors -Code 'FORBIDDEN_TOOL_AUTHORITY' -Message "$($binding.toolId) may not claim $authority."
            }
        }
    }

    $enforcement = @($bindings | Where-Object { @($_.authorityClasses) -ccontains 'enforcement-plane' })
    if ($enforcement.Count -ne 1 -or [string]$enforcement[0].toolId -cne 'intune') {
        Add-BlueprintError -Errors $errors -Code 'INTUNE_NOT_SOLE_ENFORCEMENT_PLANE' -Message 'Exactly one enforcement plane is required and it must be Intune.'
    }

    $desiredStateAuthorities = @($bindings | Where-Object { @($_.authorityClasses) -ccontains 'desired-state' })
    if ($desiredStateAuthorities.Count -ne 1 -or [string]$desiredStateAuthorities[0].toolId -cne 'git') {
        Add-BlueprintError -Errors $errors -Code 'GIT_NOT_SOLE_DESIRED_STATE_AUTHORITY' -Message 'Exactly one desired-state authority is required and it must be Git.'
    }

    $graphWrite = @($bindings | Where-Object toolId -eq 'microsoft-graph-write')
    $graphReadback = @($bindings | Where-Object toolId -eq 'microsoft-graph-readback')
    $directoryReadback = @($bindings | Where-Object toolId -eq 'microsoft-graph-directory-readback')
    $armReadback = @($bindings | Where-Object toolId -eq 'azure-resource-manager-readback')
    if ($graphWrite.Count -eq 1) {
        if ($null -eq $graphWrite[0].readback -or
            $graphWrite[0].readback.required -ne $true -or
            $graphWrite[0].readback.viaToolRef -ne 'microsoft-graph-readback') {
            Add-BlueprintError -Errors $errors -Code 'GRAPH_READBACK_REQUIRED' -Message 'Graph write requires independent Microsoft Graph readback.'
        }
    }
    if ($graphWrite.Count -eq 1 -and $graphReadback.Count -eq 1) {
        if ([string]$graphWrite[0].identityRole -cne 'WRITER' -or [string]$graphReadback[0].identityRole -cne 'READER' -or
            [string]$graphReadback[0].writeScope -cne 'none' -or
            [string]$graphWrite[0].identityBoundary -ceq [string]$graphReadback[0].identityBoundary -or
            @($graphReadback[0].authorityClasses) -ccontains 'enforcement-plane' -or
            @($graphReadback[0].authorityClasses) -ccontains 'desired-state' -or
            @($graphReadback[0].authorityClasses) -ccontains 'desired-state-transition') {
            Add-BlueprintError -Errors $errors -Code 'GRAPH_READBACK_IDENTITY_NOT_INDEPENDENT' -Message 'Graph readback must be a distinct read-only identity with no enforcement or desired-state authority.'
        }
    }
    if ($armReadback.Count -eq 1 -and $graphWrite.Count -eq 1) {
        if ([string]$armReadback[0].identityRole -cne 'READER' -or
            [string]$armReadback[0].writeScope -cne 'none' -or
            [string]$armReadback[0].identityBoundary -ceq [string]$graphWrite[0].identityBoundary -or
            @($armReadback[0].authorityClasses) -ccontains 'enforcement-plane' -or
            @($armReadback[0].authorityClasses) -ccontains 'desired-state-transition') {
            Add-BlueprintError -Errors $errors -Code 'ARM_READBACK_IDENTITY_NOT_INDEPENDENT' -Message 'Azure resource-plane readback must use a distinct read-only identity with no enforcement or transition authority.'
        }
    }
    if ($directoryReadback.Count -eq 1 -and $graphWrite.Count -eq 1 -and $graphReadback.Count -eq 1) {
        if ([string]$directoryReadback[0].identityRole -cne 'READER' -or
            [string]$directoryReadback[0].writeScope -cne 'none' -or
            [string]$directoryReadback[0].identityBoundary -ceq [string]$graphWrite[0].identityBoundary -or
            [string]$directoryReadback[0].identityBoundary -ceq [string]$graphReadback[0].identityBoundary -or
            @($directoryReadback[0].authorityClasses) -ccontains 'enforcement-plane' -or
            @($directoryReadback[0].authorityClasses) -ccontains 'desired-state-transition') {
            Add-BlueprintError -Errors $errors -Code 'DIRECTORY_READBACK_IDENTITY_NOT_INDEPENDENT' -Message 'Directory readback must use a distinct read-only identity with no enforcement or transition authority.'
        }
    }
    $terraformBinding = @($bindings | Where-Object toolId -eq 'terraform')
    if ($terraformBinding.Count -eq 1) {
        foreach ($requiredReadback in @('microsoft-graph-readback', 'microsoft-graph-directory-readback', 'azure-resource-manager-readback')) {
            if (@($terraformBinding[0].readback.viaToolRefs) -cnotcontains $requiredReadback) {
                Add-BlueprintError -Errors $errors -Code 'TERRAFORM_RESOURCE_PLANE_READBACK_INCOMPLETE' -Message "Terraform lacks independent $requiredReadback."
            }
        }
    }

    $perBindingReadbackPolicies = @(
        [pscustomobject]@{
            toolId = 'msgraph-terraform-provider'
            viaToolRef = 'microsoft-graph-readback'
            viaToolRefs = @()
            scopeRule = ''
        },
        [pscustomobject]@{
            toolId = 'entra-workload-identity'
            viaToolRef = ''
            viaToolRefs = @('microsoft-graph-directory-readback', 'azure-resource-manager-readback')
            scopeRule = 'Use independent directory Graph for Entra objects and Azure Resource Manager for Azure role assignments; require both when both planes change.'
        },
        [pscustomobject]@{
            toolId = 'azure-key-vault'
            viaToolRef = ''
            viaToolRefs = @('azure-resource-manager-readback')
            scopeRule = 'Use the independent Azure Resource Manager read identity for Key Vault configuration and access-policy state; CI output is not readback.'
        },
        [pscustomobject]@{
            toolId = 'terraform-state'
            viaToolRef = ''
            viaToolRefs = @('azure-resource-manager-readback')
            scopeRule = 'Use the independent Azure Resource Manager read identity for backend resource configuration; Terraform state or apply output is not readback.'
        }
    )
    foreach ($policy in $perBindingReadbackPolicies) {
        $matchingBinding = @($bindings | Where-Object { [string]$_.toolId -ceq [string]$policy.toolId })
        if ($matchingBinding.Count -ne 1) { continue }
        $readback = $matchingBinding[0].readback
        $actualRefs = @($readback.viaToolRefs | Where-Object { Test-ValuePresent $_ })
        $refsMatch = $actualRefs.Count -eq @($policy.viaToolRefs).Count
        foreach ($requiredRef in @($policy.viaToolRefs)) {
            if ($actualRefs -cnotcontains [string]$requiredRef) { $refsMatch = $false }
        }
        foreach ($actualRef in $actualRefs) {
            if (@($policy.viaToolRefs) -cnotcontains [string]$actualRef) { $refsMatch = $false }
        }
        if ($readback.required -ne $true -or [string]$readback.mismatchDisposition -cne 'HOLD' -or
            [string]$readback.viaToolRef -cne [string]$policy.viaToolRef -or -not $refsMatch -or
            [string]$readback.scopeRule -cne [string]$policy.scopeRule) {
            Add-BlueprintError -Errors $errors -Code 'PER_BINDING_READBACK_PLANE_INVALID' -Message "$($policy.toolId) is not bound to its exact independent resource-plane observer."
        }
    }

    foreach ($binding in $bindings) {
        $viaToolRef = if ($null -ne $binding.readback) { [string]$binding.readback.viaToolRef } else { '' }
        if (-not [string]::IsNullOrWhiteSpace($viaToolRef) -and $toolIds -cnotcontains $viaToolRef) {
            Add-BlueprintError -Errors $errors -Code 'DANGLING_TOOL_REF' -Message "$($binding.toolId) references unknown readback tool $viaToolRef."
        }
        foreach ($additionalToolRef in @($binding.readback.viaToolRefs)) {
            if (-not [string]::IsNullOrWhiteSpace([string]$additionalToolRef) -and $toolIds -cnotcontains [string]$additionalToolRef) {
                Add-BlueprintError -Errors $errors -Code 'DANGLING_TOOL_REF' -Message "$($binding.toolId) references unknown readback tool $additionalToolRef."
            }
        }
    }

    $ansible = @($bindings | Where-Object toolId -eq 'ansible')
    if ($ansible.Count -eq 1 -and [string]$ansible[0].writeScope -match '(?i)(production-intune-settings|production writer|intune-owned production)') {
        Add-BlueprintError -Errors $errors -Code 'ANSIBLE_PRODUCTION_WRITE_FORBIDDEN' -Message 'Ansible may not write production or Intune-owned settings.'
    }

    $fabric = @($bindings | Where-Object toolId -eq 'fabric-onelake')
    if ($fabric.Count -eq 1 -and
        (-not (Test-CanonicalValueEqual @($fabric[0].authorityClasses) @('analytics-projection-custody','reporting-view')) -or
         @($fabric[0].authorityClasses | Where-Object { $forbiddenAuthorities -ccontains $_ }).Count -gt 0)) {
        Add-BlueprintError -Errors $errors -Code 'FORBIDDEN_TOOL_AUTHORITY' -Message 'Fabric must remain an analytics-projection custody/reporting-view binding and cannot originate evidence or verdicts.'
    }

    if ($null -eq $Registry.activation -or [string]$Registry.activation.state -cne 'HOLD') {
        Add-BlueprintError -Errors $errors -Code 'PUBLIC_BLUEPRINT_CANNOT_ACTIVATE' -Message 'The public non-normative registry must remain HOLD; ACTIVE exists only in a separately authenticated private implementation.'
    }
    if ($null -ne $Registry.activation -and @($Registry.activation.blockingDecisions).Count -eq 0) {
        Add-BlueprintError -Errors $errors -Code 'HOLD_WITHOUT_BLOCKING_DECISION' -Message 'HOLD requires at least one explicit blocking decision.'
    }

    $result = New-BlueprintResult -Errors $errors -State $(if ($errors.Count -eq 0) { 'VALIDATED_BINDING_BLUEPRINT' } else { 'BLOCKED' })
    $result.Allowed = $false
    return $result
}

function Test-ControlMatrix {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]$Matrix,
        [Parameter(Mandatory = $true)]$Registry,
        [string]$ControlRoot = $script:BlueprintRoot
    )

    $errors = New-Object System.Collections.ArrayList
    if ($null -eq $Matrix) {
        Add-BlueprintError -Errors $errors -Code 'NULL_CONTROL_MATRIX' -Message 'Control matrix is null.'
        return New-BlueprintResult -Errors $errors
    }
    if (-not (Test-CanonicalJsonRuntimeDomain -Value $Matrix) -or
        -not (Test-CanonicalJsonRuntimeDomain -Value $Registry)) {
        Add-BlueprintError -Errors $errors -Code 'CANONICAL_JSON_RUNTIME_DOMAIN_INVALID' -Message 'Control matrix or tool registry contains a value outside the frozen cross-host JSON runtime domain.'
        return New-BlueprintResult -Errors $errors -State 'BLOCKED'
    }

    Test-RequiredProperties -Object $Matrix -Names @('matrixVersion', 'documentType', 'status', 'roleCatalog', 'controls') -Context 'control matrix' -Errors $errors
    Test-AllowedProperties -Object $Matrix -Names @('matrixVersion', 'documentType', 'status', 'roleCatalog', 'controls') -Context 'control matrix' -Errors $errors
    if ([string]$Matrix.matrixVersion -cne '1.0.0') {
        Add-BlueprintError -Errors $errors -Code 'CONTROL_MATRIX_VERSION_MISMATCH' -Message 'Control matrix must use the frozen v1.0.0 policy.'
    }
    if ($Matrix.documentType -cne 'qualification-control-matrix') {
        Add-BlueprintError -Errors $errors -Code 'INVALID_DOCUMENT_TYPE' -Message 'Control matrix documentType must be qualification-control-matrix.'
    }
    if ($Matrix.status -cne 'NON_NORMATIVE') {
        Add-BlueprintError -Errors $errors -Code 'PORTABLE_BOUNDARY_VIOLATION' -Message 'Control matrix must remain NON_NORMATIVE.'
    }

    $roleIds = @()
    if ($null -ne $Matrix.roleCatalog) {
        Test-RequiredProperties -Object $Matrix.roleCatalog -Names @('policyVersion', 'activationState', 'roles', 'rules') -Context 'canonical role catalog' -Errors $errors
        Test-AllowedProperties -Object $Matrix.roleCatalog -Names @('policyVersion', 'activationState', 'privatePrincipalBindingRef', 'roles', 'rules') -Context 'canonical role catalog' -Errors $errors
        if ([string]$Matrix.roleCatalog.activationState -cne 'HOLD' -or
            $null -eq $Matrix.roleCatalog.PSObject.Properties['privatePrincipalBindingRef'] -or
            $null -ne $Matrix.roleCatalog.privatePrincipalBindingRef) {
            Add-BlueprintError -Errors $errors -Code 'PUBLIC_ROLE_BINDING_NOT_HELD' -Message 'The public role catalog must remain HOLD with no private principal binding.'
        }
        $roleIds = @($Matrix.roleCatalog.roles | ForEach-Object { [string]$_.roleId })
        foreach ($group in @($roleIds | Group-Object -CaseSensitive)) {
            if ($group.Count -gt 1) {
                Add-BlueprintError -Errors $errors -Code 'DUPLICATE_CANONICAL_ROLE_ID' -Message "Role catalog repeats $($group.Name)."
            }
        }
        foreach ($role in @($Matrix.roleCatalog.roles)) {
            Test-RequiredProperties -Object $role -Names @('roleId', 'dutyClass', 'description') -Context 'canonical role' -Errors $errors
            Test-AllowedProperties -Object $role -Names @('roleId', 'dutyClass', 'description') -Context "canonical role $($role.roleId)" -Errors $errors
            if ([string]$role.roleId -cnotmatch '^ROLE_[A-Z0-9_]+$' -or
                [string]$role.dutyClass -cnotin @('OWNER_OR_OPERATOR', 'APPROVER')) {
                Add-BlueprintError -Errors $errors -Code 'INVALID_CANONICAL_ROLE' -Message "$($role.roleId) is not a canonical role with a bounded duty class."
            }
        }
    }

    $controls = @($Matrix.controls)
    if ($controls.Count -eq 0) {
        Add-BlueprintError -Errors $errors -Code 'EMPTY_CONTROL_MATRIX' -Message 'Control matrix has no controls.'
        return New-BlueprintResult -Errors $errors
    }

    $controlIds = @($controls | ForEach-Object { [string]$_.controlId })
    foreach ($group in @($controlIds | Group-Object -CaseSensitive)) {
        if ($group.Count -gt 1) {
            Add-BlueprintError -Errors $errors -Code 'DUPLICATE_CONTROL_ID' -Message "Duplicate controlId $($group.Name)."
        }
    }

    $requiredControlIds = @(
        'GOV-001', 'GOV-002', 'DATA-001', 'DATA-002', 'CLAIM-001', 'CLAIM-002',
        'IAC-001', 'IAC-002', 'IAC-003', 'INTUNE-001', 'INTUNE-002', 'INTUNE-003',
        'INTUNE-004', 'TEST-001', 'PRIV-001', 'SUPPLY-001', 'MON-001', 'MON-002'
    )
    foreach ($requiredControlId in $requiredControlIds) {
        if ($controlIds -cnotcontains $requiredControlId) {
            Add-BlueprintError -Errors $errors -Code 'REQUIRED_CONTROL_MISSING' -Message "Required control $requiredControlId is absent."
        }
    }
    foreach ($controlId in $controlIds) {
        if ($requiredControlIds -cnotcontains $controlId) {
            Add-BlueprintError -Errors $errors -Code 'UNAPPROVED_CONTROL' -Message "Control $controlId is outside the frozen v1.0.0 control inventory."
        }
    }
    $expectedControlPolicyDigest = 'sha256:b232732e7d95a8721ea6f6cc0aa08cae8155f9e42cb1fae5ad6229e5587bd246'
    $actualControlPolicyDigest = Get-ControlPolicyDigest -Matrix $Matrix -ControlOrder $requiredControlIds
    if ([string]$actualControlPolicyDigest -cne $expectedControlPolicyDigest) {
        Add-BlueprintError -Errors $errors -Code 'CONTROL_POLICY_DRIFT' -Message 'The frozen role and control policy differs from the reviewed v1.0.0 binding.'
    }

    $knownToolIds = @($Registry.bindings | ForEach-Object { [string]$_.toolId })
    foreach ($binding in @($Registry.bindings)) {
        $bindingOwnerRole = [string]$binding.ownerRole
        $bindingOwnerCatalogRecord = @($Matrix.roleCatalog.roles | Where-Object { [string]$_.roleId -ceq $bindingOwnerRole })
        if ($roleIds -cnotcontains $bindingOwnerRole) {
            Add-BlueprintError -Errors $errors -Code 'UNRESOLVED_TOOL_OWNER_ROLE' -Message "$($binding.toolId) ownerRole does not resolve by exact canonical roleId."
        }
        elseif ($bindingOwnerCatalogRecord.Count -ne 1 -or [string]$bindingOwnerCatalogRecord[0].dutyClass -cne 'OWNER_OR_OPERATOR') {
            Add-BlueprintError -Errors $errors -Code 'ROLE_DUTY_CLASS_MISMATCH' -Message "$($binding.toolId) ownerRole is not an owner/operator duty."
        }
    }
    $requiredControlFields = @(
        'controlId', 'objective', 'ownerRole', 'approverRole', 'toolRefs',
        'evidenceOutputs', 'failureState', 'failClosed', 'exceptionRule',
        'monitoring', 'readbackRef', 'rollbackRef', 'writesIntune'
    )
    foreach ($control in $controls) {
        Test-RequiredProperties -Object $control -Names $requiredControlFields -Context "control $($control.controlId)" -Errors $errors
        Test-AllowedProperties -Object $control -Names $requiredControlFields -Context "control $($control.controlId)" -Errors $errors
        Test-AllowedProperties -Object $control.failClosed -Names @('missing', 'stale', 'unknown', 'mismatch') -Context "control $($control.controlId) failClosed" -Errors $errors

        if ($control.failureState -cnotin @('BLOCKED', 'HOLD', 'INCONCLUSIVE', 'FAIL')) {
            Add-BlueprintError -Errors $errors -Code 'NON_BLOCKING_FAILURE_STATE' -Message "$($control.controlId) has a non-blocking top-level failureState."
        }

        if ([string]$control.ownerRole -ceq [string]$control.approverRole) {
            Add-BlueprintError -Errors $errors -Code 'SEPARATION_OF_DUTIES_REQUIRED' -Message "$($control.controlId) has the same owner and approver role."
        }
        foreach ($roleField in @('ownerRole', 'approverRole')) {
            if ($roleIds -cnotcontains [string]$control.$roleField) {
                Add-BlueprintError -Errors $errors -Code 'UNRESOLVED_CANONICAL_ROLE' -Message "$($control.controlId) $roleField does not resolve by exact canonical roleId."
            }
        }
        $ownerCatalogRecord = @($Matrix.roleCatalog.roles | Where-Object { [string]$_.roleId -ceq [string]$control.ownerRole })
        $approverCatalogRecord = @($Matrix.roleCatalog.roles | Where-Object { [string]$_.roleId -ceq [string]$control.approverRole })
        if ($ownerCatalogRecord.Count -eq 1 -and [string]$ownerCatalogRecord[0].dutyClass -cne 'OWNER_OR_OPERATOR') {
            Add-BlueprintError -Errors $errors -Code 'ROLE_DUTY_CLASS_MISMATCH' -Message "$($control.controlId) ownerRole is not an owner/operator duty."
        }
        if ($approverCatalogRecord.Count -eq 1 -and [string]$approverCatalogRecord[0].dutyClass -cne 'APPROVER') {
            Add-BlueprintError -Errors $errors -Code 'ROLE_DUTY_CLASS_MISMATCH' -Message "$($control.controlId) approverRole is not an approval duty."
        }
        foreach ($toolRef in @($control.toolRefs)) {
            if ($knownToolIds -cnotcontains $toolRef) {
                Add-BlueprintError -Errors $errors -Code 'DANGLING_TOOL_REF' -Message "$($control.controlId) references unknown tool $toolRef."
            }
        }
        foreach ($propertyName in @('missing', 'stale', 'unknown', 'mismatch')) {
            $property = $control.failClosed.PSObject.Properties[$propertyName]
            if ($null -eq $property -or $property.Value -notin @('BLOCKED', 'HOLD', 'INCONCLUSIVE', 'FAIL')) {
                Add-BlueprintError -Errors $errors -Code 'NON_BLOCKING_FAILURE_STATE' -Message "$($control.controlId) does not fail closed for $propertyName."
            }
        }
        $expectedIntuneWrite = [string]$control.controlId -cin @('IAC-002', 'INTUNE-002', 'INTUNE-003', 'INTUNE-004')
        if ($control.writesIntune -isnot [bool] -or [bool]$control.writesIntune -ne $expectedIntuneWrite) {
            Add-BlueprintError -Errors $errors -Code 'INTUNE_WRITE_CLASSIFICATION_MISMATCH' -Message "$($control.controlId) has an incorrect writesIntune classification."
        }
        foreach ($referenceName in @('readbackRef', 'rollbackRef')) {
            $reference = [string]$control.$referenceName
            if (-not [string]::IsNullOrWhiteSpace($reference) -and
                -not (Test-LocalControlReference -Reference $reference -Root $ControlRoot -KnownToolIds $knownToolIds)) {
                Add-BlueprintError -Errors $errors -Code 'UNRESOLVED_CONTROL_REFERENCE' -Message "$($control.controlId) $referenceName does not resolve to a local file/pointer/anchor, a known tool, or an explicit private reference."
            }
        }
        if ($expectedIntuneWrite) {
            if (@($control.toolRefs) -cnotcontains 'intune' -or
                @($control.toolRefs) -cnotcontains 'microsoft-graph-write' -or
                @($control.toolRefs) -cnotcontains 'microsoft-graph-readback') {
                Add-BlueprintError -Errors $errors -Code 'INTUNE_WRITE_PATH_INVALID' -Message "$($control.controlId) must bind Intune, the bounded Graph adapter, and independent Graph readback."
            }
            if (-not (Test-ValuePresent $control.readbackRef)) {
                Add-BlueprintError -Errors $errors -Code 'INTUNE_READBACK_REQUIRED' -Message "$($control.controlId) lacks readback."
            }
            if (-not (Test-ValuePresent $control.rollbackRef)) {
                Add-BlueprintError -Errors $errors -Code 'ROLLBACK_REQUIRED' -Message "$($control.controlId) lacks rollback."
            }
        }
        if ([string]$control.controlId -ceq 'IAC-002') {
            foreach ($requiredToolRef in @(
                'terraform', 'atmos', 'enterprise-ci', 'policy-as-code', 'iac-quality-security',
                'entra-workload-identity', 'msgraph-terraform-provider',
                'microsoft-graph-directory-readback', 'azure-resource-manager-readback'
            )) {
                if (@($control.toolRefs) -cnotcontains $requiredToolRef) {
                    Add-BlueprintError -Errors $errors -Code 'IAC_APPLY_PATH_INVALID' -Message "IAC-002 lacks $requiredToolRef in the multi-plane reviewed apply path."
                }
            }
            if ([string]$control.readbackRef -cne 'private://ci/multi-plane-readback-attestation' -or
                -not ([string]$control.rollbackRef).StartsWith('private://', [System.StringComparison]::Ordinal)) {
                Add-BlueprintError -Errors $errors -Code 'IAC_APPLY_READBACK_OR_ROLLBACK_INVALID' -Message 'IAC-002 requires the private multi-plane readback attestation and a private rollback runbook.'
            }
        }
        if ([string]$control.controlId -ceq 'INTUNE-004' -and
            ([string]$control.readbackRef -cne 'microsoft-graph-readback' -or
             -not ([string]$control.rollbackRef).StartsWith('private://', [System.StringComparison]::Ordinal))) {
            Add-BlueprintError -Errors $errors -Code 'INTUNE_READBACK_OR_ROLLBACK_INVALID' -Message 'INTUNE-004 requires independent Graph readback and a bounded private rollback runbook.'
        }
    }

    $result = New-BlueprintResult -Errors $errors -State $(if ($errors.Count -eq 0) { 'VALIDATED_CONTROL_MATRIX' } else { 'BLOCKED' })
    $result.Allowed = $false
    return $result
}

function Test-Phase0EvidenceReusePolicy {
    param(
        [AllowNull()]$TestPlan,
        [Parameter(Mandatory = $true)][DateTimeOffset]$EvaluationTime,
        [Parameter(Mandatory = $true)][AllowEmptyCollection()][System.Collections.ArrayList]$Errors
    )

    if ($null -eq $TestPlan -or $TestPlan.evidenceReusePolicy -isnot [pscustomobject]) {
        Add-BlueprintError -Errors $Errors -Code 'PHASE0_EVIDENCE_REUSE_POLICY_INVALID' -Message 'The frozen Phase 0 test plan lacks a structured evidence-reuse policy.'
        return $false
    }

    $policy = $TestPlan.evidenceReusePolicy
    $policyFields = @('policyVersion','status','frozenAt','approvedBy','documentaryContext','compatibilityCache','dynamicEvidence','bootstrap')
    Test-RequiredProperties -Object $policy -Names $policyFields -Context 'Phase 0 evidence-reuse policy' -Errors $Errors
    Test-AllowedProperties -Object $policy -Names ($policyFields + @('extensions')) -Context 'Phase 0 evidence-reuse policy' -Errors $Errors
    [DateTimeOffset]$policyFrozenAt = [DateTimeOffset]::MinValue
    $valid = (Test-NonBlankString $policy.policyVersion) -and
        [string]$policy.status -ceq 'frozen' -and
        (Test-NonBlankString $policy.approvedBy) -and
        [OperationsBlueprint.StrictRfc3339]::TryParse([string]$policy.frozenAt, [ref]$policyFrozenAt) -and
        $policyFrozenAt -le $EvaluationTime

    $documentaryFields = @(
        'countsTowardSamplingFloor','replacesFreshPhase1','exactConfigurationRequired',
        'artifactHashVerificationRequired','currencyWindowRequired','unchangedDependenciesRequired'
    )
    if ($policy.documentaryContext -isnot [pscustomobject]) { $valid = $false }
    else {
        Test-RequiredProperties -Object $policy.documentaryContext -Names $documentaryFields -Context 'Phase 0 documentary reuse policy' -Errors $Errors
        Test-AllowedProperties -Object $policy.documentaryContext -Names $documentaryFields -Context 'Phase 0 documentary reuse policy' -Errors $Errors
        $valid = $valid -and
            $policy.documentaryContext.countsTowardSamplingFloor -eq $false -and
            $policy.documentaryContext.replacesFreshPhase1 -eq $false -and
            $policy.documentaryContext.exactConfigurationRequired -eq $true -and
            $policy.documentaryContext.artifactHashVerificationRequired -eq $true -and
            $policy.documentaryContext.currencyWindowRequired -eq $true -and
            $policy.documentaryContext.unchangedDependenciesRequired -eq $true
    }

    $requiredDependencyDimensions = @(
        'hardware','firmware','operating-system','agents','applications','peripherals',
        'conditions','test-and-pack','support-currency','threshold-policy','staleness'
    )
    $cacheFields = @(
        'eligibleClass','maximumAgeDays','requiredDependencyDimensions','exactSubjectRequired',
        'artifactHashVerificationRequired','completeEvidenceRequired','separateStrataOnMismatch','bridge'
    )
    if ($policy.compatibilityCache -isnot [pscustomobject]) { $valid = $false }
    else {
        $cache = $policy.compatibilityCache
        Test-RequiredProperties -Object $cache -Names $cacheFields -Context 'Phase 0 compatibility-cache policy' -Errors $Errors
        Test-AllowedProperties -Object $cache -Names $cacheFields -Context 'Phase 0 compatibility-cache policy' -Errors $Errors
        $cacheDimensions = @($cache.requiredDependencyDimensions)
        $valid = $valid -and [string]$cache.eligibleClass -ceq 'application-compatibility' -and
            ($cache.maximumAgeDays -is [int] -or $cache.maximumAgeDays -is [long]) -and
            [int64]$cache.maximumAgeDays -ge 1 -and
            $cacheDimensions.Count -eq $requiredDependencyDimensions.Count -and
            @($cacheDimensions | Group-Object -CaseSensitive | Where-Object Count -gt 1).Count -eq 0 -and
            $cache.exactSubjectRequired -eq $true -and
            $cache.artifactHashVerificationRequired -eq $true -and
            $cache.completeEvidenceRequired -eq $true -and
            $cache.separateStrataOnMismatch -eq $true
        foreach ($dimension in $requiredDependencyDimensions) {
            if ($cacheDimensions -cnotcontains $dimension) { $valid = $false }
        }
        $bridgeFields = @(
            'minimumCandidateUnits','minimumRepetitionsPerCriticalCombination','criticalMatrixRef',
            'functionalRuleRef','repeatabilityRuleRef','driftRuleRef','cachePlusBridgeMustMeetFullFloor'
        )
        if ($cache.bridge -isnot [pscustomobject]) { $valid = $false }
        else {
            Test-RequiredProperties -Object $cache.bridge -Names $bridgeFields -Context 'Phase 0 compatibility-cache bridge policy' -Errors $Errors
            Test-AllowedProperties -Object $cache.bridge -Names $bridgeFields -Context 'Phase 0 compatibility-cache bridge policy' -Errors $Errors
            $valid = $valid -and
                ($cache.bridge.minimumCandidateUnits -is [int] -or $cache.bridge.minimumCandidateUnits -is [long]) -and
                [int64]$cache.bridge.minimumCandidateUnits -ge 1 -and
                ($cache.bridge.minimumRepetitionsPerCriticalCombination -is [int] -or $cache.bridge.minimumRepetitionsPerCriticalCombination -is [long]) -and
                [int64]$cache.bridge.minimumRepetitionsPerCriticalCombination -ge 1 -and
                (Test-NonBlankString $cache.bridge.criticalMatrixRef) -and
                (Test-NonBlankString $cache.bridge.functionalRuleRef) -and
                (Test-NonBlankString $cache.bridge.repeatabilityRuleRef) -and
                (Test-NonBlankString $cache.bridge.driftRuleRef) -and
                $cache.bridge.cachePlusBridgeMustMeetFullFloor -eq $true
        }
    }

    $requiredDynamicClasses = @(
        'controlled-benchmark','sustained-performance','battery-standby','dock-reliability',
        'corporate-floor','agent-state','production-pilot','sentiment'
    )
    if ($policy.dynamicEvidence -isnot [pscustomobject]) { $valid = $false }
    else {
        $dynamicFields = @('classes','cachedRecordsCountTowardFloors','freshConcurrentEvidenceRequired')
        Test-RequiredProperties -Object $policy.dynamicEvidence -Names $dynamicFields -Context 'Phase 0 dynamic-evidence policy' -Errors $Errors
        Test-AllowedProperties -Object $policy.dynamicEvidence -Names $dynamicFields -Context 'Phase 0 dynamic-evidence policy' -Errors $Errors
        $dynamicClasses = @($policy.dynamicEvidence.classes)
        $valid = $valid -and $dynamicClasses.Count -eq $requiredDynamicClasses.Count -and
            @($dynamicClasses | Group-Object -CaseSensitive | Where-Object Count -gt 1).Count -eq 0 -and
            $policy.dynamicEvidence.cachedRecordsCountTowardFloors -eq $false -and
            $policy.dynamicEvidence.freshConcurrentEvidenceRequired -eq $true
        foreach ($className in $requiredDynamicClasses) {
            if ($dynamicClasses -cnotcontains $className) { $valid = $false }
        }
    }

    if ($policy.bootstrap -isnot [pscustomobject]) { $valid = $false }
    else {
        $bootstrapFields = @(
            'compatibilityFullFreshFloorRequired','controlFullFreshClassFloorRequired',
            'productionTelemetryCountsTowardFloor','singleAnchorRunSufficient'
        )
        Test-RequiredProperties -Object $policy.bootstrap -Names $bootstrapFields -Context 'Phase 0 bootstrap evidence policy' -Errors $Errors
        Test-AllowedProperties -Object $policy.bootstrap -Names $bootstrapFields -Context 'Phase 0 bootstrap evidence policy' -Errors $Errors
        $valid = $valid -and
            $policy.bootstrap.compatibilityFullFreshFloorRequired -eq $true -and
            $policy.bootstrap.controlFullFreshClassFloorRequired -eq $true -and
            $policy.bootstrap.productionTelemetryCountsTowardFloor -eq $false -and
            $policy.bootstrap.singleAnchorRunSufficient -eq $false
    }

    if (-not $valid) {
        Add-BlueprintError -Errors $Errors -Code 'PHASE0_EVIDENCE_REUSE_POLICY_INVALID' -Message 'The frozen Phase 0 evidence-reuse policy weakens documentary, cache, dynamic-evidence, or bootstrap requirements.'
    }
    return $valid
}

function Test-FrozenPhase0TestPlan {
    param(
        $TestPlan,
        [Parameter(Mandatory = $true)][string]$ExpectedManifestRef,
        [Parameter(Mandatory = $true)]$RecordMap,
        [Parameter(Mandatory = $true)][DateTimeOffset]$EvaluationTime,
        [Parameter(Mandatory = $true)][AllowEmptyCollection()][System.Collections.ArrayList]$Errors
    )

    $conditionIds = New-Object System.Collections.ArrayList
    if ($null -eq $TestPlan) { return @($conditionIds) }
    Test-RequiredProperties -Object $TestPlan -Names @(
        'planId', 'schemaVersion', 'status', 'qualificationTier', 'manifestRef',
        'thresholdPolicyRef', 'dependencyReviewRef', 'frozenAt',
        'approvedBy', 'samplingFloors', 'evidenceReusePolicy', 'tests'
    ) -Context 'frozen Phase 0 test plan' -Errors $Errors
    $omittedClassesProperty = $TestPlan.PSObject.Properties['omittedClasses']
    if ($null -eq $omittedClassesProperty -or $omittedClassesProperty.Value -isnot [System.Collections.IList]) {
        Add-BlueprintError -Errors $Errors -Code 'MISSING_REQUIRED_FIELD' -Message 'Frozen Phase 0 test plan requires an omittedClasses array, which may be empty only when every governed class is present.'
    }
    [DateTimeOffset]$frozenAt = [DateTimeOffset]::MinValue
    if ([string]$TestPlan.schemaVersion -cne '2.0.1' -or
        [string]$TestPlan.status -cne 'frozen' -or
        [string]$TestPlan.qualificationTier -cnotin @('full', 'delta', 'paper') -or
        [string]$TestPlan.manifestRef -cne $ExpectedManifestRef -or
        -not (Test-NonBlankString $TestPlan.approvedBy) -or
        -not [OperationsBlueprint.StrictRfc3339]::TryParse([string]$TestPlan.frozenAt, [ref]$frozenAt) -or
        $frozenAt -gt $EvaluationTime) {
        Add-BlueprintError -Errors $Errors -Code 'PHASE0_TEST_PLAN_NOT_FROZEN' -Message 'The test plan must be a non-future, approved, frozen v2.0.1 plan for the exact manifest and qualification tier.'
    }
    [void](Resolve-CanonicalRecord -RecordMap $RecordMap -Reference $TestPlan.thresholdPolicyRef `
        -ExpectedTypes @('threshold-policy') -Context 'Phase 0 test-plan threshold policy' -Errors $Errors)
    if (-not (Test-NonBlankString $TestPlan.dependencyReviewRef) -or
        $TestPlan.evidenceReusePolicy -isnot [pscustomobject]) {
        Add-BlueprintError -Errors $Errors -Code 'PHASE0_TEST_PLAN_DEPENDENCY_POLICY_MISSING' -Message 'The frozen test plan requires a dependency review and structured evidence-reuse policy.'
    }
    [void](Test-Phase0EvidenceReusePolicy -TestPlan $TestPlan -EvaluationTime $EvaluationTime -Errors $Errors)

    $floorDefinitions = [ordered]@{
        'component-identification' = @{ Units = 5; Runs = 1; PerRole = $true; Phase = 1 }
        'controlled-benchmark' = @{ Units = 3; Runs = 5; PerRole = $true; Phase = 3 }
        'sustained-performance' = @{ Units = 3; Runs = 3; PerRole = $true; Phase = 3 }
        'battery-standby' = @{ Units = 3; Runs = 3; PerRole = $true; Phase = 3 }
        'dock-reliability' = @{ Units = 3; Runs = 20; PerRole = $true; Phase = 3 }
        'application-compatibility' = @{ Units = 2; Runs = 2; PerRole = $false; Phase = 2 }
        'production-pilot' = @{ Units = 30; Runs = 10; PerRole = $false; Phase = 4 }
        'sentiment' = @{ Units = 24; Runs = 1; PerRole = $false; Phase = 4 }
        'corporate-floor' = @{ Units = 3; Runs = 3; PerRole = $true; Phase = 3 }
        'agent-state' = @{ Units = 3; Runs = 3; PerRole = $true; Phase = 3 }
    }
    foreach ($className in @($floorDefinitions.Keys)) {
        $floorProperty = if ($TestPlan.samplingFloors -is [pscustomobject]) {
            $TestPlan.samplingFloors.PSObject.Properties[[string]$className]
        }
        else { $null }
        if ($null -eq $floorProperty -or $floorProperty.Value -isnot [pscustomobject]) {
            Add-BlueprintError -Errors $Errors -Code 'PHASE0_SAMPLING_FLOOR_MISSING' -Message "The frozen test plan omits the $className class floor."
            continue
        }
        $floor = $floorProperty.Value
        Test-RequiredProperties -Object $floor -Names @(
            'minUnits', 'minRepetitionsPerUnit', 'perRole', 'samplingConcern',
            'selectionMethod', 'repetitionUnit'
        ) -Context "Phase 0 $className sampling floor" -Errors $Errors
        $expected = $floorDefinitions[$className]
        if (($floor.minUnits -isnot [int] -and $floor.minUnits -isnot [long]) -or
            ($floor.minRepetitionsPerUnit -isnot [int] -and $floor.minRepetitionsPerUnit -isnot [long]) -or
            [int64]$floor.minUnits -lt [int64]$expected.Units -or
            [int64]$floor.minRepetitionsPerUnit -lt [int64]$expected.Runs -or
            $floor.perRole -isnot [bool] -or $floor.perRole -ne [bool]$expected.PerRole -or
            -not (Test-NonBlankString $floor.samplingConcern) -or
            -not (Test-NonBlankString $floor.selectionMethod) -or
            -not (Test-NonBlankString $floor.repetitionUnit)) {
            Add-BlueprintError -Errors $Errors -Code 'PHASE0_SAMPLING_FLOOR_INVALID' -Message "The $className floor weakens or leaves blank its frozen units, repetitions, role rule, concern, selection, or repetition unit."
        }
    }

    $testRows = @($TestPlan.tests)
    $omittedRows = @($TestPlan.omittedClasses)
    if ($testRows.Count -eq 0) {
        Add-BlueprintError -Errors $Errors -Code 'PHASE0_TEST_DEFINITIONS_MISSING' -Message 'The frozen test plan requires at least one executable test definition.'
    }
    foreach ($testIdGroup in @($testRows | Group-Object -Property testId -CaseSensitive)) {
        if (-not (Test-NonBlankString $testIdGroup.Name) -or $testIdGroup.Count -gt 1) {
            Add-BlueprintError -Errors $Errors -Code 'PHASE0_TEST_DEFINITION_INVALID' -Message 'Test definition IDs must be nonblank and ordinally unique.'
        }
    }
    foreach ($test in $testRows) {
        Test-RequiredProperties -Object $test -Names @(
            'testId', 'testVersion', 'testPackVersion', 'phase', 'class', 'samplingFloorRef',
            'purpose', 'dependencies', 'conditions', 'appliesTo', 'expectedEvidence',
            'rules', 'stalenessDependencies'
        ) -Context 'Phase 0 test definition' -Errors $Errors
        $className = [string]$test.class
        if (-not $floorDefinitions.Contains($className) -or
            ($test.phase -isnot [int] -and $test.phase -isnot [long]) -or
            ($floorDefinitions.Contains($className) -and [int64]$test.phase -ne [int64]$floorDefinitions[$className].Phase) -or
            [string]$test.samplingFloorRef -cne "#/samplingFloors/$className") {
            Add-BlueprintError -Errors $Errors -Code 'PHASE0_TEST_DEFINITION_INVALID' -Message 'Every test must bind a recognized class to its exact phase and frozen sampling-floor pointer.'
        }
        $localConditionIds = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::Ordinal)
        foreach ($condition in @($test.conditions)) {
            if ($condition -isnot [pscustomobject] -or
                -not (Test-NonBlankString $condition.conditionId) -or
                -not (Test-NonBlankString $condition.description)) {
                Add-BlueprintError -Errors $Errors -Code 'PHASE0_TEST_CONDITION_INVALID' -Message 'Every test condition requires a nonblank ID and description.'
            }
            elseif (-not $localConditionIds.Add([string]$condition.conditionId)) {
                Add-BlueprintError -Errors $Errors -Code 'PHASE0_TEST_CONDITION_INVALID' -Message 'Condition IDs must be ordinally unique within each frozen test definition.'
            }
            elseif (@($conditionIds) -cnotcontains [string]$condition.conditionId) {
                [void]$conditionIds.Add([string]$condition.conditionId)
            }
        }
        $appliesTo = @($test.appliesTo)
        if ($appliesTo.Count -eq 0 -or
            @($appliesTo | Where-Object { $_ -isnot [string] -or [string]$_ -cnotin @('candidate','incumbent','sibling-or-alternative') }).Count -gt 0 -or
            @($appliesTo | Group-Object -CaseSensitive | Where-Object Count -gt 1).Count -gt 0 -or
            ([int64]$test.phase -eq 3 -and
             (@($appliesTo | Where-Object { [string]$_ -cin @('candidate','incumbent','sibling-or-alternative') }).Count -ne 3))) {
            Add-BlueprintError -Errors $Errors -Code 'PHASE0_TEST_DEFINITION_INVALID' -Message 'Each frozen test requires an ordinally unique canonical appliesTo role set; Phase 3 requires candidate, incumbent, and sibling-or-alternative.'
        }
    }
    foreach ($omittedGroup in @($omittedRows | Group-Object -Property class -CaseSensitive)) {
        if (-not $floorDefinitions.Contains([string]$omittedGroup.Name) -or $omittedGroup.Count -gt 1) {
            Add-BlueprintError -Errors $Errors -Code 'PHASE0_CLASS_ACCOUNTING_INVALID' -Message 'Omitted test classes must be recognized and ordinally unique.'
        }
    }
    foreach ($omitted in $omittedRows) {
        Test-RequiredProperties -Object $omitted -Names @('class', 'rationale', 'dependenciesUnaffected', 'reviewEvidenceRef') -Context 'Phase 0 omitted class' -Errors $Errors
        if (-not (Test-NonBlankString $omitted.rationale) -or
            $omitted.dependenciesUnaffected -ne $true -or
            -not (Test-NonBlankString $omitted.reviewEvidenceRef)) {
            Add-BlueprintError -Errors $Errors -Code 'PHASE0_CLASS_ACCOUNTING_INVALID' -Message 'Every omitted class requires a rationale, unaffected-dependencies attestation, and review evidence.'
        }
    }
    foreach ($className in @($floorDefinitions.Keys)) {
        $tested = @($testRows | Where-Object { [string]$_.class -ceq [string]$className }).Count -gt 0
        $omitted = @($omittedRows | Where-Object { [string]$_.class -ceq [string]$className }).Count -eq 1
        if ($tested -eq $omitted) {
            Add-BlueprintError -Errors $Errors -Code 'PHASE0_CLASS_ACCOUNTING_INVALID' -Message "Test class $className must be either executable or explicitly omitted, but never both or neither."
        }
    }
    return @($conditionIds)
}

function Get-CompatibilityCacheAdmissionSubjectDigest {
    param([Parameter(Mandatory = $true)]$AdmissionRecord)

    $payload = if ($AdmissionRecord.payload -is [pscustomobject]) { $AdmissionRecord.payload } else { $AdmissionRecord }
    $excluded = @(
        'admissionSubjectDigest','signedSubjectDigest','admissionArtifactRef','admissionArtifactDigest',
        'attestationRef','attestationDigest','attestationSubjectDigest','attestationStatus',
        'signatureRef','signatureDigest','signatureStatus'
    )
    $subject = [ordered]@{}
    foreach ($property in @($payload.PSObject.Properties)) {
        if ($excluded -ccontains [string]$property.Name) { continue }
        $subject[[string]$property.Name] = $property.Value
    }
    return Get-CanonicalPayloadDigest -Payload ([pscustomobject]$subject)
}

function Resolve-CompatibilityCacheDigestBindings {
    param(
        [AllowNull()]$Bindings,
        [Parameter(Mandatory = $true)]$RecordMap,
        [Parameter(Mandatory = $true)][string]$ExpectedType,
        [Parameter(Mandatory = $true)][string]$Context,
        [Parameter(Mandatory = $true)][AllowEmptyCollection()][System.Collections.ArrayList]$Errors
    )

    $records = New-Object System.Collections.ArrayList
    $refs = [System.Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal)
    $valid = $Bindings -is [System.Collections.IList] -and @($Bindings).Count -gt 0
    foreach ($binding in @($Bindings)) {
        if ($binding -isnot [pscustomobject]) { $valid = $false; continue }
        Test-RequiredProperties -Object $binding -Names @('recordRef','contentDigest') -Context $Context -Errors $Errors
        Test-AllowedProperties -Object $binding -Names @('recordRef','contentDigest') -Context $Context -Errors $Errors
        $recordRef = [string]$binding.recordRef
        if (-not (Test-NonBlankString $recordRef) -or $recordRef.Contains('#') -or
            -not $refs.Add($recordRef) -or -not (Test-Sha256Token $binding.contentDigest) -or
            -not $RecordMap.ContainsKey($recordRef)) {
            $valid = $false
            continue
        }
        $record = $RecordMap[$recordRef]
        if ([string]$record.recordType -cne $ExpectedType -or
            [string]$record.contentDigest -cne [string]$binding.contentDigest) {
            $valid = $false
            continue
        }
        [void]$records.Add($record)
    }
    return [pscustomobject]@{ Valid = $valid; Records = @($records); Refs = $refs }
}

function Test-CompatibilityCacheAdmissionSemantics {
    param(
        [Parameter(Mandatory = $true)]$Distribution,
        [Parameter(Mandatory = $true)]$CachedEvidence,
        [Parameter(Mandatory = $true)]$Manifest,
        [Parameter(Mandatory = $true)]$Phase0TestPlan,
        [Parameter(Mandatory = $true)]$ThresholdPolicy,
        [Parameter(Mandatory = $true)]$RecordMap,
        [AllowNull()]$CurrentRelease,
        [Parameter(Mandatory = $true)][DateTimeOffset]$EvaluationTime,
        [ValidateSet('TEST','PRODUCTION')][string]$ValidationProfile = 'PRODUCTION',
        [Parameter(Mandatory = $true)][AllowEmptyCollection()][System.Collections.ArrayList]$Errors
    )

    $initialErrorCount = $Errors.Count
    $ValidationProfile = ([string]$ValidationProfile).ToUpperInvariant()
    $admission = Resolve-CanonicalRecord -RecordMap $RecordMap -Reference $Distribution.compatibilityCacheAdmissionRef `
        -ExpectedTypes @('compatibility-cache-admission-record') -Context 'compatibility cache admission' -Errors $Errors
    if ($null -eq $admission -or [string]$admission.recordType -cne 'compatibility-cache-admission-record') {
        Add-BlueprintError -Errors $Errors -Code 'COMPATIBILITY_CACHE_ADMISSION_INVALID' -Message 'The cache consumer lacks one exact typed admission wrapper.'
        return [pscustomobject]@{ Valid = $false; Admission = $null; HistoricalRelease = $null; CurrentRelease = $null }
    }

    $fields = @(
        'schemaVersion','recordStage','status','cachedEvidenceRef','cachedEvidenceDigest',
        'historicalEvidenceReleaseRef','historicalEvidenceReleaseDigest','historicalEvidenceReleaseSubjectDigest',
        'currentManifestRef','currentManifestDigest','currentTestPlanRef','currentTestPlanDigest',
        'currentThresholdPolicyRef','currentThresholdPolicyDigest','bridgeEvidenceBindings',
        'bridgeDistributionBindings','dependencySnapshotRef','dependencySnapshotDigest','dependencyStatus',
        'currentConsumerRef','currentEvidenceReleaseRef','currentEvidenceReleaseSubjectDigest',
        'bridgeAcceptedAt','admittedAt','issuedAt','expiresAt','freshnessPolicyRef','freshnessPolicyDigest',
        'freshnessMaxAgeMinutes','admissionSubjectDigest','admissionArtifactRef','admissionArtifactDigest',
        'attestationRef','attestationDigest','attestationSubjectDigest','attestationStatus','signedSubjectDigest',
        'signatureSignerPrincipalId','signatureKeyRef','signatureKeySpkiDigest','signatureKeyBindingRef',
        'signatureKeyBindingDigest','signatureKeyBindingStatus','signatureKeyBindingCheckedAt',
        'signatureRef','signatureDigest','signatureStatus','issuedByRole','issuedByPrincipalId',
        'recordProducerPrincipalId','affectedRequesterPrincipalId','roleBindingRef','roleBindingDigest',
        'roleBindingReadbackRef','roleBindingReadbackDigest','roleBindingReadbackPolicyRef',
        'roleBindingReadbackPolicyDigest','roleBindingReadbackMaxAgeMinutes','revocationStatus',
        'revocationEvidenceRef','revocationEvidenceDigest','revocationCheckedAt','authorizationEffect'
    )
    Test-RequiredProperties -Object $admission -Names $fields -Context 'compatibility cache admission' -Errors $Errors

    $historicalRelease = Resolve-CanonicalRecord -RecordMap $RecordMap -Reference $admission.historicalEvidenceReleaseRef `
        -ExpectedTypes @('evidence-release') -Context 'historical compatibility evidence release' -Errors $Errors
    $resolvedCachedEvidence = Resolve-CanonicalRecord -RecordMap $RecordMap -Reference $admission.cachedEvidenceRef `
        -ExpectedTypes @('evidence-record') -Context 'historical compatibility evidence' -Errors $Errors
    $resolvedCurrentRelease = Resolve-CanonicalRecord -RecordMap $RecordMap -Reference $admission.currentEvidenceReleaseRef `
        -ExpectedTypes @('evidence-release') -Context 'current compatibility evidence release' -Errors $Errors
    $historicalDistribution = if ($null -ne $resolvedCachedEvidence) {
        Resolve-CanonicalRecord -RecordMap $RecordMap -Reference $resolvedCachedEvidence.distributionRef `
            -ExpectedTypes @('distribution-record') -Context 'historical compatibility distribution' -Errors $Errors
    }
    else { $null }

    $bridgeEvidenceResult = Resolve-CompatibilityCacheDigestBindings -Bindings $admission.bridgeEvidenceBindings `
        -RecordMap $RecordMap -ExpectedType 'evidence-record' -Context 'compatibility cache bridge evidence binding' -Errors $Errors
    $bridgeDistributionResult = Resolve-CompatibilityCacheDigestBindings -Bindings $admission.bridgeDistributionBindings `
        -RecordMap $RecordMap -ExpectedType 'distribution-record' -Context 'compatibility cache bridge distribution binding' -Errors $Errors
    $bridgeEvidenceRecords = @($bridgeEvidenceResult.Records)
    $bridgeDistributionRecords = @($bridgeDistributionResult.Records)

    $allInputRefs = [System.Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal)
    $distinctnessValid = $true
    foreach ($inputRef in @(
        [string]$admission.recordId,[string]$admission.cachedEvidenceRef,
        [string]$admission.historicalEvidenceReleaseRef,[string]$admission.currentEvidenceReleaseRef,
        [string]$admission.currentConsumerRef
    ) + @($admission.bridgeEvidenceBindings | ForEach-Object { [string]$_.recordRef }) +
        @($admission.bridgeDistributionBindings | ForEach-Object { [string]$_.recordRef })) {
        if (-not (Test-NonBlankString $inputRef) -or -not $allInputRefs.Add($inputRef)) { $distinctnessValid = $false }
    }
    if ($null -ne $historicalDistribution -and
        [string]$historicalDistribution.recordId -ceq [string]$admission.currentConsumerRef) {
        $distinctnessValid = $false
    }
    if (([string]$admission.dependencySnapshotRef).Contains('#') -or
        -not $allInputRefs.Add([string]$admission.dependencySnapshotRef)) {
        $distinctnessValid = $false
    }

    $authorityBindingValid = -not ([string]$admission.currentManifestRef).Contains('#') -and
        -not ([string]$admission.currentTestPlanRef).Contains('#') -and
        -not ([string]$admission.currentThresholdPolicyRef).Contains('#') -and
        [string]$admission.currentManifestRef -ceq [string]$Manifest.recordId -and
        [string]$admission.currentManifestDigest -ceq [string]$Manifest.contentDigest -and
        [string]$admission.currentTestPlanRef -ceq [string]$Phase0TestPlan.recordId -and
        [string]$admission.currentTestPlanDigest -ceq [string]$Phase0TestPlan.contentDigest -and
        [string]$admission.currentThresholdPolicyRef -ceq [string]$ThresholdPolicy.recordId -and
        [string]$admission.currentThresholdPolicyDigest -ceq [string]$ThresholdPolicy.contentDigest

    $releaseBindingValid = $null -ne $historicalRelease -and $null -ne $resolvedCachedEvidence -and
        $null -ne $historicalDistribution -and $null -ne $resolvedCurrentRelease -and $null -ne $CurrentRelease -and
        [string]$resolvedCachedEvidence.recordId -ceq [string]$CachedEvidence.recordId -and
        [string]$resolvedCachedEvidence.contentDigest -ceq [string]$CachedEvidence.contentDigest -and
        [string]$admission.cachedEvidenceDigest -ceq [string]$resolvedCachedEvidence.contentDigest -and
        [string]$admission.historicalEvidenceReleaseDigest -ceq [string]$historicalRelease.contentDigest -and
        [string]$admission.historicalEvidenceReleaseSubjectDigest -ceq [string]$historicalRelease.releaseSubjectDigest -and
        [string]$historicalRelease.releaseSubjectDigest -ceq [string](Get-EvidenceReleaseSubjectDigest -ReleaseRecord $historicalRelease) -and
        [string]$resolvedCachedEvidence.evidenceReleaseRef -ceq [string]$historicalRelease.recordId -and
        [string]$resolvedCachedEvidence.distributionRef -ceq [string]$historicalDistribution.recordId -and
        [string]$historicalDistribution.sourceEvidenceRef -ceq [string]$resolvedCachedEvidence.recordId -and
        [string]$historicalDistribution.sourceEvidenceDigest -ceq [string]$resolvedCachedEvidence.contentDigest -and
        [string]$historicalDistribution.sourceEvidenceReleaseRef -ceq [string]$historicalRelease.recordId -and
        [string]$historicalDistribution.sourceEvidenceReleaseSubjectDigest -ceq [string]$historicalRelease.releaseSubjectDigest -and
        @($historicalRelease.memberRecordIds) -ccontains [string]$resolvedCachedEvidence.recordId -and
        @($historicalRelease.memberRecordIds) -ccontains [string]$historicalDistribution.recordId -and
        [string]$historicalRelease.freshnessBinding.observedAt -ceq [string]$resolvedCachedEvidence.freshnessBinding.observedAt -and
        [string]$historicalRelease.freshnessBinding.admittedAt -ceq [string]$resolvedCachedEvidence.freshnessBinding.admittedAt -and
        [string]$historicalRelease.freshnessBinding.policyRef -ceq [string]$resolvedCachedEvidence.freshnessBinding.policyRef -and
        [string]$historicalRelease.freshnessBinding.maxAgeDays -ceq [string]$resolvedCachedEvidence.freshnessBinding.maxAgeDays -and
        [string]$historicalRelease.freshnessBinding.dependencySnapshotRef -ceq [string]$resolvedCachedEvidence.freshnessBinding.dependencySnapshotRef -and
        [string]$historicalRelease.freshnessBinding.dependencySnapshotDigest -ceq [string]$resolvedCachedEvidence.freshnessBinding.dependencySnapshotDigest -and
        [string]$historicalRelease.freshnessBinding.dependencyStatus -ceq 'MATCH' -and
        [string]$resolvedCurrentRelease.recordId -ceq [string]$CurrentRelease.recordId -and
        [string]$resolvedCurrentRelease.contentDigest -ceq [string]$CurrentRelease.contentDigest -and
        [string]$admission.currentEvidenceReleaseSubjectDigest -ceq [string]$resolvedCurrentRelease.releaseSubjectDigest -and
        [string]$resolvedCurrentRelease.releaseSubjectDigest -ceq [string](Get-EvidenceReleaseSubjectDigest -ReleaseRecord $resolvedCurrentRelease) -and
        @($resolvedCurrentRelease.memberRecordIds) -ccontains [string]$admission.recordId -and
        @($resolvedCurrentRelease.memberRecordIds) -ccontains [string]$Distribution.recordId

    $consumerBindingValid = [string]$Distribution.testClass -ceq 'application-compatibility' -and
        [string]$Distribution.compatibilityCacheAdmissionRef -ceq [string]$admission.recordId -and
        [string]$Distribution.compatibilityCacheAdmissionDigest -ceq [string]$admission.contentDigest -and
        [string]$admission.currentConsumerRef -ceq [string]$Distribution.recordId -and
        [string]$Distribution.sourceEvidenceRef -ceq [string]$resolvedCachedEvidence.recordId -and
        [string]$Distribution.sourceEvidenceDigest -ceq [string]$resolvedCachedEvidence.contentDigest -and
        [string]$Distribution.sourceEvidenceReleaseRef -ceq [string]$historicalRelease.recordId -and
        [string]$Distribution.sourceEvidenceReleaseSubjectDigest -ceq [string]$historicalRelease.releaseSubjectDigest -and
        [string]$Distribution.metricId -ceq [string]$historicalDistribution.metricId -and
        [string]$Distribution.unit -ceq [string]$historicalDistribution.unit -and
        [string]$Distribution.statisticDirection -ceq [string]$historicalDistribution.statisticDirection -and
        [string]$Distribution.baselineFingerprint -ceq [string]$historicalDistribution.baselineFingerprint -and
        [string]$Distribution.testClass -ceq [string]$historicalDistribution.testClass -and
        [int64]$Distribution.unitCount -eq [int64]$historicalDistribution.unitCount -and
        [int64]$Distribution.runCount -eq [int64]$historicalDistribution.runCount -and
        (Test-CanonicalValueEqual @($Distribution.perUnitRunCounts) @($historicalDistribution.perUnitRunCounts)) -and
        (Test-CanonicalValueEqual $Distribution.median $historicalDistribution.median) -and
        (Test-CanonicalValueEqual $Distribution.spread $historicalDistribution.spread) -and
        (Test-CanonicalValueEqual $Distribution.runVariation $historicalDistribution.runVariation) -and
        (Test-CanonicalValueEqual $Distribution.coverage $historicalDistribution.coverage) -and
        (Test-CanonicalValueEqual @($Distribution.missingResults) @($historicalDistribution.missingResults)) -and
        (Test-CanonicalValueEqual @($Distribution.outliers) @($historicalDistribution.outliers)) -and
        (Test-CanonicalValueEqual @($Distribution.exclusions) @($historicalDistribution.exclusions)) -and
        [string]$Distribution.samplingFloorStatus -ceq [string]$historicalDistribution.samplingFloorStatus -and
        [string]$Distribution.distributionStatus -ceq [string]$historicalDistribution.distributionStatus

    $dependencyRecord = if (-not ([string]$admission.dependencySnapshotRef).Contains('#') -and
        $RecordMap.ContainsKey([string]$admission.dependencySnapshotRef)) {
        $RecordMap[[string]$admission.dependencySnapshotRef]
    }
    else { $null }
    $dependencySnapshotDigest = if ($null -ne $dependencyRecord) {
        Get-CanonicalPayloadDigest -Payload $dependencyRecord.dependencySnapshot
    }
    else { '' }
    $dependencyValid = $null -ne $dependencyRecord -and
        [string]$dependencyRecord.recordType -ceq 'platform-baseline-record' -and
        [string]$dependencyRecord.dependencyStatus -ceq 'CURRENT' -and
        [string]$dependencyRecord.dependencySnapshotDigest -ceq [string]$dependencySnapshotDigest -and
        [string]$admission.dependencySnapshotDigest -ceq [string]$dependencyRecord.contentDigest -and
        [string]$admission.dependencyStatus -ceq 'MATCH'

    [DateTimeOffset]$historicalObservedAt = [DateTimeOffset]::MinValue
    [DateTimeOffset]$historicalAdmittedAt = [DateTimeOffset]::MinValue
    [DateTimeOffset]$historicalReleasedAt = [DateTimeOffset]::MinValue
    [DateTimeOffset]$bridgeAcceptedAt = [DateTimeOffset]::MinValue
    [DateTimeOffset]$admittedAt = [DateTimeOffset]::MinValue
    [DateTimeOffset]$issuedAt = [DateTimeOffset]::MinValue
    [DateTimeOffset]$expiresAt = [DateTimeOffset]::MinValue
    [DateTimeOffset]$revocationCheckedAt = [DateTimeOffset]::MinValue
    [DateTimeOffset]$keyBindingCheckedAt = [DateTimeOffset]::MinValue
    [DateTimeOffset]$currentReleasedAt = [DateTimeOffset]::MinValue
    [DateTimeOffset]$manifestFrozenAt = [DateTimeOffset]::MinValue
    [DateTimeOffset]$planFrozenAt = [DateTimeOffset]::MinValue
    [DateTimeOffset]$policyFrozenAt = [DateTimeOffset]::MinValue
    [DateTimeOffset]$dependencyCapturedAt = [DateTimeOffset]::MinValue
    [DateTimeOffset]$dependencyValidFrom = [DateTimeOffset]::MinValue
    [DateTimeOffset]$dependencyValidUntil = [DateTimeOffset]::MinValue
    $timesValid = [OperationsBlueprint.StrictRfc3339]::TryParse([string]$resolvedCachedEvidence.timestamp, [ref]$historicalObservedAt) -and
        [OperationsBlueprint.StrictRfc3339]::TryParse([string]$resolvedCachedEvidence.admission.admittedAt, [ref]$historicalAdmittedAt) -and
        [OperationsBlueprint.StrictRfc3339]::TryParse([string]$historicalRelease.releasedAt, [ref]$historicalReleasedAt) -and
        [OperationsBlueprint.StrictRfc3339]::TryParse([string]$admission.bridgeAcceptedAt, [ref]$bridgeAcceptedAt) -and
        [OperationsBlueprint.StrictRfc3339]::TryParse([string]$admission.admittedAt, [ref]$admittedAt) -and
        [OperationsBlueprint.StrictRfc3339]::TryParse([string]$admission.issuedAt, [ref]$issuedAt) -and
        [OperationsBlueprint.StrictRfc3339]::TryParse([string]$admission.expiresAt, [ref]$expiresAt) -and
        [OperationsBlueprint.StrictRfc3339]::TryParse([string]$admission.revocationCheckedAt, [ref]$revocationCheckedAt) -and
        [OperationsBlueprint.StrictRfc3339]::TryParse([string]$admission.signatureKeyBindingCheckedAt, [ref]$keyBindingCheckedAt) -and
        [OperationsBlueprint.StrictRfc3339]::TryParse([string]$resolvedCurrentRelease.releasedAt, [ref]$currentReleasedAt) -and
        [OperationsBlueprint.StrictRfc3339]::TryParse([string]$Manifest.frozenAt, [ref]$manifestFrozenAt) -and
        [OperationsBlueprint.StrictRfc3339]::TryParse([string]$Phase0TestPlan.frozenAt, [ref]$planFrozenAt) -and
        [OperationsBlueprint.StrictRfc3339]::TryParse([string]$ThresholdPolicy.frozenAt, [ref]$policyFrozenAt) -and
        [OperationsBlueprint.StrictRfc3339]::TryParse([string]$dependencyRecord.capturedAt, [ref]$dependencyCapturedAt) -and
        [OperationsBlueprint.StrictRfc3339]::TryParse([string]$dependencyRecord.validFrom, [ref]$dependencyValidFrom) -and
        [OperationsBlueprint.StrictRfc3339]::TryParse([string]$dependencyRecord.validUntil, [ref]$dependencyValidUntil) -and
        $historicalObservedAt -lt $historicalAdmittedAt -and $historicalAdmittedAt -lt $historicalReleasedAt -and
        $historicalReleasedAt -lt $bridgeAcceptedAt -and
        $manifestFrozenAt -lt $bridgeAcceptedAt -and $planFrozenAt -lt $bridgeAcceptedAt -and
        $policyFrozenAt -lt $bridgeAcceptedAt -and $bridgeAcceptedAt -lt $admittedAt -and
        $admittedAt -le $issuedAt -and $issuedAt -lt $currentReleasedAt -and
        $admittedAt -le $revocationCheckedAt -and $revocationCheckedAt -le $issuedAt -and
        $admittedAt -le $keyBindingCheckedAt -and $keyBindingCheckedAt -le $issuedAt -and
        $issuedAt -le $EvaluationTime -and
        $currentReleasedAt -le $EvaluationTime -and $expiresAt -gt $EvaluationTime -and $expiresAt -gt $issuedAt -and
        $manifestFrozenAt -lt $dependencyCapturedAt -and $planFrozenAt -lt $dependencyCapturedAt -and
        $policyFrozenAt -lt $dependencyCapturedAt -and $dependencyCapturedAt -le $EvaluationTime -and
        $dependencyValidFrom -le $EvaluationTime -and $dependencyValidUntil -gt $EvaluationTime
    $dependencyValid = $dependencyValid -and $timesValid

    $cachePolicy = $Phase0TestPlan.evidenceReusePolicy.compatibilityCache
    $bridgePolicy = if ($cachePolicy -is [pscustomobject]) { $cachePolicy.bridge } else { $null }
    $cacheAgeValid = $cachePolicy -is [pscustomobject] -and $bridgePolicy -is [pscustomobject] -and
        ($cachePolicy.maximumAgeDays -is [int] -or $cachePolicy.maximumAgeDays -is [long]) -and
        [int64]$cachePolicy.maximumAgeDays -gt 0 -and
        ($EvaluationTime - $historicalObservedAt).TotalDays -le [int64]$cachePolicy.maximumAgeDays

    $cachedControlRole = [string]$resolvedCachedEvidence.controlRole
    $manifestControl = if ($Manifest.controls -is [pscustomobject] -and
        @('incumbent','sibling-or-alternative') -ccontains $cachedControlRole -and
        $null -ne $Manifest.controls.PSObject.Properties[$cachedControlRole]) {
        $Manifest.controls.PSObject.Properties[$cachedControlRole].Value
    }
    else { $null }
    $manifestEvidencePlan = if ($manifestControl -is [pscustomobject]) { $manifestControl.evidencePlan } else { $null }
    $manifestBridge = if ($manifestEvidencePlan -is [pscustomobject]) { $manifestEvidencePlan.bridge } else { $null }
    $bridgePlanValid = $manifestEvidencePlan -is [pscustomobject] -and $manifestBridge -is [pscustomobject] -and
        [string]$manifestEvidencePlan.mode -ceq 'cache-reuse' -and
        [string]$manifestEvidencePlan.reusePolicyRef -ceq (([string]$Phase0TestPlan.recordId) + '#/evidenceReusePolicy') -and
        [string]$manifestEvidencePlan.cachedReleaseRef -ceq [string]$historicalRelease.recordId -and
        [string]$manifestEvidencePlan.dependencySnapshotRef -ceq [string]$admission.dependencySnapshotRef -and
        $manifestEvidencePlan.withinMaximumAge -eq $true -and
        ($manifestBridge.candidateUnits -is [int] -or $manifestBridge.candidateUnits -is [long]) -and
        ($manifestBridge.repetitionsPerCriticalCombination -is [int] -or $manifestBridge.repetitionsPerCriticalCombination -is [long]) -and
        [int64]$manifestBridge.candidateUnits -ge [int64]$bridgePolicy.minimumCandidateUnits -and
        [int64]$manifestBridge.repetitionsPerCriticalCombination -ge [int64]$bridgePolicy.minimumRepetitionsPerCriticalCombination -and
        [string]$manifestBridge.criticalMatrixRef -ceq [string]$bridgePolicy.criticalMatrixRef -and
        [string]$manifestBridge.functionalRuleRef -ceq [string]$bridgePolicy.functionalRuleRef -and
        [string]$manifestBridge.repeatabilityRuleRef -ceq [string]$bridgePolicy.repeatabilityRuleRef -and
        [string]$manifestBridge.driftRuleRef -ceq [string]$bridgePolicy.driftRuleRef -and
        (Test-NonBlankString $manifestBridge.acceptanceEvidenceRef) -and
        $manifestBridge.accepted -eq $true -and
        $manifestBridge.cachePlusBridgeMeetsFloor -eq $true

    $bridgeValid = $bridgePlanValid -and $bridgeEvidenceResult.Valid -and $bridgeDistributionResult.Valid -and
        $bridgeEvidenceRecords.Count -eq $bridgeDistributionRecords.Count -and $bridgeEvidenceRecords.Count -gt 0
    $bridgeDistributionByEvidence = [System.Collections.Generic.Dictionary[string,object]]::new([StringComparer]::Ordinal)
    foreach ($bridgeDistribution in $bridgeDistributionRecords) {
        if (-not (Test-NonBlankString $bridgeDistribution.sourceEvidenceRef) -or
            $bridgeDistributionByEvidence.ContainsKey([string]$bridgeDistribution.sourceEvidenceRef)) {
            $bridgeValid = $false
        }
        else { $bridgeDistributionByEvidence.Add([string]$bridgeDistribution.sourceEvidenceRef, $bridgeDistribution) }
    }
    $bridgeUnitRefs = [System.Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal)
    $combinedUnitRefs = [System.Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal)
    foreach ($unit in @($historicalDistribution.perUnitRunCounts)) {
        if (Test-NonBlankString $unit.unitRef) { [void]$combinedUnitRefs.Add([string]$unit.unitRef) }
    }
    [int64]$bridgeAcceptanceEvidenceCount = 0
    foreach ($bridgeEvidence in $bridgeEvidenceRecords) {
        if (-not $bridgeDistributionByEvidence.ContainsKey([string]$bridgeEvidence.recordId)) {
            $bridgeValid = $false
            continue
        }
        $bridgeDistribution = $bridgeDistributionByEvidence[[string]$bridgeEvidence.recordId]
        [DateTimeOffset]$bridgeObservedAt = [DateTimeOffset]::MinValue
        [DateTimeOffset]$bridgeAdmittedAt = [DateTimeOffset]::MinValue
        [DateTimeOffset]$bridgeDistributionCreatedAt = [DateTimeOffset]::MinValue
        $bridgeValid = $bridgeValid -and
            [string]$bridgeEvidence.provenance -ceq 'T0' -and
            [string]$bridgeEvidence.evidenceUse -ceq 'gate-or-verdict' -and
            [string]$bridgeEvidence.controlRole -ceq 'candidate' -and
            [string]$bridgeEvidence.admission.mode -ceq 'fresh' -and
            [string]$bridgeEvidence.distributionRef -ceq [string]$bridgeDistribution.recordId -and
            [string]$bridgeEvidence.evidenceReleaseRef -ceq [string]$resolvedCurrentRelease.recordId -and
            [string]$bridgeEvidence.subjectRef -ceq [string]$resolvedCachedEvidence.subjectRef -and
            [string]$bridgeEvidence.testRef -ceq [string]$resolvedCachedEvidence.testRef -and
            [string]$bridgeEvidence.conditionRef -ceq [string]$resolvedCachedEvidence.conditionRef -and
            [string]$bridgeEvidence.baselineFingerprint -ceq [string]$resolvedCachedEvidence.baselineFingerprint -and
            [string]$bridgeEvidence.testPlanRef -ceq [string]$Phase0TestPlan.recordId -and
            [string]$bridgeEvidence.freshnessBinding.dependencySnapshotRef -ceq (([string]$admission.dependencySnapshotRef) + '#/dependencySnapshot') -and
            [string]$bridgeEvidence.freshnessBinding.dependencySnapshotDigest -ceq [string]$dependencySnapshotDigest -and
            [string]$bridgeEvidence.freshnessBinding.dependencyStatus -ceq 'MATCH' -and
            [string]$bridgeDistribution.testClass -ceq 'application-compatibility' -and
            [string]$bridgeDistribution.sourceEvidenceDigest -ceq [string]$bridgeEvidence.contentDigest -and
            [string]$bridgeDistribution.sourceEvidenceReleaseRef -ceq [string]$resolvedCurrentRelease.recordId -and
            [string]$bridgeDistribution.sourceEvidenceReleaseSubjectDigest -ceq [string]$resolvedCurrentRelease.releaseSubjectDigest -and
            @($resolvedCurrentRelease.memberRecordIds) -ccontains [string]$bridgeEvidence.recordId -and
            @($resolvedCurrentRelease.memberRecordIds) -ccontains [string]$bridgeDistribution.recordId -and
            [OperationsBlueprint.StrictRfc3339]::TryParse([string]$bridgeEvidence.timestamp, [ref]$bridgeObservedAt) -and
            [OperationsBlueprint.StrictRfc3339]::TryParse([string]$bridgeEvidence.admission.admittedAt, [ref]$bridgeAdmittedAt) -and
            [OperationsBlueprint.StrictRfc3339]::TryParse([string]$bridgeDistribution.validFrom, [ref]$bridgeDistributionCreatedAt) -and
            $historicalReleasedAt -lt $bridgeObservedAt -and
            $manifestFrozenAt -lt $bridgeObservedAt -and $planFrozenAt -lt $bridgeObservedAt -and
            $policyFrozenAt -lt $bridgeObservedAt -and $bridgeObservedAt -lt $bridgeAdmittedAt -and
            $bridgeAdmittedAt -lt $bridgeDistributionCreatedAt -and
            $bridgeDistributionCreatedAt -lt $bridgeAcceptedAt

        if ([string]$bridgeEvidence.recordId -ceq [string]$manifestBridge.acceptanceEvidenceRef) {
            $bridgeAcceptanceEvidenceCount++
            $ruleResult = if ($bridgeEvidence.result -is [pscustomobject]) {
                $bridgeEvidence.result.compatibilityCacheBridge
            }
            else { $null }
            $ruleResultFields = @(
                'status','criticalMatrixRef','criticalMatrixPassed','functionalRuleRef','functionalRulePassed',
                'repeatabilityRuleRef','repeatabilityRulePassed','driftRuleRef','driftRulePassed',
                'candidateUnits','repetitionsPerCriticalCombination','cachePlusBridgeMeetsFloor'
            )
            if ($ruleResult -isnot [pscustomobject]) {
                $bridgeValid = $false
            }
            else {
                Test-RequiredProperties -Object $ruleResult -Names $ruleResultFields -Context 'compatibility bridge rule result' -Errors $Errors
                Test-AllowedProperties -Object $ruleResult -Names $ruleResultFields -Context 'compatibility bridge rule result' -Errors $Errors
                $bridgeValid = $bridgeValid -and
                    [string]$ruleResult.status -ceq 'PASS' -and
                    [string]$ruleResult.criticalMatrixRef -ceq [string]$bridgePolicy.criticalMatrixRef -and
                    $ruleResult.criticalMatrixPassed -eq $true -and
                    [string]$ruleResult.functionalRuleRef -ceq [string]$bridgePolicy.functionalRuleRef -and
                    $ruleResult.functionalRulePassed -eq $true -and
                    [string]$ruleResult.repeatabilityRuleRef -ceq [string]$bridgePolicy.repeatabilityRuleRef -and
                    $ruleResult.repeatabilityRulePassed -eq $true -and
                    [string]$ruleResult.driftRuleRef -ceq [string]$bridgePolicy.driftRuleRef -and
                    $ruleResult.driftRulePassed -eq $true -and
                    ($ruleResult.candidateUnits -is [int] -or $ruleResult.candidateUnits -is [long]) -and
                    ($ruleResult.repetitionsPerCriticalCombination -is [int] -or $ruleResult.repetitionsPerCriticalCombination -is [long]) -and
                    [int64]$ruleResult.candidateUnits -eq [int64]$manifestBridge.candidateUnits -and
                    [int64]$ruleResult.repetitionsPerCriticalCombination -eq [int64]$manifestBridge.repetitionsPerCriticalCombination -and
                    $ruleResult.cachePlusBridgeMeetsFloor -eq $true
            }
        }
        [void](Test-DistributionPhase0FloorBinding -Distribution $bridgeDistribution -Phase0TestPlan $Phase0TestPlan `
            -ExpectedEvidenceRecord $bridgeEvidence -ExpectedTestPlanRef ([string]$Phase0TestPlan.recordId) `
            -Context 'compatibility bridge distribution' -Errors $Errors)
        $bridgeClosureErrorCount = $Errors.Count
        $bridgeClosure = Test-DistributionSourceEvidenceClosure -Distribution $bridgeDistribution -RecordMap $RecordMap `
            -EvaluationTime $EvaluationTime -ExpectedEvidenceRecord $bridgeEvidence `
            -CacheAdmissionSemanticsAlreadyValidated `
            -Context 'compatibility bridge distribution' -Errors $Errors
        Test-PortableEvidenceAdmissionSemantics -Evidence $bridgeEvidence -Distribution $bridgeDistribution `
            -Manifest $Manifest -Phase0TestPlan $Phase0TestPlan -ThresholdPolicy $ThresholdPolicy `
            -RecordMap $RecordMap -CurrentRelease $resolvedCurrentRelease -EvaluationTime $EvaluationTime `
            -ValidationProfile $ValidationProfile -Errors $Errors
        if ($null -eq $bridgeClosure -or -not $bridgeClosure.Valid -or $Errors.Count -gt $bridgeClosureErrorCount) {
            $bridgeValid = $false
        }
        Test-DistributionPerUnitRunProof -Distribution $bridgeDistribution -Context 'compatibility bridge distribution' -Errors $Errors
        foreach ($unit in @($bridgeDistribution.perUnitRunCounts)) {
            if (-not (Test-NonBlankString $unit.unitRef) -or
                ($unit.acceptedRunCount -isnot [int] -and $unit.acceptedRunCount -isnot [long]) -or
                [int64]$unit.acceptedRunCount -lt [int64]$bridgePolicy.minimumRepetitionsPerCriticalCombination) {
                $bridgeValid = $false
            }
            else {
                [void]$bridgeUnitRefs.Add([string]$unit.unitRef)
                [void]$combinedUnitRefs.Add([string]$unit.unitRef)
            }
        }
    }
    $applicationFloor = if ($Phase0TestPlan.samplingFloors -is [pscustomobject]) {
        $Phase0TestPlan.samplingFloors.PSObject.Properties['application-compatibility'].Value
    }
    else { $null }
    if ($bridgeAcceptanceEvidenceCount -ne 1 -or $bridgePolicy -isnot [pscustomobject] -or
        $applicationFloor -isnot [pscustomobject] -or
        ($bridgePolicy.minimumCandidateUnits -isnot [int] -and $bridgePolicy.minimumCandidateUnits -isnot [long]) -or
        ($bridgePolicy.minimumRepetitionsPerCriticalCombination -isnot [int] -and $bridgePolicy.minimumRepetitionsPerCriticalCombination -isnot [long]) -or
        $bridgeUnitRefs.Count -ne [int64]$manifestBridge.candidateUnits -or
        $bridgeUnitRefs.Count -lt [int64]$bridgePolicy.minimumCandidateUnits -or
        $combinedUnitRefs.Count -lt [int64]$applicationFloor.minUnits) {
        $bridgeValid = $false
    }

    [int64]$readbackMaximumAge = if (($admission.roleBindingReadbackMaxAgeMinutes -is [int] -or
            $admission.roleBindingReadbackMaxAgeMinutes -is [long]) -and
        [int64]$admission.roleBindingReadbackMaxAgeMinutes -gt 0) {
        [int64]$admission.roleBindingReadbackMaxAgeMinutes
    }
    else { 0 }
    $policyErrorCount = $Errors.Count
    $readbackPolicy = if ($readbackMaximumAge -gt 0) {
        Test-SecurityFreshnessPolicyBinding -RecordMap $RecordMap `
            -Reference $admission.roleBindingReadbackPolicyRef -Digest $admission.roleBindingReadbackPolicyDigest `
            -ExpectedKind 'READBACK_FRESHNESS' -ExpectedMaximumAgeMinutes $readbackMaximumAge `
            -ExpectedTenantBoundaryRef ([string]$Manifest.tenantBoundaryRef) `
            -ExpectedTargetEnvironmentRef ([string]$Manifest.targetEnvironmentRef) `
            -ExpectedAuthorityMode 'ROOT_BOOTSTRAP' -EvaluationTime $EvaluationTime -Errors $Errors
    }
    else { $null }
    $policyValid = $null -ne $readbackPolicy -and $Errors.Count -eq $policyErrorCount -and
        [string]$admission.freshnessPolicyRef -ceq [string]$admission.roleBindingReadbackPolicyRef -and
        [string]$admission.freshnessPolicyDigest -ceq [string]$admission.roleBindingReadbackPolicyDigest -and
        ($admission.freshnessMaxAgeMinutes -is [int] -or $admission.freshnessMaxAgeMinutes -is [long]) -and
        [int64]$admission.freshnessMaxAgeMinutes -eq $readbackMaximumAge -and
        ($EvaluationTime - $revocationCheckedAt).TotalMinutes -le $readbackMaximumAge -and
        ($EvaluationTime - $keyBindingCheckedAt).TotalMinutes -le $readbackMaximumAge

    $roleErrorCount = $Errors.Count
    $roleClosure = if ($readbackMaximumAge -gt 0) {
        Test-RoleBindingClosure -RecordMap $RecordMap -RoleBindingRef ([string]$admission.roleBindingRef) `
            -RoleBindingDigest ([string]$admission.roleBindingDigest) `
            -RoleBindingReadbackRef ([string]$admission.roleBindingReadbackRef) `
            -RoleBindingReadbackDigest ([string]$admission.roleBindingReadbackDigest) `
            -ExpectedTenantBoundaryRef ([string]$Manifest.tenantBoundaryRef) `
            -ExpectedTargetEnvironmentRef ([string]$Manifest.targetEnvironmentRef) `
            -ExpectedReadbackPolicyRef ([string]$admission.roleBindingReadbackPolicyRef) `
            -ExpectedReadbackPolicyDigest ([string]$admission.roleBindingReadbackPolicyDigest) `
            -ExpectedReadbackMaximumAgeMinutes $readbackMaximumAge -EvaluationTime $EvaluationTime -Errors $Errors
    }
    else { $null }
    [DateTimeOffset]$roleReadbackObservedAt = [DateTimeOffset]::MinValue
    $roleValid = $null -ne $roleClosure -and $Errors.Count -eq $roleErrorCount -and
        [OperationsBlueprint.StrictRfc3339]::TryParse([string]$roleClosure.Readback.observedAt, [ref]$roleReadbackObservedAt) -and
        $roleReadbackObservedAt -lt $admittedAt -and
        @($roleClosure.RoleBinding.bindings | Where-Object {
            [string]$_.roleId -ceq 'ROLE_EVIDENCE_CUSTODY_OWNER' -and
            [string]$_.canonicalPrincipalId -ceq [string]$admission.issuedByPrincipalId
        }).Count -eq 1

    $principalSet = [System.Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
    $principalSeparationValid = $true
    $principals = @(
        [string]$admission.issuedByPrincipalId,[string]$admission.recordProducerPrincipalId,
        [string]$admission.affectedRequesterPrincipalId
    )
    if ($null -ne $roleClosure) {
        foreach ($alias in @([string]$roleClosure.RoleBinding.sourceIdentityRef,[string]$roleClosure.Readback.readIdentityRef)) {
            if ($roleClosure.AliasMap.ContainsKey($alias)) { $principals += @([string]$roleClosure.AliasMap[$alias]) }
            else { $principalSeparationValid = $false }
        }
        $principals += @(
            [string]$roleClosure.Approval.approverPrincipalRef,
            [string]$roleClosure.RootAuthority.ceremonyOperatorIdentityRef,
            [string]$roleClosure.RootAuthority.independentReadIdentityRef
        )
        $principals += @($roleClosure.RootAuthority.authorityKeyBindings | ForEach-Object { [string]$_.keyCustodianPrincipalId })
    }
    foreach ($principal in $principals) {
        if ([string]$principal -cnotmatch '^private://canonical-principals/sha256/[0-9a-f]{64}$' -or
            -not $principalSet.Add([string]$principal)) { $principalSeparationValid = $false }
    }

    $expectedSubjectDigest = Get-CompatibilityCacheAdmissionSubjectDigest -AdmissionRecord $admission
    $protectedBindingValid = [string]$admission.admissionSubjectDigest -ceq [string]$expectedSubjectDigest -and
        [string]$admission.signedSubjectDigest -ceq [string]$expectedSubjectDigest -and
        [string]$admission.admissionArtifactRef -cmatch '^private://' -and
        [string]$admission.admissionArtifactDigest -ceq [string]$expectedSubjectDigest -and
        [string]$admission.attestationRef -cmatch '^private://' -and
        (Test-Sha256Token $admission.attestationDigest) -and
        [string]$admission.attestationSubjectDigest -ceq [string]$expectedSubjectDigest -and
        [string]$admission.attestationStatus -ceq 'VERIFIED' -and
        [string]$admission.signatureSignerPrincipalId -ceq [string]$admission.issuedByPrincipalId -and
        [string]$admission.signatureKeyRef -cmatch '^private://' -and
        (Test-Sha256Token $admission.signatureKeySpkiDigest) -and
        [string]$admission.signatureKeyBindingRef -cmatch '^private://' -and
        (Test-Sha256Token $admission.signatureKeyBindingDigest) -and
        [string]$admission.signatureKeyBindingStatus -ceq 'VERIFIED' -and
        [string]$admission.signatureRef -cmatch '^private://' -and
        (Test-Sha256Token $admission.signatureDigest) -and
        [string]$admission.signatureStatus -ceq 'VERIFIED'

    if ($null -ne $historicalRelease) {
        Test-EvidenceReleaseBinding -ReleaseRecord $historicalRelease -EvidenceRecords @($resolvedCachedEvidence) `
            -RecordMap $RecordMap -EvaluationTime $EvaluationTime -HistoricalCacheRelease `
            -Context 'historical compatibility evidence release' -Errors $Errors
    }
    if ($null -ne $resolvedCurrentRelease) {
        Test-EvidenceReleaseBinding -ReleaseRecord $resolvedCurrentRelease -EvidenceRecords @($bridgeEvidenceRecords) `
            -RecordMap $RecordMap -EvaluationTime $EvaluationTime `
            -CacheAdmissionSemanticsAlreadyValidated `
            -Context 'current compatibility evidence release' -Errors $Errors
    }

    $valid = [string]$Distribution.compatibilityCacheAdmissionRef -ceq [string]$admission.recordId -and
        [string]$admission.schemaVersion -ceq '1.0.0' -and
        [string]$admission.recordStage -ceq 'COMPATIBILITY_CACHE_ADMISSION' -and
        [string]$admission.status -ceq 'ADMITTED' -and
        [string]$admission.issuedByRole -ceq 'ROLE_EVIDENCE_CUSTODY_OWNER' -and
        [string]$admission.dependencyStatus -ceq 'MATCH' -and
        [string]$admission.revocationStatus -ceq 'NOT_REVOKED' -and
        [string]$admission.revocationEvidenceRef -cmatch '^private://' -and
        (Test-Sha256Token $admission.revocationEvidenceDigest) -and
        [string]$admission.authorizationEffect -ceq 'NONE' -and
        [string]$resolvedCachedEvidence.admission.mode -ceq 'fresh' -and
        $authorityBindingValid -and $releaseBindingValid -and $consumerBindingValid -and
        $dependencyValid -and $timesValid -and $cacheAgeValid -and $bridgeValid -and
        $policyValid -and $roleValid -and $principalSeparationValid -and $distinctnessValid -and $protectedBindingValid

    if ([string]$ValidationProfile -ceq 'PRODUCTION') {
        Add-BlueprintError -Errors $Errors -Code 'COMPATIBILITY_CACHE_PRIVATE_BINDING_UNVERIFIED' -Message 'The public validator cannot authenticate the protected cache admission artifact, signature, key binding, dependency bridge, issuer, and revocation bytes.'
        $valid = $false
    }
    if (-not $valid -or $Errors.Count -gt $initialErrorCount) {
        Add-BlueprintError -Errors $Errors -Code 'COMPATIBILITY_CACHE_ADMISSION_INVALID' -Message 'The compatibility cache admission is not exact, acyclic, current, signed, role-bound, release-closed, dependency-matched, and freshly bridged.'
        $valid = $false
    }
    return [pscustomobject]@{
        Valid = $valid
        Admission = $admission
        HistoricalRelease = $historicalRelease
        CurrentRelease = $resolvedCurrentRelease
    }
}

function Test-PortableEvidenceAdmissionSemantics {
    param(
        [Parameter(Mandatory = $true)]$Evidence,
        [Parameter(Mandatory = $true)]$Distribution,
        [AllowNull()]$Manifest,
        [AllowNull()]$Phase0TestPlan,
        [AllowNull()]$ThresholdPolicy,
        [Parameter(Mandatory = $true)]$RecordMap,
        [AllowNull()]$CurrentRelease,
        [Parameter(Mandatory = $true)][DateTimeOffset]$EvaluationTime,
        [ValidateSet('TEST','PRODUCTION')][string]$ValidationProfile = 'PRODUCTION',
        [Parameter(Mandatory = $true)][AllowEmptyCollection()][System.Collections.ArrayList]$Errors
    )

    $context = "portable evidence $($Evidence.recordId) admission"
    if ($Evidence.admission -isnot [pscustomobject] -or $null -eq $Manifest -or
        $null -eq $Phase0TestPlan -or $null -eq $ThresholdPolicy) {
        Add-BlueprintError -Errors $Errors -Code 'PORTABLE_EVIDENCE_ADMISSION_INVALID' -Message "$context lacks an admission object or exact frozen manifest, test-plan, and threshold-policy authorities."
        return
    }
    $admission = $Evidence.admission
    $hasCacheAdmissionRef = Test-NonBlankString $Distribution.compatibilityCacheAdmissionRef
    $hasCacheAdmissionDigest = Test-NonBlankString $Distribution.compatibilityCacheAdmissionDigest
    if ($hasCacheAdmissionRef -or $hasCacheAdmissionDigest) {
        if (-not $hasCacheAdmissionRef -or -not $hasCacheAdmissionDigest -or
            [string]$Distribution.testClass -cne 'application-compatibility' -or
            [string]$Evidence.provenance -cne 'T0' -or
            [string]$Evidence.evidenceUse -cne 'gate-or-verdict') {
            Add-BlueprintError -Errors $Errors -Code 'COMPATIBILITY_CACHE_ADMISSION_INVALID' -Message 'A cache consumer requires one complete typed admission binding and T0 gate-bearing application-compatibility evidence.'
            return
        }
        [void](Test-CompatibilityCacheAdmissionSemantics -Distribution $Distribution -CachedEvidence $Evidence `
            -Manifest $Manifest -Phase0TestPlan $Phase0TestPlan -ThresholdPolicy $ThresholdPolicy `
            -RecordMap $RecordMap -CurrentRelease $CurrentRelease -EvaluationTime $EvaluationTime `
            -ValidationProfile $ValidationProfile -Errors $Errors)
        return
    }
    [DateTimeOffset]$evidenceTimestamp = [DateTimeOffset]::MinValue
    [DateTimeOffset]$admittedAt = [DateTimeOffset]::MinValue
    [DateTimeOffset]$manifestFrozenAt = [DateTimeOffset]::MinValue
    [DateTimeOffset]$planFrozenAt = [DateTimeOffset]::MinValue
    [DateTimeOffset]$policyFrozenAt = [DateTimeOffset]::MinValue
    $chronologyValid = [OperationsBlueprint.StrictRfc3339]::TryParse([string]$Evidence.timestamp, [ref]$evidenceTimestamp) -and
        [OperationsBlueprint.StrictRfc3339]::TryParse([string]$admission.admittedAt, [ref]$admittedAt) -and
        [OperationsBlueprint.StrictRfc3339]::TryParse([string]$Manifest.frozenAt, [ref]$manifestFrozenAt) -and
        [OperationsBlueprint.StrictRfc3339]::TryParse([string]$Phase0TestPlan.frozenAt, [ref]$planFrozenAt) -and
        [OperationsBlueprint.StrictRfc3339]::TryParse([string]$ThresholdPolicy.frozenAt, [ref]$policyFrozenAt) -and
        $evidenceTimestamp -le $admittedAt -and $admittedAt -le $EvaluationTime
    if (-not $chronologyValid) {
        Add-BlueprintError -Errors $Errors -Code 'PORTABLE_EVIDENCE_ADMISSION_INVALID' -Message "$context has invalid or future source, admission, manifest, plan, or policy chronology."
    }

    $testClass = [string]$Distribution.testClass
    $dynamicClasses = @(
        'controlled-benchmark','sustained-performance','battery-standby','dock-reliability',
        'corporate-floor','agent-state','production-pilot','sentiment'
    )
    if ($dynamicClasses -ccontains $testClass) {
        if ([string]$admission.mode -cne 'fresh' -or
            -not $chronologyValid -or $evidenceTimestamp -le $manifestFrozenAt -or
            $evidenceTimestamp -le $planFrozenAt -or $evidenceTimestamp -le $policyFrozenAt -or
            $admittedAt -le $evidenceTimestamp) {
            Add-BlueprintError -Errors $Errors -Code 'DYNAMIC_EVIDENCE_NOT_FRESH' -Message 'Dynamic controlled, performance, battery, dock, floor, agent, pilot, and sentiment evidence must be freshly observed after all three frozen authorities and admitted strictly after observation.'
        }
        return
    }

    if ([string]$admission.mode -ceq 'fresh') {
        if (-not $chronologyValid -or $evidenceTimestamp -le $manifestFrozenAt -or
            $evidenceTimestamp -le $planFrozenAt -or $evidenceTimestamp -le $policyFrozenAt -or
            $admittedAt -le $evidenceTimestamp) {
            Add-BlueprintError -Errors $Errors -Code 'PORTABLE_EVIDENCE_ADMISSION_INVALID' -Message 'Fresh evidence must be observed after the exact manifest, test plan, and threshold policy freezes and admitted strictly after observation.'
        }
        return
    }
    Add-BlueprintError -Errors $Errors -Code 'COMPATIBILITY_CACHE_ADMISSION_REQUIRED' -Message 'Legacy mutable compatibility-cache admission embedded in portable evidence is not accepted; reuse requires a separate typed, digest-bound cache admission wrapper.'
}

function Test-DistributionPhase0FloorBinding {
    param(
        [Parameter(Mandatory = $true)]$Distribution,
        [AllowNull()]$Phase0TestPlan,
        [AllowNull()]$ExpectedEvidenceRecord,
        [Parameter(Mandatory = $true)][string]$ExpectedTestPlanRef,
        [Parameter(Mandatory = $true)][string]$Context,
        [Parameter(Mandatory = $true)][AllowEmptyCollection()][System.Collections.ArrayList]$Errors
    )

    Test-RequiredProperties -Object $Distribution -Names @(
        'phase0TestPlanRef', 'phase0TestPlanDigest', 'samplingFloorPointer',
        'samplingFloorDigest', 'testRef', 'testDefinitionDigest', 'conditionRef',
        'baselineFingerprint', 'testClass', 'requiredUnits', 'requiredRuns'
    ) -Context $Context -Errors $Errors
    $testClass = [string]$Distribution.testClass
    $definitionMatches = @(if ($null -ne $Phase0TestPlan) {
        $Phase0TestPlan.tests | Where-Object { [string]$_.testId -ceq [string]$Distribution.testRef }
    })
    $definition = if ($definitionMatches.Count -eq 1) { $definitionMatches[0] } else { $null }
    $definitionDigest = if ($null -ne $definition) { Get-CanonicalPayloadDigest -Payload $definition } else { '' }
    $definitionConditionMatches = @(if ($null -ne $definition) {
        $definition.conditions | Where-Object { [string]$_.conditionId -ceq [string]$Distribution.conditionRef }
    })
    $legalPhaseByClass = [System.Collections.Generic.Dictionary[string,int]]::new([System.StringComparer]::Ordinal)
    $legalPhaseByClass.Add('component-identification', 1)
    $legalPhaseByClass.Add('controlled-benchmark', 3)
    $legalPhaseByClass.Add('sustained-performance', 3)
    $legalPhaseByClass.Add('battery-standby', 3)
    $legalPhaseByClass.Add('dock-reliability', 3)
    $legalPhaseByClass.Add('application-compatibility', 2)
    $legalPhaseByClass.Add('production-pilot', 4)
    $legalPhaseByClass.Add('sentiment', 4)
    $legalPhaseByClass.Add('corporate-floor', 3)
    $legalPhaseByClass.Add('agent-state', 3)
    $floor = $null
    if ($null -ne $Phase0TestPlan -and $Phase0TestPlan.samplingFloors -is [pscustomobject]) {
        $floorProperty = $Phase0TestPlan.samplingFloors.PSObject.Properties[$testClass]
        if ($null -ne $floorProperty -and $floorProperty.Value -is [pscustomobject]) {
            $floor = $floorProperty.Value
        }
    }
    $floorDigest = if ($null -ne $floor) { Get-CanonicalPayloadDigest -Payload $floor } else { '' }
    $definitionValid = $null -ne $Phase0TestPlan -and $definitionMatches.Count -eq 1 -and
        $null -ne $definition -and $definitionConditionMatches.Count -eq 1 -and
        [string]$Distribution.testDefinitionDigest -ceq [string]$definitionDigest -and
        [string]$Distribution.testClass -ceq [string]$definition.class -and
        $legalPhaseByClass.ContainsKey([string]$definition.class) -and
        ($definition.phase -is [int] -or $definition.phase -is [long]) -and
        [int64]$definition.phase -eq [int64]$legalPhaseByClass[[string]$definition.class] -and
        [string]$definition.samplingFloorRef -ceq "#/samplingFloors/$testClass"
    if ($null -ne $ExpectedEvidenceRecord) {
        $cacheConsumer = (Test-NonBlankString $Distribution.compatibilityCacheAdmissionRef) -and
            (Test-NonBlankString $Distribution.compatibilityCacheAdmissionDigest) -and
            [string]$Distribution.testClass -ceq 'application-compatibility'
        $sourceBackReferenceValid = if ($cacheConsumer) {
            (Test-NonBlankString $ExpectedEvidenceRecord.distributionRef) -and
                -not ([string]$ExpectedEvidenceRecord.distributionRef).Contains('#') -and
                [string]$ExpectedEvidenceRecord.distributionRef -cne [string]$Distribution.recordId
        }
        else { [string]$ExpectedEvidenceRecord.distributionRef -ceq [string]$Distribution.recordId }
        $definitionValid = $definitionValid -and
            [string]$ExpectedEvidenceRecord.testRef -ceq [string]$Distribution.testRef -and
            [string]$ExpectedEvidenceRecord.conditionRef -ceq [string]$Distribution.conditionRef -and
            [string]$ExpectedEvidenceRecord.baselineFingerprint -ceq [string]$Distribution.baselineFingerprint -and
            [string]$ExpectedEvidenceRecord.testPlanRef -ceq [string]$Distribution.phase0TestPlanRef -and
            [string]$ExpectedEvidenceRecord.testPackVersion -ceq [string]$definition.testPackVersion -and
            $sourceBackReferenceValid
    }
    if (-not $definitionValid) {
        Add-BlueprintError -Errors $Errors -Code 'DISTRIBUTION_TEST_DEFINITION_BINDING_INVALID' -Message "$Context does not resolve one exact case-sensitive frozen test definition and bind its digest, class, legal phase, local condition, baseline, test pack, and source-evidence back-reference."
    }
    $floorValid = $null -ne $Phase0TestPlan -and $null -ne $floor -and
        [string]$Distribution.phase0TestPlanRef -ceq $ExpectedTestPlanRef -and
        [string]$Distribution.phase0TestPlanRef -ceq [string]$Phase0TestPlan.recordId -and
        [string]$Distribution.phase0TestPlanDigest -ceq [string]$Phase0TestPlan.contentDigest -and
        [string]$Distribution.samplingFloorPointer -ceq "#/samplingFloors/$testClass" -and
        [string]$Distribution.samplingFloorDigest -ceq [string]$floorDigest -and
        ($Distribution.requiredUnits -is [int] -or $Distribution.requiredUnits -is [long]) -and
        ($Distribution.requiredRuns -is [int] -or $Distribution.requiredRuns -is [long]) -and
        ($floor.minUnits -is [int] -or $floor.minUnits -is [long]) -and
        ($floor.minRepetitionsPerUnit -is [int] -or $floor.minRepetitionsPerUnit -is [long]) -and
        [int64]$Distribution.requiredUnits -eq [int64]$floor.minUnits -and
        [int64]$Distribution.requiredRuns -eq [int64]$floor.minRepetitionsPerUnit
    if (-not $floorValid) {
        Add-BlueprintError -Errors $Errors -Code 'DISTRIBUTION_PHASE0_FLOOR_BINDING_INVALID' -Message "$Context does not bind its required units and runs to the exact frozen Phase 0 class floor and canonical digest."
    }
    return [pscustomobject]@{ Valid = ($definitionValid -and $floorValid); TestDefinition = $definition }
}

function Get-Phase3CandidateComparisonRequirements {
    param(
        [AllowNull()]$Phase0TestPlan,
        [Parameter(Mandatory = $true)][string]$BaselineFingerprint,
        [Parameter(Mandatory = $true)][AllowEmptyCollection()][System.Collections.ArrayList]$Errors
    )

    $tuples = [System.Collections.Generic.Dictionary[string,object]]::new([System.StringComparer]::Ordinal)
    $conditionRefs = New-Object System.Collections.ArrayList
    if ($null -eq $Phase0TestPlan) {
        return [pscustomobject]@{ Tuples = $tuples; ConditionRefs = @($conditionRefs) }
    }

    foreach ($definition in @($Phase0TestPlan.tests | Where-Object {
        ($_.phase -is [int] -or $_.phase -is [long]) -and [int64]$_.phase -eq 3
    })) {
        $definitionDigest = Get-CanonicalPayloadDigest -Payload $definition
        foreach ($condition in @($definition.conditions)) {
            $conditionRef = [string]$condition.conditionId
            if (Test-NonBlankString $conditionRef -and @($conditionRefs) -cnotcontains $conditionRef) {
                [void]$conditionRefs.Add($conditionRef)
            }
            foreach ($role in @($definition.appliesTo)) {
                $roleName = [string]$role
                if ($roleName -cnotin @('candidate','incumbent','sibling-or-alternative') -or
                    -not (Test-NonBlankString $conditionRef)) {
                    continue
                }
                $tuple = [pscustomobject][ordered]@{
                    testRef = [string]$definition.testId
                    controlRole = $roleName
                    conditionRef = $conditionRef
                    baselineFingerprint = $BaselineFingerprint
                    testDefinitionDigest = [string]$definitionDigest
                    testClass = [string]$definition.class
                    testPackVersion = [string]$definition.testPackVersion
                }
                $tupleKey = Get-CanonicalPayloadDigest -Payload ([pscustomobject][ordered]@{
                    testRef = $tuple.testRef
                    controlRole = $tuple.controlRole
                    conditionRef = $tuple.conditionRef
                    baselineFingerprint = $tuple.baselineFingerprint
                })
                if ($tuples.ContainsKey($tupleKey)) {
                    Add-BlueprintError -Errors $Errors -Code 'COMPARISON_TEST_TUPLE_INVALID' -Message 'The frozen Phase 3 plan produces a duplicate exact test, role, condition, and baseline tuple.'
                }
                else {
                    $tuples.Add($tupleKey, $tuple)
                }
            }
        }
    }
    if ($tuples.Count -eq 0) {
        Add-BlueprintError -Errors $Errors -Code 'COMPARISON_TEST_TUPLE_INVALID' -Message 'The frozen plan defines no Phase 3 candidate-comparison tuple.'
    }
    return [pscustomobject]@{ Tuples = $tuples; ConditionRefs = @($conditionRefs) }
}

function Test-FleetClaimFreshnessBinding {
    param(
        [AllowNull()]$Freshness,
        [Parameter(Mandatory = $true)][string]$ObservationWindow,
        [Parameter(Mandatory = $true)][DateTimeOffset]$PolicyExecutedAt,
        [Parameter(Mandatory = $true)][DateTimeOffset]$EvaluationTime,
        [Parameter(Mandatory = $true)]$RecordMap,
        [Parameter(Mandatory = $true)][string]$ExpectedPolicyRef,
        [Parameter(Mandatory = $true)][string]$ExpectedDependencySnapshotRef,
        [Parameter(Mandatory = $true)][string]$ExpectedDependencySnapshotDigest,
        [Parameter(Mandatory = $true)][string]$Context,
        [Parameter(Mandatory = $true)][AllowEmptyCollection()][System.Collections.ArrayList]$Errors
    )

    $fields = @(
        'observedAt','admittedAt','policyRef','policyDigest','policyObjectPointer','policyObjectDigest',
        'maximumAgePointer','maximumAgeDays','platformBaselineRef','platformBaselineDigest',
        'platformBaselinePointer','dependencySnapshotRef','dependencySnapshotPointer',
        'dependencySnapshotDigest','dependencyStatus'
    )
    if ($Freshness -isnot [pscustomobject]) {
        Add-BlueprintError -Errors $Errors -Code 'FLEET_PORTFOLIO_CLAIM_FRESHNESS_INVALID' -Message "$Context requires the governed fleet-portfolio freshness binding."
        return
    }
    Test-RequiredProperties -Object $Freshness -Names $fields -Context "$Context freshness" -Errors $Errors
    Test-AllowedProperties -Object $Freshness -Names $fields -Context "$Context freshness" -Errors $Errors
    [DateTimeOffset]$observedAt = [DateTimeOffset]::MinValue
    [DateTimeOffset]$admittedAt = [DateTimeOffset]::MinValue
    $timeValid = [OperationsBlueprint.StrictRfc3339]::TryParse([string]$Freshness.observedAt, [ref]$observedAt) -and
        [OperationsBlueprint.StrictRfc3339]::TryParse([string]$Freshness.admittedAt, [ref]$admittedAt)
    $maxAgeValid = ($Freshness.maximumAgeDays -is [int] -or $Freshness.maximumAgeDays -is [long]) -and
        [int64]$Freshness.maximumAgeDays -ge 1 -and [int64]$Freshness.maximumAgeDays -le 3650
    $windowDateMatches = $false
    if ($timeValid -and [string]$ObservationWindow -cmatch '^\d{4}-\d{2}-\d{2}/(\d{4}-\d{2}-\d{2})$') {
        [DateTimeOffset]$windowEnd = [DateTimeOffset]::MinValue
        $windowDateMatches = [OperationsBlueprint.StrictIsoDate]::TryParse([string]$Matches[1], [ref]$windowEnd) -and
            $observedAt.UtcDateTime.Date -eq $windowEnd.UtcDateTime.Date
    }
    if (-not $timeValid -or -not $maxAgeValid -or -not $windowDateMatches -or
        $observedAt -gt $admittedAt -or $admittedAt -gt $PolicyExecutedAt -or $PolicyExecutedAt -gt $EvaluationTime -or
        ($maxAgeValid -and $timeValid -and ($EvaluationTime - $observedAt).TotalDays -gt [int64]$Freshness.maximumAgeDays) -or
        [string]$Freshness.dependencyStatus -cne 'MATCH') {
        Add-BlueprintError -Errors $Errors -Code 'FLEET_PORTFOLIO_CLAIM_FRESHNESS_INVALID' -Message "$Context freshness must be MATCH, current, bounded, and ordered observation <= admission <= policy execution <= evaluation."
    }

    $requiredDependencyFields = @(
        'windowsBuild','biosVersion','driverPackVersion','corporateImageVersion',
        'securityAgentSetDigest','conditionSetDigest','testPackVersion'
    )
    $policy = Resolve-CanonicalRecord -RecordMap $RecordMap -Reference $Freshness.policyRef `
        -ExpectedTypes @('threshold-policy') -Context "$Context freshness policy" -Errors $Errors
    $policyObjectFound = $false
    $maximumAgeFound = $false
    $policyObject = if ($null -ne $policy) {
        Get-JsonPointerValue -Document $policy.payload -Pointer ([string]$Freshness.policyObjectPointer) -Found ([ref]$policyObjectFound)
    }
    else { $null }
    $maximumAgeValue = if ($null -ne $policy) {
        Get-JsonPointerValue -Document $policy.payload -Pointer ([string]$Freshness.maximumAgePointer) -Found ([ref]$maximumAgeFound)
    }
    else { $null }
    $policyObjectValid = $policyObject -is [pscustomobject]
    if ($policyObjectValid) {
        Test-RequiredProperties -Object $policyObject -Names @('maxAgeDays','requiredDependencyFields') -Context "$Context fleet freshness policy object" -Errors $Errors
        Test-AllowedProperties -Object $policyObject -Names @('maxAgeDays','requiredDependencyFields') -Context "$Context fleet freshness policy object" -Errors $Errors
        $policyObjectValid = ($policyObject.maxAgeDays -is [int] -or $policyObject.maxAgeDays -is [long]) -and
            [int64]$policyObject.maxAgeDays -eq [int64]$Freshness.maximumAgeDays -and
            $policyObject.requiredDependencyFields -is [System.Collections.IList] -and
            (ConvertTo-DeterministicJsonText -Value (ConvertTo-CanonicalJsonValue @($policyObject.requiredDependencyFields))) -ceq
                (ConvertTo-DeterministicJsonText -Value (ConvertTo-CanonicalJsonValue $requiredDependencyFields))
    }
    $calculatedPolicyObjectDigest = if ($policyObjectFound) { Get-CanonicalPayloadDigest -Payload $policyObject } else { '' }
    if ($null -eq $policy -or [string]$Freshness.policyRef -cne [string]$ExpectedPolicyRef -or
        [string]$Freshness.policyRef -cne [string]$policy.recordId -or
        [string]$Freshness.policyDigest -cne [string]$policy.contentDigest -or
        [string]$Freshness.policyObjectPointer -cne '/extensions/leadershipFreshness/currentFleetIssue' -or
        [string]$Freshness.maximumAgePointer -cne '/extensions/leadershipFreshness/currentFleetIssue/maxAgeDays' -or
        -not (Test-CanonicalRecordPointerCoverage -Record $policy -Pointer ([string]$Freshness.policyObjectPointer)) -or
        -not (Test-CanonicalRecordPointerCoverage -Record $policy -Pointer ([string]$Freshness.maximumAgePointer)) -or
        -not $policyObjectFound -or -not $maximumAgeFound -or -not $policyObjectValid -or
        [string]$Freshness.policyObjectDigest -cne [string]$calculatedPolicyObjectDigest -or
        ($maximumAgeValue -isnot [int] -and $maximumAgeValue -isnot [long]) -or
        [int64]$maximumAgeValue -ne [int64]$Freshness.maximumAgeDays) {
        Add-BlueprintError -Errors $Errors -Code 'FLEET_PORTFOLIO_CLAIM_FRESHNESS_INVALID' -Message "$Context freshness does not resolve the exact frozen threshold-policy overlay, object digest, dependency-field policy, and maximum-age scalar."
    }

    $baseline = Resolve-CanonicalRecord -RecordMap $RecordMap -Reference $Freshness.platformBaselineRef `
        -ExpectedTypes @('platform-baseline-record') -Context "$Context platform baseline" -Errors $Errors
    $snapshotFound = $false
    $snapshot = if ($null -ne $baseline) {
        Get-JsonPointerValue -Document $baseline.payload -Pointer ([string]$Freshness.platformBaselinePointer) -Found ([ref]$snapshotFound)
    }
    else { $null }
    if ($snapshot -is [pscustomobject]) {
        Test-LeadershipDependencySnapshot -Snapshot $snapshot -Context "$Context fleet freshness" -Errors $Errors
    }
    $snapshotDigest = if ($snapshotFound) { Get-CanonicalPayloadDigest -Payload $snapshot } else { '' }
    $expectedBaselineRef = ([string]$ExpectedDependencySnapshotRef).Split('#', 2)[0]
    if ($null -eq $baseline -or [string]$Freshness.platformBaselineRef -cne [string]$expectedBaselineRef -or
        [string]$Freshness.dependencySnapshotRef -cne [string]$ExpectedDependencySnapshotRef -or
        [string]$Freshness.dependencySnapshotDigest -cne [string]$ExpectedDependencySnapshotDigest -or
        [string]$Freshness.platformBaselineRef -cne [string]$baseline.recordId -or
        [string]$Freshness.platformBaselineDigest -cne [string]$baseline.contentDigest -or
        [string]$Freshness.platformBaselinePointer -cne '/dependencySnapshot' -or
        [string]$Freshness.dependencySnapshotPointer -cne '/dependencySnapshot' -or
        [string]$Freshness.dependencySnapshotRef -cne (([string]$baseline.recordId) + '#/dependencySnapshot') -or
        @($baseline.pointers) -cnotcontains '/dependencySnapshot' -or -not $snapshotFound -or
        [string]$baseline.dependencyStatus -cne 'CURRENT' -or
        [string]$baseline.dependencySnapshotDigest -cne [string]$snapshotDigest -or
        [string]$Freshness.dependencySnapshotDigest -cne [string]$snapshotDigest) {
        Add-BlueprintError -Errors $Errors -Code 'FLEET_PORTFOLIO_CLAIM_FRESHNESS_INVALID' -Message "$Context freshness does not resolve the exact current seven-field platform-baseline dependency snapshot and digest."
    }
}

function Test-FleetSourceFreshnessBinding {
    param(
        [AllowNull()]$SourceFreshness,
        [AllowNull()]$GovernedFreshness,
        [Parameter(Mandatory = $true)][string]$ObservationWindow,
        [Parameter(Mandatory = $true)][DateTimeOffset]$PolicyExecutedAt,
        [Parameter(Mandatory = $true)][DateTimeOffset]$EvaluationTime,
        [Parameter(Mandatory = $true)][string]$Context,
        [Parameter(Mandatory = $true)][AllowEmptyCollection()][System.Collections.ArrayList]$Errors
    )

    $fields = @('observedAt','admittedAt','policyRef','maxAgeDays','dependencySnapshotRef','dependencySnapshotDigest','dependencyStatus')
    if ($SourceFreshness -isnot [pscustomobject] -or $GovernedFreshness -isnot [pscustomobject]) {
        Add-BlueprintError -Errors $Errors -Code 'FLEET_PORTFOLIO_CLAIM_FRESHNESS_INVALID' -Message "$Context requires a generic source freshness binding governed by the enclosing fleet freshness contract."
        return
    }
    Test-RequiredProperties -Object $SourceFreshness -Names $fields -Context "$Context source freshness" -Errors $Errors
    Test-AllowedProperties -Object $SourceFreshness -Names $fields -Context "$Context source freshness" -Errors $Errors
    [DateTimeOffset]$observedAt = [DateTimeOffset]::MinValue
    [DateTimeOffset]$admittedAt = [DateTimeOffset]::MinValue
    [DateTimeOffset]$windowEnd = [DateTimeOffset]::MinValue
    $timesValid = [OperationsBlueprint.StrictRfc3339]::TryParse([string]$SourceFreshness.observedAt, [ref]$observedAt) -and
        [OperationsBlueprint.StrictRfc3339]::TryParse([string]$SourceFreshness.admittedAt, [ref]$admittedAt) -and
        [string]$ObservationWindow -cmatch '^\d{4}-\d{2}-\d{2}/(\d{4}-\d{2}-\d{2})$' -and
        [OperationsBlueprint.StrictIsoDate]::TryParse([string]$Matches[1], [ref]$windowEnd)
    $expectedSourcePolicyRef = ([string]$GovernedFreshness.policyRef) + '#' + ([string]$GovernedFreshness.policyObjectPointer)
    if (-not $timesValid -or $observedAt.UtcDateTime.Date -ne $windowEnd.UtcDateTime.Date -or
        $observedAt -gt $admittedAt -or $admittedAt -gt $PolicyExecutedAt -or $PolicyExecutedAt -gt $EvaluationTime -or
        ($timesValid -and ($EvaluationTime - $observedAt).TotalDays -gt [int64]$GovernedFreshness.maximumAgeDays) -or
        [string]$SourceFreshness.observedAt -cne [string]$GovernedFreshness.observedAt -or
        [string]$SourceFreshness.admittedAt -cne [string]$GovernedFreshness.admittedAt -or
        [string]$SourceFreshness.policyRef -cne $expectedSourcePolicyRef -or
        ($SourceFreshness.maxAgeDays -isnot [int] -and $SourceFreshness.maxAgeDays -isnot [long]) -or
        [int64]$SourceFreshness.maxAgeDays -ne [int64]$GovernedFreshness.maximumAgeDays -or
        [string]$SourceFreshness.dependencySnapshotRef -cne [string]$GovernedFreshness.dependencySnapshotRef -or
        [string]$SourceFreshness.dependencySnapshotDigest -cne [string]$GovernedFreshness.dependencySnapshotDigest -or
        [string]$SourceFreshness.dependencyStatus -cne 'MATCH') {
        Add-BlueprintError -Errors $Errors -Code 'FLEET_PORTFOLIO_CLAIM_FRESHNESS_INVALID' -Message "$Context source freshness is stale, out of order, or differs from the exact governed fleet policy and platform dependency binding."
    }
}

function Test-DistributionPerUnitRunProof {
    param(
        [Parameter(Mandatory = $true)]$Distribution,
        [Parameter(Mandatory = $true)][string]$Context,
        [Parameter(Mandatory = $true)][AllowEmptyCollection()][System.Collections.ArrayList]$Errors
    )

    $proofValid = $Distribution.perUnitRunCounts -is [System.Collections.IList] -and
        ($Distribution.unitCount -is [int] -or $Distribution.unitCount -is [long]) -and
        ($Distribution.runCount -is [int] -or $Distribution.runCount -is [long]) -and
        ($Distribution.requiredUnits -is [int] -or $Distribution.requiredUnits -is [long]) -and
        ($Distribution.requiredRuns -is [int] -or $Distribution.requiredRuns -is [long])
    $rows = @($Distribution.perUnitRunCounts)
    $unitRefs = [System.Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal)
    [System.Numerics.BigInteger]$acceptedRunTotal = [System.Numerics.BigInteger]::Zero
    if ($proofValid) {
        $proofValid = [int64]$Distribution.unitCount -ge [int64]$Distribution.requiredUnits -and
            $rows.Count -eq [int64]$Distribution.unitCount
    }
    foreach ($row in $rows) {
        if ($row -isnot [pscustomobject]) { $proofValid = $false; continue }
        Test-RequiredProperties -Object $row -Names @('unitRef','acceptedRunCount') -Context "$Context per-unit run proof" -Errors $Errors
        Test-AllowedProperties -Object $row -Names @('unitRef','acceptedRunCount') -Context "$Context per-unit run proof" -Errors $Errors
        if ([string]$row.unitRef -cnotmatch '^private://fleet-units/sha256/[0-9a-f]{64}$' -or
            -not $unitRefs.Add([string]$row.unitRef) -or
            ($row.acceptedRunCount -isnot [int] -and $row.acceptedRunCount -isnot [long]) -or
            [int64]$row.acceptedRunCount -lt [int64]$Distribution.requiredRuns) {
            $proofValid = $false
            continue
        }
        $acceptedRunTotal += [System.Numerics.BigInteger][int64]$row.acceptedRunCount
    }
    if (-not $proofValid -or $acceptedRunTotal -ne [System.Numerics.BigInteger][int64]$Distribution.runCount) {
        Add-BlueprintError -Errors $Errors -Code 'DISTRIBUTION_PER_UNIT_RUN_PROOF_INVALID' -Message "$Context must prove one privacy-safe unique row per accepted unit, the frozen repetitions on every unit, and an exact accepted-run total."
    }
}

function Test-PortableEvidenceDistributionCrosswalk {
    param(
        [AllowNull()]$SourceEvidence,
        [Parameter(Mandatory = $true)]$Distribution,
        [switch]$AllowCacheConsumer,
        [Parameter(Mandatory = $true)][string]$Context,
        [Parameter(Mandatory = $true)][AllowEmptyCollection()][System.Collections.ArrayList]$Errors
    )

    $portableDistribution = if ($null -ne $SourceEvidence) { $SourceEvidence.distribution } else { $null }
    $portableCoverage = if ($null -ne $SourceEvidence) { $SourceEvidence.coverage } else { $null }
    $portableSubject = if ($null -ne $SourceEvidence -and $SourceEvidence.payload -is [pscustomobject]) { $SourceEvidence.payload.subject } else { $null }
    $portableBaseline = if ($null -ne $SourceEvidence -and $SourceEvidence.payload -is [pscustomobject]) { $SourceEvidence.payload.baseline } else { $null }
    $valid = $null -ne $SourceEvidence -and [string]$SourceEvidence.provenance -ceq 'T0' -and
        $portableDistribution -is [pscustomobject] -and $portableCoverage -is [pscustomobject] -and
        $portableSubject -is [pscustomobject] -and $portableBaseline -is [pscustomobject] -and
        $SourceEvidence.result -is [pscustomobject] -and [string]$SourceEvidence.result.status -ceq 'PASS' -and
        [string]$SourceEvidence.subjectRef -ceq [string]$portableSubject.manifestRef -and
        [string]$SourceEvidence.controlRole -ceq [string]$portableSubject.role -and
        [string]$SourceEvidence.baselineFingerprint -ceq [string]$portableBaseline.baselineFingerprintSha256 -and
        ($AllowCacheConsumer -or [string]$SourceEvidence.distributionRef -ceq [string]$Distribution.recordId)

    $runs = @($portableDistribution.runs)
    $runIds = [System.Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal)
    $deviceIds = [System.Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal)
    $runsValid = $runs.Count -gt 0
    foreach ($run in $runs) {
        if ($run -isnot [pscustomobject] -or -not (Test-NonBlankString $run.runId) -or
            -not (Test-NonBlankString $run.deviceId) -or -not $runIds.Add([string]$run.runId)) {
            $runsValid = $false
            continue
        }
        [void]$deviceIds.Add([string]$run.deviceId)
    }
    $countsValid = ($portableDistribution.unitCount -is [int] -or $portableDistribution.unitCount -is [long]) -and
        ($portableDistribution.runCount -is [int] -or $portableDistribution.runCount -is [long]) -and
        ($portableCoverage.plannedUnits -is [int] -or $portableCoverage.plannedUnits -is [long]) -and
        ($portableCoverage.observedUnits -is [int] -or $portableCoverage.observedUnits -is [long]) -and
        ($portableCoverage.plannedRuns -is [int] -or $portableCoverage.plannedRuns -is [long]) -and
        ($portableCoverage.observedRuns -is [int] -or $portableCoverage.observedRuns -is [long]) -and
        $runsValid -and $runs.Count -eq [int64]$portableDistribution.runCount -and
        $deviceIds.Count -eq [int64]$portableDistribution.unitCount -and
        [int64]$portableDistribution.unitCount -eq [int64]$Distribution.unitCount -and
        [int64]$portableDistribution.runCount -eq [int64]$Distribution.runCount -and
        [int64]$portableCoverage.plannedUnits -eq [int64]$Distribution.coverage.expected -and
        [int64]$portableCoverage.observedUnits -eq [int64]$Distribution.coverage.observed -and
        [int64]$portableCoverage.observedUnits -eq [int64]$portableDistribution.unitCount -and
        [int64]$portableCoverage.observedRuns -eq [int64]$portableDistribution.runCount -and
        [System.Numerics.BigInteger][int64]$portableCoverage.plannedRuns -ge
            ([System.Numerics.BigInteger][int64]$portableCoverage.plannedUnits * [System.Numerics.BigInteger][int64]$Distribution.requiredRuns) -and
        [int64]$portableCoverage.observedRuns -le [int64]$portableCoverage.plannedRuns
    $valid = $valid -and $countsValid

    $numericValid = $portableDistribution.summary -is [pscustomobject] -and
        [string]$portableDistribution.summary.kind -ceq 'numeric' -and
        (Test-NumberValue $portableDistribution.summary.median) -and (Test-NumberValue $Distribution.median) -and
        $portableDistribution.summary.spread -is [pscustomobject] -and
        $Distribution.spread -is [pscustomobject] -and
        (Test-NumberValue $portableDistribution.runVariationPct) -and
        $null -ne $Distribution.runVariation.PSObject.Properties['coefficientOfVariation'] -and
        (Test-NumberValue $Distribution.runVariation.coefficientOfVariation)
    if ($numericValid) {
        try {
            $numericValid = [decimal]$portableDistribution.summary.median -eq [decimal]$Distribution.median -and
                [decimal]$portableDistribution.runVariationPct -eq [decimal]$Distribution.runVariation.coefficientOfVariation
            if ([string]$portableDistribution.summary.spread.kind -ceq 'range') {
                $numericValid = $numericValid -and (Test-NumberValue $portableDistribution.summary.spread.min) -and
                    (Test-NumberValue $portableDistribution.summary.spread.max) -and
                    (Test-NumberValue $Distribution.spread.minimum) -and (Test-NumberValue $Distribution.spread.maximum) -and
                    [decimal]$portableDistribution.summary.spread.min -eq [decimal]$Distribution.spread.minimum -and
                    [decimal]$portableDistribution.summary.spread.max -eq [decimal]$Distribution.spread.maximum
            }
            elseif ([string]$portableDistribution.summary.spread.kind -ceq 'percentile') {
                $numericValid = $numericValid -and
                    $null -ne $Distribution.spread.PSObject.Properties['p95'] -and
                    (Test-NumberValue $portableDistribution.summary.spread.p05) -and
                    (Test-NumberValue $portableDistribution.summary.spread.p95) -and
                    (Test-NumberValue $Distribution.spread.minimum) -and (Test-NumberValue $Distribution.spread.maximum) -and
                    (Test-NumberValue $Distribution.spread.p95) -and
                    [decimal]$portableDistribution.summary.spread.p95 -eq [decimal]$Distribution.spread.p95 -and
                    [decimal]$Distribution.spread.minimum -le [decimal]$portableDistribution.summary.spread.p05 -and
                    [decimal]$Distribution.spread.maximum -ge [decimal]$portableDistribution.summary.spread.p95
            }
            else { $numericValid = $false }
        }
        catch { $numericValid = $false }
    }
    $valid = $valid -and $numericValid

    $coverageValid = (Test-NumberValue $portableCoverage.percent) -and (Test-NumberValue $Distribution.coverage.percent)
    if ($coverageValid) {
        try {
            [decimal]$expectedPercent = ([decimal]$portableCoverage.observedUnits / [decimal]$portableCoverage.plannedUnits) * [decimal]100
            $coverageValid = [Math]::Abs([double]([decimal]$portableCoverage.percent - $expectedPercent)) -le 0.01 -and
                [decimal]$portableCoverage.percent -eq [decimal]$Distribution.coverage.percent
        }
        catch { $coverageValid = $false }
    }
    $valid = $valid -and $coverageValid

    [System.Numerics.BigInteger]$missingTotal = 0
    $missingReasons = [System.Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal)
    $missingProjectionValid = $portableDistribution.missingResults -is [pscustomobject] -and
        ($portableDistribution.missingResults.count -is [int] -or $portableDistribution.missingResults.count -is [long])
    foreach ($finding in @($Distribution.missingResults)) {
        if ($finding -isnot [pscustomobject] -or ($finding.count -isnot [int] -and $finding.count -isnot [long]) -or
            [int64]$finding.count -lt 0) { $missingProjectionValid = $false; continue }
        $missingTotal += [System.Numerics.BigInteger][int64]$finding.count
        if (Test-NonBlankString $finding.reason) { [void]$missingReasons.Add([string]$finding.reason) }
    }
    [string[]]$portableMissingReasons = @($portableDistribution.missingResults.reasons | ForEach-Object { [string]$_ })
    [string[]]$operationMissingReasons = @($missingReasons)
    if ($portableMissingReasons.Count -gt 1) { [Array]::Sort($portableMissingReasons, [StringComparer]::Ordinal) }
    if ($operationMissingReasons.Count -gt 1) { [Array]::Sort($operationMissingReasons, [StringComparer]::Ordinal) }
    $missingProjectionValid = $missingProjectionValid -and
        $missingTotal -eq [System.Numerics.BigInteger][int64]$portableDistribution.missingResults.count -and
        [int64]$portableDistribution.missingResults.count -eq ([int64]$portableCoverage.plannedRuns - [int64]$portableCoverage.observedRuns) -and
        (Test-CanonicalValueEqual $portableMissingReasons $operationMissingReasons)
    $valid = $valid -and $missingProjectionValid

    $portableOutlierCounts = [System.Collections.Generic.Dictionary[string,int64]]::new([StringComparer]::Ordinal)
    $operationOutlierCounts = [System.Collections.Generic.Dictionary[string,int64]]::new([StringComparer]::Ordinal)
    $outliersValid = $true
    foreach ($outlier in @($portableDistribution.excludedOutliers)) {
        if ($outlier -isnot [pscustomobject] -or -not (Test-NonBlankString $outlier.reason)) { $outliersValid = $false; continue }
        $reason = [string]$outlier.reason
        if (-not $portableOutlierCounts.ContainsKey($reason)) { $portableOutlierCounts.Add($reason, 0) }
        $portableOutlierCounts[$reason]++
    }
    foreach ($finding in @($Distribution.outliers)) {
        if ($finding -isnot [pscustomobject] -or ($finding.count -isnot [int] -and $finding.count -isnot [long]) -or
            [int64]$finding.count -lt 0 -or ([int64]$finding.count -gt 0 -and -not (Test-NonBlankString $finding.reason))) {
            $outliersValid = $false
            continue
        }
        if (Test-NonBlankString $finding.reason) {
            $reason = [string]$finding.reason
            if (-not $operationOutlierCounts.ContainsKey($reason)) { $operationOutlierCounts.Add($reason, 0) }
            $operationOutlierCounts[$reason] += [int64]$finding.count
        }
    }
    $allOutlierReasons = [System.Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal)
    foreach ($reason in @($portableOutlierCounts.Keys)) { [void]$allOutlierReasons.Add([string]$reason) }
    foreach ($reason in @($operationOutlierCounts.Keys)) { [void]$allOutlierReasons.Add([string]$reason) }
    foreach ($reason in @($allOutlierReasons)) {
        $portableCount = if ($portableOutlierCounts.ContainsKey($reason)) { $portableOutlierCounts[$reason] } else { 0 }
        $operationCount = if ($operationOutlierCounts.ContainsKey($reason)) { $operationOutlierCounts[$reason] } else { 0 }
        if ($portableCount -ne $operationCount) { $outliersValid = $false }
    }
    $valid = $valid -and $outliersValid

    if (-not $valid) {
        Add-BlueprintError -Errors $Errors -Code 'DISTRIBUTION_PORTABLE_EVIDENCE_CROSSWALK_INVALID' -Message "$Context does not exactly reconcile the normative portable T0 subject, baseline, distribution, run identities, summary, variation, coverage, missingness, and outliers with the linked operations distribution."
    }
    return $valid
}

function Test-DistributionSourceEvidenceClosure {
    param(
        [Parameter(Mandatory = $true)]$Distribution,
        [Parameter(Mandatory = $true)]$RecordMap,
        [Parameter(Mandatory = $true)][DateTimeOffset]$EvaluationTime,
        [AllowNull()]$ExpectedEvidenceRecord,
        [switch]$CacheAdmissionSemanticsAlreadyValidated,
        [Parameter(Mandatory = $true)][string]$Context,
        [Parameter(Mandatory = $true)][AllowEmptyCollection()][System.Collections.ArrayList]$Errors
    )

    Test-RequiredProperties -Object $Distribution -Names @(
        'sourceEvidenceRef','sourceEvidenceDigest','sourceEvidenceReleaseRef','sourceEvidenceReleaseSubjectDigest'
    ) -Context $Context -Errors $Errors
    $source = Resolve-CanonicalRecord -RecordMap $RecordMap -Reference $Distribution.sourceEvidenceRef `
        -ExpectedTypes @('evidence-record') -Context "$Context source evidence" -Errors $Errors
    $release = Resolve-CanonicalRecord -RecordMap $RecordMap -Reference $Distribution.sourceEvidenceReleaseRef `
        -ExpectedTypes @('evidence-release') -Context "$Context source evidence release" -Errors $Errors
    $hasCacheAdmissionRef = Test-NonBlankString $Distribution.compatibilityCacheAdmissionRef
    $hasCacheAdmissionDigest = Test-NonBlankString $Distribution.compatibilityCacheAdmissionDigest
    $isCacheConsumer = $hasCacheAdmissionRef -and $hasCacheAdmissionDigest -and
        [string]$Distribution.testClass -ceq 'application-compatibility'
    $cacheAdmission = if ($isCacheConsumer -and
        -not ([string]$Distribution.compatibilityCacheAdmissionRef).Contains('#') -and
        $RecordMap.ContainsKey([string]$Distribution.compatibilityCacheAdmissionRef)) {
        $RecordMap[[string]$Distribution.compatibilityCacheAdmissionRef]
    }
    else { $null }
    $valid = $null -ne $source -and $null -ne $release -and
        [string]$Distribution.sourceEvidenceRef -ceq [string]$source.recordId -and
        [string]$Distribution.sourceEvidenceDigest -ceq [string]$source.contentDigest -and
        [string]$Distribution.sourceEvidenceReleaseRef -ceq [string]$release.recordId -and
        [string]$Distribution.sourceEvidenceReleaseSubjectDigest -ceq [string]$release.releaseSubjectDigest -and
        [string]$source.evidenceReleaseRef -ceq [string]$release.recordId -and
        @($release.memberRecordIds) -ccontains [string]$source.recordId
    if ($isCacheConsumer) {
        $valid = $valid -and $null -ne $cacheAdmission -and
            [string]$cacheAdmission.recordType -ceq 'compatibility-cache-admission-record' -and
            [string]$cacheAdmission.status -ceq 'ADMITTED' -and
            [string]$cacheAdmission.contentDigest -ceq [string]$Distribution.compatibilityCacheAdmissionDigest -and
            [string]$cacheAdmission.currentConsumerRef -ceq [string]$Distribution.recordId -and
            (Test-NonBlankString $source.distributionRef) -and
            -not ([string]$source.distributionRef).Contains('#') -and
            @($release.memberRecordIds) -ccontains [string]$source.distributionRef
    }
    else {
        $valid = $valid -and -not $hasCacheAdmissionRef -and -not $hasCacheAdmissionDigest -and
            [string]$source.distributionRef -ceq [string]$Distribution.recordId -and
            @($release.memberRecordIds) -ccontains [string]$Distribution.recordId
    }
    if ($null -ne $ExpectedEvidenceRecord) {
        $valid = $valid -and [string]$source.recordId -ceq [string]$ExpectedEvidenceRecord.recordId -and
            [string]$source.contentDigest -ceq [string]$ExpectedEvidenceRecord.contentDigest
    }
    $valid = (Test-PortableEvidenceDistributionCrosswalk -SourceEvidence $source -Distribution $Distribution `
        -AllowCacheConsumer:$isCacheConsumer -Context $Context -Errors $Errors) -and $valid
    if ($null -ne $release) {
        Test-EvidenceReleaseBinding -ReleaseRecord $release -EvidenceRecords @($source) -RecordMap $RecordMap `
            -EvaluationTime $EvaluationTime -HistoricalCacheRelease:$isCacheConsumer `
            -CacheAdmissionSemanticsAlreadyValidated:$CacheAdmissionSemanticsAlreadyValidated `
            -Context $Context -Errors $Errors
    }
    if (-not $valid) {
        Add-BlueprintError -Errors $Errors -Code 'DISTRIBUTION_SOURCE_EVIDENCE_BINDING_INVALID' -Message "$Context does not bind the exact source-evidence digest, back-reference, current release digest, and common release membership."
    }
    return [pscustomobject]@{ SourceEvidence = $source; Release = $release; Valid = $valid }
}

function Test-CapacityInputBindings {
    param(
        [AllowNull()]$CalculationEvidence,
        [AllowNull()]$CapacityWaterfall,
        [AllowNull()]$Manifest,
        [AllowNull()]$Phase0TestPlan,
        [AllowNull()]$ThresholdPolicy,
        [AllowNull()]$VerdictRecord,
        [Parameter(Mandatory = $true)]$Chain,
        [Parameter(Mandatory = $true)]$RecordMap,
        [Parameter(Mandatory = $true)][DateTimeOffset]$EvaluationTime,
        [Parameter(Mandatory = $true)][AllowEmptyCollection()][System.Collections.ArrayList]$Errors
    )

    $initialErrorCount = $Errors.Count
    if ($CalculationEvidence -isnot [pscustomobject] -or $CalculationEvidence.result -isnot [pscustomobject] -or
        $CapacityWaterfall -isnot [pscustomobject] -or $Manifest -isnot [pscustomobject] -or
        $Phase0TestPlan -isnot [pscustomobject] -or $ThresholdPolicy -isnot [pscustomobject] -or
        $VerdictRecord -isnot [pscustomobject]) {
        Add-BlueprintError -Errors $Errors -Code 'CAPACITY_INPUT_BINDING_INVALID' -Message 'Capacity calculation lacks the exact manifest, Phase 0 authorities, final verdict, or structured input bindings.'
        return $false
    }

    $personaMatches = @()
    for ($personaIndex = 0; $personaIndex -lt @($Manifest.personas).Count; $personaIndex++) {
        if ([string]$Manifest.personas[$personaIndex].name -ceq [string]$Chain.personaNeed.personaId) {
            $personaMatches += @($personaIndex)
        }
    }
    if ($personaMatches.Count -ne 1) {
        Add-BlueprintError -Errors $Errors -Code 'CAPACITY_INPUT_BINDING_INVALID' -Message 'Capacity calculation does not resolve exactly one frozen manifest persona.'
        return $false
    }
    $selectedPersonaIndex = [int]$personaMatches[0]
    $capacityPolicy = if ($ThresholdPolicy.extensions -is [pscustomobject] -and
        $ThresholdPolicy.extensions.operationsBlueprintV1 -is [pscustomobject]) {
        $ThresholdPolicy.extensions.operationsBlueprintV1
    }
    else { $null }
    if ($null -eq $capacityPolicy -or
        -not (Test-NonBlankString $capacityPolicy.capacityCorporateFloorMetricId) -or
        -not (Test-NonBlankString $capacityPolicy.capacityCorporateImageMetricId)) {
        Add-BlueprintError -Errors $Errors -Code 'CAPACITY_INPUT_POLICY_INVALID' -Message 'The exact frozen threshold policy lacks approved corporate-floor memory and image metric identifiers.'
        return $false
    }

    $expected = [ordered]@{
        physicalMemoryGB = [pscustomobject]@{ RecordRef = [string]$Manifest.recordId; Pointer = '/hardwareEnvelope/memory/totalGB'; Value = $CapacityWaterfall.memory.physicalMemoryGB; Kind = 'MANIFEST'; MetricId = '' }
        corporateFloorGB = [pscustomobject]@{ RecordRef = ''; Pointer = '/median'; Value = $CapacityWaterfall.memory.corporateFloorGB; Kind = 'CORPORATE_FLOOR'; MetricId = [string]$capacityPolicy.capacityCorporateFloorMetricId }
        personaRequirementGB = [pscustomobject]@{ RecordRef = [string]$Manifest.recordId; Pointer = "/personas/$selectedPersonaIndex/extensions/operationsBlueprintV1/personaRequirementGB"; Value = $CapacityWaterfall.memory.personaRequirementGB; Kind = 'MANIFEST'; MetricId = '' }
        formattedCapacityGB = [pscustomobject]@{ RecordRef = [string]$Manifest.recordId; Pointer = '/hardwareEnvelope/storage/minCapacityGB'; Value = $CapacityWaterfall.storage.formattedCapacityGB; Kind = 'MANIFEST'; MetricId = '' }
        corporateImageGB = [pscustomobject]@{ RecordRef = ''; Pointer = '/median'; Value = $CapacityWaterfall.storage.corporateImageGB; Kind = 'CORPORATE_FLOOR'; MetricId = [string]$capacityPolicy.capacityCorporateImageMetricId }
        personaWorkingSetGB = [pscustomobject]@{ RecordRef = [string]$Manifest.recordId; Pointer = "/personas/$selectedPersonaIndex/extensions/operationsBlueprintV1/personaWorkingSetGB"; Value = $CapacityWaterfall.storage.personaWorkingSetGB; Kind = 'MANIFEST'; MetricId = '' }
    }
    $bindings = @($CalculationEvidence.result.capacityInputBindings)
    $bindingByName = [System.Collections.Generic.Dictionary[string,object]]::new([StringComparer]::Ordinal)
    $bindingsValid = $CalculationEvidence.result.capacityInputBindings -is [System.Collections.IList] -and
        $bindings.Count -eq $expected.Count
    foreach ($binding in $bindings) {
        if ($binding -isnot [pscustomobject]) { $bindingsValid = $false; continue }
        Test-RequiredProperties -Object $binding -Names @('inputName','recordRef','contentDigest','pointer','valueDigest') -Context 'capacity input binding' -Errors $Errors
        Test-AllowedProperties -Object $binding -Names @('inputName','recordRef','contentDigest','pointer','valueDigest') -Context 'capacity input binding' -Errors $Errors
        $inputName = [string]$binding.inputName
        if (-not $expected.Contains($inputName) -or $bindingByName.ContainsKey($inputName)) {
            $bindingsValid = $false
            continue
        }
        $bindingByName.Add($inputName, $binding)
    }

    $corporateDistributionRefs = [System.Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal)
    foreach ($inputName in @($expected.Keys)) {
        if (-not $bindingByName.ContainsKey([string]$inputName)) { $bindingsValid = $false; continue }
        $binding = $bindingByName[[string]$inputName]
        $definition = $expected[[string]$inputName]
        $recordRef = [string]$binding.recordRef
        if (-not (Test-NonBlankString $recordRef) -or $recordRef.Contains('#') -or
            -not $RecordMap.ContainsKey($recordRef) -or -not (Test-Sha256Token $binding.contentDigest) -or
            -not (Test-Sha256Token $binding.valueDigest)) {
            $bindingsValid = $false
            continue
        }
        $sourceRecord = $RecordMap[$recordRef]
        $valueFound = $false
        $sourceValue = Get-JsonPointerValue -Document $sourceRecord.payload -Pointer ([string]$binding.pointer) -Found ([ref]$valueFound)
        $valueValid = $valueFound -and (Test-NumberValue $sourceValue) -and
            (Test-CanonicalJsonRuntimeDomain $sourceValue) -and
            (Test-NumberValue $definition.Value) -and
            (Test-CanonicalJsonRuntimeDomain $definition.Value)
        if ($valueValid) {
            try { $valueValid = [decimal]$sourceValue -eq [decimal]$definition.Value }
            catch { $valueValid = $false }
        }
        if ([string]$sourceRecord.contentDigest -cne [string]$binding.contentDigest -or
            [string]$binding.pointer -cne [string]$definition.Pointer -or
            [string]$binding.valueDigest -cne [string](Get-CanonicalPayloadDigest -Payload $sourceValue) -or
            -not $valueValid) {
            $bindingsValid = $false
        }

        if ([string]$definition.Kind -ceq 'MANIFEST') {
            if ($recordRef -cne [string]$definition.RecordRef -or [string]$sourceRecord.recordType -cne 'candidate-manifest') {
                $bindingsValid = $false
            }
        }
        else {
            if ([string]$sourceRecord.recordType -cne 'distribution-record' -or
                [string]$sourceRecord.testClass -cne 'corporate-floor' -or
                [string]$sourceRecord.metricId -cne [string]$definition.MetricId -or
                -not $corporateDistributionRefs.Add($recordRef)) {
                $bindingsValid = $false
                continue
            }
            $closure = Test-DistributionSourceEvidenceClosure -Distribution $sourceRecord -RecordMap $RecordMap `
                -EvaluationTime $EvaluationTime -ExpectedEvidenceRecord $null `
                -Context "capacity $inputName distribution" -Errors $Errors
            if ($null -eq $closure.SourceEvidence -or $null -eq $closure.Release -or
                [string]$closure.SourceEvidence.subjectRef -cne [string]$Manifest.recordId -or
                @($VerdictRecord.evidenceReleases) -cnotcontains [string]$closure.Release.recordId) {
                $bindingsValid = $false
            }
            else {
                [void](Test-DistributionPhase0FloorBinding -Distribution $sourceRecord -Phase0TestPlan $Phase0TestPlan `
                    -ExpectedEvidenceRecord $closure.SourceEvidence -ExpectedTestPlanRef ([string]$Phase0TestPlan.recordId) `
                    -Context "capacity $inputName distribution" -Errors $Errors)
                Test-PortableEvidenceAdmissionSemantics -Evidence $closure.SourceEvidence -Distribution $sourceRecord `
                    -Manifest $Manifest -Phase0TestPlan $Phase0TestPlan -ThresholdPolicy $ThresholdPolicy `
                    -RecordMap $RecordMap -CurrentRelease $closure.Release -EvaluationTime $EvaluationTime -Errors $Errors
            }
        }
    }
    if (-not $bindingsValid -or $Errors.Count -gt $initialErrorCount) {
        Add-BlueprintError -Errors $Errors -Code 'CAPACITY_INPUT_BINDING_INVALID' -Message 'Capacity inputs do not resolve exact digest-bound manifest HCE/persona values and fresh corporate-floor/image distributions under the frozen Phase 0 authorities.'
        return $false
    }
    return $true
}

function Test-CapacityWaterfallSemantics {
    param(
        [AllowNull()]$CapacityWaterfall,
        [AllowNull()]$VerdictRecord,
        [AllowNull()]$Phase0TestPlan,
        [AllowNull()]$ThresholdPolicy,
        [AllowNull()]$Manifest,
        [Parameter(Mandatory = $true)]$Chain,
        [Parameter(Mandatory = $true)]$RecordMap,
        [Parameter(Mandatory = $true)][DateTimeOffset]$EvaluationTime,
        [Parameter(Mandatory = $true)][AllowEmptyCollection()][System.Collections.ArrayList]$Errors
    )

    if ($CapacityWaterfall -isnot [pscustomobject] -or $null -eq $VerdictRecord -or
        $null -eq $Phase0TestPlan -or $null -eq $ThresholdPolicy) {
        Add-BlueprintError -Errors $Errors -Code 'CAPACITY_WATERFALL_SEMANTICS_INVALID' -Message 'Capacity readiness lacks a selected waterfall, final verdict, or exact frozen threshold policy.'
        return
    }
    Test-RequiredProperties -Object $CapacityWaterfall -Names @('thresholdPolicyRef','calculationEvidenceRef','memory','storage') -Context 'selected capacity waterfall' -Errors $Errors
    $calculationEvidence = Resolve-CanonicalRecord -RecordMap $RecordMap -Reference $CapacityWaterfall.calculationEvidenceRef `
        -ExpectedTypes @('evidence-record') -Context 'capacity calculation evidence' -Errors $Errors
    $calculationRelease = if ($null -ne $calculationEvidence) {
        Resolve-CanonicalRecord -RecordMap $RecordMap -Reference $calculationEvidence.evidenceReleaseRef `
            -ExpectedTypes @('evidence-release') -Context 'capacity calculation evidence release' -Errors $Errors
    }
    else { $null }
    if ($null -ne $calculationRelease) {
        Test-RequiredProperties -Object $calculationRelease -Names @(
            'testPlanRef','testPlanDigest','thresholdPolicyRef','thresholdPolicyDigest',
            'memberRecordIds','semanticGateStatus','samplingFloorStatus','distributionStatus','coverageStatus'
        ) -Context 'capacity calculation evidence release' -Errors $Errors
    }
    $sourceCapacity = if ($null -ne $calculationEvidence -and $calculationEvidence.result -is [pscustomobject]) {
        $calculationEvidence.result.capacityWaterfall
    }
    else { $null }
    $sourceBindingValid = $null -ne $calculationEvidence -and $null -ne $calculationRelease -and
        [string]$CapacityWaterfall.thresholdPolicyRef -ceq [string]$ThresholdPolicy.recordId -and
        [string]$Phase0TestPlan.thresholdPolicyRef -ceq [string]$ThresholdPolicy.recordId -and
        [string]$calculationEvidence.result.status -ceq 'PASS' -and
        $sourceCapacity -is [pscustomobject] -and
        (Test-CanonicalValueEqual $sourceCapacity $CapacityWaterfall) -and
        [string]$calculationEvidence.provenance -ceq 'T0' -and
        [string]$calculationEvidence.evidenceUse -ceq 'gate-or-verdict' -and
        [string]$calculationEvidence.subjectRef -ceq [string]$Chain.personaNeed.manifestRef -and
        [string]$calculationEvidence.personaId -ceq [string]$Chain.personaNeed.personaId -and
        [string]$calculationEvidence.testPlanRef -ceq [string]$Phase0TestPlan.recordId -and
        [string]$calculationEvidence.evidenceReleaseRef -ceq [string]$Chain.personaNeed.evidenceReleaseRef -and
        [string]$calculationRelease.recordId -ceq [string]$Chain.personaNeed.evidenceReleaseRef -and
        [string]$calculationRelease.testPlanRef -ceq [string]$Phase0TestPlan.recordId -and
        [string]$calculationRelease.testPlanDigest -ceq [string]$Phase0TestPlan.contentDigest -and
        [string]$calculationRelease.thresholdPolicyRef -ceq [string]$ThresholdPolicy.recordId -and
        [string]$calculationRelease.thresholdPolicyDigest -ceq [string]$ThresholdPolicy.contentDigest -and
        @($calculationRelease.memberRecordIds) -ccontains [string]$calculationEvidence.recordId -and
        @($VerdictRecord.evidenceReleases) -ccontains [string]$calculationRelease.recordId -and
        @($Chain.personaNeed.evidenceRefs) -ccontains [string]$calculationEvidence.recordId -and
        [string]$calculationRelease.semanticGateStatus -ceq 'PASS' -and
        [string]$calculationRelease.samplingFloorStatus -ceq 'PASS' -and
        [string]$calculationRelease.distributionStatus -ceq 'PASS' -and
        [string]$calculationRelease.coverageStatus -ceq 'PASS'
    if (-not $sourceBindingValid) {
        Add-BlueprintError -Errors $Errors -Code 'CAPACITY_CALCULATION_EVIDENCE_INVALID' -Message 'The capacity waterfall is not the exact PASS result of validated T0 persona evidence in the retained verdict release and semantic source closure.'
    }
    [void](Test-CapacityInputBindings -CalculationEvidence $calculationEvidence -CapacityWaterfall $CapacityWaterfall `
        -Manifest $Manifest -Phase0TestPlan $Phase0TestPlan -ThresholdPolicy $ThresholdPolicy `
        -VerdictRecord $VerdictRecord -Chain $Chain -RecordMap $RecordMap -EvaluationTime $EvaluationTime -Errors $Errors)

    $memory = $CapacityWaterfall.memory
    $storage = $CapacityWaterfall.storage
    if ($memory -isnot [pscustomobject] -or $storage -isnot [pscustomobject] -or
        $ThresholdPolicy.reserves -isnot [pscustomobject]) {
        Add-BlueprintError -Errors $Errors -Code 'CAPACITY_WATERFALL_SEMANTICS_INVALID' -Message 'Capacity memory, storage, or frozen reserve inputs are missing.'
        return
    }
    $memoryFields = @('physicalMemoryGB','corporateFloorGB','memoryReserveGB','remainingWorkloadHeadroomGB','personaRequirementGB')
    $storageFields = @('formattedCapacityGB','corporateImageGB','storageReserveGB','personaWorkingSetGB','remainingWorkloadHeadroomGB')
    $numbersValid = $true
    foreach ($field in $memoryFields) {
        if (-not (Test-NumberValue $memory.$field) -or -not (Test-CanonicalJsonRuntimeDomain $memory.$field)) { $numbersValid = $false }
    }
    foreach ($field in $storageFields) {
        if (-not (Test-NumberValue $storage.$field) -or -not (Test-CanonicalJsonRuntimeDomain $storage.$field)) { $numbersValid = $false }
    }
    foreach ($reserveValue in @($ThresholdPolicy.reserves.memoryReserveGB.value, $ThresholdPolicy.reserves.storageReserveGB.value)) {
        if (-not (Test-NumberValue $reserveValue) -or -not (Test-CanonicalJsonRuntimeDomain $reserveValue)) { $numbersValid = $false }
    }
    if (-not $numbersValid) {
        Add-BlueprintError -Errors $Errors -Code 'CAPACITY_NUMERIC_DOMAIN_INVALID' -Message 'Capacity inputs must be finite numbers in the frozen cross-host canonical domain.'
        return
    }

    $capacityPolicy = if ($ThresholdPolicy.extensions -is [pscustomobject] -and
        $ThresholdPolicy.extensions.operationsBlueprintV1 -is [pscustomobject]) {
        $ThresholdPolicy.extensions.operationsBlueprintV1
    }
    else { $null }
    $toleranceValid = $null -ne $capacityPolicy -and
        (Test-NumberValue $capacityPolicy.capacityArithmeticToleranceGB) -and
        (Test-CanonicalJsonRuntimeDomain $capacityPolicy.capacityArithmeticToleranceGB) -and
        [decimal]$capacityPolicy.capacityArithmeticToleranceGB -gt 0 -and
        [decimal]$capacityPolicy.capacityArithmeticToleranceGB -le 1 -and
        (Test-NonBlankString $capacityPolicy.capacityArithmeticToleranceRationale) -and
        (Test-NonBlankString $capacityPolicy.capacityArithmeticToleranceApprovedBy)
    if (-not $toleranceValid) {
        Add-BlueprintError -Errors $Errors -Code 'CAPACITY_ARITHMETIC_POLICY_INVALID' -Message 'The authenticated frozen threshold policy lacks a finite positive bounded capacity arithmetic tolerance, rationale, and approver.'
        return
    }
    [decimal]$memoryPhysical = [decimal]$memory.physicalMemoryGB
    [decimal]$memoryFloor = [decimal]$memory.corporateFloorGB
    [decimal]$memoryReserve = [decimal]$memory.memoryReserveGB
    [decimal]$memoryRequirement = [decimal]$memory.personaRequirementGB
    [decimal]$storageCapacity = [decimal]$storage.formattedCapacityGB
    [decimal]$storageImage = [decimal]$storage.corporateImageGB
    [decimal]$storageReserve = [decimal]$storage.storageReserveGB
    [decimal]$storageWorkingSet = [decimal]$storage.personaWorkingSetGB
    $nonnegativeInputs = $memoryPhysical -ge 0 -and $memoryFloor -ge 0 -and $memoryReserve -ge 0 -and
        $memoryRequirement -ge 0 -and $storageCapacity -ge 0 -and $storageImage -ge 0 -and
        $storageReserve -ge 0 -and $storageWorkingSet -ge 0
    if (-not $nonnegativeInputs) {
        Add-BlueprintError -Errors $Errors -Code 'CAPACITY_NUMERIC_DOMAIN_INVALID' -Message 'Physical capacity, governed floors/reserves, and persona memory/storage requirements must be nonnegative.'
        return
    }
    [decimal]$memoryExpected = $memoryPhysical - $memoryFloor - $memoryReserve
    [decimal]$storageExpected = $storageCapacity - $storageImage - $storageReserve - $storageWorkingSet
    $memoryOutcome = if ($memoryExpected -ge $memoryRequirement) { 'PASS' } else { 'SHORTFALL' }
    $storageOutcome = if ($storageExpected -ge 0) { 'PASS' } else { 'SHORTFALL' }
    $arithmeticValid = $memoryReserve -eq [decimal]$ThresholdPolicy.reserves.memoryReserveGB.value -and
        $storageReserve -eq [decimal]$ThresholdPolicy.reserves.storageReserveGB.value -and
        [decimal]$memory.remainingWorkloadHeadroomGB -eq $memoryExpected -and
        [decimal]$storage.remainingWorkloadHeadroomGB -eq $storageExpected -and
        (($memoryFloor + $memoryReserve -le $memoryPhysical) -or [string]$memory.outcome -ceq 'SHORTFALL') -and
        (($storageImage + $storageReserve + $storageWorkingSet -le $storageCapacity) -or [string]$storage.outcome -ceq 'SHORTFALL') -and
        [string]$memory.outcome -ceq $memoryOutcome -and [string]$storage.outcome -ceq $storageOutcome
    if (-not $arithmeticValid) {
        Add-BlueprintError -Errors $Errors -Code 'CAPACITY_WATERFALL_ARITHMETIC_INVALID' -Message 'Capacity PASS or SHORTFALL does not match the exact frozen reserves and recomputed memory and storage headroom equations.'
    }
}

function Get-FleetPortfolioCoverageDomainDigest {
    param([Parameter(Mandatory = $true)]$FleetPortfolio)

    return Get-CanonicalPayloadDigest -Payload ([pscustomobject][ordered]@{
        privacyReleaseRef = [string]$FleetPortfolio.privacyReleaseRef
        privacyReleaseDigest = [string]$FleetPortfolio.privacyReleaseDigest
        snapshotAt = [string]$FleetPortfolio.snapshotAt
        observationWindow = [string]$FleetPortfolio.observationWindow
        scope = [pscustomobject][ordered]@{
            portfolioRecordId = [string]$FleetPortfolio.recordId
            populationCohortRef = [string]$FleetPortfolio.populationCohortRef
