        purpose = [string]$FleetPortfolio.coverage.populationCommitmentPurpose
        keyRef = [string]$FleetPortfolio.coverage.populationCommitmentKeyRef
        keyVersion = [string]$FleetPortfolio.coverage.populationCommitmentKeyVersion
