function Register-FleetPopulationProofBinding {
    param(
        [AllowNull()]$Reference,
        [AllowNull()]$Digest,
        [Parameter(Mandatory = $true)]$Governance,
        [Parameter(Mandatory = $true)][string]$Context,
        [Parameter(Mandatory = $true)][AllowEmptyCollection()][System.Collections.ArrayList]$Errors
    )

    if ($null -eq $Governance.PopulationProofRefs -or $null -eq $Governance.PopulationProofDigests) {
        Add-BlueprintError -Errors $Errors -Code 'FLEET_PORTFOLIO_POPULATION_COMMITMENT_INVALID' -Message "$Context lacks the fail-closed population-proof uniqueness registry."
        return $false
    }
    if ([string]$Reference -cnotmatch '^private://\S+$' -or -not (Test-Sha256Token $Digest) -or
        -not $Governance.PopulationProofRefs.Add([string]$Reference) -or
        -not $Governance.PopulationProofDigests.Add([string]$Digest)) {
        Add-BlueprintError -Errors $Errors -Code 'FLEET_PORTFOLIO_POPULATION_COMMITMENT_INVALID' -Message "$Context requires an ordinally unique private proof reference and SHA-256 artifact digest."
        return $false
    }
    return $true
}

function Register-FleetPopulationCommitmentDigest {
    param(
        [AllowNull()]$Digest,
        [AllowNull()]$DomainDigest,
        [Parameter(Mandatory = $true)]$Governance,
        [Parameter(Mandatory = $true)][string]$Context,
        [Parameter(Mandatory = $true)][AllowEmptyCollection()][System.Collections.ArrayList]$Errors
    )

    $registry = $Governance.PopulationCommitmentDomainsByDigest
    if ($null -eq $registry -or -not (Test-Sha256Token $Digest) -or -not (Test-Sha256Token $DomainDigest)) {
        Add-BlueprintError -Errors $Errors -Code 'FLEET_PORTFOLIO_POPULATION_COMMITMENT_INVALID' -Message "$Context lacks a valid domain-separated population commitment registry entry."
        return $false
    }
    if ($registry.ContainsKey([string]$Digest)) {
        if ([string]$registry[[string]$Digest] -cne [string]$DomainDigest) {
            Add-BlueprintError -Errors $Errors -Code 'FLEET_PORTFOLIO_POPULATION_COMMITMENT_INVALID' -Message "$Context reuses a population commitment across distinct release-scoped domains or purposes."
            return $false
        }
        return $true
    }
    $registry.Add([string]$Digest, [string]$DomainDigest)
    return $true
}

function Test-FleetPopulationCommitmentMetadata {
    param(
        [AllowNull()]$Binding,
        [Parameter(Mandatory = $true)][string]$ExpectedPurpose,
        [Parameter(Mandatory = $true)][string]$ExpectedDomainDigest,
        [AllowNull()]$ParentBinding,
        [Parameter(Mandatory = $true)]$Governance,
        [Parameter(Mandatory = $true)][string]$Context,
        [Parameter(Mandatory = $true)][AllowEmptyCollection()][System.Collections.ArrayList]$Errors,
        [switch]$CoverageBinding
    )

    $metadataFields = @(
        'proofScheme','proofVersion','populationCommitmentKeyRef','populationCommitmentKeyVersion',
        'populationCanonicalization','populationCanonicalizationVersion','populationCommitmentPurpose',
        'populationCommitmentDomainDigest'
    )
    $proofFields = if ($CoverageBinding) {
        @('populationPartitionProofRef','populationPartitionProofDigest')
    }
    else { @('populationSubsetProofRef','populationSubsetProofDigest') }
    if ($Binding -isnot [pscustomobject]) {
        Add-BlueprintError -Errors $Errors -Code 'FLEET_PORTFOLIO_POPULATION_COMMITMENT_INVALID' -Message "$Context lacks a structured privacy-safe population commitment."
        return $false
    }
    Test-RequiredProperties -Object $Binding -Names @($metadataFields + $proofFields) -Context "$Context population commitment" -Errors $Errors
    $valid = [string]$Binding.proofScheme -ceq 'HMAC_SHA256_SORTED_SET_COMMITMENT' -and
        [string]$Binding.proofVersion -ceq '1.0.0' -and
        [string]$Binding.populationCommitmentKeyRef -cmatch '^private://\S+$' -and
        [string]$Binding.populationCommitmentKeyVersion -cmatch '^[A-Za-z0-9][A-Za-z0-9._:-]{0,255}$' -and
        [string]$Binding.populationCanonicalization -ceq 'UTF8_NFC_LENGTH_PREFIXED_SORTED' -and
        [string]$Binding.populationCanonicalizationVersion -ceq '1.0.0' -and
        [string]$Binding.populationCommitmentPurpose -ceq $ExpectedPurpose -and
        (Test-Sha256Token $Binding.populationCommitmentDomainDigest) -and
        [string]$Binding.populationCommitmentDomainDigest -ceq $ExpectedDomainDigest
    if ($null -ne $ParentBinding) {
        $valid = $valid -and
            [string]$Binding.proofScheme -ceq [string]$ParentBinding.proofScheme -and
            [string]$Binding.proofVersion -ceq [string]$ParentBinding.proofVersion -and
            [string]$Binding.populationCommitmentKeyRef -ceq [string]$ParentBinding.populationCommitmentKeyRef -and
            [string]$Binding.populationCommitmentKeyVersion -ceq [string]$ParentBinding.populationCommitmentKeyVersion -and
            [string]$Binding.populationCanonicalization -ceq [string]$ParentBinding.populationCanonicalization -and
            [string]$Binding.populationCanonicalizationVersion -ceq [string]$ParentBinding.populationCanonicalizationVersion
    }
    $proofRef = if ($CoverageBinding) { $Binding.populationPartitionProofRef } else { $Binding.populationSubsetProofRef }
    $proofDigest = if ($CoverageBinding) { $Binding.populationPartitionProofDigest } else { $Binding.populationSubsetProofDigest }
    $valid = (Register-FleetPopulationProofBinding -Reference $proofRef -Digest $proofDigest -Governance $Governance -Context $Context -Errors $Errors) -and $valid
    if (-not $valid) {
        Add-BlueprintError -Errors $Errors -Code 'FLEET_PORTFOLIO_POPULATION_COMMITMENT_INVALID' -Message "$Context proof scheme, release-scoped domain, key version, canonicalization, purpose, or parent binding is not exact."
    }
    return $valid
}

function Test-FleetCoveragePopulationCommitment {
    param(
        [AllowNull()]$Coverage,
        [Parameter(Mandatory = $true)][string]$ExpectedPurpose,
        [Parameter(Mandatory = $true)][string]$ExpectedDomainDigest,
        [AllowNull()]$ParentCoverage,
        [Parameter(Mandatory = $true)]$Governance,
        [Parameter(Mandatory = $true)][string]$Context,
        [Parameter(Mandatory = $true)][AllowEmptyCollection()][System.Collections.ArrayList]$Errors
    )

    $digestFields = @(
        'plannedPopulationDigest','eligiblePopulationDigest','observedPopulationDigest',
        'missingPopulationDigest','excludedPopulationDigest'
    )
    if ($Coverage -isnot [pscustomobject]) {
        Add-BlueprintError -Errors $Errors -Code 'FLEET_PORTFOLIO_POPULATION_COMMITMENT_INVALID' -Message "$Context lacks committed planned, eligible, observed, missing, and excluded population sets."
        return $false
    }
    Test-RequiredProperties -Object $Coverage -Names $digestFields -Context "$Context population commitment" -Errors $Errors
    $valid = @($digestFields | Where-Object { -not (Test-Sha256Token $Coverage.$_) }).Count -eq 0
    foreach ($digestField in $digestFields) {
        $valid = (Register-FleetPopulationCommitmentDigest -Digest $Coverage.$digestField `
            -DomainDigest $ExpectedDomainDigest -Governance $Governance `
            -Context "$Context $digestField" -Errors $Errors) -and $valid
    }
    $metadataValid = Test-FleetPopulationCommitmentMetadata -Binding $Coverage -ExpectedPurpose $ExpectedPurpose `
        -ExpectedDomainDigest $ExpectedDomainDigest -ParentBinding $ParentCoverage -Governance $Governance `
        -Context $Context -Errors $Errors -CoverageBinding
    $valid = $valid -and $metadataValid
    if (-not $valid) {
        Add-BlueprintError -Errors $Errors -Code 'FLEET_PORTFOLIO_POPULATION_COMMITMENT_INVALID' -Message "$Context population-set digests or domain-separated proof metadata are incomplete or invalid. Cross-domain set relationships require the authenticated private proof resolver."
    }
    return $valid
}

function Test-FleetConfigurationPopulationCommitment {
    param(
        [Parameter(Mandatory = $true)]$FleetPortfolio,
        [AllowNull()]$ConfigurationCohort,
        [Parameter(Mandatory = $true)]$Governance,
        [Parameter(Mandatory = $true)][string]$Context,
        [Parameter(Mandatory = $true)][AllowEmptyCollection()][System.Collections.ArrayList]$Errors
    )

    $fields = @(
        'configurationRef','cohortRef','observedDeviceCount','unassignedPersonaCount',
        'observedPopulationDigest','unassignedPopulationDigest','populationSubsetProofRef',
        'populationSubsetProofDigest','personaPartitionProofRef','personaPartitionProofDigest'
    )
    if ($ConfigurationCohort -isnot [pscustomobject]) { return $false }
    Test-RequiredProperties -Object $ConfigurationCohort -Names $fields -Context "$Context population commitment" -Errors $Errors
    $valid = [string]$ConfigurationCohort.cohortRef -ceq [string]$FleetPortfolio.populationCohortRef -and
        (Test-Sha256Token $ConfigurationCohort.observedPopulationDigest) -and
        (Test-Sha256Token $ConfigurationCohort.unassignedPopulationDigest) -and
        (Test-FleetPopulationCommitmentMetadata -Binding $ConfigurationCohort `
            -ExpectedPurpose 'CONFIGURATION_COHORT' `
            -ExpectedDomainDigest (Get-FleetConfigurationPopulationDomainDigest -FleetPortfolio $FleetPortfolio -ConfigurationCohort $ConfigurationCohort) `
            -ParentBinding $FleetPortfolio.coverage -Governance $Governance -Context $Context -Errors $Errors)
    $configurationDomainDigest = Get-FleetConfigurationPopulationDomainDigest -FleetPortfolio $FleetPortfolio -ConfigurationCohort $ConfigurationCohort
    foreach ($digestField in @('observedPopulationDigest','unassignedPopulationDigest')) {
        $valid = (Register-FleetPopulationCommitmentDigest -Digest $ConfigurationCohort.$digestField `
            -DomainDigest $configurationDomainDigest -Governance $Governance `
            -Context "$Context $digestField" -Errors $Errors) -and $valid
    }
    $valid = (Register-FleetPopulationProofBinding -Reference $ConfigurationCohort.personaPartitionProofRef `
        -Digest $ConfigurationCohort.personaPartitionProofDigest -Governance $Governance `
        -Context "$Context persona partition" -Errors $Errors) -and $valid
    if (-not $valid) {
        Add-BlueprintError -Errors $Errors -Code 'FLEET_PORTFOLIO_POPULATION_COMMITMENT_INVALID' -Message "$Context configuration subset, unassigned-set commitment, or persona partition proof binding is invalid."
    }
    return $valid
}

function Test-FleetPersonaPopulationCommitment {
    param(
        [Parameter(Mandatory = $true)]$FleetPortfolio,
        [Parameter(Mandatory = $true)]$ConfigurationCohort,
        [AllowNull()]$PersonaAllocation,
        [Parameter(Mandatory = $true)]$Governance,
        [Parameter(Mandatory = $true)][string]$Context,
        [Parameter(Mandatory = $true)][AllowEmptyCollection()][System.Collections.ArrayList]$Errors
    )

    if ($PersonaAllocation -isnot [pscustomobject]) { return $false }
    Test-RequiredProperties -Object $PersonaAllocation -Names @(
        'personaId','cohortRef','observedDeviceCount','observedPopulationDigest',
        'populationSubsetProofRef','populationSubsetProofDigest'
    ) -Context "$Context population commitment" -Errors $Errors
    $valid = [string]$PersonaAllocation.cohortRef -ceq [string]$ConfigurationCohort.cohortRef -and
        (Test-Sha256Token $PersonaAllocation.observedPopulationDigest) -and
        (Test-FleetPopulationCommitmentMetadata -Binding $PersonaAllocation `
            -ExpectedPurpose 'PERSONA_ALLOCATION' `
            -ExpectedDomainDigest (Get-FleetPersonaPopulationDomainDigest -FleetPortfolio $FleetPortfolio `
                -ConfigurationCohort $ConfigurationCohort -PersonaAllocation $PersonaAllocation) `
            -ParentBinding $FleetPortfolio.coverage -Governance $Governance -Context $Context -Errors $Errors)
    $personaDomainDigest = Get-FleetPersonaPopulationDomainDigest -FleetPortfolio $FleetPortfolio `
        -ConfigurationCohort $ConfigurationCohort -PersonaAllocation $PersonaAllocation
    $valid = (Register-FleetPopulationCommitmentDigest -Digest $PersonaAllocation.observedPopulationDigest `
        -DomainDigest $personaDomainDigest -Governance $Governance `
        -Context "$Context observedPopulationDigest" -Errors $Errors) -and $valid
    if (-not $valid) {
        Add-BlueprintError -Errors $Errors -Code 'FLEET_PORTFOLIO_POPULATION_COMMITMENT_INVALID' -Message "$Context persona subset commitment is invalid."
    }
    return $valid
}

function Test-FleetPortfolioCoverageValue {
    param(
        [AllowNull()]$Coverage,
        [Parameter(Mandatory = $true)][decimal]$MinimumCoveragePct,
        [Parameter(Mandatory = $true)][int64]$AggregationFloor,
        [Parameter(Mandatory = $true)][string]$Context,
        [Parameter(Mandatory = $true)][string]$ErrorCode,
        [Parameter(Mandatory = $true)][AllowEmptyCollection()][System.Collections.ArrayList]$Errors
    )

    $fields = @(
        'planned','eligible','observed','missing','excluded','percent',
        'plannedPopulationDigest','eligiblePopulationDigest','observedPopulationDigest',
        'missingPopulationDigest','excludedPopulationDigest','populationPartitionProofRef',
        'populationPartitionProofDigest','proofScheme','proofVersion','populationCommitmentKeyRef',
        'populationCommitmentKeyVersion','populationCanonicalization','populationCanonicalizationVersion',
        'populationCommitmentPurpose','populationCommitmentDomainDigest','status'
    )
    if ($Coverage -isnot [pscustomobject]) {
        Add-BlueprintError -Errors $Errors -Code $ErrorCode -Message "$Context requires governed fleet coverage."
        return $false
    }
    Test-RequiredProperties -Object $Coverage -Names $fields -Context "$Context coverage" -Errors $Errors
    Test-AllowedProperties -Object $Coverage -Names $fields -Context "$Context coverage" -Errors $Errors
    $integerFields = @('planned','eligible','observed','missing','excluded')
    $valid = @($integerFields | Where-Object {
        $Coverage.$_ -isnot [int] -and $Coverage.$_ -isnot [long]
    }).Count -eq 0 -and (Test-NumberValue $Coverage.percent)
    if ($valid) {
        $planned = [int64]$Coverage.planned
        $eligible = [int64]$Coverage.eligible
        $observed = [int64]$Coverage.observed
        $missing = [int64]$Coverage.missing
        $excluded = [int64]$Coverage.excluded
        $plannedExact = [System.Numerics.BigInteger]$planned
        $eligibleExact = [System.Numerics.BigInteger]$eligible
        $observedExact = [System.Numerics.BigInteger]$observed
        $missingExact = [System.Numerics.BigInteger]$missing
        $excludedExact = [System.Numerics.BigInteger]$excluded
        $calculatedPercent = if ($eligible -gt 0) { 100.0 * $observed / $eligible } else { -1.0 }
        $coverageFloorMet = $eligible -gt 0 -and
            (([decimal]$observed * [decimal]100) -ge ($MinimumCoveragePct * [decimal]$eligible))
        $valid = @(@($planned,$eligible,$observed,$missing,$excluded) | Where-Object { [int64]$_ -lt 0 }).Count -eq 0 -and
            $eligible -gt 0 -and $eligibleExact -eq ($plannedExact - $excludedExact) -and
            $eligibleExact -eq ($observedExact + $missingExact) -and $observedExact -le $eligibleExact -and
            [Math]::Abs([double]$Coverage.percent - $calculatedPercent) -le 0.01 -and
            [string]$Coverage.status -ceq 'PASS' -and $coverageFloorMet -and
            $observed -ge $AggregationFloor
    }
    if (-not $valid) {
        Add-BlueprintError -Errors $Errors -Code $ErrorCode -Message "$Context coverage must recompute eligible and percent, be nonempty PASS, meet the frozen Phase 0 percentage, and meet the privacy aggregation floor."
    }
    return $valid
}

function Get-FleetPortfolioGovernanceBinding {
    param(
        [Parameter(Mandatory = $true)]$FleetPortfolio,
        [Parameter(Mandatory = $true)]$Chain,
        [Parameter(Mandatory = $true)]$RecordMap,
        [ValidateSet('TEST','PRODUCTION')][string]$ValidationProfile,
        [Parameter(Mandatory = $true)][AllowEmptyCollection()][System.Collections.ArrayList]$Errors
    )

    $ValidationProfile = ([string]$ValidationProfile).ToUpperInvariant()
    $fields = @(
        'privacyPolicyDigest','privacyReleaseDigest','privacyAggregationFloorPointer',
        'privacyAggregationFloorDigest','minimumCoveragePointer','minimumCoverageValueDigest','minimumCoveragePct'
    )
    Test-RequiredProperties -Object $FleetPortfolio -Names $fields -Context 'fleet portfolio privacy and coverage governance' -Errors $Errors
    $phase0Plan = Resolve-CanonicalRecord -RecordMap $RecordMap -Reference $Chain.candidateComparison.testPlanRef `
        -ExpectedTypes @('test-plan') -Context 'fleet portfolio Phase 0 test plan' -Errors $Errors
    $thresholdPolicy = if ($null -ne $phase0Plan) {
        Resolve-CanonicalRecord -RecordMap $RecordMap -Reference $phase0Plan.thresholdPolicyRef `
            -ExpectedTypes @('threshold-policy') -Context 'fleet portfolio Phase 0 threshold policy' -Errors $Errors
    }
    else { $null }
    $minimumFound = $false
    $minimumValue = if ($null -ne $thresholdPolicy) {
        Get-JsonPointerValue -Document $thresholdPolicy.payload -Pointer ([string]$FleetPortfolio.minimumCoveragePointer) -Found ([ref]$minimumFound)
    }
    else { $null }
    [decimal]$minimumDecimal = [decimal]101
    $minimumValid = $minimumFound -and (Test-NumberValue $minimumValue)
    if ($minimumValid) {
        try {
            $minimumDecimal = [decimal]$minimumValue
            $minimumValid = $minimumDecimal -ge [decimal]0 -and $minimumDecimal -le [decimal]100
        }
        catch { $minimumValid = $false }
    }
    $minimumValueDigest = if ($minimumFound) { Get-CanonicalPayloadDigest -Payload $minimumValue } else { '' }
    $aggregationFloorValid = ($FleetPortfolio.aggregationFloor -is [int] -or $FleetPortfolio.aggregationFloor -is [long]) -and
        [int64]$FleetPortfolio.aggregationFloor -gt 0
    if ([string]$FleetPortfolio.privacyPolicyRef -cnotmatch '^private://' -or
        [string]$FleetPortfolio.privacyReleaseRef -cnotmatch '^private://' -or
        -not (Test-Sha256Token $FleetPortfolio.privacyPolicyDigest) -or
        -not (Test-Sha256Token $FleetPortfolio.privacyReleaseDigest) -or
        [string]$FleetPortfolio.privacyAggregationFloorPointer -cne '/aggregationFloor' -or
        -not $aggregationFloorValid -or
        [string]$FleetPortfolio.privacyAggregationFloorDigest -cne [string](Get-CanonicalPayloadDigest -Payload $FleetPortfolio.aggregationFloor) -or
        $null -eq $phase0Plan -or $null -eq $thresholdPolicy -or
        [string]$thresholdPolicy.recordId -cne [string]$phase0Plan.thresholdPolicyRef -or
        [string]$FleetPortfolio.freshnessBinding.policyRef -cne [string]$thresholdPolicy.recordId -or
        [string]$FleetPortfolio.freshnessBinding.policyDigest -cne [string]$thresholdPolicy.contentDigest -or
        [string]$FleetPortfolio.minimumCoveragePointer -cne '/thresholds/minTelemetryCoveragePct/value' -or
        -not (Test-CanonicalRecordPointerCoverage -Record $thresholdPolicy -Pointer ([string]$FleetPortfolio.minimumCoveragePointer)) -or
        -not $minimumFound -or -not $minimumValid -or
        [string]$FleetPortfolio.minimumCoverageValueDigest -cne [string]$minimumValueDigest -or
        -not (Test-NumberValue $FleetPortfolio.minimumCoveragePct) -or
        [string](Get-CanonicalPayloadDigest -Payload $FleetPortfolio.minimumCoveragePct) -cne [string]$minimumValueDigest -or
        [decimal]$FleetPortfolio.minimumCoveragePct -ne $minimumDecimal) {
        Add-BlueprintError -Errors $Errors -Code 'FLEET_PORTFOLIO_GOVERNANCE_BINDING_INVALID' -Message 'Fleet portfolio privacy commitments, aggregation-floor scalar, and Phase 0 minimum-coverage pointer/value/digest are not exact.'
    }
    if ([string]$ValidationProfile -ceq 'PRODUCTION') {
        Add-BlueprintError -Errors $Errors -Code 'FLEET_PORTFOLIO_PRIVATE_PRIVACY_BINDING_UNVERIFIED' -Message 'The public validator cannot verify protected privacy-policy, release, population-set, subset, partition, issuer, freshness, authorization, or revocation proof bytes; production remains HOLD until the authenticated private resolver supplies that proof.'
    }
    return [pscustomobject]@{
        Phase0TestPlan = $phase0Plan
        ThresholdPolicy = $thresholdPolicy
        MinimumCoveragePct = if ($minimumValid) { $minimumDecimal } else { [decimal]101 }
        AggregationFloor = if ($aggregationFloorValid) { [int64]$FleetPortfolio.aggregationFloor } else { [int64]::MaxValue }
        PopulationProofRefs = [System.Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal)
        PopulationProofDigests = [System.Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal)
        PopulationCommitmentDomainsByDigest = [System.Collections.Generic.Dictionary[string,string]]::new([StringComparer]::Ordinal)
    }
}

function Test-FleetPortfolioDimensionSemantics {
    param(
        [Parameter(Mandatory = $true)]$FleetPortfolio,
        [Parameter(Mandatory = $true)]$Chain,
        [Parameter(Mandatory = $true)]$RecordMap,
        [Parameter(Mandatory = $true)]$Governance,
        [Parameter(Mandatory = $true)][DateTimeOffset]$EvaluationTime,
        [Parameter(Mandatory = $true)][DateTimeOffset]$LineageGeneratedAt,
        [Parameter(Mandatory = $true)][AllowEmptyCollection()][System.Collections.ArrayList]$Errors
    )

    $coverage = $FleetPortfolio.dimensionCoverage
    if ($coverage -isnot [pscustomobject]) {
        Add-BlueprintError -Errors $Errors -Code 'FLEET_PORTFOLIO_DIMENSION_SET_INCOMPLETE' -Message 'Fleet portfolio issuance requires the frozen twelve-dimension typed evidence policy.'
        return
    }
    $dimensionProperties = [ordered]@{
        CONFIGURATION_PERSONA_POPULATION = 'configurationPersonaPopulation'
        PLATFORM_SUPPORT_BASELINE = 'platformSupportBaseline'
        CAPACITY_HEADROOM = 'capacityHeadroom'
        WORKLOAD_RESOURCE_PRESSURE = 'workloadResourcePressure'
        APPLICATION_STATE = 'applicationState'
        BATTERY_STANDBY = 'batteryStandby'
        DOCK_RELIABILITY = 'dockReliability'
        PROVISIONING_UPDATE_COMPLIANCE_MANAGEMENT = 'provisioningUpdateComplianceManagement'
        INCIDENT_REPAIR_SUPPORT = 'incidentRepairSupport'
        REGION_WORK_PATTERN_REPRESENTATION = 'regionWorkPatternRepresentation'
        PROVENANCE_INTEGRITY = 'provenanceIntegrity'
        LIMITATIONS_OUTLIERS_FRESHNESS_REQUALIFICATION = 'limitationsOutliersFreshnessRequalification'
    }
    $coverageFields = @(
        'dimensionPolicyId','dimensionPolicyVersion','dimensionPolicyRef','dimensionPolicyDigest',
        'policyExecutionRef','policyExecutionDigest','policyExecutionToolRef','policyExecutionToolVersion',
        'policyExecutedAt','bindingsDigest'
    ) + @($dimensionProperties.Values)
    Test-RequiredProperties -Object $coverage -Names $coverageFields -Context 'fleet portfolio typed dimension coverage' -Errors $Errors
    Test-AllowedProperties -Object $coverage -Names $coverageFields -Context 'fleet portfolio typed dimension coverage' -Errors $Errors

    $policyRows = @($Chain.currentFleetRequiredDimensions)
    $policyById = [System.Collections.Generic.Dictionary[string,object]]::new([StringComparer]::Ordinal)
    $policyValid = $policyRows.Count -eq $dimensionProperties.Count
    foreach ($row in $policyRows) {
        if ($row -isnot [pscustomobject] -or -not (Test-NonBlankString $row.dimensionId) -or
            -not $dimensionProperties.Contains([string]$row.dimensionId) -or
            $row.requiredClaimMetricTypes -isnot [System.Collections.IList] -or
            @($row.requiredClaimMetricTypes).Count -eq 0 -or
            @($row.requiredClaimMetricTypes | Where-Object { -not (Test-NonBlankString $_) }).Count -gt 0 -or
            @($row.requiredClaimMetricTypes | Group-Object -CaseSensitive | Where-Object Count -gt 1).Count -gt 0 -or
            $policyById.ContainsKey([string]$row.dimensionId)) {
            $policyValid = $false
            continue
        }
        $policyById.Add([string]$row.dimensionId, $row)
    }
    foreach ($dimensionId in @($dimensionProperties.Keys)) {
        if (-not $policyById.ContainsKey([string]$dimensionId)) { $policyValid = $false }
    }
    $expectedPolicyRef = 'leadership-claim-chain-v1.0.0#/currentFleetRequiredDimensions'
    $expectedPolicyDigest = Get-CanonicalPayloadDigest -Payload ([object[]]$policyRows)
    if (-not $policyValid -or
        [string]$coverage.dimensionPolicyId -cne 'CURRENT_FLEET_LEADERSHIP_DIMENSIONS_V1' -or
        [string]$coverage.dimensionPolicyVersion -cne [string]$Chain.chainVersion -or
        [string]$coverage.dimensionPolicyVersion -cne '1.0.0' -or
        [string]$coverage.dimensionPolicyRef -cne $expectedPolicyRef -or
        [string]$coverage.dimensionPolicyDigest -cne [string]$expectedPolicyDigest) {
        Add-BlueprintError -Errors $Errors -Code 'FLEET_PORTFOLIO_DIMENSION_POLICY_MISMATCH' -Message 'Fleet dimension policy does not equal the frozen leadership policy reference, version, ordered dimensions, and exact claim-type sets.'
    }

    [DateTimeOffset]$policyExecutedAt = [DateTimeOffset]::MinValue
    $policyTimeValid = [OperationsBlueprint.StrictRfc3339]::TryParse([string]$coverage.policyExecutedAt, [ref]$policyExecutedAt) -and
        $policyExecutedAt -le $LineageGeneratedAt -and $policyExecutedAt -le $EvaluationTime
    if ([string]$coverage.policyExecutionRef -cnotmatch '^private://' -or
        [string]$coverage.policyExecutionToolRef -cne 'policy-as-code' -or
        -not (Test-NonBlankString $coverage.policyExecutionToolVersion) -or -not $policyTimeValid) {
        Add-BlueprintError -Errors $Errors -Code 'FLEET_PORTFOLIO_POLICY_EXECUTION_INVALID' -Message 'Fleet dimension policy requires a retained, non-future, versioned policy-as-code execution artifact.'
    }

    $phase0Plan = $Governance.Phase0TestPlan
    [decimal]$minimumCoveragePct = [decimal]$Governance.MinimumCoveragePct
    [int64]$aggregationFloor = [int64]$Governance.AggregationFloor
    $queryPack = Resolve-CanonicalRecord -RecordMap $RecordMap -Reference $FleetPortfolio.queryPackRef -ExpectedTypes @('query-pack-record') -Context 'fleet dimension query pack' -Errors $Errors
    Test-FleetClaimFreshnessBinding -Freshness $FleetPortfolio.freshnessBinding `
        -ObservationWindow ([string]$FleetPortfolio.observationWindow) -PolicyExecutedAt $policyExecutedAt `
        -EvaluationTime $EvaluationTime -RecordMap $RecordMap `
        -ExpectedPolicyRef ([string]$phase0Plan.thresholdPolicyRef) `
        -ExpectedDependencySnapshotRef ([string]$Chain.currentFleetIssue.freshness.dependencySnapshotRef) `
        -ExpectedDependencySnapshotDigest ([string]$Chain.currentFleetIssue.freshness.dependencySnapshotDigest) `
        -Context 'fleet portfolio' -Errors $Errors
    $dimensionDigestBindings = New-Object System.Collections.ArrayList
    $claimIds = [System.Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal)
    $distributionTypes = @(
        'PHYSICAL_CAPACITY_CORPORATE_FLOOR_RESERVE_HEADROOM','RESOURCE_PRESSURE','WORKLOAD_TIMING',
        'BATTERY_RUNTIME','STANDBY_DRAIN','DOCK_ATTACH_DETACH_SLEEP_RESUME_RELIABILITY',
        'INCIDENT_PREVALENCE','REPAIR_PREVALENCE','SUPPORT_CONTACT_PREVALENCE','SUPPORT_EFFORT'
    )
    $denominatedTypes = @(
        'PERSONA_COHORT_POPULATION','APPLICATION_FAILURE_COMPATIBILITY','PROVISIONING_STATE',
        'UPDATE_STATE','COMPLIANCE_STATE','MANAGEMENT_STATE','REGION_REPRESENTATION','WORK_PATTERN_REPRESENTATION'
    )
    $structuredTypes = @(
        'QUALIFIED_CONFIGURATION_ENVELOPE','DEVICE_AGE_WARRANTY_SUPPORT',
        'WINDOWS_BIOS_DRIVER_FIRMWARE_SECURITY_BASELINE','SOURCE_PROVENANCE','ARTIFACT_INTEGRITY',
        'PRIVACY_SAFE_JOIN','OUTLIER_EXCLUSION_LIMITATION','FRESHNESS_STATUS','REQUALIFICATION_TRIGGER'
    )
    $sourceTypes = @('evidence-record')

    foreach ($dimensionId in @($dimensionProperties.Keys)) {
        $propertyName = [string]$dimensionProperties[$dimensionId]
        $dimensionProperty = $coverage.PSObject.Properties[$propertyName]
        if ($null -eq $dimensionProperty -or $dimensionProperty.Value -isnot [pscustomobject]) {
            Add-BlueprintError -Errors $Errors -Code 'FLEET_PORTFOLIO_DIMENSION_SET_INCOMPLETE' -Message 'Fleet portfolio omits a required typed decision dimension.'
            continue
        }
        $dimension = $dimensionProperty.Value
        Test-RequiredProperties -Object $dimension -Names @('dimensionId','status','claimBindings','dimensionEvidenceDigest') -Context "fleet dimension $dimensionId" -Errors $Errors
        Test-AllowedProperties -Object $dimension -Names @('dimensionId','status','claimBindings','dimensionEvidenceDigest') -Context "fleet dimension $dimensionId" -Errors $Errors
        $requiredTypes = @(if ($policyById.ContainsKey([string]$dimensionId)) { @($policyById[[string]$dimensionId].requiredClaimMetricTypes) })
        $claims = @($dimension.claimBindings)
        if ([string]$dimension.dimensionId -cne [string]$dimensionId -or
            [string]$dimension.status -cne 'PASS' -or $claims.Count -ne $requiredTypes.Count) {
            Add-BlueprintError -Errors $Errors -Code 'FLEET_PORTFOLIO_DIMENSION_SET_INCOMPLETE' -Message 'Fleet dimension identity, PASS state, or exact policy claim count is invalid.'
        }

        for ($claimIndex = 0; $claimIndex -lt $claims.Count; $claimIndex++) {
            $claim = $claims[$claimIndex]
            $expectedClaimType = if ($claimIndex -lt $requiredTypes.Count) { [string]$requiredTypes[$claimIndex] } else { '' }
            $claimFields = @(
                'claimBindingId','claimMetricType','evidenceShape','metricId','unit','statisticDirection',
                'evidenceReleaseBindings','sourceRecordBindings','sourcePointers','coverage','missingnessReasonCodes',
                'exclusionRefs','baselineFingerprint','observationWindow','provenanceTier','corroborationRefs',
                'sourceToolRef','sourceToolVersion','queryPackRef','queryPackDigest','queryPackVersion',
                'artifactHashes','freshnessBinding','limitations','requalificationTriggerRefs'
            )
            $allowEmptyClaimArrays = @('missingnessReasonCodes','exclusionRefs','corroborationRefs','limitations','requalificationTriggerRefs')
            Test-RequiredProperties -Object $claim -Names @($claimFields | Where-Object { $allowEmptyClaimArrays -cnotcontains [string]$_ }) -Context "fleet dimension $dimensionId claim" -Errors $Errors
            foreach ($arrayField in $allowEmptyClaimArrays) {
                $arrayProperty = $claim.PSObject.Properties[$arrayField]
                if ($null -eq $arrayProperty -or $arrayProperty.Value -isnot [System.Collections.IList]) {
                    Add-BlueprintError -Errors $Errors -Code 'MISSING_REQUIRED_FIELD' -Message "fleet dimension $dimensionId claim requires an $arrayField array, which may be empty only when its governed condition is absent."
                }
            }
            Test-AllowedProperties -Object $claim -Names @($claimFields + @(
                'distributionRef','distributionDigest','denominator','structuredSummaryRef','structuredSummaryDigest',
                'resultPointer','resultDigest','numeratorValue','rateValue','rateScale','resultValueType'
            )) -Context "fleet dimension $dimensionId claim" -Errors $Errors
            if ([string]$claim.claimBindingId -cnotmatch '^[A-Za-z0-9][A-Za-z0-9._:-]{0,255}$' -or
                -not $claimIds.Add([string]$claim.claimBindingId) -or
                [string]$claim.claimMetricType -cne $expectedClaimType -or
                -not (Test-NonBlankString $claim.metricId) -or -not (Test-NonBlankString $claim.unit) -or
                [string]$claim.statisticDirection -cnotin @('HIGHER_IS_BETTER','LOWER_IS_BETTER','TARGET_RANGE','DESCRIPTIVE_ONLY')) {
                Add-BlueprintError -Errors $Errors -Code 'FLEET_PORTFOLIO_CLAIM_POLICY_MISMATCH' -Message 'Fleet claim identity, metric type, metric label, unit, direction, or global ordinal uniqueness differs from the frozen dimension policy.'
            }

            $expectedShape = if ($distributionTypes -ccontains $expectedClaimType) { 'DISTRIBUTION' }
                elseif ($denominatedTypes -ccontains $expectedClaimType) { 'DENOMINATED_COUNT' }
                elseif ($structuredTypes -ccontains $expectedClaimType) { 'STRUCTURED_STATE' }
                else { '' }
            if ([string]$claim.evidenceShape -cne $expectedShape) {
                Add-BlueprintError -Errors $Errors -Code 'FLEET_PORTFOLIO_CLAIM_SHAPE_MISMATCH' -Message 'Fleet claim evidence shape does not match its frozen claim metric type.'
            }

            $releaseRecords = New-Object System.Collections.ArrayList
            $releaseBindings = @($claim.evidenceReleaseBindings)
            if ($releaseBindings.Count -eq 0 -or
                @($releaseBindings | Group-Object { ([string]$_.recordRef) + '::' + ([string]$_.contentDigest) } -CaseSensitive | Where-Object Count -gt 1).Count -gt 0 -or
                @($releaseBindings | Group-Object -Property recordRef -CaseSensitive | Where-Object Count -gt 1).Count -gt 0) {
                Add-BlueprintError -Errors $Errors -Code 'FLEET_PORTFOLIO_CLAIM_RELEASE_INVALID' -Message 'Every fleet claim requires a nonempty ordinal-unique evidence-release set.'
            }
            foreach ($releaseBinding in $releaseBindings) {
                Test-RequiredProperties -Object $releaseBinding -Names @('recordRef','contentDigest') -Context "fleet claim $expectedClaimType release binding" -Errors $Errors
                $releaseRef = [string]$releaseBinding.recordRef
                $release = Resolve-CanonicalRecord -RecordMap $RecordMap -Reference $releaseRef -ExpectedTypes @('evidence-release') -Context "fleet claim $expectedClaimType release" -Errors $Errors
                if ($null -ne $release -and [string]$release.contentDigest -ceq [string]$releaseBinding.contentDigest) {
                    [void]$releaseRecords.Add($release)
                    Test-EvidenceReleaseBinding -ReleaseRecord $release -EvidenceRecords @() -RecordMap $RecordMap `
                        -EvaluationTime $EvaluationTime -ConsumerRecord $FleetPortfolio `
                        -Context "fleet claim $expectedClaimType" -Errors $Errors
                    [DateTimeOffset]$releaseAt = [DateTimeOffset]::MinValue
                    [DateTimeOffset]$releaseWindowEnd = [DateTimeOffset]::MinValue
                    $releaseWindowValid = [string]$FleetPortfolio.observationWindow -cmatch '^\d{4}-\d{2}-\d{2}/(\d{4}-\d{2}-\d{2})$' -and
                        [OperationsBlueprint.StrictIsoDate]::TryParse([string]$Matches[1], [ref]$releaseWindowEnd)
                    if (-not [OperationsBlueprint.StrictRfc3339]::TryParse([string]$release.releasedAt, [ref]$releaseAt) -or
                        -not $releaseWindowValid -or $releaseAt -lt $releaseWindowEnd -or $releaseAt -gt $policyExecutedAt) {
                        Add-BlueprintError -Errors $Errors -Code 'FLEET_PORTFOLIO_CLAIM_RELEASE_INVALID' -Message 'Fleet claim evidence release must be issued after its observation window and before the retained policy execution.'
                    }
                    Test-FleetSourceFreshnessBinding -SourceFreshness $release.freshnessBinding -GovernedFreshness $claim.freshnessBinding `
                        -ObservationWindow ([string]$FleetPortfolio.observationWindow) -PolicyExecutedAt $policyExecutedAt `
                        -EvaluationTime $EvaluationTime -Context "fleet claim $expectedClaimType release" -Errors $Errors
                }
                else {
                    Add-BlueprintError -Errors $Errors -Code 'FLEET_PORTFOLIO_CLAIM_RELEASE_INVALID' -Message 'Fleet claim evidence-release digest does not match the current canonical release envelope.'
                }
                if (@($FleetPortfolio.sourceEvidenceReleaseBindings | Where-Object {
                    [string]$_.recordRef -ceq $releaseRef -and [string]$_.contentDigest -ceq [string]$releaseBinding.contentDigest
                }).Count -ne 1) {
                    Add-BlueprintError -Errors $Errors -Code 'FLEET_PORTFOLIO_CLAIM_RELEASE_INVALID' -Message 'Fleet claim release is not in the portfolio source-release set.'
                }
            }

            $sourceMap = [System.Collections.Generic.Dictionary[string,object]]::new([StringComparer]::Ordinal)
            foreach ($binding in @($claim.sourceRecordBindings)) {
                Test-RequiredProperties -Object $binding -Names @('recordRef','contentDigest') -Context "fleet claim $expectedClaimType source binding" -Errors $Errors
                $source = Resolve-CanonicalRecord -RecordMap $RecordMap -Reference $binding.recordRef -ExpectedTypes $sourceTypes -Context "fleet claim $expectedClaimType source" -Errors $Errors
                if ($null -eq $source -or [string]$source.contentDigest -cne [string]$binding.contentDigest -or $sourceMap.ContainsKey([string]$binding.recordRef)) {
                    Add-BlueprintError -Errors $Errors -Code 'FLEET_PORTFOLIO_CLAIM_SOURCE_BINDING_INVALID' -Message 'Fleet claim source reference, digest, or ordinal uniqueness is invalid.'
                }
                else { $sourceMap.Add([string]$binding.recordRef, $source) }
            }
            if ($sourceMap.Count -eq 0) {
                Add-BlueprintError -Errors $Errors -Code 'FLEET_PORTFOLIO_CLAIM_SOURCE_BINDING_INVALID' -Message 'Fleet claim requires at least one canonical source record and digest.'
            }
            foreach ($pointer in @($claim.sourcePointers)) {
                Test-RequiredProperties -Object $pointer -Names @('recordRef','contentDigest','jsonPointer') -Context "fleet claim $expectedClaimType source pointer" -Errors $Errors
                $pointerSource = if ($sourceMap.ContainsKey([string]$pointer.recordRef)) { $sourceMap[[string]$pointer.recordRef] } else { $null }
                if ($null -eq $pointerSource -or [string]$pointer.contentDigest -cne [string]$pointerSource.contentDigest -or
                    -not (Test-CanonicalRecordPointerCoverage -Record $pointerSource -Pointer ([string]$pointer.jsonPointer))) {
                    Add-BlueprintError -Errors $Errors -Code 'FLEET_PORTFOLIO_CLAIM_POINTER_INVALID' -Message 'Fleet claim source pointer does not resolve through the exact bound record digest and pointer inventory.'
                }
            }
            foreach ($sourceRef in @($sourceMap.Keys)) {
                if (@($claim.sourcePointers | Where-Object { [string]$_.recordRef -ceq [string]$sourceRef }).Count -eq 0 -or
                    @($releaseRecords | Where-Object { @($_.memberRecordIds) -ccontains ([string]$sourceRef).Split('#',2)[0] }).Count -eq 0) {
                    Add-BlueprintError -Errors $Errors -Code 'FLEET_PORTFOLIO_CLAIM_SOURCE_UNRELEASED' -Message 'Every fleet claim source must have an exact pointer and belong to a declared immutable evidence release.'
                }
            }

            $claimCoverageValid = Test-FleetPortfolioCoverageValue -Coverage $claim.coverage `
                -MinimumCoveragePct $minimumCoveragePct -AggregationFloor $aggregationFloor `
                -Context "fleet claim $expectedClaimType" -ErrorCode 'FLEET_PORTFOLIO_CLAIM_COVERAGE_INVALID' -Errors $Errors
            [void](Test-FleetCoveragePopulationCommitment -Coverage $claim.coverage `
                -ExpectedPurpose 'CLAIM_COVERAGE' `
                -ExpectedDomainDigest (Get-FleetClaimCoverageDomainDigest -FleetPortfolio $FleetPortfolio -Claim $claim) `
                -ParentCoverage $FleetPortfolio.coverage -Governance $Governance `
                -Context "fleet claim $expectedClaimType" -Errors $Errors)
            $portfolioCoverageComparable = $FleetPortfolio.coverage -is [pscustomobject] -and
                @(@('planned','eligible','observed','excluded') | Where-Object {
                    $FleetPortfolio.coverage.$_ -isnot [int] -and $FleetPortfolio.coverage.$_ -isnot [long]
                }).Count -eq 0
            if ($claimCoverageValid -and (-not $portfolioCoverageComparable -or
                [int64]$claim.coverage.planned -ne [int64]$FleetPortfolio.coverage.planned -or
                [int64]$claim.coverage.eligible -gt [int64]$FleetPortfolio.coverage.eligible -or
                [int64]$claim.coverage.observed -gt [int64]$FleetPortfolio.coverage.observed -or
                [int64]$claim.coverage.excluded -lt [int64]$FleetPortfolio.coverage.excluded)) {
                $claimCoverageValid = $false
                Add-BlueprintError -Errors $Errors -Code 'FLEET_PORTFOLIO_CLAIM_COVERAGE_INVALID' -Message 'Fleet claim coverage must retain the exact planned cohort; its eligible/observed counts cannot exceed the portfolio and its exclusion count cannot be below the portfolio base count. Metric-specific missingness and exclusions remain explicit.'
            }
            if (-not $claimCoverageValid -or
                ([int64]$claim.coverage.missing -gt 0 -and @($claim.missingnessReasonCodes).Count -eq 0) -or
                ([int64]$claim.coverage.missing -eq 0 -and @($claim.missingnessReasonCodes).Count -ne 0) -or
                ([int64]$claim.coverage.excluded -gt 0 -and @($claim.exclusionRefs).Count -eq 0) -or
                ([int64]$claim.coverage.excluded -eq 0 -and @($claim.exclusionRefs).Count -ne 0)) {
                Add-BlueprintError -Errors $Errors -Code 'FLEET_PORTFOLIO_CLAIM_COVERAGE_INVALID' -Message 'Fleet claim coverage, missingness, and exclusions must reconcile exactly to the governed portfolio cohort.'
            }
            if ([string]$claim.baselineFingerprint -cne [string]$Chain.currentFleetIssue.baselineFingerprint -or
                [string]$claim.observationWindow -cne [string]$FleetPortfolio.observationWindow -or
                -not (Test-ObservationWindow -Value $claim.observationWindow -EvaluationTime $EvaluationTime)) {
                Add-BlueprintError -Errors $Errors -Code 'FLEET_PORTFOLIO_CLAIM_BASELINE_WINDOW_MISMATCH' -Message 'Fleet claim must bind the current-fleet baseline fingerprint and exact closed portfolio observation window.'
            }
            if ($null -eq $queryPack -or [string]$claim.queryPackRef -cne [string]$FleetPortfolio.queryPackRef -or
                [string]$claim.queryPackDigest -cne [string]$FleetPortfolio.queryPackDigest -or
                [string]$claim.queryPackDigest -cne [string]$queryPack.contentDigest -or
                [string]$claim.queryPackVersion -cne [string]$queryPack.version -or
                @($queryPack.sourceToolRefs) -cnotcontains [string]$claim.sourceToolRef -or
                @($queryPack.metricIds) -cnotcontains [string]$claim.metricId -or
                -not (Test-NonBlankString $claim.sourceToolVersion)) {
                Add-BlueprintError -Errors $Errors -Code 'FLEET_PORTFOLIO_CLAIM_QUERY_PROVENANCE_INVALID' -Message 'Fleet claim tool, metric, query-pack version, and exact query-pack digest are not reconciled.'
            }

            $sourceEvidence = @($sourceMap.Values | Where-Object { [string]$_.recordType -ceq 'evidence-record' })
            if ([string]$claim.provenanceTier -cnotin @('T0','T1','T2') -or
                @($sourceEvidence | Where-Object { [string]$_.provenance -ceq [string]$claim.provenanceTier }).Count -eq 0 -or
                @($sourceEvidence | Where-Object { [string]$_.tool.name -ceq [string]$claim.sourceToolRef -and [string]$_.tool.version -ceq [string]$claim.sourceToolVersion }).Count -eq 0) {
                Add-BlueprintError -Errors $Errors -Code 'FLEET_PORTFOLIO_CLAIM_PROVENANCE_INVALID' -Message 'Fleet claim provenance tier and tool/version are not proven by a bound source evidence record.'
            }
            foreach ($sourceEvidenceRecord in $sourceEvidence) {
                Test-FleetSourceFreshnessBinding -SourceFreshness $sourceEvidenceRecord.freshnessBinding `
                    -GovernedFreshness $claim.freshnessBinding -ObservationWindow ([string]$claim.observationWindow) `
                    -PolicyExecutedAt $policyExecutedAt -EvaluationTime $EvaluationTime `
                    -Context "fleet claim $expectedClaimType source evidence" -Errors $Errors
            }
            foreach ($artifactHash in @($claim.artifactHashes)) {
                if (-not (Test-Sha256Token $artifactHash) -or
                    @($sourceEvidence | ForEach-Object { @($_.artifacts) } | Where-Object { [string]$_.sha256 -ceq [string]$artifactHash }).Count -eq 0) {
                    Add-BlueprintError -Errors $Errors -Code 'FLEET_PORTFOLIO_CLAIM_ARTIFACT_INVALID' -Message 'Fleet claim artifact hash is not retained by its exact released source evidence.'
                }
            }
            if ([string]$claim.provenanceTier -ceq 'T2') {
                if (@($claim.corroborationRefs).Count -eq 0) {
                    Add-BlueprintError -Errors $Errors -Code 'FLEET_PORTFOLIO_T2_CORROBORATION_INVALID' -Message 'T2 fleet claims require current released T0/T1 corroboration.'
                }
                foreach ($corroborationRef in @($claim.corroborationRefs)) {
                    $corroboration = Resolve-CanonicalRecord -RecordMap $RecordMap -Reference $corroborationRef -ExpectedTypes @('evidence-record') -Context 'fleet claim T2 corroboration' -Errors $Errors
                    if ($null -eq $corroboration -or [string]$corroboration.provenance -cnotin @('T0','T1') -or
                        @($releaseRecords | Where-Object { @($_.memberRecordIds) -ccontains ([string]$corroborationRef).Split('#',2)[0] }).Count -eq 0) {
                        Add-BlueprintError -Errors $Errors -Code 'FLEET_PORTFOLIO_T2_CORROBORATION_INVALID' -Message 'T2 fleet claim corroboration must resolve to released T0/T1 evidence.'
                    }
                }
            }
            elseif (@($claim.corroborationRefs).Count -ne 0) {
                Add-BlueprintError -Errors $Errors -Code 'FLEET_PORTFOLIO_T2_CORROBORATION_INVALID' -Message 'Non-T2 fleet claims may not carry ambiguous corroboration references.'
            }

            Test-FleetClaimFreshnessBinding -Freshness $claim.freshnessBinding -ObservationWindow ([string]$claim.observationWindow) `
                -PolicyExecutedAt $policyExecutedAt -EvaluationTime $EvaluationTime -RecordMap $RecordMap `
                -ExpectedPolicyRef ([string]$phase0Plan.thresholdPolicyRef) `
                -ExpectedDependencySnapshotRef ([string]$Chain.currentFleetIssue.freshness.dependencySnapshotRef) `
                -ExpectedDependencySnapshotDigest ([string]$Chain.currentFleetIssue.freshness.dependencySnapshotDigest) `
                -Context "fleet claim $expectedClaimType" -Errors $Errors
            if ($claim.freshnessBinding -isnot [pscustomobject] -or $FleetPortfolio.freshnessBinding -isnot [pscustomobject] -or
                (ConvertTo-DeterministicJsonText -Value (ConvertTo-CanonicalJsonValue $claim.freshnessBinding)) -cne
                    (ConvertTo-DeterministicJsonText -Value (ConvertTo-CanonicalJsonValue $FleetPortfolio.freshnessBinding))) {
                Add-BlueprintError -Errors $Errors -Code 'FLEET_PORTFOLIO_CLAIM_FRESHNESS_INVALID' -Message 'Fleet claim freshness must equal the exact portfolio policy, platform dependency, age, observation, and admission binding.'
            }
            if (@($claim.limitations | Where-Object { -not (Test-NonBlankString $_) }).Count -gt 0) {
                Add-BlueprintError -Errors $Errors -Code 'FLEET_PORTFOLIO_CLAIM_LIMITATION_INVALID' -Message 'Fleet claim limitations must be explicit nonblank statements or an honest empty set.'
            }
            foreach ($triggerRef in @($claim.requalificationTriggerRefs)) {
                [void](Resolve-CanonicalRecord -RecordMap $RecordMap -Reference $triggerRef -ExpectedTypes @('requalification-plan-record') -Context 'fleet claim requalification trigger' -Errors $Errors)
            }
            if ($expectedClaimType -ceq 'REQUALIFICATION_TRIGGER' -and @($claim.requalificationTriggerRefs).Count -eq 0) {
                Add-BlueprintError -Errors $Errors -Code 'FLEET_PORTFOLIO_REQUALIFICATION_TRIGGER_MISSING' -Message 'The requalification dimension must bind at least one current canonical requalification plan.'
            }

            if ($expectedShape -ceq 'DISTRIBUTION') {
                $distribution = Resolve-CanonicalRecord -RecordMap $RecordMap -Reference $claim.distributionRef -ExpectedTypes @('distribution-record') -Context "fleet claim $expectedClaimType distribution" -Errors $Errors
                $distributionClosure = if ($null -ne $distribution) {
                    Test-DistributionSourceEvidenceClosure -Distribution $distribution -RecordMap $RecordMap `
                        -EvaluationTime $EvaluationTime -ExpectedEvidenceRecord $null `
                        -Context "fleet claim $expectedClaimType distribution" -Errors $Errors
                }
                else { $null }
                $distributionSource = if ($null -ne $distributionClosure) { $distributionClosure.SourceEvidence } else { $null }
                if ($null -ne $distribution) {
                    [void](Test-DistributionPhase0FloorBinding -Distribution $distribution -Phase0TestPlan $phase0Plan `
                        -ExpectedEvidenceRecord $distributionSource -ExpectedTestPlanRef ([string]$Chain.candidateComparison.testPlanRef) `
                        -Context "fleet claim $expectedClaimType distribution" -Errors $Errors)
                    Test-DistributionPerUnitRunProof -Distribution $distribution -Context "fleet claim $expectedClaimType distribution" -Errors $Errors
                }
                $eligibleCount = if ($claimCoverageValid) { [int64]$claim.coverage.eligible } else { -1 }
                if ($null -eq $distribution -or [string]$distribution.contentDigest -cne [string]$claim.distributionDigest -or
                    [string]$distribution.metricId -cne [string]$claim.metricId -or [string]$distribution.unit -cne [string]$claim.unit -or
                    [string]$distribution.statisticDirection -cne [string]$claim.statisticDirection -or
                    [string]$distribution.samplingFloorStatus -cne 'PASS' -or [string]$distribution.distributionStatus -cne 'PASS' -or
                    ($distribution.unitCount -isnot [int] -and $distribution.unitCount -isnot [long]) -or
                    ($distribution.runCount -isnot [int] -and $distribution.runCount -isnot [long]) -or
                    [int64]$distribution.unitCount -lt [int64]$distribution.requiredUnits -or
                    [int64]$distribution.unitCount -ne [int64]$claim.coverage.observed -or
                    [int64]$distribution.coverage.expected -ne $eligibleCount -or
                    [int64]$distribution.coverage.observed -ne [int64]$claim.coverage.observed -or
                    $null -eq $distributionSource -or [string]$distributionSource.recordType -cne 'evidence-record' -or
                    [string]$distribution.sourceEvidenceDigest -cne [string]$distributionSource.contentDigest -or
                    [string]$distributionSource.claimId -cne [string]$claim.claimBindingId -or
                    [string]$distributionSource.distributionRef -cne [string]$distribution.recordId -or
                    [string]$distributionSource.cohortRef -cne [string]$Chain.currentFleetIssue.cohortRef -or
                    [string]$distributionSource.observationWindow -cne [string]$claim.observationWindow -or
                    [string]$distributionSource.provenance -cne [string]$claim.provenanceTier -or
                    [string]$distributionSource.tool.name -cne [string]$claim.sourceToolRef -or
                    [string]$distributionSource.tool.version -cne [string]$claim.sourceToolVersion -or
                    [string]$distributionSource.baselineFingerprint -cne [string]$claim.baselineFingerprint -or
                    @($claim.sourcePointers | Where-Object {
                        [string]$_.recordRef -ceq [string]$distribution.sourceEvidenceRef -and
                        [string]$_.contentDigest -ceq [string]$distributionSource.contentDigest -and
                        [string]$_.jsonPointer -ceq '/result/status'
                    }).Count -ne 1 -or
                    @($releaseRecords | Where-Object {
                        [string]$_.recordId -ceq [string]$distribution.sourceEvidenceReleaseRef -and
                        [string]$_.releaseSubjectDigest -ceq [string]$distribution.sourceEvidenceReleaseSubjectDigest -and
                        @($_.memberRecordIds) -ccontains ([string]$claim.distributionRef).Split('#',2)[0] -and
                        @($_.memberRecordIds) -ccontains ([string]$distribution.sourceEvidenceRef).Split('#',2)[0]
                    }).Count -eq 0) {
                    Add-BlueprintError -Errors $Errors -Code 'FLEET_PORTFOLIO_DISTRIBUTION_BINDING_INVALID' -Message 'Fleet distribution claim does not reconcile its digest, metric, unit, direction, cohort coverage, Phase 0 floor, run count, source, and release.'
                }
            }
            elseif ($expectedShape -cin @('DENOMINATED_COUNT','STRUCTURED_STATE')) {
                $expectedResultPointer = if ($expectedShape -ceq 'DENOMINATED_COUNT') { '/result/numeratorValue' } else { '/result/state' }
                $summary = Resolve-CanonicalRecord -RecordMap $RecordMap -Reference $claim.structuredSummaryRef -ExpectedTypes @('evidence-record') -Context "fleet claim $expectedClaimType structured summary" -Errors $Errors
                $resultFound = $false
                $resultValue = if ($null -ne $summary) {
                    Get-JsonPointerValue -Document $summary.payload -Pointer ([string]$claim.resultPointer) -Found ([ref]$resultFound)
                }
                else { $null }
                $resultDigest = if ($resultFound) { Get-CanonicalPayloadDigest -Payload $resultValue } else { '' }
                $summaryReleaseMatches = @($releaseRecords | Where-Object {
                    [string]$_.recordId -ceq [string]$summary.evidenceReleaseRef -and
                    @($_.memberRecordIds) -ccontains ([string]$claim.structuredSummaryRef).Split('#',2)[0]
                }).Count -gt 0
                $summaryCoverage = if ($null -ne $summary) { $summary.coverage } else { $null }
                $summaryCoverageValid = $summaryCoverage -is [pscustomobject] -and
                    (Test-NonBlankString $summaryCoverage.scope) -and
                    ($summaryCoverage.plannedUnits -is [int] -or $summaryCoverage.plannedUnits -is [long]) -and
                    ($summaryCoverage.observedUnits -is [int] -or $summaryCoverage.observedUnits -is [long]) -and
                    ($summaryCoverage.plannedRuns -is [int] -or $summaryCoverage.plannedRuns -is [long]) -and
                    ($summaryCoverage.observedRuns -is [int] -or $summaryCoverage.observedRuns -is [long]) -and
                    (Test-NumberValue $summaryCoverage.percent) -and
                    $summaryCoverage.gaps -is [System.Collections.IList]
                if ($summaryCoverageValid) {
                    [int64]$eligibleUnits = [int64]$claim.coverage.eligible
                    [double]$expectedSummaryPercent = if ($eligibleUnits -gt 0) { 100.0 * [int64]$claim.coverage.observed / $eligibleUnits } else { -1.0 }
                    $summaryCoverageValid = [int64]$summaryCoverage.plannedUnits -eq $eligibleUnits -and
                        [int64]$summaryCoverage.observedUnits -eq [int64]$claim.coverage.observed -and
                        [int64]$summaryCoverage.plannedRuns -ge [int64]$summaryCoverage.plannedUnits -and
                        [int64]$summaryCoverage.observedRuns -ge [int64]$summaryCoverage.observedUnits -and
                        [int64]$summaryCoverage.observedRuns -le [int64]$summaryCoverage.plannedRuns -and
                        [Math]::Abs([double]$summaryCoverage.percent - $expectedSummaryPercent) -le 0.01 -and
                        (([int64]$claim.coverage.missing -eq 0 -and @($summaryCoverage.gaps).Count -eq 0) -or
                         ([int64]$claim.coverage.missing -gt 0 -and @($summaryCoverage.gaps).Count -gt 0))
                }
                if ($null -eq $summary -or [string]$summary.contentDigest -cne [string]$claim.structuredSummaryDigest -or
                    -not $sourceMap.ContainsKey([string]$claim.structuredSummaryRef) -or
                    -not $summaryReleaseMatches -or [string]$summary.claimId -cne [string]$claim.claimBindingId -or
                    [string]$summary.metricId -cne [string]$claim.metricId -or [string]$summary.unit -cne [string]$claim.unit -or
                    [string]$summary.statisticDirection -cne [string]$claim.statisticDirection -or
                    [string]$summary.cohortRef -cne [string]$Chain.currentFleetIssue.cohortRef -or
                    [string]$summary.coverageStatus -cne 'PASS' -or -not $summaryCoverageValid -or
                    [string]$summary.provenance -cne [string]$claim.provenanceTier -or
                    [string]$summary.tool.name -cne [string]$claim.sourceToolRef -or
                    [string]$summary.tool.version -cne [string]$claim.sourceToolVersion -or
                    [string]$summary.baselineFingerprint -cne [string]$claim.baselineFingerprint -or
                    [string]$summary.observationWindow -cne [string]$claim.observationWindow -or
                    [string]$claim.resultPointer -cne $expectedResultPointer -or -not $resultFound -or
                    [string]$claim.resultDigest -cne [string]$resultDigest -or
                    @($claim.sourcePointers | Where-Object {
                        [string]$_.recordRef -ceq [string]$claim.structuredSummaryRef -and
                        [string]$_.contentDigest -ceq [string]$claim.structuredSummaryDigest -and
                        [string]$_.jsonPointer -ceq [string]$claim.resultPointer
                    }).Count -ne 1) {
                    Add-BlueprintError -Errors $Errors -Code 'FLEET_PORTFOLIO_STRUCTURED_SUMMARY_INVALID' -Message 'Fleet structured claim summary does not bind the exact evidence, metric, result projection/digest, provenance, baseline, window, tool, and release.'
                }
                if ($expectedShape -ceq 'DENOMINATED_COUNT') {
                    $scale = switch ([string]$claim.rateScale) {
                        'PER_UNIT' { [decimal]1 }
                        'PERCENT' { [decimal]100 }
                        'PER_1000' { [decimal]1000 }
                        default { [decimal]0 }
                    }
                    $numericValid = $resultFound -and ($resultValue -is [int] -or $resultValue -is [long]) -and
                        ($claim.numeratorValue -is [int] -or $claim.numeratorValue -is [long]) -and [int64]$claim.numeratorValue -ge 0 -and
                        (Test-NumberValue $claim.rateValue) -and [double]$claim.rateValue -ge 0 -and
                        $scale -gt 0 -and $claim.denominator -is [pscustomobject] -and
                        ($claim.denominator.value -is [int] -or $claim.denominator.value -is [long]) -and
                        [int64]$claim.denominator.value -gt 0 -and
                        [int64]$claim.numeratorValue -le [int64]$claim.denominator.value
                    if ($numericValid) {
                        [decimal]$expectedRate = ([decimal]$claim.numeratorValue / [decimal]$claim.denominator.value) * $scale
                        $numericValid = (Get-CanonicalPayloadDigest -Payload $resultValue) -ceq (Get-CanonicalPayloadDigest -Payload $claim.numeratorValue) -and
                            [Math]::Abs([double]([decimal]$claim.rateValue - $expectedRate)) -le 0.000000001
                    }
                    if (-not $numericValid) {
                        Add-BlueprintError -Errors $Errors -Code 'FLEET_PORTFOLIO_STRUCTURED_SUMMARY_INVALID' -Message 'Fleet denominated claim must bind a nonnegative integer /result/numeratorValue and a rate recomputed from its exact governed denominator and scale.'
                    }
                }
                else {
                    $actualResultType = if ($resultValue -is [bool]) { 'BOOLEAN' }
                        elseif ($resultValue -is [string]) { 'STRING' }
                        elseif ($resultValue -is [pscustomobject]) { 'OBJECT' }
                        elseif ($resultValue -is [System.Collections.IList] -and $resultValue -isnot [string]) { 'ARRAY' }
                        else { '' }
                    if ([string]$claim.resultValueType -cne $actualResultType) {
                        Add-BlueprintError -Errors $Errors -Code 'FLEET_PORTFOLIO_STRUCTURED_SUMMARY_INVALID' -Message 'Fleet structured-state claim resultValueType does not match the exact pointed JSON value.'
                    }
                }
            }
            if ($expectedShape -cin @('DISTRIBUTION','DENOMINATED_COUNT')) {
                $denominatorValid = $claim.denominator -is [pscustomobject] -and
                    (Test-NonBlankString $claim.denominator.definition) -and (Test-NonBlankString $claim.denominator.unit) -and
                    (Test-NumberValue $claim.denominator.value) -and [double]$claim.denominator.value -gt 0 -and
                    $claimCoverageValid -and [double]$claim.denominator.value -eq [int64]$claim.coverage.eligible
                if (-not $denominatorValid) {
                    Add-BlueprintError -Errors $Errors -Code 'FLEET_PORTFOLIO_CLAIM_DENOMINATOR_INVALID' -Message 'Fleet quantitative claim denominator must be positive and equal the exact eligible cohort after governed exclusions.'
                }
            }
        }

        $expectedDimensionDigest = Get-CanonicalPayloadDigest -Payload ([pscustomobject][ordered]@{
            dimensionId = [string]$dimension.dimensionId
            status = [string]$dimension.status
            claimBindings = @($dimension.claimBindings)
        })
        if ([string]$dimension.dimensionEvidenceDigest -cne [string]$expectedDimensionDigest) {
            Add-BlueprintError -Errors $Errors -Code 'FLEET_PORTFOLIO_DIMENSION_DIGEST_MISMATCH' -Message 'Fleet dimension evidence digest does not match its exact ordered identity, status, and claim bindings.'
        }
        [void]$dimensionDigestBindings.Add([pscustomobject][ordered]@{
            dimensionId = [string]$dimensionId
            dimensionEvidenceDigest = [string]$dimension.dimensionEvidenceDigest
        })
    }

    $expectedBindingsDigest = Get-CanonicalPayloadDigest -Payload ([pscustomobject][ordered]@{
        dimensionPolicyRef = $expectedPolicyRef
        dimensionPolicyDigest = [string]$expectedPolicyDigest
        dimensions = @($dimensionDigestBindings)
    })
    $expectedExecutionDigest = Get-CanonicalPayloadDigest -Payload ([pscustomobject][ordered]@{
        dimensionPolicyRef = $expectedPolicyRef
        dimensionPolicyDigest = [string]$expectedPolicyDigest
        policyExecutionToolRef = [string]$coverage.policyExecutionToolRef
        policyExecutionToolVersion = [string]$coverage.policyExecutionToolVersion
        policyExecutedAt = [string]$coverage.policyExecutedAt
        bindingsDigest = [string]$coverage.bindingsDigest
    })
    if ([string]$coverage.bindingsDigest -cne [string]$expectedBindingsDigest) {
        Add-BlueprintError -Errors $Errors -Code 'FLEET_PORTFOLIO_BINDINGS_DIGEST_MISMATCH' -Message 'Fleet portfolio bindingsDigest does not match the fixed twelve-dimension policy order and evidence digests.'
    }
    if ([string]$coverage.policyExecutionDigest -cne [string]$expectedExecutionDigest) {
        Add-BlueprintError -Errors $Errors -Code 'FLEET_PORTFOLIO_POLICY_EXECUTION_DIGEST_MISMATCH' -Message 'Fleet policy execution digest does not match its exact policy, tool, time, and bindings projection.'
    }
}

function Get-NormalizedQualificationAuthorityApproverBindings {
    param([object[]]$ApproverBindings)

    $rowsByKey = [System.Collections.Generic.Dictionary[string,System.Collections.Queue]]::new([StringComparer]::Ordinal)
    $sortKeys = New-Object System.Collections.Generic.List[string]
    foreach ($binding in @($ApproverBindings)) {
        $row = [pscustomobject][ordered]@{
            roleId = [string]$binding.roleId
            canonicalPrincipalId = [string]$binding.canonicalPrincipalId
        }
        $key = ([string]$row.roleId) + [char]0 + ([string]$row.canonicalPrincipalId)
        if (-not $rowsByKey.ContainsKey($key)) { $rowsByKey.Add($key, [System.Collections.Queue]::new()) }
        $rowsByKey[$key].Enqueue($row)
        $sortKeys.Add($key)
    }
    [string[]]$orderedKeys = @($sortKeys)
    if ($orderedKeys.Count -gt 1) { [Array]::Sort($orderedKeys, [StringComparer]::Ordinal) }
    $normalized = New-Object System.Collections.ArrayList
    foreach ($key in $orderedKeys) { [void]$normalized.Add($rowsByKey[$key].Dequeue()) }
    return @($normalized)
}

function Get-QualificationAuthorityApproverSetDigest {
    param([object[]]$ApproverBindings)

    $normalized = @(Get-NormalizedQualificationAuthorityApproverBindings -ApproverBindings $ApproverBindings)
    return Get-CanonicalPayloadDigest -Payload ([pscustomobject][ordered]@{
        approverBindings = @($normalized)
    })
}

function Get-QualificationAuthorityDecisionRef {
    param(
        [Parameter(Mandatory = $true)][string]$VerdictRef,
        [Parameter(Mandatory = $true)][ValidateSet('VERDICT_ISSUANCE','ARBITRATION','DEADLINE_DECISION','PILOT_NOT_REQUIRED')][string]$DecisionScope
    )

    switch ($DecisionScope) {
        'VERDICT_ISSUANCE' { return $VerdictRef }
        'ARBITRATION' { return $VerdictRef + '#/arbitration' }
        'DEADLINE_DECISION' { return $VerdictRef + '#/deadlineDecision' }
        'PILOT_NOT_REQUIRED' { return $VerdictRef + '#/pilotAuthorization' }
    }
}

function Get-QualificationAuthorityDecisionSubjectDigest {
    param(
        [Parameter(Mandatory = $true)]$Verdict,
        [Parameter(Mandatory = $true)][ValidateSet('VERDICT_ISSUANCE','ARBITRATION','DEADLINE_DECISION','PILOT_NOT_REQUIRED')][string]$DecisionScope
    )

    $verdictRef = [string]$Verdict.recordId
    $subject = [ordered]@{
        decisionScope = $DecisionScope
        decisionRef = Get-QualificationAuthorityDecisionRef -VerdictRef $verdictRef -DecisionScope $DecisionScope
        verdictRef = $verdictRef
        manifestRef = [string]$Verdict.manifestRef
        qualificationAuthority = [string]$Verdict.qualificationAuthority
    }
    if ($DecisionScope -ceq 'VERDICT_ISSUANCE') {
        $approvalFields = @(
            'qualificationAuthorityApprovalRef','qualificationAuthorityApprovalDigest',
            'arbitrationAuthorityApprovalRef','arbitrationAuthorityApprovalDigest',
            'deadlineAuthorityApprovalRef','deadlineAuthorityApprovalDigest',
            'pilotNotRequiredApprovalRef','pilotNotRequiredApprovalDigest'
        )
        $decisionBindings = New-Object System.Collections.ArrayList
        foreach ($binding in @($Verdict.portableProjectionRecord.projection.bindings)) {
            if ($approvalFields -ccontains [string]$binding.projectionField) { continue }
            [void]$decisionBindings.Add([pscustomobject][ordered]@{
                projectionField = [string]$binding.projectionField
                pointer = [string]$binding.pointer
                value = $binding.value
                valueDigest = [string]$binding.valueDigest
            })
        }
        $subject.verdictProjectionBindings = @($decisionBindings)
    }
    else {
        $fieldName = switch ($DecisionScope) {
            'ARBITRATION' { 'arbitration' }
            'DEADLINE_DECISION' { 'deadlineDecision' }
            'PILOT_NOT_REQUIRED' { 'pilotAuthorization' }
        }
        $matches = @($Verdict.portableProjectionRecord.projection.bindings | Where-Object {
            [string]$_.projectionField -ceq [string]$fieldName
        })
        if ($matches.Count -ne 1) { return 'INVALID_QUALIFICATION_AUTHORITY_DECISION_SUBJECT' }
        $subject.decisionBinding = [pscustomobject][ordered]@{
            projectionField = [string]$matches[0].projectionField
            pointer = [string]$matches[0].pointer
            value = $matches[0].value
            valueDigest = [string]$matches[0].valueDigest
        }
    }
    return Get-CanonicalPayloadDigest -Payload ([pscustomobject]$subject)
}

function Get-QualificationAuthorityApprovalSubjectDigest {
    param([Parameter(Mandatory = $true)]$Approval)

    $approvalPayload = if ($Approval.payload -is [pscustomobject]) { $Approval.payload } else { $Approval }
    $normalizedApprovers = @(Get-NormalizedQualificationAuthorityApproverBindings -ApproverBindings @($approvalPayload.approverBindings))
    $subject = [ordered]@{}
    $excluded = @(
        'approvalSubjectDigest','signedSubjectDigest','approvalArtifactDigest',
        'signatureRef','signatureDigest','signatureStatus'
    )
    foreach ($property in @($approvalPayload.PSObject.Properties)) {
        if ($excluded -ccontains [string]$property.Name) { continue }
        if ([string]$property.Name -ceq 'approverBindings') {
            $subject.approverBindings = @($normalizedApprovers)
        }
        else {
            $subject[[string]$property.Name] = $property.Value
        }
    }
    return Get-CanonicalPayloadDigest -Payload ([pscustomobject]$subject)
}

function Test-QualificationAuthorityApprovalSemantics {
    param(
        [Parameter(Mandatory = $true)]$RecordMap,
        [Parameter(Mandatory = $true)][AllowNull()]$ApprovalRef,
        [Parameter(Mandatory = $true)][AllowNull()]$ApprovalDigest,
        [Parameter(Mandatory = $true)]$Verdict,
        [Parameter(Mandatory = $true)]$Manifest,
        [Parameter(Mandatory = $true)][ValidateSet('VERDICT_ISSUANCE','ARBITRATION','DEADLINE_DECISION','PILOT_NOT_REQUIRED')][string]$DecisionScope,
        [Parameter(Mandatory = $true)][DateTimeOffset]$EvaluationTime,
        [Parameter(Mandatory = $true)][string]$FailureCode,
        [Parameter(Mandatory = $true)][AllowEmptyCollection()][System.Collections.ArrayList]$Errors
    )

    $initialErrorCount = $Errors.Count
    $approval = Resolve-CanonicalRecord -RecordMap $RecordMap -Reference $ApprovalRef `
        -ExpectedTypes @('qualification-authority-approval-record') `
        -Context "$DecisionScope qualification-authority approval" -Errors $Errors
    if ($null -eq $approval -or [string]$approval.recordType -cne 'qualification-authority-approval-record') {
        Add-BlueprintError -Errors $Errors -Code $FailureCode -Message 'The decision lacks one exact typed qualification-authority approval.'
        return [pscustomobject]@{ Valid = $false; Approval = $null; RoleClosure = $null }
    }

    $fields = @(
        'schemaVersion','recordStage','status','tenantBoundaryRef','targetEnvironmentRef','manifestRef',
        'manifestDigest','verdictRef','qualificationAuthority','authorityRole','authorityPrincipalId',
        'recordProducerPrincipalId','affectedRequesterPrincipalId','approverBindings','approverSetRef',
        'approverSetDigest','roleBindingRef','roleBindingDigest','roleBindingReadbackRef',
        'roleBindingReadbackDigest','roleBindingReadbackPolicyRef','roleBindingReadbackPolicyDigest',
        'roleBindingReadbackMaxAgeMinutes','decisionScope','decisionRef','decisionSubjectDigest',
        'approvalSubjectDigest','signedSubjectRef','signedSubjectDigest','approvalArtifactRef',
        'approvalArtifactDigest','signatureRef','signatureDigest','signatureStatus','issuedAt','approvedAt',
        'expiresAt','freshnessBinding','revocationStatus','revocationEvidenceRef',
        'revocationEvidenceDigest','revocationCheckedAt','authorizationEffect'
    )
    Test-RequiredProperties -Object $approval -Names $fields -Context "$DecisionScope qualification-authority approval" -Errors $Errors

    $approverBindings = @($approval.approverBindings)
    $approverRoles = [System.Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal)
    $approverPrincipals = [System.Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
    [string[]]$frozenRoles = @(Get-FrozenRoleCatalog)
    $approversValid = $approverBindings.Count -ge 2
    foreach ($binding in $approverBindings) {
        if ($binding -isnot [pscustomobject]) { $approversValid = $false; continue }
        Test-RequiredProperties -Object $binding -Names @('roleId','canonicalPrincipalId') -Context 'qualification-authority approver binding' -Errors $Errors
        Test-AllowedProperties -Object $binding -Names @('roleId','canonicalPrincipalId') -Context 'qualification-authority approver binding' -Errors $Errors
        if ($frozenRoles -cnotcontains [string]$binding.roleId -or
            [string]$binding.canonicalPrincipalId -cnotmatch '^private://canonical-principals/sha256/[0-9a-f]{64}$' -or
            -not $approverRoles.Add([string]$binding.roleId) -or
            -not $approverPrincipals.Add([string]$binding.canonicalPrincipalId)) {
            $approversValid = $false
        }
    }
    [string[]]$expectedApproverRoles = @($Verdict.approvers | ForEach-Object { [string]$_ })
    [string[]]$actualApproverRoles = @($approverBindings | ForEach-Object { [string]$_.roleId })
    if ($expectedApproverRoles.Count -gt 1) { [Array]::Sort($expectedApproverRoles, [StringComparer]::Ordinal) }
    if ($actualApproverRoles.Count -gt 1) { [Array]::Sort($actualApproverRoles, [StringComparer]::Ordinal) }
    $approversValid = $approversValid -and (Test-CanonicalValueEqual $expectedApproverRoles $actualApproverRoles)
    $expectedApproverSetDigest = Get-QualificationAuthorityApproverSetDigest -ApproverBindings $approverBindings

    [int64]$readbackMaximumAge = if (($approval.roleBindingReadbackMaxAgeMinutes -is [int] -or
            $approval.roleBindingReadbackMaxAgeMinutes -is [long]) -and
        [int64]$approval.roleBindingReadbackMaxAgeMinutes -gt 0) {
        [int64]$approval.roleBindingReadbackMaxAgeMinutes
    }
    else { 0 }
    $policyErrorCount = $Errors.Count
    $readbackPolicy = if ($readbackMaximumAge -gt 0) {
        Test-SecurityFreshnessPolicyBinding -RecordMap $RecordMap `
            -Reference $approval.roleBindingReadbackPolicyRef -Digest $approval.roleBindingReadbackPolicyDigest `
            -ExpectedKind 'READBACK_FRESHNESS' -ExpectedMaximumAgeMinutes $readbackMaximumAge `
            -ExpectedTenantBoundaryRef ([string]$approval.tenantBoundaryRef) `
            -ExpectedTargetEnvironmentRef ([string]$approval.targetEnvironmentRef) `
            -ExpectedAuthorityMode 'ROOT_BOOTSTRAP' -EvaluationTime $EvaluationTime -Errors $Errors
    }
    else { $null }
    $policyValid = $null -ne $readbackPolicy -and $Errors.Count -eq $policyErrorCount

    $roleErrorCount = $Errors.Count
    $roleClosure = if ($readbackMaximumAge -gt 0) {
        Test-RoleBindingClosure -RecordMap $RecordMap -RoleBindingRef ([string]$approval.roleBindingRef) `
            -RoleBindingDigest ([string]$approval.roleBindingDigest) `
            -RoleBindingReadbackRef ([string]$approval.roleBindingReadbackRef) `
            -RoleBindingReadbackDigest ([string]$approval.roleBindingReadbackDigest) `
            -ExpectedTenantBoundaryRef ([string]$approval.tenantBoundaryRef) `
            -ExpectedTargetEnvironmentRef ([string]$approval.targetEnvironmentRef) `
            -ExpectedReadbackPolicyRef ([string]$approval.roleBindingReadbackPolicyRef) `
            -ExpectedReadbackPolicyDigest ([string]$approval.roleBindingReadbackPolicyDigest) `
            -ExpectedReadbackMaximumAgeMinutes $readbackMaximumAge `
            -EvaluationTime $EvaluationTime -Errors $Errors
    }
    else { $null }
    $roleClosureValid = $null -ne $roleClosure -and $Errors.Count -eq $roleErrorCount

    $roleAssignmentsValid = $roleClosureValid
    if ($null -ne $roleClosure) {
        if (@($roleClosure.RoleBinding.bindings | Where-Object {
                [string]$_.roleId -ceq 'ROLE_QUALIFICATION_AUTHORITY' -and
                [string]$_.canonicalPrincipalId -ceq [string]$approval.authorityPrincipalId
            }).Count -ne 1) { $roleAssignmentsValid = $false }
        foreach ($binding in $approverBindings) {
            if (@($roleClosure.RoleBinding.bindings | Where-Object {
                    [string]$_.roleId -ceq [string]$binding.roleId -and
                    [string]$_.canonicalPrincipalId -ceq [string]$binding.canonicalPrincipalId
                }).Count -ne 1) { $roleAssignmentsValid = $false }
        }
    }

    $principalSet = [System.Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
    $principalSeparationValid = $true
    $principals = @(
        [string]$approval.authorityPrincipalId,
        [string]$approval.recordProducerPrincipalId,
        [string]$approval.affectedRequesterPrincipalId
    ) + @($approverBindings | ForEach-Object { [string]$_.canonicalPrincipalId })
    if ($null -ne $roleClosure) {
        foreach ($alias in @(
            [string]$roleClosure.RoleBinding.sourceIdentityRef,
            [string]$roleClosure.Readback.readIdentityRef
        )) {
            if ($roleClosure.AliasMap.ContainsKey($alias)) { $principals += @([string]$roleClosure.AliasMap[$alias]) }
            else { $principalSeparationValid = $false }
        }
        $principals += @(
            [string]$roleClosure.Approval.approverPrincipalRef,
            [string]$roleClosure.RootAuthority.ceremonyOperatorIdentityRef,
            [string]$roleClosure.RootAuthority.independentReadIdentityRef
        )
        $principals += @($roleClosure.RootAuthority.authorityKeyBindings | ForEach-Object { [string]$_.keyCustodianPrincipalId })
    }
    foreach ($principal in $principals) {
        if ([string]$principal -cnotmatch '^private://canonical-principals/sha256/[0-9a-f]{64}$' -or
            -not $principalSet.Add([string]$principal)) { $principalSeparationValid = $false }
    }

    $expectedDecisionRef = Get-QualificationAuthorityDecisionRef -VerdictRef ([string]$Verdict.recordId) -DecisionScope $DecisionScope
    $expectedDecisionSubjectDigest = Get-QualificationAuthorityDecisionSubjectDigest -Verdict $Verdict -DecisionScope $DecisionScope
    $expectedApprovalSubjectDigest = Get-QualificationAuthorityApprovalSubjectDigest -Approval $approval
    [DateTimeOffset]$issuedAt = [DateTimeOffset]::MinValue
    [DateTimeOffset]$approvedAt = [DateTimeOffset]::MinValue
    [DateTimeOffset]$expiresAt = [DateTimeOffset]::MinValue
    [DateTimeOffset]$revocationCheckedAt = [DateTimeOffset]::MinValue
    [DateTimeOffset]$roleObservedAt = [DateTimeOffset]::MinValue
    $timesValid = [OperationsBlueprint.StrictRfc3339]::TryParse([string]$approval.issuedAt, [ref]$issuedAt) -and
        [OperationsBlueprint.StrictRfc3339]::TryParse([string]$approval.approvedAt, [ref]$approvedAt) -and
        [OperationsBlueprint.StrictRfc3339]::TryParse([string]$approval.expiresAt, [ref]$expiresAt) -and
        [OperationsBlueprint.StrictRfc3339]::TryParse([string]$approval.revocationCheckedAt, [ref]$revocationCheckedAt) -and
        $issuedAt -le $approvedAt -and $approvedAt -le $revocationCheckedAt -and
        $revocationCheckedAt -le $EvaluationTime -and $expiresAt -gt $EvaluationTime -and
        $expiresAt -gt $approvedAt
    if ($null -ne $roleClosure) {
        $timesValid = $timesValid -and
            [OperationsBlueprint.StrictRfc3339]::TryParse([string]$roleClosure.Readback.observedAt, [ref]$roleObservedAt) -and
            $roleObservedAt -lt $issuedAt
    }
    $freshnessValid = Test-PortableContractFreshnessBinding -Freshness $approval.freshnessBinding `
        -EvaluationTime $EvaluationTime -Context "$DecisionScope authority approval freshness" -Errors $Errors
    $freshnessValid = $freshnessValid -and
        [string]$approval.freshnessBinding.observedAt -ceq [string]$approval.revocationCheckedAt -and
        [string]$approval.freshnessBinding.policyRef -ceq [string]$approval.roleBindingReadbackPolicyRef -and
        [string]$approval.freshnessBinding.dependencySnapshotRef -ceq [string]$approval.revocationEvidenceRef -and
        [string]$approval.freshnessBinding.dependencySnapshotDigest -ceq [string]$approval.revocationEvidenceDigest -and
        [string]$approval.freshnessBinding.dependencyStatus -ceq 'MATCH' -and
        $readbackMaximumAge -gt 0 -and
        $revocationCheckedAt -ne [DateTimeOffset]::MinValue -and
        ($EvaluationTime - $revocationCheckedAt).TotalMinutes -le $readbackMaximumAge

    $valid = [string]$ApprovalRef -ceq [string]$approval.recordId -and
        [string]$approval.contentDigest -ceq [string]$ApprovalDigest -and
        [string]$approval.schemaVersion -ceq '1.0.0' -and
        [string]$approval.recordStage -ceq 'QUALIFICATION_AUTHORITY_APPROVAL' -and
        [string]$approval.status -ceq 'APPROVED' -and
        [string]$approval.tenantBoundaryRef -ceq [string]$Manifest.tenantBoundaryRef -and
        [string]$approval.targetEnvironmentRef -ceq [string]$Manifest.targetEnvironmentRef -and
        [string]$approval.manifestRef -ceq [string]$Manifest.recordId -and
        [string]$approval.manifestDigest -ceq [string]$Manifest.contentDigest -and
        [string]$approval.verdictRef -ceq [string]$Verdict.recordId -and
        [string]$approval.qualificationAuthority -ceq [string]$Manifest.qualificationAuthority -and
        [string]$approval.qualificationAuthority -ceq [string]$Verdict.qualificationAuthority -and
        [string]$approval.authorityRole -ceq 'ROLE_QUALIFICATION_AUTHORITY' -and
        [string]$approval.authorityPrincipalId -cmatch '^private://canonical-principals/sha256/[0-9a-f]{64}$' -and
        [string]$approval.recordProducerPrincipalId -cmatch '^private://canonical-principals/sha256/[0-9a-f]{64}$' -and
        [string]$approval.affectedRequesterPrincipalId -cmatch '^private://canonical-principals/sha256/[0-9a-f]{64}$' -and
        $approversValid -and
        [string]$approval.approverSetRef -cmatch '^private://' -and
        [string]$approval.approverSetDigest -ceq [string]$expectedApproverSetDigest -and
        $policyValid -and $roleClosureValid -and $roleAssignmentsValid -and $principalSeparationValid -and
        [string]$approval.decisionScope -ceq $DecisionScope -and
        [string]$approval.decisionRef -ceq [string]$expectedDecisionRef -and
        [string]$approval.decisionSubjectDigest -ceq [string]$expectedDecisionSubjectDigest -and
        [string]$approval.approvalSubjectDigest -ceq [string]$expectedApprovalSubjectDigest -and
        [string]$approval.signedSubjectRef -cmatch '^private://' -and
        [string]$approval.signedSubjectDigest -ceq [string]$expectedApprovalSubjectDigest -and
        [string]$approval.approvalArtifactRef -cmatch '^private://' -and
        [string]$approval.approvalArtifactDigest -ceq [string]$expectedApprovalSubjectDigest -and
        [string]$approval.signatureRef -cmatch '^private://' -and
        (Test-Sha256Token $approval.signatureDigest) -and
        [string]$approval.signatureStatus -ceq 'VERIFIED' -and $timesValid -and $freshnessValid -and
        [string]$approval.revocationStatus -ceq 'NOT_REVOKED' -and
        [string]$approval.revocationEvidenceRef -cmatch '^private://' -and
        (Test-Sha256Token $approval.revocationEvidenceDigest) -and
        [string]$approval.authorizationEffect -ceq 'NONE'
    if (-not $valid -or $Errors.Count -gt $initialErrorCount) {
        Add-BlueprintError -Errors $Errors -Code $FailureCode -Message 'The qualification-authority approval is not current, scope-exact, role-bound, independently read back, signed over its recomputed subject, non-revoked, and principal-separated.'
        $valid = $false
    }
    return [pscustomobject]@{ Valid = $valid; Approval = $approval; RoleClosure = $roleClosure }
}

function Get-PilotDistributionUnitSetDigest {
    param([Parameter(Mandatory = $true)]$Distribution)

    [string[]]$unitRefs = @($Distribution.perUnitRunCounts | ForEach-Object { [string]$_.unitRef })
    if ($unitRefs.Count -gt 1) { [Array]::Sort($unitRefs, [StringComparer]::Ordinal) }
    return Get-CanonicalPayloadDigest -Payload ([pscustomobject][ordered]@{
        canonicalization = 'ORDINAL_PRIVATE_UNIT_REF_SET'
        version = '1.0.0'
        unitCount = $Distribution.unitCount
        unitRefs = @($unitRefs)
    })
}

function Get-PilotParticipantCommitmentDomainDigest {
    param(
        [Parameter(Mandatory = $true)]$Proof,
        [Parameter(Mandatory = $true)]$PilotEvidenceRelease,
        [Parameter(Mandatory = $true)]$Manifest,
        [Parameter(Mandatory = $true)]$Phase0TestPlan,
        [Parameter(Mandatory = $true)]$FrozenThresholdPolicy,
        [Parameter(Mandatory = $true)][string]$PilotPopulationPlanRef,
        [Parameter(Mandatory = $true)][string]$PilotPopulationPlanDigest,
        [Parameter(Mandatory = $true)]$PilotVerdict,
        [Parameter(Mandatory = $true)][string]$AuthorizedAt,
        [Parameter(Mandatory = $true)][string]$StartedAt,
        [Parameter(Mandatory = $true)][string]$CompletedAt
    )

    return Get-CanonicalPayloadDigest -Payload ([pscustomobject][ordered]@{
        releaseRef = [string]$PilotEvidenceRelease.recordId
        releaseSubjectDigest = [string]$PilotEvidenceRelease.releaseSubjectDigest
        manifestRef = [string]$Manifest.recordId
        manifestDigest = [string]$Manifest.contentDigest
        phase0TestPlanRef = [string]$Phase0TestPlan.recordId
        phase0TestPlanDigest = [string]$Phase0TestPlan.contentDigest
        thresholdPolicyRef = [string]$FrozenThresholdPolicy.recordId
        thresholdPolicyDigest = [string]$FrozenThresholdPolicy.contentDigest
        pilotPopulationPlanRef = $PilotPopulationPlanRef
        pilotPopulationPlanDigest = $PilotPopulationPlanDigest
        pilotAuthorizationRecordRef = [string]$PilotVerdict.recordId
        pilotAuthorizationRecordDigest = [string]$PilotVerdict.contentDigest
        authorizedAt = $AuthorizedAt
        startedAt = $StartedAt
        completedAt = $CompletedAt
        attributeSnapshotRef = [string]$Proof.attributeSnapshotRef
        attributeSnapshotDigest = [string]$Proof.attributeSnapshotDigest
        attributeSnapshotAt = [string]$Proof.attributeSnapshotAt
        purpose = [string]$Proof.populationCommitmentPurpose
        keyRef = [string]$Proof.populationCommitmentKeyRef
        keyVersion = [string]$Proof.populationCommitmentKeyVersion
        canonicalization = [string]$Proof.populationCanonicalization
        canonicalizationVersion = [string]$Proof.populationCanonicalizationVersion
    })
}

function Get-PilotParticipantProofSubjectDigest {
    param([Parameter(Mandatory = $true)]$Proof)

    $subject = [ordered]@{}
    foreach ($property in @($Proof.PSObject.Properties)) {
        if (@('proofSubjectDigest','protectedProofRef','protectedProofDigest','protectedProofStatus') -ccontains [string]$property.Name) { continue }
        $subject[[string]$property.Name] = $property.Value
    }
    return Get-CanonicalPayloadDigest -Payload ([pscustomobject]$subject)
}

function Test-PilotPrivateParticipantClosure {
    param(
        [AllowNull()]$ProductionRepresentation,
        [AllowNull()]$SentimentRepresentation,
        [AllowNull()]$PilotEvidenceRelease,
        [AllowNull()]$Manifest,
        [AllowNull()]$Phase0TestPlan,
        [AllowNull()]$FrozenThresholdPolicy,
        [AllowNull()]$PilotPopulationPlan,
        [Parameter(Mandatory = $true)][AllowEmptyString()][string]$PilotPopulationPlanRef,
        [AllowNull()]$PilotVerdict,
        [AllowNull()]$FinalVerdict,
        [AllowNull()]$ProductionEvidence,
        [AllowNull()]$SentimentEvidence,
        [AllowNull()]$ProductionDistribution,
        [AllowNull()]$SentimentDistribution,
        [Parameter(Mandatory = $true)][DateTimeOffset]$AuthorizedAt,
        [Parameter(Mandatory = $true)][DateTimeOffset]$StartedAt,
        [Parameter(Mandatory = $true)][DateTimeOffset]$CompletedAt,
        [Parameter(Mandatory = $true)][AllowEmptyString()][string]$StartedAtText,
        [Parameter(Mandatory = $true)][AllowEmptyString()][string]$CompletedAtText,
        [Parameter(Mandatory = $true)][DateTimeOffset]$EvaluationTime,
        [ValidateSet('TEST','PRODUCTION')][string]$ValidationProfile,
        [Parameter(Mandatory = $true)][AllowEmptyCollection()][System.Collections.ArrayList]$Errors
    )

    $initialErrorCount = $Errors.Count
    $ValidationProfile = ([string]$ValidationProfile).ToUpperInvariant()
    if ($ProductionRepresentation -isnot [pscustomobject] -or $SentimentRepresentation -isnot [pscustomobject] -or
        $ProductionRepresentation.populationProof -isnot [pscustomobject] -or
        $SentimentRepresentation.populationProof -isnot [pscustomobject] -or
        $null -eq $PilotEvidenceRelease -or $null -eq $Manifest -or $null -eq $Phase0TestPlan -or
        $null -eq $FrozenThresholdPolicy -or $PilotPopulationPlan -isnot [pscustomobject] -or
        $null -eq $PilotVerdict -or $null -eq $FinalVerdict -or
        $null -eq $ProductionEvidence -or $null -eq $SentimentEvidence -or
        $null -eq $ProductionDistribution -or $null -eq $SentimentDistribution) {
        Add-BlueprintError -Errors $Errors -Code 'PILOT_PARTICIPANT_COMMITMENT_INVALID' -Message 'Pilot completion lacks one closed shared participant commitment across production and sentiment evidence.'
        if ($ValidationProfile -ceq 'PRODUCTION') {
            Add-BlueprintError -Errors $Errors -Code 'PILOT_PRIVATE_PARTICIPANT_PROOF_UNVERIFIED' -Message 'The public validator cannot authenticate protected pilot population proof bytes.'
        }
        return $false
    }

    $proof = $ProductionRepresentation.populationProof
    $proofFields = @(
        'proofScheme','proofVersion','populationCanonicalization','populationCanonicalizationVersion',
        'populationCommitmentKeyRef','populationCommitmentKeyVersion','populationCommitmentPurpose',
        'populationCommitmentDomainDigest','plannedPopulationSourceRef','plannedPopulationSourceDigest',
        'attributeSnapshotRef','attributeSnapshotDigest','attributeSnapshotAt','plannedCount','enrolledCount',
        'completedCount','respondentCount','plannedPopulationDigest','enrolledPopulationDigest',
        'completedPopulationDigest','respondentPopulationDigest','completedUnitSetDigest','respondentUnitSetDigest',
        'productionRepresentationDigest','sentimentRepresentationDigest','selectionProofRef','selectionProofDigest',
        'enrollmentSubsetProofRef','enrollmentSubsetProofDigest','completionSubsetProofRef',
        'completionSubsetProofDigest','respondentSubsetProofRef','respondentSubsetProofDigest',
        'attributePartitionProofRef','attributePartitionProofDigest','distributionWindowBindings',
        'proofIssuerPrincipalId','proofIssuedAt','proofExpiresAt','proofRevocationStatus',
        'proofRevocationEvidenceRef','proofRevocationEvidenceDigest','proofRevocationCheckedAt',
        'proofSubjectDigest','protectedProofRef','protectedProofDigest','protectedProofStatus'
    )
    Test-RequiredProperties -Object $proof -Names $proofFields -Context 'pilot participant commitment' -Errors $Errors
    Test-AllowedProperties -Object $proof -Names $proofFields -Context 'pilot participant commitment' -Errors $Errors
    if (-not (Test-CanonicalValueEqual $proof $SentimentRepresentation.populationProof)) {
        Add-BlueprintError -Errors $Errors -Code 'PILOT_PARTICIPANT_COMMITMENT_INVALID' -Message 'Production and sentiment evidence must carry the same shared participant commitment.'
    }

    $productionRepresentationBase = [ordered]@{}
    foreach ($property in @($ProductionRepresentation.PSObject.Properties)) {
        if ([string]$property.Name -ceq 'populationProof') { continue }
        $productionRepresentationBase[[string]$property.Name] = $property.Value
    }
    $sentimentRepresentationBase = [ordered]@{}
    foreach ($property in @($SentimentRepresentation.PSObject.Properties)) {
        if (@('populationProof','parentProductionEvidenceRef','parentProductionEvidenceDigest') -ccontains [string]$property.Name) { continue }
        $sentimentRepresentationBase[[string]$property.Name] = $property.Value
    }
    $pilotPopulationPlanDigest = Get-CanonicalPayloadDigest -Payload $PilotPopulationPlan
    $expectedDomainDigest = Get-PilotParticipantCommitmentDomainDigest -Proof $proof `
        -PilotEvidenceRelease $PilotEvidenceRelease -Manifest $Manifest -Phase0TestPlan $Phase0TestPlan `
        -FrozenThresholdPolicy $FrozenThresholdPolicy -PilotPopulationPlanRef $PilotPopulationPlanRef `
        -PilotPopulationPlanDigest $pilotPopulationPlanDigest -PilotVerdict $PilotVerdict `
        -AuthorizedAt ([string]$PilotVerdict.pilotAuthorization.approvedAt) `
        -StartedAt $StartedAtText -CompletedAt $CompletedAtText

    [DateTimeOffset]$attributeSnapshotAt = [DateTimeOffset]::MinValue
    [DateTimeOffset]$proofIssuedAt = [DateTimeOffset]::MinValue
    [DateTimeOffset]$proofExpiresAt = [DateTimeOffset]::MinValue
    [DateTimeOffset]$proofRevocationCheckedAt = [DateTimeOffset]::MinValue
    [DateTimeOffset]$productionEvidenceAdmittedAt = [DateTimeOffset]::MinValue
    [DateTimeOffset]$sentimentEvidenceAdmittedAt = [DateTimeOffset]::MinValue
    [DateTimeOffset]$pilotEvidenceReleasedAt = [DateTimeOffset]::MinValue
    [DateTimeOffset]$finalVerdictImmutableAt = [DateTimeOffset]::MinValue
    $metadataValid = [string]$proof.proofScheme -ceq 'HMAC_SHA256_SORTED_SET_COMMITMENT' -and
        [string]$proof.proofVersion -ceq '1.0.0' -and
        [string]$proof.populationCanonicalization -ceq 'UTF8_NFC_LENGTH_PREFIXED_SORTED' -and
        [string]$proof.populationCanonicalizationVersion -ceq '1.0.0' -and
        [string]$proof.populationCommitmentPurpose -ceq 'PILOT_PARTICIPANT_CLOSURE' -and
        [string]$proof.populationCommitmentKeyRef -cmatch '^private://\S+$' -and
        [string]$proof.populationCommitmentKeyVersion -cmatch '^[A-Za-z0-9][A-Za-z0-9._:-]{0,255}$' -and
        [string]$proof.plannedPopulationSourceRef -cmatch '^private://\S+$' -and
        (Test-Sha256Token $proof.plannedPopulationSourceDigest) -and
        [string]$proof.attributeSnapshotRef -cmatch '^private://\S+$' -and
        (Test-Sha256Token $proof.attributeSnapshotDigest) -and
        [string]$proof.populationCommitmentDomainDigest -ceq [string]$expectedDomainDigest -and
        [OperationsBlueprint.StrictRfc3339]::TryParse([string]$proof.attributeSnapshotAt, [ref]$attributeSnapshotAt) -and
        $attributeSnapshotAt -ge $AuthorizedAt -and $attributeSnapshotAt -le $StartedAt -and
        [OperationsBlueprint.StrictRfc3339]::TryParse([string]$proof.proofIssuedAt, [ref]$proofIssuedAt) -and
        [OperationsBlueprint.StrictRfc3339]::TryParse([string]$proof.proofExpiresAt, [ref]$proofExpiresAt) -and
        [OperationsBlueprint.StrictRfc3339]::TryParse([string]$proof.proofRevocationCheckedAt, [ref]$proofRevocationCheckedAt) -and
        [OperationsBlueprint.StrictRfc3339]::TryParse([string]$ProductionEvidence.admission.admittedAt, [ref]$productionEvidenceAdmittedAt) -and
        [OperationsBlueprint.StrictRfc3339]::TryParse([string]$SentimentEvidence.admission.admittedAt, [ref]$sentimentEvidenceAdmittedAt) -and
        [OperationsBlueprint.StrictRfc3339]::TryParse([string]$PilotEvidenceRelease.releasedAt, [ref]$pilotEvidenceReleasedAt) -and
        [OperationsBlueprint.StrictRfc3339]::TryParse([string]$FinalVerdict.immutableAt, [ref]$finalVerdictImmutableAt) -and
        $proofIssuedAt -ge $CompletedAt -and
        $proofIssuedAt -lt $productionEvidenceAdmittedAt -and
        $proofIssuedAt -lt $sentimentEvidenceAdmittedAt -and
        $productionEvidenceAdmittedAt -lt $pilotEvidenceReleasedAt -and
        $sentimentEvidenceAdmittedAt -lt $pilotEvidenceReleasedAt -and
        $proofIssuedAt -lt $pilotEvidenceReleasedAt -and
        $pilotEvidenceReleasedAt -lt $finalVerdictImmutableAt -and $finalVerdictImmutableAt -le $EvaluationTime -and
        $proofIssuedAt -le $proofRevocationCheckedAt -and
        $proofRevocationCheckedAt -le $EvaluationTime -and $proofExpiresAt -gt $EvaluationTime -and
        [string]$proof.proofIssuerPrincipalId -cmatch '^private://canonical-principals/sha256/[0-9a-f]{64}$' -and
        [string]$proof.proofRevocationStatus -ceq 'NOT_REVOKED' -and
        [string]$proof.proofRevocationEvidenceRef -cmatch '^private://\S+$' -and
        (Test-Sha256Token $proof.proofRevocationEvidenceDigest) -and
        [string]$proof.protectedProofRef -cmatch '^private://\S+$' -and
        (Test-Sha256Token $proof.protectedProofDigest) -and
        [string]$proof.protectedProofStatus -ceq 'VERIFIED'

    $targetCountValid = ($PilotPopulationPlan.targetCount -is [int] -or $PilotPopulationPlan.targetCount -is [long]) -and
        [int64]$PilotPopulationPlan.targetCount -gt 0
    $respondentCountValid = ($SentimentDistribution.unitCount -is [int] -or $SentimentDistribution.unitCount -is [long]) -and
        [int64]$SentimentDistribution.unitCount -gt 0
    if ($targetCountValid -and $respondentCountValid) {
        $metadataValid = $metadataValid -and
            ($proof.plannedCount -is [int] -or $proof.plannedCount -is [long]) -and
            ($proof.enrolledCount -is [int] -or $proof.enrolledCount -is [long]) -and
            ($proof.completedCount -is [int] -or $proof.completedCount -is [long]) -and
            ($proof.respondentCount -is [int] -or $proof.respondentCount -is [long]) -and
            [int64]$proof.plannedCount -eq [int64]$PilotPopulationPlan.targetCount -and
            [int64]$proof.enrolledCount -eq [int64]$PilotPopulationPlan.targetCount -and
            [int64]$proof.completedCount -eq [int64]$PilotPopulationPlan.targetCount -and
            [int64]$proof.respondentCount -eq [int64]$SentimentDistribution.unitCount -and
            [int64]$proof.respondentCount -le [int64]$proof.completedCount
    }
    else { $metadataValid = $false }
    foreach ($digestField in @(
        'plannedPopulationDigest','enrolledPopulationDigest','completedPopulationDigest',
        'respondentPopulationDigest','completedUnitSetDigest','respondentUnitSetDigest',
        'productionRepresentationDigest','sentimentRepresentationDigest','selectionProofDigest',
        'enrollmentSubsetProofDigest','completionSubsetProofDigest','respondentSubsetProofDigest',
        'attributePartitionProofDigest','proofSubjectDigest'
    )) {
        if (-not (Test-Sha256Token $proof.$digestField)) { $metadataValid = $false }
    }
    $metadataValid = $metadataValid -and
        [string]$proof.plannedPopulationDigest -ceq [string]$proof.enrolledPopulationDigest -and
        [string]$proof.enrolledPopulationDigest -ceq [string]$proof.completedPopulationDigest -and
        [string]$proof.completedUnitSetDigest -ceq [string](Get-PilotDistributionUnitSetDigest -Distribution $ProductionDistribution) -and
        [string]$proof.respondentUnitSetDigest -ceq [string](Get-PilotDistributionUnitSetDigest -Distribution $SentimentDistribution) -and
        [string]$proof.productionRepresentationDigest -ceq [string](Get-CanonicalPayloadDigest -Payload ([pscustomobject]$productionRepresentationBase)) -and
        [string]$proof.sentimentRepresentationDigest -ceq [string](Get-CanonicalPayloadDigest -Payload ([pscustomobject]$sentimentRepresentationBase)) -and
        [string]$SentimentRepresentation.parentProductionEvidenceRef -ceq [string]$ProductionEvidence.recordId -and
        [string]$SentimentRepresentation.parentProductionEvidenceDigest -ceq [string]$ProductionEvidence.contentDigest -and
        [string]$ProductionDistribution.sourceEvidenceRef -ceq [string]$ProductionEvidence.recordId -and
        [string]$ProductionDistribution.sourceEvidenceDigest -ceq [string]$ProductionEvidence.contentDigest -and
        [string]$SentimentDistribution.sourceEvidenceRef -ceq [string]$SentimentEvidence.recordId -and
        [string]$SentimentDistribution.sourceEvidenceDigest -ceq [string]$SentimentEvidence.contentDigest -and
        @($PilotEvidenceRelease.memberRecordIds) -ccontains [string]$ProductionEvidence.recordId -and
        @($PilotEvidenceRelease.memberRecordIds) -ccontains [string]$SentimentEvidence.recordId -and
        @($PilotEvidenceRelease.memberRecordIds) -ccontains [string]$ProductionDistribution.recordId -and
        @($PilotEvidenceRelease.memberRecordIds) -ccontains [string]$SentimentDistribution.recordId

    $proofRefs = [System.Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal)
    $proofDigests = [System.Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal)
    foreach ($proofRefField in @(
        'selectionProofRef','enrollmentSubsetProofRef','completionSubsetProofRef',
        'respondentSubsetProofRef','attributePartitionProofRef','protectedProofRef','proofRevocationEvidenceRef'
    )) {
        if ([string]$proof.$proofRefField -cnotmatch '^private://\S+$' -or
            -not $proofRefs.Add([string]$proof.$proofRefField)) { $metadataValid = $false }
    }
    foreach ($proofDigestField in @(
        'selectionProofDigest','enrollmentSubsetProofDigest','completionSubsetProofDigest',
        'respondentSubsetProofDigest','attributePartitionProofDigest','protectedProofDigest',
        'proofRevocationEvidenceDigest'
    )) {
        if (-not (Test-Sha256Token $proof.$proofDigestField) -or
            -not $proofDigests.Add([string]$proof.$proofDigestField)) { $metadataValid = $false }
    }

    $expectedDistributions = @($ProductionDistribution, $SentimentDistribution)
    $windowBindings = @($proof.distributionWindowBindings)
    $windowBindingRefs = [System.Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal)
    $windowProofValid = $proof.distributionWindowBindings -is [System.Collections.IList] -and
        $windowBindings.Count -eq $expectedDistributions.Count
    [string[]]$windowBindingOrder = @($windowBindings | ForEach-Object { [string]$_.distributionRef })
    [string[]]$sortedWindowBindingOrder = @($windowBindingOrder)
    if ($sortedWindowBindingOrder.Count -gt 1) { [Array]::Sort($sortedWindowBindingOrder, [StringComparer]::Ordinal) }
    $windowProofValid = $windowProofValid -and (Test-CanonicalValueEqual $windowBindingOrder $sortedWindowBindingOrder)
    $productionFloor = $Phase0TestPlan.samplingFloors.PSObject.Properties['production-pilot'].Value
    $minimumEvidenceDays = if ($productionFloor -is [pscustomobject] -and
        ($productionFloor.minEvidenceDays -is [int] -or $productionFloor.minEvidenceDays -is [long]) -and
        [int64]$productionFloor.minEvidenceDays -gt 0) { [int64]$productionFloor.minEvidenceDays } else { 0 }
    foreach ($distribution in $expectedDistributions) {
        $matches = @($windowBindings | Where-Object { [string]$_.distributionRef -ceq [string]$distribution.recordId })
        if ($matches.Count -ne 1) { $windowProofValid = $false; continue }
        $binding = $matches[0]
        $bindingFields = @('distributionRef','testClass','unitSetDigest','acceptedWindowSetDigest','perUnitAcceptedWindows')
        Test-RequiredProperties -Object $binding -Names $bindingFields -Context 'pilot accepted-window binding' -Errors $Errors
        Test-AllowedProperties -Object $binding -Names $bindingFields -Context 'pilot accepted-window binding' -Errors $Errors
        if (-not $windowBindingRefs.Add([string]$binding.distributionRef) -or
            [string]$binding.testClass -cne [string]$distribution.testClass -or
            [string]$binding.unitSetDigest -cne [string](Get-PilotDistributionUnitSetDigest -Distribution $distribution)) {
            $windowProofValid = $false
        }
        $windowRows = @($binding.perUnitAcceptedWindows)
        $runRows = @($distribution.perUnitRunCounts)
        $windowByUnit = [System.Collections.Generic.Dictionary[string,object]]::new([StringComparer]::Ordinal)
        $rowProjection = New-Object System.Collections.ArrayList
        [System.Numerics.BigInteger]$acceptedDateTotal = [System.Numerics.BigInteger]::Zero
        if ($binding.perUnitAcceptedWindows -isnot [System.Collections.IList] -or $windowRows.Count -ne $runRows.Count) {
            $windowProofValid = $false
        }
        foreach ($windowRow in $windowRows) {
            $rowFields = @('unitRef','acceptedDates','acceptedWindowDigest')
            if ($windowRow -isnot [pscustomobject]) { $windowProofValid = $false; continue }
            Test-RequiredProperties -Object $windowRow -Names $rowFields -Context 'pilot per-unit accepted-window proof' -Errors $Errors
            Test-AllowedProperties -Object $windowRow -Names $rowFields -Context 'pilot per-unit accepted-window proof' -Errors $Errors
            $unitRef = [string]$windowRow.unitRef
            $dates = @($windowRow.acceptedDates | ForEach-Object { [string]$_ })
            [string[]]$sortedDates = @($dates)
            if ($sortedDates.Count -gt 1) { [Array]::Sort($sortedDates, [StringComparer]::Ordinal) }
            $datesValid = $windowRow.acceptedDates -is [System.Collections.IList] -and
                $dates.Count -gt 0 -and (Test-CanonicalValueEqual $dates $sortedDates) -and
                @($dates | Group-Object -CaseSensitive | Where-Object Count -gt 1).Count -eq 0
            foreach ($acceptedDate in $dates) {
                [DateTimeOffset]$parsedDate = [DateTimeOffset]::MinValue
                if (-not [OperationsBlueprint.StrictIsoDate]::TryParse($acceptedDate, [ref]$parsedDate) -or
                    $parsedDate.UtcDateTime.Date -lt $StartedAt.UtcDateTime.Date -or
                    $parsedDate.UtcDateTime.Date -gt $CompletedAt.UtcDateTime.Date) { $datesValid = $false }
            }
            $runMatches = @($runRows | Where-Object { [string]$_.unitRef -ceq $unitRef })
            if ([string]$unitRef -cnotmatch '^private://fleet-units/sha256/[0-9a-f]{64}$' -or
                $windowByUnit.ContainsKey($unitRef) -or $runMatches.Count -ne 1 -or
                -not $datesValid -or $dates.Count -ne [int64]$runMatches[0].acceptedRunCount -or
                ([string]$distribution.testClass -ceq 'production-pilot' -and
                 ($minimumEvidenceDays -le 0 -or $dates.Count -lt $minimumEvidenceDays))) {
                $windowProofValid = $false
            }
            else { $windowByUnit.Add($unitRef, $windowRow) }
            $rowSubject = [pscustomobject][ordered]@{ unitRef = $unitRef; acceptedDates = @($dates) }
            if ([string]$windowRow.acceptedWindowDigest -cne [string](Get-CanonicalPayloadDigest -Payload $rowSubject)) {
                $windowProofValid = $false
            }
            [void]$rowProjection.Add([pscustomobject][ordered]@{
                unitRef = $unitRef
                acceptedDates = @($dates)
                acceptedWindowDigest = [string]$windowRow.acceptedWindowDigest
            })
            $acceptedDateTotal += [System.Numerics.BigInteger]$dates.Count
        }
        [string[]]$orderedUnitRefs = @($windowByUnit.Keys)
        if ($orderedUnitRefs.Count -gt 1) { [Array]::Sort($orderedUnitRefs, [StringComparer]::Ordinal) }
        $orderedRows = @($orderedUnitRefs | ForEach-Object { $windowByUnit[[string]$_] })
        if (-not (Test-CanonicalValueEqual @($windowRows) $orderedRows) -or
            [string]$binding.acceptedWindowSetDigest -cne [string](Get-CanonicalPayloadDigest -Payload @($rowProjection)) -or
            $acceptedDateTotal -ne [System.Numerics.BigInteger][int64]$distribution.runCount) {
            $windowProofValid = $false
        }
    }

    $metadataValid = $metadataValid -and $windowProofValid -and
        [string]$proof.proofSubjectDigest -ceq [string](Get-PilotParticipantProofSubjectDigest -Proof $proof)
    if (-not $metadataValid -or $Errors.Count -gt $initialErrorCount) {
        Add-BlueprintError -Errors $Errors -Code 'PILOT_PARTICIPANT_COMMITMENT_INVALID' -Message 'Pilot participant commitments, protected subset/partition bindings, attribute snapshot, or per-unit accepted-day windows are incomplete, replayed, stale, or inconsistent.'
    }
    if ($ValidationProfile -ceq 'PRODUCTION') {
        Add-BlueprintError -Errors $Errors -Code 'PILOT_PRIVATE_PARTICIPANT_PROOF_UNVERIFIED' -Message 'The public validator cannot authenticate protected participant membership, source-population, HR/directory attributes, subset, partition, pseudonym-domain, issuer, or revocation proof bytes.'
    }
    return $metadataValid -and $Errors.Count -eq $initialErrorCount
}

function Test-PilotCompletionRepresentationProof {
    param(
        [AllowNull()]$Representation,
        [AllowNull()]$PilotPopulationPlan,
        [Parameter(Mandatory = $true)][AllowEmptyString()][string]$PilotPopulationPlanRef,
        [AllowNull()]$CoverageEvidence,
        [AllowNull()]$ProductionDistribution,
        [AllowNull()]$ProductionFloor,
        [Parameter(Mandatory = $true)][AllowEmptyCollection()][System.Collections.ArrayList]$Errors
    )

    $initialErrorCount = $Errors.Count
    $representationFields = @(
        'pilotPopulationPlanRef','targetCount','selectionDimensions','volunteerOnly','dimensions','populationProof'
    )
    if ($Representation -isnot [pscustomobject] -or $PilotPopulationPlan -isnot [pscustomobject]) {
        Add-BlueprintError -Errors $Errors -Code 'PILOT_REPRESENTATION_PROOF_INVALID' -Message 'Pilot coverage evidence requires one closed representation proof for the exact frozen pilot population plan.'
        return $false
    }
    Test-RequiredProperties -Object $Representation -Names $representationFields -Context 'pilot representation proof' -Errors $Errors
    Test-AllowedProperties -Object $Representation -Names $representationFields -Context 'pilot representation proof' -Errors $Errors
    Test-RequiredProperties -Object $PilotPopulationPlan -Names @(
        'targetCount','selectionDimensions','privacyOwner','volunteerOnly'
    ) -Context 'pilot population plan' -Errors $Errors

    $targetCountValid = ($PilotPopulationPlan.targetCount -is [int] -or $PilotPopulationPlan.targetCount -is [long]) -and
        [int64]$PilotPopulationPlan.targetCount -gt 0
    $targetCount = if ($targetCountValid) { [int64]$PilotPopulationPlan.targetCount } else { [int64]0 }
    $selectionDimensions = @($PilotPopulationPlan.selectionDimensions)
    $representationDimensions = @($Representation.selectionDimensions)
    $dimensionRows = @($Representation.dimensions)
    $coverageObservedUnits = if ($null -ne $CoverageEvidence -and
        ($CoverageEvidence.coverage.observedUnits -is [int] -or $CoverageEvidence.coverage.observedUnits -is [long])) {
        [int64]$CoverageEvidence.coverage.observedUnits
    }
    else { [int64]-1 }
    $distributionUnitCount = if ($null -ne $ProductionDistribution -and
        ($ProductionDistribution.unitCount -is [int] -or $ProductionDistribution.unitCount -is [long])) {
        [int64]$ProductionDistribution.unitCount
    }
    else { [int64]-1 }

    $selectionSet = [System.Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal)
    $selectionValid = $PilotPopulationPlan.selectionDimensions -is [System.Collections.IList] -and
        $Representation.selectionDimensions -is [System.Collections.IList] -and
        $selectionDimensions.Count -ge 3 -and
        (Test-CanonicalValueEqual $selectionDimensions $representationDimensions)
    foreach ($dimensionName in $selectionDimensions) {
        if ($dimensionName -isnot [string] -or [string]::IsNullOrWhiteSpace([string]$dimensionName) -or
            -not $selectionSet.Add([string]$dimensionName)) { $selectionValid = $false }
    }
    foreach ($requiredDimension in @('persona','region','work-pattern')) {
        if (-not $selectionSet.Contains($requiredDimension)) { $selectionValid = $false }
    }
    if (-not $targetCountValid -or -not $selectionValid -or
        ($Representation.targetCount -isnot [int] -and $Representation.targetCount -isnot [long]) -or
        [int64]$Representation.targetCount -ne $targetCount -or
        $PilotPopulationPlan.volunteerOnly -ne $false -or $Representation.volunteerOnly -ne $false -or
        [string]$Representation.pilotPopulationPlanRef -cne $PilotPopulationPlanRef -or
        $coverageObservedUnits -ne $targetCount -or $distributionUnitCount -ne $targetCount) {
        Add-BlueprintError -Errors $Errors -Code 'PILOT_REPRESENTATION_PLAN_MISMATCH' -Message 'Pilot representation must bind the exact target count, ordered selection dimensions, non-volunteer population plan, coverage count, and production-pilot unit count.'
    }

    $rowNames = @($dimensionRows | ForEach-Object { [string]$_.dimension })
    if ($Representation.dimensions -isnot [System.Collections.IList] -or
        $dimensionRows.Count -ne $selectionDimensions.Count -or
        -not (Test-CanonicalValueEqual $rowNames $selectionDimensions)) {
        Add-BlueprintError -Errors $Errors -Code 'PILOT_REPRESENTATION_DIMENSION_MISMATCH' -Message 'Pilot representation requires exactly one ordered dimension row for every frozen selection dimension.'
    }

    $dimensionSet = [System.Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal)
    foreach ($dimensionRow in $dimensionRows) {
        $dimensionFields = @('dimension','plannedCount','observedCount','nonmissingCount','categories')
        if ($dimensionRow -isnot [pscustomobject]) {
            Add-BlueprintError -Errors $Errors -Code 'PILOT_REPRESENTATION_DIMENSION_MISMATCH' -Message 'Every pilot representation dimension must be a closed structured row.'
            continue
        }
        Test-RequiredProperties -Object $dimensionRow -Names $dimensionFields -Context 'pilot representation dimension' -Errors $Errors
        Test-AllowedProperties -Object $dimensionRow -Names $dimensionFields -Context 'pilot representation dimension' -Errors $Errors
        $dimensionName = [string]$dimensionRow.dimension
        $countsValid = ($dimensionRow.plannedCount -is [int] -or $dimensionRow.plannedCount -is [long]) -and
            ($dimensionRow.observedCount -is [int] -or $dimensionRow.observedCount -is [long]) -and
            ($dimensionRow.nonmissingCount -is [int] -or $dimensionRow.nonmissingCount -is [long])
        [int64]$plannedCount = if ($countsValid) { [int64]$dimensionRow.plannedCount } else { -1 }
        [int64]$observedCount = if ($countsValid) { [int64]$dimensionRow.observedCount } else { -1 }
        [int64]$nonmissingCount = if ($countsValid) { [int64]$dimensionRow.nonmissingCount } else { -1 }
        if (-not $selectionSet.Contains($dimensionName) -or -not $dimensionSet.Add($dimensionName) -or
            -not $countsValid -or $plannedCount -ne $targetCount -or
            $observedCount -ne $targetCount -or $nonmissingCount -ne $observedCount) {
            Add-BlueprintError -Errors $Errors -Code 'PILOT_REPRESENTATION_DIMENSION_MISMATCH' -Message "Pilot representation dimension $dimensionName does not reconcile exact planned, observed, and nonmissing population counts."
        }

        $categoryRows = @($dimensionRow.categories)
        $categorySet = [System.Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal)
        [System.Numerics.BigInteger]$plannedTotal = [System.Numerics.BigInteger]::Zero
        [System.Numerics.BigInteger]$observedTotal = [System.Numerics.BigInteger]::Zero
        [System.Numerics.BigInteger]$nonmissingTotal = [System.Numerics.BigInteger]::Zero
        $categoriesValid = $dimensionRow.categories -is [System.Collections.IList] -and $categoryRows.Count -gt 0
        $categoryByName = [System.Collections.Generic.Dictionary[string,object]]::new([StringComparer]::Ordinal)
        foreach ($categoryRow in $categoryRows) {
            $categoryFields = @('category','plannedCount','observedCount','nonmissingCount','categoryPopulationDigest')
            if ($categoryRow -isnot [pscustomobject]) { $categoriesValid = $false; continue }
            Test-RequiredProperties -Object $categoryRow -Names $categoryFields -Context "pilot representation $dimensionName category" -Errors $Errors
            Test-AllowedProperties -Object $categoryRow -Names $categoryFields -Context "pilot representation $dimensionName category" -Errors $Errors
            $categoryName = [string]$categoryRow.category
            $categoryCountsValid = ($categoryRow.plannedCount -is [int] -or $categoryRow.plannedCount -is [long]) -and
                ($categoryRow.observedCount -is [int] -or $categoryRow.observedCount -is [long]) -and
                ($categoryRow.nonmissingCount -is [int] -or $categoryRow.nonmissingCount -is [long])
            if (-not (Test-NonBlankString $categoryName) -or -not $categorySet.Add($categoryName) -or
                -not $categoryCountsValid -or -not (Test-Sha256Token $categoryRow.categoryPopulationDigest)) {
                $categoriesValid = $false
                continue
            }
            [int64]$categoryPlanned = [int64]$categoryRow.plannedCount
            [int64]$categoryObserved = [int64]$categoryRow.observedCount
            [int64]$categoryNonmissing = [int64]$categoryRow.nonmissingCount
            if ($categoryPlanned -lt 1 -or $categoryObserved -lt $categoryPlanned -or
                $categoryNonmissing -ne $categoryObserved) { $categoriesValid = $false }
            $plannedTotal += [System.Numerics.BigInteger]$categoryPlanned
            $observedTotal += [System.Numerics.BigInteger]$categoryObserved
            $nonmissingTotal += [System.Numerics.BigInteger]$categoryNonmissing
            $categoryByName.Add($categoryName, $categoryRow)
        }
        if ($plannedTotal -ne [System.Numerics.BigInteger]$plannedCount -or
            $observedTotal -ne [System.Numerics.BigInteger]$observedCount -or
            $nonmissingTotal -ne [System.Numerics.BigInteger]$nonmissingCount) {
            $categoriesValid = $false
        }

        $quotaPropertyName = switch ($dimensionName) {
            'work-pattern' { 'workPattern' }
            'persona' { 'persona' }
            'region' { 'region' }
            default { $null }
        }
        if ($null -ne $quotaPropertyName) {
            $quotaProperty = if ($ProductionFloor -is [pscustomobject] -and
                $ProductionFloor.stratumQuotas -is [pscustomobject]) {
                $ProductionFloor.stratumQuotas.PSObject.Properties[$quotaPropertyName]
            }
            else { $null }
            $quotaMap = if ($null -ne $quotaProperty -and $quotaProperty.Value -is [pscustomobject]) {
                $quotaProperty.Value
            }
            else { $null }
            $quotaNames = @(if ($null -ne $quotaMap) { $quotaMap.PSObject.Properties.Name })
            if ($null -eq $quotaMap -or $categoryRows.Count -ne $quotaNames.Count) {
                $categoriesValid = $false
            }
            else {
                foreach ($quota in @($quotaMap.PSObject.Properties)) {
                    if (-not $categoryByName.ContainsKey([string]$quota.Name) -or
                        ($quota.Value -isnot [int] -and $quota.Value -isnot [long]) -or
                        [int64]$quota.Value -lt 1 -or
                        [int64]$categoryByName[[string]$quota.Name].plannedCount -lt [int64]$quota.Value -or
                        [int64]$categoryByName[[string]$quota.Name].observedCount -lt [int64]$quota.Value) {
                        $categoriesValid = $false
                    }
                }
            }
        }
        if (-not $categoriesValid) {
            Add-BlueprintError -Errors $Errors -Code 'PILOT_REPRESENTATION_CATEGORY_MISMATCH' -Message "Pilot representation dimension $dimensionName lacks unique categories whose planned, observed, and nonmissing counts reconcile to the frozen quotas and dimension totals."
        }
    }
    return $Errors.Count -eq $initialErrorCount
}

function Test-PilotSentimentRepresentationProof {
    param(
        [AllowNull()]$Representation,
        [AllowNull()]$PilotPopulationPlan,
        [Parameter(Mandatory = $true)][AllowEmptyString()][string]$PilotPopulationPlanRef,
        [AllowNull()]$SentimentDistribution,
        [AllowNull()]$SentimentFloor,
        [Parameter(Mandatory = $true)][AllowEmptyCollection()][System.Collections.ArrayList]$Errors
    )

    $initialErrorCount = $Errors.Count
    $representationFields = @(
        'pilotPopulationPlanRef','targetCount','selectionDimensions','volunteerOnly','dimensions','populationProof',
        'parentProductionEvidenceRef','parentProductionEvidenceDigest'
    )
    if ($Representation -isnot [pscustomobject] -or $PilotPopulationPlan -isnot [pscustomobject] -or
        $SentimentDistribution -isnot [pscustomobject] -or $SentimentFloor -isnot [pscustomobject]) {
        Add-BlueprintError -Errors $Errors -Code 'PILOT_SENTIMENT_REPRESENTATION_INVALID' -Message 'Sentiment evidence requires one closed observed-representation proof against the exact pilot population and frozen quotas.'
        return $false
    }
    Test-RequiredProperties -Object $Representation -Names $representationFields -Context 'pilot sentiment representation proof' -Errors $Errors
    Test-AllowedProperties -Object $Representation -Names $representationFields -Context 'pilot sentiment representation proof' -Errors $Errors

    $targetValid = ($PilotPopulationPlan.targetCount -is [int] -or $PilotPopulationPlan.targetCount -is [long]) -and
        [int64]$PilotPopulationPlan.targetCount -gt 0
    $responseCountValid = ($SentimentDistribution.unitCount -is [int] -or $SentimentDistribution.unitCount -is [long]) -and
        [int64]$SentimentDistribution.unitCount -gt 0
    [int64]$targetCount = if ($targetValid) { [int64]$PilotPopulationPlan.targetCount } else { 0 }
    [int64]$responseCount = if ($responseCountValid) { [int64]$SentimentDistribution.unitCount } else { 0 }
    $selectionDimensions = @($PilotPopulationPlan.selectionDimensions)
    $representationDimensions = @($Representation.selectionDimensions)
    $dimensionRows = @($Representation.dimensions)
    $selectionSet = [System.Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal)
    $selectionValid = $PilotPopulationPlan.selectionDimensions -is [System.Collections.IList] -and
        $Representation.selectionDimensions -is [System.Collections.IList] -and
        $selectionDimensions.Count -ge 3 -and
        (Test-CanonicalValueEqual $selectionDimensions $representationDimensions)
    foreach ($dimensionName in $selectionDimensions) {
        if (-not (Test-NonBlankString $dimensionName) -or -not $selectionSet.Add([string]$dimensionName)) {
            $selectionValid = $false
        }
    }
    foreach ($requiredDimension in @('persona','region','work-pattern')) {
        if (-not $selectionSet.Contains($requiredDimension)) { $selectionValid = $false }
    }
    if (-not $targetValid -or -not $responseCountValid -or -not $selectionValid -or
        ($Representation.targetCount -isnot [int] -and $Representation.targetCount -isnot [long]) -or
        [int64]$Representation.targetCount -ne $targetCount -or
        [string]$Representation.pilotPopulationPlanRef -cne $PilotPopulationPlanRef -or
        $PilotPopulationPlan.volunteerOnly -ne $false -or $Representation.volunteerOnly -ne $false) {
        Add-BlueprintError -Errors $Errors -Code 'PILOT_SENTIMENT_REPRESENTATION_INVALID' -Message 'Sentiment representation does not bind the exact non-volunteer population target and ordered persona, region, and work-pattern dimensions.'
    }

    $rowNames = @($dimensionRows | ForEach-Object { [string]$_.dimension })
    if ($Representation.dimensions -isnot [System.Collections.IList] -or
        $dimensionRows.Count -ne $selectionDimensions.Count -or
        -not (Test-CanonicalValueEqual $rowNames $selectionDimensions)) {
        Add-BlueprintError -Errors $Errors -Code 'PILOT_SENTIMENT_REPRESENTATION_INVALID' -Message 'Sentiment representation requires exactly one ordered row for every frozen selection dimension.'
    }

    $dimensionSet = [System.Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal)
    foreach ($dimensionRow in $dimensionRows) {
        $dimensionFields = @('dimension','plannedCount','observedCount','nonmissingCount','categories')
        if ($dimensionRow -isnot [pscustomobject]) {
            Add-BlueprintError -Errors $Errors -Code 'PILOT_SENTIMENT_REPRESENTATION_INVALID' -Message 'Every sentiment representation dimension must be a closed structured row.'
            continue
        }
        Test-RequiredProperties -Object $dimensionRow -Names $dimensionFields -Context 'pilot sentiment representation dimension' -Errors $Errors
        Test-AllowedProperties -Object $dimensionRow -Names $dimensionFields -Context 'pilot sentiment representation dimension' -Errors $Errors
        $dimensionName = [string]$dimensionRow.dimension
        $countsValid = ($dimensionRow.plannedCount -is [int] -or $dimensionRow.plannedCount -is [long]) -and
            ($dimensionRow.observedCount -is [int] -or $dimensionRow.observedCount -is [long]) -and
            ($dimensionRow.nonmissingCount -is [int] -or $dimensionRow.nonmissingCount -is [long])
        if (-not $selectionSet.Contains($dimensionName) -or -not $dimensionSet.Add($dimensionName) -or
            -not $countsValid -or [int64]$dimensionRow.plannedCount -ne $targetCount -or
            [int64]$dimensionRow.observedCount -ne $responseCount -or
            [int64]$dimensionRow.nonmissingCount -ne $responseCount) {
            Add-BlueprintError -Errors $Errors -Code 'PILOT_SENTIMENT_REPRESENTATION_INVALID' -Message "Sentiment representation dimension $dimensionName does not reconcile the exact planned population and nonmissing response count."
            continue
        }

        $quotaPropertyName = switch ($dimensionName) {
            'work-pattern' { 'workPattern' }
            'persona' { 'persona' }
            'region' { 'region' }
            default { $null }
        }
        $quotaProperty = if ($null -ne $quotaPropertyName -and $SentimentFloor.stratumQuotas -is [pscustomobject]) {
            $SentimentFloor.stratumQuotas.PSObject.Properties[$quotaPropertyName]
        }
        else { $null }
        $quotaMap = if ($null -ne $quotaProperty -and $quotaProperty.Value -is [pscustomobject]) {
            $quotaProperty.Value
        }
        else { $null }
        $categoryRows = @($dimensionRow.categories)
        $categoryByName = [System.Collections.Generic.Dictionary[string,object]]::new([StringComparer]::Ordinal)
        [System.Numerics.BigInteger]$plannedTotal = [System.Numerics.BigInteger]::Zero
        [System.Numerics.BigInteger]$observedTotal = [System.Numerics.BigInteger]::Zero
        [System.Numerics.BigInteger]$nonmissingTotal = [System.Numerics.BigInteger]::Zero
        $categoriesValid = $dimensionRow.categories -is [System.Collections.IList] -and $null -ne $quotaMap -and
            $categoryRows.Count -eq @($quotaMap.PSObject.Properties).Count
        foreach ($categoryRow in $categoryRows) {
            $categoryFields = @('category','plannedCount','observedCount','nonmissingCount','categoryPopulationDigest')
            if ($categoryRow -isnot [pscustomobject]) { $categoriesValid = $false; continue }
            Test-RequiredProperties -Object $categoryRow -Names $categoryFields -Context "pilot sentiment $dimensionName category" -Errors $Errors
            Test-AllowedProperties -Object $categoryRow -Names $categoryFields -Context "pilot sentiment $dimensionName category" -Errors $Errors
            $categoryName = [string]$categoryRow.category
            $categoryCountsValid = ($categoryRow.plannedCount -is [int] -or $categoryRow.plannedCount -is [long]) -and
                ($categoryRow.observedCount -is [int] -or $categoryRow.observedCount -is [long]) -and
                ($categoryRow.nonmissingCount -is [int] -or $categoryRow.nonmissingCount -is [long])
            if (-not (Test-NonBlankString $categoryName) -or $categoryByName.ContainsKey($categoryName) -or
                -not $categoryCountsValid -or -not (Test-Sha256Token $categoryRow.categoryPopulationDigest)) {
                $categoriesValid = $false
                continue
            }
            $categoryByName.Add($categoryName, $categoryRow)
            [int64]$categoryPlanned = [int64]$categoryRow.plannedCount
            [int64]$categoryObserved = [int64]$categoryRow.observedCount
            [int64]$categoryNonmissing = [int64]$categoryRow.nonmissingCount
            if ($categoryPlanned -lt $categoryObserved -or $categoryObserved -lt 0 -or
                $categoryNonmissing -ne $categoryObserved) { $categoriesValid = $false }
            $plannedTotal += [System.Numerics.BigInteger]$categoryPlanned
            $observedTotal += [System.Numerics.BigInteger]$categoryObserved
            $nonmissingTotal += [System.Numerics.BigInteger]$categoryNonmissing
        }
        if ($plannedTotal -ne [System.Numerics.BigInteger]$targetCount -or
            $observedTotal -ne [System.Numerics.BigInteger]$responseCount -or
            $nonmissingTotal -ne [System.Numerics.BigInteger]$responseCount) {
            $categoriesValid = $false
        }
        if ($null -ne $quotaMap) {
            foreach ($quota in @($quotaMap.PSObject.Properties)) {
                if (-not $categoryByName.ContainsKey([string]$quota.Name) -or
                    ($quota.Value -isnot [int] -and $quota.Value -isnot [long]) -or
                    [int64]$quota.Value -lt 1 -or
                    [int64]$categoryByName[[string]$quota.Name].observedCount -lt [int64]$quota.Value) {
                    $categoriesValid = $false
                }
            }
        }
        if (-not $categoriesValid) {
            Add-BlueprintError -Errors $Errors -Code 'PILOT_SENTIMENT_REPRESENTATION_INVALID' -Message "Sentiment representation dimension $dimensionName does not prove exact response totals and every frozen observed stratum quota."
        }
    }
    return $Errors.Count -eq $initialErrorCount
}

function Test-PilotPhase4DistributionSemantics {
    param(
        [AllowNull()]$Distribution,
        [Parameter(Mandatory = $true)][ValidateSet('production-pilot','sentiment')][string]$ExpectedClass,
        [Parameter(Mandatory = $true)]$RecordMap,
        [AllowNull()]$Phase0TestPlan,
        [AllowNull()]$PilotEvidenceRelease,
        [AllowNull()]$ExpectedEvidenceRecord,
        [AllowNull()]$PilotPopulationPlan,
        [AllowNull()][string]$PilotPopulationPlanRef,
        [AllowNull()]$Manifest,
        [AllowNull()]$FrozenThresholdPolicy,
        [Parameter(Mandatory = $true)][DateTimeOffset]$EvaluationTime,
        [Parameter(Mandatory = $true)][DateTimeOffset]$AuthorizedAt,
        [Parameter(Mandatory = $true)][DateTimeOffset]$StartedAt,
        [Parameter(Mandatory = $true)][DateTimeOffset]$CompletedAt,
        [Parameter(Mandatory = $true)][DateTimeOffset]$FinalImmutableAt,
        [Parameter(Mandatory = $true)][string]$Context,
        [Parameter(Mandatory = $true)][AllowEmptyCollection()][System.Collections.ArrayList]$Errors
    )

    $initialErrorCount = $Errors.Count
    if ($null -eq $Distribution) {
        Add-BlueprintError -Errors $Errors -Code 'PILOT_PHASE4_DISTRIBUTION_INVALID' -Message "$Context does not resolve one exact distribution record."
        return [pscustomobject]@{ Valid = $false; SourceEvidence = $null; Release = $null }
    }
    Test-RequiredProperties -Object $Distribution -Names @(
        'sourceEvidenceRef','sourceEvidenceDigest','sourceEvidenceReleaseRef','sourceEvidenceReleaseSubjectDigest',
        'testRef','testDefinitionDigest','conditionRef','baselineFingerprint','testClass','metricId','unit',
        'statisticDirection','unitCount','runCount','perUnitRunCounts','requiredUnits','requiredRuns',
        'phase0TestPlanRef','phase0TestPlanDigest','samplingFloorPointer','samplingFloorDigest','median',
        'spread','runVariation','coverage','missingResults','outliers','exclusions','samplingFloorStatus',
        'distributionStatus'
    ) -Context $Context -Errors $Errors
    $closure = Test-DistributionSourceEvidenceClosure -Distribution $Distribution -RecordMap $RecordMap `
        -EvaluationTime $EvaluationTime -ExpectedEvidenceRecord $ExpectedEvidenceRecord -Context $Context -Errors $Errors
    if ($null -ne $Phase0TestPlan) {
        [void](Test-DistributionPhase0FloorBinding -Distribution $Distribution -Phase0TestPlan $Phase0TestPlan `
            -ExpectedEvidenceRecord $closure.SourceEvidence -ExpectedTestPlanRef ([string]$Phase0TestPlan.recordId) `
            -Context $Context -Errors $Errors)
    }
    else {
        Add-BlueprintError -Errors $Errors -Code 'PILOT_PHASE4_DISTRIBUTION_INVALID' -Message "$Context cannot bind its Phase 4 definition and sampling floor because the frozen test plan is unresolved."
    }
    Test-DistributionPerUnitRunProof -Distribution $Distribution -Context $Context -Errors $Errors

    if ($null -ne $closure.SourceEvidence) {
        Test-PortableEvidenceAdmissionSemantics -Evidence $closure.SourceEvidence -Distribution $Distribution `
            -Manifest $Manifest -Phase0TestPlan $Phase0TestPlan -ThresholdPolicy $FrozenThresholdPolicy `
            -RecordMap $RecordMap -CurrentRelease $PilotEvidenceRelease -EvaluationTime $EvaluationTime -Errors $Errors
    }
    [DateTimeOffset]$pilotObservedAt = [DateTimeOffset]::MinValue
    [DateTimeOffset]$pilotAdmittedAt = [DateTimeOffset]::MinValue
    [DateTimeOffset]$pilotReleasedAt = [DateTimeOffset]::MinValue
    $pilotWindowValid = $null -ne $closure.SourceEvidence -and $null -ne $PilotEvidenceRelease -and
        [string]$closure.SourceEvidence.admission.mode -ceq 'fresh' -and
        [OperationsBlueprint.StrictRfc3339]::TryParse([string]$closure.SourceEvidence.timestamp, [ref]$pilotObservedAt) -and
        [OperationsBlueprint.StrictRfc3339]::TryParse([string]$closure.SourceEvidence.admission.admittedAt, [ref]$pilotAdmittedAt) -and
        [OperationsBlueprint.StrictRfc3339]::TryParse([string]$PilotEvidenceRelease.releasedAt, [ref]$pilotReleasedAt) -and
        $AuthorizedAt -le $StartedAt -and $StartedAt -le $pilotObservedAt -and
        $pilotObservedAt -le $CompletedAt -and $CompletedAt -lt $pilotAdmittedAt -and
        $pilotAdmittedAt -lt $pilotReleasedAt -and $pilotReleasedAt -lt $FinalImmutableAt -and
        $FinalImmutableAt -le $EvaluationTime
    if (-not $pilotWindowValid) {
        Add-BlueprintError -Errors $Errors -Code 'PILOT_EVIDENCE_WINDOW_INVALID' -Message "$Context observation, post-completion admission, immutable release, or final-verdict chronology is invalid."
    }

    $sameRelease = $null -ne $PilotEvidenceRelease -and $null -ne $closure.Release -and
        [string]$closure.Release.recordId -ceq [string]$PilotEvidenceRelease.recordId -and
        [string]$closure.Release.contentDigest -ceq [string]$PilotEvidenceRelease.contentDigest -and
        [string]$Distribution.sourceEvidenceReleaseRef -ceq [string]$PilotEvidenceRelease.recordId -and
        [string]$Distribution.sourceEvidenceReleaseSubjectDigest -ceq [string]$PilotEvidenceRelease.releaseSubjectDigest -and
        @($PilotEvidenceRelease.conditionRefs) -ccontains [string]$Distribution.conditionRef -and
        [string]$PilotEvidenceRelease.baselineFingerprint -ceq [string]$Distribution.baselineFingerprint
    $floor = $null
    if ($Phase0TestPlan -is [pscustomobject] -and $Phase0TestPlan.samplingFloors -is [pscustomobject]) {
        $floorProperty = $Phase0TestPlan.samplingFloors.PSObject.Properties[$ExpectedClass]
        if ($null -ne $floorProperty -and $floorProperty.Value -is [pscustomobject]) { $floor = $floorProperty.Value }
    }
    $quotaTotalsValid = $floor -is [pscustomobject] -and
        ($floor.minUnits -is [int] -or $floor.minUnits -is [long]) -and
        [int64]$floor.minUnits -gt 0 -and $floor.stratumQuotas -is [pscustomobject]
    if ($quotaTotalsValid) {
        foreach ($quotaDimension in @('persona','region','workPattern')) {
            $quotaDimensionProperty = $floor.stratumQuotas.PSObject.Properties[$quotaDimension]
            if ($null -eq $quotaDimensionProperty -or $quotaDimensionProperty.Value -isnot [pscustomobject] -or
                @($quotaDimensionProperty.Value.PSObject.Properties).Count -eq 0) {
                $quotaTotalsValid = $false
                continue
            }
            [System.Numerics.BigInteger]$quotaTotal = [System.Numerics.BigInteger]::Zero
            foreach ($quota in @($quotaDimensionProperty.Value.PSObject.Properties)) {
                if ($quota.Value -isnot [int] -and $quota.Value -isnot [long]) {
                    $quotaTotalsValid = $false
                    continue
                }
                if ([int64]$quota.Value -lt 1) { $quotaTotalsValid = $false }
                $quotaTotal += [System.Numerics.BigInteger][int64]$quota.Value
            }
            if ($quotaTotal -ne [System.Numerics.BigInteger][int64]$floor.minUnits) {
                $quotaTotalsValid = $false
            }
        }
    }
    $representationFloorValid = $floor -is [pscustomobject] -and
        $floor.representative -eq $true -and $floor.volunteerOnly -eq $false -and
        $quotaTotalsValid
    if ($ExpectedClass -ceq 'production-pilot') {
        $representationFloorValid = $representationFloorValid -and
            ($floor.minEvidenceDays -is [int] -or $floor.minEvidenceDays -is [long]) -and
            [int64]$floor.minEvidenceDays -ge 10
    }
    else {
        $representationFloorValid = $representationFloorValid -and (Test-NumberValue $floor.minResponseRatePct) -and
            [double]$floor.minResponseRatePct -ge 80 -and [double]$floor.minResponseRatePct -le 100
    }

    $coverageValid = $Distribution.coverage -is [pscustomobject]
    if ($coverageValid) {
        Test-RequiredProperties -Object $Distribution.coverage -Names @('expected','observed','percent') -Context "$Context coverage" -Errors $Errors
        Test-AllowedProperties -Object $Distribution.coverage -Names @('expected','observed','percent') -Context "$Context coverage" -Errors $Errors
        $coverageValid = ($Distribution.coverage.expected -is [int] -or $Distribution.coverage.expected -is [long]) -and
            ($Distribution.coverage.observed -is [int] -or $Distribution.coverage.observed -is [long]) -and
            (Test-NumberValue $Distribution.coverage.percent)
    }
    if ($coverageValid) {
        [int64]$expectedUnits = [int64]$Distribution.coverage.expected
        [int64]$observedUnits = [int64]$Distribution.coverage.observed
        [double]$coveragePercent = [double]$Distribution.coverage.percent
        $calculatedPercent = if ($expectedUnits -gt 0) { 100.0 * $observedUnits / $expectedUnits } else { -1.0 }
        $coverageValid = $expectedUnits -gt 0 -and $observedUnits -ge 0 -and $observedUnits -le $expectedUnits -and
            ($Distribution.unitCount -is [int] -or $Distribution.unitCount -is [long]) -and
            [int64]$Distribution.unitCount -eq $observedUnits -and
            [Math]::Abs($coveragePercent - $calculatedPercent) -le 0.01
        if ($PilotPopulationPlan -is [pscustomobject] -and
            ($PilotPopulationPlan.targetCount -is [int] -or $PilotPopulationPlan.targetCount -is [long])) {
            $coverageValid = $coverageValid -and $expectedUnits -eq [int64]$PilotPopulationPlan.targetCount
            if ($ExpectedClass -ceq 'production-pilot') {
                $coverageValid = $coverageValid -and $observedUnits -eq [int64]$PilotPopulationPlan.targetCount
            }
            elseif ($null -ne $floor -and (Test-NumberValue $floor.minResponseRatePct) -and
                (Test-CanonicalJsonRuntimeDomain $floor.minResponseRatePct)) {
                try {
                    $coverageValid = $coverageValid -and
                        ([decimal]$observedUnits * [decimal]100) -ge
                        ([decimal]$floor.minResponseRatePct * [decimal]$expectedUnits)
                }
                catch { $coverageValid = $false }
            }
        }
    }

    $sourceValid = $null -ne $closure.SourceEvidence -and
        [string]$closure.SourceEvidence.schemaVersion -ceq '2.0.1' -and
        [string]$closure.SourceEvidence.recordKind -ceq 'measurement-summary' -and
        [string]$closure.SourceEvidence.provenance -ceq 'T0' -and
        [string]$closure.SourceEvidence.evidenceUse -ceq 'gate-or-verdict' -and
        [string]$closure.SourceEvidence.evidenceReleaseRef -ceq [string]$PilotEvidenceRelease.recordId -and
        [string]$closure.SourceEvidence.coverageStatus -ceq 'PASS' -and
        [string]$closure.SourceEvidence.distributionRef -ceq [string]$Distribution.recordId -and
        [string]$closure.SourceEvidence.testPlanRef -ceq [string]$Phase0TestPlan.recordId
    if ($null -ne $PilotEvidenceRelease -and (Test-ValuePresent $PilotEvidenceRelease.testPackVersion)) {
        $sourceValid = $sourceValid -and [string]$closure.SourceEvidence.testPackVersion -ceq [string]$PilotEvidenceRelease.testPackVersion
    }
    if ($ExpectedClass -ceq 'sentiment') {
        [void](Test-PilotSentimentRepresentationProof -Representation $closure.SourceEvidence.result.representation `
            -PilotPopulationPlan $PilotPopulationPlan -PilotPopulationPlanRef $PilotPopulationPlanRef `
            -SentimentDistribution $Distribution -SentimentFloor $floor -Errors $Errors)
    }

    $shapeValid = [string]$Distribution.testClass -ceq $ExpectedClass -and $sameRelease -and
        $representationFloorValid -and $coverageValid -and $sourceValid -and $pilotWindowValid -and
        [string]$Distribution.samplingFloorStatus -ceq 'PASS' -and
        [string]$Distribution.distributionStatus -ceq 'PASS' -and
        (Test-NonBlankString $Distribution.metricId) -and (Test-NonBlankString $Distribution.unit) -and
        (Test-NumberValue $Distribution.median) -and $Distribution.spread -is [pscustomobject] -and
        $Distribution.runVariation -is [pscustomobject]
    if (-not $shapeValid) {
        Add-BlueprintError -Errors $Errors -Code 'PILOT_PHASE4_DISTRIBUTION_INVALID' -Message "$Context is not a passing, exact-release, exact-floor, representative $ExpectedClass distribution with reconciled coverage and T0 source evidence."
    }
    return [pscustomobject]@{
        Valid = $shapeValid -and $Errors.Count -eq $initialErrorCount
        SourceEvidence = $closure.SourceEvidence
        Release = $closure.Release
        Floor = $floor
    }
}

function Test-FinalVerdictPilotCompletionSemantics {
    param(
        [Parameter(Mandatory = $true)]$Verdict,
        [Parameter(Mandatory = $true)][AllowNull()]$PilotVerdict,
        [Parameter(Mandatory = $true)][AllowNull()]$Manifest,
        [Parameter(Mandatory = $true)][AllowNull()]$Phase0TestPlan,
        [Parameter(Mandatory = $true)][AllowNull()]$FrozenThresholdPolicy,
        [Parameter(Mandatory = $true)]$RecordMap,
        [Parameter(Mandatory = $true)][DateTimeOffset]$EvaluationTime,
        [ValidateSet('TEST','PRODUCTION')][string]$ValidationProfile,
        [AllowNull()]$VerdictIssuanceApprovalValidation,
        [Parameter(Mandatory = $true)][AllowEmptyCollection()][System.Collections.ArrayList]$Errors
    )

    $initialErrorCount = $Errors.Count
    $completion = $Verdict.pilotCompletion
    $completionFields = @(
        'status','pilotEvidenceReleaseRef','coverageEvidenceRef','stopConditionOutcome',
        'startedAt','completedAt','approvedBy','reason','authorityApprovalRef','extensions'
    )
    if ($completion -isnot [pscustomobject]) {
        Add-BlueprintError -Errors $Errors -Code 'PILOT_COMPLETION_INVALID' -Message 'A Phase 5 verdict requires one structured pilotCompletion decision.'
        return [pscustomobject]@{ Valid = $false; PilotEvidenceRelease = $null; CoverageEvidence = $null; PilotNotRequiredApprovalValidation = $null }
    }
    Test-RequiredProperties -Object $completion -Names @('status') -Context 'final verdict pilot completion' -Errors $Errors
    Test-AllowedProperties -Object $completion -Names $completionFields -Context 'final verdict pilot completion' -Errors $Errors

    $pilotEvidenceRelease = $null
    $coverageEvidence = $null
    $pilotNotRequiredApprovalValidation = $null
    if ([string]$completion.status -ceq 'COMPLETED') {
        Test-RequiredProperties -Object $completion -Names @(
            'pilotEvidenceReleaseRef','coverageEvidenceRef','stopConditionOutcome','startedAt','completedAt','approvedBy'
        ) -Context 'completed production pilot' -Errors $Errors
        if ($null -ne $completion.PSObject.Properties['reason'] -or
            $null -ne $completion.PSObject.Properties['authorityApprovalRef'] -or
            $null -eq $PilotVerdict -or [string]$Verdict.pilotAuthorization.status -cne 'AUTHORIZED' -or
            [string]$PilotVerdict.pilotAuthorization.status -cne 'AUTHORIZED') {
            Add-BlueprintError -Errors $Errors -Code 'PILOT_COMPLETION_INVALID' -Message 'COMPLETED is valid only after the exact immutable AUTHORIZED pilot and may not retain waiver-only fields.'
        }

        [DateTimeOffset]$authorizedAt = [DateTimeOffset]::MinValue
        [DateTimeOffset]$startedAt = [DateTimeOffset]::MinValue
        [DateTimeOffset]$completedAt = [DateTimeOffset]::MinValue
        [DateTimeOffset]$immutableAt = [DateTimeOffset]::MinValue
        $chronologyValid = $null -ne $PilotVerdict -and
            [OperationsBlueprint.StrictRfc3339]::TryParse([string]$PilotVerdict.pilotAuthorization.approvedAt, [ref]$authorizedAt) -and
            [OperationsBlueprint.StrictRfc3339]::TryParse([string]$completion.startedAt, [ref]$startedAt) -and
            [OperationsBlueprint.StrictRfc3339]::TryParse([string]$completion.completedAt, [ref]$completedAt) -and
            [OperationsBlueprint.StrictRfc3339]::TryParse([string]$Verdict.immutableAt, [ref]$immutableAt) -and
            $authorizedAt -le $startedAt -and $startedAt -le $completedAt -and
            $completedAt -le $immutableAt -and $immutableAt -le $EvaluationTime
        if (-not $chronologyValid) {
            Add-BlueprintError -Errors $Errors -Code 'PILOT_COMPLETION_CHRONOLOGY_INVALID' -Message 'Pilot chronology must satisfy authorization <= start <= completion <= final immutableAt <= evaluation time.'
        }

        $pilotEvidenceRelease = Resolve-CanonicalRecord -RecordMap $RecordMap `
            -Reference $completion.pilotEvidenceReleaseRef -ExpectedTypes @('evidence-release') `
            -Context 'pilot completion evidence release' -Errors $Errors
        $coverageEvidence = Resolve-CanonicalRecord -RecordMap $RecordMap `
            -Reference $completion.coverageEvidenceRef -ExpectedTypes @('evidence-record') `
            -Context 'pilot completion coverage evidence' -Errors $Errors
        if ($null -ne $pilotEvidenceRelease) {
            Test-RequiredProperties -Object $pilotEvidenceRelease -Names @(
                'memberRecordIds','memberRecordBindings','semanticGateStatus','samplingFloorStatus','distributionStatus','coverageStatus',
                'testPlanRef','testPlanDigest','thresholdPolicyRef','thresholdPolicyDigest','conditionRefs',
                'baselineFingerprint','testPackVersion','freshnessBinding'
            ) -Context 'pilot completion evidence release' -Errors $Errors
            Test-EvidenceReleaseBinding -ReleaseRecord $pilotEvidenceRelease -EvidenceRecords @($coverageEvidence) -RecordMap $RecordMap `
                -EvaluationTime $EvaluationTime -ConsumerRecord $Verdict -Manifest $Manifest `
                -Phase0TestPlan $Phase0TestPlan -ThresholdPolicy $FrozenThresholdPolicy `
                -ValidationProfile $ValidationProfile -Context 'pilot completion' -Errors $Errors
            $pilotMemberClosureValid = $true
            foreach ($pilotMemberId in @($pilotEvidenceRelease.memberRecordIds)) {
                if (-not $RecordMap.ContainsKey([string]$pilotMemberId)) { $pilotMemberClosureValid = $false; continue }
                $pilotMember = $RecordMap[[string]$pilotMemberId]
                if ([string]$pilotMember.recordType -ceq 'evidence-record') {
                    if ([string]$pilotMember.evidenceReleaseRef -cne [string]$pilotEvidenceRelease.recordId -or
                        -not $RecordMap.ContainsKey([string]$pilotMember.distributionRef) -or
                        @($pilotEvidenceRelease.memberRecordIds) -cnotcontains [string]$pilotMember.distributionRef -or
                        ($RecordMap.ContainsKey([string]$pilotMember.distributionRef) -and
                         [string]$RecordMap[[string]$pilotMember.distributionRef].testClass -cnotin @('production-pilot','sentiment'))) {
                        $pilotMemberClosureValid = $false
                    }
                }
                elseif ([string]$pilotMember.recordType -ceq 'distribution-record') {
                    if ([string]$pilotMember.testClass -cnotin @('production-pilot','sentiment') -or
                        @($pilotEvidenceRelease.memberRecordIds) -cnotcontains [string]$pilotMember.sourceEvidenceRef) {
                        $pilotMemberClosureValid = $false
                    }
                }
                else { $pilotMemberClosureValid = $false }
            }
            if (-not $pilotMemberClosureValid) {
                Add-BlueprintError -Errors $Errors -Code 'PILOT_EVIDENCE_RELEASE_SCOPE_INVALID' -Message 'The final pilot release may contain only digest-bound Phase 4 production-pilot and sentiment evidence with their exact source distributions.'
            }
        }
        $releaseBindingValid = $null -ne $pilotEvidenceRelease -and $null -ne $coverageEvidence -and
            [string]$completion.pilotEvidenceReleaseRef -ceq [string]$pilotEvidenceRelease.recordId -and
            [string]$completion.coverageEvidenceRef -ceq [string]$coverageEvidence.recordId -and
            @($Verdict.evidenceReleases | Where-Object { [string]$_ -ceq [string]$pilotEvidenceRelease.recordId }).Count -eq 1 -and
            @($pilotEvidenceRelease.memberRecordIds) -ccontains [string]$coverageEvidence.recordId -and
            $null -ne $Phase0TestPlan -and
            [string]$pilotEvidenceRelease.testPlanRef -ceq [string]$Phase0TestPlan.recordId -and
            [string]$pilotEvidenceRelease.testPlanDigest -ceq [string]$Phase0TestPlan.contentDigest -and
            $null -ne $FrozenThresholdPolicy -and
            [string]$pilotEvidenceRelease.thresholdPolicyRef -ceq [string]$FrozenThresholdPolicy.recordId -and
            [string]$pilotEvidenceRelease.thresholdPolicyDigest -ceq [string]$FrozenThresholdPolicy.contentDigest
        if (-not $releaseBindingValid) {
            Add-BlueprintError -Errors $Errors -Code 'PILOT_COMPLETION_EVIDENCE_INVALID' -Message 'Pilot completion must bind exact whole-record coverage and pilot-release IDs, final release membership, and the frozen test-plan and threshold-policy digests.'
        }

        $pilotPopulationPlan = $null
        $pilotPopulationPlanRef = if ($null -ne $PilotVerdict) { [string]$PilotVerdict.pilotPopulationPlanRef } else { '' }
        $populationPlanRecord = if (Test-NonBlankString $pilotPopulationPlanRef) {
            Resolve-CanonicalRecord -RecordMap $RecordMap -Reference $pilotPopulationPlanRef `
                -ExpectedTypes @('candidate-manifest') -Context 'pilot population plan' -Errors $Errors
        }
        else { $null }
        $populationPointer = if ($pilotPopulationPlanRef.Contains('#')) { $pilotPopulationPlanRef.Split('#', 2)[1] } else { '' }
        $populationFound = $false
        if ($null -ne $populationPlanRecord) {
            $pilotPopulationPlan = Get-JsonPointerValue -Document $populationPlanRecord.payload `
                -Pointer $populationPointer -Found ([ref]$populationFound)
        }
        if ($null -eq $Manifest -or $null -eq $populationPlanRecord -or
            [string]$populationPlanRecord.recordId -cne [string]$Manifest.recordId -or
            $pilotPopulationPlanRef -cne ([string]$Manifest.recordId + '#/pilotPopulationPlan') -or
            -not $populationFound -or $pilotPopulationPlan -isnot [pscustomobject] -or
            [string]$PilotVerdict.privacyOwner -cne [string]$pilotPopulationPlan.privacyOwner) {
            Add-BlueprintError -Errors $Errors -Code 'PILOT_POPULATION_PLAN_BINDING_INVALID' -Message 'Pilot completion does not resolve the exact frozen manifest pilotPopulationPlan and privacy owner authorized before enrollment.'
        }

        $coverageDistribution = if ($null -ne $coverageEvidence) {
            Resolve-CanonicalRecord -RecordMap $RecordMap -Reference $coverageEvidence.distributionRef `
                -ExpectedTypes @('distribution-record') -Context 'pilot coverage distribution' -Errors $Errors
        }
        else { $null }
        $coverageDistributionValidation = Test-PilotPhase4DistributionSemantics `
            -Distribution $coverageDistribution -ExpectedClass 'production-pilot' -RecordMap $RecordMap `
            -Phase0TestPlan $Phase0TestPlan -PilotEvidenceRelease $pilotEvidenceRelease `
            -ExpectedEvidenceRecord $coverageEvidence -PilotPopulationPlan $pilotPopulationPlan `
            -PilotPopulationPlanRef $pilotPopulationPlanRef `
            -Manifest $Manifest -FrozenThresholdPolicy $FrozenThresholdPolicy -EvaluationTime $EvaluationTime `
            -AuthorizedAt $authorizedAt -StartedAt $startedAt -CompletedAt $completedAt -FinalImmutableAt $immutableAt `
            -Context 'pilot coverage distribution' -Errors $Errors

        if ($null -ne $coverageEvidence) {
            Test-RequiredProperties -Object $coverageEvidence -Names @(
                'schemaVersion','recordKind','provenance','evidenceUse','testRef','conditionRef','testPackVersion',
                'timestamp','result','distribution','coverage','evidenceReleaseRef','coverageStatus','distributionRef','testPlanRef'
            ) -Context 'pilot completion coverage evidence' -Errors $Errors
            $coverageFields = @('scope','plannedUnits','observedUnits','plannedRuns','observedRuns','percent','gaps')
            if ($coverageEvidence.coverage -is [pscustomobject]) {
                Test-RequiredProperties -Object $coverageEvidence.coverage -Names @(
                    $coverageFields | Where-Object { [string]$_ -cne 'gaps' }
                ) -Context 'pilot completion portable coverage' -Errors $Errors
                # A complete pilot must explicitly report zero gaps. Presence is
                # required, while an empty collection is the valid success value.
                if ($null -eq $coverageEvidence.coverage.PSObject.Properties['gaps']) {
                    Add-BlueprintError -Errors $Errors -Code 'MISSING_REQUIRED_FIELD' -Message 'pilot completion portable coverage requires gaps.'
                }
                Test-AllowedProperties -Object $coverageEvidence.coverage -Names @($coverageFields + 'extensions') -Context 'pilot completion portable coverage' -Errors $Errors
            }
            $portableCoverageValid = $coverageEvidence.coverage -is [pscustomobject] -and
                $coverageEvidence.distribution -is [pscustomobject] -and $null -ne $coverageDistribution -and
                ($coverageEvidence.coverage.plannedUnits -is [int] -or $coverageEvidence.coverage.plannedUnits -is [long]) -and
                ($coverageEvidence.coverage.observedUnits -is [int] -or $coverageEvidence.coverage.observedUnits -is [long]) -and
                ($coverageEvidence.coverage.plannedRuns -is [int] -or $coverageEvidence.coverage.plannedRuns -is [long]) -and
                ($coverageEvidence.coverage.observedRuns -is [int] -or $coverageEvidence.coverage.observedRuns -is [long]) -and
                (Test-NumberValue $coverageEvidence.coverage.percent) -and
                $coverageEvidence.coverage.gaps -is [System.Collections.IList] -and @($coverageEvidence.coverage.gaps).Count -eq 0 -and
                ($pilotPopulationPlan.targetCount -is [int] -or $pilotPopulationPlan.targetCount -is [long]) -and
                ($coverageDistribution.unitCount -is [int] -or $coverageDistribution.unitCount -is [long]) -and
                ($coverageDistribution.runCount -is [int] -or $coverageDistribution.runCount -is [long]) -and
                ($coverageDistribution.requiredRuns -is [int] -or $coverageDistribution.requiredRuns -is [long]) -and
                ($coverageEvidence.distribution.unitCount -is [int] -or $coverageEvidence.distribution.unitCount -is [long]) -and
                ($coverageEvidence.distribution.runCount -is [int] -or $coverageEvidence.distribution.runCount -is [long]) -and
                [int64]$coverageEvidence.coverage.plannedUnits -eq [int64]$pilotPopulationPlan.targetCount -and
                [int64]$coverageEvidence.coverage.observedUnits -eq [int64]$pilotPopulationPlan.targetCount -and
                [int64]$coverageEvidence.coverage.observedRuns -eq [int64]$coverageDistribution.runCount -and
                [System.Numerics.BigInteger][int64]$coverageEvidence.coverage.plannedRuns -eq
                    ([System.Numerics.BigInteger][int64]$pilotPopulationPlan.targetCount *
                     [System.Numerics.BigInteger][int64]$coverageDistribution.requiredRuns) -and
                [double]$coverageEvidence.coverage.percent -eq 100.0 -and
                [int64]$coverageEvidence.distribution.unitCount -eq [int64]$coverageDistribution.unitCount -and
                [int64]$coverageEvidence.distribution.runCount -eq [int64]$coverageDistribution.runCount -and
                [string]$coverageEvidence.result.stopConditionOutcome -ceq [string]$completion.stopConditionOutcome
            if (-not $portableCoverageValid) {
                Add-BlueprintError -Errors $Errors -Code 'PILOT_COMPLETION_COVERAGE_INVALID' -Message 'Pilot coverage evidence must reconcile the exact population target, completed runs, zero representation gaps, portable distribution counts, and stop outcome.'
            }
        }

        $productionFloor = if ($null -ne $coverageDistributionValidation) { $coverageDistributionValidation.Floor } else { $null }
        if (-not $chronologyValid -or $productionFloor -isnot [pscustomobject] -or
            ($productionFloor.minEvidenceDays -isnot [int] -and $productionFloor.minEvidenceDays -isnot [long]) -or
            ($chronologyValid -and ($completedAt - $startedAt).TotalDays -lt [int64]$productionFloor.minEvidenceDays)) {
            Add-BlueprintError -Errors $Errors -Code 'PILOT_EVIDENCE_DURATION_INVALID' -Message 'Completed production-pilot evidence must span at least the exact minimum evidence days frozen by the Phase 0 production-pilot floor.'
        }
        [void](Test-PilotCompletionRepresentationProof -Representation $coverageEvidence.result.representation `
            -PilotPopulationPlan $pilotPopulationPlan -PilotPopulationPlanRef $pilotPopulationPlanRef `
            -CoverageEvidence $coverageEvidence -ProductionDistribution $coverageDistribution `
            -ProductionFloor $productionFloor -Errors $Errors)

        $phase4Distributions = New-Object System.Collections.ArrayList
        if ($null -ne $pilotEvidenceRelease) {
            foreach ($memberRef in @($pilotEvidenceRelease.memberRecordIds)) {
                if (([string]$memberRef).Contains('#')) { continue }
                if (-not $RecordMap.ContainsKey([string]$memberRef)) { continue }
                $member = $RecordMap[[string]$memberRef]
                if ([string]$member.recordType -ceq 'distribution-record' -and
                    [string]$member.testClass -cin @('production-pilot','sentiment')) {
                    [void]$phase4Distributions.Add($member)
                }
            }
        }
        foreach ($phase4Distribution in @($phase4Distributions)) {
            if ($null -ne $coverageDistribution -and
                [string]$phase4Distribution.recordId -ceq [string]$coverageDistribution.recordId) {
                continue
            }
            $expectedSource = if ($RecordMap.ContainsKey([string]$phase4Distribution.sourceEvidenceRef)) {
                $RecordMap[[string]$phase4Distribution.sourceEvidenceRef]
            }
            else { $null }
            [void](Test-PilotPhase4DistributionSemantics -Distribution $phase4Distribution `
                -ExpectedClass ([string]$phase4Distribution.testClass) -RecordMap $RecordMap `
                -Phase0TestPlan $Phase0TestPlan -PilotEvidenceRelease $pilotEvidenceRelease `
                -ExpectedEvidenceRecord $expectedSource -PilotPopulationPlan $pilotPopulationPlan `
                -PilotPopulationPlanRef $pilotPopulationPlanRef `
                -Manifest $Manifest -FrozenThresholdPolicy $FrozenThresholdPolicy -EvaluationTime $EvaluationTime `
                -AuthorizedAt $authorizedAt -StartedAt $startedAt -CompletedAt $completedAt -FinalImmutableAt $immutableAt `
                -Context "pilot Phase 4 distribution $($phase4Distribution.recordId)" -Errors $Errors)
        }
        foreach ($requiredClass in @('production-pilot','sentiment')) {
            if (@($phase4Distributions | Where-Object { [string]$_.testClass -ceq $requiredClass }).Count -eq 0) {
                Add-BlueprintError -Errors $Errors -Code 'PILOT_PHASE4_DISTRIBUTION_MISSING' -Message "Pilot evidence release lacks a representative, exact-floor $requiredClass distribution."
            }
        }

        $productionDistributions = @($phase4Distributions | Where-Object { [string]$_.testClass -ceq 'production-pilot' })
        $sentimentDistributions = @($phase4Distributions | Where-Object { [string]$_.testClass -ceq 'sentiment' })
        $sentimentEvidence = if ($sentimentDistributions.Count -eq 1 -and
            $RecordMap.ContainsKey([string]$sentimentDistributions[0].sourceEvidenceRef)) {
            $RecordMap[[string]$sentimentDistributions[0].sourceEvidenceRef]
        }
        else { $null }
        if ($productionDistributions.Count -ne 1 -or $sentimentDistributions.Count -ne 1) {
            Add-BlueprintError -Errors $Errors -Code 'PILOT_PARTICIPANT_COMMITMENT_INVALID' -Message 'The v1 pilot participant proof profile requires exactly one production-pilot and one sentiment distribution in the final release.'
        }
        [void](Test-PilotPrivateParticipantClosure `
            -ProductionRepresentation $coverageEvidence.result.representation `
            -SentimentRepresentation $(if ($null -ne $sentimentEvidence) { $sentimentEvidence.result.representation } else { $null }) `
            -PilotEvidenceRelease $pilotEvidenceRelease -Manifest $Manifest -Phase0TestPlan $Phase0TestPlan `
            -FrozenThresholdPolicy $FrozenThresholdPolicy -PilotPopulationPlan $pilotPopulationPlan `
            -PilotPopulationPlanRef $pilotPopulationPlanRef -PilotVerdict $PilotVerdict -FinalVerdict $Verdict `
            -ProductionEvidence $coverageEvidence -SentimentEvidence $sentimentEvidence `
            -ProductionDistribution $(if ($productionDistributions.Count -eq 1) { $productionDistributions[0] } else { $null }) `
            -SentimentDistribution $(if ($sentimentDistributions.Count -eq 1) { $sentimentDistributions[0] } else { $null }) `
            -AuthorizedAt $authorizedAt -StartedAt $startedAt -CompletedAt $completedAt `
            -StartedAtText ([string]$completion.startedAt) -CompletedAtText ([string]$completion.completedAt) `
            -EvaluationTime $EvaluationTime -ValidationProfile $ValidationProfile -Errors $Errors)

        $stopOutcomeValid = [string]$completion.stopConditionOutcome -cin @(
            'NO_UNRESOLVED_STOP_CONDITION','ROLLBACK_COMPLETED'
        )
        if ([string]$completion.stopConditionOutcome -ceq 'ROLLBACK_COMPLETED') {
            $stopOutcomeValid = $stopOutcomeValid -and
                [string]$Verdict.fleetVerdict -cin @('HOLD','FAIL','INCONCLUSIVE') -and
                [string]$Verdict.fleetDeploymentDisposition -ceq 'BLOCKED' -and
                [string]$Verdict.procurementDisposition -ceq 'BLOCKED'
        }
        elseif ([string]$Verdict.fleetVerdict -cin @('QUALIFY','QUALIFY_WITH_CONDITIONS')) {
            $stopOutcomeValid = $stopOutcomeValid -and
                [string]$completion.stopConditionOutcome -ceq 'NO_UNRESOLVED_STOP_CONDITION'
        }
        if (-not $stopOutcomeValid) {
            Add-BlueprintError -Errors $Errors -Code 'PILOT_STOP_OUTCOME_INVALID' -Message 'A qualifying verdict requires no unresolved stop condition; a completed rollback must leave deployment and procurement blocked.'
        }
    }
    elseif ([string]$completion.status -ceq 'NOT_REQUIRED') {
        Test-RequiredProperties -Object $completion -Names @('reason','authorityApprovalRef') -Context 'pilot not-required completion' -Errors $Errors
        $completedOnlyFields = @(
            'pilotEvidenceReleaseRef','coverageEvidenceRef','stopConditionOutcome','startedAt','completedAt','approvedBy'
        )
        $hasCompletedOnlyField = @($completedOnlyFields | Where-Object {
            $null -ne $completion.PSObject.Properties[[string]$_]
        }).Count -gt 0
        if ($null -eq $PilotVerdict -or [string]$Verdict.pilotAuthorization.status -cne 'NOT_REQUIRED' -or
            [string]$PilotVerdict.pilotAuthorization.status -cne 'NOT_REQUIRED' -or
            -not (Test-NonBlankString $completion.reason) -or
            [string]$completion.reason -cne [string]$Verdict.pilotAuthorization.reason -or
            $hasCompletedOnlyField -or
            [string]$completion.authorityApprovalRef -cne [string]$Verdict.pilotNotRequiredApprovalRef -or
            -not (Test-Sha256Token $Verdict.pilotNotRequiredApprovalDigest) -or $null -eq $Manifest) {
            Add-BlueprintError -Errors $Errors -Code 'PILOT_NOT_REQUIRED_APPROVAL_INVALID' -Message 'NOT_REQUIRED must have one consistent reason, no execution fields, and the exact governed waiver approval reference and digest.'
        }
        elseif ($null -ne $Manifest) {
            $pilotNotRequiredApprovalValidation = Test-QualificationAuthorityApprovalSemantics `
                -RecordMap $RecordMap -ApprovalRef $Verdict.pilotNotRequiredApprovalRef `
                -ApprovalDigest $Verdict.pilotNotRequiredApprovalDigest -Verdict $Verdict -Manifest $Manifest `
                -DecisionScope 'PILOT_NOT_REQUIRED' -EvaluationTime $EvaluationTime `
                -FailureCode 'PILOT_NOT_REQUIRED_APPROVAL_INVALID' -Errors $Errors
            if ($null -eq $pilotNotRequiredApprovalValidation -or
                $null -eq $pilotNotRequiredApprovalValidation.Approval -or
                [string]$Verdict.pilotNotRequiredApprovalRef -cne [string]$pilotNotRequiredApprovalValidation.Approval.recordId -or
                [string]$completion.authorityApprovalRef -cne [string]$pilotNotRequiredApprovalValidation.Approval.recordId) {
                Add-BlueprintError -Errors $Errors -Code 'PILOT_NOT_REQUIRED_APPROVAL_INVALID' -Message 'Pilot waiver references must both identify the exact whole governed approval record; fragments and aliases are forbidden.'
            }
            if ($null -ne $VerdictIssuanceApprovalValidation -and
                ($null -eq $pilotNotRequiredApprovalValidation -or
                 [string]$pilotNotRequiredApprovalValidation.Approval.authorityPrincipalId -cne [string]$VerdictIssuanceApprovalValidation.Approval.authorityPrincipalId -or
                 [string]$pilotNotRequiredApprovalValidation.Approval.approverSetDigest -cne [string]$VerdictIssuanceApprovalValidation.Approval.approverSetDigest)) {
                Add-BlueprintError -Errors $Errors -Code 'PILOT_NOT_REQUIRED_APPROVAL_INVALID' -Message 'Pilot waiver and verdict issuance must use the same canonical authority principal and approver set.'
            }
        }
    }
    else {
        Add-BlueprintError -Errors $Errors -Code 'PILOT_COMPLETION_INVALID' -Message 'pilotCompletion.status must be exactly COMPLETED or NOT_REQUIRED.'
    }

    $personaPermits = @($Verdict.personaVerdicts | Where-Object {
        [string]$_.verdict -cin @('QUALIFY','QUALIFY_WITH_CONDITIONS') -or
        [string]$_.assignmentDisposition -cin @('APPROVED','APPROVED_WITH_CONDITIONS')
    }).Count -gt 0
    $finalDecisionPermits = [string]$Verdict.fleetVerdict -cin @('QUALIFY','QUALIFY_WITH_CONDITIONS') -or
        [string]$Verdict.fleetDeploymentDisposition -cin @('APPROVED','APPROVED_WITH_CONDITIONS') -or
        [string]$Verdict.procurementDisposition -cin @('APPROVED','APPROVED_WITH_CONDITIONS') -or
        $personaPermits
    if ($finalDecisionPermits -and
        ([string]$Verdict.pilotAuthorization.status -cne 'AUTHORIZED' -or
         [string]$completion.status -cne 'COMPLETED')) {
        Add-BlueprintError -Errors $Errors -Code 'PILOT_PHASE4_REQUIRED_FOR_APPROVAL' -Message 'Any qualifying, assignment, deployment, or procurement approval requires an authorized and completed Phase 4 pilot.'
    }
    if ([string]$completion.status -ceq 'NOT_REQUIRED') {
        $waiverIsStopOnly = [string]$Verdict.fleetVerdict -cin @('HOLD','FAIL','INCONCLUSIVE') -and
            [string]$Verdict.fleetDeploymentDisposition -ceq 'BLOCKED' -and
            [string]$Verdict.procurementDisposition -ceq 'BLOCKED' -and
            @($Verdict.personaVerdicts | Where-Object {
                [string]$_.assignmentDisposition -cne 'BLOCKED' -or
                [string]$_.verdict -cnotin @('HOLD','FAIL','INCONCLUSIVE')
            }).Count -eq 0
        if (-not $waiverIsStopOnly) {
            Add-BlueprintError -Errors $Errors -Code 'PILOT_NOT_REQUIRED_DECISION_INVALID' -Message 'A pilot waiver may support only a non-deployment decision with all deployment, procurement, and persona assignments blocked.'
        }
    }

    return [pscustomobject]@{
        Valid = $Errors.Count -eq $initialErrorCount
        PilotEvidenceRelease = $pilotEvidenceRelease
        CoverageEvidence = $coverageEvidence
        PilotNotRequiredApprovalValidation = $pilotNotRequiredApprovalValidation
    }
}

function Test-LeadershipClaimChain {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]$Chain,
        [object[]]$RecordIndex = @(),
        [DateTimeOffset]$EvaluationTime = [DateTimeOffset]::UtcNow,
        [ValidateSet('TEST', 'PRODUCTION')][string]$ValidationProfile = 'PRODUCTION'
    )

    $ValidationProfile = ([string]$ValidationProfile).ToUpperInvariant()
    $errors = New-Object System.Collections.ArrayList
    if ($null -eq $Chain) {
        Add-BlueprintError -Errors $errors -Code 'NULL_CLAIM_CHAIN' -Message 'Leadership claim chain is null.'
        return New-BlueprintResult -Errors $errors
    }
    if (-not (Test-CanonicalJsonRuntimeDomain -Value $Chain)) {
        Add-BlueprintError -Errors $errors -Code 'CANONICAL_JSON_RUNTIME_DOMAIN_INVALID' -Message 'Leadership claim chain contains a value outside the frozen cross-host JSON runtime domain.'
        return New-BlueprintResult -Errors $errors -State $(if ($ValidationProfile -ceq 'TEST') { 'TEST_FIXTURE_BLOCKED_NON_PROMOTABLE' } else { 'BLOCKED' })
    }

    $claimTopLevelFields = @(
        'chainVersion', 'documentType', 'status', 'portableContractRefs',
        'personaNeed', 'currentFleetIssue', 'candidateComparison', 'businessEffect',
        'recommendation', 'lineage', 'requiredLeadershipLinks',
        'currentFleetRequiredDimensions', 'readinessRules'
    )
    Test-RequiredProperties -Object $Chain -Names @(
        'chainVersion', 'documentType', 'status', 'portableContractRefs', 'lineage',
        'requiredLeadershipLinks', 'currentFleetRequiredDimensions', 'readinessRules'
    ) -Context 'leadership claim chain' -Errors $errors
    Test-AllowedProperties -Object $Chain -Names $claimTopLevelFields -Context 'leadership claim chain' -Errors $errors
    foreach ($linkField in @('personaNeed', 'currentFleetIssue', 'candidateComparison', 'businessEffect', 'recommendation')) {
        if ($null -eq $Chain.PSObject.Properties[$linkField]) {
            Add-BlueprintError -Errors $errors -Code 'MISSING_REQUIRED_FIELD' -Message "Leadership claim chain requires $linkField."
        }
    }
    if ($Chain.documentType -cne 'leadership-claim-chain') {
        Add-BlueprintError -Errors $errors -Code 'INVALID_DOCUMENT_TYPE' -Message 'Claim chain documentType must be leadership-claim-chain.'
    }
    if ([string]$Chain.chainVersion -cne '1.0.0') {
        Add-BlueprintError -Errors $errors -Code 'CLAIM_CHAIN_VERSION_MISMATCH' -Message 'Claim chain must use the frozen v1.0.0 public template policy.'
    }
    if ([string]$Chain.status -cnotin @('NOT_ISSUED', 'ISSUED')) {
        Add-BlueprintError -Errors $errors -Code 'INVALID_CLAIM_CHAIN_STATUS' -Message 'Claim chain status must be NOT_ISSUED or ISSUED.'
    }
    if ($null -ne $Chain.lineage) {
        Test-AllowedProperties -Object $Chain.lineage -Names @(
            'generatedAt', 'validatorReleaseRef', 'semanticValidationRef',
            'semanticValidationDigest', 'semanticInputDigest', 'derivedDocumentsAreEvidence'
        ) -Context 'leadership lineage' -Errors $errors
        if ($Chain.lineage.derivedDocumentsAreEvidence -ne $false) {
            Add-BlueprintError -Errors $errors -Code 'DERIVED_DOCUMENT_AS_EVIDENCE' -Message 'Derived documents cannot be evidence.'
        }
        $expectedValidatorReleaseRef = if ([string]$Chain.status -ceq 'NOT_ISSUED') {
            'operations-blueprint-v1.0.0'
        }
        else { 'private://validator-releases/operations-blueprint-v1.0.0' }
        if ([string]$Chain.lineage.validatorReleaseRef -cne $expectedValidatorReleaseRef) {
            Add-BlueprintError -Errors $errors -Code 'VALIDATOR_RELEASE_MISMATCH' -Message 'Claim chain must bind the reviewed operations blueprint validator release.'
        }
    }

    $requiredPortableContractRefs = @(
        '../../v2.0.1/NEW_LAPTOP_EVALUATION_PLAYBOOK_v2.md',
        '../../v2.0.1/schemas/candidate-manifest.schema.json',
        '../../v2.0.1/schemas/test-plan.schema.json',
        '../../v2.0.1/schemas/evidence-record.schema.json',
        '../../v2.0.1/schemas/threshold-policy.schema.json',
        '../../v2.0.1/schemas/verdict-record.schema.json'
    )
    if (@($Chain.portableContractRefs).Count -ne $requiredPortableContractRefs.Count) {
        Add-BlueprintError -Errors $errors -Code 'PORTABLE_CONTRACT_SET_MISMATCH' -Message 'Claim chain must bind the exact Playbook v2.0.1 portable contract set.'
    }
    foreach ($portableRef in $requiredPortableContractRefs) {
        if (@($Chain.portableContractRefs) -cnotcontains $portableRef) {
            Add-BlueprintError -Errors $errors -Code 'PORTABLE_CONTRACT_SET_MISMATCH' -Message "Claim chain omits portable contract $portableRef."
        }
    }
    $leadershipTemplatePolicyDigest = Get-LeadershipTemplatePolicyDigest -Chain $Chain
    $expectedLeadershipTemplatePolicyDigest = if ([string]$Chain.status -ceq 'NOT_ISSUED') {
        'sha256:905c56315c1838670fe8fda39b68fc2fb4518e1e9caa8c473f5adad4042f9063'
    }
    else { 'sha256:a135cf5339bbd671047136678ea2e48aa320009c2ca839faf8475fb11aca09f9' }
    if ([string]$leadershipTemplatePolicyDigest -cne $expectedLeadershipTemplatePolicyDigest) {
        Add-BlueprintError -Errors $errors -Code 'LEADERSHIP_TEMPLATE_POLICY_DRIFT' -Message 'The frozen five-link questions, fleet dimensions, readiness rules, or contract boundary changed.'
    }

    if ($Chain.status -eq 'NOT_ISSUED') {
        foreach ($linkField in @('personaNeed', 'currentFleetIssue', 'candidateComparison', 'businessEffect', 'recommendation')) {
            if ($null -ne $Chain.$linkField) {
                Add-BlueprintError -Errors $errors -Code 'UNISSUED_DECISION_LINK_PRESENT' -Message "NOT_ISSUED chain may not carry $linkField."
            }
        }
        foreach ($lineageField in @('generatedAt', 'semanticValidationRef', 'semanticValidationDigest', 'semanticInputDigest')) {
            if ($null -ne $Chain.lineage.$lineageField) {
                Add-BlueprintError -Errors $errors -Code 'UNISSUED_LINEAGE_PRESENT' -Message "NOT_ISSUED chain may not carry $lineageField."
            }
        }
        $notReadyResult = New-BlueprintResult -Errors $errors -State 'NOT_READY'
        $notReadyResult.Allowed = $false
        return $notReadyResult
    }

    Test-RequiredProperties -Object $Chain.lineage -Names @(
        'generatedAt', 'validatorReleaseRef', 'derivedDocumentsAreEvidence',
        'semanticValidationRef', 'semanticValidationDigest', 'semanticInputDigest'
    ) -Context 'issued claim lineage' -Errors $errors
    if (-not (Test-Sha256Token $Chain.lineage.semanticValidationDigest)) {
        Add-BlueprintError -Errors $errors -Code 'SEMANTIC_VALIDATION_DIGEST_INVALID' -Message 'Issued lineage requires the retained semantic-validation result digest.'
    }
    if (-not (Test-Sha256Token $Chain.lineage.semanticInputDigest)) {
        Add-BlueprintError -Errors $errors -Code 'SEMANTIC_INPUT_DIGEST_INVALID' -Message 'Issued lineage requires the canonical decision-input digest.'
    }
    [DateTimeOffset]$lineageGeneratedAt = [DateTimeOffset]::MinValue
    if (-not [OperationsBlueprint.StrictRfc3339]::TryParse([string]$Chain.lineage.generatedAt, [ref]$lineageGeneratedAt) -or $lineageGeneratedAt -gt $EvaluationTime) {
        Add-BlueprintError -Errors $errors -Code 'LINEAGE_GENERATED_TIME_INVALID' -Message 'Issued claim generation time must be valid and non-future.'
    }

    $links = @(
        @{ Name = 'personaNeed'; Code = 'MISSING_PERSONA_NEED' },
        @{ Name = 'currentFleetIssue'; Code = 'MISSING_CURRENT_FLEET_ISSUE' },
        @{ Name = 'candidateComparison'; Code = 'MISSING_CANDIDATE_COMPARISON' },
        @{ Name = 'businessEffect'; Code = 'MISSING_BUSINESS_EFFECT' },
        @{ Name = 'recommendation'; Code = 'MISSING_RECOMMENDATION' }
    )
    foreach ($link in $links) {
        $property = $Chain.PSObject.Properties[$link.Name]
        if ($null -eq $property -or $null -eq $property.Value) {
            Add-BlueprintError -Errors $errors -Code $link.Code -Message "Issued chain lacks $($link.Name)."
        }
    }
    if ($errors.Count -gt 0) { return New-BlueprintResult -Errors $errors }

    Test-RequiredProperties -Object $Chain.personaNeed -Names @('personaId', 'manifestRef', 'personaVerdictPointer', 'capacityWaterfallPointer', 'evidenceReleaseRef', 'evidenceRefs', 'provenance', 'freshness') -Context 'personaNeed' -Errors $errors
    Test-RequiredProperties -Object $Chain.currentFleetIssue -Names @(
        'incumbentControlRef', 'cohortRef', 'statement', 'issueStatementPointer',
        'attributionClass', 'observationWindow', 'baselineFingerprint',
        'fleetPortfolioRef', 'fleetPortfolioCohortPointer',
        'evidenceReleaseRef', 'evidenceRefs', 'provenance', 'freshness'
    ) -Context 'currentFleetIssue' -Errors $errors
    if (-not (Test-ValuePresent $Chain.currentFleetIssue.fleetPortfolioRef) -or
        -not (Test-ValuePresent $Chain.currentFleetIssue.fleetPortfolioCohortPointer)) {
        Add-BlueprintError -Errors $errors -Code 'FLEET_PORTFOLIO_REF_REQUIRED' -Message 'Current-fleet evidence requires an issued fleet-portfolio record and selected cohort pointer.'
    }
    Test-RequiredProperties -Object $Chain.candidateComparison -Names @('candidateRef', 'incumbentControlRef', 'siblingControlRef', 'testPlanRef', 'conditionRefs', 'evidenceReleaseRef', 'evidenceRefs', 'provenance', 'baselineFingerprint', 'testPackVersion', 'freshness') -Context 'candidateComparison' -Errors $errors
    $businessEffectPolicies = @($Chain.requiredLeadershipLinks | Where-Object { [string]$_.link -ceq 'businessEffect' })
    $businessEffectPolicy = if ($businessEffectPolicies.Count -eq 1) { $businessEffectPolicies[0] } else { $null }
    if ($null -eq $businessEffectPolicy) {
        Add-BlueprintError -Errors $errors -Code 'BUSINESS_EFFECT_MACHINE_POLICY_INVALID' -Message 'The frozen leadership policy must contain exactly one businessEffect machine-policy entry.'
    }
    Test-RequiredProperties -Object $Chain.recommendation -Names @(
        'verdictRef', 'fleetVerdictPointer', 'personaVerdictPointer',
        'procurementEnvelopePointer', 'claimRecordRef', 'statementPointer', 'action', 'statement', 'freshness'
    ) -Context 'recommendation' -Errors $errors
    Test-AllowedProperties -Object $Chain.personaNeed -Names @(
        'personaId', 'manifestRef', 'personaVerdictPointer', 'capacityWaterfallPointer',
        'evidenceReleaseRef', 'evidenceRefs', 'provenance', 'freshness'
    ) -Context 'personaNeed' -Errors $errors
    Test-AllowedProperties -Object $Chain.currentFleetIssue -Names @(
        'incumbentControlRef', 'cohortRef', 'statement', 'issueStatementPointer',
        'attributionClass', 'observationWindow', 'baselineFingerprint',
        'fleetPortfolioRef', 'fleetPortfolioCohortPointer',
        'evidenceReleaseRef', 'evidenceRefs', 'provenance', 'freshness'
    ) -Context 'currentFleetIssue' -Errors $errors
    if ([string]$Chain.currentFleetIssue.attributionClass -cnotin @('DIRECT', 'CONTROLLED_DELTA', 'ASSOCIATION', 'UNKNOWN')) {
        Add-BlueprintError -Errors $errors -Code 'CURRENT_FLEET_ATTRIBUTION_INVALID' -Message 'Current-fleet issue requires a bounded attribution class.'
    }
    Test-AllowedProperties -Object $Chain.candidateComparison -Names @(
        'candidateRef', 'incumbentControlRef', 'siblingControlRef', 'testPlanRef',
        'conditionRefs', 'evidenceReleaseRef', 'evidenceRefs', 'provenance',
        'baselineFingerprint', 'testPackVersion', 'freshness'
    ) -Context 'candidateComparison' -Errors $errors
    $businessEffectAllowedFields = New-Object System.Collections.ArrayList
    if ($null -ne $businessEffectPolicy) {
        foreach ($policyField in @($businessEffectPolicy.requiredFields)) {
            if (Test-NonBlankString $policyField -and @($businessEffectAllowedFields) -cnotcontains [string]$policyField) {
                [void]$businessEffectAllowedFields.Add([string]$policyField)
            }
        }
        if ($businessEffectPolicy.requiredByEffectType -is [pscustomobject]) {
            foreach ($branchProperty in @($businessEffectPolicy.requiredByEffectType.PSObject.Properties)) {
                foreach ($policyField in @($branchProperty.Value)) {
                    if (Test-NonBlankString $policyField -and @($businessEffectAllowedFields) -cnotcontains [string]$policyField) {
                        [void]$businessEffectAllowedFields.Add([string]$policyField)
                    }
                }
            }
        }
    }
    Test-AllowedProperties -Object $Chain.businessEffect -Names @($businessEffectAllowedFields) -Context 'businessEffect' -Errors $errors
    Test-AllowedProperties -Object $Chain.recommendation -Names @(
        'verdictRef', 'fleetVerdictPointer', 'personaVerdictPointer',
        'procurementEnvelopePointer', 'claimRecordRef', 'statementPointer', 'action', 'statement', 'freshness'
    ) -Context 'recommendation' -Errors $errors

    if (-not (Test-ObservationWindow -Value $Chain.currentFleetIssue.observationWindow -EvaluationTime $EvaluationTime)) {
        Add-BlueprintError -Errors $errors -Code 'INVALID_OBSERVATION_WINDOW' -Message 'currentFleetIssue observationWindow must be a closed, non-future ISO date interval.'
    }

    foreach ($linkName in @('personaNeed', 'currentFleetIssue', 'candidateComparison')) {
        foreach ($evidenceRef in @($Chain.$linkName.evidenceRefs)) {
            if ($evidenceRef -isnot [string] -or [string]::IsNullOrWhiteSpace([string]$evidenceRef)) {
                Add-BlueprintError -Errors $errors -Code 'INVALID_RECORD_REF' -Message "$linkName contains a null or blank evidence reference."
            }
        }
        foreach ($provenance in @($Chain.$linkName.provenance)) {
            if ([string]$provenance -cnotin @('T0', 'T1', 'T2')) {
                Add-BlueprintError -Errors $errors -Code 'INVALID_PROVENANCE' -Message "$linkName contains unsupported provenance."
            }
        }
    }

    $businessEffectType = [string]$Chain.businessEffect.effectType
    $businessEffectPolicyValid = $null -ne $businessEffectPolicy -and
        [string]$businessEffectPolicy.branchSelector -ceq 'effectType' -and
        $businessEffectPolicy.requiredFields -is [System.Collections.IList] -and
        $businessEffectPolicy.freshnessRequiredFields -is [System.Collections.IList] -and
        $businessEffectPolicy.statusByEffectType -is [pscustomobject] -and
        $businessEffectPolicy.requiredByEffectType -is [pscustomobject] -and
        $businessEffectPolicy.forbiddenByEffectType -is [pscustomobject]
    $requiredBusinessEffectFields = @()
    $forbiddenBusinessEffectFields = @()
    $expectedBusinessEffectStatus = ''
    if ($businessEffectPolicyValid) {
        $requiredBranchProperty = $businessEffectPolicy.requiredByEffectType.PSObject.Properties[$businessEffectType]
        $forbiddenBranchProperty = $businessEffectPolicy.forbiddenByEffectType.PSObject.Properties[$businessEffectType]
        $statusProperty = $businessEffectPolicy.statusByEffectType.PSObject.Properties[$businessEffectType]
        $businessEffectPolicyValid = $null -ne $requiredBranchProperty -and
            $requiredBranchProperty.Value -is [System.Collections.IList] -and
            $null -ne $forbiddenBranchProperty -and
            $forbiddenBranchProperty.Value -is [System.Collections.IList] -and
            $null -ne $statusProperty -and
            (Test-NonBlankString $statusProperty.Value)
        if ($businessEffectPolicyValid) {
            $requiredBusinessEffectFields = @($businessEffectPolicy.requiredFields) + @($requiredBranchProperty.Value)
            $forbiddenBusinessEffectFields = @($forbiddenBranchProperty.Value)
            $expectedBusinessEffectStatus = [string]$statusProperty.Value
            if (@($requiredBusinessEffectFields | Where-Object { -not (Test-NonBlankString $_) }).Count -gt 0 -or
                @($requiredBusinessEffectFields | Group-Object -CaseSensitive | Where-Object Count -gt 1).Count -gt 0 -or
                @($forbiddenBusinessEffectFields | Where-Object { -not (Test-NonBlankString $_) }).Count -gt 0 -or
                @($forbiddenBusinessEffectFields | Group-Object -CaseSensitive | Where-Object Count -gt 1).Count -gt 0 -or
                @($requiredBusinessEffectFields | Where-Object { $forbiddenBusinessEffectFields -ccontains [string]$_ }).Count -gt 0) {
                $businessEffectPolicyValid = $false
            }
        }
    }
    if (-not $businessEffectPolicyValid) {
        Add-BlueprintError -Errors $errors -Code 'BUSINESS_EFFECT_MACHINE_POLICY_INVALID' -Message 'The frozen businessEffect policy lacks a resolvable effect branch, status mapping, or disjoint required and forbidden field sets.'
    }
    else {
        Test-RequiredProperties -Object $Chain.businessEffect -Names $requiredBusinessEffectFields -Context "$businessEffectType businessEffect" -Errors $errors
        Test-RequiredProperties -Object $Chain.businessEffect.freshness -Names @($businessEffectPolicy.freshnessRequiredFields) -Context "$businessEffectType businessEffect freshness" -Errors $errors
        foreach ($forbiddenField in $forbiddenBusinessEffectFields) {
            if (Test-ValuePresent $Chain.businessEffect.$forbiddenField) {
                Add-BlueprintError -Errors $errors -Code 'BUSINESS_EFFECT_FORBIDDEN_FIELD_PRESENT' -Message "$businessEffectType businessEffect carries a field forbidden by the frozen machine policy."
            }
        }
        if ([string]$Chain.businessEffect.status -cne $expectedBusinessEffectStatus) {
            Add-BlueprintError -Errors $errors -Code 'INVALID_BUSINESS_EFFECT_STATUS' -Message 'businessEffect status does not match the frozen effectType branch policy.'
        }
    }
    if ($businessEffectType -cnotin @('COST_DELTA', 'NON_PRICE_EFFECT', 'NOT_MEASURED')) {
        Add-BlueprintError -Errors $errors -Code 'BUSINESS_EFFECT_TYPE_MISMATCH' -Message 'businessEffect effectType is not a frozen machine-policy branch.'
    }
    if ([string]$Chain.businessEffect.status -ceq 'MEASURED') {
        if (-not (Test-ObservationWindow -Value $Chain.businessEffect.observationWindow -EvaluationTime $EvaluationTime)) {
            Add-BlueprintError -Errors $errors -Code 'INVALID_OBSERVATION_WINDOW' -Message 'Measured businessEffect requires a closed, non-future ISO date interval.'
        }
    }
    elseif ([string]$Chain.businessEffect.status -ceq 'NOT_MEASURED') {
        if ([string]$Chain.businessEffect.statement -cne 'NOT_MEASURED: No non-price business effect is claimed for this decision.' -or
            [string]$Chain.businessEffect.decisionImpact -cne 'No non-price benefit may support this recommendation; only current commercial quotes and the issued verdict remain decision inputs.' -or
            @($Chain.businessEffect.assumptions).Count -ne 1 -or
            [string]$Chain.businessEffect.assumptions[0] -cne 'No non-price business-effect estimate is available.') {
            Add-BlueprintError -Errors $errors -Code 'UNMEASURED_BUSINESS_EFFECT_MISREPRESENTED' -Message 'NOT_MEASURED must use the controlled no-benefit statement, assumption, and decision impact and carry no invented business-effect evidence.'
        }
    }

    $allEvidenceRefs = @($Chain.personaNeed.evidenceRefs) + @($Chain.currentFleetIssue.evidenceRefs) + @($Chain.candidateComparison.evidenceRefs)
    if ([string]$Chain.businessEffect.status -ceq 'MEASURED') { $allEvidenceRefs += @($Chain.businessEffect.evidenceRefs) }
    foreach ($evidenceRef in $allEvidenceRefs) {
        if ([string]$evidenceRef -match '(?i)(leadership-brief|persona-fit|spec-sheet|README)\.md$') {
            Add-BlueprintError -Errors $errors -Code 'DERIVED_DOCUMENT_AS_EVIDENCE' -Message "Derived document $evidenceRef cannot support a leadership claim."
        }
    }

    if ([string]$Chain.currentFleetIssue.incumbentControlRef -cne [string]$Chain.candidateComparison.incumbentControlRef) {
        Add-BlueprintError -Errors $errors -Code 'INCUMBENT_REF_MISMATCH' -Message 'Current-fleet issue and candidate comparison cite different incumbent controls.'
    }
    if ([string]$Chain.currentFleetIssue.baselineFingerprint -cne [string]$Chain.candidateComparison.baselineFingerprint) {
        Add-BlueprintError -Errors $errors -Code 'COMPARISON_BASELINE_MISMATCH' -Message 'Candidate and incumbent baselines differ.'
    }
    if ([string]$Chain.personaNeed.personaVerdictPointer -cne [string]$Chain.recommendation.personaVerdictPointer) {
        Add-BlueprintError -Errors $errors -Code 'PERSONA_VERDICT_POINTER_MISMATCH' -Message 'Persona need and recommendation cite different persona verdict pointers.'
    }
    if ([string]$Chain.personaNeed.capacityWaterfallPointer -cne ([string]$Chain.personaNeed.personaVerdictPointer + '/capacityWaterfall')) {
        Add-BlueprintError -Errors $errors -Code 'CAPACITY_WATERFALL_POINTER_MISMATCH' -Message 'Capacity waterfall must be the capacityWaterfall child of the selected persona verdict.'
    }
    if ([string]$Chain.recommendation.fleetVerdictPointer -cne ([string]$Chain.recommendation.verdictRef + '#/fleetVerdict') -or
        -not ([string]$Chain.recommendation.personaVerdictPointer).StartsWith(([string]$Chain.recommendation.verdictRef + '#/personaVerdicts/'), [System.StringComparison]::Ordinal) -or
        [string]$Chain.recommendation.procurementEnvelopePointer -cne ([string]$Chain.recommendation.verdictRef + '#/procurementEnvelope')) {
        Add-BlueprintError -Errors $errors -Code 'VERDICT_POINTER_SET_MISMATCH' -Message 'Fleet, persona, and procurement pointers must resolve into their exact properties in one verdict record.'
    }

    $requiredConditionRefs = @($Chain.candidateComparison.conditionRefs)
    if ($requiredConditionRefs.Count -eq 0 -or @($requiredConditionRefs | Where-Object { $_ -isnot [string] -or [string]::IsNullOrWhiteSpace([string]$_) }).Count -gt 0) {
        Add-BlueprintError -Errors $errors -Code 'COMPARISON_CONDITION_SET_INVALID' -Message 'Candidate comparison requires a non-empty frozen condition reference set.'
    }
    foreach ($conditionGroup in @($requiredConditionRefs | Group-Object -CaseSensitive)) {
        if ($conditionGroup.Count -gt 1) {
            Add-BlueprintError -Errors $errors -Code 'COMPARISON_CONDITION_SET_INVALID' -Message "Candidate comparison repeats condition $($conditionGroup.Name)."
        }
    }

    $recordMap = Get-CanonicalRecordMap -RecordIndex $RecordIndex -Errors $errors -Context 'issued leadership chain' `
        -EvaluationTime $EvaluationTime -ValidationProfile $ValidationProfile

    $manifestRecord = Resolve-CanonicalRecord -RecordMap $recordMap -Reference $Chain.personaNeed.manifestRef -ExpectedTypes @('candidate-manifest') -Context 'persona manifest' -Errors $errors
    [void](Resolve-CanonicalRecord -RecordMap $recordMap -Reference $Chain.personaNeed.capacityWaterfallPointer -ExpectedTypes @('verdict-record') -Context 'capacity waterfall' -Errors $errors)
    [void](Resolve-CanonicalRecord -RecordMap $recordMap -Reference $Chain.personaNeed.personaVerdictPointer -ExpectedTypes @('verdict-record') -Context 'persona verdict' -Errors $errors)
    $personaEvidenceRelease = Resolve-CanonicalRecord -RecordMap $recordMap -Reference $Chain.personaNeed.evidenceReleaseRef -ExpectedTypes @('evidence-release') -Context 'persona evidence release' -Errors $errors
    [void](Resolve-CanonicalRecord -RecordMap $recordMap -Reference $Chain.currentFleetIssue.incumbentControlRef -ExpectedTypes @('candidate-manifest') -Context 'current incumbent' -Errors $errors)
    $currentFleetCohortRecord = Resolve-CanonicalRecord -RecordMap $recordMap -Reference $Chain.currentFleetIssue.cohortRef -ExpectedTypes @('cohort-record') -Context 'current fleet cohort' -Errors $errors
    $fleetPortfolioRecord = Resolve-CanonicalRecord -RecordMap $recordMap -Reference $Chain.currentFleetIssue.fleetPortfolioRef -ExpectedTypes @('fleet-portfolio-record') -Context 'current fleet portfolio' -Errors $errors
    [void](Resolve-CanonicalRecord -RecordMap $recordMap -Reference $Chain.currentFleetIssue.fleetPortfolioCohortPointer -ExpectedTypes @('fleet-portfolio-record') -Context 'current fleet portfolio cohort' -Errors $errors)
    $fleetEvidenceRelease = Resolve-CanonicalRecord -RecordMap $recordMap -Reference $Chain.currentFleetIssue.evidenceReleaseRef -ExpectedTypes @('evidence-release') -Context 'current fleet evidence release' -Errors $errors
    if ($null -ne $fleetPortfolioRecord) {
        Test-RequiredProperties -Object $fleetPortfolioRecord -Names @(
            'schemaVersion', 'recordStage', 'status', 'snapshotAt', 'observationWindow',
            'populationCohortRef', 'joinPolicyRef', 'joinPolicyDigest', 'queryPackRef', 'queryPackDigest', 'privacyPolicyRef',
            'privacyPolicyDigest', 'privacyReleaseRef', 'privacyReleaseDigest', 'aggregationFloor',
            'privacyAggregationFloorPointer', 'privacyAggregationFloorDigest',
            'minimumCoveragePointer', 'minimumCoverageValueDigest', 'minimumCoveragePct',
            'coverage', 'configurationCohorts', 'configurationPartitionProofRef', 'configurationPartitionProofDigest',
            'sourceRecordCount', 'uniqueDeviceCount', 'duplicateRecordCount', 'staleDeviceCount',
            'retiredDeviceCount', 'offlineDeviceCount', 'unhealthyDeviceCount', 'joinEligibleDeviceCount',
            'joinedDeviceCount', 'unjoinableDeviceCount', 'matchedDeviceCount', 'unmatchedDeviceCount',
            'reconciliationMethod', 'reconciliationStatus', 'reconciliationEvidenceRef',
            'reconciliationEvidenceDigest', 'sourceEvidenceReleaseBindings', 'dimensionCoverage', 'freshnessBinding'
        ) -Context 'fleet portfolio record' -Errors $errors
        $fleetQueryPack = Resolve-CanonicalRecord -RecordMap $recordMap -Reference $fleetPortfolioRecord.queryPackRef -ExpectedTypes @('query-pack-record') -Context 'fleet portfolio query pack' -Errors $errors
        $fleetGovernance = Get-FleetPortfolioGovernanceBinding -FleetPortfolio $fleetPortfolioRecord -Chain $Chain `
            -RecordMap $recordMap -ValidationProfile $ValidationProfile -Errors $errors
        [void](Test-FleetCoveragePopulationCommitment -Coverage $fleetPortfolioRecord.coverage `
            -ExpectedPurpose 'PORTFOLIO_COVERAGE' `
            -ExpectedDomainDigest (Get-FleetPortfolioCoverageDomainDigest -FleetPortfolio $fleetPortfolioRecord) `
            -ParentCoverage $null -Governance $fleetGovernance -Context 'fleet portfolio' -Errors $errors)
        [void](Register-FleetPopulationProofBinding -Reference $fleetPortfolioRecord.configurationPartitionProofRef `
            -Digest $fleetPortfolioRecord.configurationPartitionProofDigest -Governance $fleetGovernance `
            -Context 'fleet configuration partition' -Errors $errors)
        if ([string]$fleetPortfolioRecord.schemaVersion -cne '1.0.0' -or
            [string]$fleetPortfolioRecord.recordStage -cne 'CURRENT_FLEET_PORTFOLIO' -or
            [string]$fleetPortfolioRecord.status -cne 'ISSUED' -or
            [string]$fleetPortfolioRecord.joinPolicyRef -cnotmatch '^private://' -or
            -not (Test-Sha256Token $fleetPortfolioRecord.joinPolicyDigest) -or
            ($null -ne $fleetQueryPack -and [string]$fleetQueryPack.contentDigest -cne [string]$fleetPortfolioRecord.queryPackDigest) -or
            [string]$fleetPortfolioRecord.privacyPolicyRef -cnotmatch '^private://' -or
            [string]$fleetPortfolioRecord.privacyReleaseRef -cnotmatch '^private://' -or
            [string]$fleetPortfolioRecord.reconciliationMethod -cne 'MUTUALLY_EXCLUSIVE_PRECEDENCE_V1' -or
            [string]$fleetPortfolioRecord.reconciliationStatus -cne 'PASS' -or
            [string]$fleetPortfolioRecord.reconciliationEvidenceRef -cnotmatch '^private://' -or
            -not (Test-Sha256Token $fleetPortfolioRecord.reconciliationEvidenceDigest) -or
            @($fleetPortfolioRecord.configurationCohorts).Count -eq 0) {
            Add-BlueprintError -Errors $errors -Code 'FLEET_PORTFOLIO_RECORD_MISMATCH' -Message 'The fleet portfolio must be an issued, private-policy-bound operations record with one or more configuration cohorts.'
        }
        $populationCohortRecord = Resolve-CanonicalRecord -RecordMap $recordMap -Reference $fleetPortfolioRecord.populationCohortRef `
            -ExpectedTypes @('cohort-record') -Context 'fleet portfolio population cohort' -Errors $errors
        if ([string]$fleetPortfolioRecord.populationCohortRef -cne [string]$Chain.currentFleetIssue.cohortRef -or
            ($null -ne $currentFleetCohortRecord -and $null -ne $populationCohortRecord -and
             [string]$currentFleetCohortRecord.contentDigest -cne [string]$populationCohortRecord.contentDigest)) {
            Add-BlueprintError -Errors $errors -Code 'FLEET_PORTFOLIO_POPULATION_COHORT_MISMATCH' -Message 'The portfolio population cohort must be the exact cohort used by the current-fleet issue.'
        }

        $portfolioPrefix = [string]$Chain.currentFleetIssue.fleetPortfolioRef + '#'
        $portfolioPointer = [string]$Chain.currentFleetIssue.fleetPortfolioCohortPointer
        $portfolioPointerFound = $false
        $selectedPortfolioCohort = if ($portfolioPointer.StartsWith($portfolioPrefix, [System.StringComparison]::Ordinal)) {
            Get-JsonPointerValue -Document $fleetPortfolioRecord.payload -Pointer $portfolioPointer.Substring($portfolioPrefix.Length) -Found ([ref]$portfolioPointerFound)
        }
        else { $null }
        if (-not $portfolioPointerFound -or $selectedPortfolioCohort -isnot [pscustomobject] -or
            $portfolioPointer -cnotmatch ([regex]::Escape($portfolioPrefix) + '/configurationCohorts/\d+$')) {
            Add-BlueprintError -Errors $errors -Code 'FLEET_PORTFOLIO_COHORT_POINTER_INVALID' -Message 'fleetPortfolioCohortPointer must resolve to one configurationCohorts row inside fleetPortfolioRef.'
        }
        else {
            Test-RequiredProperties -Object $selectedPortfolioCohort -Names @(
                'configurationRef', 'cohortRef', 'observedDeviceCount', 'unknownComponentIdentityCount',
                'observedPopulationDigest', 'personaAllocations', 'unassignedPersonaCount', 'unassignedPopulationDigest',
                'populationSubsetProofRef', 'populationSubsetProofDigest', 'personaPartitionProofRef',
                'personaPartitionProofDigest', 'proofScheme', 'proofVersion', 'populationCommitmentKeyRef',
                'populationCommitmentKeyVersion', 'populationCanonicalization', 'populationCanonicalizationVersion',
                'populationCommitmentPurpose', 'populationCommitmentDomainDigest', 'lifecycleEvidenceRefs',
                'platformEvidenceRefs', 'issueEvidenceRefs'
            ) -Context 'selected fleet portfolio cohort' -Errors $errors
            if ([string]$selectedPortfolioCohort.configurationRef -cne [string]$Chain.currentFleetIssue.incumbentControlRef -or
                [string]$selectedPortfolioCohort.cohortRef -cne [string]$Chain.currentFleetIssue.cohortRef) {
                Add-BlueprintError -Errors $errors -Code 'FLEET_PORTFOLIO_COHORT_BINDING_MISMATCH' -Message 'The selected fleet-portfolio row must be the exact incumbent configuration and persona-specific cohort used by the current-fleet issue.'
            }
            $selectedPersonaAllocations = @($selectedPortfolioCohort.personaAllocations | Where-Object { [string]$_.personaId -ceq [string]$Chain.personaNeed.personaId })
            if ($selectedPersonaAllocations.Count -ne 1) {
                Add-BlueprintError -Errors $errors -Code 'FLEET_PORTFOLIO_PERSONA_BINDING_MISMATCH' -Message 'The selected fleet-portfolio cohort must contain the exact recommended persona once.'
            }
            $fleetStatementRecordId = ([string]$Chain.currentFleetIssue.issueStatementPointer).Split('#', 2)[0]
            if (@($selectedPortfolioCohort.issueEvidenceRefs) -cnotcontains $fleetStatementRecordId) {
                Add-BlueprintError -Errors $errors -Code 'FLEET_PORTFOLIO_EVIDENCE_UNRELEASED' -Message 'The selected fleet-portfolio cohort does not retain the current-fleet issue evidence.'
            }
        }

        [DateTimeOffset]$portfolioSnapshotAt = [DateTimeOffset]::MinValue
        $windowValid = Test-ObservationWindow -Value $fleetPortfolioRecord.observationWindow -EvaluationTime $EvaluationTime
        $windowEndText = if ([string]$fleetPortfolioRecord.observationWindow -cmatch '^\d{4}-\d{2}-\d{2}/(\d{4}-\d{2}-\d{2})$') { [string]$Matches[1] } else { '' }
        [DateTimeOffset]$windowEnd = [DateTimeOffset]::MinValue
        if (-not [OperationsBlueprint.StrictRfc3339]::TryParse([string]$fleetPortfolioRecord.snapshotAt, [ref]$portfolioSnapshotAt) -or
            $portfolioSnapshotAt -gt $EvaluationTime -or -not $windowValid -or
            -not [OperationsBlueprint.StrictIsoDate]::TryParse($windowEndText, [ref]$windowEnd) -or
            $portfolioSnapshotAt.UtcDateTime.Date -ne $windowEnd.UtcDateTime.Date -or
            [string]$fleetPortfolioRecord.observationWindow -cne [string]$Chain.currentFleetIssue.observationWindow -or
            [string]$fleetPortfolioRecord.freshnessBinding.observedAt -cne [string]$fleetPortfolioRecord.snapshotAt) {
            Add-BlueprintError -Errors $errors -Code 'FLEET_PORTFOLIO_FRESHNESS_INVALID' -Message 'Fleet portfolio snapshotAt must equal the current-fleet window end and its source freshness observation.'
        }

        Test-RequiredProperties -Object $fleetPortfolioRecord.coverage -Names @('planned', 'eligible', 'observed', 'missing', 'excluded', 'percent', 'status') -Context 'fleet portfolio coverage' -Errors $errors
        $fleetPortfolioCoverageValid = Test-FleetPortfolioCoverageValue -Coverage $fleetPortfolioRecord.coverage `
            -MinimumCoveragePct $fleetGovernance.MinimumCoveragePct -AggregationFloor $fleetGovernance.AggregationFloor `
            -Context 'fleet portfolio' -ErrorCode 'FLEET_PORTFOLIO_COVERAGE_INVALID' -Errors $errors
        $coverageValues = @(
            $fleetPortfolioRecord.coverage.planned, $fleetPortfolioRecord.coverage.eligible, $fleetPortfolioRecord.coverage.observed,
            $fleetPortfolioRecord.coverage.missing, $fleetPortfolioRecord.coverage.excluded,
            $fleetPortfolioRecord.sourceRecordCount, $fleetPortfolioRecord.uniqueDeviceCount,
            $fleetPortfolioRecord.duplicateRecordCount, $fleetPortfolioRecord.staleDeviceCount,
            $fleetPortfolioRecord.retiredDeviceCount, $fleetPortfolioRecord.offlineDeviceCount,
            $fleetPortfolioRecord.unhealthyDeviceCount, $fleetPortfolioRecord.joinEligibleDeviceCount,
            $fleetPortfolioRecord.joinedDeviceCount, $fleetPortfolioRecord.unjoinableDeviceCount,
            $fleetPortfolioRecord.matchedDeviceCount, $fleetPortfolioRecord.unmatchedDeviceCount,
            $fleetPortfolioRecord.aggregationFloor
        )
        $coverageIntegersValid = @($coverageValues | Where-Object { $_ -isnot [int] -and $_ -isnot [long] }).Count -eq 0
        [System.Numerics.BigInteger]$configurationObservedTotal = [System.Numerics.BigInteger]::Zero
        $portfolioCountsValid = $coverageIntegersValid
        if ($coverageIntegersValid) {
            if (@($coverageValues | Where-Object { [int64]$_ -lt 0 }).Count -gt 0) { $portfolioCountsValid = $false }
            foreach ($configurationCohort in @($fleetPortfolioRecord.configurationCohorts)) {
                Test-RequiredProperties -Object $configurationCohort -Names @(
                    'configurationRef', 'cohortRef', 'observedDeviceCount', 'unknownComponentIdentityCount',
                    'observedPopulationDigest', 'personaAllocations', 'unassignedPersonaCount', 'unassignedPopulationDigest',
                    'populationSubsetProofRef', 'populationSubsetProofDigest', 'personaPartitionProofRef',
                    'personaPartitionProofDigest', 'proofScheme', 'proofVersion', 'populationCommitmentKeyRef',
                    'populationCommitmentKeyVersion', 'populationCanonicalization', 'populationCanonicalizationVersion',
                    'populationCommitmentPurpose', 'populationCommitmentDomainDigest', 'lifecycleEvidenceRefs',
                    'platformEvidenceRefs', 'issueEvidenceRefs'
                ) -Context 'fleet portfolio configuration cohort' -Errors $errors
                [void](Test-FleetConfigurationPopulationCommitment -FleetPortfolio $fleetPortfolioRecord `
                    -ConfigurationCohort $configurationCohort -Governance $fleetGovernance `
                    -Context 'fleet portfolio configuration cohort' -Errors $errors)
                $rowCountValues = @($configurationCohort.observedDeviceCount, $configurationCohort.unknownComponentIdentityCount, $configurationCohort.unassignedPersonaCount)
                if (@($rowCountValues | Where-Object { $_ -isnot [int] -and $_ -isnot [long] }).Count -gt 0) {
                    $portfolioCountsValid = $false
                    continue
                }
                $rowObserved = [int64]$configurationCohort.observedDeviceCount
                $rowUnknown = [int64]$configurationCohort.unknownComponentIdentityCount
                $unassigned = [int64]$configurationCohort.unassignedPersonaCount
                if ($rowObserved -lt [int64]$fleetGovernance.AggregationFloor) {
                    $portfolioCountsValid = $false
                    Add-BlueprintError -Errors $errors -Code 'FLEET_PORTFOLIO_PRIVACY_FLOOR_INVALID' -Message 'Every rendered fleet configuration cohort must meet the governed privacy aggregation floor.'
                }
                [System.Numerics.BigInteger]$personaTotal = [System.Numerics.BigInteger]::Zero
                foreach ($personaAllocation in @($configurationCohort.personaAllocations)) {
                    [void](Test-FleetPersonaPopulationCommitment -FleetPortfolio $fleetPortfolioRecord `
                        -ConfigurationCohort $configurationCohort -PersonaAllocation $personaAllocation `
                        -Governance $fleetGovernance -Context 'fleet portfolio persona allocation' -Errors $errors)
                    if (($personaAllocation.observedDeviceCount -isnot [int] -and $personaAllocation.observedDeviceCount -isnot [long]) -or
                        [int64]$personaAllocation.observedDeviceCount -lt 0) { $portfolioCountsValid = $false }
                    else {
                        $personaObserved = [int64]$personaAllocation.observedDeviceCount
                        $personaTotal += [System.Numerics.BigInteger]$personaObserved
                        if ($personaObserved -lt [int64]$fleetGovernance.AggregationFloor) {
                            $portfolioCountsValid = $false
                            Add-BlueprintError -Errors $errors -Code 'FLEET_PORTFOLIO_PRIVACY_FLOOR_INVALID' -Message 'Every rendered fleet persona cohort must meet the governed privacy aggregation floor.'
                        }
                    }
                }
                if ($rowObserved -lt 0 -or $rowUnknown -lt 0 -or $rowUnknown -gt $rowObserved -or
                    $unassigned -lt 0 -or
                    ($personaTotal + [System.Numerics.BigInteger]$unassigned) -ne [System.Numerics.BigInteger]$rowObserved) {
                    $portfolioCountsValid = $false
                }
                $configurationObservedTotal += [System.Numerics.BigInteger]$rowObserved
            }
            $plannedExact = [System.Numerics.BigInteger][int64]$fleetPortfolioRecord.coverage.planned
            $eligibleExact = [System.Numerics.BigInteger][int64]$fleetPortfolioRecord.coverage.eligible
            $observedExact = [System.Numerics.BigInteger][int64]$fleetPortfolioRecord.coverage.observed
            $missingExact = [System.Numerics.BigInteger][int64]$fleetPortfolioRecord.coverage.missing
            $excludedExact = [System.Numerics.BigInteger][int64]$fleetPortfolioRecord.coverage.excluded
            $sourceExact = [System.Numerics.BigInteger][int64]$fleetPortfolioRecord.sourceRecordCount
            $uniqueExact = [System.Numerics.BigInteger][int64]$fleetPortfolioRecord.uniqueDeviceCount
            $duplicateExact = [System.Numerics.BigInteger][int64]$fleetPortfolioRecord.duplicateRecordCount
            $staleExact = [System.Numerics.BigInteger][int64]$fleetPortfolioRecord.staleDeviceCount
            $retiredExact = [System.Numerics.BigInteger][int64]$fleetPortfolioRecord.retiredDeviceCount
            $offlineExact = [System.Numerics.BigInteger][int64]$fleetPortfolioRecord.offlineDeviceCount
            $unhealthyExact = [System.Numerics.BigInteger][int64]$fleetPortfolioRecord.unhealthyDeviceCount
            $joinEligibleExact = [System.Numerics.BigInteger][int64]$fleetPortfolioRecord.joinEligibleDeviceCount
            $joinedExact = [System.Numerics.BigInteger][int64]$fleetPortfolioRecord.joinedDeviceCount
            $unjoinableExact = [System.Numerics.BigInteger][int64]$fleetPortfolioRecord.unjoinableDeviceCount
            $matchedExact = [System.Numerics.BigInteger][int64]$fleetPortfolioRecord.matchedDeviceCount
            $unmatchedExact = [System.Numerics.BigInteger][int64]$fleetPortfolioRecord.unmatchedDeviceCount
            if ($plannedExact -le [System.Numerics.BigInteger]::Zero -or
                $eligibleExact -ne ($plannedExact - $excludedExact) -or
                $eligibleExact -ne ($observedExact + $missingExact) -or
                $sourceExact -ne ($uniqueExact + $duplicateExact) -or
                $uniqueExact -ne ($staleExact + $retiredExact + $offlineExact + $unhealthyExact + $joinEligibleExact) -or
                $joinEligibleExact -ne ($joinedExact + $unjoinableExact) -or
                $joinedExact -ne ($matchedExact + $unmatchedExact) -or
                $configurationObservedTotal -ne $matchedExact -or
                $observedExact -ne $joinedExact -or
                [int64]$fleetPortfolioRecord.aggregationFloor -le 0) { $portfolioCountsValid = $false }
        }
        if (-not $portfolioCountsValid) {
            Add-BlueprintError -Errors $errors -Code 'FLEET_PORTFOLIO_COUNT_RECONCILIATION_FAILED' -Message 'Fleet portfolio planned, observed, missing, excluded, configuration, persona, unknown, and unmatched counts must be nonnegative integers and reconcile exactly.'
        }
        if ($null -ne $populationCohortRecord) {
            Test-RequiredProperties -Object $populationCohortRecord -Names @(
                'cohortId', 'asOf', 'personaIds', 'deviceConfigurationRefs', 'population',
                'evidenceReleaseRefs', 'freshnessBinding'
            ) -Context 'fleet portfolio population cohort' -Errors $errors
            Test-RequiredProperties -Object $populationCohortRecord.population -Names @(
                'eligibleUnits', 'observedUnits', 'missingUnits', 'coveragePercent'
            ) -Context 'fleet portfolio population cohort counts' -Errors $errors
            $cohortCountValues = @(
                $populationCohortRecord.population.eligibleUnits,
                $populationCohortRecord.population.observedUnits,
                $populationCohortRecord.population.missingUnits,
                $populationCohortRecord.population.coveragePercent
            )
            $cohortCountsValid = @($cohortCountValues[0..2] | Where-Object { $_ -isnot [int] -and $_ -isnot [long] }).Count -eq 0 -and
                (Test-NumberValue $cohortCountValues[3])
            if ($cohortCountsValid) {
                $eligibleUnits = [int64]$populationCohortRecord.population.eligibleUnits
                $observedUnits = [int64]$populationCohortRecord.population.observedUnits
                $missingUnits = [int64]$populationCohortRecord.population.missingUnits
                $expectedCoverage = if ($eligibleUnits -gt 0) { 100.0 * $observedUnits / $eligibleUnits } else { -1.0 }
                $cohortFloorMet = $eligibleUnits -gt 0 -and
                    (([decimal]$observedUnits * [decimal]100) -ge
                     ([decimal]$fleetGovernance.MinimumCoveragePct * [decimal]$eligibleUnits))
                $cohortCountsValid = $eligibleUnits -eq [int64]$fleetPortfolioRecord.coverage.eligible -and
                    $observedUnits -eq [int64]$fleetPortfolioRecord.coverage.observed -and
                    $missingUnits -eq [int64]$fleetPortfolioRecord.coverage.missing -and
                    [System.Numerics.BigInteger]$eligibleUnits -eq
                        ([System.Numerics.BigInteger]$observedUnits + [System.Numerics.BigInteger]$missingUnits) -and
                    [Math]::Abs([double]$populationCohortRecord.population.coveragePercent - $expectedCoverage) -le 0.01 -and
                    $cohortFloorMet -and $observedUnits -ge [int64]$fleetGovernance.AggregationFloor
            }
            if (-not $cohortCountsValid) {
                Add-BlueprintError -Errors $errors -Code 'FLEET_PORTFOLIO_POPULATION_COHORT_MISMATCH' -Message 'Population-cohort eligible, observed, missing, and coverage values must reconcile exactly to the fleet portfolio.'
            }
            $portfolioConfigurationRefs = @($fleetPortfolioRecord.configurationCohorts | ForEach-Object { [string]$_.configurationRef } | Select-Object -Unique)
            $portfolioPersonaIds = @($fleetPortfolioRecord.configurationCohorts | ForEach-Object { @($_.personaAllocations) } | ForEach-Object { [string]$_.personaId } | Select-Object -Unique)
            foreach ($configurationRef in $portfolioConfigurationRefs) {
                if (@($populationCohortRecord.deviceConfigurationRefs) -cnotcontains [string]$configurationRef) {
                    Add-BlueprintError -Errors $errors -Code 'FLEET_PORTFOLIO_DIMENSION_SET_INCOMPLETE' -Message 'Population cohort omits a configuration represented in the fleet portfolio.'
                }
            }
            foreach ($personaId in $portfolioPersonaIds) {
                if (@($populationCohortRecord.personaIds) -cnotcontains [string]$personaId) {
                    Add-BlueprintError -Errors $errors -Code 'FLEET_PORTFOLIO_DIMENSION_SET_INCOMPLETE' -Message 'Population cohort omits a persona represented in the fleet portfolio.'
                }
            }
        }
        if (-not $fleetPortfolioCoverageValid -or [string]$fleetPortfolioRecord.coverage.status -cne 'PASS') {
            Add-BlueprintError -Errors $errors -Code 'FLEET_PORTFOLIO_COVERAGE_INVALID' -Message 'Purchase-ready fleet portfolio coverage must be PASS.'
        }
        Test-FleetPortfolioDimensionSemantics -FleetPortfolio $fleetPortfolioRecord -Chain $Chain `
            -RecordMap $recordMap -Governance $fleetGovernance -EvaluationTime $EvaluationTime `
            -LineageGeneratedAt $lineageGeneratedAt -Errors $errors
        $selectedPersonaObservedValid = $selectedPersonaAllocations.Count -eq 1 -and
            ($selectedPersonaAllocations[0].observedDeviceCount -is [int] -or
             $selectedPersonaAllocations[0].observedDeviceCount -is [long])
        if ($selectedPortfolioCohort -is [pscustomobject] -and $selectedPersonaAllocations.Count -eq 1 -and
            (-not $selectedPersonaObservedValid -or
             [int64]$selectedPersonaAllocations[0].observedDeviceCount -lt [int64]$fleetGovernance.AggregationFloor)) {
            Add-BlueprintError -Errors $errors -Code 'FLEET_PORTFOLIO_PRIVACY_FLOOR_INVALID' -Message 'The selected persona cohort does not meet the approved fleet-portfolio aggregation floor.'
        }

        foreach ($configurationGroup in @($fleetPortfolioRecord.configurationCohorts | Group-Object { ([string]$_.configurationRef) + '::' + ([string]$_.cohortRef) } -CaseSensitive)) {
            if ($configurationGroup.Count -gt 1) {
                Add-BlueprintError -Errors $errors -Code 'FLEET_PORTFOLIO_CONFIGURATION_DUPLICATE' -Message 'Fleet portfolio configuration/cohort pairs must be ordinally unique.'
            }
        }
        foreach ($configurationCohort in @($fleetPortfolioRecord.configurationCohorts)) {
            [void](Resolve-CanonicalRecord -RecordMap $recordMap -Reference $configurationCohort.configurationRef -ExpectedTypes @('candidate-manifest') -Context 'fleet portfolio configuration' -Errors $errors)
            [void](Resolve-CanonicalRecord -RecordMap $recordMap -Reference $configurationCohort.cohortRef -ExpectedTypes @('cohort-record') -Context 'fleet portfolio configuration cohort' -Errors $errors)
            foreach ($personaGroup in @($configurationCohort.personaAllocations | Group-Object -Property personaId -CaseSensitive)) {
                if ($personaGroup.Count -gt 1) {
                    Add-BlueprintError -Errors $errors -Code 'FLEET_PORTFOLIO_CONFIGURATION_DUPLICATE' -Message 'Fleet portfolio persona allocations must be ordinally unique within each configuration cohort.'
                }
            }
        }

        $portfolioReleases = @()
        $portfolioReleaseBindings = @($fleetPortfolioRecord.sourceEvidenceReleaseBindings)
        if ($portfolioReleaseBindings.Count -eq 0 -or
            @($portfolioReleaseBindings | Group-Object -Property recordRef -CaseSensitive | Where-Object Count -gt 1).Count -gt 0 -or
            @($portfolioReleaseBindings | Group-Object { ([string]$_.recordRef) + '::' + ([string]$_.contentDigest) } -CaseSensitive | Where-Object Count -gt 1).Count -gt 0) {
            Add-BlueprintError -Errors $errors -Code 'FLEET_PORTFOLIO_RELEASE_SET_INVALID' -Message 'Fleet portfolio source evidence releases must be ordinally unique.'
        }
        foreach ($releaseBinding in $portfolioReleaseBindings) {
            Test-RequiredProperties -Object $releaseBinding -Names @('recordRef','contentDigest') -Context 'fleet portfolio source release binding' -Errors $errors
            $portfolioRelease = Resolve-CanonicalRecord -RecordMap $recordMap -Reference $releaseBinding.recordRef -ExpectedTypes @('evidence-release') -Context 'fleet portfolio source release' -Errors $errors
            if ($null -ne $portfolioRelease -and [string]$portfolioRelease.contentDigest -ceq [string]$releaseBinding.contentDigest) {
                $portfolioReleases += $portfolioRelease
                Test-EvidenceReleaseBinding -ReleaseRecord $portfolioRelease -EvidenceRecords @() -RecordMap $recordMap `
                    -EvaluationTime $EvaluationTime -ConsumerRecord $verdictRecord -Manifest $manifestRecord `
                    -Phase0TestPlan $testPlanRecord -ThresholdPolicy $frozenThresholdPolicyRecord `
                    -ValidationProfile $ValidationProfile -Context 'fleet portfolio source' -Errors $errors
                [DateTimeOffset]$portfolioPolicyAt = [DateTimeOffset]::MinValue
                [DateTimeOffset]$portfolioReleaseAt = [DateTimeOffset]::MinValue
                [DateTimeOffset]$portfolioWindowEnd = [DateTimeOffset]::MinValue
                $portfolioReleaseWindowValid = [OperationsBlueprint.StrictRfc3339]::TryParse([string]$fleetPortfolioRecord.dimensionCoverage.policyExecutedAt, [ref]$portfolioPolicyAt) -and
                    [string]$fleetPortfolioRecord.observationWindow -cmatch '^\d{4}-\d{2}-\d{2}/(\d{4}-\d{2}-\d{2})$' -and
                    [OperationsBlueprint.StrictIsoDate]::TryParse([string]$Matches[1], [ref]$portfolioWindowEnd) -and
                    [OperationsBlueprint.StrictRfc3339]::TryParse([string]$portfolioRelease.releasedAt, [ref]$portfolioReleaseAt) -and
                    $portfolioReleaseAt -ge $portfolioWindowEnd -and $portfolioReleaseAt -le $portfolioPolicyAt
                if (-not $portfolioReleaseWindowValid) {
                    Add-BlueprintError -Errors $errors -Code 'FLEET_PORTFOLIO_RELEASE_SET_INVALID' -Message 'Fleet portfolio source release must be current and issued after the observation window and before dimension-policy execution.'
                }
                Test-FleetSourceFreshnessBinding -SourceFreshness $portfolioRelease.freshnessBinding `
                    -GovernedFreshness $fleetPortfolioRecord.freshnessBinding `
                    -ObservationWindow ([string]$fleetPortfolioRecord.observationWindow) `
                    -PolicyExecutedAt $portfolioPolicyAt -EvaluationTime $EvaluationTime `
                    -Context 'fleet portfolio source release' -Errors $errors
            }
            else {
                Add-BlueprintError -Errors $errors -Code 'FLEET_PORTFOLIO_RELEASE_SET_INVALID' -Message 'Fleet portfolio source release binding does not match the current canonical evidence-release digest.'
            }
        }
        if (@($portfolioReleaseBindings | Where-Object {
            [string]$_.recordRef -ceq [string]$Chain.currentFleetIssue.evidenceReleaseRef -and
            $null -ne $fleetEvidenceRelease -and [string]$_.contentDigest -ceq [string]$fleetEvidenceRelease.contentDigest
        }).Count -ne 1) {
            Add-BlueprintError -Errors $errors -Code 'FLEET_PORTFOLIO_EVIDENCE_UNRELEASED' -Message 'Fleet portfolio source releases omit the selected current-fleet evidence release.'
        }
        $portfolioEvidenceRefs = @()
        foreach ($configurationCohort in @($fleetPortfolioRecord.configurationCohorts)) {
            $portfolioEvidenceRefs += @($configurationCohort.lifecycleEvidenceRefs)
            $portfolioEvidenceRefs += @($configurationCohort.platformEvidenceRefs)
            $portfolioEvidenceRefs += @($configurationCohort.issueEvidenceRefs)
        }
        foreach ($evidenceRef in @($portfolioEvidenceRefs | Select-Object -Unique)) {
            $portfolioEvidenceRecord = Resolve-CanonicalRecord -RecordMap $recordMap -Reference $evidenceRef -ExpectedTypes @('evidence-record') -Context 'fleet portfolio evidence' -Errors $errors
            if (@($portfolioReleases | Where-Object { @($_.memberRecordIds) -ccontains [string]$evidenceRef }).Count -eq 0) {
                Add-BlueprintError -Errors $errors -Code 'FLEET_PORTFOLIO_EVIDENCE_UNRELEASED' -Message "Fleet portfolio evidence $evidenceRef is not a member of a declared source release."
            }
            if ($null -ne $portfolioEvidenceRecord -and
                ([string]$portfolioEvidenceRecord.cohortRef -cne [string]$Chain.currentFleetIssue.cohortRef -or
                 [string]$portfolioEvidenceRecord.observationWindow -cne [string]$fleetPortfolioRecord.observationWindow)) {
                Add-BlueprintError -Errors $errors -Code 'FLEET_PORTFOLIO_EVIDENCE_DIMENSION_MISMATCH' -Message 'Fleet portfolio evidence must bind the exact population cohort and observation window.'
            }
        }
    }
    $fleetIssueStatementRecord = Resolve-CanonicalRecord -RecordMap $recordMap -Reference $Chain.currentFleetIssue.issueStatementPointer -ExpectedTypes @('evidence-record') -Context 'current fleet issue statement' -Errors $errors
    if ($null -ne $fleetIssueStatementRecord) {
        $statementRecordId = ([string]$Chain.currentFleetIssue.issueStatementPointer).Split('#', 2)[0]
        $statementPointer = if (([string]$Chain.currentFleetIssue.issueStatementPointer).Contains('#')) {
            ([string]$Chain.currentFleetIssue.issueStatementPointer).Split('#', 2)[1]
        }
        else { '' }
        $statementFound = $false
        $sourceStatement = Get-JsonPointerValue -Document $fleetIssueStatementRecord.payload -Pointer $statementPointer -Found ([ref]$statementFound)
        $expectedIssueStatementPointer = $statementRecordId + '#/extensions/operationsBlueprintV1/issueStatement'
        if ([string]$Chain.currentFleetIssue.issueStatementPointer -cne $expectedIssueStatementPointer -or
            @($Chain.currentFleetIssue.evidenceRefs) -cnotcontains $statementRecordId -or
            -not $statementFound -or
            [string]$sourceStatement -cne [string]$Chain.currentFleetIssue.statement -or
            [string]$fleetIssueStatementRecord.attributionClass -cne [string]$Chain.currentFleetIssue.attributionClass -or
            ($null -ne $fleetEvidenceRelease -and @($fleetEvidenceRelease.memberRecordIds) -cnotcontains $statementRecordId)) {
            Add-BlueprintError -Errors $errors -Code 'CURRENT_FLEET_STATEMENT_BINDING_MISMATCH' -Message 'Current-fleet statement is not the exact released issueStatement for the declared evidence record and attribution class.'
        }
    }
    [void](Resolve-CanonicalRecord -RecordMap $recordMap -Reference $Chain.candidateComparison.candidateRef -ExpectedTypes @('candidate-manifest') -Context 'candidate' -Errors $errors)
    [void](Resolve-CanonicalRecord -RecordMap $recordMap -Reference $Chain.candidateComparison.incumbentControlRef -ExpectedTypes @('candidate-manifest') -Context 'comparison incumbent' -Errors $errors)
    [void](Resolve-CanonicalRecord -RecordMap $recordMap -Reference $Chain.candidateComparison.siblingControlRef -ExpectedTypes @('candidate-manifest') -Context 'sibling control' -Errors $errors)
    $testPlanRecord = Resolve-CanonicalRecord -RecordMap $recordMap -Reference $Chain.candidateComparison.testPlanRef -ExpectedTypes @('test-plan') -Context 'test plan' -Errors $errors
    $frozenThresholdPolicyRecord = if ($null -ne $testPlanRecord) {
        Resolve-CanonicalRecord -RecordMap $recordMap -Reference $testPlanRecord.thresholdPolicyRef `
            -ExpectedTypes @('threshold-policy') -Context 'Phase 0 frozen threshold policy' -Errors $errors
    }
    else { $null }
    $candidateEvidenceRelease = Resolve-CanonicalRecord -RecordMap $recordMap -Reference $Chain.candidateComparison.evidenceReleaseRef -ExpectedTypes @('evidence-release') -Context 'candidate comparison evidence release' -Errors $errors
    $manifestPrefix = [string]$Chain.personaNeed.manifestRef + '#'
    if (-not ([string]$Chain.candidateComparison.candidateRef).StartsWith(($manifestPrefix + '/candidateDevices/'), [System.StringComparison]::Ordinal) -or
        [string]$Chain.candidateComparison.incumbentControlRef -cne ($manifestPrefix + '/controls/incumbent') -or
        [string]$Chain.candidateComparison.siblingControlRef -cne ($manifestPrefix + '/controls/sibling-or-alternative')) {
        Add-BlueprintError -Errors $errors -Code 'MANIFEST_SUBJECT_BINDING_MISMATCH' -Message 'Candidate, incumbent, and sibling subjects must be projections from the one frozen persona manifest.'
    }
    if ($null -ne $manifestRecord) {
        Test-RequiredProperties -Object $manifestRecord -Names @(
            'schemaVersion', 'status', 'frozenAt', 'qualificationAuthority', 'testPlanRef', 'thresholdPolicyRef',
            'tenantBoundaryRef', 'targetEnvironmentRef'
        ) -Context 'candidate manifest projection' -Errors $errors
        [DateTimeOffset]$manifestFrozenAt = [DateTimeOffset]::MinValue
        if ([string]$manifestRecord.testPlanRef -cne [string]$Chain.candidateComparison.testPlanRef -or
            [string]$manifestRecord.schemaVersion -cne '2.0.1' -or
            [string]$manifestRecord.status -cne 'frozen' -or
            -not (Test-NonBlankString $manifestRecord.qualificationAuthority) -or
            -not [OperationsBlueprint.StrictRfc3339]::TryParse([string]$manifestRecord.frozenAt, [ref]$manifestFrozenAt) -or
            $manifestFrozenAt -gt $EvaluationTime) {
            Add-BlueprintError -Errors $errors -Code 'MANIFEST_TEST_PLAN_MISMATCH' -Message 'Compared subjects do not use a current Phase 0 manifest and test plan frozen before evaluation.'
        }
    }
    $comparisonRequirements = [pscustomobject]@{
        Tuples = [System.Collections.Generic.Dictionary[string,object]]::new([System.StringComparer]::Ordinal)
        ConditionRefs = @()
    }
    if ($null -ne $testPlanRecord) {
        $frozenPlanConditionIds = @(Test-FrozenPhase0TestPlan -TestPlan $testPlanRecord `
            -ExpectedManifestRef ([string]$Chain.personaNeed.manifestRef) -RecordMap $recordMap `
            -EvaluationTime $EvaluationTime -Errors $errors)
        $comparisonRequirements = Get-Phase3CandidateComparisonRequirements -Phase0TestPlan $testPlanRecord `
            -BaselineFingerprint ([string]$Chain.candidateComparison.baselineFingerprint) -Errors $errors
        if ($null -ne $manifestRecord -and
            [string]$testPlanRecord.thresholdPolicyRef -cne [string]$manifestRecord.thresholdPolicyRef) {
            Add-BlueprintError -Errors $errors -Code 'PHASE0_THRESHOLD_POLICY_MISMATCH' -Message 'The test plan and manifest must bind the exact threshold policy frozen in Phase 0.'
        }
        if ($null -eq $frozenThresholdPolicyRecord -or
            [string]$frozenThresholdPolicyRecord.recordId -cne [string]$testPlanRecord.thresholdPolicyRef -or
            ($null -ne $manifestRecord -and [string]$frozenThresholdPolicyRecord.recordId -cne [string]$manifestRecord.thresholdPolicyRef)) {
            Add-BlueprintError -Errors $errors -Code 'PHASE0_THRESHOLD_POLICY_MISMATCH' -Message 'The Phase 0 threshold policy must resolve as the one canonical policy selected by both the frozen test plan and manifest.'
        }
        if (@($comparisonRequirements.ConditionRefs).Count -ne $requiredConditionRefs.Count) {
            Add-BlueprintError -Errors $errors -Code 'TEST_PLAN_CONDITION_SET_MISMATCH' -Message 'Candidate comparison does not bind the exact condition set of Phase 3 frozen test definitions.'
        }
        foreach ($requiredConditionRef in $requiredConditionRefs) {
            if (@($comparisonRequirements.ConditionRefs) -cnotcontains [string]$requiredConditionRef) {
                Add-BlueprintError -Errors $errors -Code 'TEST_PLAN_CONDITION_SET_MISMATCH' -Message "No Phase 3 frozen test definition contains comparison condition $requiredConditionRef."
            }
        }
    }
    $candidateQuoteRecord = $null
    $controlQuoteRecord = $null
    if ([string]$Chain.businessEffect.status -ceq 'NOT_MEASURED') {
        $commercialBasis = Test-CommercialBasis -Chain $Chain -RecordMap $recordMap -EvaluationTime $EvaluationTime -Errors $errors
        $candidateQuoteRecord = $commercialBasis.Candidate
        $controlQuoteRecord = $commercialBasis.Control
    }
    $businessEffectRecord = $null
    $businessEvidenceRelease = $null
    if ([string]$Chain.businessEffect.status -ceq 'MEASURED') {
        $businessEffectRecord = Resolve-CanonicalRecord -RecordMap $recordMap -Reference $Chain.businessEffect.businessEffectPointer -ExpectedTypes @('business-impact-record') -Context 'business effect pointer' -Errors $errors
        $businessEvidenceRelease = Resolve-CanonicalRecord -RecordMap $recordMap -Reference $Chain.businessEffect.evidenceReleaseRef -ExpectedTypes @('evidence-release') -Context 'business effect evidence release' -Errors $errors
        if (-not ([string]$Chain.businessEffect.businessEffectPointer).StartsWith(([string]$Chain.businessEffect.businessEffectRef + '#'), [System.StringComparison]::Ordinal)) {
            Add-BlueprintError -Errors $errors -Code 'BUSINESS_EFFECT_POINTER_MISMATCH' -Message 'businessEffectPointer must point into businessEffectRef.'
        }
        if ($null -ne $businessEffectRecord) {
            $effectiveBusinessEffectType = [string]$businessEffectRecord.effectType
            if ($effectiveBusinessEffectType -cnotin @('COST_DELTA','NON_PRICE_EFFECT') -or
                [string]$businessEffectRecord.recordId -cne [string]$Chain.businessEffect.businessEffectRef -or
                ((Test-ValuePresent $Chain.businessEffect.effectType) -and
                 [string]$Chain.businessEffect.effectType -cne $effectiveBusinessEffectType)) {
                Add-BlueprintError -Errors $errors -Code 'BUSINESS_EFFECT_TYPE_MISMATCH' -Message 'Measured leadership effect type and record identity must match the authoritative COST_DELTA or NON_PRICE_EFFECT record.'
            }
            if ([string]$businessEffectRecord.businessEffectStatement -cne [string]$Chain.businessEffect.statement -or
                [string]$businessEffectRecord.observationWindow -cne [string]$Chain.businessEffect.observationWindow) {
                Add-BlueprintError -Errors $errors -Code 'BUSINESS_EFFECT_BINDING_MISMATCH' -Message 'Business-effect statement or observation window differs from the typed record.'
            }

            if ($effectiveBusinessEffectType -ceq 'COST_DELTA') {
                $commercialBasis = Test-CommercialBasis -Chain $Chain -RecordMap $recordMap -EvaluationTime $EvaluationTime -Errors $errors
                $candidateQuoteRecord = $commercialBasis.Candidate
                $controlQuoteRecord = $commercialBasis.Control
                [void](Resolve-CanonicalRecord -RecordMap $recordMap -Reference $Chain.businessEffect.calculationPointer -ExpectedTypes @('business-impact-record') -Context 'business calculation pointer' -Errors $errors)
                if ([string]$businessEffectRecord.currency -cne [string]$Chain.businessEffect.currency -or
                    [string]$businessEffectRecord.quantity -cne [string]$Chain.businessEffect.quantity -or
                    [string]$businessEffectRecord.candidateQuoteRef -cne [string]$Chain.businessEffect.candidateQuoteRef -or
                    [string]$businessEffectRecord.controlQuoteRef -cne [string]$Chain.businessEffect.controlQuoteRef -or
                    [string]$businessEffectRecord.quoteValidUntil -cne [string]$Chain.businessEffect.quoteValidUntil -or
                    [string]$businessEffectRecord.calculationMethod -cne [string]$Chain.businessEffect.calculationMethod -or
                    [string]$businessEffectRecord.calculationResult -cne [string]$Chain.businessEffect.calculationResult -or
                    [string]$businessEffectRecord.resultUnit -cne [string]$Chain.businessEffect.resultUnit -or
                    [string]$businessEffectRecord.uncertainty -cne [string]$Chain.businessEffect.uncertainty -or
                    -not (Test-CanonicalValueEqual @($businessEffectRecord.assumptions) @($Chain.businessEffect.assumptions))) {
                    Add-BlueprintError -Errors $errors -Code 'BUSINESS_EFFECT_BINDING_MISMATCH' -Message 'COST_DELTA statement, window, assumptions, quotes, calculation, result, or uncertainty differs from the typed record.'
                }
                if (-not ([string]$Chain.businessEffect.calculationPointer).StartsWith(([string]$Chain.businessEffect.businessEffectRef + '#'), [System.StringComparison]::Ordinal)) {
                    Add-BlueprintError -Errors $errors -Code 'BUSINESS_CALCULATION_POINTER_MISMATCH' -Message 'calculationPointer must point into businessEffectRef.'
                }
                if (($Chain.businessEffect.quantity -isnot [int] -and $Chain.businessEffect.quantity -isnot [long] -and $Chain.businessEffect.quantity -isnot [double] -and $Chain.businessEffect.quantity -isnot [decimal]) -or
                    [decimal]$Chain.businessEffect.quantity -le 0 -or
                    ($Chain.businessEffect.calculationResult -isnot [int] -and $Chain.businessEffect.calculationResult -isnot [long] -and $Chain.businessEffect.calculationResult -isnot [double] -and $Chain.businessEffect.calculationResult -isnot [decimal]) -or
                    [string]$Chain.businessEffect.calculationMethod -cne 'candidate-total-minus-control-total' -or
                    [string]$Chain.businessEffect.resultUnit -cne [string]$Chain.businessEffect.currency) {
                    Add-BlueprintError -Errors $errors -Code 'BUSINESS_CALCULATION_INVALID' -Message 'COST_DELTA requires a positive quantity, numeric result, frozen delta method, and result unit equal to currency.'
                }
                if ($null -ne $candidateQuoteRecord -and $null -ne $controlQuoteRecord -and
                    $candidateQuoteRecord.totalPrice -is [ValueType] -and $controlQuoteRecord.totalPrice -is [ValueType] -and
                    $Chain.businessEffect.calculationResult -is [ValueType]) {
                    $expectedCostDelta = [double]$candidateQuoteRecord.totalPrice - [double]$controlQuoteRecord.totalPrice
                    if ([Math]::Abs([double]$Chain.businessEffect.calculationResult - $expectedCostDelta) -gt 0.005) {
                        Add-BlueprintError -Errors $errors -Code 'BUSINESS_CALCULATION_RESULT_MISMATCH' -Message 'COST_DELTA result does not equal candidate total minus incumbent total.'
                    }
                }
            }
            elseif ($effectiveBusinessEffectType -ceq 'NON_PRICE_EFFECT') {
                $controlledNonPriceDecisionImpact = 'This measured non-price effect may support the recommendation only within its stated metric, denominator, observation window, coverage, and limitations; no monetary effect is claimed.'
                if ([string]$Chain.businessEffect.decisionImpact -cne $controlledNonPriceDecisionImpact -or
                    [string]$businessEffectRecord.metricId -cne [string]$Chain.businessEffect.metricId -or
                    [string]$businessEffectRecord.metricUnit -cne [string]$Chain.businessEffect.metricUnit -or
                    [string]$businessEffectRecord.metricDirection -cne [string]$Chain.businessEffect.metricDirection -or
                    [string]$businessEffectRecord.distributionRef -cne [string]$Chain.businessEffect.distributionRef -or
                    [string]$businessEffectRecord.distributionDigest -cne [string]$Chain.businessEffect.distributionDigest -or
                    -not (Test-CanonicalValueEqual $businessEffectRecord.denominator $Chain.businessEffect.denominator) -or
                    -not (Test-CanonicalValueEqual $businessEffectRecord.coverage $Chain.businessEffect.coverage) -or
                    -not (Test-CanonicalValueEqual @($businessEffectRecord.limitations) @($Chain.businessEffect.limitations)) -or
                    -not (Test-CanonicalValueEqual @($businessEffectRecord.sourceRecordBindings) @($Chain.businessEffect.sourceRecordBindings))) {
                    Add-BlueprintError -Errors $errors -Code 'BUSINESS_EFFECT_BINDING_MISMATCH' -Message 'NON_PRICE_EFFECT decision impact, metric, direction, denominator, distribution, coverage, limitations, or source-record bindings differ from the typed record or controlled non-monetary statement.'
                }
                foreach ($businessEvidenceRef in @($Chain.businessEffect.evidenceRefs)) {
                    $businessEvidenceSource = Resolve-CanonicalRecord -RecordMap $recordMap -Reference $businessEvidenceRef -ExpectedTypes @('evidence-record') -Context 'NON_PRICE_EFFECT source evidence' -Errors $errors
                    if ($null -ne $businessEvidenceSource -and
                        @($businessEffectRecord.sourceRecordBindings | Where-Object {
                            [string]$_.recordRef -ceq [string]$businessEvidenceRef -and
                            [string]$_.contentDigest -ceq [string]$businessEvidenceSource.contentDigest
                        }).Count -ne 1) {
                        Add-BlueprintError -Errors $errors -Code 'BUSINESS_EFFECT_SOURCE_BINDING_INVALID' -Message 'Every NON_PRICE_EFFECT leadership evidence reference must have one exact reference-and-digest binding in the typed effect record.'
                    }
                }
            }
        }
    }
    $verdictRecord = Resolve-CanonicalRecord -RecordMap $recordMap -Reference $Chain.recommendation.verdictRef -ExpectedTypes @('verdict-record') -Context 'recommendation verdict' -Errors $errors
    [void](Resolve-CanonicalRecord -RecordMap $recordMap -Reference $Chain.recommendation.fleetVerdictPointer -ExpectedTypes @('verdict-record') -Context 'fleet verdict pointer' -Errors $errors)
    [void](Resolve-CanonicalRecord -RecordMap $recordMap -Reference $Chain.recommendation.personaVerdictPointer -ExpectedTypes @('verdict-record') -Context 'persona verdict pointer' -Errors $errors)
    [void](Resolve-CanonicalRecord -RecordMap $recordMap -Reference $Chain.recommendation.procurementEnvelopePointer -ExpectedTypes @('verdict-record') -Context 'procurement envelope pointer' -Errors $errors)
    $decisionClaimRecord = Resolve-CanonicalRecord -RecordMap $recordMap -Reference $Chain.recommendation.statementPointer -ExpectedTypes @('decision-claim-record') -Context 'rendered recommendation statement' -Errors $errors
    if (-not ([string]$Chain.recommendation.statementPointer).StartsWith(([string]$Chain.recommendation.claimRecordRef + '#'), [System.StringComparison]::Ordinal)) {
        Add-BlueprintError -Errors $errors -Code 'DECISION_CLAIM_POINTER_MISMATCH' -Message 'statementPointer must point into claimRecordRef.'
    }
    if ($null -ne $verdictRecord) {
        $qualificationAuthorityApprovalValidation = $null
        Test-RequiredProperties -Object $verdictRecord -Names @(
            'schemaVersion', 'recordStage', 'status', 'immutableAt', 'manifestRef', 'qualificationAuthority',
            'approvers', 'evidenceReleases', 'qualificationAuthorityApprovalRef',
            'qualificationAuthorityApprovalDigest', 'pilotAuthorizationRecordRef',
            'pilotAuthorizationRecordDigest', 'pilotAuthorization', 'fleetVerdict',
            'fleetDeploymentDisposition', 'personaVerdicts', 'arbitration',
            'procurementEnvelope', 'procurementDisposition', 'residualRisks', 'requalificationTriggers'
        ) -Context 'recommendation verdict' -Errors $errors
        # Unconditional qualification is represented by an explicitly present
        # empty conditions array. Do not conflate that with a missing field.
        if ($null -eq $verdictRecord.PSObject.Properties['conditions']) {
            Add-BlueprintError -Errors $errors -Code 'MISSING_REQUIRED_FIELD' -Message 'recommendation verdict requires conditions.'
        }
        if ([string]$verdictRecord.manifestRef -cne [string]$Chain.personaNeed.manifestRef) {
            Add-BlueprintError -Errors $errors -Code 'VERDICT_MANIFEST_MISMATCH' -Message 'The final verdict is not bound to the frozen manifest used by the persona and comparison links.'
        }
        if ([string]$verdictRecord.schemaVersion -cne '2.0.1' -or
            [string]$verdictRecord.recordStage -cne 'phase5-final' -or
            [string]$verdictRecord.status -cne 'approved-and-immutable' -or
            [string]$verdictRecord.fleetVerdict -cnotin @('QUALIFY', 'QUALIFY_WITH_CONDITIONS', 'HOLD', 'FAIL', 'INCONCLUSIVE') -or
            [string]$verdictRecord.procurementDisposition -cnotin @('APPROVED', 'APPROVED_WITH_CONDITIONS', 'BLOCKED')) {
            Add-BlueprintError -Errors $errors -Code 'FINAL_VERDICT_SEMANTICS_INVALID' -Message 'Recommendation requires a semantically valid Phase 5 final verdict projection.'
        }
        if ($null -eq $manifestRecord -or
            [string]$verdictRecord.qualificationAuthority -cne [string]$manifestRecord.qualificationAuthority -or
            [string]$verdictRecord.qualificationAuthority -cne 'ROLE_QUALIFICATION_AUTHORITY') {
            Add-BlueprintError -Errors $errors -Code 'QUALIFICATION_AUTHORITY_MISMATCH' -Message 'Manifest and verdict must bind the same canonical qualification authority.'
        }
        if ($null -ne $manifestRecord) {
            $qualificationAuthorityApprovalValidation = Test-QualificationAuthorityApprovalSemantics -RecordMap $recordMap `
                -ApprovalRef $verdictRecord.qualificationAuthorityApprovalRef `
                -ApprovalDigest $verdictRecord.qualificationAuthorityApprovalDigest `
                -Verdict $verdictRecord -Manifest $manifestRecord -DecisionScope 'VERDICT_ISSUANCE' `
                -EvaluationTime $EvaluationTime -FailureCode 'QUALIFICATION_AUTHORITY_APPROVAL_INVALID' -Errors $errors
        }

        $pilotVerdict = Resolve-CanonicalRecord -RecordMap $recordMap `
            -Reference $verdictRecord.pilotAuthorizationRecordRef -ExpectedTypes @('verdict-record') `
            -Context 'final-verdict pilot authorization record' -Errors $errors
        if ($null -eq $pilotVerdict -or [string]$pilotVerdict.recordType -cne 'verdict-record' -or
            [string]$pilotVerdict.contentDigest -cne [string]$verdictRecord.pilotAuthorizationRecordDigest -or
            [string]$pilotVerdict.recordStage -cne 'pilot-authorization' -or
            [string]$pilotVerdict.status -cne 'approved-and-immutable' -or
            [string]$pilotVerdict.manifestRef -cne [string]$verdictRecord.manifestRef -or
            [string]$pilotVerdict.qualificationAuthority -cne [string]$verdictRecord.qualificationAuthority -or
            -not (Test-CanonicalValueEqual $pilotVerdict.pilotAuthorization $verdictRecord.pilotAuthorization)) {
            Add-BlueprintError -Errors $errors -Code 'PILOT_AUTHORIZATION_BINDING_INVALID' -Message 'The final verdict must resolve the exact immutable pilot-authorization verdict and digest for the same manifest, authority, and pilot disposition.'
        }
        elseif ($null -ne $manifestRecord) {
            $pilotIssuanceApprovalValidation = Test-QualificationAuthorityApprovalSemantics -RecordMap $recordMap `
                -ApprovalRef $pilotVerdict.qualificationAuthorityApprovalRef `
                -ApprovalDigest $pilotVerdict.qualificationAuthorityApprovalDigest `
                -Verdict $pilotVerdict -Manifest $manifestRecord -DecisionScope 'VERDICT_ISSUANCE' `
                -EvaluationTime $EvaluationTime -FailureCode 'QUALIFICATION_AUTHORITY_APPROVAL_INVALID' -Errors $errors
            if ($null -ne $qualificationAuthorityApprovalValidation -and
                ($null -eq $pilotIssuanceApprovalValidation -or
                 [string]$pilotIssuanceApprovalValidation.Approval.authorityPrincipalId -cne [string]$qualificationAuthorityApprovalValidation.Approval.authorityPrincipalId -or
                 [string]$pilotIssuanceApprovalValidation.Approval.approverSetDigest -cne [string]$qualificationAuthorityApprovalValidation.Approval.approverSetDigest)) {
                Add-BlueprintError -Errors $errors -Code 'QUALIFICATION_AUTHORITY_MISMATCH' -Message 'Pilot and final verdict issuance approvals must use the same canonical authority principal and approver set.'
            }
        }
        if ([string]$verdictRecord.pilotAuthorization.status -ceq 'NOT_REQUIRED') {
            if (-not (Test-NonBlankString $verdictRecord.pilotAuthorization.reason) -or
                $null -eq $manifestRecord) {
                Add-BlueprintError -Errors $errors -Code 'PILOT_NOT_REQUIRED_APPROVAL_INVALID' -Message 'A NOT_REQUIRED pilot disposition requires a nonblank governed reason and scope-specific authority approval.'
            }
            else {
                $pilotNotRequiredApprovalValidation = Test-QualificationAuthorityApprovalSemantics -RecordMap $recordMap `
                    -ApprovalRef $verdictRecord.pilotNotRequiredApprovalRef `
                    -ApprovalDigest $verdictRecord.pilotNotRequiredApprovalDigest `
                    -Verdict $verdictRecord -Manifest $manifestRecord -DecisionScope 'PILOT_NOT_REQUIRED' `
                    -EvaluationTime $EvaluationTime -FailureCode 'PILOT_NOT_REQUIRED_APPROVAL_INVALID' -Errors $errors
                if ($null -ne $qualificationAuthorityApprovalValidation -and
                    ($null -eq $pilotNotRequiredApprovalValidation -or
                     [string]$pilotNotRequiredApprovalValidation.Approval.authorityPrincipalId -cne [string]$qualificationAuthorityApprovalValidation.Approval.authorityPrincipalId -or
                     [string]$pilotNotRequiredApprovalValidation.Approval.approverSetDigest -cne [string]$qualificationAuthorityApprovalValidation.Approval.approverSetDigest)) {
                    Add-BlueprintError -Errors $errors -Code 'PILOT_NOT_REQUIRED_APPROVAL_INVALID' -Message 'Pilot waiver and verdict issuance must use the same canonical authority principal and approver set.'
                }
                if ($null -ne $pilotVerdict) {
                    $pilotVerdictWaiverValidation = Test-QualificationAuthorityApprovalSemantics -RecordMap $recordMap `
                        -ApprovalRef $pilotVerdict.pilotNotRequiredApprovalRef `
                        -ApprovalDigest $pilotVerdict.pilotNotRequiredApprovalDigest `
                        -Verdict $pilotVerdict -Manifest $manifestRecord -DecisionScope 'PILOT_NOT_REQUIRED' `
                        -EvaluationTime $EvaluationTime -FailureCode 'PILOT_NOT_REQUIRED_APPROVAL_INVALID' -Errors $errors
                    if ($null -ne $qualificationAuthorityApprovalValidation -and
                        ($null -eq $pilotVerdictWaiverValidation -or
                         [string]$pilotVerdictWaiverValidation.Approval.authorityPrincipalId -cne [string]$qualificationAuthorityApprovalValidation.Approval.authorityPrincipalId -or
                         [string]$pilotVerdictWaiverValidation.Approval.approverSetDigest -cne [string]$qualificationAuthorityApprovalValidation.Approval.approverSetDigest)) {
                        Add-BlueprintError -Errors $errors -Code 'PILOT_NOT_REQUIRED_APPROVAL_INVALID' -Message 'Pilot-record waiver and final verdict must use the same canonical authority principal and approver set.'
                    }
                }
            }
        }
        elseif ((Test-ValuePresent $verdictRecord.pilotNotRequiredApprovalRef) -or
            (Test-ValuePresent $verdictRecord.pilotNotRequiredApprovalDigest)) {
            Add-BlueprintError -Errors $errors -Code 'PILOT_NOT_REQUIRED_APPROVAL_INVALID' -Message 'A required or authorized pilot may not retain a NOT_REQUIRED authority approval.'
        }
        [void](Test-FinalVerdictPilotCompletionSemantics -Verdict $verdictRecord -PilotVerdict $pilotVerdict `
            -Manifest $manifestRecord -Phase0TestPlan $testPlanRecord -FrozenThresholdPolicy $frozenThresholdPolicyRecord `
            -RecordMap $recordMap -EvaluationTime $EvaluationTime -ValidationProfile $ValidationProfile `
            -VerdictIssuanceApprovalValidation $qualificationAuthorityApprovalValidation -Errors $errors)
        if (([string]$verdictRecord.fleetVerdict -ceq 'QUALIFY' -and [string]$verdictRecord.fleetDeploymentDisposition -cne 'APPROVED') -or
            ([string]$verdictRecord.fleetVerdict -ceq 'QUALIFY_WITH_CONDITIONS' -and [string]$verdictRecord.fleetDeploymentDisposition -cne 'APPROVED_WITH_CONDITIONS') -or
            ([string]$verdictRecord.fleetVerdict -cin @('HOLD', 'FAIL') -and [string]$verdictRecord.fleetDeploymentDisposition -cne 'BLOCKED')) {
            Add-BlueprintError -Errors $errors -Code 'FLEET_DISPOSITION_MISMATCH' -Message 'Fleet deployment disposition strengthens or contradicts the fleet verdict.'
        }
        Test-RequiredProperties -Object $verdictRecord.arbitration -Names @('required') -Context 'verdict arbitration' -Errors $errors
        $arbitrationTriggersProperty = $verdictRecord.arbitration.PSObject.Properties['triggers']
        if ($null -eq $arbitrationTriggersProperty -or $arbitrationTriggersProperty.Value -isnot [System.Collections.IList]) {
            Add-BlueprintError -Errors $errors -Code 'MISSING_REQUIRED_FIELD' -Message 'Verdict arbitration requires a triggers array, which may be empty only when arbitration.required is false.'
        }
        Test-AllowedProperties -Object $verdictRecord.arbitration -Names @(
            'required', 'triggers', 'authority', 'outcome', 'date', 'evidenceRefs', 'extensions'
        ) -Context 'verdict arbitration' -Errors $errors
        $arbitrationTriggers = @($verdictRecord.arbitration.triggers)
        if ($verdictRecord.arbitration.required -isnot [bool] -or
            @($arbitrationTriggers | Where-Object { $_ -isnot [string] -or [string]$_ -cnotin @('verdict-conflict', 'deadline-inconclusive', 'substitution-dispute') }).Count -gt 0 -or
            @($arbitrationTriggers | Group-Object -CaseSensitive | Where-Object Count -gt 1).Count -gt 0) {
            Add-BlueprintError -Errors $errors -Code 'ARBITRATION_RECORD_INVALID' -Message 'Arbitration must use a boolean required flag and a unique recognized trigger set.'
        }
        if ($verdictRecord.arbitration.required -eq $true) {
            Test-RequiredProperties -Object $verdictRecord.arbitration -Names @('authority', 'outcome', 'date', 'evidenceRefs') -Context 'required verdict arbitration' -Errors $errors
            [DateTime]$arbitrationDate = [DateTime]::MinValue
            if ($arbitrationTriggers.Count -eq 0 -or
                -not (Test-NonBlankString $verdictRecord.arbitration.authority) -or
                -not (Test-NonBlankString $verdictRecord.arbitration.outcome) -or
                -not (Test-ExactIsoDate -Value $verdictRecord.arbitration.date -ParsedDate ([ref]$arbitrationDate)) -or
                $arbitrationDate.Date -gt $EvaluationTime.Date -or
                @($verdictRecord.arbitration.evidenceRefs).Count -eq 0 -or
                @($verdictRecord.arbitration.evidenceRefs | Where-Object { -not (Test-NonBlankString $_) }).Count -gt 0 -or
                @($verdictRecord.arbitration.evidenceRefs | Group-Object -CaseSensitive | Where-Object Count -gt 1).Count -gt 0) {
                Add-BlueprintError -Errors $errors -Code 'ARBITRATION_RECORD_INVALID' -Message 'Required arbitration must be complete, uniquely evidenced, exact-date formatted, and non-future.'
            }
            foreach ($arbitrationEvidenceRef in @($verdictRecord.arbitration.evidenceRefs)) {
                [void](Resolve-CanonicalRecord -RecordMap $recordMap -Reference $arbitrationEvidenceRef `
                    -ExpectedTypes @('evidence-record', 'evidence-release', 'exception-record', 'procurement-envelope-record') `
                    -Context 'arbitration evidence' -Errors $errors)
            }
            if ([string]$verdictRecord.arbitration.authority -cne [string]$verdictRecord.qualificationAuthority -or
                $null -eq $manifestRecord) {
                Add-BlueprintError -Errors $errors -Code 'ARBITRATION_AUTHORITY_APPROVAL_INVALID' -Message 'Required arbitration must use the manifest-bound qualification authority and a scope-specific approval.'
            }
            else {
                $arbitrationApprovalValidation = Test-QualificationAuthorityApprovalSemantics -RecordMap $recordMap `
                    -ApprovalRef $verdictRecord.arbitrationAuthorityApprovalRef `
                    -ApprovalDigest $verdictRecord.arbitrationAuthorityApprovalDigest `
                    -Verdict $verdictRecord -Manifest $manifestRecord -DecisionScope 'ARBITRATION' `
                    -EvaluationTime $EvaluationTime -FailureCode 'ARBITRATION_AUTHORITY_APPROVAL_INVALID' -Errors $errors
                if ($null -ne $qualificationAuthorityApprovalValidation -and
                    ($null -eq $arbitrationApprovalValidation -or
                     [string]$arbitrationApprovalValidation.Approval.authorityPrincipalId -cne [string]$qualificationAuthorityApprovalValidation.Approval.authorityPrincipalId -or
                     [string]$arbitrationApprovalValidation.Approval.approverSetDigest -cne [string]$qualificationAuthorityApprovalValidation.Approval.approverSetDigest)) {
                    Add-BlueprintError -Errors $errors -Code 'ARBITRATION_AUTHORITY_APPROVAL_INVALID' -Message 'Arbitration and verdict issuance must use the same canonical authority principal and approver set.'
                }
            }
        }
        elseif ($arbitrationTriggers.Count -gt 0 -or
            (Test-ValuePresent $verdictRecord.arbitration.authority) -or
            (Test-ValuePresent $verdictRecord.arbitration.outcome) -or
            (Test-ValuePresent $verdictRecord.arbitration.date) -or
            (Test-ValuePresent $verdictRecord.arbitration.evidenceRefs)) {
            Add-BlueprintError -Errors $errors -Code 'ARBITRATION_RECORD_INCONSISTENT' -Message 'Arbitration marked not required cannot retain triggers or completed-decision fields.'
        }
        if ($verdictRecord.arbitration.required -ne $true -and
            ((Test-ValuePresent $verdictRecord.arbitrationAuthorityApprovalRef) -or
             (Test-ValuePresent $verdictRecord.arbitrationAuthorityApprovalDigest))) {
            Add-BlueprintError -Errors $errors -Code 'ARBITRATION_AUTHORITY_APPROVAL_INVALID' -Message 'Arbitration authority approval evidence is forbidden when arbitration is not required.'
        }
        $substitutionArbitrationRequired = @($verdictRecord.procurementEnvelope.substitutionAssessments | Where-Object { $_.arbitrationRequired -eq $true }).Count -gt 0
        if (($substitutionArbitrationRequired -and ($verdictRecord.arbitration.required -ne $true -or $arbitrationTriggers -cnotcontains 'substitution-dispute')) -or
            (-not $substitutionArbitrationRequired -and $arbitrationTriggers -ccontains 'substitution-dispute')) {
            Add-BlueprintError -Errors $errors -Code 'ARBITRATION_TRIGGER_MISMATCH' -Message 'Substitution-dispute arbitration must exactly match the structured substitution assessments.'
        }
        if ($arbitrationTriggers -ccontains 'deadline-inconclusive' -and [string]$verdictRecord.fleetVerdict -cne 'INCONCLUSIVE') {
            Add-BlueprintError -Errors $errors -Code 'ARBITRATION_TRIGGER_MISMATCH' -Message 'deadline-inconclusive arbitration is valid only for an INCONCLUSIVE fleet verdict.'
        }

        $riskAcceptedInconclusive = [string]$verdictRecord.fleetVerdict -ceq 'INCONCLUSIVE' -and
            [string]$verdictRecord.deadlineDecision.deadlineStatus -ceq 'deadline-reached' -and
            [string]$verdictRecord.deadlineDecision.evidenceState -ceq 'inconclusive' -and
            [string]$verdictRecord.deadlineDecision.decision -ceq 'risk-accepted-expiring-exception'
        if ($riskAcceptedInconclusive) {
            if ([string]$verdictRecord.deadlineDecision.authorityApprovalRef -cne [string]$verdictRecord.deadlineAuthorityApprovalRef -or
                $null -eq $manifestRecord) {
                Add-BlueprintError -Errors $errors -Code 'DEADLINE_AUTHORITY_APPROVAL_INVALID' -Message 'Deadline risk acceptance must bind the exact same qualification-authority approval inside and outside the portable decision.'
            }
            else {
                $deadlineApprovalValidation = Test-QualificationAuthorityApprovalSemantics -RecordMap $recordMap `
                    -ApprovalRef $verdictRecord.deadlineAuthorityApprovalRef `
                    -ApprovalDigest $verdictRecord.deadlineAuthorityApprovalDigest `
                    -Verdict $verdictRecord -Manifest $manifestRecord -DecisionScope 'DEADLINE_DECISION' `
                    -EvaluationTime $EvaluationTime -FailureCode 'DEADLINE_AUTHORITY_APPROVAL_INVALID' -Errors $errors
                if ($null -ne $qualificationAuthorityApprovalValidation -and
                    ($null -eq $deadlineApprovalValidation -or
                     [string]$deadlineApprovalValidation.Approval.authorityPrincipalId -cne [string]$qualificationAuthorityApprovalValidation.Approval.authorityPrincipalId -or
                     [string]$deadlineApprovalValidation.Approval.approverSetDigest -cne [string]$qualificationAuthorityApprovalValidation.Approval.approverSetDigest)) {
                    Add-BlueprintError -Errors $errors -Code 'DEADLINE_AUTHORITY_APPROVAL_INVALID' -Message 'Deadline and verdict issuance must use the same canonical authority principal and approver set.'
                }
            }
        }
        elseif ((Test-ValuePresent $verdictRecord.deadlineAuthorityApprovalRef) -or
            (Test-ValuePresent $verdictRecord.deadlineAuthorityApprovalDigest) -or
            (Test-ValuePresent $verdictRecord.deadlineDecision.authorityApprovalRef)) {
            Add-BlueprintError -Errors $errors -Code 'DEADLINE_AUTHORITY_APPROVAL_INVALID' -Message 'Deadline authority approval evidence is valid only for the governed expiring-exception decision.'
        }
        if ([string]$verdictRecord.fleetVerdict -ceq 'INCONCLUSIVE') {
            if (-not $riskAcceptedInconclusive) {
                if ([string]$verdictRecord.fleetDeploymentDisposition -cne 'BLOCKED' -or [string]$verdictRecord.procurementDisposition -cne 'BLOCKED') {
                    Add-BlueprintError -Errors $errors -Code 'INCONCLUSIVE_DEADLINE_RULE_VIOLATED' -Message 'INCONCLUSIVE without the exact deadline exception path must block deployment and procurement.'
                }
            }
            else {
                $exceptionRef = [string]$verdictRecord.deadlineDecision.exceptionRef
                $exception = @($verdictRecord.exceptions | Where-Object { [string]$_.exceptionId -ceq $exceptionRef })
                $exceptionFields = @(
                    'exceptionId', 'owner', 'reason', 'compensatingControl', 'scope',
                    'expiration', 'closureEvidence', 'approvedBy'
                )
                if ($exception.Count -eq 1) {
                    Test-RequiredProperties -Object $exception[0] -Names $exceptionFields -Context 'deadline exception' -Errors $errors
                    Test-AllowedProperties -Object $exception[0] -Names @($exceptionFields + 'extensions') -Context 'deadline exception' -Errors $errors
                    foreach ($field in @($exceptionFields | Where-Object { [string]$_ -cne 'expiration' })) {
                        if (-not (Test-NonBlankString $exception[0].$field)) {
                            Add-BlueprintError -Errors $errors -Code 'INCONCLUSIVE_EXCEPTION_INVALID' -Message "Deadline exception field $field must be a nonblank string."
                        }
                    }
                }
                [DateTime]$exceptionExpiration = [DateTime]::MinValue
                if ($exception.Count -ne 1 -or $verdictRecord.arbitration.required -ne $true -or
                    @($verdictRecord.arbitration.triggers) -cnotcontains 'deadline-inconclusive' -or
                    -not (Test-ExactIsoDate -Value $exception[0].expiration -ParsedDate ([ref]$exceptionExpiration)) -or
                    $exceptionExpiration.Date -le $EvaluationTime.Date) {
                    Add-BlueprintError -Errors $errors -Code 'INCONCLUSIVE_EXCEPTION_INVALID' -Message 'Deadline risk acceptance requires one current exact yyyy-MM-dd exception and completed deadline arbitration.'
                }
            }
        }

        $personaPointer = ([string]$Chain.recommendation.personaVerdictPointer).Split('#', 2)[1]
        $personaFound = $false
        $selectedPersonaVerdict = Get-JsonPointerValue -Document $verdictRecord.payload -Pointer $personaPointer -Found ([ref]$personaFound)
        $capacityPointer = ([string]$Chain.personaNeed.capacityWaterfallPointer).Split('#', 2)[1]
        $capacityFound = $false
        $selectedCapacity = Get-JsonPointerValue -Document $verdictRecord.payload -Pointer $capacityPointer -Found ([ref]$capacityFound)
        if (-not $personaFound -or $selectedPersonaVerdict -isnot [pscustomobject] -or -not $capacityFound -or $selectedCapacity -isnot [pscustomobject]) {
            Add-BlueprintError -Errors $errors -Code 'SELECTED_PERSONA_VERDICT_UNRESOLVED' -Message 'Selected persona verdict and its capacity waterfall must resolve from the verified verdict payload.'
        }
        else {
            Test-RequiredProperties -Object $selectedPersonaVerdict -Names @(
                'persona', 'verdict', 'assignmentDisposition', 'conflictsWithFleetConditions', 'capacityWaterfall'
            ) -Context 'selected persona verdict' -Errors $errors
            # An unconditional persona QUALIFY must carry an explicit empty
            # conditionRefs array; conditional verdict logic below still
            # requires one or more references when conditions apply.
            if ($null -eq $selectedPersonaVerdict.PSObject.Properties['conditionRefs']) {
                Add-BlueprintError -Errors $errors -Code 'MISSING_REQUIRED_FIELD' -Message 'selected persona verdict requires conditionRefs.'
            }
            Test-CapacityWaterfallSemantics -CapacityWaterfall $selectedCapacity -VerdictRecord $verdictRecord `
                -Phase0TestPlan $testPlanRecord -ThresholdPolicy $frozenThresholdPolicyRecord `
                -Manifest $manifestRecord -Chain $Chain -RecordMap $recordMap `
                -EvaluationTime $EvaluationTime -Errors $errors
            if ([string]$selectedPersonaVerdict.persona -cne [string]$Chain.personaNeed.personaId) {
                Add-BlueprintError -Errors $errors -Code 'SELECTED_PERSONA_ID_MISMATCH' -Message 'The selected verdict entry belongs to a different persona.'
            }
            if ([string]$selectedPersonaVerdict.verdict -cnotin @('QUALIFY', 'QUALIFY_WITH_CONDITIONS', 'HOLD', 'FAIL', 'INCONCLUSIVE')) {
                Add-BlueprintError -Errors $errors -Code 'PERSONA_VERDICT_SEMANTICS_INVALID' -Message 'Selected persona verdict is invalid.'
            }
            if ($selectedPersonaVerdict.conflictsWithFleetConditions -isnot [bool]) {
                Add-BlueprintError -Errors $errors -Code 'PERSONA_FLEET_CONFLICT_STATE_INVALID' -Message 'Selected persona conflictsWithFleetConditions must be a boolean.'
            }
            elseif ($selectedPersonaVerdict.conflictsWithFleetConditions) {
                if ($verdictRecord.arbitration.required -ne $true -or
                    @($verdictRecord.arbitration.triggers) -cnotcontains 'verdict-conflict' -or
                    -not (Test-ValuePresent $verdictRecord.arbitration.authority) -or
                    -not (Test-ValuePresent $verdictRecord.arbitration.outcome) -or
                    @($verdictRecord.arbitration.evidenceRefs).Count -eq 0) {
                    Add-BlueprintError -Errors $errors -Code 'PERSONA_FLEET_CONFLICT_ARBITRATION_REQUIRED' -Message 'A selected persona/fleet conflict requires complete qualification-authority arbitration and retained evidence.'
                }
                if ([string]$selectedPersonaVerdict.verdict -cne 'QUALIFY_WITH_CONDITIONS' -or
                    [string]$selectedPersonaVerdict.assignmentDisposition -cne 'APPROVED_WITH_CONDITIONS' -or
                    @($selectedPersonaVerdict.conditionRefs).Count -eq 0 -or
                    [string]$verdictRecord.procurementDisposition -cne 'APPROVED_WITH_CONDITIONS') {
                    Add-BlueprintError -Errors $errors -Code 'PERSONA_FLEET_CONFLICT_NOT_CONDITIONAL' -Message 'A resolved persona/fleet conflict may only proceed through explicit current conditions and conditional procurement; otherwise it remains blocking.'
                }
            }
            elseif (@($verdictRecord.arbitration.triggers) -ccontains 'verdict-conflict') {
                Add-BlueprintError -Errors $errors -Code 'ARBITRATION_TRIGGER_MISMATCH' -Message 'verdict-conflict arbitration cannot be retained when the selected persona declares no fleet-condition conflict.'
            }
            if (([string]$selectedPersonaVerdict.verdict -ceq 'QUALIFY' -and [string]$selectedPersonaVerdict.assignmentDisposition -cne 'APPROVED') -or
                ([string]$selectedPersonaVerdict.verdict -ceq 'QUALIFY_WITH_CONDITIONS' -and
                    ([string]$selectedPersonaVerdict.assignmentDisposition -cne 'APPROVED_WITH_CONDITIONS' -or @($selectedPersonaVerdict.conditionRefs).Count -eq 0)) -or
                ([string]$selectedPersonaVerdict.verdict -cin @('HOLD', 'FAIL', 'INCONCLUSIVE') -and [string]$selectedPersonaVerdict.assignmentDisposition -cne 'BLOCKED')) {
                Add-BlueprintError -Errors $errors -Code 'PERSONA_DISPOSITION_MISMATCH' -Message 'Selected persona assignment disposition strengthens or contradicts its verdict.'
            }
            if ([string]$selectedCapacity.memory.outcome -ceq 'SHORTFALL' -or [string]$selectedCapacity.storage.outcome -ceq 'SHORTFALL') {
                if ([string]$selectedPersonaVerdict.verdict -cin @('QUALIFY', 'QUALIFY_WITH_CONDITIONS')) {
                    Add-BlueprintError -Errors $errors -Code 'CAPACITY_SHORTFALL_CONTRADICTS_VERDICT' -Message 'A persona with a recorded capacity shortfall cannot receive a qualifying verdict.'
                }
            }
            foreach ($conditionId in @($selectedPersonaVerdict.conditionRefs)) {
                $condition = @($verdictRecord.conditions | Where-Object { [string]$_.conditionId -ceq [string]$conditionId })
                if ($condition.Count -ne 1) {
                    Add-BlueprintError -Errors $errors -Code 'VERDICT_CONDITION_UNRESOLVED' -Message "Persona condition $conditionId does not resolve exactly once in the final verdict."
                    continue
                }
                [DateTime]$conditionExpiration = [DateTime]::MinValue
                if (-not (Test-ExactIsoDate -Value $condition[0].expiration -ParsedDate ([ref]$conditionExpiration)) -or
                    $conditionExpiration.Date -le $EvaluationTime.Date) {
                    Add-BlueprintError -Errors $errors -Code 'VERDICT_CONDITION_EXPIRED' -Message "Persona condition $conditionId is invalid or expired."
                }
            }
        }

        Test-RequiredProperties -Object $verdictRecord.procurementEnvelope -Names @(
            'approvedSkus', 'quantityScope', 'substitutionPolicy', 'substitutionAssessments'
        ) -Context 'procurement envelope' -Errors $errors
        if ($verdictRecord.procurementEnvelope.substitutionPolicy.silentSubstitutionAllowed -ne $false -or
            $verdictRecord.procurementEnvelope.substitutionPolicy.observableEquivalenceEvidenceRequired -ne $true -or
            [string]$verdictRecord.procurementEnvelope.substitutionPolicy.materialDifferenceAction -cne 'DELTA_QUALIFICATION_REQUIRED' -or
            [string]$verdictRecord.procurementEnvelope.substitutionPolicy.unknownIdentityDisposition -cne 'HOLD') {
            Add-BlueprintError -Errors $errors -Code 'PROCUREMENT_SUBSTITUTION_POLICY_INVALID' -Message 'Procurement envelope weakens the portable substitution safety rule.'
        }
        if (@($verdictRecord.procurementEnvelope.substitutionAssessments | Where-Object {
            [string]$_.identityStatus -ceq 'UNKNOWN' -or [string]$_.disposition -cin @('HOLD', 'DELTA_QUALIFICATION_REQUIRED')
        }).Count -gt 0 -and [string]$verdictRecord.procurementDisposition -cne 'BLOCKED') {
            Add-BlueprintError -Errors $errors -Code 'PROCUREMENT_DISPOSITION_STRENGTHENED' -Message 'Unknown identity or pending delta qualification must block procurement.'
        }

        if ($selectedPersonaVerdict -is [pscustomobject]) {
            $expectedRecommendation = Get-ExpectedRecommendation -VerdictPayload $verdictRecord.payload -PersonaVerdict $selectedPersonaVerdict -VerdictRef ([string]$Chain.recommendation.verdictRef)
            if ([string]$expectedRecommendation.Action -ceq 'BUY_WITH_CONDITIONS') {
                if (@($verdictRecord.conditions).Count -eq 0) {
                    Add-BlueprintError -Errors $errors -Code 'CONDITIONAL_RECOMMENDATION_WITHOUT_CONDITIONS' -Message 'A conditional buying recommendation requires retained current condition records.'
                }
                foreach ($condition in @($verdictRecord.conditions)) {
                    Test-RequiredProperties -Object $condition -Names @('conditionId', 'description', 'owner', 'expiration', 'closureEvidence') -Context 'verdict condition' -Errors $errors
                    [DateTime]$conditionExpiration = [DateTime]::MinValue
                    if (-not (Test-ExactIsoDate -Value $condition.expiration -ParsedDate ([ref]$conditionExpiration)) -or $conditionExpiration.Date -le $EvaluationTime.Date) {
                        Add-BlueprintError -Errors $errors -Code 'VERDICT_CONDITION_EXPIRED' -Message "$($condition.conditionId) is invalid or expired."
                    }
                }
            }
            if ([string]$Chain.recommendation.action -cne [string]$expectedRecommendation.Action -or
                [string]$Chain.recommendation.statement -cne [string]$expectedRecommendation.Statement) {
                Add-BlueprintError -Errors $errors -Code 'RECOMMENDATION_STRENGTHENS_VERDICT' -Message 'Recommendation action or text is not the deterministic rendering of the selected final verdict.'
            }
        }
    }
    if ($null -ne $decisionClaimRecord -and $null -ne $verdictRecord) {
        Test-RequiredProperties -Object $decisionClaimRecord -Names @(
            'sourceVerdictRef', 'sourceVerdictDigest', 'sourceManifestRef', 'sourceManifestDigest',
            'sourcePointers', 'semanticValidationRef', 'semanticValidationDigest', 'semanticInputDigest',
            'personaId', 'fleetDisposition', 'personaDisposition', 'decisionAction',
            'procurementEnvelopeDigest', 'arbitrationRequired', 'renderedStatement',
            'renderedStatementDigest', 'rendererToolRef', 'rendererVersion', 'rendererReleaseRef',
            'rendererReleaseDigest', 'templateRef', 'templateDigest', 'renderMode',
            'manualOverrideAllowed', 'unmeasuredClaimPolicy', 'renderedAt'
        ) -Context 'decision claim record' -Errors $errors
        $procurementEnvelopeDigest = Get-CanonicalPayloadDigest -Payload $verdictRecord.procurementEnvelope
        [DateTimeOffset]$decisionRenderedAt = [DateTimeOffset]::MinValue
        if ([string]$decisionClaimRecord.sourceVerdictRef -cne [string]$Chain.recommendation.verdictRef -or
            [string]$decisionClaimRecord.sourceVerdictDigest -cne [string]$verdictRecord.contentDigest -or
            [string]$decisionClaimRecord.sourceManifestRef -cne [string]$Chain.personaNeed.manifestRef -or
            ($null -ne $manifestRecord -and [string]$decisionClaimRecord.sourceManifestDigest -cne [string]$manifestRecord.contentDigest) -or
            [string]$decisionClaimRecord.semanticValidationRef -cne [string]$Chain.lineage.semanticValidationRef -or
            [string]$decisionClaimRecord.semanticValidationDigest -cne [string]$Chain.lineage.semanticValidationDigest -or
            [string]$decisionClaimRecord.semanticInputDigest -cne [string]$Chain.lineage.semanticInputDigest -or
            [string]$decisionClaimRecord.personaId -cne [string]$Chain.personaNeed.personaId -or
            [string]$decisionClaimRecord.fleetDisposition -cne [string]$verdictRecord.fleetVerdict -or
            ($selectedPersonaVerdict -is [pscustomobject] -and [string]$decisionClaimRecord.personaDisposition -cne [string]$selectedPersonaVerdict.verdict) -or
            [string]$decisionClaimRecord.decisionAction -cne [string]$Chain.recommendation.action -or
            [string]$decisionClaimRecord.procurementEnvelopeDigest -cne [string]$procurementEnvelopeDigest -or
            $decisionClaimRecord.arbitrationRequired -ne [bool]$verdictRecord.arbitration.required -or
            [string]$decisionClaimRecord.renderedStatement -cne [string]$Chain.recommendation.statement -or
            [string]$decisionClaimRecord.renderedStatementDigest -cne (Get-CanonicalPayloadDigest -Payload ([string]$decisionClaimRecord.renderedStatement)) -or
            [string]$decisionClaimRecord.rendererToolRef -cne 'decision-packet-renderer' -or
            -not (Test-Sha256Token $decisionClaimRecord.rendererReleaseDigest) -or
            -not (Test-Sha256Token $decisionClaimRecord.templateDigest) -or
            [string]$decisionClaimRecord.renderMode -cne 'DETERMINISTIC_FROM_CANONICAL_RECORDS' -or
            $decisionClaimRecord.manualOverrideAllowed -ne $false -or
            [string]$decisionClaimRecord.unmeasuredClaimPolicy -cne 'CONTROLLED_HYPOTHESIS_ONLY' -or
            -not [OperationsBlueprint.StrictRfc3339]::TryParse([string]$decisionClaimRecord.renderedAt, [ref]$decisionRenderedAt) -or
            $decisionRenderedAt -gt $EvaluationTime) {
            Add-BlueprintError -Errors $errors -Code 'DECISION_CLAIM_BINDING_MISMATCH' -Message 'Rendered recommendation is not bound to the exact manifest, persona, verdict, procurement envelope, action, and statement.'
        }
        if ($verdictRecord.arbitration.required -eq $true) {
            $expectedArbitrationDigest = Get-CanonicalPayloadDigest -Payload $verdictRecord.arbitration
            if ([string]$decisionClaimRecord.arbitrationRef -cne ([string]$Chain.recommendation.verdictRef + '#/arbitration') -or
                [string]$decisionClaimRecord.arbitrationDigest -cne [string]$expectedArbitrationDigest) {
                Add-BlueprintError -Errors $errors -Code 'DECISION_CLAIM_ARBITRATION_MISMATCH' -Message 'Decision claim omits or changes the required structured arbitration outcome.'
            }
        }
        $expectedDecisionConditionIds = if ([string]$Chain.recommendation.action -ceq 'BUY_WITH_CONDITIONS') {
            @($verdictRecord.conditions | ForEach-Object { [string]$_.conditionId } | Sort-Object -CaseSensitive -Unique)
        }
        else { @() }
        if (-not (Test-CanonicalValueEqual @($decisionClaimRecord.conditionRefs) @($expectedDecisionConditionIds))) {
            Add-BlueprintError -Errors $errors -Code 'DECISION_CLAIM_CONDITION_SET_MISMATCH' -Message 'Decision claim condition references do not exactly match the deterministic final-verdict condition set.'
        }
        $requiredSourcePointers = @(
            [string]$Chain.recommendation.fleetVerdictPointer,
            [string]$Chain.recommendation.personaVerdictPointer,
            [string]$Chain.recommendation.procurementEnvelopePointer
        )
        foreach ($requiredPointer in $requiredSourcePointers) {
            if (@($decisionClaimRecord.sourcePointers) -cnotcontains $requiredPointer) {
                Add-BlueprintError -Errors $errors -Code 'DECISION_CLAIM_SOURCE_POINTER_MISSING' -Message 'Rendered recommendation omits a required source verdict pointer.'
            }
        }
    }

    $linkEvidenceRecords = @{}
    $programSamplingFloors = [System.Collections.Generic.Dictionary[string,object]]::new([System.StringComparer]::Ordinal)
    $programSamplingFloors.Add('component-identification', @(5, 1))
    $programSamplingFloors.Add('controlled-benchmark', @(3, 5))
    $programSamplingFloors.Add('sustained-performance', @(3, 3))
    $programSamplingFloors.Add('battery-standby', @(3, 3))
    $programSamplingFloors.Add('dock-reliability', @(3, 20))
    $programSamplingFloors.Add('application-compatibility', @(2, 2))
    $programSamplingFloors.Add('production-pilot', @(30, 10))
    $programSamplingFloors.Add('sentiment', @(24, 1))
    $programSamplingFloors.Add('corporate-floor', @(3, 3))
    $programSamplingFloors.Add('agent-state', @(3, 3))
    $releaseByLink = @{
        personaNeed = $personaEvidenceRelease
        currentFleetIssue = $fleetEvidenceRelease
        candidateComparison = $candidateEvidenceRelease
        businessEffect = $businessEvidenceRelease
    }
    $distributionByEvidenceId = [System.Collections.Generic.Dictionary[string,object]]::new([System.StringComparer]::Ordinal)
    $evidenceLinkNames = @('personaNeed', 'currentFleetIssue', 'candidateComparison')
    if ([string]$Chain.businessEffect.status -ceq 'MEASURED') { $evidenceLinkNames += 'businessEffect' }
    foreach ($linkName in $evidenceLinkNames) {
        $linkEvidenceRecords[$linkName] = New-Object System.Collections.ArrayList
        foreach ($evidenceRef in @($Chain.$linkName.evidenceRefs)) {
            $evidenceRecord = Resolve-CanonicalRecord -RecordMap $recordMap -Reference $evidenceRef -ExpectedTypes @('evidence-record') -Context "$linkName evidence" -Errors $errors
            if ($null -ne $evidenceRecord) { [void]$linkEvidenceRecords[$linkName].Add($evidenceRecord) }
        }
        $actualProvenance = @($linkEvidenceRecords[$linkName] | ForEach-Object { [string]$_.provenance } | Select-Object -Unique)
        foreach ($declared in @($Chain.$linkName.provenance)) {
            if ($actualProvenance -cnotcontains [string]$declared) {
                Add-BlueprintError -Errors $errors -Code 'EVIDENCE_PROVENANCE_MISMATCH' -Message "$linkName declares provenance not present in its typed evidence records."
            }
        }
        foreach ($actual in $actualProvenance) {
            if (@($Chain.$linkName.provenance) -cnotcontains [string]$actual) {
                Add-BlueprintError -Errors $errors -Code 'EVIDENCE_PROVENANCE_MISMATCH' -Message "$linkName omits provenance present in its typed evidence records."
            }
        }
        if ($actualProvenance.Count -gt 0 -and @($actualProvenance | Where-Object { [string]$_ -cne 'T2' }).Count -eq 0) {
            Add-BlueprintError -Errors $errors -Code 'T2_ONLY_DECISION_SUPPORT' -Message "$linkName is supported only by T2 evidence."
        }
        foreach ($evidenceRecord in @($linkEvidenceRecords[$linkName] | Where-Object { [string]$_.provenance -ceq 'T0' })) {
            Test-RequiredProperties -Object $evidenceRecord -Names @('distributionRef') -Context "T0 evidence $($evidenceRecord.recordId)" -Errors $errors
            $distributionRecord = Resolve-CanonicalRecord -RecordMap $recordMap -Reference $evidenceRecord.distributionRef -ExpectedTypes @('distribution-record') -Context "distribution for $($evidenceRecord.recordId)" -Errors $errors
            if ($null -eq $distributionRecord) { continue }
            $distributionByEvidenceId[[string]$evidenceRecord.recordId] = $distributionRecord
            Test-RequiredProperties -Object $distributionRecord -Names @(
                'sourceEvidenceRef', 'sourceEvidenceDigest', 'sourceEvidenceReleaseRef', 'sourceEvidenceReleaseSubjectDigest',
                'testRef', 'testDefinitionDigest', 'conditionRef', 'baselineFingerprint',
                'testClass', 'metricId', 'unit', 'statisticDirection',
                'unitCount', 'runCount', 'requiredUnits', 'requiredRuns', 'median',
                'spread', 'runVariation', 'coverage', 'missingResults',
                'outliers', 'exclusions', 'samplingFloorStatus', 'distributionStatus',
                'phase0TestPlanRef', 'phase0TestPlanDigest', 'samplingFloorPointer',
                'samplingFloorDigest', 'perUnitRunCounts'
            ) -Context "distribution $($distributionRecord.recordId)" -Errors $errors
            $distributionShapeValid = (Test-NonBlankString $distributionRecord.metricId) -and
                (Test-NonBlankString $distributionRecord.unit) -and
                (Test-NumberValue $distributionRecord.median) -and
                $distributionRecord.spread -is [pscustomobject] -and
                $distributionRecord.runVariation -is [pscustomobject]
            if ($distributionRecord.spread -is [pscustomobject]) {
                Test-RequiredProperties -Object $distributionRecord.spread -Names @('minimum', 'maximum') -Context "distribution $($distributionRecord.recordId) spread" -Errors $errors
                Test-AllowedProperties -Object $distributionRecord.spread -Names @('minimum', 'maximum', 'p10', 'p25', 'p75', 'p90', 'p95', 'p99') -Context "distribution $($distributionRecord.recordId) spread" -Errors $errors
                $orderedSpreadValues = New-Object System.Collections.ArrayList
                foreach ($spreadName in @('minimum', 'p10', 'p25', 'p75', 'p90', 'p95', 'p99', 'maximum')) {
                    $spreadProperty = $distributionRecord.spread.PSObject.Properties[$spreadName]
                    if ($null -eq $spreadProperty) { continue }
                    if (-not (Test-NumberValue $spreadProperty.Value)) { $distributionShapeValid = $false; continue }
                    [void]$orderedSpreadValues.Add([double]$spreadProperty.Value)
                }
                for ($spreadIndex = 1; $spreadIndex -lt $orderedSpreadValues.Count; $spreadIndex++) {
                    if ([double]$orderedSpreadValues[$spreadIndex] -lt [double]$orderedSpreadValues[$spreadIndex - 1]) {
                        $distributionShapeValid = $false
                    }
                }
                if ((Test-NumberValue $distributionRecord.median) -and
                    (Test-NumberValue $distributionRecord.spread.minimum) -and
                    (Test-NumberValue $distributionRecord.spread.maximum) -and
                    ([double]$distributionRecord.median -lt [double]$distributionRecord.spread.minimum -or
                     [double]$distributionRecord.median -gt [double]$distributionRecord.spread.maximum)) {
                    $distributionShapeValid = $false
                }
            }
            if ($distributionRecord.runVariation -is [pscustomobject]) {
                Test-RequiredProperties -Object $distributionRecord.runVariation -Names @('minimum', 'maximum') -Context "distribution $($distributionRecord.recordId) run variation" -Errors $errors
                Test-AllowedProperties -Object $distributionRecord.runVariation -Names @('minimum', 'maximum', 'standardDeviation', 'coefficientOfVariation') -Context "distribution $($distributionRecord.recordId) run variation" -Errors $errors
                if (-not (Test-NumberValue $distributionRecord.runVariation.minimum) -or
                    -not (Test-NumberValue $distributionRecord.runVariation.maximum) -or
                    [double]$distributionRecord.runVariation.minimum -gt [double]$distributionRecord.runVariation.maximum) {
                    $distributionShapeValid = $false
                }
                foreach ($variationName in @('standardDeviation', 'coefficientOfVariation')) {
                    $variationProperty = $distributionRecord.runVariation.PSObject.Properties[$variationName]
                    if ($null -ne $variationProperty -and
                        (-not (Test-NumberValue $variationProperty.Value) -or [double]$variationProperty.Value -lt 0)) {
                        $distributionShapeValid = $false
                    }
                }
            }
            if (-not $distributionShapeValid) {
                Add-BlueprintError -Errors $errors -Code 'DISTRIBUTION_VALUE_SHAPE_INVALID' -Message "$($distributionRecord.recordId) requires nonblank metric/unit labels and numeric, ordered median/spread/run-variation values."
            }
            $testClass = [string]$distributionRecord.testClass
            $floor = $programSamplingFloors[$testClass]
            $distributionClosure = Test-DistributionSourceEvidenceClosure -Distribution $distributionRecord -RecordMap $recordMap `
                -EvaluationTime $EvaluationTime -ExpectedEvidenceRecord $evidenceRecord `
                -Context "distribution $($distributionRecord.recordId)" -Errors $errors
            [void](Test-DistributionPhase0FloorBinding -Distribution $distributionRecord -Phase0TestPlan $testPlanRecord `
                -ExpectedEvidenceRecord $distributionClosure.SourceEvidence `
                -ExpectedTestPlanRef ([string]$Chain.candidateComparison.testPlanRef) -Context "distribution $($distributionRecord.recordId)" -Errors $errors)
            Test-PortableEvidenceAdmissionSemantics -Evidence $evidenceRecord -Distribution $distributionRecord `
                -Manifest $manifestRecord -Phase0TestPlan $testPlanRecord -ThresholdPolicy $frozenThresholdPolicyRecord -RecordMap $recordMap `
                -CurrentRelease $releaseByLink[$linkName] -EvaluationTime $EvaluationTime `
                -ValidationProfile $ValidationProfile -Errors $errors
            Test-DistributionPerUnitRunProof -Distribution $distributionRecord -Context "distribution $($distributionRecord.recordId)" -Errors $errors
            Test-RequiredProperties -Object $distributionRecord.coverage -Names @('expected', 'observed', 'percent') -Context "distribution $($distributionRecord.recordId) coverage" -Errors $errors
            $coverageInvalid = $distributionRecord.coverage.expected -isnot [int] -and $distributionRecord.coverage.expected -isnot [long]
            $coverageInvalid = $coverageInvalid -or ($distributionRecord.coverage.observed -isnot [int] -and $distributionRecord.coverage.observed -isnot [long])
            $coverageInvalid = $coverageInvalid -or ($distributionRecord.coverage.percent -isnot [int] -and $distributionRecord.coverage.percent -isnot [long] -and $distributionRecord.coverage.percent -isnot [double] -and $distributionRecord.coverage.percent -isnot [decimal])
            if (-not $coverageInvalid) {
                $coverageExpected = [int64]$distributionRecord.coverage.expected
                $coverageObserved = [int64]$distributionRecord.coverage.observed
                $coveragePercent = [double]$distributionRecord.coverage.percent
                $calculatedCoveragePercent = if ($coverageExpected -gt 0) { 100.0 * $coverageObserved / $coverageExpected } else { -1.0 }
                $coverageInvalid = $coverageExpected -lt [int64]$distributionRecord.requiredUnits -or
                    $coverageObserved -ne [int64]$distributionRecord.unitCount -or
                    $coverageObserved -gt $coverageExpected -or
                    $coveragePercent -lt 0 -or $coveragePercent -gt 100 -or
                    [Math]::Abs($coveragePercent - $calculatedCoveragePercent) -gt 0.01
            }
            if ($coverageInvalid) {
                Add-BlueprintError -Errors $errors -Code 'DISTRIBUTION_COVERAGE_INVALID' -Message "$($distributionRecord.recordId) coverage does not reconcile expected units, observed units, unitCount, and percent."
            }
            if ([string]$distributionRecord.sourceEvidenceRef -cne [string]$evidenceRecord.recordId -or
                [string]$distributionRecord.samplingFloorStatus -cne 'PASS' -or
                [string]$distributionRecord.distributionStatus -cne 'PASS' -or
                [string]$distributionRecord.statisticDirection -cnotin @('HIGHER_IS_BETTER', 'LOWER_IS_BETTER', 'TARGET_RANGE', 'DESCRIPTIVE_ONLY') -or
                $null -eq $floor -or
                ($distributionRecord.unitCount -isnot [int] -and $distributionRecord.unitCount -isnot [long]) -or
                ($distributionRecord.runCount -isnot [int] -and $distributionRecord.runCount -isnot [long]) -or
                ($distributionRecord.requiredUnits -isnot [int] -and $distributionRecord.requiredUnits -isnot [long]) -or
                ($distributionRecord.requiredRuns -isnot [int] -and $distributionRecord.requiredRuns -isnot [long]) -or
                [int64]$distributionRecord.requiredUnits -lt 1 -or [int64]$distributionRecord.requiredRuns -lt 1 -or
                ($null -ne $floor -and [int64]$distributionRecord.requiredUnits -lt [int64]$floor[0]) -or
                ($null -ne $floor -and [int64]$distributionRecord.requiredRuns -lt [int64]$floor[1]) -or
                [int64]$distributionRecord.unitCount -lt [int64]$distributionRecord.requiredUnits) {
                Add-BlueprintError -Errors $errors -Code 'DISTRIBUTION_SEMANTICS_INVALID' -Message "$($distributionRecord.recordId) does not prove the applicable Playbook v2.0.1 class floor, accepted run total, and distribution."
            }
            if ($null -ne $releaseByLink[$linkName] -and @($releaseByLink[$linkName].memberRecordIds) -cnotcontains [string]$distributionRecord.recordId) {
                Add-BlueprintError -Errors $errors -Code 'DISTRIBUTION_NOT_IN_RELEASE' -Message "$($distributionRecord.recordId) is absent from the applicable immutable evidence release."
            }
        }
    }

    foreach ($record in @($linkEvidenceRecords.personaNeed)) {
        Test-RequiredProperties -Object $record -Names @(
            'subjectRef', 'personaId', 'capacityWaterfallPointer', 'evidenceReleaseRef', 'coverageStatus'
        ) -Context "persona evidence $($record.recordId)" -Errors $errors
        if ([string]$record.subjectRef -cne [string]$Chain.personaNeed.manifestRef -or
            [string]$record.personaId -cne [string]$Chain.personaNeed.personaId -or
            [string]$record.capacityWaterfallPointer -cne [string]$Chain.personaNeed.capacityWaterfallPointer -or
            [string]$record.evidenceReleaseRef -cne [string]$Chain.personaNeed.evidenceReleaseRef -or
            [string]$record.coverageStatus -cne 'PASS') {
            Add-BlueprintError -Errors $errors -Code 'PERSONA_EVIDENCE_BINDING_MISMATCH' -Message 'Persona evidence is not bound to the selected persona, manifest, capacity waterfall, release, and passing coverage.'
        }
    }
    Test-EvidenceReleaseBinding -ReleaseRecord $personaEvidenceRelease -EvidenceRecords @($linkEvidenceRecords.personaNeed) `
        -RecordMap $recordMap -EvaluationTime $EvaluationTime -ConsumerRecord $verdictRecord -Manifest $manifestRecord `
        -Phase0TestPlan $testPlanRecord -ThresholdPolicy $frozenThresholdPolicyRecord `
        -ValidationProfile $ValidationProfile -Context 'personaNeed' -Errors $errors

    foreach ($record in @($linkEvidenceRecords.currentFleetIssue)) {
        Test-RequiredProperties -Object $record -Names @(
            'subjectRef', 'cohortRef', 'observationWindow', 'baselineFingerprint',
            'evidenceReleaseRef', 'distributionRef', 'coverageStatus'
        ) -Context "current fleet evidence $($record.recordId)" -Errors $errors
        if ([string]$record.subjectRef -cne [string]$Chain.currentFleetIssue.incumbentControlRef -or
            [string]$record.cohortRef -cne [string]$Chain.currentFleetIssue.cohortRef -or
            [string]$record.observationWindow -cne [string]$Chain.currentFleetIssue.observationWindow -or
            [string]$record.baselineFingerprint -cne [string]$Chain.currentFleetIssue.baselineFingerprint -or
            [string]$record.evidenceReleaseRef -cne [string]$Chain.currentFleetIssue.evidenceReleaseRef -or
            [string]$record.coverageStatus -cne 'PASS') {
            Add-BlueprintError -Errors $errors -Code 'CURRENT_FLEET_EVIDENCE_BINDING_MISMATCH' -Message 'Current-fleet evidence is not bound to the incumbent, cohort, window, baseline, release, distribution, and passing coverage.'
        }
    }
    Test-EvidenceReleaseBinding -ReleaseRecord $fleetEvidenceRelease -EvidenceRecords @($linkEvidenceRecords.currentFleetIssue) `
        -RecordMap $recordMap -EvaluationTime $EvaluationTime -ConsumerRecord $verdictRecord -Manifest $manifestRecord `
        -Phase0TestPlan $testPlanRecord -ThresholdPolicy $frozenThresholdPolicyRecord `
        -ValidationProfile $ValidationProfile -Context 'currentFleetIssue' -Errors $errors

    $observedComparisonTuples = [System.Collections.Generic.Dictionary[string,object]]::new([System.StringComparer]::Ordinal)
    $comparisonTimestampGroups = [System.Collections.Generic.Dictionary[string,object]]::new([System.StringComparer]::Ordinal)
    foreach ($record in @($linkEvidenceRecords.candidateComparison)) {
        Test-RequiredProperties -Object $record -Names @(
            'subjectRef', 'controlRole', 'testPlanRef', 'testRef', 'conditionRef', 'baselineFingerprint',
            'testPackVersion', 'evidenceReleaseRef', 'distributionRef', 'coverageStatus'
        ) -Context "candidate comparison evidence $($record.recordId)" -Errors $errors
        $expectedSubject = switch ([string]$record.controlRole) {
            'candidate' { [string]$Chain.candidateComparison.candidateRef }
            'incumbent' { [string]$Chain.candidateComparison.incumbentControlRef }
            'sibling-or-alternative' { [string]$Chain.candidateComparison.siblingControlRef }
            default { '' }
        }
        if ([string]::IsNullOrWhiteSpace($expectedSubject)) {
            Add-BlueprintError -Errors $errors -Code 'INVALID_COMPARISON_ROLE' -Message "$($record.recordId) has no canonical candidate, incumbent, or sibling-or-alternative role."
        }
        $tupleKey = Get-CanonicalPayloadDigest -Payload ([pscustomobject][ordered]@{
            testRef = [string]$record.testRef
            controlRole = [string]$record.controlRole
            conditionRef = [string]$record.conditionRef
            baselineFingerprint = [string]$record.baselineFingerprint
        })
        $requiredTuple = if ($comparisonRequirements.Tuples.ContainsKey($tupleKey)) {
            $comparisonRequirements.Tuples[$tupleKey]
        }
        else { $null }
        $comparisonDistribution = if ($distributionByEvidenceId.ContainsKey([string]$record.recordId)) {
            $distributionByEvidenceId[[string]$record.recordId]
        }
        else { $null }
        if ($null -eq $requiredTuple) {
            Add-BlueprintError -Errors $errors -Code 'COMPARISON_TEST_TUPLE_INVALID' -Message 'Candidate-comparison evidence uses a test, role, condition, or baseline tuple not required by a Phase 3 frozen test definition.'
        }
        elseif ($observedComparisonTuples.ContainsKey($tupleKey)) {
            Add-BlueprintError -Errors $errors -Code 'COMPARISON_TEST_TUPLE_INVALID' -Message 'Candidate-comparison evidence repeats an exact Phase 3 test, role, condition, and baseline tuple.'
        }
        else {
            $observedComparisonTuples.Add($tupleKey, $record)
        }
        $concurrentGroupKey = Get-CanonicalPayloadDigest -Payload ([pscustomobject][ordered]@{
            testRef = [string]$record.testRef
            conditionRef = [string]$record.conditionRef
            baselineFingerprint = [string]$record.baselineFingerprint
        })
        if (-not $comparisonTimestampGroups.ContainsKey($concurrentGroupKey)) {
            $comparisonTimestampGroups.Add($concurrentGroupKey, (New-Object System.Collections.ArrayList))
        }
        [DateTimeOffset]$comparisonTimestamp = [DateTimeOffset]::MinValue
        if ([string]$record.admission.mode -cne 'fresh' -or
            -not [OperationsBlueprint.StrictRfc3339]::TryParse([string]$record.timestamp, [ref]$comparisonTimestamp)) {
            Add-BlueprintError -Errors $errors -Code 'DYNAMIC_EVIDENCE_NOT_FRESH' -Message 'Every Phase 3 candidate, incumbent, and sibling comparison record must be freshly observed under one contemporaneous window.'
        }
        else {
            [void]$comparisonTimestampGroups[$concurrentGroupKey].Add($comparisonTimestamp)
        }
        if ([string]$record.subjectRef -cne $expectedSubject -or
            [string]$record.testPlanRef -cne [string]$Chain.candidateComparison.testPlanRef -or
            [string]$record.baselineFingerprint -cne [string]$Chain.candidateComparison.baselineFingerprint -or
            ($null -ne $requiredTuple -and
             ([string]$record.testPackVersion -cne [string]$requiredTuple.testPackVersion -or
              [string]$record.testRef -cne [string]$requiredTuple.testRef)) -or
            [string]$record.testPackVersion -cne [string]$Chain.candidateComparison.testPackVersion -or
            [string]$record.evidenceReleaseRef -cne [string]$Chain.candidateComparison.evidenceReleaseRef -or
            [string]$record.coverageStatus -cne 'PASS' -or
            $null -eq $comparisonDistribution -or
            [string]$comparisonDistribution.testRef -cne [string]$record.testRef -or
            [string]$comparisonDistribution.conditionRef -cne [string]$record.conditionRef -or
            [string]$comparisonDistribution.baselineFingerprint -cne [string]$record.baselineFingerprint -or
            ($null -ne $requiredTuple -and
             ([string]$comparisonDistribution.testDefinitionDigest -cne [string]$requiredTuple.testDefinitionDigest -or
              [string]$comparisonDistribution.testClass -cne [string]$requiredTuple.testClass))) {
            Add-BlueprintError -Errors $errors -Code 'COMPARISON_EVIDENCE_BINDING_MISMATCH' -Message 'Comparison evidence is not bound to the expected subject, role, test plan, condition, baseline, test pack, release, distribution, and passing coverage.'
        }
    }
    foreach ($requiredTupleEntry in @($comparisonRequirements.Tuples.GetEnumerator())) {
        if (-not $observedComparisonTuples.ContainsKey([string]$requiredTupleEntry.Key)) {
            $requiredTuple = $requiredTupleEntry.Value
            Add-BlueprintError -Errors $errors -Code 'COMPARISON_TEST_TUPLE_MISSING' -Message "Candidate comparison lacks a required Phase 3 tuple for test $($requiredTuple.testRef), role $($requiredTuple.controlRole), and condition $($requiredTuple.conditionRef)."
        }
    }
    $phase3TimingPolicy = if ($null -ne $frozenThresholdPolicyRecord -and
        $frozenThresholdPolicyRecord.extensions -is [pscustomobject] -and
        $frozenThresholdPolicyRecord.extensions.operationsBlueprintV1 -is [pscustomobject]) {
        $frozenThresholdPolicyRecord.extensions.operationsBlueprintV1
    }
    else { $null }
    $phase3WindowHours = 0.0
    $phase3WindowPolicyValid = $null -ne $phase3TimingPolicy -and
        (Test-NumberValue $phase3TimingPolicy.phase3ContemporaneityWindowHours) -and
        (Test-CanonicalJsonRuntimeDomain $phase3TimingPolicy.phase3ContemporaneityWindowHours) -and
        [double]$phase3TimingPolicy.phase3ContemporaneityWindowHours -gt 0 -and
        [double]$phase3TimingPolicy.phase3ContemporaneityWindowHours -le 168 -and
        (Test-NonBlankString $phase3TimingPolicy.phase3ContemporaneityRationale) -and
        (Test-NonBlankString $phase3TimingPolicy.phase3ContemporaneityApprovedBy)
    if ($phase3WindowPolicyValid) {
        $phase3WindowHours = [double]$phase3TimingPolicy.phase3ContemporaneityWindowHours
    }
    else {
        Add-BlueprintError -Errors $errors -Code 'PHASE3_CONTEMPORANEITY_POLICY_INVALID' -Message 'The authenticated frozen threshold policy lacks a positive bounded Phase 3 contemporaneity window, rationale, and approver.'
    }
    foreach ($timestampGroup in @($comparisonTimestampGroups.Values)) {
        $timestamps = @($timestampGroup)
        if ($timestamps.Count -ne 3) {
            Add-BlueprintError -Errors $errors -Code 'COMPARISON_EVIDENCE_NOT_CONTEMPORANEOUS' -Message 'Each Phase 3 test, condition, and baseline requires exactly one fresh candidate, incumbent, and sibling observation timestamp.'
            continue
        }
        $orderedTimestamps = @($timestamps | Sort-Object)
        if (-not $phase3WindowPolicyValid -or
            ($orderedTimestamps[-1] - $orderedTimestamps[0]).TotalHours -gt $phase3WindowHours) {
            Add-BlueprintError -Errors $errors -Code 'COMPARISON_EVIDENCE_NOT_CONTEMPORANEOUS' -Message 'Phase 3 candidate, incumbent, and sibling observations for the same test and condition exceed the exact window approved in the frozen threshold policy.'
        }
    }
    if ($null -ne $candidateEvidenceRelease) {
        Test-RequiredProperties -Object $candidateEvidenceRelease -Names @('testPlanRef', 'conditionRefs', 'baselineFingerprint', 'testPackVersion') -Context 'candidate comparison evidence release' -Errors $errors
        if ([string]$candidateEvidenceRelease.testPlanRef -cne [string]$Chain.candidateComparison.testPlanRef -or
            [string]$candidateEvidenceRelease.baselineFingerprint -cne [string]$Chain.candidateComparison.baselineFingerprint -or
            [string]$candidateEvidenceRelease.testPackVersion -cne [string]$Chain.candidateComparison.testPackVersion) {
            Add-BlueprintError -Errors $errors -Code 'COMPARISON_RELEASE_BINDING_MISMATCH' -Message 'Comparison release is not bound to the frozen test plan, baseline, and test pack.'
        }
        if (@($candidateEvidenceRelease.conditionRefs).Count -ne $requiredConditionRefs.Count) {
            Add-BlueprintError -Errors $errors -Code 'COMPARISON_RELEASE_CONDITION_MISMATCH' -Message 'Comparison release does not bind the exact frozen condition set.'
        }
        foreach ($requiredConditionRef in $requiredConditionRefs) {
            if (@($candidateEvidenceRelease.conditionRefs) -cnotcontains [string]$requiredConditionRef) {
                Add-BlueprintError -Errors $errors -Code 'COMPARISON_RELEASE_CONDITION_MISMATCH' -Message "Comparison release omits frozen condition $requiredConditionRef."
            }
        }
    }
    Test-EvidenceReleaseBinding -ReleaseRecord $candidateEvidenceRelease -EvidenceRecords @($linkEvidenceRecords.candidateComparison) `
        -RecordMap $recordMap -EvaluationTime $EvaluationTime -ConsumerRecord $verdictRecord -Manifest $manifestRecord `
        -Phase0TestPlan $testPlanRecord -ThresholdPolicy $frozenThresholdPolicyRecord `
        -ValidationProfile $ValidationProfile -Context 'candidateComparison' -Errors $errors

    if ([string]$Chain.businessEffect.status -ceq 'MEASURED') {
        foreach ($record in @($linkEvidenceRecords.businessEffect)) {
            Test-RequiredProperties -Object $record -Names @(
                'businessEffectRef', 'observationWindow', 'evidenceReleaseRef', 'distributionRef', 'coverageStatus'
            ) -Context "business effect evidence $($record.recordId)" -Errors $errors
            if ([string]$record.businessEffectRef -cne [string]$Chain.businessEffect.businessEffectRef -or
                [string]$record.observationWindow -cne [string]$Chain.businessEffect.observationWindow -or
                [string]$record.evidenceReleaseRef -cne [string]$Chain.businessEffect.evidenceReleaseRef -or
                [string]$record.coverageStatus -cne 'PASS') {
                Add-BlueprintError -Errors $errors -Code 'BUSINESS_EFFECT_EVIDENCE_BINDING_MISMATCH' -Message 'Business-effect evidence is not bound to the exact record, window, release, distribution, and passing coverage.'
            }
        }
        Test-EvidenceReleaseBinding -ReleaseRecord $businessEvidenceRelease -EvidenceRecords @($linkEvidenceRecords.businessEffect) `
            -RecordMap $recordMap -EvaluationTime $EvaluationTime -ConsumerRecord $verdictRecord -Manifest $manifestRecord `
            -Phase0TestPlan $testPlanRecord -ThresholdPolicy $frozenThresholdPolicyRecord `
            -ValidationProfile $ValidationProfile -Context 'businessEffect' -Errors $errors
    }

    $expectedFreshnessPolicyRef = if ($null -ne $frozenThresholdPolicyRecord) { [string]$frozenThresholdPolicyRecord.recordId } else { '' }
    $expectedFreshnessPolicyDigest = if ($null -ne $frozenThresholdPolicyRecord) { [string]$frozenThresholdPolicyRecord.contentDigest } else { '' }
    $personaFreshnessSources = @($personaEvidenceRelease) + @($linkEvidenceRecords.personaNeed)
    Test-LeadershipFreshnessBinding -Link $Chain.personaNeed -LinkName 'personaNeed' -RecordMap $recordMap `
        -ExpectedPolicyRef $expectedFreshnessPolicyRef -ExpectedPolicyDigest $expectedFreshnessPolicyDigest `
        -SourceRecords $personaFreshnessSources -EvaluationTime $EvaluationTime -LineageGeneratedAt $lineageGeneratedAt -Errors $errors
    $fleetFreshnessSources = @($fleetEvidenceRelease) + @($linkEvidenceRecords.currentFleetIssue)
    Test-LeadershipFreshnessBinding -Link $Chain.currentFleetIssue -LinkName 'currentFleetIssue' -RecordMap $recordMap `
        -ExpectedPolicyRef $expectedFreshnessPolicyRef -ExpectedPolicyDigest $expectedFreshnessPolicyDigest `
        -SourceRecords $fleetFreshnessSources -EvaluationTime $EvaluationTime -LineageGeneratedAt $lineageGeneratedAt `
        -ObservationWindow ([string]$Chain.currentFleetIssue.observationWindow) -Errors $errors
    $candidateFreshnessSources = @($candidateEvidenceRelease) + @($linkEvidenceRecords.candidateComparison)
    Test-LeadershipFreshnessBinding -Link $Chain.candidateComparison -LinkName 'candidateComparison' -RecordMap $recordMap `
        -ExpectedPolicyRef $expectedFreshnessPolicyRef -ExpectedPolicyDigest $expectedFreshnessPolicyDigest `
        -SourceRecords $candidateFreshnessSources -EvaluationTime $EvaluationTime -LineageGeneratedAt $lineageGeneratedAt -Errors $errors
    if ([string]$Chain.businessEffect.status -ceq 'MEASURED') {
        $businessFreshnessSources = @($businessEffectRecord, $businessEvidenceRelease) + @($linkEvidenceRecords.businessEffect)
        Test-LeadershipFreshnessBinding -Link $Chain.businessEffect -LinkName 'businessEffect' -RecordMap $recordMap `
            -ExpectedPolicyRef $expectedFreshnessPolicyRef -ExpectedPolicyDigest $expectedFreshnessPolicyDigest `
            -SourceRecords $businessFreshnessSources -EvaluationTime $EvaluationTime -LineageGeneratedAt $lineageGeneratedAt `
            -ObservationWindow ([string]$Chain.businessEffect.observationWindow) -Errors $errors
    }
    else {
        $unmeasuredBusinessFreshnessSources = @($candidateQuoteRecord, $controlQuoteRecord)
        Test-LeadershipFreshnessBinding -Link $Chain.businessEffect -LinkName 'businessEffect' -RecordMap $recordMap `
            -ExpectedPolicyRef $expectedFreshnessPolicyRef -ExpectedPolicyDigest $expectedFreshnessPolicyDigest `
            -SourceRecords $unmeasuredBusinessFreshnessSources -EvaluationTime $EvaluationTime `
            -LineageGeneratedAt $lineageGeneratedAt -Errors $errors
    }
    $recommendationFreshnessSources = @($verdictRecord, $decisionClaimRecord)
    Test-LeadershipFreshnessBinding -Link $Chain.recommendation -LinkName 'recommendation' -RecordMap $recordMap `
        -ExpectedPolicyRef $expectedFreshnessPolicyRef -ExpectedPolicyDigest $expectedFreshnessPolicyDigest `
        -SourceRecords $recommendationFreshnessSources -EvaluationTime $EvaluationTime `
        -LineageGeneratedAt $lineageGeneratedAt -Errors $errors

    $semanticRecord = Resolve-CanonicalRecord -RecordMap $recordMap -Reference $Chain.lineage.semanticValidationRef -ExpectedTypes @('semantic-validation-record') -Context 'semantic validation lineage' -Errors $errors
    if ($null -ne $semanticRecord) {
        Test-RequiredProperties -Object $semanticRecord -Names @(
            'inputDigest', 'validatorReleaseRef', 'validatorReleaseDigest', 'validationResultDigest',
            'sourceRecordSetDigest', 'sourceRecordRefs', 'validationResult', 'validatedAt',
            'evaluationTime', 'expiresAt'
        ) -Context 'semantic validation record' -Errors $errors
        $calculatedSemanticInputDigest = Get-LeadershipSemanticInputDigest -Chain $Chain -RecordMap $recordMap
        [string[]]$expectedSemanticSourceRefs = @(Get-LeadershipSemanticInputDigest -Chain $Chain -RecordMap $recordMap -ReturnSourceRecordRefs)
        [DateTimeOffset]$semanticValidatedAt = [DateTimeOffset]::MinValue
        [DateTimeOffset]$semanticEvaluationTime = [DateTimeOffset]::MinValue
        [DateTimeOffset]$semanticExpiresAt = [DateTimeOffset]::MinValue
        [string[]]$semanticSourceRefs = @()
        if (@($semanticRecord.sourceRecordRefs).Count -gt 0) {
            $semanticSourceRefs = [string[]]@($semanticRecord.sourceRecordRefs)
            [Array]::Sort($semanticSourceRefs, [StringComparer]::Ordinal)
        }
        $expectedSemanticSourceSetDigest = Get-CanonicalPayloadDigest -Payload ([pscustomobject]@{ sourceRecordRefs = @($expectedSemanticSourceRefs) })
        $expectedSemanticValidationResultDigest = Get-SemanticValidationResultDigest -SemanticRecord $semanticRecord
        # This is the byte digest of the immutable v2.0.1 ContractSchemas.Tests.ps1
        # release containing Test-ContractBundleSemantics. The private release
        # may attest and distribute those bytes, but it may not substitute a
        # weaker schema-only or caller-selected semantic validator.
        $expectedSemanticValidatorReleaseDigest = 'sha256:b4fdd5765b3d850a296a2948e50d17c6f5b457316adbe903dc13894a9bf66466'
        if (-not [OperationsBlueprint.StrictRfc3339]::TryParse([string]$semanticRecord.validatedAt, [ref]$semanticValidatedAt) -or
            $semanticValidatedAt -lt $lineageGeneratedAt -or $semanticValidatedAt -gt $EvaluationTime) {
            Add-BlueprintError -Errors $errors -Code 'SEMANTIC_VALIDATION_TIME_INVALID' -Message 'Semantic validation must occur after claim generation and not in the future.'
        }
        if (-not [OperationsBlueprint.StrictRfc3339]::TryParse([string]$semanticRecord.evaluationTime, [ref]$semanticEvaluationTime) -or
            -not [OperationsBlueprint.StrictRfc3339]::TryParse([string]$semanticRecord.expiresAt, [ref]$semanticExpiresAt) -or
            $semanticEvaluationTime -gt $semanticValidatedAt -or $semanticExpiresAt -le $EvaluationTime) {
            Add-BlueprintError -Errors $errors -Code 'SEMANTIC_VALIDATION_TIME_INVALID' -Message 'Semantic validation evaluation and expiry must be ordered, current, and non-future.'
        }
        foreach ($expectedSourceRef in @($expectedSemanticSourceRefs)) {
            $expectedSourceId = ([string]$expectedSourceRef).Split('#', 2)[0]
            if (-not $recordMap.ContainsKey($expectedSourceId)) { continue }
            $expectedSource = $recordMap[$expectedSourceId]
            [DateTimeOffset]$sourceValidatedAt = [DateTimeOffset]::MinValue
            [DateTimeOffset]$sourceProjectedAt = [DateTimeOffset]::MinValue
            if ([string]$expectedSource.recordType -ceq 'portable-contract-validation-record' -and
                (-not [OperationsBlueprint.StrictRfc3339]::TryParse([string]$expectedSource.validatedAt, [ref]$sourceValidatedAt) -or
                 $sourceValidatedAt -gt $semanticValidatedAt -or [string]$expectedSource.status -cne 'VERIFIED')) {
                Add-BlueprintError -Errors $errors -Code 'SEMANTIC_VALIDATION_SOURCE_CHRONOLOGY_INVALID' -Message 'Bundle-semantic validation must occur after every complete portable-source schema validation it includes.'
            }
            if ($null -ne $expectedSource.PSObject.Properties['portableProjectionRecord'] -and
                (-not [OperationsBlueprint.StrictRfc3339]::TryParse([string]$expectedSource.portableProjectionRecord.projectedAt, [ref]$sourceProjectedAt) -or
                 $sourceProjectedAt -gt $semanticValidatedAt)) {
                Add-BlueprintError -Errors $errors -Code 'SEMANTIC_VALIDATION_SOURCE_CHRONOLOGY_INVALID' -Message 'Bundle-semantic validation predates one of the exact authenticated portable projections it claims to validate.'
            }
        }
        if ([string]$semanticRecord.contentDigest -cne [string]$Chain.lineage.semanticValidationDigest -or
            [string]$semanticRecord.inputDigest -cne [string]$Chain.lineage.semanticInputDigest -or
            [string]$semanticRecord.inputDigest -cne [string]$calculatedSemanticInputDigest -or
            [string]$semanticRecord.validatorReleaseRef -cne [string]$Chain.lineage.validatorReleaseRef -or
            [string]$semanticRecord.validatorReleaseDigest -cne $expectedSemanticValidatorReleaseDigest -or
            [string]$semanticRecord.validationResultDigest -cne [string]$expectedSemanticValidationResultDigest -or
            [string]$semanticRecord.sourceRecordSetDigest -cne [string]$expectedSemanticSourceSetDigest -or
            @($semanticRecord.sourceRecordRefs).Count -eq 0 -or
            @($semanticRecord.sourceRecordRefs | Group-Object -CaseSensitive | Where-Object Count -gt 1).Count -gt 0 -or
            -not (Test-CanonicalValueEqual @($semanticSourceRefs) @($expectedSemanticSourceRefs)) -or
            [string]$semanticRecord.validationResult -cne 'PASS') {
            Add-BlueprintError -Errors $errors -Code 'SEMANTIC_VALIDATION_BINDING_MISMATCH' -Message 'Semantic validation must bind the exact canonical decision-input digest, immutable v2.0.1 bundle-semantic validator, complete transitive source-record set, retained attestation, and PASS result.'
        }
        foreach ($semanticSourceRef in @($semanticRecord.sourceRecordRefs)) {
            $semanticSourceId = ([string]$semanticSourceRef).Split('#', 2)[0]
            $semanticSourceTypes = if ($recordMap.ContainsKey($semanticSourceId)) {
                @([string]$recordMap[$semanticSourceId].recordType)
            }
            else { @('unresolved-semantic-source') }
            [void](Resolve-CanonicalRecord -RecordMap $recordMap -Reference $semanticSourceRef `
                -ExpectedTypes $semanticSourceTypes `
                -Context 'leadership semantic source closure' -Errors $errors)
        }
        foreach ($requiredSemanticSourceRef in @([string]$Chain.personaNeed.manifestRef, [string]$Chain.recommendation.verdictRef)) {
            if (@($semanticRecord.sourceRecordRefs) -cnotcontains $requiredSemanticSourceRef) {
                Add-BlueprintError -Errors $errors -Code 'SEMANTIC_SOURCE_CLOSURE_INCOMPLETE' -Message 'Semantic validation source closure omits the exact manifest or final verdict.'
            }
        }
        if ($null -ne $decisionClaimRecord) {
            [DateTimeOffset]$decisionRenderedAfterSemantic = [DateTimeOffset]::MinValue
            if (-not [OperationsBlueprint.StrictRfc3339]::TryParse([string]$decisionClaimRecord.renderedAt, [ref]$decisionRenderedAfterSemantic) -or
                $decisionRenderedAfterSemantic -lt $semanticValidatedAt) {
                Add-BlueprintError -Errors $errors -Code 'DECISION_CLAIM_CHRONOLOGY_INVALID' -Message 'The deterministic decision claim must be rendered after the bound semantic validation completed.'
            }
        }
    }
    $verdictPrefix = ([string]$Chain.recommendation.verdictRef) + '#'
    foreach ($pointerName in @('fleetVerdictPointer', 'personaVerdictPointer', 'procurementEnvelopePointer')) {
        $pointer = [string]$Chain.recommendation.$pointerName
        if (-not $pointer.StartsWith($verdictPrefix, [System.StringComparison]::Ordinal)) {
            Add-BlueprintError -Errors $errors -Code 'VERDICT_POINTER_MISMATCH' -Message "$pointerName does not point into verdictRef."
        }
    }

    $claimState = if ($errors.Count -gt 0) { 'BLOCKED' }
        elseif ([string]$ValidationProfile -ceq 'TEST') { 'TEST_FIXTURE_VALIDATED' }
        else { 'VALIDATED_DERIVED_INPUT' }
    $result = New-BlueprintResult -Errors $errors -State $claimState
    $result.Allowed = $false
    return $result
}

function Test-CanonicalValueEqual {
    param([AllowNull()]$Left, [AllowNull()]$Right)

    return (ConvertTo-DeterministicJsonText -Value (ConvertTo-CanonicalJsonValue $Left)) -ceq
        (ConvertTo-DeterministicJsonText -Value (ConvertTo-CanonicalJsonValue $Right))
}

function Get-WriteAuthorizationRequestDigest {
    param([Parameter(Mandatory = $true)]$Request)

    $intent = [ordered]@{
        requestedStage = [string]$Request.requestedStage
        desiredStateRevision = [string]$Request.desiredStateRevision
        graphWriteRevision = [string]$Request.graphWriteRevision
        reviewedPlanRef = [string]$Request.reviewedPlanRef
        reviewedPlanDigest = [string]$Request.reviewedPlanDigest
        packageDigest = [string]$Request.packageDigest
        packageVerificationRef = [string]$Request.packageVerificationRef
        packageVerificationDigest = [string]$Request.packageVerificationDigest
        packageRevocationFreshnessPolicyRef = [string]$Request.packageRevocationFreshnessPolicyRef
        packageRevocationFreshnessPolicyDigest = [string]$Request.packageRevocationFreshnessPolicyDigest
        packageRevocationCheckMaxAgeMinutes = $Request.packageRevocationCheckMaxAgeMinutes
        targetMembershipDigest = [string]$Request.targetMembershipDigest
        targetPopulation = $Request.targetPopulation
        targetRing = [string]$Request.targetRing
        targetScopeRef = [string]$Request.targetScopeRef
        tenantBoundaryRef = [string]$Request.tenantBoundaryRef
        targetEnvironmentRef = [string]$Request.targetEnvironmentRef
        managedObjectType = [string]$Request.managedObjectType
        managedObjectRefs = @($Request.managedObjectRefs)
        managedObjectSetDigest = [string]$Request.managedObjectSetDigest
        consumptionLedgerRef = [string]$Request.consumptionLedgerRef
        consumptionLedgerPolicyRef = [string]$Request.consumptionLedgerPolicyRef
        consumptionLedgerPolicyDigest = [string]$Request.consumptionLedgerPolicyDigest
        independentReadbackPolicyRef = [string]$Request.independentReadbackPolicyRef
        independentReadbackPolicyDigest = [string]$Request.independentReadbackPolicyDigest
        readbackMaxAgeMinutes = $Request.readbackMaxAgeMinutes
        authorizationTtlPolicyRef = [string]$Request.authorizationTtlPolicyRef
        authorizationTtlPolicyDigest = [string]$Request.authorizationTtlPolicyDigest
        authorizationMaxTtlMinutes = $Request.authorizationMaxTtlMinutes
        authorizationRevocationFreshnessPolicyRef = [string]$Request.authorizationRevocationFreshnessPolicyRef
        authorizationRevocationFreshnessPolicyDigest = [string]$Request.authorizationRevocationFreshnessPolicyDigest
        authorizationRevocationCheckMaxAgeMinutes = $Request.authorizationRevocationCheckMaxAgeMinutes
        writerToolRef = [string]$Request.writerToolRef
        writeIdentityRef = [string]$Request.writeIdentityRef
        applyOperatorIdentityRef = [string]$Request.applyOperatorIdentityRef
        manifestRef = [string]$Request.manifestRef
        personaId = [string]$Request.personaId
        requesterPrincipalRef = [string]$Request.requesterPrincipalRef
        transportOwnershipRecordRef = [string]$Request.transportOwnershipRecordRef
        transportOwnershipRecordDigest = [string]$Request.transportOwnershipRecordDigest
        roleBindingRef = [string]$Request.roleBindingRef
        roleBindingDigest = [string]$Request.roleBindingDigest
        roleBindingReadbackRef = [string]$Request.roleBindingReadbackRef
        roleBindingReadbackDigest = [string]$Request.roleBindingReadbackDigest
        transportSelectionStatus = [string]$Request.transportSelectionStatus
        writeOperationId = [string]$Request.writeOperationId
        protectedApprovalRef = [string]$Request.protectedApprovalRef
        approvalRecordDigest = [string]$Request.approvalRecordDigest
        approvalExpiresAt = [string]$Request.approvalExpiresAt
        approvalSetStatus = [string]$Request.approvalSetStatus
        approvalRoleIds = @($Request.approvalRoleIds)
        approvalSetScopeRef = [string]$Request.approvalSetScopeRef
        approvalSetPlanDigest = [string]$Request.approvalSetPlanDigest
        privateActivationRecordRef = [string]$Request.privateActivationRecordRef
        privateActivationRecordDigest = [string]$Request.privateActivationRecordDigest
        transportExceptionRef = [string]$Request.transportExceptionRef
        transportExceptionDigest = [string]$Request.transportExceptionDigest
        transportExceptionExpiresAt = [string]$Request.transportExceptionExpiresAt
        rolloutMonitoringRef = [string]$Request.rolloutMonitoringRef
        rolloutMonitoringRecordDigest = [string]$Request.rolloutMonitoringRecordDigest
        authorization = $Request.authorization
    }
    return Get-CanonicalPayloadDigest -Payload ([pscustomobject]$intent)
}

function Get-TargetCompositionDigest {
    param(
        [Parameter(Mandatory = $true)]$TargetPopulation,
        [Parameter(Mandatory = $true)][string]$TargetScopeRef,
        [Parameter(Mandatory = $true)][string]$TargetRing,
        [Parameter(Mandatory = $true)][string]$PersonaId
    )

    [string[]]$sortedExclusions = @()
    if (@($TargetPopulation.exclusionRefs).Count -gt 0) {
        $sortedExclusions = [string[]]@($TargetPopulation.exclusionRefs)
        [Array]::Sort($sortedExclusions, [StringComparer]::Ordinal)
    }
    return Get-CanonicalPayloadDigest -Payload ([pscustomobject][ordered]@{
        targetScopeRef = $TargetScopeRef
        targetRing = $TargetRing
        personaId = $PersonaId
        targetPopulationCount = $TargetPopulation.targetPopulationCount
        exclusionRefs = @($sortedExclusions)
        groupMembershipRuleDigest = [string]$TargetPopulation.groupMembershipRuleDigest
        assignmentFilterDigest = [string]$TargetPopulation.assignmentFilterDigest
        assignmentFilterMode = [string]$TargetPopulation.assignmentFilterMode
        dynamicMembershipPolicy = [string]$TargetPopulation.dynamicMembershipPolicy
    })
}

function Get-ManagedObjectSetDigest {
    param([AllowNull()]$ManagedObjectRefs)

    [string[]]$sortedRefs = @()
    if (@($ManagedObjectRefs).Count -gt 0) {
        $sortedRefs = [string[]]@($ManagedObjectRefs | ForEach-Object { [string]$_ })
        [Array]::Sort($sortedRefs, [StringComparer]::Ordinal)
    }
    return Get-CanonicalPayloadDigest -Payload ([pscustomobject][ordered]@{
        managedObjectRefs = @($sortedRefs)
    })
}

function Get-AtmosOrderedSourceSetDigest {
    param([AllowNull()]$OrderedSourceBindings)

    $canonicalSources = @(
        foreach ($source in @($OrderedSourceBindings | Where-Object { $null -ne $_ })) {
            [pscustomobject][ordered]@{
                order = $source.order
                sourceKind = [string]$source.sourceKind
                sourceRef = [string]$source.sourceRef
                sourceDigest = [string]$source.sourceDigest
            }
        }
    )
    return Get-CanonicalPayloadDigest -Payload ([pscustomobject][ordered]@{
        orderedSourceBindings = @($canonicalSources)
    })
}

function Test-BusinessImpactRecordSemantics {
    param(
        [Parameter(Mandatory = $true)]$Record,
        [Parameter(Mandatory = $true)]$RecordMap,
        [Parameter(Mandatory = $true)][DateTimeOffset]$EvaluationTime,
        [Parameter(Mandatory = $true)][AllowEmptyCollection()][System.Collections.ArrayList]$Errors
    )

    $effectType = [string]$Record.effectType
    $metadataFields = @('record', 'validFrom', 'validUntil')
    $freshness = $Record.freshnessBinding
    $freshnessValid = $true
    if ($effectType -cin @('COST_DELTA', 'NON_PRICE_EFFECT')) {
        if ($freshness -isnot [pscustomobject]) {
            $freshnessValid = $false
        }
        else {
            Test-RequiredProperties -Object $freshness -Names @(
                'observedAt', 'admittedAt', 'policyRef', 'maxAgeDays',
                'dependencySnapshotRef', 'dependencySnapshotDigest', 'dependencyStatus'
            ) -Context 'business-effect freshness binding' -Errors $Errors
            [DateTimeOffset]$observedAt = [DateTimeOffset]::MinValue
            [DateTimeOffset]$admittedAt = [DateTimeOffset]::MinValue
            $maxAgeValid = ($freshness.maxAgeDays -is [int] -or $freshness.maxAgeDays -is [long]) -and
                [int64]$freshness.maxAgeDays -ge 1 -and [int64]$freshness.maxAgeDays -le 3650
            $freshnessValid = [OperationsBlueprint.StrictRfc3339]::TryParse([string]$freshness.observedAt, [ref]$observedAt) -and
                [OperationsBlueprint.StrictRfc3339]::TryParse([string]$freshness.admittedAt, [ref]$admittedAt) -and
                $observedAt -le $admittedAt -and $admittedAt -le $EvaluationTime -and $maxAgeValid -and
                ($EvaluationTime - $observedAt).TotalDays -le [int64]$(if ($maxAgeValid) { $freshness.maxAgeDays } else { 1 }) -and
                [string]$freshness.dependencyStatus -ceq 'MATCH' -and
                (Test-Sha256Token $freshness.dependencySnapshotDigest)

            $supportedFreshnessTypes = @(
                'candidate-manifest','test-plan','evidence-record','threshold-policy','verdict-record',
                'evidence-release','cohort-record','business-impact-record','commercial-quote-record',
                'distribution-record','platform-baseline-record','fleet-portfolio-record','coverage-policy-record'
            )
            $freshnessPolicy = Resolve-CanonicalRecord -RecordMap $RecordMap -Reference $freshness.policyRef `
                -ExpectedTypes $supportedFreshnessTypes -Context 'business-effect freshness policy' -Errors $Errors
            $dependencySnapshot = Resolve-CanonicalRecord -RecordMap $RecordMap -Reference $freshness.dependencySnapshotRef `
                -ExpectedTypes $supportedFreshnessTypes -Context 'business-effect dependency snapshot' -Errors $Errors
            $snapshotFound = $false
            $snapshotValue = $null
            $snapshotRefParts = ([string]$freshness.dependencySnapshotRef).Split('#', 2)
            if ($null -ne $dependencySnapshot -and $snapshotRefParts.Count -eq 2) {
                $snapshotValue = Get-JsonPointerValue -Document $dependencySnapshot.payload -Pointer $snapshotRefParts[1] -Found ([ref]$snapshotFound)
            }
            if ($null -eq $freshnessPolicy -or $null -eq $dependencySnapshot -or -not $snapshotFound -or
                (Get-CanonicalPayloadDigest -Payload $snapshotValue) -cne [string]$freshness.dependencySnapshotDigest) {
                $freshnessValid = $false
            }
        }
        if (-not $freshnessValid) {
            Add-BlueprintError -Errors $Errors -Code 'BUSINESS_EFFECT_FRESHNESS_INVALID' -Message 'A measured business effect requires a current MATCH freshness binding whose policy and dependency snapshot resolve exactly.'
        }
    }

    if ($effectType -ceq 'COST_DELTA') {
        $requiredFields = @(
            'effectType','businessEffectStatement','observationWindow','assumptions','currency','quantity',
            'candidateQuoteRef','controlQuoteRef','quoteValidUntil','calculation','calculationMethod',
            'calculationResult','resultUnit','uncertainty','freshnessBinding'
        )
        Test-RequiredProperties -Object $Record -Names $requiredFields -Context 'COST_DELTA business-impact record' -Errors $Errors
        Test-AllowedProperties -Object $Record.payload -Names @($metadataFields + $requiredFields) -Context 'COST_DELTA business-impact payload' -Errors $Errors
        $assumptions = @($Record.assumptions)
        $quantityValid = (Test-NumberValue $Record.quantity) -and [decimal]$Record.quantity -gt 0
        $calculationValid = $Record.calculation -is [pscustomobject] -and
            [string]$Record.calculation.method -ceq 'candidate-total-minus-control-total' -and
            (Test-NumberValue $Record.calculation.result) -and (Test-NumberValue $Record.calculationResult)
        if (-not (Test-NonBlankString $Record.businessEffectStatement) -or
            -not (Test-ObservationWindow -Value $Record.observationWindow -EvaluationTime $EvaluationTime) -or
            $assumptions.Count -eq 0 -or @($assumptions | Where-Object { -not (Test-NonBlankString $_) }).Count -gt 0 -or
            @($assumptions | Group-Object -CaseSensitive | Where-Object Count -gt 1).Count -gt 0 -or
            [string]$Record.currency -cnotmatch '^[A-Z]{3}$' -or -not $quantityValid -or
            [string]$Record.candidateQuoteRef -ceq [string]$Record.controlQuoteRef -or
            [string]$Record.calculationMethod -cne 'candidate-total-minus-control-total' -or
            [string]$Record.resultUnit -cne [string]$Record.currency -or
            -not (Test-NonBlankString $Record.uncertainty) -or -not $calculationValid) {
            Add-BlueprintError -Errors $Errors -Code 'BUSINESS_EFFECT_POSTURE_INVALID' -Message 'COST_DELTA requires a closed observation window, unique assumptions, current distinct quotes, a positive quantity, ISO currency, and the frozen candidate-minus-control calculation.'
        }

        $candidateQuote = Resolve-CanonicalRecord -RecordMap $RecordMap -Reference $Record.candidateQuoteRef `
            -ExpectedTypes @('commercial-quote-record') -Context 'business-effect candidate quote' -Errors $Errors
        $controlQuote = Resolve-CanonicalRecord -RecordMap $RecordMap -Reference $Record.controlQuoteRef `
            -ExpectedTypes @('commercial-quote-record') -Context 'business-effect control quote' -Errors $Errors
        [DateTimeOffset]$declaredQuoteValidUntil = [DateTimeOffset]::MinValue
        $declaredQuoteTimeValid = [OperationsBlueprint.StrictRfc3339]::TryParse([string]$Record.quoteValidUntil, [ref]$declaredQuoteValidUntil) -and
            $declaredQuoteValidUntil -gt $EvaluationTime
        $quoteBindingsValid = $declaredQuoteTimeValid -and $null -ne $candidateQuote -and $null -ne $controlQuote
        $quoteExpirations = New-Object System.Collections.ArrayList
        foreach ($quote in @($candidateQuote, $controlQuote)) {
            if ($null -eq $quote) { continue }
            Test-RequiredProperties -Object $quote -Names @(
                'currency','quantity','unitPrice','totalPrice','quotedAt','validUntil'
            ) -Context 'business-effect commercial quote' -Errors $Errors
            [DateTimeOffset]$quotedAt = [DateTimeOffset]::MinValue
            [DateTimeOffset]$validUntil = [DateTimeOffset]::MinValue
            $numericQuote = (Test-NumberValue $quote.unitPrice) -and (Test-NumberValue $quote.totalPrice) -and
                [decimal]$quote.unitPrice -ge 0 -and [decimal]$quote.totalPrice -ge 0
            if ([string]$quote.currency -cne [string]$Record.currency -or
                [string]$quote.quantity -cne [string]$Record.quantity -or -not $numericQuote -or
                ($numericQuote -and [Math]::Abs([double]$quote.totalPrice - ([double]$quote.unitPrice * [double]$quote.quantity)) -gt 0.005) -or
                -not [OperationsBlueprint.StrictRfc3339]::TryParse([string]$quote.quotedAt, [ref]$quotedAt) -or $quotedAt -gt $EvaluationTime -or
                -not [OperationsBlueprint.StrictRfc3339]::TryParse([string]$quote.validUntil, [ref]$validUntil) -or $validUntil -le $EvaluationTime) {
                $quoteBindingsValid = $false
            }
            else { [void]$quoteExpirations.Add($validUntil) }
        }
        if ($quoteExpirations.Count -eq 2) {
            $earliestQuoteExpiry = if ($quoteExpirations[0] -le $quoteExpirations[1]) { $quoteExpirations[0] } else { $quoteExpirations[1] }
            if ($earliestQuoteExpiry -ne $declaredQuoteValidUntil) { $quoteBindingsValid = $false }
        }
        else { $quoteBindingsValid = $false }
        if (-not $quoteBindingsValid) {
            Add-BlueprintError -Errors $Errors -Code 'BUSINESS_EFFECT_SOURCE_BINDING_INVALID' -Message 'COST_DELTA quote references must resolve to current, arithmetically consistent quotes with the same quantity/currency and the earliest expiration.'
        }
        if ($null -ne $candidateQuote -and $null -ne $controlQuote -and $calculationValid -and
            (Test-NumberValue $candidateQuote.totalPrice) -and (Test-NumberValue $controlQuote.totalPrice)) {
            $expectedDelta = [double]$candidateQuote.totalPrice - [double]$controlQuote.totalPrice
            if ([Math]::Abs([double]$Record.calculation.result - $expectedDelta) -gt 0.005 -or
                [Math]::Abs([double]$Record.calculationResult - $expectedDelta) -gt 0.005) {
                Add-BlueprintError -Errors $Errors -Code 'BUSINESS_EFFECT_ARITHMETIC_INVALID' -Message 'COST_DELTA calculation and declared result must equal candidate total minus control total.'
            }
        }
    }
    elseif ($effectType -ceq 'NON_PRICE_EFFECT') {
        $requiredFields = @(
            'effectType','businessEffectStatement','metricId','metricUnit','metricDirection','denominator',
            'observationWindow','distributionRef','distributionDigest','coverage','limitations',
            'sourceRecordBindings','freshnessBinding'
        )
        Test-RequiredProperties -Object $Record -Names $requiredFields -Context 'NON_PRICE_EFFECT business-impact record' -Errors $Errors
        Test-AllowedProperties -Object $Record.payload -Names @($metadataFields + $requiredFields) -Context 'NON_PRICE_EFFECT business-impact payload' -Errors $Errors
        $denominatorValid = $Record.denominator -is [pscustomobject] -and
            (Test-NonBlankString $Record.denominator.definition) -and
            (Test-NonBlankString $Record.denominator.unit) -and
            (Test-NumberValue $Record.denominator.value) -and [decimal]$Record.denominator.value -gt 0
        $coverageValid = $Record.coverage -is [pscustomobject] -and
            ($Record.coverage.expected -is [int] -or $Record.coverage.expected -is [long]) -and
            ($Record.coverage.observed -is [int] -or $Record.coverage.observed -is [long]) -and
            (Test-NumberValue $Record.coverage.percent)
        if ($coverageValid) {
            $coverageValid = [int64]$Record.coverage.expected -gt 0 -and
                [int64]$Record.coverage.observed -gt 0 -and
                [int64]$Record.coverage.observed -le [int64]$Record.coverage.expected -and
                [Math]::Abs([double]$Record.coverage.percent -
                    (([double]$Record.coverage.observed / [double]$Record.coverage.expected) * 100.0)) -le 0.01
        }
        $limitations = @($Record.limitations)
        if (-not (Test-NonBlankString $Record.businessEffectStatement) -or
            [string]$Record.metricId -cnotmatch '^[A-Za-z0-9][A-Za-z0-9._:-]{0,255}$' -or
            -not (Test-NonBlankString $Record.metricUnit) -or
            [string]$Record.metricDirection -cnotin @('HIGHER_IS_BETTER','LOWER_IS_BETTER','TARGET_RANGE','DESCRIPTIVE_ONLY') -or
            -not $denominatorValid -or -not $coverageValid -or
            -not (Test-ObservationWindow -Value $Record.observationWindow -EvaluationTime $EvaluationTime) -or
            $limitations.Count -eq 0 -or @($limitations | Where-Object { -not (Test-NonBlankString $_) }).Count -gt 0 -or
            @($limitations | Group-Object -CaseSensitive | Where-Object Count -gt 1).Count -gt 0 -or
            -not (Test-Sha256Token $Record.distributionDigest)) {
            Add-BlueprintError -Errors $Errors -Code 'BUSINESS_EFFECT_POSTURE_INVALID' -Message 'NON_PRICE_EFFECT requires a named metric, direction, positive denominator, reconciled nonzero coverage, closed observation window, limitations, and an exact distribution digest.'
        }

        $distribution = Resolve-CanonicalRecord -RecordMap $RecordMap -Reference $Record.distributionRef `
            -ExpectedTypes @('distribution-record') -Context 'business-effect distribution' -Errors $Errors
        $rawBindings = @($Record.sourceRecordBindings)
        $bindings = @($rawBindings | Where-Object { $null -ne $_ })
        $bindingsValid = $bindings.Count -gt 0 -and $bindings.Count -eq $rawBindings.Count -and
            @($bindings | Group-Object -Property recordRef -CaseSensitive | Where-Object Count -gt 1).Count -eq 0
        foreach ($binding in $bindings) {
            Test-RequiredProperties -Object $binding -Names @('recordRef','contentDigest') -Context 'business-effect source binding' -Errors $Errors
            $source = Resolve-CanonicalRecord -RecordMap $RecordMap -Reference $binding.recordRef `
                -ExpectedTypes @('evidence-record','evidence-release','distribution-record','cohort-record','fleet-portfolio-record','platform-baseline-record') `
                -Context 'business-effect source binding' -Errors $Errors
            if ($null -eq $source -or [string]$source.contentDigest -cne [string]$binding.contentDigest) { $bindingsValid = $false }
        }
        if ($null -eq $distribution -or [string]$distribution.contentDigest -cne [string]$Record.distributionDigest -or
            @($bindings | Where-Object { [string]$_.recordRef -ceq [string]$Record.distributionRef -and [string]$_.contentDigest -ceq [string]$Record.distributionDigest }).Count -ne 1) {
            $bindingsValid = $false
        }
        if (-not $bindingsValid) {
            Add-BlueprintError -Errors $Errors -Code 'BUSINESS_EFFECT_SOURCE_BINDING_INVALID' -Message 'NON_PRICE_EFFECT must bind its exact distribution and every supporting canonical record by reference and digest.'
        }
    }
    elseif ($effectType -ceq 'NOT_MEASURED') {
        $requiredFields = @('effectType','businessEffectStatement','reason','decisionImpact','recordedAt')
        Test-RequiredProperties -Object $Record -Names $requiredFields -Context 'NOT_MEASURED business-impact record' -Errors $Errors
        Test-AllowedProperties -Object $Record.payload -Names @($metadataFields + $requiredFields) -Context 'NOT_MEASURED business-impact payload' -Errors $Errors
        [DateTimeOffset]$recordedAt = [DateTimeOffset]::MinValue
        if ([string]$Record.businessEffectStatement -cne 'NO_MEASURED_EFFECT_CLAIM' -or
            -not (Test-NonBlankString $Record.reason) -or
            [string]$Record.decisionImpact -cnotin @('HOLD','EXCLUDE_FROM_DECISION','DECISION_MAY_PROCEED_WITHOUT_EFFECT_CLAIM') -or
            -not [OperationsBlueprint.StrictRfc3339]::TryParse([string]$Record.recordedAt, [ref]$recordedAt) -or $recordedAt -gt $EvaluationTime) {
            Add-BlueprintError -Errors $Errors -Code 'BUSINESS_EFFECT_POSTURE_INVALID' -Message 'NOT_MEASURED must be the controlled no-claim statement with a reason, bounded decision impact, and non-future recording time.'
        }
    }
    else {
        Add-BlueprintError -Errors $Errors -Code 'BUSINESS_EFFECT_POSTURE_INVALID' -Message 'A business-impact record must select exactly one COST_DELTA, NON_PRICE_EFFECT, or NOT_MEASURED posture.'
    }
}

function Test-AtmosStackRenderRecordSemantics {
    param(
        [Parameter(Mandatory = $true)]$Record,
        [Parameter(Mandatory = $true)][DateTimeOffset]$EvaluationTime,
        [Parameter(Mandatory = $true)][AllowEmptyCollection()][System.Collections.ArrayList]$Errors
    )

    $requiredFields = @(
        'schemaVersion','recordStage','status','sourceCommit','stackId','environmentId','tenantBoundaryRef','targetEnvironmentRef',
        'orderedSourceBindings','orderedSourceSetDigest','declaredOverrideKeys','usedOverrideKeys',
        'resolvedNonSecretValuesDigest','renderedOutputRef','renderedOutputDigest','affectedComponents',
        'secretScanPolicyRef','secretScanPolicyDigest','secretScanEvidenceRef','secretScanEvidenceDigest',
        'secretScanStatus','policyBundleRef','policyBundleDigest','policyResultsRef','policyResultsDigest',
        'policyStatus','rendererToolRef','rendererVersion','rendererReleaseRef','rendererReleaseDigest','renderedAt'
    )
    Test-RequiredProperties -Object $Record -Names $requiredFields -Context 'Atmos stack-render record' -Errors $Errors
    Test-AllowedProperties -Object $Record.payload -Names @(@('record','validFrom','validUntil') + $requiredFields) -Context 'Atmos stack-render payload' -Errors $Errors

    $rawSourceBindings = @($Record.orderedSourceBindings)
    $sourceBindings = @($rawSourceBindings | Where-Object { $null -ne $_ })
    $sourcesValid = $sourceBindings.Count -gt 0 -and $sourceBindings.Count -eq $rawSourceBindings.Count
    $canonicalSources = New-Object System.Collections.ArrayList
    for ($index = 0; $index -lt $sourceBindings.Count; $index++) {
        $source = $sourceBindings[$index]
        Test-RequiredProperties -Object $source -Names @('order','sourceKind','sourceRef','sourceDigest') -Context 'Atmos ordered source binding' -Errors $Errors
        $expectedOrder = $index + 1
        if (($source.order -isnot [int] -and $source.order -isnot [long]) -or
            [int64]$source.order -ne $expectedOrder -or
            [string]$source.sourceKind -cnotin @('DEFAULTS','CATALOG','STACK','COMPONENT','OVERRIDE') -or
            [string]$source.sourceRef -cnotmatch '^private://' -or -not (Test-Sha256Token $source.sourceDigest)) {
            $sourcesValid = $false
        }
        [void]$canonicalSources.Add([pscustomobject][ordered]@{
            order = $source.order
            sourceKind = [string]$source.sourceKind
            sourceRef = [string]$source.sourceRef
            sourceDigest = [string]$source.sourceDigest
        })
    }
    if (@($sourceBindings | Group-Object -Property order | Where-Object Count -gt 1).Count -gt 0 -or
        @($sourceBindings | Group-Object -Property sourceRef -CaseSensitive | Where-Object Count -gt 1).Count -gt 0) {
        $sourcesValid = $false
    }
    $expectedSourceSetDigest = Get-AtmosOrderedSourceSetDigest -OrderedSourceBindings @($canonicalSources)
    if ([string]$Record.orderedSourceSetDigest -cne [string]$expectedSourceSetDigest) { $sourcesValid = $false }

    $declaredKeys = @($Record.declaredOverrideKeys)
    $usedKeys = @($Record.usedOverrideKeys)
    $overridesValid = @($declaredKeys | Where-Object { [string]$_ -cnotmatch '^[A-Za-z0-9][A-Za-z0-9._:-]{0,255}$' }).Count -eq 0 -and
        @($usedKeys | Where-Object { [string]$_ -cnotmatch '^[A-Za-z0-9][A-Za-z0-9._:-]{0,255}$' }).Count -eq 0 -and
        @($declaredKeys | Group-Object -CaseSensitive | Where-Object Count -gt 1).Count -eq 0 -and
        @($usedKeys | Group-Object -CaseSensitive | Where-Object Count -gt 1).Count -eq 0
    foreach ($usedKey in $usedKeys) {
        if ($declaredKeys -cnotcontains [string]$usedKey) { $overridesValid = $false }
    }
    if ($usedKeys.Count -gt 0 -and @($sourceBindings | Where-Object { [string]$_.sourceKind -ceq 'OVERRIDE' }).Count -eq 0) {
        $overridesValid = $false
    }

    $affectedComponents = @($Record.affectedComponents)
    [DateTimeOffset]$renderedAt = [DateTimeOffset]::MinValue
    $privateRefs = @(
        'tenantBoundaryRef','targetEnvironmentRef','renderedOutputRef','secretScanPolicyRef','secretScanEvidenceRef',
        'policyBundleRef','policyResultsRef','rendererReleaseRef'
    )
    $digestFields = @(
        'orderedSourceSetDigest','resolvedNonSecretValuesDigest','renderedOutputDigest',
        'secretScanPolicyDigest','secretScanEvidenceDigest','policyBundleDigest',
        'policyResultsDigest','rendererReleaseDigest'
    )
    if ([string]$Record.schemaVersion -cne '1.0.0' -or [string]$Record.recordStage -cne 'ATMOS_STACK_RENDER' -or
        [string]$Record.status -cne 'VERIFIED' -or [string]$Record.sourceCommit -cnotmatch '^[0-9a-f]{40}([0-9a-f]{24})?$' -or
        [string]$Record.stackId -cnotmatch '^[A-Za-z0-9][A-Za-z0-9._:-]{0,255}$' -or
        [string]$Record.environmentId -cnotmatch '^[A-Za-z0-9][A-Za-z0-9._:-]{0,255}$' -or
        @($privateRefs | Where-Object { [string]$Record.$_ -cnotmatch '^private://' }).Count -gt 0 -or
        @($digestFields | Where-Object { -not (Test-Sha256Token $Record.$_) }).Count -gt 0 -or
        $affectedComponents.Count -eq 0 -or
        @($affectedComponents | Where-Object { -not (Test-NonBlankString $_) }).Count -gt 0 -or
        @($affectedComponents | Group-Object -CaseSensitive | Where-Object Count -gt 1).Count -gt 0 -or
        [string]$Record.secretScanStatus -cne 'PASS' -or [string]$Record.policyStatus -cne 'PASS' -or
        [string]$Record.rendererToolRef -cne 'atmos' -or -not (Test-NonBlankString $Record.rendererVersion) -or
        -not [OperationsBlueprint.StrictRfc3339]::TryParse([string]$Record.renderedAt, [ref]$renderedAt) -or $renderedAt -gt $EvaluationTime -or
        -not $sourcesValid -or -not $overridesValid) {
        Add-BlueprintError -Errors $Errors -Code 'ATMOS_STACK_RENDER_INVALID' -Message 'Atmos stack render must be a current VERIFIED deterministic composition with contiguous ordered sources, a recomputed source-set digest, declared-only overrides, non-secret output digest, and PASS secret/policy evidence.'
    }
}

function Test-TargetPopulationBinding {
    param(
        $TargetPopulation,
        [Parameter(Mandatory = $true)]$RecordMap,
        [Parameter(Mandatory = $true)][string]$ExpectedTargetScopeRef,
        [Parameter(Mandatory = $true)][string]$ExpectedTenantBoundaryRef,
        [Parameter(Mandatory = $true)][string]$ExpectedTargetEnvironmentRef,
        [Parameter(Mandatory = $true)][string]$ExpectedTargetMembershipDigest,
        [Parameter(Mandatory = $true)][string]$ExpectedTargetRing,
        [Parameter(Mandatory = $true)][string]$ExpectedPersonaId,
        [Parameter(Mandatory = $true)][string]$ExpectedReadbackPolicyRef,
        [string]$WriteIdentityRef,
        [Parameter(Mandatory = $true)][DateTimeOffset]$EvaluationTime,
        [int64]$MaximumAgeMinutes = 1440,
        [Parameter(Mandatory = $true)][string]$Context,
        [Parameter(Mandatory = $true)][AllowEmptyCollection()][System.Collections.ArrayList]$Errors
    )

    if ($TargetPopulation -isnot [pscustomobject]) {
        Add-BlueprintError -Errors $Errors -Code 'TARGET_POPULATION_BINDING_REQUIRED' -Message "$Context requires a structured targetPopulation binding."
        return $null
    }
    $fields = @(
        'populationCeiling', 'targetPopulationCount', 'exclusionRefs', 'targetCompositionDigest',
        'groupMembershipRuleRef', 'groupMembershipRuleDigest',
        'assignmentFilterRef', 'assignmentFilterDigest', 'assignmentFilterMode',
        'dynamicMembershipPolicy',
        'directoryReadbackRef', 'directoryReadbackDigest', 'directoryReadbackAt'
    )
    Test-RequiredProperties -Object $TargetPopulation -Names @($fields | Where-Object { $_ -cne 'exclusionRefs' }) -Context "$Context target population" -Errors $Errors
    if ($null -eq $TargetPopulation.PSObject.Properties['exclusionRefs']) {
        Add-BlueprintError -Errors $Errors -Code 'MISSING_REQUIRED_FIELD' -Message "$Context target population requires exclusionRefs."
    }
    Test-AllowedProperties -Object $TargetPopulation -Names $fields -Context "$Context target population" -Errors $Errors
    $expectedCompositionDigest = Get-TargetCompositionDigest -TargetPopulation $TargetPopulation `
        -TargetScopeRef $ExpectedTargetScopeRef -TargetRing $ExpectedTargetRing -PersonaId $ExpectedPersonaId
    $countsValid = ($TargetPopulation.populationCeiling -is [int] -or $TargetPopulation.populationCeiling -is [long]) -and
        ($TargetPopulation.targetPopulationCount -is [int] -or $TargetPopulation.targetPopulationCount -is [long]) -and
        [int64]$TargetPopulation.populationCeiling -gt 0 -and [int64]$TargetPopulation.targetPopulationCount -gt 0 -and
        [int64]$TargetPopulation.targetPopulationCount -le [int64]$TargetPopulation.populationCeiling
    if (-not $countsValid -or
        @($TargetPopulation.exclusionRefs | Where-Object { $_ -isnot [string] -or [string]$_ -cnotmatch '^private://' }).Count -gt 0 -or
        @($TargetPopulation.exclusionRefs | Group-Object -CaseSensitive | Where-Object Count -gt 1).Count -gt 0 -or
        [string]$TargetPopulation.targetCompositionDigest -cne [string]$expectedCompositionDigest -or
        [string]$TargetPopulation.groupMembershipRuleRef -cnotmatch '^private://' -or
        -not (Test-Sha256Token $TargetPopulation.groupMembershipRuleDigest) -or
        [string]$TargetPopulation.assignmentFilterRef -cnotmatch '^private://' -or
        -not (Test-Sha256Token $TargetPopulation.assignmentFilterDigest) -or
        [string]$TargetPopulation.assignmentFilterMode -cnotin @('INCLUDE', 'EXCLUDE', 'NONE') -or
        [string]$TargetPopulation.dynamicMembershipPolicy -cnotin @('STATIC_SNAPSHOT', 'DYNAMIC_WITH_CEILING_AND_PREWRITE_READBACK') -or
        -not (Test-Sha256Token $TargetPopulation.directoryReadbackDigest)) {
        Add-BlueprintError -Errors $Errors -Code 'TARGET_POPULATION_LIMIT_OR_COMPOSITION_INVALID' -Message "$Context target population has an invalid ceiling, count, exclusions, composition, membership rule, or dynamic policy."
    }
    $directory = Resolve-CanonicalRecord -RecordMap $RecordMap -Reference $TargetPopulation.directoryReadbackRef `
        -ExpectedTypes @('readback-record') -Context "$Context directory population readback" -Errors $Errors
    if ($null -eq $directory) { return $null }
    $directoryFields = @(
        'schemaVersion', 'recordStage', 'status', 'readbackKind', 'readerToolRef', 'readIdentityRef',
        'tenantBoundaryRef', 'targetEnvironmentRef', 'targetScopeRef', 'groupMembershipRuleRef', 'groupMembershipRuleDigest',
        'assignmentFilterRef', 'assignmentFilterDigest', 'assignmentFilterMode',
        'dynamicMembershipPolicy', 'populationCeiling', 'targetPopulationCount', 'exclusionRefs',
        'targetCompositionDigest', 'targetMembershipDigest', 'responseArtifactRef',
        'responseArtifactDigest', 'paginationComplete', 'collectedAt', 'freshnessBinding'
    )
    Test-RequiredProperties -Object $directory -Names @($directoryFields | Where-Object { $_ -cne 'exclusionRefs' }) -Context "$Context directory population readback" -Errors $Errors
    if ($null -eq $directory.PSObject.Properties['exclusionRefs']) {
        Add-BlueprintError -Errors $Errors -Code 'MISSING_REQUIRED_FIELD' -Message "$Context directory population readback requires exclusionRefs."
    }
    [DateTimeOffset]$directoryAt = [DateTimeOffset]::MinValue
    $directoryTimeValid = [OperationsBlueprint.StrictRfc3339]::TryParse([string]$directory.collectedAt, [ref]$directoryAt)
    $directoryFreshness = $directory.freshnessBinding
    [DateTimeOffset]$directoryFreshnessObservedAt = [DateTimeOffset]::MinValue
    [DateTimeOffset]$directoryFreshnessAdmittedAt = [DateTimeOffset]::MinValue
    [int64]$expectedDirectoryFreshnessDays = [int64][Math]::Ceiling([double]$MaximumAgeMinutes / 1440.0)
    $directoryFreshnessValid = $directoryFreshness -is [pscustomobject] -and
        [OperationsBlueprint.StrictRfc3339]::TryParse([string]$directoryFreshness.observedAt, [ref]$directoryFreshnessObservedAt) -and
        [OperationsBlueprint.StrictRfc3339]::TryParse([string]$directoryFreshness.admittedAt, [ref]$directoryFreshnessAdmittedAt)
    if ($directoryFreshness -is [pscustomobject]) {
        Test-RequiredProperties -Object $directoryFreshness -Names @(
            'observedAt','admittedAt','policyRef','maxAgeDays','dependencySnapshotRef',
            'dependencySnapshotDigest','dependencyStatus'
        ) -Context "$Context directory freshness binding" -Errors $Errors
    }
    if ([string]$directory.contentDigest -cne [string]$TargetPopulation.directoryReadbackDigest -or
        [string]$directory.schemaVersion -cne '1.0.0' -or
        [string]$directory.recordStage -cne 'DIRECTORY_MEMBERSHIP_READBACK' -or
        [string]$directory.status -cne 'VERIFIED' -or
        [string]$directory.readbackKind -cne 'DIRECTORY_TARGET_POPULATION' -or
        [string]$directory.readerToolRef -cne 'microsoft-graph-directory-readback' -or
        [string]$directory.readIdentityRef -cnotmatch '^private://' -or
        ((Test-ValuePresent $WriteIdentityRef) -and [string]$directory.readIdentityRef -ceq [string]$WriteIdentityRef) -or
        [string]$directory.tenantBoundaryRef -cne $ExpectedTenantBoundaryRef -or
        [string]$directory.targetEnvironmentRef -cne $ExpectedTargetEnvironmentRef -or
        [string]$directory.targetScopeRef -cne $ExpectedTargetScopeRef -or
        [string]$directory.groupMembershipRuleRef -cne [string]$TargetPopulation.groupMembershipRuleRef -or
        [string]$directory.groupMembershipRuleDigest -cne [string]$TargetPopulation.groupMembershipRuleDigest -or
        [string]$directory.assignmentFilterRef -cne [string]$TargetPopulation.assignmentFilterRef -or
        [string]$directory.assignmentFilterDigest -cne [string]$TargetPopulation.assignmentFilterDigest -or
        [string]$directory.assignmentFilterMode -cne [string]$TargetPopulation.assignmentFilterMode -or
        [string]$directory.dynamicMembershipPolicy -cne [string]$TargetPopulation.dynamicMembershipPolicy -or
        [string]$directory.populationCeiling -cne [string]$TargetPopulation.populationCeiling -or
        [string]$directory.targetPopulationCount -cne [string]$TargetPopulation.targetPopulationCount -or
        -not (Test-CanonicalValueEqual @($directory.exclusionRefs) @($TargetPopulation.exclusionRefs)) -or
        [string]$directory.targetCompositionDigest -cne [string]$TargetPopulation.targetCompositionDigest -or
        [string]$directory.targetMembershipDigest -cne $ExpectedTargetMembershipDigest -or
        [string]$directory.responseArtifactRef -cnotmatch '^private://' -or
        -not (Test-Sha256Token $directory.responseArtifactDigest) -or
        $directory.paginationComplete -ne $true -or
        [string]$directory.collectedAt -cne [string]$TargetPopulation.directoryReadbackAt -or
        -not $directoryTimeValid -or $directoryAt -gt $EvaluationTime -or
        ($EvaluationTime - $directoryAt).TotalMinutes -gt $MaximumAgeMinutes -or
        -not $directoryFreshnessValid -or
        $directoryFreshnessObservedAt -ne $directoryAt -or
        $directoryFreshnessAdmittedAt -lt $directoryAt -or $directoryFreshnessAdmittedAt -gt $EvaluationTime -or
        [string]$directoryFreshness.policyRef -cne $ExpectedReadbackPolicyRef -or
        ($directoryFreshness.maxAgeDays -isnot [int] -and $directoryFreshness.maxAgeDays -isnot [long]) -or
        [int64]$directoryFreshness.maxAgeDays -ne $expectedDirectoryFreshnessDays -or
        [string]$directoryFreshness.dependencySnapshotRef -cne [string]$TargetPopulation.groupMembershipRuleRef -or
        [string]$directoryFreshness.dependencySnapshotDigest -cne [string]$TargetPopulation.groupMembershipRuleDigest -or
        [string]$directoryFreshness.dependencyStatus -cne 'MATCH') {
        Add-BlueprintError -Errors $Errors -Code 'DIRECTORY_TARGET_POPULATION_READBACK_MISMATCH' -Message "$Context target population is not backed by a fresh, complete, independent directory readback of the exact rule, ceiling, composition, exclusions, scope, and membership snapshot."
    }
    return $directory
}

function Get-SecurityFreshnessPolicyApprovalSubjectDigest {
    param([Parameter(Mandatory = $true)]$Policy)

    $subject = [ordered]@{
        schemaVersion = [string]$Policy.schemaVersion
        recordStage = [string]$Policy.recordStage
        status = [string]$Policy.status
        authorityMode = [string]$Policy.authorityMode
        policyScope = [string]$Policy.policyScope
        policyKind = [string]$Policy.policyKind
        maximumAgeMinutes = $Policy.maximumAgeMinutes
        tenantBoundaryRef = [string]$Policy.tenantBoundaryRef
        targetEnvironmentRef = [string]$Policy.targetEnvironmentRef
        approvedByRole = [string]$Policy.approvedByRole
        approvedByPrincipalRef = [string]$Policy.approvedByPrincipalRef
    }
    if ([string]$Policy.authorityMode -ceq 'ROOT_BOOTSTRAP') {
        $subject['rootAuthorityRef'] = [string]$Policy.rootAuthorityRef
        $subject['rootAuthorityDigest'] = [string]$Policy.rootAuthorityDigest
        $subject['rootAuthorityReadbackRef'] = [string]$Policy.rootAuthorityReadbackRef
        $subject['rootAuthorityReadbackDigest'] = [string]$Policy.rootAuthorityReadbackDigest
        $subject['signatureAuthorityKeyRef'] = [string]$Policy.signatureAuthorityKeyRef
        $subject['signatureAuthorityPublicKeySpkiDigest'] = [string]$Policy.signatureAuthorityPublicKeySpkiDigest
    }
    elseif ([string]$Policy.authorityMode -ceq 'ROLE_BOUND') {
        $subject['roleBindingRef'] = [string]$Policy.roleBindingRef
        $subject['roleBindingDigest'] = [string]$Policy.roleBindingDigest
        $subject['roleBindingReadbackRef'] = [string]$Policy.roleBindingReadbackRef
        $subject['roleBindingReadbackDigest'] = [string]$Policy.roleBindingReadbackDigest
    }
    $subject['approvalArtifactRef'] = [string]$Policy.approvalArtifactRef
    $subject['approvedAt'] = [string]$Policy.approvedAt
    $subject['expiresAt'] = [string]$Policy.expiresAt
    return Get-CanonicalPayloadDigest -Payload ([pscustomobject]$subject)
}

function Test-IdentityGovernanceRootAuthoritySemantics {
    param(
        [AllowNull()]$RootAuthority,
        [Parameter(Mandatory = $true)][string]$ExpectedContentDigest,
        [Parameter(Mandatory = $true)][string]$ExpectedTenantBoundaryRef,
        [Parameter(Mandatory = $true)][string]$ExpectedTargetEnvironmentRef,
        [Parameter(Mandatory = $true)][string]$ExpectedIndependentReadbackRef,
        [Parameter(Mandatory = $true)][string]$ExpectedIndependentReadbackDigest,
        [Parameter(Mandatory = $true)][DateTimeOffset]$EvaluationTime,
        [Parameter(Mandatory = $true)][AllowEmptyCollection()][System.Collections.ArrayList]$Errors,
        [Parameter(Mandatory = $true)][string]$FailureCode,
        [Parameter(Mandatory = $true)][string]$FailureMessage
    )

    $initialErrorCount = $Errors.Count
    $authorityKeys = [System.Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal)
    $authoritySpkiDigests = [System.Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal)
    $authorityKeyPairs = [System.Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal)
    $authorityCustodians = [System.Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
    $authorityCustodianByPair = [System.Collections.Generic.Dictionary[string,string]]::new([StringComparer]::Ordinal)
    [DateTimeOffset]$rootIssuedAt = [DateTimeOffset]::MinValue
    [DateTimeOffset]$rootExpiresAt = [DateTimeOffset]::MinValue
    [DateTimeOffset]$rootRevocationCheckedAt = [DateTimeOffset]::MinValue
    [DateTimeOffset]$rootReadbackAt = [DateTimeOffset]::MinValue
    $rootAuthorityValid = $false

    if ($null -ne $RootAuthority -and
        [string]$RootAuthority.recordType -ceq 'identity-governance-root-authority-record') {
        $rootFields = @(
            'schemaVersion','recordStage','status','authorityVersion','tenantBoundaryRef',
            'targetEnvironmentRef','ceremonyOwnerRole','ceremonyOperatorIdentityRef','quorumThreshold',
            'authorityKeyBindings','authorityKeySetDigest','ceremonySubjectDigest','ceremonyEvidenceRef',
            'ceremonyEvidenceDigest','ceremonySignatureBindings','ceremonyAttestationRef',
            'ceremonyAttestationDigest','ceremonyAttestationStatus','independentReadbackRef',
            'independentReadbackDigest','independentReaderToolRef','independentReadIdentityRef',
            'independentReadbackStatus','independentReadbackAt','independentReadbackMaxAgeMinutes',
            'independentReadbackSubjectDigest','independentReadbackAttestationRef',
            'independentReadbackAttestationDigest','independentReadbackAttestationStatus',
            'issuedAt','expiresAt','revocationStatus','revocationEvidenceRef',
            'revocationEvidenceDigest','revocationCheckedAt'
        )
        Test-RequiredProperties -Object $RootAuthority -Names $rootFields -Context 'identity-governance root authority' -Errors $Errors

        $authorityKeysValid = @($RootAuthority.authorityKeyBindings).Count -ge 2
        $priorAuthorityKeySort = $null
        foreach ($keyBinding in @($RootAuthority.authorityKeyBindings)) {
            if ($null -eq $keyBinding) { $authorityKeysValid = $false; continue }
            $keyFields = @('authorityKeyRef','publicKeySpkiDigest','keyCustodianPrincipalId')
            Test-RequiredProperties -Object $keyBinding -Names $keyFields -Context 'root-authority key binding' -Errors $Errors
            Test-AllowedProperties -Object $keyBinding -Names $keyFields -Context 'root-authority key binding' -Errors $Errors
            $keyPair = ([string]$keyBinding.authorityKeyRef) + [char]0 + ([string]$keyBinding.publicKeySpkiDigest)
            $keySort = $keyPair + [char]0 + ([string]$keyBinding.keyCustodianPrincipalId)
            if ([string]$keyBinding.authorityKeyRef -cnotmatch '^private://' -or
                -not (Test-Sha256Token $keyBinding.publicKeySpkiDigest) -or
                [string]$keyBinding.keyCustodianPrincipalId -cnotmatch '^private://canonical-principals/sha256/[0-9a-f]{64}$' -or
                -not $authorityKeys.Add([string]$keyBinding.authorityKeyRef) -or
                -not $authoritySpkiDigests.Add([string]$keyBinding.publicKeySpkiDigest) -or
                -not $authorityCustodians.Add([string]$keyBinding.keyCustodianPrincipalId) -or
                -not $authorityKeyPairs.Add($keyPair) -or
                ($null -ne $priorAuthorityKeySort -and
                    [StringComparer]::Ordinal.Compare([string]$priorAuthorityKeySort, $keySort) -ge 0)) {
                $authorityKeysValid = $false
            }
            elseif (-not $authorityCustodianByPair.ContainsKey($keyPair)) {
                $authorityCustodianByPair.Add($keyPair, [string]$keyBinding.keyCustodianPrincipalId)
            }
            $priorAuthorityKeySort = $keySort
        }

        $quorumValid = ($RootAuthority.quorumThreshold -is [int] -or $RootAuthority.quorumThreshold -is [long]) -and
            [int64]$RootAuthority.quorumThreshold -ge 2 -and
            [int64]$RootAuthority.quorumThreshold -le $authoritySpkiDigests.Count -and
            [int64]$RootAuthority.quorumThreshold -le $authorityCustodians.Count
        $signatureKeys = [System.Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal)
        $signatureSpkiDigests = [System.Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal)
        $signaturePrincipals = [System.Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
        $signatureRefs = [System.Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal)
        $signaturesValid = @($RootAuthority.ceremonySignatureBindings).Count -ge 2
        foreach ($signatureBinding in @($RootAuthority.ceremonySignatureBindings)) {
            if ($null -eq $signatureBinding) { $signaturesValid = $false; continue }
            $signatureFields = @(
                'authorityKeyRef','publicKeySpkiDigest','signerPrincipalId','signedSubjectDigest',
                'signatureRef','signatureDigest','signatureStatus'
            )
            Test-RequiredProperties -Object $signatureBinding -Names $signatureFields -Context 'root-authority ceremony signature' -Errors $Errors
            Test-AllowedProperties -Object $signatureBinding -Names $signatureFields -Context 'root-authority ceremony signature' -Errors $Errors
            $signatureKeyPair = ([string]$signatureBinding.authorityKeyRef) + [char]0 + ([string]$signatureBinding.publicKeySpkiDigest)
            if (-not $authorityKeyPairs.Contains($signatureKeyPair) -or
                -not $signatureKeys.Add([string]$signatureBinding.authorityKeyRef) -or
                -not $signatureSpkiDigests.Add([string]$signatureBinding.publicKeySpkiDigest) -or
                -not $signaturePrincipals.Add([string]$signatureBinding.signerPrincipalId) -or
                -not $authorityCustodianByPair.ContainsKey($signatureKeyPair) -or
                [string]$signatureBinding.signerPrincipalId -cne [string]$authorityCustodianByPair[$signatureKeyPair] -or
                [string]$signatureBinding.signedSubjectDigest -cne [string]$RootAuthority.ceremonySubjectDigest -or
                [string]$signatureBinding.signatureRef -cnotmatch '^private://' -or
                -not $signatureRefs.Add([string]$signatureBinding.signatureRef) -or
                -not (Test-Sha256Token $signatureBinding.signatureDigest) -or
                [string]$signatureBinding.signatureStatus -cne 'VERIFIED') {
                $signaturesValid = $false
            }
        }
        if ($quorumValid -and
            ($signatureKeys.Count -lt [int64]$RootAuthority.quorumThreshold -or
             $signatureSpkiDigests.Count -lt [int64]$RootAuthority.quorumThreshold -or
             $signaturePrincipals.Count -lt [int64]$RootAuthority.quorumThreshold)) {
            $signaturesValid = $false
        }

        $rootTimesValid = [OperationsBlueprint.StrictRfc3339]::TryParse([string]$RootAuthority.issuedAt, [ref]$rootIssuedAt) -and
            [OperationsBlueprint.StrictRfc3339]::TryParse([string]$RootAuthority.expiresAt, [ref]$rootExpiresAt) -and
            [OperationsBlueprint.StrictRfc3339]::TryParse([string]$RootAuthority.revocationCheckedAt, [ref]$rootRevocationCheckedAt) -and
            [OperationsBlueprint.StrictRfc3339]::TryParse([string]$RootAuthority.independentReadbackAt, [ref]$rootReadbackAt)
        $expectedRootKeySetDigest = Get-IdentityGovernanceAuthorityKeySetDigest -AuthorityKeyBindings @($RootAuthority.authorityKeyBindings)
        $expectedRootSubjectDigest = Get-IdentityGovernanceRootCeremonySubjectDigest -Authority $RootAuthority
        $rootAuthorityValid = [string]$RootAuthority.contentDigest -ceq $ExpectedContentDigest -and
            [string]$RootAuthority.schemaVersion -ceq '1.0.0' -and
            [string]$RootAuthority.recordStage -ceq 'IDENTITY_GOVERNANCE_ROOT_AUTHORITY' -and
            [string]$RootAuthority.status -ceq 'ACTIVE' -and
            (Test-NonBlankString $RootAuthority.authorityVersion) -and
            [string]$RootAuthority.tenantBoundaryRef -ceq $ExpectedTenantBoundaryRef -and
            [string]$RootAuthority.targetEnvironmentRef -ceq $ExpectedTargetEnvironmentRef -and
            [string]$RootAuthority.ceremonyOwnerRole -ceq 'ROLE_IDENTITY_SECURITY_APPROVER' -and
            [string]$RootAuthority.ceremonyOperatorIdentityRef -cmatch '^private://canonical-principals/sha256/[0-9a-f]{64}$' -and
            $authorityKeysValid -and $quorumValid -and $signaturesValid -and
            [string]$RootAuthority.authorityKeySetDigest -ceq $expectedRootKeySetDigest -and
            [string]$RootAuthority.ceremonySubjectDigest -ceq $expectedRootSubjectDigest -and
            [string]$RootAuthority.ceremonyEvidenceRef -cmatch '^private://' -and
            (Test-Sha256Token $RootAuthority.ceremonyEvidenceDigest) -and
            [string]$RootAuthority.ceremonyAttestationRef -cmatch '^private://' -and
            (Test-Sha256Token $RootAuthority.ceremonyAttestationDigest) -and
            [string]$RootAuthority.ceremonyAttestationStatus -ceq 'VERIFIED' -and
            [string]$RootAuthority.independentReadbackRef -ceq $ExpectedIndependentReadbackRef -and
            [string]$RootAuthority.independentReadbackRef -cmatch '^private://' -and
            [string]$RootAuthority.independentReadbackDigest -ceq $ExpectedIndependentReadbackDigest -and
            (Test-Sha256Token $RootAuthority.independentReadbackDigest) -and
            [string]$RootAuthority.independentReaderToolRef -ceq 'microsoft-graph-directory-readback' -and
            [string]$RootAuthority.independentReadIdentityRef -cmatch '^private://canonical-principals/sha256/[0-9a-f]{64}$' -and
            [string]$RootAuthority.independentReadIdentityRef -cne [string]$RootAuthority.ceremonyOperatorIdentityRef -and
            -not $authorityCustodians.Contains([string]$RootAuthority.ceremonyOperatorIdentityRef) -and
            -not $authorityCustodians.Contains([string]$RootAuthority.independentReadIdentityRef) -and
            [string]$RootAuthority.independentReadbackStatus -ceq 'PASS' -and
            ($RootAuthority.independentReadbackMaxAgeMinutes -is [int] -or $RootAuthority.independentReadbackMaxAgeMinutes -is [long]) -and
            [int64]$RootAuthority.independentReadbackMaxAgeMinutes -gt 0 -and
            [string]$RootAuthority.independentReadbackSubjectDigest -ceq $expectedRootSubjectDigest -and
            [string]$RootAuthority.independentReadbackAttestationRef -cmatch '^private://' -and
            (Test-Sha256Token $RootAuthority.independentReadbackAttestationDigest) -and
            [string]$RootAuthority.independentReadbackAttestationStatus -ceq 'VERIFIED' -and
            [string]$RootAuthority.revocationStatus -ceq 'NOT_REVOKED' -and
            [string]$RootAuthority.revocationEvidenceRef -cmatch '^private://' -and
            (Test-Sha256Token $RootAuthority.revocationEvidenceDigest) -and
            $rootTimesValid -and $rootIssuedAt -le $rootRevocationCheckedAt -and
            $rootRevocationCheckedAt -le $rootReadbackAt -and $rootReadbackAt -le $EvaluationTime -and
            ($EvaluationTime - $rootReadbackAt).TotalMinutes -le [int64]$RootAuthority.independentReadbackMaxAgeMinutes -and
            $rootExpiresAt -gt $EvaluationTime -and $rootExpiresAt -gt $rootIssuedAt
    }

    if (-not $rootAuthorityValid -or $Errors.Count -ne $initialErrorCount) {
        Add-BlueprintError -Errors $Errors -Code $FailureCode -Message $FailureMessage
        $rootAuthorityValid = $false
    }
    return [pscustomobject]@{
        Valid = $rootAuthorityValid
        RootAuthority = $RootAuthority
        AuthorityKeyPairs = $authorityKeyPairs
        AuthorityCustodians = $authorityCustodians
        ReadbackAt = $rootReadbackAt
        IssuedAt = $rootIssuedAt
        ExpiresAt = $rootExpiresAt
        RevocationCheckedAt = $rootRevocationCheckedAt
    }
}

function Test-SecurityFreshnessPolicyBinding {
    param(
        [Parameter(Mandatory = $true)]$RecordMap,
        [Parameter(Mandatory = $true)]$Reference,
        [Parameter(Mandatory = $true)]$Digest,
        [Parameter(Mandatory = $true)][ValidateSet('AUTHORIZATION_TTL','AUTHORIZATION_REVOCATION','PACKAGE_REVOCATION','READBACK_FRESHNESS')][string]$ExpectedKind,
        [Parameter(Mandatory = $true)][int64]$ExpectedMaximumAgeMinutes,
        [Parameter(Mandatory = $true)][string]$ExpectedTenantBoundaryRef,
        [Parameter(Mandatory = $true)][string]$ExpectedTargetEnvironmentRef,
        [string]$ExpectedRoleBindingRef = '',
        [string]$ExpectedRoleBindingDigest = '',
        [string]$ExpectedRoleBindingReadbackRef = '',
        [string]$ExpectedRoleBindingReadbackDigest = '',
        [ValidateSet('ROOT_BOOTSTRAP','ROLE_BOUND')][string]$ExpectedAuthorityMode = 'ROLE_BOUND',
        [Parameter(Mandatory = $true)][DateTimeOffset]$EvaluationTime,
        [Parameter(Mandatory = $true)][AllowEmptyCollection()][System.Collections.ArrayList]$Errors
    )

    $policy = Resolve-CanonicalRecord -RecordMap $RecordMap -Reference $Reference `
        -ExpectedTypes @('security-freshness-policy-record') `
        -Context "$ExpectedKind security freshness policy" -Errors $Errors
    if ($null -eq $policy) { return $null }
    Test-RequiredProperties -Object $policy -Names @(
        'schemaVersion','recordStage','status','authorityMode','policyScope','policyKind','maximumAgeMinutes',
        'tenantBoundaryRef','targetEnvironmentRef','approvedByRole','approvedByPrincipalRef',
        'approvalSubjectDigest','signedSubjectDigest','approvalArtifactRef','approvalArtifactDigest',
        'signatureRef','signatureDigest','signatureStatus','approvedAt','expiresAt','revocationStatus',
        'revocationEvidenceRef','revocationEvidenceDigest','revocationCheckedAt'
    ) -Context "$ExpectedKind security freshness policy" -Errors $Errors
    [DateTimeOffset]$approvedAt = [DateTimeOffset]::MinValue
    [DateTimeOffset]$expiresAt = [DateTimeOffset]::MinValue
    [DateTimeOffset]$revocationCheckedAt = [DateTimeOffset]::MinValue
    $policyTimesValid = [OperationsBlueprint.StrictRfc3339]::TryParse([string]$policy.approvedAt, [ref]$approvedAt) -and
        [OperationsBlueprint.StrictRfc3339]::TryParse([string]$policy.expiresAt, [ref]$expiresAt) -and
        [OperationsBlueprint.StrictRfc3339]::TryParse([string]$policy.revocationCheckedAt, [ref]$revocationCheckedAt)
    $expectedSubjectDigest = Get-SecurityFreshnessPolicyApprovalSubjectDigest -Policy $policy
    $policyValid = [string]$policy.contentDigest -ceq [string]$Digest -and
        [string]$policy.schemaVersion -ceq '1.0.0' -and
        [string]$policy.recordStage -ceq 'SECURITY_FRESHNESS_POLICY' -and
        [string]$policy.status -ceq 'APPROVED' -and
        [string]$policy.authorityMode -ceq $ExpectedAuthorityMode -and
        [string]$policy.policyKind -ceq $ExpectedKind -and
        ($policy.maximumAgeMinutes -is [int] -or $policy.maximumAgeMinutes -is [long]) -and
        [int64]$policy.maximumAgeMinutes -eq $ExpectedMaximumAgeMinutes -and
        $ExpectedMaximumAgeMinutes -gt 0 -and
        [string]$policy.tenantBoundaryRef -ceq $ExpectedTenantBoundaryRef -and
        [string]$policy.targetEnvironmentRef -ceq $ExpectedTargetEnvironmentRef -and
        [string]$policy.approvedByPrincipalRef -cmatch '^private://canonical-principals/sha256/[0-9a-f]{64}$' -and
        [string]$policy.approvalSubjectDigest -ceq $expectedSubjectDigest -and
        [string]$policy.signedSubjectDigest -ceq $expectedSubjectDigest -and
        [string]$policy.approvalArtifactRef -cmatch '^private://' -and
        [string]$policy.approvalArtifactDigest -ceq $expectedSubjectDigest -and
        [string]$policy.signatureRef -cmatch '^private://' -and
        (Test-Sha256Token $policy.signatureDigest) -and
        [string]$policy.signatureStatus -ceq 'VERIFIED' -and
        [string]$policy.revocationStatus -ceq 'NOT_REVOKED' -and
        [string]$policy.revocationEvidenceRef -cmatch '^private://' -and
        (Test-Sha256Token $policy.revocationEvidenceDigest) -and
        $policyTimesValid -and $approvedAt -le $revocationCheckedAt -and
        $revocationCheckedAt -le $EvaluationTime -and
        ($EvaluationTime - $revocationCheckedAt).TotalMinutes -le $ExpectedMaximumAgeMinutes -and
        $approvedAt -le $EvaluationTime -and $expiresAt -gt $EvaluationTime -and $expiresAt -gt $approvedAt

    if ([string]$ExpectedAuthorityMode -ceq 'ROOT_BOOTSTRAP') {
        foreach ($field in @(
            'rootAuthorityRef','rootAuthorityDigest','rootAuthorityReadbackRef','rootAuthorityReadbackDigest',
            'signatureAuthorityKeyRef','signatureAuthorityPublicKeySpkiDigest'
        )) {
            if ($null -eq $policy.PSObject.Properties[$field]) { $policyValid = $false }
        }
        $root = Resolve-CanonicalRecord -RecordMap $RecordMap -Reference $policy.rootAuthorityRef `
            -ExpectedTypes @('identity-governance-root-authority-record') `
            -Context 'security-policy root-bootstrap authority' -Errors $Errors
        if ($null -ne $root -and
            [string]$root.recordType -cne 'identity-governance-root-authority-record') {
            $root = $null
        }
        $rootFailureMessage = 'Root-bootstrap freshness policy lacks an active quorum-signed root authority, exact SPKI key, fresh independent root observation, or valid chronology.'
        $rootValidation = Test-IdentityGovernanceRootAuthoritySemantics `
            -RootAuthority $root -ExpectedContentDigest ([string]$policy.rootAuthorityDigest) `
            -ExpectedTenantBoundaryRef $ExpectedTenantBoundaryRef `
            -ExpectedTargetEnvironmentRef $ExpectedTargetEnvironmentRef `
            -ExpectedIndependentReadbackRef ([string]$policy.rootAuthorityReadbackRef) `
            -ExpectedIndependentReadbackDigest ([string]$policy.rootAuthorityReadbackDigest) `
            -EvaluationTime $EvaluationTime -Errors $Errors `
            -FailureCode 'SECURITY_FRESHNESS_ROOT_AUTHORITY_INVALID' -FailureMessage $rootFailureMessage
        $rootAuthorityValid = $rootValidation.Valid -and
            [string]$policy.policyScope -ceq 'IDENTITY_ROLE_BINDING_READBACK' -and
            [string]$policy.policyKind -ceq 'READBACK_FRESHNESS' -and
            [string]$policy.approvedByRole -ceq 'ROLE_IDENTITY_SECURITY_APPROVER' -and
            [string]$policy.approvedByPrincipalRef -ceq [string]$root.ceremonyOperatorIdentityRef -and
            $rootValidation.AuthorityKeyPairs.Contains((([string]$policy.signatureAuthorityKeyRef) + [char]0 + ([string]$policy.signatureAuthorityPublicKeySpkiDigest))) -and
            $rootValidation.ReadbackAt -lt $approvedAt
        if (-not $rootAuthorityValid) {
            if ($rootValidation.Valid) {
                Add-BlueprintError -Errors $Errors -Code 'SECURITY_FRESHNESS_ROOT_AUTHORITY_INVALID' -Message $rootFailureMessage
            }
            $policyValid = $false
        }
        if ((Test-ValuePresent $policy.roleBindingRef) -or (Test-ValuePresent $policy.roleBindingDigest) -or
            (Test-ValuePresent $policy.roleBindingReadbackRef) -or (Test-ValuePresent $policy.roleBindingReadbackDigest)) {
            Add-BlueprintError -Errors $Errors -Code 'SECURITY_FRESHNESS_POLICY_AUTHORITY_CYCLE' -Message 'Root-bootstrap freshness policy may not depend on a role binding.'
            $policyValid = $false
        }
    }
    else {
        foreach ($field in @('roleBindingRef','roleBindingDigest','roleBindingReadbackRef','roleBindingReadbackDigest')) {
            if ($null -eq $policy.PSObject.Properties[$field]) { $policyValid = $false }
        }
        $roleReadback = Resolve-CanonicalRecord -RecordMap $RecordMap -Reference $policy.roleBindingReadbackRef `
            -ExpectedTypes @('role-binding-readback-record') -Context 'security-policy role-binding readback' -Errors $Errors
        [int64]$roleReadbackMaxAge = if ($null -ne $roleReadback -and
            ($roleReadback.maxAgeMinutes -is [int] -or $roleReadback.maxAgeMinutes -is [long]) -and
            [int64]$roleReadback.maxAgeMinutes -gt 0) { [int64]$roleReadback.maxAgeMinutes } else { 0 }
        $bootstrapPolicy = if ($null -ne $roleReadback -and
            [string]$roleReadback.readbackPolicyRef -cne [string]$policy.recordId) {
            Test-SecurityFreshnessPolicyBinding -RecordMap $RecordMap `
                -Reference $roleReadback.readbackPolicyRef -Digest $roleReadback.readbackPolicyDigest `
                -ExpectedKind 'READBACK_FRESHNESS' -ExpectedMaximumAgeMinutes $roleReadbackMaxAge `
                -ExpectedTenantBoundaryRef $ExpectedTenantBoundaryRef `
                -ExpectedTargetEnvironmentRef $ExpectedTargetEnvironmentRef `
                -ExpectedAuthorityMode 'ROOT_BOOTSTRAP' -EvaluationTime $EvaluationTime -Errors $Errors
        }
        else { $null }
        if ($null -eq $bootstrapPolicy -or [string]$bootstrapPolicy.recordId -ceq [string]$policy.recordId -or
            [string]$bootstrapPolicy.authorityMode -cne 'ROOT_BOOTSTRAP') {
            Add-BlueprintError -Errors $Errors -Code 'SECURITY_FRESHNESS_POLICY_AUTHORITY_CYCLE' -Message 'Role-bound policy readback must use one distinct acyclic ROOT_BOOTSTRAP freshness policy.'
            $policyValid = $false
        }
        $roleClosure = if ($null -ne $roleReadback -and $roleReadbackMaxAge -gt 0) {
            Test-RoleBindingClosure -RecordMap $RecordMap -RoleBindingRef ([string]$policy.roleBindingRef) `
                -RoleBindingDigest ([string]$policy.roleBindingDigest) `
                -RoleBindingReadbackRef ([string]$policy.roleBindingReadbackRef) `
                -RoleBindingReadbackDigest ([string]$policy.roleBindingReadbackDigest) `
                -ExpectedTenantBoundaryRef $ExpectedTenantBoundaryRef `
                -ExpectedTargetEnvironmentRef $ExpectedTargetEnvironmentRef `
                -ExpectedReadbackPolicyRef ([string]$roleReadback.readbackPolicyRef) `
                -ExpectedReadbackPolicyDigest ([string]$roleReadback.readbackPolicyDigest) `
                -ExpectedReadbackMaximumAgeMinutes $roleReadbackMaxAge `
                -EvaluationTime $EvaluationTime -Errors $Errors
        }
        else { $null }
        $approverBindingCount = if ($null -ne $roleClosure) {
            @($roleClosure.RoleBinding.bindings | Where-Object {
                [string]$_.roleId -ceq 'ROLE_SECURITY_APPROVER' -and
                [string]$_.canonicalPrincipalId -ceq [string]$policy.approvedByPrincipalRef
            }).Count
        }
        else { 0 }
        [DateTimeOffset]$roleObservedAt = [DateTimeOffset]::MinValue
        $roleChronologyValid = $null -ne $roleClosure -and
            [OperationsBlueprint.StrictRfc3339]::TryParse([string]$roleClosure.Readback.observedAt, [ref]$roleObservedAt) -and
            $roleObservedAt -lt $approvedAt
        if ([string]$policy.policyScope -cne 'OPERATIONAL_CONTROL_PLANE' -or
            [string]$policy.approvedByRole -cne 'ROLE_SECURITY_APPROVER' -or
            [string]$policy.roleBindingRef -cne $ExpectedRoleBindingRef -or
            [string]$policy.roleBindingDigest -cne $ExpectedRoleBindingDigest -or
            [string]$policy.roleBindingReadbackRef -cne $ExpectedRoleBindingReadbackRef -or
            [string]$policy.roleBindingReadbackDigest -cne $ExpectedRoleBindingReadbackDigest -or
            $approverBindingCount -ne 1 -or -not $roleChronologyValid -or
            (Test-ValuePresent $policy.rootAuthorityRef) -or (Test-ValuePresent $policy.rootAuthorityDigest) -or
            (Test-ValuePresent $policy.rootAuthorityReadbackRef) -or (Test-ValuePresent $policy.rootAuthorityReadbackDigest) -or
            (Test-ValuePresent $policy.signatureAuthorityKeyRef) -or
            (Test-ValuePresent $policy.signatureAuthorityPublicKeySpkiDigest)) {
            Add-BlueprintError -Errors $Errors -Code 'SECURITY_FRESHNESS_ROLE_AUTHORITY_INVALID' -Message 'Role-bound freshness policy must resolve the exact current role set, security approver, independent readback, and distinct root-bootstrap policy.'
            $policyValid = $false
        }
    }

    if (-not $policyValid) {
        Add-BlueprintError -Errors $Errors -Code 'SECURITY_FRESHNESS_POLICY_INVALID' -Message "$ExpectedKind must resolve one current, signed, independently approved canonical policy whose exact digest and maximum age match the consuming record."
    }
    return $policy
}

function Get-RoleBindingSetDigest {
    param([object[]]$Bindings)

    $entriesByKey = [System.Collections.Generic.Dictionary[string,System.Collections.Queue]]::new([StringComparer]::Ordinal)
    $sortKeys = New-Object System.Collections.Generic.List[string]
    foreach ($binding in @($Bindings)) {
        $canonicalBinding = [pscustomobject][ordered]@{
            roleId = [string]$binding.roleId
            principalAliasRef = [string]$binding.principalAliasRef
            canonicalPrincipalId = [string]$binding.canonicalPrincipalId
        }
        $key = ([string]$canonicalBinding.roleId) + [char]0 +
            ([string]$canonicalBinding.principalAliasRef) + [char]0 +
            ([string]$canonicalBinding.canonicalPrincipalId)
        if (-not $entriesByKey.ContainsKey($key)) {
            $entriesByKey.Add($key, [System.Collections.Queue]::new())
        }
        $entriesByKey[$key].Enqueue($canonicalBinding)
        $sortKeys.Add($key)
    }
    [string[]]$orderedKeys = @($sortKeys)
    if ($orderedKeys.Count -gt 1) { [Array]::Sort($orderedKeys, [StringComparer]::Ordinal) }
    $orderedBindings = New-Object System.Collections.ArrayList
    foreach ($key in $orderedKeys) { [void]$orderedBindings.Add($entriesByKey[$key].Dequeue()) }
    return Get-CanonicalPayloadDigest -Payload ([pscustomobject][ordered]@{ bindings = @($orderedBindings) })
}

function Get-FrozenRoleCatalog {
    # This catalog is intentionally duplicated from the immutable v1.0.0
    # control matrix.  An activation request cannot replace the semantic role
    # vocabulary by supplying a smaller, attacker-selected catalog.
    [string[]]$roles = @(
        'ROLE_ACCESS_POLICY_OWNER',
        'ROLE_AUTHORIZATION_LEDGER_OWNER',
        'ROLE_AUTHORIZATION_LEDGER_VERIFIER',
        'ROLE_BENCH_AUTOMATION_OWNER',
        'ROLE_CLOUD_RESOURCE_READBACK_OWNER',
        'ROLE_CONFIGURATION_MANAGER_OWNER',
        'ROLE_CONTRACT_RELEASE_OWNER',
        'ROLE_CONTRACT_VALIDATION_OWNER',
        'ROLE_DATA_GOVERNANCE_OWNER',
        'ROLE_DATA_PLATFORM_OWNER',
        'ROLE_DECISION_ANALYTICS_OWNER',
        'ROLE_DECISION_PRODUCT_OWNER',
        'ROLE_DEFENDER_SECURITY_SETTINGS_OWNER',
        'ROLE_DEVICE_EVIDENCE_OWNER',
        'ROLE_DIRECTORY_READBACK_OWNER',
        'ROLE_EMERGENCY_ENDPOINT_AUTOMATION_OWNER',
        'ROLE_ENDPOINT_ARCHITECTURE_APPROVER',
        'ROLE_ENDPOINT_ENGINEERING_OWNER',
        'ROLE_ENDPOINT_SECURITY_APPLICATION_OWNER',
        'ROLE_ENDPOINT_SECURITY_TOOLING_OWNER',
        'ROLE_ENDPOINT_TELEMETRY_OWNER',
        'ROLE_ENTERPRISE_RISK_APPROVER',
        'ROLE_EVALUATION_OWNER',
        'ROLE_EVIDENCE_CUSTODY_OWNER',
        'ROLE_GOVERNANCE_OWNER',
        'ROLE_GRAPH_AUTOMATION_OWNER',
        'ROLE_GROUP_POLICY_OWNER',
        'ROLE_HARDWARE_ENGINEERING_OWNER',
        'ROLE_HARDWARE_LIFECYCLE_OWNER',
        'ROLE_IAC_APPLY_OPERATOR',
        'ROLE_IAC_CONFIGURATION_OWNER',
        'ROLE_IAC_PLATFORM_APPROVER',
        'ROLE_IAC_PLATFORM_OWNER',
        'ROLE_IAC_SECURITY_OWNER',
        'ROLE_IAC_STATE_OWNER',
        'ROLE_IDENTITY_ACCESS_OWNER',
        'ROLE_IDENTITY_SECURITY_APPROVER',
        'ROLE_INDEPENDENT_VERIFIER',
        'ROLE_INTUNE_CHANGE_APPROVER',
        'ROLE_MONITORING_OWNER',
        'ROLE_OEM_ENDPOINT_MANAGEMENT_OWNER',
        'ROLE_PILOT_PRIVACY_OWNER',
        'ROLE_PILOT_RESEARCH_OWNER',
        'ROLE_PLATFORM_AUTOMATION_OWNER',
        'ROLE_PLATFORM_SOURCE_CONTROL_OWNER',
        'ROLE_PRIVACY_APPROVER',
        'ROLE_PRIVACY_SECURITY_APPROVER',
        'ROLE_PROCUREMENT_APPROVER',
        'ROLE_PROCUREMENT_DATA_OWNER',
        'ROLE_PROTECTED_ENVIRONMENT_APPROVER',
        'ROLE_QUALIFICATION_AUTHORITY',
        'ROLE_QUALIFICATION_GOVERNANCE_APPROVER',
        'ROLE_QUALIFICATION_OPERATIONS_APPROVER',
        'ROLE_QUALIFICATION_TEST_OWNER',
        'ROLE_REPOSITORY_OWNER',
        'ROLE_REQUALIFICATION_OWNER',
        'ROLE_REVIEW_AUTOMATION_OWNER',
        'ROLE_SECRETS_MANAGEMENT_OWNER',
        'ROLE_SECURITY_APPROVER',
        'ROLE_SERVICE_MANAGEMENT_DATA_OWNER',
        'ROLE_SUPPLY_CHAIN_OWNER',
        'ROLE_VALIDATION_TOOLCHAIN_OWNER',
        'ROLE_WINDOWS_COLLECTOR_RUNTIME_OWNER',
        'ROLE_WINDOWS_DEPLOYMENT_OWNER',
        'ROLE_WINDOWS_ENDPOINT_EVIDENCE_OWNER',
        'ROLE_WINDOWS_PROVISIONING_OWNER',
        'ROLE_WINDOWS_SERVICING_OWNER'
    )
    return $roles
}

function Get-ApprovedRoleCatalogDigest {
    param([object[]]$ApprovedRoleCatalog)

    [string[]]$normalized = @($ApprovedRoleCatalog | ForEach-Object { [string]$_ })
    if ($normalized.Count -gt 1) { [Array]::Sort($normalized, [StringComparer]::Ordinal) }
    return Get-CanonicalPayloadDigest -Payload ([pscustomobject][ordered]@{
        approvedRoleCatalog = @($normalized)
    })
}

function Get-IdentityGovernanceAuthorityKeySetDigest {
    param([object[]]$AuthorityKeyBindings)

    $byKey = [System.Collections.Generic.Dictionary[string,System.Collections.Queue]]::new([StringComparer]::Ordinal)
    $sortKeys = New-Object System.Collections.Generic.List[string]
    foreach ($binding in @($AuthorityKeyBindings)) {
        $normalizedBinding = [pscustomobject][ordered]@{
            authorityKeyRef = [string]$binding.authorityKeyRef
            publicKeySpkiDigest = [string]$binding.publicKeySpkiDigest
            keyCustodianPrincipalId = [string]$binding.keyCustodianPrincipalId
        }
        $key = ([string]$normalizedBinding.authorityKeyRef) + [char]0 +
            ([string]$normalizedBinding.publicKeySpkiDigest) + [char]0 +
            ([string]$normalizedBinding.keyCustodianPrincipalId)
        if (-not $byKey.ContainsKey($key)) { $byKey.Add($key, [System.Collections.Queue]::new()) }
        $byKey[$key].Enqueue($normalizedBinding)
        $sortKeys.Add($key)
    }
    [string[]]$orderedKeys = @($sortKeys)
    if ($orderedKeys.Count -gt 1) { [Array]::Sort($orderedKeys, [StringComparer]::Ordinal) }
    $normalized = New-Object System.Collections.ArrayList
    foreach ($key in $orderedKeys) { [void]$normalized.Add($byKey[$key].Dequeue()) }
    return Get-CanonicalPayloadDigest -Payload ([pscustomobject][ordered]@{
        authorityKeyBindings = @($normalized)
    })
}

function Get-IdentityGovernanceRootCeremonySubjectDigest {
    param([Parameter(Mandatory = $true)]$Authority)

    # The offline quorum signs this pre-readback subject.  Signatures,
    # attestations, and the independent observation are evidence about the
    # subject and therefore cannot be inputs to their own signed digest.
    $subject = [pscustomobject][ordered]@{
        schemaVersion = [string]$Authority.schemaVersion
        recordStage = [string]$Authority.recordStage
        status = [string]$Authority.status
        authorityVersion = [string]$Authority.authorityVersion
        tenantBoundaryRef = [string]$Authority.tenantBoundaryRef
        targetEnvironmentRef = [string]$Authority.targetEnvironmentRef
        ceremonyOwnerRole = [string]$Authority.ceremonyOwnerRole
        ceremonyOperatorIdentityRef = [string]$Authority.ceremonyOperatorIdentityRef
        quorumThreshold = $Authority.quorumThreshold
        authorityKeyBindings = @($Authority.authorityKeyBindings)
        authorityKeySetDigest = [string]$Authority.authorityKeySetDigest
        ceremonyEvidenceRef = [string]$Authority.ceremonyEvidenceRef
        ceremonyEvidenceDigest = [string]$Authority.ceremonyEvidenceDigest
        independentReaderToolRef = [string]$Authority.independentReaderToolRef
        independentReadbackMaxAgeMinutes = $Authority.independentReadbackMaxAgeMinutes
        issuedAt = [string]$Authority.issuedAt
        expiresAt = [string]$Authority.expiresAt
        revocationStatus = [string]$Authority.revocationStatus
        revocationEvidenceRef = [string]$Authority.revocationEvidenceRef
        revocationEvidenceDigest = [string]$Authority.revocationEvidenceDigest
        revocationCheckedAt = [string]$Authority.revocationCheckedAt
    }
    return Get-CanonicalPayloadDigest -Payload $subject
}

function Get-RoleBindingApprovalSubjectDigest {
    param([Parameter(Mandatory = $true)]$Approval)

    # Signature and attestation material are intentionally outside the signed
    # subject to avoid a circular digest.  The artifact digest is inside the
    # subject and is required by the validator to equal this projection digest.
    $subject = [pscustomobject][ordered]@{
        schemaVersion = [string]$Approval.schemaVersion
        recordStage = [string]$Approval.recordStage
        status = [string]$Approval.status
        bindingVersion = [string]$Approval.bindingVersion
        bindingSetDigest = [string]$Approval.bindingSetDigest
        tenantBoundaryRef = [string]$Approval.tenantBoundaryRef
        targetEnvironmentRef = [string]$Approval.targetEnvironmentRef
        approvedRoleCatalog = @($Approval.approvedRoleCatalog)
        approvedRoleCatalogDigest = [string]$Approval.approvedRoleCatalogDigest
        approverRole = [string]$Approval.approverRole
        approverPrincipalRef = [string]$Approval.approverPrincipalRef
        approvalAuthorityRef = [string]$Approval.approvalAuthorityRef
        approvalAuthorityDigest = [string]$Approval.approvalAuthorityDigest
        approvalAuthorityReadbackRef = [string]$Approval.approvalAuthorityReadbackRef
        approvalAuthorityReadbackDigest = [string]$Approval.approvalAuthorityReadbackDigest
        approvalArtifactRef = [string]$Approval.approvalArtifactRef
        approvedAt = [string]$Approval.approvedAt
        expiresAt = [string]$Approval.expiresAt
        revocationStatus = [string]$Approval.revocationStatus
        revocationEvidenceRef = [string]$Approval.revocationEvidenceRef
        revocationEvidenceDigest = [string]$Approval.revocationEvidenceDigest
        revocationCheckedAt = [string]$Approval.revocationCheckedAt
    }
    return Get-CanonicalPayloadDigest -Payload $subject
}

function Get-WriteAuthorizationSubjectDigest {
    param([Parameter(Mandatory = $true)]$Authorization)

    $authorizationPayload = if ($null -ne $Authorization.PSObject.Properties['payload'] -and
        $Authorization.payload -is [pscustomobject]) { $Authorization.payload } else { $Authorization }
    $subject = [ordered]@{}
    $excluded = @(
        'authorizationSubjectDigest', 'authorizationArtifactDigest',
        'issuerSignatureRef', 'issuerSignatureDigest', 'issuerSignatureStatus'
    )
    foreach ($property in @($authorizationPayload.PSObject.Properties)) {
        if ($excluded -cnotcontains [string]$property.Name) {
            $subject[[string]$property.Name] = $property.Value
        }
    }
    return Get-CanonicalPayloadDigest -Payload ([pscustomobject]$subject)
}

function Test-RoleBindingClosure {
    param(
        [Parameter(Mandatory = $true)]$RecordMap,
        [Parameter(Mandatory = $true)][string]$RoleBindingRef,
        [Parameter(Mandatory = $true)][string]$RoleBindingDigest,
        [Parameter(Mandatory = $true)][string]$RoleBindingReadbackRef,
        [Parameter(Mandatory = $true)][string]$RoleBindingReadbackDigest,
        [Parameter(Mandatory = $true)][string]$ExpectedTenantBoundaryRef,
        [Parameter(Mandatory = $true)][string]$ExpectedTargetEnvironmentRef,
        [Parameter(Mandatory = $true)][string]$ExpectedReadbackPolicyRef,
        [Parameter(Mandatory = $true)][string]$ExpectedReadbackPolicyDigest,
        [Parameter(Mandatory = $true)][int64]$ExpectedReadbackMaximumAgeMinutes,
        [Parameter(Mandatory = $true)][DateTimeOffset]$EvaluationTime,
        [Parameter(Mandatory = $true)][AllowEmptyCollection()][System.Collections.ArrayList]$Errors
    )

    $roleBinding = Resolve-CanonicalRecord -RecordMap $RecordMap -Reference $RoleBindingRef `
        -ExpectedTypes @('role-binding-record') -Context 'role-binding record' -Errors $Errors
    $roleReadback = Resolve-CanonicalRecord -RecordMap $RecordMap -Reference $RoleBindingReadbackRef `
        -ExpectedTypes @('role-binding-readback-record') -Context 'role-binding readback' -Errors $Errors
    if ($null -eq $roleBinding -or $null -eq $roleReadback) { return $null }

    $bindingFields = @(
        'schemaVersion','recordStage','status','bindingVersion','tenantBoundaryRef','targetEnvironmentRef',
        'sourceToolRef','sourceIdentityRef','bindings','bindingSetDigest','approvalRef','approvalDigest',
        'approvedAt','revocationStatus','revocationEvidenceRef','revocationEvidenceDigest',
        'revocationCheckedAt','expiresAt'
    )
    Test-RequiredProperties -Object $roleBinding -Names $bindingFields -Context 'role-binding record' -Errors $Errors
    [DateTimeOffset]$bindingApprovedAt = [DateTimeOffset]::MinValue
    [DateTimeOffset]$bindingRevocationCheckedAt = [DateTimeOffset]::MinValue
    [DateTimeOffset]$bindingExpiresAt = [DateTimeOffset]::MinValue
    $bindings = @($roleBinding.bindings)
    $aliasMap = [System.Collections.Generic.Dictionary[string,string]]::new([StringComparer]::Ordinal)
    $roleMap = [System.Collections.Generic.Dictionary[string,string]]::new([StringComparer]::Ordinal)
    $bindingSetValid = $bindings.Count -gt 0
    $roleAliasPairs = [System.Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal)
    [string[]]$frozenRoleCatalog = @(Get-FrozenRoleCatalog)
    foreach ($binding in $bindings) {
        Test-RequiredProperties -Object $binding -Names @('roleId','principalAliasRef','canonicalPrincipalId') -Context 'role-binding entry' -Errors $Errors
        Test-AllowedProperties -Object $binding -Names @('roleId','principalAliasRef','canonicalPrincipalId') -Context 'role-binding entry' -Errors $Errors
        if ($frozenRoleCatalog -cnotcontains [string]$binding.roleId -or
            [string]$binding.principalAliasRef -cnotmatch '^private://' -or
            [string]$binding.canonicalPrincipalId -cnotmatch '^private://canonical-principals/sha256/[0-9a-f]{64}$') {
            $bindingSetValid = $false
            continue
        }
        $pairKey = ([string]$binding.roleId) + [char]0 + ([string]$binding.principalAliasRef)
        if (-not $roleAliasPairs.Add($pairKey) -or $aliasMap.ContainsKey([string]$binding.principalAliasRef)) {
            $bindingSetValid = $false
            continue
        }
        $aliasMap.Add([string]$binding.principalAliasRef, [string]$binding.canonicalPrincipalId)
        $roleMap.Add([string]$binding.principalAliasRef, [string]$binding.roleId)
    }
    $expectedBindingSetDigest = Get-RoleBindingSetDigest -Bindings $bindings
    $bindingApproval = Resolve-CanonicalRecord -RecordMap $RecordMap -Reference $roleBinding.approvalRef `
        -ExpectedTypes @('role-binding-approval-record') -Context 'role-binding approval' -Errors $Errors
    $bindingTimesValid = [OperationsBlueprint.StrictRfc3339]::TryParse([string]$roleBinding.approvedAt, [ref]$bindingApprovedAt) -and
        [OperationsBlueprint.StrictRfc3339]::TryParse([string]$roleBinding.revocationCheckedAt, [ref]$bindingRevocationCheckedAt) -and
        [OperationsBlueprint.StrictRfc3339]::TryParse([string]$roleBinding.expiresAt, [ref]$bindingExpiresAt)
    $approvalFields = @(
        'schemaVersion','recordStage','status','bindingVersion','bindingSetDigest','tenantBoundaryRef',
        'targetEnvironmentRef','approvedRoleCatalog','approvedRoleCatalogDigest','approverRole',
        'approverPrincipalRef','approvalAuthorityRef','approvalAuthorityDigest',
        'approvalAuthorityReadbackRef','approvalAuthorityReadbackDigest','approvalSubjectDigest',
        'approvalArtifactRef','approvalArtifactDigest','approvalArtifactAttestationRef',
        'approvalArtifactAttestationDigest','approvalArtifactAttestationStatus','signatureAuthorityKeyRef',
        'signatureAuthorityPublicKeySpkiDigest','signedSubjectDigest','signatureRef',
        'signatureDigest','signatureStatus','approvedAt','expiresAt','revocationStatus','revocationEvidenceRef',
        'revocationEvidenceDigest','revocationCheckedAt'
    )
    if ($null -ne $bindingApproval) {
        Test-RequiredProperties -Object $bindingApproval -Names $approvalFields -Context 'role-binding approval' -Errors $Errors
    }
    $rootAuthority = if ($null -ne $bindingApproval) {
        Resolve-CanonicalRecord -RecordMap $RecordMap -Reference $bindingApproval.approvalAuthorityRef `
            -ExpectedTypes @('identity-governance-root-authority-record') `
            -Context 'identity-governance root authority' -Errors $Errors
    }
    else { $null }
    # Resolve-CanonicalRecord deliberately reports a type mismatch while
    # returning the retained record for diagnostics.  Do not dereference that
    # wrong-type payload as a root authority: a self-bootstrap or type swap must
    # remain a structured fail-closed result, never a runtime exception.
    if ($null -ne $rootAuthority -and
        [string]$rootAuthority.recordType -cne 'identity-governance-root-authority-record') {
        $rootAuthority = $null
    }

    [DateTimeOffset]$approvalApprovedAt = [DateTimeOffset]::MinValue
    [DateTimeOffset]$approvalExpiresAt = [DateTimeOffset]::MinValue
    [DateTimeOffset]$approvalRevocationCheckedAt = [DateTimeOffset]::MinValue
    $approvalTimesValid = $null -ne $bindingApproval -and
        [OperationsBlueprint.StrictRfc3339]::TryParse([string]$bindingApproval.approvedAt, [ref]$approvalApprovedAt) -and
        [OperationsBlueprint.StrictRfc3339]::TryParse([string]$bindingApproval.expiresAt, [ref]$approvalExpiresAt) -and
        [OperationsBlueprint.StrictRfc3339]::TryParse([string]$bindingApproval.revocationCheckedAt, [ref]$approvalRevocationCheckedAt)
    $expectedCatalogDigest = if ($null -ne $bindingApproval) {
        Get-ApprovedRoleCatalogDigest -ApprovedRoleCatalog @($bindingApproval.approvedRoleCatalog)
    }
    else { '' }
    $expectedApprovalSubjectDigest = if ($null -ne $bindingApproval) {
        Get-RoleBindingApprovalSubjectDigest -Approval $bindingApproval
    }
    else { '' }
    $approvalSelfBootstrap = $null -ne $bindingApproval -and
        [string]$bindingApproval.approvalAuthorityRef -cin @(
            [string]$bindingApproval.recordId, [string]$roleBinding.recordId, [string]$roleReadback.recordId
        )
    if ($approvalSelfBootstrap) {
        Add-BlueprintError -Errors $Errors -Code 'ROLE_BINDING_AUTHORITY_SELF_BOOTSTRAP' -Message 'A role-binding approval cannot serve as its own identity-governance root authority.'
    }

    $rootValidation = Test-IdentityGovernanceRootAuthoritySemantics `
        -RootAuthority $rootAuthority -ExpectedContentDigest ([string]$bindingApproval.approvalAuthorityDigest) `
        -ExpectedTenantBoundaryRef $ExpectedTenantBoundaryRef `
        -ExpectedTargetEnvironmentRef $ExpectedTargetEnvironmentRef `
        -ExpectedIndependentReadbackRef ([string]$bindingApproval.approvalAuthorityReadbackRef) `
        -ExpectedIndependentReadbackDigest ([string]$bindingApproval.approvalAuthorityReadbackDigest) `
        -EvaluationTime $EvaluationTime -Errors $Errors `
        -FailureCode 'IDENTITY_GOVERNANCE_ROOT_AUTHORITY_INVALID' `
        -FailureMessage 'Role approval requires one current nonrecursive root authority with a recomputed key set and ceremony subject, offline quorum, verified attestation, fresh independent readback, revocation evidence, and separated operator and reader.'
    $rootAuthorityValid = $rootValidation.Valid
    $authorityKeyPairs = $rootValidation.AuthorityKeyPairs
    $authorityCustodians = $rootValidation.AuthorityCustodians
    $rootReadbackAt = $rootValidation.ReadbackAt

    $bindingApprovalValid = $null -ne $bindingApproval -and $null -ne $rootAuthority -and
        [string]$bindingApproval.schemaVersion -ceq '1.0.0' -and
        [string]$bindingApproval.recordStage -ceq 'ROLE_BINDING_APPROVAL' -and
        [string]$bindingApproval.status -ceq 'APPROVED' -and
        [string]$bindingApproval.bindingVersion -ceq [string]$roleBinding.bindingVersion -and
        [string]$bindingApproval.bindingSetDigest -ceq [string]$expectedBindingSetDigest -and
        [string]$bindingApproval.tenantBoundaryRef -ceq $ExpectedTenantBoundaryRef -and
        [string]$bindingApproval.targetEnvironmentRef -ceq $ExpectedTargetEnvironmentRef -and
        (Test-CanonicalValueEqual @($bindingApproval.approvedRoleCatalog) @($frozenRoleCatalog)) -and
        [string]$bindingApproval.approvedRoleCatalogDigest -ceq $expectedCatalogDigest -and
        [string]$bindingApproval.approverRole -ceq 'ROLE_IDENTITY_SECURITY_APPROVER' -and
        [string]$bindingApproval.approverPrincipalRef -cmatch '^private://canonical-principals/sha256/[0-9a-f]{64}$' -and
        [string]$bindingApproval.approvalAuthorityRef -ceq [string]$rootAuthority.recordId -and
        [string]$bindingApproval.approvalAuthorityReadbackRef -ceq [string]$rootAuthority.independentReadbackRef -and
        [string]$bindingApproval.approvalAuthorityReadbackDigest -ceq [string]$rootAuthority.independentReadbackDigest -and
        [string]$bindingApproval.approvalSubjectDigest -ceq $expectedApprovalSubjectDigest -and
        [string]$bindingApproval.approvalArtifactRef -cmatch '^private://' -and
        [string]$bindingApproval.approvalArtifactDigest -ceq $expectedApprovalSubjectDigest -and
        [string]$bindingApproval.approvalArtifactAttestationRef -cmatch '^private://' -and
        (Test-Sha256Token $bindingApproval.approvalArtifactAttestationDigest) -and
        [string]$bindingApproval.approvalArtifactAttestationStatus -ceq 'VERIFIED' -and
        [string]$bindingApproval.signatureAuthorityKeyRef -cmatch '^private://' -and
        (Test-Sha256Token $bindingApproval.signatureAuthorityPublicKeySpkiDigest) -and
        $authorityKeyPairs.Contains((([string]$bindingApproval.signatureAuthorityKeyRef) + [char]0 + ([string]$bindingApproval.signatureAuthorityPublicKeySpkiDigest))) -and
        [string]$bindingApproval.signedSubjectDigest -ceq $expectedApprovalSubjectDigest -and
        [string]$bindingApproval.signatureRef -cmatch '^private://' -and
        (Test-Sha256Token $bindingApproval.signatureDigest) -and
        [string]$bindingApproval.signatureStatus -ceq 'VERIFIED' -and
        [string]$bindingApproval.revocationStatus -ceq 'NOT_REVOKED' -and
        [string]$bindingApproval.revocationEvidenceRef -cmatch '^private://' -and
        (Test-Sha256Token $bindingApproval.revocationEvidenceDigest) -and
        $approvalTimesValid -and $approvalApprovedAt -le $approvalRevocationCheckedAt -and
        $approvalRevocationCheckedAt -le $EvaluationTime -and $approvalExpiresAt -gt $EvaluationTime -and
        $approvalExpiresAt -gt $approvalApprovedAt -and $rootAuthorityValid -and
        $rootReadbackAt -lt $approvalApprovedAt -and -not $approvalSelfBootstrap
    $authorityPrincipalSet = [System.Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
    foreach ($principalRef in @(
        [string]$bindingApproval.approverPrincipalRef,
        [string]$rootAuthority.ceremonyOperatorIdentityRef,
        [string]$rootAuthority.independentReadIdentityRef
    )) {
        if ($principalRef -cnotmatch '^private://canonical-principals/sha256/[0-9a-f]{64}$' -or
            -not $authorityPrincipalSet.Add($principalRef)) { $bindingApprovalValid = $false }
    }
    foreach ($custodianPrincipalId in @($authorityCustodians)) {
        if ([string]$custodianPrincipalId -cnotmatch '^private://canonical-principals/sha256/[0-9a-f]{64}$' -or
            -not $authorityPrincipalSet.Add([string]$custodianPrincipalId)) { $bindingApprovalValid = $false }
    }
    foreach ($roleAliasRequirement in @(
        [pscustomobject]@{ Alias = [string]$roleBinding.sourceIdentityRef; RoleId = 'ROLE_IAC_PLATFORM_OWNER' },
        [pscustomobject]@{ Alias = [string]$roleReadback.readIdentityRef; RoleId = 'ROLE_DIRECTORY_READBACK_OWNER' }
    )) {
        if (-not $aliasMap.ContainsKey([string]$roleAliasRequirement.Alias) -or
            -not $roleMap.ContainsKey([string]$roleAliasRequirement.Alias) -or
            [string]$roleMap[[string]$roleAliasRequirement.Alias] -cne [string]$roleAliasRequirement.RoleId -or
            -not $authorityPrincipalSet.Add([string]$aliasMap[[string]$roleAliasRequirement.Alias])) {
            $bindingApprovalValid = $false
        }
    }
    if (-not $bindingApprovalValid) {
        Add-BlueprintError -Errors $Errors -Code 'ROLE_BINDING_APPROVAL_INVALID' -Message 'Role binding requires a current specialized approval of the exact frozen role catalog, binding set, tenant, environment, signed subject, and a distinct prior root-ceremony authority.'
    }
    if ([string]$roleBinding.contentDigest -cne $RoleBindingDigest -or
        [string]$roleBinding.schemaVersion -cne '1.0.0' -or
        [string]$roleBinding.recordStage -cne 'ROLE_BINDING' -or
        [string]$roleBinding.status -cne 'VERIFIED' -or
        -not (Test-NonBlankString $roleBinding.bindingVersion) -or
        [string]$roleBinding.tenantBoundaryRef -cne $ExpectedTenantBoundaryRef -or
        [string]$roleBinding.targetEnvironmentRef -cne $ExpectedTargetEnvironmentRef -or
        [string]$roleBinding.sourceToolRef -cne 'terraform' -or
        [string]$roleBinding.sourceIdentityRef -cnotmatch '^private://' -or
        -not $bindingSetValid -or
        [string]$roleBinding.bindingSetDigest -cne $expectedBindingSetDigest -or
        $null -eq $bindingApproval -or
        ($null -ne $bindingApproval -and [string]$bindingApproval.contentDigest -cne [string]$roleBinding.approvalDigest) -or
        ($null -ne $bindingApproval -and [string]$bindingApproval.status -cne 'APPROVED') -or
        -not $bindingApprovalValid -or
        ($approvalTimesValid -and $bindingApprovedAt -lt $approvalApprovedAt) -or
        [string]$roleBinding.revocationStatus -cne 'NOT_REVOKED' -or
        [string]$roleBinding.revocationEvidenceRef -cnotmatch '^private://' -or
        -not (Test-Sha256Token $roleBinding.revocationEvidenceDigest) -or
        -not $bindingTimesValid -or
        $bindingApprovedAt -gt $bindingRevocationCheckedAt -or $bindingRevocationCheckedAt -gt $EvaluationTime -or
        $bindingExpiresAt -le $EvaluationTime -or $bindingExpiresAt -le $bindingApprovedAt) {
        Add-BlueprintError -Errors $Errors -Code 'ROLE_BINDING_RECORD_INVALID' -Message 'Role binding must be current, approved, non-revoked, tenant/environment-bound, and contain one canonical directory identifier for every unique role alias with a recomputed set digest.'
    }

    $readbackFields = @(
        'schemaVersion','recordStage','status','roleBindingRef','roleBindingDigest','bindingSetDigest',
        'readerToolRef','readIdentityRef','tenantBoundaryRef','targetEnvironmentRef','observedBindingSetDigest',
        'responseArtifactRef','responseArtifactDigest','observedAt','maxAgeMinutes','readbackPolicyRef',
        'readbackPolicyDigest','revocationStatus','revocationEvidenceRef','revocationEvidenceDigest',
        'revocationCheckedAt','consistencyStatus'
    )
    Test-RequiredProperties -Object $roleReadback -Names $readbackFields -Context 'role-binding readback' -Errors $Errors
    [DateTimeOffset]$roleObservedAt = [DateTimeOffset]::MinValue
    [DateTimeOffset]$roleReadbackRevocationCheckedAt = [DateTimeOffset]::MinValue
    $readbackAgeValid = ($roleReadback.maxAgeMinutes -is [int] -or $roleReadback.maxAgeMinutes -is [long]) -and
        [int64]$roleReadback.maxAgeMinutes -eq $ExpectedReadbackMaximumAgeMinutes -and $ExpectedReadbackMaximumAgeMinutes -gt 0
    $readbackTimesValid = [OperationsBlueprint.StrictRfc3339]::TryParse([string]$roleReadback.observedAt, [ref]$roleObservedAt) -and
        [OperationsBlueprint.StrictRfc3339]::TryParse([string]$roleReadback.revocationCheckedAt, [ref]$roleReadbackRevocationCheckedAt)
    if ([string]$roleReadback.contentDigest -cne $RoleBindingReadbackDigest -or
        [string]$roleReadback.schemaVersion -cne '1.0.0' -or
        [string]$roleReadback.recordStage -cne 'ROLE_BINDING_READBACK' -or
        [string]$roleReadback.status -cne 'VERIFIED' -or
        [string]$roleReadback.roleBindingRef -cne [string]$roleBinding.recordId -or
        [string]$roleReadback.roleBindingDigest -cne [string]$roleBinding.contentDigest -or
        [string]$roleReadback.bindingSetDigest -cne [string]$roleBinding.bindingSetDigest -or
        [string]$roleReadback.observedBindingSetDigest -cne [string]$roleBinding.bindingSetDigest -or
        [string]$roleReadback.readerToolRef -cne 'microsoft-graph-directory-readback' -or
        [string]$roleReadback.readIdentityRef -cnotmatch '^private://' -or
        [string]$roleReadback.readIdentityRef -ceq [string]$roleBinding.sourceIdentityRef -or
        [string]$roleReadback.tenantBoundaryRef -cne $ExpectedTenantBoundaryRef -or
        [string]$roleReadback.targetEnvironmentRef -cne $ExpectedTargetEnvironmentRef -or
        [string]$roleReadback.responseArtifactRef -cnotmatch '^private://' -or
        -not (Test-Sha256Token $roleReadback.responseArtifactDigest) -or
        [string]$roleReadback.readbackPolicyRef -cne $ExpectedReadbackPolicyRef -or
        [string]$roleReadback.readbackPolicyDigest -cne $ExpectedReadbackPolicyDigest -or
        [string]$roleReadback.revocationStatus -cne [string]$roleBinding.revocationStatus -or
        [string]$roleReadback.revocationEvidenceRef -cne [string]$roleBinding.revocationEvidenceRef -or
        [string]$roleReadback.revocationEvidenceDigest -cne [string]$roleBinding.revocationEvidenceDigest -or
        [string]$roleReadback.revocationCheckedAt -cne [string]$roleBinding.revocationCheckedAt -or
        [string]$roleReadback.consistencyStatus -cne 'PASS' -or
        -not $readbackAgeValid -or -not $readbackTimesValid -or
        $roleObservedAt -lt $bindingRevocationCheckedAt -or
        $roleReadbackRevocationCheckedAt -lt $bindingRevocationCheckedAt -or
        $roleReadbackRevocationCheckedAt -gt $roleObservedAt -or
        $roleObservedAt -gt $EvaluationTime -or
        ($EvaluationTime - $roleObservedAt).TotalMinutes -gt $ExpectedReadbackMaximumAgeMinutes) {
        Add-BlueprintError -Errors $Errors -Code 'ROLE_BINDING_READBACK_INVALID' -Message 'Role binding requires a fresh independent directory readback of the exact canonical set, tenant, environment, revocation evidence, and authenticated readback policy.'
    }
    return [pscustomobject]@{
        RoleBinding = $roleBinding
        Readback = $roleReadback
        Approval = $bindingApproval
        RootAuthority = $rootAuthority
        AliasMap = $aliasMap
        RoleMap = $roleMap
    }
}

function Test-AzureDeploymentOperationSemantics {
    param(
        [Parameter(Mandatory = $true)]$Operation,
        [Parameter(Mandatory = $true)]$RecordMap,
        [Parameter(Mandatory = $true)][DateTimeOffset]$EvaluationTime,
        [Parameter(Mandatory = $true)][AllowEmptyCollection()][System.Collections.ArrayList]$Errors
    )

    $initialErrorCount = $Errors.Count
    Test-RequiredProperties -Object $Operation -Names @(
        'schemaVersion','recordStage','status','operationId','writerToolRef','writeIdentityRef',
        'applyOperatorIdentityRef','tenantBoundaryRef','subscriptionBoundaryRef','targetEnvironmentRef',
        'targetScopeRef','resourceType','resourceIdRef','apiVersion','sourceCommit','desiredStateRevision',
        'reviewedPlanRef','reviewedPlanDigest','expectedStateProjectionRef','expectedStateProjectionDigest',
        'expectedStateDigest','writeAuthorizationRef','writeAuthorizationDigest','writeOperationRef',
        'writeOperationDigest','authorizationConsumptionRef','authorizationConsumptionDigest',
        'authorizationConsumptionReadbackRef','authorizationConsumptionReadbackDigest','roleBindingRef',
        'roleBindingDigest','roleBindingReadbackRef','roleBindingReadbackDigest','packageVerificationRef',
        'packageVerificationDigest','operationArtifactRef','operationArtifactDigest','startedAt','completedAt'
    ) -Context 'Azure deployment operation' -Errors $Errors

    $plan = Resolve-CanonicalRecord -RecordMap $RecordMap -Reference $Operation.reviewedPlanRef `
        -ExpectedTypes @('reviewed-plan-record') -Context 'Azure deployment reviewed plan' -Errors $Errors
    $authorization = Resolve-CanonicalRecord -RecordMap $RecordMap -Reference $Operation.writeAuthorizationRef `
        -ExpectedTypes @('write-authorization-record') -Context 'Azure deployment write authorization' -Errors $Errors
    $writeOperation = Resolve-CanonicalRecord -RecordMap $RecordMap -Reference $Operation.writeOperationRef `
        -ExpectedTypes @('write-operation-record') -Context 'Azure deployment write operation' -Errors $Errors
    $consumption = Resolve-CanonicalRecord -RecordMap $RecordMap -Reference $Operation.authorizationConsumptionRef `
        -ExpectedTypes @('authorization-consumption-record') -Context 'Azure authorization consumption' -Errors $Errors
    $consumptionReadback = Resolve-CanonicalRecord -RecordMap $RecordMap `
        -Reference $Operation.authorizationConsumptionReadbackRef `
        -ExpectedTypes @('authorization-consumption-ledger-readback-record') `
        -Context 'Azure authorization-consumption readback' -Errors $Errors
    $package = Resolve-CanonicalRecord -RecordMap $RecordMap -Reference $Operation.packageVerificationRef `
        -ExpectedTypes @('package-verification-record') -Context 'Azure package verification' -Errors $Errors
    $transportOwnership = if ($null -ne $authorization) {
        Resolve-CanonicalRecord -RecordMap $RecordMap -Reference $authorization.transportOwnershipRef `
            -ExpectedTypes @('transport-ownership-record') -Context 'Azure transport ownership' -Errors $Errors
    }
    else { $null }

    [int64]$readbackMaximumAge = if ($null -ne $authorization -and
        ($authorization.readbackMaxAgeMinutes -is [int] -or $authorization.readbackMaxAgeMinutes -is [long]) -and
        [int64]$authorization.readbackMaxAgeMinutes -gt 0) {
        [int64]$authorization.readbackMaxAgeMinutes
    }
    else { 0 }
    $roleReadbackForAzureClosure = Resolve-CanonicalRecord -RecordMap $RecordMap `
        -Reference $Operation.roleBindingReadbackRef -ExpectedTypes @('role-binding-readback-record') `
        -Context 'Azure role-binding readback' -Errors $Errors
    [int64]$roleReadbackMaximumAge = if ($null -ne $roleReadbackForAzureClosure -and
        ($roleReadbackForAzureClosure.maxAgeMinutes -is [int] -or $roleReadbackForAzureClosure.maxAgeMinutes -is [long]) -and
        [int64]$roleReadbackForAzureClosure.maxAgeMinutes -gt 0) {
        [int64]$roleReadbackForAzureClosure.maxAgeMinutes
    }
    else { 0 }
    $roleClosure = if ($null -ne $authorization -and $null -ne $roleReadbackForAzureClosure -and
        $roleReadbackMaximumAge -gt 0) {
        Test-RoleBindingClosure -RecordMap $RecordMap `
            -RoleBindingRef ([string]$Operation.roleBindingRef) -RoleBindingDigest ([string]$Operation.roleBindingDigest) `
            -RoleBindingReadbackRef ([string]$Operation.roleBindingReadbackRef) `
            -RoleBindingReadbackDigest ([string]$Operation.roleBindingReadbackDigest) `
            -ExpectedTenantBoundaryRef ([string]$Operation.tenantBoundaryRef) `
            -ExpectedTargetEnvironmentRef ([string]$Operation.targetEnvironmentRef) `
            -ExpectedReadbackPolicyRef ([string]$roleReadbackForAzureClosure.readbackPolicyRef) `
            -ExpectedReadbackPolicyDigest ([string]$roleReadbackForAzureClosure.readbackPolicyDigest) `
            -ExpectedReadbackMaximumAgeMinutes $roleReadbackMaximumAge -EvaluationTime $EvaluationTime -Errors $Errors
    }
    else { $null }

    [int64]$authorizationTtlMaximumAge = if ($null -ne $authorization -and
        ($authorization.authorizationMaxTtlMinutes -is [int] -or $authorization.authorizationMaxTtlMinutes -is [long]) -and
        [int64]$authorization.authorizationMaxTtlMinutes -gt 0) {
        [int64]$authorization.authorizationMaxTtlMinutes
    }
    else { 0 }
    [int64]$authorizationRevocationMaximumAge = if ($null -ne $authorization -and
        ($authorization.authorizationRevocationCheckMaxAgeMinutes -is [int] -or $authorization.authorizationRevocationCheckMaxAgeMinutes -is [long]) -and
        [int64]$authorization.authorizationRevocationCheckMaxAgeMinutes -gt 0) {
        [int64]$authorization.authorizationRevocationCheckMaxAgeMinutes
    }
    else { 0 }
    [int64]$packageRevocationMaximumAge = if ($null -ne $package -and
        ($package.packageRevocationCheckMaxAgeMinutes -is [int] -or $package.packageRevocationCheckMaxAgeMinutes -is [long]) -and
        [int64]$package.packageRevocationCheckMaxAgeMinutes -gt 0) {
        [int64]$package.packageRevocationCheckMaxAgeMinutes
    }
    else { 0 }
    $authorizationTtlPolicy = if ($null -ne $authorization) {
        Test-SecurityFreshnessPolicyBinding -RecordMap $RecordMap `
            -Reference $authorization.authorizationTtlPolicyRef -Digest $authorization.authorizationTtlPolicyDigest `
            -ExpectedKind 'AUTHORIZATION_TTL' -ExpectedMaximumAgeMinutes $authorizationTtlMaximumAge `
            -ExpectedTenantBoundaryRef ([string]$Operation.tenantBoundaryRef) `
            -ExpectedTargetEnvironmentRef ([string]$Operation.targetEnvironmentRef) `
            -ExpectedRoleBindingRef ([string]$Operation.roleBindingRef) `
            -ExpectedRoleBindingDigest ([string]$Operation.roleBindingDigest) `
            -ExpectedRoleBindingReadbackRef ([string]$Operation.roleBindingReadbackRef) `
            -ExpectedRoleBindingReadbackDigest ([string]$Operation.roleBindingReadbackDigest) `
            -EvaluationTime $EvaluationTime -Errors $Errors
    }
    else { $null }
    $authorizationRevocationPolicy = if ($null -ne $authorization) {
        Test-SecurityFreshnessPolicyBinding -RecordMap $RecordMap `
            -Reference $authorization.authorizationRevocationFreshnessPolicyRef `
            -Digest $authorization.authorizationRevocationFreshnessPolicyDigest `
            -ExpectedKind 'AUTHORIZATION_REVOCATION' -ExpectedMaximumAgeMinutes $authorizationRevocationMaximumAge `
            -ExpectedTenantBoundaryRef ([string]$Operation.tenantBoundaryRef) `
            -ExpectedTargetEnvironmentRef ([string]$Operation.targetEnvironmentRef) `
            -ExpectedRoleBindingRef ([string]$Operation.roleBindingRef) `
            -ExpectedRoleBindingDigest ([string]$Operation.roleBindingDigest) `
            -ExpectedRoleBindingReadbackRef ([string]$Operation.roleBindingReadbackRef) `
            -ExpectedRoleBindingReadbackDigest ([string]$Operation.roleBindingReadbackDigest) `
            -EvaluationTime $EvaluationTime -Errors $Errors
    }
    else { $null }
    $packageRevocationPolicy = if ($null -ne $package) {
        Test-SecurityFreshnessPolicyBinding -RecordMap $RecordMap `
            -Reference $package.packageRevocationFreshnessPolicyRef `
            -Digest $package.packageRevocationFreshnessPolicyDigest `
            -ExpectedKind 'PACKAGE_REVOCATION' -ExpectedMaximumAgeMinutes $packageRevocationMaximumAge `
            -ExpectedTenantBoundaryRef ([string]$Operation.tenantBoundaryRef) `
            -ExpectedTargetEnvironmentRef ([string]$Operation.targetEnvironmentRef) `
            -ExpectedRoleBindingRef ([string]$Operation.roleBindingRef) `
            -ExpectedRoleBindingDigest ([string]$Operation.roleBindingDigest) `
            -ExpectedRoleBindingReadbackRef ([string]$Operation.roleBindingReadbackRef) `
            -ExpectedRoleBindingReadbackDigest ([string]$Operation.roleBindingReadbackDigest) `
            -EvaluationTime $EvaluationTime -Errors $Errors
    }
    else { $null }
    $authorizationReadbackPolicy = if ($null -ne $authorization) {
        Test-SecurityFreshnessPolicyBinding -RecordMap $RecordMap `
            -Reference $authorization.independentReadbackPolicyRef `
            -Digest $authorization.independentReadbackPolicyDigest `
            -ExpectedKind 'READBACK_FRESHNESS' -ExpectedMaximumAgeMinutes $readbackMaximumAge `
            -ExpectedTenantBoundaryRef ([string]$Operation.tenantBoundaryRef) `
            -ExpectedTargetEnvironmentRef ([string]$Operation.targetEnvironmentRef) `
            -ExpectedRoleBindingRef ([string]$Operation.roleBindingRef) `
            -ExpectedRoleBindingDigest ([string]$Operation.roleBindingDigest) `
            -ExpectedRoleBindingReadbackRef ([string]$Operation.roleBindingReadbackRef) `
            -ExpectedRoleBindingReadbackDigest ([string]$Operation.roleBindingReadbackDigest) `
            -EvaluationTime $EvaluationTime -Errors $Errors
    }
    else { $null }
    $packageSemanticRecord = if ($null -ne $authorization -and $null -ne $package) {
        Test-PackageVerificationBinding -RecordMap $RecordMap `
            -Reference $Operation.packageVerificationRef -Digest $Operation.packageVerificationDigest `
            -ExpectedPackageDigest ([string]$authorization.packageDigest) `
            -ExpectedSourceCommit ([string]$Operation.sourceCommit) `
            -ExpectedRevocationFreshnessPolicyRef ([string]$package.packageRevocationFreshnessPolicyRef) `
            -ExpectedRevocationFreshnessPolicyDigest ([string]$package.packageRevocationFreshnessPolicyDigest) `
            -MaximumRevocationAgeMinutes $packageRevocationMaximumAge -EvaluationTime $EvaluationTime -Errors $Errors
    }
    else { $null }

    [DateTimeOffset]$operationStartedAt = [DateTimeOffset]::MinValue
    [DateTimeOffset]$operationCompletedAt = [DateTimeOffset]::MinValue
    [DateTimeOffset]$planExpiresAt = [DateTimeOffset]::MinValue
    [DateTimeOffset]$authorizationIssuedAt = [DateTimeOffset]::MinValue
    [DateTimeOffset]$authorizationNotBefore = [DateTimeOffset]::MinValue
    [DateTimeOffset]$authorizationExpiresAt = [DateTimeOffset]::MinValue
    [DateTimeOffset]$authorizationRevocationCheckedAt = [DateTimeOffset]::MinValue
    [DateTimeOffset]$authorizationTtlPolicyApprovedAt = [DateTimeOffset]::MinValue
    [DateTimeOffset]$authorizationRevocationPolicyApprovedAt = [DateTimeOffset]::MinValue
    [DateTimeOffset]$packageRevocationPolicyApprovedAt = [DateTimeOffset]::MinValue
    [DateTimeOffset]$authorizationReadbackPolicyApprovedAt = [DateTimeOffset]::MinValue
    [DateTimeOffset]$packageRevocationCheckedAt = [DateTimeOffset]::MinValue
    [DateTimeOffset]$consumedAt = [DateTimeOffset]::MinValue
    [DateTimeOffset]$workflowStartedAt = [DateTimeOffset]::MinValue
    [DateTimeOffset]$mutationStartedAt = [DateTimeOffset]::MinValue
    [DateTimeOffset]$writeCompletedAt = [DateTimeOffset]::MinValue
    [DateTimeOffset]$ledgerObservedAt = [DateTimeOffset]::MinValue
    $timesValid = [OperationsBlueprint.StrictRfc3339]::TryParse([string]$Operation.startedAt, [ref]$operationStartedAt) -and
        [OperationsBlueprint.StrictRfc3339]::TryParse([string]$Operation.completedAt, [ref]$operationCompletedAt) -and
        $null -ne $plan -and [OperationsBlueprint.StrictRfc3339]::TryParse([string]$plan.planExpiresAt, [ref]$planExpiresAt) -and
        $null -ne $authorization -and
        [OperationsBlueprint.StrictRfc3339]::TryParse([string]$authorization.issuedAt, [ref]$authorizationIssuedAt) -and
        [OperationsBlueprint.StrictRfc3339]::TryParse([string]$authorization.notBefore, [ref]$authorizationNotBefore) -and
        [OperationsBlueprint.StrictRfc3339]::TryParse([string]$authorization.expiresAt, [ref]$authorizationExpiresAt) -and
        [OperationsBlueprint.StrictRfc3339]::TryParse([string]$authorization.revocationCheckedAt, [ref]$authorizationRevocationCheckedAt) -and
        $null -ne $authorizationTtlPolicy -and
        [OperationsBlueprint.StrictRfc3339]::TryParse([string]$authorizationTtlPolicy.approvedAt, [ref]$authorizationTtlPolicyApprovedAt) -and
        $null -ne $authorizationRevocationPolicy -and
        [OperationsBlueprint.StrictRfc3339]::TryParse([string]$authorizationRevocationPolicy.approvedAt, [ref]$authorizationRevocationPolicyApprovedAt) -and
        $null -ne $packageRevocationPolicy -and
        [OperationsBlueprint.StrictRfc3339]::TryParse([string]$packageRevocationPolicy.approvedAt, [ref]$packageRevocationPolicyApprovedAt) -and
        $null -ne $authorizationReadbackPolicy -and
        [OperationsBlueprint.StrictRfc3339]::TryParse([string]$authorizationReadbackPolicy.approvedAt, [ref]$authorizationReadbackPolicyApprovedAt) -and
        $null -ne $package -and
        [OperationsBlueprint.StrictRfc3339]::TryParse([string]$package.revocationCheckedAt, [ref]$packageRevocationCheckedAt) -and
        $null -ne $consumption -and [OperationsBlueprint.StrictRfc3339]::TryParse([string]$consumption.consumedAt, [ref]$consumedAt) -and
        $null -ne $writeOperation -and
        [OperationsBlueprint.StrictRfc3339]::TryParse([string]$writeOperation.startedAt, [ref]$workflowStartedAt) -and
        [OperationsBlueprint.StrictRfc3339]::TryParse([string]$writeOperation.mutationStartedAt, [ref]$mutationStartedAt) -and
        [OperationsBlueprint.StrictRfc3339]::TryParse([string]$writeOperation.completedAt, [ref]$writeCompletedAt) -and
        $null -ne $consumptionReadback -and
        [OperationsBlueprint.StrictRfc3339]::TryParse([string]$consumptionReadback.observedAt, [ref]$ledgerObservedAt)

    $expectedAuthorizationSubjectDigest = if ($null -ne $authorization) {
        Get-WriteAuthorizationSubjectDigest -Authorization $authorization
    }
    else { '' }
    $expectedAzureManagedObjectSetDigest = Get-ManagedObjectSetDigest -ManagedObjectRefs @([string]$Operation.resourceIdRef)
    $authorizationNonceOwners = if ($null -ne $authorization) { @($RecordMap.Values | Where-Object {
        [string]$_.recordType -ceq 'write-authorization-record' -and
        [string]$_.authorizationNonce -ceq [string]$authorization.authorizationNonce
    }) } else { @() }
    $authorizationOperationConsumers = if ($null -ne $authorization) { @($RecordMap.Values | Where-Object {
        [string]$_.recordType -ceq 'write-operation-record' -and
        ([string]$_.writeAuthorizationRef -ceq [string]$Operation.writeAuthorizationRef -or
         [string]$_.authorizationId -ceq [string]$authorization.authorizationId -or
         [string]$_.authorizationNonce -ceq [string]$authorization.authorizationNonce)
    }) } else { @() }
    $azureDeploymentConsumers = @($RecordMap.Values | Where-Object {
        [string]$_.recordType -ceq 'azure-deployment-operation-record' -and
        ([string]$_.operationId -ceq [string]$Operation.operationId -or
         [string]$_.writeAuthorizationRef -ceq [string]$Operation.writeAuthorizationRef -or
         [string]$_.writeOperationRef -ceq [string]$Operation.writeOperationRef -or
         [string]$_.authorizationConsumptionRef -ceq [string]$Operation.authorizationConsumptionRef)
    })
    $sameNonceConsumptions = if ($null -ne $consumption) { @($RecordMap.Values | Where-Object {
        [string]$_.recordType -ceq 'authorization-consumption-record' -and
        [string]$_.authorizationNonce -ceq [string]$consumption.authorizationNonce -and
        [string]$_.status -ceq 'COMMITTED'
    }) } else { @() }
    $sameLedgerSequence = if ($null -ne $consumption) { @($RecordMap.Values | Where-Object {
        [string]$_.recordType -ceq 'authorization-consumption-record' -and
        [string]$_.consumptionLedgerRef -ceq [string]$consumption.consumptionLedgerRef -and
        [string]$_.consumptionLedgerSequence -ceq [string]$consumption.consumptionLedgerSequence -and
        [string]$_.status -ceq 'COMMITTED'
    }) } else { @() }
    $sameConsumptionObservers = if ($null -ne $consumption) { @($RecordMap.Values | Where-Object {
        [string]$_.recordType -ceq 'authorization-consumption-ledger-readback-record' -and
        [string]$_.consumptionRecordRef -ceq [string]$consumption.recordId -and
        [string]$_.status -ceq 'VERIFIED'
    }) } else { @() }
    $consumptionSequenceValid = $null -ne $consumption -and
        ($consumption.consumptionLedgerSequence -is [int] -or $consumption.consumptionLedgerSequence -is [long]) -and
        [int64]$consumption.consumptionLedgerSequence -ge 1
    $previousLedgerEntryValid = $consumptionSequenceValid
    if ($consumptionSequenceValid -and [int64]$consumption.consumptionLedgerSequence -gt 1) {
        [int64]$previousSequence = [int64]$consumption.consumptionLedgerSequence - 1
        $previousLedgerEntryValid = @($RecordMap.Values | Where-Object {
            [string]$_.recordType -ceq 'authorization-consumption-record' -and
            [string]$_.status -ceq 'COMMITTED' -and
            [string]$_.consumptionLedgerRef -ceq [string]$consumption.consumptionLedgerRef -and
            [string]$_.consumptionLedgerSequence -ceq [string]$previousSequence -and
            [string]$_.consumptionLedgerDigest -ceq [string]$consumption.previousLedgerEntryDigest
        }).Count -eq 1
    }
    if ($authorizationNonceOwners.Count -ne 1 -or $authorizationOperationConsumers.Count -ne 1 -or
        $sameNonceConsumptions.Count -ne 1 -or $sameLedgerSequence.Count -ne 1 -or
        $sameConsumptionObservers.Count -ne 1 -or $azureDeploymentConsumers.Count -ne 1) {
        Add-BlueprintError -Errors $Errors -Code 'WRITE_AUTHORIZATION_REPLAY_OR_REUSE' -Message 'Azure deployment requires one unique authorization nonce, consumer, committed consumption, and ledger sequence.'
    }
    if (-not $previousLedgerEntryValid) {
        Add-BlueprintError -Errors $Errors -Code 'AUTHORIZATION_LEDGER_CHAIN_INVALID' -Message 'Azure deployment authorization consumption does not resolve its immediately previous monotonic ledger entry.'
    }
    $chainValid =
        [string]$Operation.schemaVersion -ceq '1.0.0' -and
        [string]$Operation.recordStage -ceq 'AZURE_RESOURCE_DEPLOYMENT_OPERATION' -and
        [string]$Operation.status -ceq 'COMPLETED' -and
        (Test-NonBlankString $Operation.operationId) -and
        [string]$Operation.writerToolRef -ceq 'terraform' -and
        @('writeIdentityRef','applyOperatorIdentityRef','tenantBoundaryRef','subscriptionBoundaryRef',
          'targetEnvironmentRef','targetScopeRef','resourceIdRef','expectedStateProjectionRef',
          'operationArtifactRef' | Where-Object { [string]$Operation.$_ -cnotmatch '^private://' }).Count -eq 0 -and
        [string]$Operation.writeIdentityRef -cne [string]$Operation.applyOperatorIdentityRef -and
        (Test-NonBlankString $Operation.resourceType) -and (Test-NonBlankString $Operation.apiVersion) -and
        [string]$Operation.sourceCommit -cmatch '^[0-9a-f]{40}([0-9a-f]{24})?$' -and
        @('desiredStateRevision','reviewedPlanDigest','expectedStateProjectionDigest','expectedStateDigest',
          'writeAuthorizationDigest','writeOperationDigest','authorizationConsumptionDigest',
          'authorizationConsumptionReadbackDigest','roleBindingDigest','roleBindingReadbackDigest',
          'packageVerificationDigest','operationArtifactDigest' | Where-Object { -not (Test-Sha256Token $Operation.$_) }).Count -eq 0 -and
        $null -ne $plan -and $null -ne $authorization -and $null -ne $writeOperation -and
        $null -ne $consumption -and $null -ne $consumptionReadback -and $null -ne $package -and
        $null -ne $transportOwnership -and
        $null -ne $authorizationTtlPolicy -and $null -ne $authorizationRevocationPolicy -and
        $null -ne $packageRevocationPolicy -and $null -ne $authorizationReadbackPolicy -and
        $null -ne $packageSemanticRecord -and
        $null -ne $roleClosure -and
        [string]$plan.contentDigest -ceq [string]$Operation.reviewedPlanDigest -and
        [string]$plan.status -ceq 'APPROVED' -and [string]$plan.writerToolRef -ceq 'terraform' -and
        [string]$plan.sourceCommit -ceq [string]$Operation.sourceCommit -and
        [string]$plan.desiredStateRevision -ceq [string]$Operation.desiredStateRevision -and
        [string]$plan.tenantBoundaryRef -ceq [string]$Operation.tenantBoundaryRef -and
        [string]$plan.targetEnvironmentRef -ceq [string]$Operation.targetEnvironmentRef -and
        [string]$plan.targetScopeRef -ceq [string]$Operation.targetScopeRef -and
        [string]$plan.azureSubscriptionBoundaryRef -ceq [string]$Operation.subscriptionBoundaryRef -and
        [string]$plan.azureResourceType -ceq [string]$Operation.resourceType -and
        [string]$plan.azureResourceIdRef -ceq [string]$Operation.resourceIdRef -and
        [string]$plan.azureApiVersion -ceq [string]$Operation.apiVersion -and
        [string]$plan.expectedStateProjectionRef -ceq [string]$Operation.expectedStateProjectionRef -and
        [string]$plan.expectedStateProjectionDigest -ceq [string]$Operation.expectedStateProjectionDigest -and
        [string]$plan.expectedStateDigest -ceq [string]$Operation.expectedStateDigest -and
        [string]$plan.managedObjectType -ceq [string]$Operation.resourceType -and
        [string]$plan.packageDigest -ceq [string]$authorization.packageDigest -and
        [string]$plan.packageVerificationRef -ceq [string]$Operation.packageVerificationRef -and
        [string]$plan.packageVerificationDigest -ceq [string]$Operation.packageVerificationDigest -and
        [string]$authorization.contentDigest -ceq [string]$Operation.writeAuthorizationDigest -and
        [string]$authorization.status -ceq 'ISSUED' -and
        [string]$authorization.authorizedOperationId -ceq [string]$Operation.operationId -and
        [string]$authorization.reviewedPlanRef -ceq [string]$Operation.reviewedPlanRef -and
        [string]$authorization.reviewedPlanDigest -ceq [string]$Operation.reviewedPlanDigest -and
        [string]$authorization.writerToolRef -ceq 'terraform' -and
        [string]$authorization.writeIdentityRef -ceq [string]$Operation.writeIdentityRef -and
        [string]$authorization.applyOperatorIdentityRef -ceq [string]$Operation.applyOperatorIdentityRef -and
        [string]$authorization.tenantBoundaryRef -ceq [string]$Operation.tenantBoundaryRef -and
        [string]$authorization.targetEnvironmentRef -ceq [string]$Operation.targetEnvironmentRef -and
        [string]$authorization.targetScopeRef -ceq [string]$Operation.targetScopeRef -and
        [string]$authorization.desiredStateRevision -ceq [string]$Operation.desiredStateRevision -and
        [string]$authorization.managedObjectType -ceq [string]$Operation.resourceType -and
        (Test-CanonicalValueEqual @($authorization.managedObjectRefs) @([string]$Operation.resourceIdRef)) -and
        [string]$authorization.managedObjectSetDigest -ceq $expectedAzureManagedObjectSetDigest -and
        ($authorization.maxUses -is [int] -or $authorization.maxUses -is [long]) -and
        [int64]$authorization.maxUses -eq 1 -and $authorization.singleUse -eq $true -and
        [string]$authorization.revocationStatus -ceq 'NOT_REVOKED' -and
        [string]$authorization.revocationEvidenceRef -cmatch '^private://' -and
        (Test-Sha256Token $authorization.revocationEvidenceDigest) -and
        [string]$authorization.authorizationTtlPolicyRef -ceq [string]$authorizationTtlPolicy.recordId -and
        [string]$authorization.authorizationTtlPolicyDigest -ceq [string]$authorizationTtlPolicy.contentDigest -and
        ($authorization.authorizationMaxTtlMinutes -is [int] -or $authorization.authorizationMaxTtlMinutes -is [long]) -and
        [int64]$authorization.authorizationMaxTtlMinutes -eq $authorizationTtlMaximumAge -and
        [string]$authorization.authorizationRevocationFreshnessPolicyRef -ceq [string]$authorizationRevocationPolicy.recordId -and
        [string]$authorization.authorizationRevocationFreshnessPolicyDigest -ceq [string]$authorizationRevocationPolicy.contentDigest -and
        ($authorization.authorizationRevocationCheckMaxAgeMinutes -is [int] -or $authorization.authorizationRevocationCheckMaxAgeMinutes -is [long]) -and
        [int64]$authorization.authorizationRevocationCheckMaxAgeMinutes -eq $authorizationRevocationMaximumAge -and
        [string]$authorization.independentReadbackPolicyRef -ceq [string]$authorizationReadbackPolicy.recordId -and
        [string]$authorization.independentReadbackPolicyDigest -ceq [string]$authorizationReadbackPolicy.contentDigest -and
        ($authorization.readbackMaxAgeMinutes -is [int] -or $authorization.readbackMaxAgeMinutes -is [long]) -and
        [int64]$authorization.readbackMaxAgeMinutes -eq $readbackMaximumAge -and
        [string]$authorization.packageDigest -ceq [string]$plan.packageDigest -and
        [string]$authorization.targetMembershipDigest -ceq [string]$plan.targetMembershipDigest -and
        (Test-CanonicalValueEqual $authorization.targetPopulation $plan.targetPopulation) -and
        [string]$authorization.packageVerificationRef -ceq [string]$Operation.packageVerificationRef -and
        [string]$authorization.packageVerificationDigest -ceq [string]$Operation.packageVerificationDigest -and
        [string]$authorization.roleBindingRef -ceq [string]$Operation.roleBindingRef -and
        [string]$authorization.roleBindingDigest -ceq [string]$Operation.roleBindingDigest -and
        [string]$authorization.roleBindingReadbackRef -ceq [string]$Operation.roleBindingReadbackRef -and
        [string]$authorization.roleBindingReadbackDigest -ceq [string]$Operation.roleBindingReadbackDigest -and
        [string]$authorization.transportOwnershipDigest -ceq [string]$transportOwnership.contentDigest -and
        [string]$transportOwnership.managedObjectType -ceq [string]$Operation.resourceType -and
        [string]$transportOwnership.targetScopeRef -ceq [string]$Operation.targetScopeRef -and
        [string]$transportOwnership.writerToolRef -ceq 'terraform' -and
        [string]$transportOwnership.selectionStatus -ceq 'APPROVED_OBJECT_TYPE_OWNER' -and
        [string]$authorization.issuedByRole -ceq 'ROLE_PROTECTED_ENVIRONMENT_APPROVER' -and
        [string]$authorization.issuedByPrincipalRef -cmatch '^private://' -and
        [string]$authorization.authorizationSubjectDigest -ceq $expectedAuthorizationSubjectDigest -and
        [string]$authorization.authorizationArtifactRef -cmatch '^private://' -and
        [string]$authorization.authorizationArtifactDigest -ceq $expectedAuthorizationSubjectDigest -and
        [string]$authorization.issuerSignatureRef -cmatch '^private://' -and
        (Test-Sha256Token $authorization.issuerSignatureDigest) -and
        [string]$authorization.issuerSignatureStatus -ceq 'VERIFIED' -and
        [string]$writeOperation.contentDigest -ceq [string]$Operation.writeOperationDigest -and
        [string]$writeOperation.status -ceq 'COMPLETED' -and
        [string]$writeOperation.operationId -ceq [string]$Operation.operationId -and
        [string]$writeOperation.writeAuthorizationRef -ceq [string]$Operation.writeAuthorizationRef -and
        [string]$writeOperation.writeAuthorizationDigest -ceq [string]$Operation.writeAuthorizationDigest -and
        [string]$writeOperation.authorizationId -ceq [string]$authorization.authorizationId -and
        [string]$writeOperation.authorizationNonce -ceq [string]$authorization.authorizationNonce -and
        ($writeOperation.maxUses -is [int] -or $writeOperation.maxUses -is [long]) -and
        [int64]$writeOperation.maxUses -eq 1 -and
        [string]$writeOperation.reviewedPlanRef -ceq [string]$Operation.reviewedPlanRef -and
        [string]$writeOperation.reviewedPlanDigest -ceq [string]$Operation.reviewedPlanDigest -and
        [string]$writeOperation.writerToolRef -ceq 'terraform' -and
        [string]$writeOperation.writeIdentityRef -ceq [string]$Operation.writeIdentityRef -and
        [string]$writeOperation.applyOperatorIdentityRef -ceq [string]$Operation.applyOperatorIdentityRef -and
        [string]$writeOperation.tenantBoundaryRef -ceq [string]$Operation.tenantBoundaryRef -and
        [string]$writeOperation.targetEnvironmentRef -ceq [string]$Operation.targetEnvironmentRef -and
        [string]$writeOperation.targetScopeRef -ceq [string]$Operation.targetScopeRef -and
        [string]$writeOperation.desiredStateRevision -ceq [string]$Operation.desiredStateRevision -and
        [string]$writeOperation.packageVerificationRef -ceq [string]$Operation.packageVerificationRef -and
        [string]$writeOperation.packageVerificationDigest -ceq [string]$Operation.packageVerificationDigest -and
        [string]$writeOperation.roleBindingRef -ceq [string]$Operation.roleBindingRef -and
        [string]$writeOperation.roleBindingDigest -ceq [string]$Operation.roleBindingDigest -and
        [string]$writeOperation.roleBindingReadbackRef -ceq [string]$Operation.roleBindingReadbackRef -and
        [string]$writeOperation.roleBindingReadbackDigest -ceq [string]$Operation.roleBindingReadbackDigest -and
        [string]$writeOperation.authorizationConsumptionRef -ceq [string]$Operation.authorizationConsumptionRef -and
        [string]$writeOperation.authorizationConsumptionDigest -ceq [string]$Operation.authorizationConsumptionDigest -and
        [string]$writeOperation.consumptionLedgerRef -ceq [string]$consumption.consumptionLedgerRef -and
        [string]$writeOperation.consumptionLedgerDigest -ceq [string]$consumption.consumptionLedgerDigest -and
        [string]$writeOperation.consumptionLedgerSequence -ceq [string]$consumption.consumptionLedgerSequence -and
        [string]$writeOperation.replayCheckStatus -ceq 'NOT_REUSED' -and
        [string]$writeOperation.transportOwnershipRef -ceq [string]$authorization.transportOwnershipRef -and
        [string]$writeOperation.transportOwnershipDigest -ceq [string]$authorization.transportOwnershipDigest -and
        [string]$writeOperation.managedObjectType -ceq [string]$Operation.resourceType -and
        (Test-CanonicalValueEqual @($writeOperation.managedObjectRefs) @([string]$Operation.resourceIdRef)) -and
        [string]$writeOperation.managedObjectSetDigest -ceq $expectedAzureManagedObjectSetDigest -and
        [string]$writeOperation.packageDigest -ceq [string]$authorization.packageDigest -and
        [string]$writeOperation.targetMembershipDigest -ceq [string]$authorization.targetMembershipDigest -and
        (Test-CanonicalValueEqual $writeOperation.targetPopulation $authorization.targetPopulation) -and
        [string]$writeOperation.independentReadbackPolicyRef -ceq [string]$authorization.independentReadbackPolicyRef -and
        [string]$writeOperation.independentReadbackPolicyDigest -ceq [string]$authorization.independentReadbackPolicyDigest -and
        ($writeOperation.readbackMaxAgeMinutes -is [int] -or $writeOperation.readbackMaxAgeMinutes -is [long]) -and
        [int64]$writeOperation.readbackMaxAgeMinutes -eq $readbackMaximumAge -and
        [string]$writeOperation.consumedAt -ceq [string]$consumption.consumedAt -and
        ($writeOperation.authorizationUseCount -is [int] -or $writeOperation.authorizationUseCount -is [long]) -and
        [int64]$writeOperation.authorizationUseCount -eq 1 -and
        [string]$writeOperation.expectedReadbackKind -ceq 'AZURE_RESOURCE_STATE' -and
        [string]$consumption.contentDigest -ceq [string]$Operation.authorizationConsumptionDigest -and
        [string]$consumption.schemaVersion -ceq '1.0.0' -and
        [string]$consumption.recordStage -ceq 'AUTHORIZATION_CONSUMPTION' -and
        [string]$consumption.status -ceq 'COMMITTED' -and
        [string]$consumption.consumptionLedgerRef -ceq [string]$authorization.consumptionLedgerRef -and
        [string]$consumption.consumptionLedgerPolicyRef -ceq [string]$authorization.consumptionLedgerPolicyRef -and
        [string]$consumption.consumptionLedgerPolicyDigest -ceq [string]$authorization.consumptionLedgerPolicyDigest -and
        [string]$consumption.ledgerAuthorityIdentityRef -cmatch '^private://' -and
        [string]$consumption.ledgerAuthorityIdentityRef -cne [string]$Operation.writeIdentityRef -and
        [string]$consumption.ledgerAuthorityIdentityRef -cne [string]$Operation.applyOperatorIdentityRef -and
        [string]$consumption.authorizationRef -ceq [string]$Operation.writeAuthorizationRef -and
        [string]$consumption.authorizationDigest -ceq [string]$Operation.writeAuthorizationDigest -and
        [string]$consumption.authorizationId -ceq [string]$authorization.authorizationId -and
        [string]$consumption.authorizationNonce -ceq [string]$authorization.authorizationNonce -and
        [string]$consumption.authorizedOperationId -ceq [string]$Operation.operationId -and
        [string]$consumption.managedObjectSetDigest -ceq $expectedAzureManagedObjectSetDigest -and
        [string]$consumption.ledgerAuthorityRole -ceq 'ROLE_AUTHORIZATION_LEDGER_OWNER' -and
        ($consumption.maxUses -is [int] -or $consumption.maxUses -is [long]) -and
        [int64]$consumption.maxUses -eq 1 -and
        ($consumption.authorizationUseCount -is [int] -or $consumption.authorizationUseCount -is [long]) -and
        [int64]$consumption.authorizationUseCount -eq 1 -and
        $consumptionSequenceValid -and $previousLedgerEntryValid -and
        (Test-Sha256Token $consumption.previousLedgerEntryDigest) -and
        (Test-Sha256Token $consumption.consumptionLedgerDigest) -and
        [string]$consumption.previousLedgerEntryDigest -cne [string]$consumption.consumptionLedgerDigest -and
        [string]$consumption.replayCheckStatus -ceq 'NOT_REUSED' -and
        [string]$consumption.atomicCommitEvidenceRef -cmatch '^private://' -and
        (Test-Sha256Token $consumption.atomicCommitEvidenceDigest) -and
        [string]$consumption.independentReadbackPolicyRef -ceq [string]$authorization.independentReadbackPolicyRef -and
        [string]$consumption.independentReadbackPolicyDigest -ceq [string]$authorization.independentReadbackPolicyDigest -and
        [string]$writeOperation.authorizationConsumptionRef -ceq [string]$Operation.authorizationConsumptionRef -and
        [string]$writeOperation.authorizationConsumptionDigest -ceq [string]$Operation.authorizationConsumptionDigest -and
        [string]$writeOperation.preNetworkAtomicCommitEvidenceRef -ceq [string]$consumption.atomicCommitEvidenceRef -and
        [string]$writeOperation.preNetworkAtomicCommitEvidenceDigest -ceq [string]$consumption.atomicCommitEvidenceDigest -and
        [string]$consumptionReadback.contentDigest -ceq [string]$Operation.authorizationConsumptionReadbackDigest -and
        [string]$consumptionReadback.schemaVersion -ceq '1.0.0' -and
        [string]$consumptionReadback.recordStage -ceq 'AUTHORIZATION_CONSUMPTION_LEDGER_READBACK' -and
        [string]$consumptionReadback.status -ceq 'VERIFIED' -and
        [string]$consumptionReadback.consumptionRecordRef -ceq [string]$Operation.authorizationConsumptionRef -and
        [string]$consumptionReadback.consumptionRecordDigest -ceq [string]$Operation.authorizationConsumptionDigest -and
        [string]$consumptionReadback.authorizationRef -ceq [string]$Operation.writeAuthorizationRef -and
        [string]$consumptionReadback.authorizationDigest -ceq [string]$Operation.writeAuthorizationDigest -and
        [string]$consumptionReadback.authorizationId -ceq [string]$authorization.authorizationId -and
        [string]$consumptionReadback.authorizationNonce -ceq [string]$authorization.authorizationNonce -and
        [string]$consumptionReadback.authorizedOperationId -ceq [string]$Operation.operationId -and
        [string]$consumptionReadback.consumptionLedgerRef -ceq [string]$consumption.consumptionLedgerRef -and
        [string]$consumptionReadback.ledgerAuthorityIdentityRef -ceq [string]$consumption.ledgerAuthorityIdentityRef -and
        [string]$consumptionReadback.writeOperationRef -ceq [string]$Operation.writeOperationRef -and
        [string]$consumptionReadback.writeOperationDigest -ceq [string]$Operation.writeOperationDigest -and
        [string]$consumptionReadback.writeOperationId -ceq [string]$Operation.operationId -and
        [string]$consumptionReadback.consumptionLedgerSequence -ceq [string]$consumption.consumptionLedgerSequence -and
        [string]$consumptionReadback.resultingLedgerDigest -ceq [string]$consumption.consumptionLedgerDigest -and
        [string]$consumptionReadback.previousLedgerEntryDigest -ceq [string]$consumption.previousLedgerEntryDigest -and
        [string]$consumptionReadback.atomicCommitEvidenceRef -ceq [string]$consumption.atomicCommitEvidenceRef -and
        [string]$consumptionReadback.atomicCommitEvidenceDigest -ceq [string]$consumption.atomicCommitEvidenceDigest -and
        [string]$consumptionReadback.readerToolRef -ceq 'authorization-consumption-ledger-readback' -and
        [string]$consumptionReadback.readIdentityRef -cmatch '^private://' -and
        [string]$consumptionReadback.readIdentityRef -cne [string]$consumption.ledgerAuthorityIdentityRef -and
        [string]$consumptionReadback.observationArtifactRef -cmatch '^private://' -and
        (Test-Sha256Token $consumptionReadback.observationArtifactDigest) -and
        [string]$consumptionReadback.observationArtifactAttestationRef -cmatch '^private://' -and
        (Test-Sha256Token $consumptionReadback.observationArtifactAttestationDigest) -and
        [string]$consumptionReadback.observationArtifactAttestationStatus -ceq 'VERIFIED' -and
        ($consumptionReadback.maxAgeMinutes -is [int] -or $consumptionReadback.maxAgeMinutes -is [long]) -and
        [int64]$consumptionReadback.maxAgeMinutes -eq $readbackMaximumAge -and
        [string]$consumptionReadback.readbackPolicyRef -ceq [string]$authorization.independentReadbackPolicyRef -and
        [string]$consumptionReadback.readbackPolicyDigest -ceq [string]$authorization.independentReadbackPolicyDigest -and
        [string]$consumptionReadback.chainStatus -ceq 'PASS' -and
        [string]$consumptionReadback.replayStatus -ceq 'PASS' -and
        [string]$consumptionReadback.consistencyStatus -ceq 'PASS' -and
        [string]$package.contentDigest -ceq [string]$Operation.packageVerificationDigest -and
        [string]$package.status -ceq 'VERIFIED' -and
        [string]$package.packageDigest -ceq [string]$authorization.packageDigest -and
        [string]$package.sourceCommit -ceq [string]$Operation.sourceCommit -and
        $timesValid -and $planExpiresAt -gt $operationCompletedAt -and
        $authorizationIssuedAt -le $authorizationNotBefore -and
        $authorizationTtlPolicyApprovedAt -le $authorizationIssuedAt -and
        ($authorizationExpiresAt - $authorizationIssuedAt).TotalMinutes -le $authorizationTtlMaximumAge -and
        $authorizationRevocationPolicyApprovedAt -le $authorizationRevocationCheckedAt -and
        $authorizationRevocationCheckedAt -le $EvaluationTime -and
        ($EvaluationTime - $authorizationRevocationCheckedAt).TotalMinutes -le $authorizationRevocationMaximumAge -and
        $packageRevocationPolicyApprovedAt -le $packageRevocationCheckedAt -and
        $authorizationReadbackPolicyApprovedAt -le $consumedAt -and
        $authorizationNotBefore -le $workflowStartedAt -and $workflowStartedAt -le $consumedAt -and
        $authorizationRevocationCheckedAt -le $consumedAt -and
        $consumedAt -le $mutationStartedAt -and $mutationStartedAt -eq $operationStartedAt -and
        $writeCompletedAt -eq $operationCompletedAt -and $operationCompletedAt -lt $authorizationExpiresAt -and
        $operationCompletedAt -le $ledgerObservedAt -and $ledgerObservedAt -le $EvaluationTime -and
        ($EvaluationTime - $ledgerObservedAt).TotalMinutes -le $readbackMaximumAge -and
        $operationCompletedAt -le $EvaluationTime

    if (-not $chainValid) {
        Add-BlueprintError -Errors $Errors -Code 'AZURE_DEPLOYMENT_OPERATION_CHAIN_INVALID' -Message 'Azure deployment must resolve one exact pre-approved projection and a complete single-use authorization, atomic consumption, independent ledger observation, role-binding, package, tenant, environment, resource, and chronology chain.'
    }

    $azureCanonicalPrincipalIds = @()
    if ($null -ne $roleClosure) {
        $azureActors = @(
            [pscustomobject]@{ label='azure-write-identity'; alias=[string]$Operation.writeIdentityRef; requiredRole='ROLE_IAC_PLATFORM_OWNER' },
            [pscustomobject]@{ label='azure-apply-operator'; alias=[string]$Operation.applyOperatorIdentityRef; requiredRole='ROLE_IAC_APPLY_OPERATOR' },
            [pscustomobject]@{ label='authorization-issuer'; alias=[string]$authorization.issuedByPrincipalRef; requiredRole='ROLE_PROTECTED_ENVIRONMENT_APPROVER' },
            [pscustomobject]@{ label='ledger-authority'; alias=[string]$consumption.ledgerAuthorityIdentityRef; requiredRole='ROLE_AUTHORIZATION_LEDGER_OWNER' },
            [pscustomobject]@{ label='ledger-observer'; alias=[string]$consumptionReadback.readIdentityRef; requiredRole='ROLE_AUTHORIZATION_LEDGER_VERIFIER' },
            [pscustomobject]@{ label='package-signer'; alias=[string]$package.signerIdentityRef; requiredRole='ROLE_SUPPLY_CHAIN_OWNER' },
            [pscustomobject]@{ label='package-verifier'; alias=[string]$package.verifierIdentityRef; requiredRole='ROLE_SECURITY_APPROVER' },
            [pscustomobject]@{ label='role-binding-source'; alias=[string]$roleClosure.RoleBinding.sourceIdentityRef; requiredRole='ROLE_IAC_PLATFORM_OWNER' },
            [pscustomobject]@{ label='role-binding-reader'; alias=[string]$roleClosure.Readback.readIdentityRef; requiredRole='ROLE_DIRECTORY_READBACK_OWNER' },
            [pscustomobject]@{ label='role-binding-approver'; directPrincipal=$true; canonicalId=[string]$roleClosure.Approval.approverPrincipalRef; requiredRole='ROLE_IDENTITY_SECURITY_APPROVER' },
            [pscustomobject]@{ label='identity-root-operator'; directPrincipal=$true; canonicalId=[string]$roleClosure.RootAuthority.ceremonyOperatorIdentityRef; requiredRole='ROLE_IDENTITY_SECURITY_APPROVER' },
            [pscustomobject]@{ label='identity-root-reader'; directPrincipal=$true; canonicalId=[string]$roleClosure.RootAuthority.independentReadIdentityRef; requiredRole='ROLE_DIRECTORY_READBACK_OWNER' },
            [pscustomobject]@{ label='authorization-ttl-policy-approver'; directPrincipal=$true; canonicalId=[string]$authorizationTtlPolicy.approvedByPrincipalRef; requiredRole='ROLE_SECURITY_APPROVER' },
            [pscustomobject]@{ label='authorization-revocation-policy-approver'; directPrincipal=$true; canonicalId=[string]$authorizationRevocationPolicy.approvedByPrincipalRef; requiredRole='ROLE_SECURITY_APPROVER' },
            [pscustomobject]@{ label='package-revocation-policy-approver'; directPrincipal=$true; canonicalId=[string]$packageRevocationPolicy.approvedByPrincipalRef; requiredRole='ROLE_SECURITY_APPROVER' },
            [pscustomobject]@{ label='readback-policy-approver'; directPrincipal=$true; canonicalId=[string]$authorizationReadbackPolicy.approvedByPrincipalRef; requiredRole='ROLE_SECURITY_APPROVER' }
        )
        foreach ($keyBinding in @($roleClosure.RootAuthority.authorityKeyBindings)) {
            $azureActors += [pscustomobject]@{
                label = 'identity-root-key-custodian'
                directPrincipal = $true
                canonicalId = [string]$keyBinding.keyCustodianPrincipalId
            }
        }
        $azurePrincipalSet = [System.Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
        $azureRoleSetValid = $true
        foreach ($actor in $azureActors) {
            if ($actor.directPrincipal -eq $true) {
                $canonicalId = [string]$actor.canonicalId
                if ($canonicalId -cnotmatch '^private://canonical-principals/sha256/[0-9a-f]{64}$' -or
                    -not $azurePrincipalSet.Add($canonicalId)) { $azureRoleSetValid = $false }
                continue
            }
            if (-not $roleClosure.AliasMap.ContainsKey([string]$actor.alias) -or
                -not $roleClosure.RoleMap.ContainsKey([string]$actor.alias) -or
                [string]$roleClosure.RoleMap[[string]$actor.alias] -cne [string]$actor.requiredRole) {
                $azureRoleSetValid = $false
                continue
            }
            $canonicalId = [string]$roleClosure.AliasMap[[string]$actor.alias]
            if ($canonicalId -cnotmatch '^private://canonical-principals/sha256/[0-9a-f]{64}$' -or
                -not $azurePrincipalSet.Add($canonicalId)) { $azureRoleSetValid = $false }
        }
        if (-not $azureRoleSetValid) {
            Add-BlueprintError -Errors $Errors -Code 'AZURE_DEPLOYMENT_ROLE_BINDING_INVALID' -Message 'Every Azure deployment actor must resolve to its exact frozen semantic role and a distinct canonical principal.'
        }
        $azureCanonicalPrincipalIds = @($azurePrincipalSet)
    }

    if ($Errors.Count -gt $initialErrorCount) {
        Add-BlueprintError -Errors $Errors -Code 'AZURE_DEPLOYMENT_OPERATION_INVALID' -Message 'Azure deployment operation failed its complete fail-closed semantic gate.'
    }
    return [pscustomobject]@{
        Valid = ($Errors.Count -eq $initialErrorCount)
        RoleClosure = $roleClosure
        CanonicalPrincipalIds = @($azureCanonicalPrincipalIds)
    }
}

function Test-PackageVerificationBinding {
    param(
        [Parameter(Mandatory = $true)]$RecordMap,
        [Parameter(Mandatory = $true)]$Reference,
        [Parameter(Mandatory = $true)]$Digest,
        [Parameter(Mandatory = $true)][string]$ExpectedPackageDigest,
        [string]$ExpectedSourceCommit,
        [Parameter(Mandatory = $true)][string]$ExpectedRevocationFreshnessPolicyRef,
        [Parameter(Mandatory = $true)][string]$ExpectedRevocationFreshnessPolicyDigest,
        [Parameter(Mandatory = $true)][int64]$MaximumRevocationAgeMinutes,
        [Parameter(Mandatory = $true)][DateTimeOffset]$EvaluationTime,
        [Parameter(Mandatory = $true)][AllowEmptyCollection()][System.Collections.ArrayList]$Errors
    )

    $package = Resolve-CanonicalRecord -RecordMap $RecordMap -Reference $Reference -ExpectedTypes @('package-verification-record') -Context 'package verification' -Errors $Errors
    if ($null -eq $package) { return $null }
    Test-RequiredProperties -Object $package -Names @(
        'schemaVersion', 'recordStage', 'status', 'packageDigest', 'packageArtifactRef', 'sourceCommit',
        'signatureRef', 'signatureDigest', 'signatureStatus', 'signerIdentityRef',
        'timestampEvidenceRef', 'timestampEvidenceDigest', 'timestampAuthorityRef', 'timestampStatus', 'timestampedAt',
        'revocationEvidenceRef', 'revocationEvidenceDigest', 'certificateRevocationStatus', 'revocationCheckedAt',
        'packageRevocationFreshnessPolicyRef', 'packageRevocationFreshnessPolicyDigest',
        'packageRevocationCheckMaxAgeMinutes',
        'verificationToolRef', 'verifierIdentityRef', 'verifierRole',
        'verificationPolicyRef', 'verificationPolicyDigest', 'sbomRef', 'sbomDigest',
        'malwareScanRef', 'malwareScanDigest', 'malwareScanStatus',
        'diagnosticRedactionPolicyRef', 'diagnosticRedactionPolicyDigest', 'diagnosticRedactionStatus',
        'diagnosticDataClassification', 'verifiedAt', 'expiresAt'
    ) -Context 'package verification record' -Errors $Errors
    [DateTimeOffset]$verifiedAt = [DateTimeOffset]::MinValue
    [DateTimeOffset]$expiresAt = [DateTimeOffset]::MinValue
    [DateTimeOffset]$timestampedAt = [DateTimeOffset]::MinValue
    [DateTimeOffset]$revocationCheckedAt = [DateTimeOffset]::MinValue
    if ([string]$package.contentDigest -cne [string]$Digest -or
        [string]$package.schemaVersion -cne '1.0.0' -or [string]$package.recordStage -cne 'PACKAGE_VERIFICATION' -or
        [string]$package.status -cne 'VERIFIED' -or [string]$package.packageDigest -cne $ExpectedPackageDigest -or
        ((Test-ValuePresent $ExpectedSourceCommit) -and [string]$package.sourceCommit -cne $ExpectedSourceCommit) -or
        [string]$package.sourceCommit -cnotmatch '^[0-9a-f]{40}([0-9a-f]{24})?$' -or
        [string]$package.signatureStatus -cne 'VALID' -or
        [string]$package.timestampStatus -cne 'VALID' -or
        [string]$package.certificateRevocationStatus -cne 'GOOD' -or
        [string]$package.verificationToolRef -cne 'artifact-signing' -or
        [string]$package.verifierRole -cne 'ROLE_SECURITY_APPROVER' -or
        [string]$package.verifierIdentityRef -ceq [string]$package.signerIdentityRef -or
        [string]$package.malwareScanStatus -cne 'PASS' -or [string]$package.diagnosticRedactionStatus -cne 'PASS' -or
        [string]$package.diagnosticDataClassification -cnotin @('SAFE_SHAREABLE', 'RESTRICTED_INTERNAL') -or
        @('packageArtifactRef','signatureRef','signerIdentityRef','timestampEvidenceRef','timestampAuthorityRef','revocationEvidenceRef','verifierIdentityRef','verificationPolicyRef','sbomRef','malwareScanRef','diagnosticRedactionPolicyRef' | Where-Object { [string]$package.$_ -cnotmatch '^private://' }).Count -gt 0 -or
        @('signatureDigest','timestampEvidenceDigest','revocationEvidenceDigest','verificationPolicyDigest','sbomDigest','malwareScanDigest','diagnosticRedactionPolicyDigest' | Where-Object { -not (Test-Sha256Token $package.$_) }).Count -gt 0 -or
        -not [OperationsBlueprint.StrictRfc3339]::TryParse([string]$package.timestampedAt, [ref]$timestampedAt) -or
        -not [OperationsBlueprint.StrictRfc3339]::TryParse([string]$package.revocationCheckedAt, [ref]$revocationCheckedAt) -or
        -not [OperationsBlueprint.StrictRfc3339]::TryParse([string]$package.verifiedAt, [ref]$verifiedAt) -or
        -not [OperationsBlueprint.StrictRfc3339]::TryParse([string]$package.expiresAt, [ref]$expiresAt) -or
        $timestampedAt -gt $verifiedAt -or $revocationCheckedAt -gt $verifiedAt -or
        $verifiedAt -gt $EvaluationTime -or $expiresAt -le $EvaluationTime -or $expiresAt -le $verifiedAt) {
        Add-BlueprintError -Errors $Errors -Code 'PACKAGE_VERIFICATION_BINDING_INVALID' -Message 'Package verification must be current and bind the exact package, source commit, valid signature/timestamp/revocation evidence, independent verifier, policy, SBOM, malware result, and diagnostic-redaction result.'
    }
    if ([string]$package.packageRevocationFreshnessPolicyRef -cne $ExpectedRevocationFreshnessPolicyRef -or
        [string]$package.packageRevocationFreshnessPolicyDigest -cne $ExpectedRevocationFreshnessPolicyDigest -or
        ($package.packageRevocationCheckMaxAgeMinutes -isnot [int] -and $package.packageRevocationCheckMaxAgeMinutes -isnot [long]) -or
        [int64]$package.packageRevocationCheckMaxAgeMinutes -ne $MaximumRevocationAgeMinutes -or
        $MaximumRevocationAgeMinutes -lt 1 -or
        -not (Test-Sha256Token $package.packageRevocationFreshnessPolicyDigest) -or
        [string]$package.packageRevocationFreshnessPolicyRef -cnotmatch '^private://' -or
        $revocationCheckedAt -eq [DateTimeOffset]::MinValue -or
        ($EvaluationTime - $revocationCheckedAt).TotalMinutes -gt $MaximumRevocationAgeMinutes) {
        Add-BlueprintError -Errors $Errors -Code 'PACKAGE_REVOCATION_EVIDENCE_STALE_OR_POLICY_MISMATCH' -Message 'Package revocation evidence must match the frozen freshness policy and remain within its exact maximum age.'
    }
    return $package
}

function Test-RolloutMonitoringBinding {
    param(
        [Parameter(Mandatory = $true)]$Request,
        [Parameter(Mandatory = $true)]$Authorization,
        [Parameter(Mandatory = $true)]$RecordMap,
        $PlanRecord,
        $FinalVerdictRecord,
        $StopConditionsRecord,
        $RollbackRecord,
        $Registry,
        [Parameter(Mandatory = $true)][DateTimeOffset]$EvaluationTime,
        [ValidateSet('TEST', 'PRODUCTION')][string]$ValidationProfile = 'PRODUCTION',
        [Parameter(Mandatory = $true)][AllowEmptyCollection()][System.Collections.ArrayList]$Errors
    )

    $ValidationProfile = ([string]$ValidationProfile).ToUpperInvariant()
    if (-not (Test-ValuePresent $Request.rolloutMonitoringRef) -or
        -not (Test-ValuePresent $Request.rolloutMonitoringRecordDigest)) {
        Add-BlueprintError -Errors $Errors -Code 'ROLLOUT_MONITORING_REQUIRED' -Message 'Production activation requires a canonical rollout-monitoring record and exact digest.'
        return
    }
    if (-not (Test-Sha256Token $Request.rolloutMonitoringRecordDigest)) {
        Add-BlueprintError -Errors $Errors -Code 'ROLLOUT_MONITORING_DIGEST_INVALID' -Message 'rolloutMonitoringRecordDigest must be SHA-256.'
    }
    $monitor = Resolve-CanonicalRecord -RecordMap $RecordMap -Reference $Request.rolloutMonitoringRef -ExpectedTypes @('rollout-monitoring-record') -Context 'production rollout monitoring' -Errors $Errors
    if ($null -eq $monitor) { return }

    Test-RequiredProperties -Object $monitor -Names @(
        'schemaVersion', 'recordStage', 'status', 'manifestRef', 'manifestDigest', 'personaId',
        'semanticValidationRef', 'semanticValidationDigest', 'semanticInputDigest',
        'validatorReleaseRef', 'validatorReleaseDigest', 'semanticValidatedAt',
        'decisionClaimRef', 'decisionClaimDigest', 'renderManifestRef', 'renderManifestDigest',
        'decisionAction',
        'finalVerdictRef', 'finalVerdictDigest', 'fleetVerdictPointer', 'personaVerdictPointer', 'procurementEnvelopePointer',
        'sourceCommit', 'atmosRenderDigest', 'atmosStackRenderRef', 'atmosStackRenderDigest',
        'reviewedPlanRef', 'reviewedPlanDigest',
        'desiredStateRevision', 'packageDigest', 'packageVerificationRef', 'packageVerificationDigest',
        'targetRing', 'targetScopeRef', 'targetMembershipDigest', 'targetPopulation',
        'queryPackRef', 'queryPackDigest', 'queryPack', 'telemetryCohortRef', 'telemetryCohortDigest',
        'telemetryBaselineRef', 'telemetryBaselineDigest', 'coveragePolicyRef', 'coveragePolicyDigest',
        'thresholdPolicyRef', 'thresholdPolicyDigest', 'coverageFloors', 'signals',
        'primaryAlertRef', 'primaryAlertDigest', 'independentDeadmanRef', 'independentDeadmanDigest',
        'independentDeadmanOwnerRole', 'independentDeadmanCadenceMinutes',
        'stopConditionsRef', 'stopConditionsDigest', 'rollbackRef', 'rollbackDigest',
        'requalificationPlanRef', 'requalificationPlanDigest', 'requalificationTriggersPointer',
        'ownerRole', 'approvedAt', 'expiresAt'
    ) -Context 'rollout monitoring record' -Errors $Errors

    [DateTimeOffset]$monitorApprovedAt = [DateTimeOffset]::MinValue
    [DateTimeOffset]$monitorExpiresAt = [DateTimeOffset]::MinValue
    if ([string]$monitor.schemaVersion -cne '1.0.0' -or
        [string]$monitor.recordStage -cne 'PRODUCTION_ROLLOUT_MONITORING' -or
        [string]$monitor.status -cne 'APPROVED' -or
        -not [OperationsBlueprint.StrictRfc3339]::TryParse([string]$monitor.approvedAt, [ref]$monitorApprovedAt) -or
        -not [OperationsBlueprint.StrictRfc3339]::TryParse([string]$monitor.expiresAt, [ref]$monitorExpiresAt) -or
        $monitorApprovedAt -gt $EvaluationTime -or $monitorExpiresAt -le $EvaluationTime) {
        Add-BlueprintError -Errors $Errors -Code 'ROLLOUT_MONITORING_EXPIRED_OR_STALE' -Message 'Rollout monitoring must be an approved, non-future, unexpired production record.'
    }
    if ([string]$monitor.contentDigest -cne [string]$Request.rolloutMonitoringRecordDigest -or
        [string]$monitor.manifestRef -cne [string]$Request.manifestRef -or
        [string]$monitor.personaId -cne [string]$Request.personaId -or
        -not (Test-Sha256Token $monitor.manifestDigest) -or
        [string]$monitor.decisionAction -cnotin @('BUY', 'BUY_WITH_CONDITIONS') -or
        [string]$monitor.packageVerificationRef -cne [string]$Request.packageVerificationRef -or
        [string]$monitor.packageVerificationDigest -cne [string]$Request.packageVerificationDigest -or
        -not (Test-CanonicalValueEqual $monitor.targetPopulation $Request.targetPopulation)) {
        Add-BlueprintError -Errors $Errors -Code 'ROLLOUT_MONITORING_RECORD_MISMATCH' -Message 'Rollout monitoring digest, manifest, or persona differs from the production request.'
    }
    [DateTimeOffset]$monitorDirectoryReadbackAt = [DateTimeOffset]::MinValue
    if (-not [OperationsBlueprint.StrictRfc3339]::TryParse([string]$monitor.targetPopulation.directoryReadbackAt, [ref]$monitorDirectoryReadbackAt) -or
        $monitorDirectoryReadbackAt -gt $monitorApprovedAt) {
        Add-BlueprintError -Errors $Errors -Code 'ROLLOUT_MONITORING_TARGET_POPULATION_INVALID' -Message 'Rollout monitoring target population must be independently read before monitoring approval.'
    }

    $monitorManifest = Resolve-CanonicalRecord -RecordMap $RecordMap -Reference $monitor.manifestRef -ExpectedTypes @('candidate-manifest') -Context 'rollout manifest' -Errors $Errors
    if ($null -ne $monitorManifest -and [string]$monitorManifest.contentDigest -cne [string]$monitor.manifestDigest) {
        Add-BlueprintError -Errors $Errors -Code 'ROLLOUT_MONITORING_PROVENANCE_INCOMPLETE' -Message 'Rollout monitoring manifest digest differs from the canonical candidate manifest.'
    }
    $semanticRecord = Resolve-CanonicalRecord -RecordMap $RecordMap -Reference $monitor.semanticValidationRef -ExpectedTypes @('semantic-validation-record') -Context 'rollout semantic validation' -Errors $Errors
    $decisionRecord = Resolve-CanonicalRecord -RecordMap $RecordMap -Reference $monitor.decisionClaimRef -ExpectedTypes @('decision-claim-record') -Context 'rollout decision claim' -Errors $Errors
    $renderManifestRecord = Resolve-CanonicalRecord -RecordMap $RecordMap -Reference $monitor.renderManifestRef -ExpectedTypes @('render-manifest-record') -Context 'leadership render manifest' -Errors $Errors
    $monitorAtmosStackRender = Resolve-CanonicalRecord -RecordMap $RecordMap -Reference $monitor.atmosStackRenderRef -ExpectedTypes @('atmos-stack-render-record') -Context 'rollout Atmos stack render' -Errors $Errors
    if ($null -eq $monitorAtmosStackRender -or
        ($null -ne $monitorAtmosStackRender -and
            ([string]$monitorAtmosStackRender.contentDigest -cne [string]$monitor.atmosStackRenderDigest -or
             [string]$monitorAtmosStackRender.sourceCommit -cne [string]$monitor.sourceCommit -or
             [string]$monitorAtmosStackRender.renderedOutputDigest -cne [string]$monitor.atmosRenderDigest))) {
        Add-BlueprintError -Errors $Errors -Code 'ROLLOUT_ATMOS_STACK_RENDER_MISMATCH' -Message 'Rollout monitoring must bind the exact verified Atmos source commit and rendered output digest.'
    }
    if ($null -ne $semanticRecord) {
        Test-RequiredProperties -Object $semanticRecord -Names @(
            'inputDigest', 'validatorReleaseRef', 'validatorReleaseDigest', 'validationResultDigest',
            'sourceRecordSetDigest', 'sourceRecordRefs', 'validationResult', 'validatedAt',
            'evaluationTime', 'expiresAt'
        ) -Context 'rollout semantic validation' -Errors $Errors
        [string[]]$semanticSourceRefs = @()
        if (@($semanticRecord.sourceRecordRefs).Count -gt 0) {
            $semanticSourceRefs = [string[]]@($semanticRecord.sourceRecordRefs)
            [Array]::Sort($semanticSourceRefs, [StringComparer]::Ordinal)
        }
        $expectedSourceSetDigest = Get-CanonicalPayloadDigest -Payload ([pscustomobject]@{ sourceRecordRefs = @($semanticSourceRefs) })
        $expectedSemanticValidationResultDigest = Get-SemanticValidationResultDigest -SemanticRecord $semanticRecord
        [DateTimeOffset]$semanticValidatedAt = [DateTimeOffset]::MinValue
        [DateTimeOffset]$semanticEvaluationTime = [DateTimeOffset]::MinValue
        [DateTimeOffset]$semanticExpiresAt = [DateTimeOffset]::MinValue
        if ([string]$semanticRecord.contentDigest -cne [string]$monitor.semanticValidationDigest -or
            [string]$semanticRecord.validationResult -cne 'PASS' -or
            [string]$semanticRecord.inputDigest -cne [string]$monitor.semanticInputDigest -or
            [string]$semanticRecord.validatorReleaseRef -cne [string]$monitor.validatorReleaseRef -or
            [string]$semanticRecord.validatorReleaseDigest -cne [string]$monitor.validatorReleaseDigest -or
            [string]$semanticRecord.validatorReleaseDigest -cne 'sha256:b4fdd5765b3d850a296a2948e50d17c6f5b457316adbe903dc13894a9bf66466' -or
            [string]$semanticRecord.validationResultDigest -cne [string]$expectedSemanticValidationResultDigest -or
            [string]$semanticRecord.sourceRecordSetDigest -cne [string]$expectedSourceSetDigest -or
            @($semanticRecord.sourceRecordRefs).Count -eq 0 -or
            @($semanticRecord.sourceRecordRefs | Group-Object -CaseSensitive | Where-Object Count -gt 1).Count -gt 0 -or
            -not [OperationsBlueprint.StrictRfc3339]::TryParse([string]$semanticRecord.validatedAt, [ref]$semanticValidatedAt) -or
            -not [OperationsBlueprint.StrictRfc3339]::TryParse([string]$semanticRecord.evaluationTime, [ref]$semanticEvaluationTime) -or
            -not [OperationsBlueprint.StrictRfc3339]::TryParse([string]$semanticRecord.expiresAt, [ref]$semanticExpiresAt) -or
            [string]$semanticRecord.validatedAt -cne [string]$monitor.semanticValidatedAt -or
            $semanticEvaluationTime -gt $semanticValidatedAt -or $semanticValidatedAt -gt $monitorApprovedAt -or
            $semanticExpiresAt -le $EvaluationTime) {
            Add-BlueprintError -Errors $Errors -Code 'ROLLOUT_MONITORING_PROVENANCE_INCOMPLETE' -Message 'Rollout monitoring does not bind a current PASS semantic release, exact validator release, source-record closure, evaluation time, and input digest.'
        }
        foreach ($sourceRef in @($semanticRecord.sourceRecordRefs)) {
            $sourceId = ([string]$sourceRef).Split('#', 2)[0]
            $sourceTypes = if ($RecordMap.ContainsKey($sourceId)) { @([string]$RecordMap[$sourceId].recordType) } else { @('unresolved-semantic-source') }
            [void](Resolve-CanonicalRecord -RecordMap $RecordMap -Reference $sourceRef `
                -ExpectedTypes $sourceTypes `
                -Context 'semantic source-record closure' -Errors $Errors)
        }
        foreach ($requiredSemanticSourceRef in @([string]$monitor.manifestRef, [string]$monitor.finalVerdictRef)) {
            if (@($semanticRecord.sourceRecordRefs) -cnotcontains $requiredSemanticSourceRef) {
                Add-BlueprintError -Errors $Errors -Code 'ROLLOUT_MONITORING_PROVENANCE_INCOMPLETE' -Message 'Semantic source-record closure omits the required manifest or verdict record.'
            }
        }
    }
    if ($null -ne $decisionRecord -and $null -ne $FinalVerdictRecord) {
        $procurementDigest = Get-CanonicalPayloadDigest -Payload $FinalVerdictRecord.procurementEnvelope
        if ([string]$decisionRecord.contentDigest -cne [string]$monitor.decisionClaimDigest -or
            [string]$decisionRecord.sourceVerdictRef -cne [string]$monitor.finalVerdictRef -or
            [string]$decisionRecord.personaId -cne [string]$Request.personaId -or
            [string]$decisionRecord.decisionAction -cne [string]$monitor.decisionAction -or
            [string]$decisionRecord.procurementEnvelopeDigest -cne [string]$procurementDigest -or
            [string]$decisionRecord.semanticValidationRef -cne [string]$monitor.semanticValidationRef -or
            [string]$decisionRecord.semanticValidationDigest -cne [string]$monitor.semanticValidationDigest -or
            [string]$decisionRecord.semanticInputDigest -cne [string]$monitor.semanticInputDigest -or
            $decisionRecord.manualOverrideAllowed -ne $false -or
            [string]$decisionRecord.renderedStatementDigest -cne (Get-CanonicalPayloadDigest -Payload ([string]$decisionRecord.renderedStatement))) {
            Add-BlueprintError -Errors $Errors -Code 'ROLLOUT_MONITORING_DECISION_BINDING_MISMATCH' -Message 'Rollout monitoring decision claim differs from the exact final verdict, persona, or procurement envelope.'
        }
    }
    if ($null -ne $renderManifestRecord) {
        $renderManifestFields = @(
            'schemaVersion', 'recordStage', 'status', 'semanticValidationRef', 'semanticValidationDigest',
            'semanticInputDigest', 'claimChainRef', 'claimChainDigest', 'decisionClaimRef',
            'decisionClaimDigest', 'sourceRecordBindings', 'sourceRecordSetDigest', 'rendererToolRef',
            'rendererVersion', 'rendererReleaseRef', 'rendererReleaseDigest', 'templateRef',
            'templateVersion', 'templateDigest', 'renderMode', 'manualOverrideAllowed',
            'outputArtifactRef', 'outputArtifactDigest', 'outputArtifactAttestationRef',
            'outputArtifactAttestationDigest', 'outputFormat', 'encoding', 'safeLinkPolicyRef',
            'safeLinkPolicyDigest', 'privacyReleaseRef', 'privacyReleaseDigest', 'securityTestRef',
            'securityTestDigest', 'securityTestStatus', 'generatedByIdentityRef', 'generatedAt'
        )
        Test-RequiredProperties -Object $renderManifestRecord -Names $renderManifestFields -Context 'leadership render manifest' -Errors $Errors
        $sourceBindings = @($renderManifestRecord.sourceRecordBindings)
        $renderSourceBindingsValid = $sourceBindings.Count -gt 0 -and
            @($sourceBindings | Group-Object -Property recordRef -CaseSensitive | Where-Object Count -gt 1).Count -eq 0
        $canonicalRenderBindings = New-Object System.Collections.ArrayList
        foreach ($sourceBinding in $sourceBindings) {
            Test-RequiredProperties -Object $sourceBinding -Names @('recordRef', 'contentDigest') -Context 'render source-record binding' -Errors $Errors
            $sourceRecord = Resolve-CanonicalRecord -RecordMap $RecordMap -Reference $sourceBinding.recordRef `
                -ExpectedTypes @('candidate-manifest','test-plan','threshold-policy','evidence-record','evidence-release','distribution-record','verdict-record','fleet-portfolio-record','business-impact-record','commercial-quote-record','cohort-record','platform-baseline-record') `
                -Context 'render source-record binding' -Errors $Errors
            if ($null -eq $sourceRecord -or [string]$sourceRecord.contentDigest -cne [string]$sourceBinding.contentDigest) {
                $renderSourceBindingsValid = $false
            }
            [void]$canonicalRenderBindings.Add([pscustomobject][ordered]@{
                recordRef = [string]$sourceBinding.recordRef
                contentDigest = [string]$sourceBinding.contentDigest
            })
        }
        $renderBindingMap = [System.Collections.Generic.Dictionary[string,object]]::new([StringComparer]::Ordinal)
        foreach ($canonicalBinding in @($canonicalRenderBindings)) {
            if (-not $renderBindingMap.ContainsKey([string]$canonicalBinding.recordRef)) {
                [void]$renderBindingMap.Add([string]$canonicalBinding.recordRef, $canonicalBinding)
            }
        }
        [string[]]$sortedRenderRefs = @($renderBindingMap.Keys)
        [Array]::Sort($sortedRenderRefs, [StringComparer]::Ordinal)
        $sortedCanonicalRenderBindings = @($sortedRenderRefs | ForEach-Object { $renderBindingMap[[string]$_] })
        $expectedRenderSourceSetDigest = Get-CanonicalPayloadDigest -Payload ([pscustomobject]@{
            sourceRecordBindings = @($sortedCanonicalRenderBindings)
        })
        if ($null -eq $semanticRecord -or $sourceBindings.Count -ne @($semanticRecord.sourceRecordRefs).Count) {
            $renderSourceBindingsValid = $false
        }
        elseif ($null -ne $semanticRecord) {
            foreach ($semanticSourceRef in @($semanticRecord.sourceRecordRefs)) {
                if (@($sourceBindings | Where-Object { [string]$_.recordRef -ceq [string]$semanticSourceRef }).Count -ne 1) {
                    $renderSourceBindingsValid = $false
                }
            }
        }
        [DateTimeOffset]$renderGeneratedAt = [DateTimeOffset]::MinValue
        [DateTimeOffset]$decisionRenderedAt = [DateTimeOffset]::MinValue
        $renderGeneratedTimeValid = [OperationsBlueprint.StrictRfc3339]::TryParse([string]$renderManifestRecord.generatedAt, [ref]$renderGeneratedAt)
        $decisionRenderedTimeValid = $null -ne $decisionRecord -and
            [OperationsBlueprint.StrictRfc3339]::TryParse([string]$decisionRecord.renderedAt, [ref]$decisionRenderedAt)
        if ([string]$renderManifestRecord.contentDigest -cne [string]$monitor.renderManifestDigest -or
            [string]$renderManifestRecord.schemaVersion -cne '1.0.0' -or
            [string]$renderManifestRecord.recordStage -cne 'LEADERSHIP_RENDER_MANIFEST' -or
            [string]$renderManifestRecord.status -cne 'ISSUED' -or
            [string]$renderManifestRecord.semanticValidationRef -cne [string]$monitor.semanticValidationRef -or
            [string]$renderManifestRecord.semanticValidationDigest -cne [string]$monitor.semanticValidationDigest -or
            [string]$renderManifestRecord.semanticInputDigest -cne [string]$monitor.semanticInputDigest -or
            [string]$renderManifestRecord.decisionClaimRef -cne [string]$monitor.decisionClaimRef -or
            [string]$renderManifestRecord.decisionClaimDigest -cne [string]$monitor.decisionClaimDigest -or
            [string]$renderManifestRecord.sourceRecordSetDigest -cne [string]$expectedRenderSourceSetDigest -or
            -not $renderSourceBindingsValid -or
            [string]$renderManifestRecord.rendererToolRef -cne 'decision-packet-renderer' -or
            -not (Test-NonBlankString $renderManifestRecord.rendererVersion) -or
            -not (Test-NonBlankString $renderManifestRecord.templateVersion) -or
            [string]$renderManifestRecord.renderMode -cne 'DETERMINISTIC_FROM_CANONICAL_RECORDS' -or
            $renderManifestRecord.manualOverrideAllowed -ne $false -or
            [string]$renderManifestRecord.outputFormat -cnotin @('PDF','HTML','MARKDOWN','JSON') -or
            [string]$renderManifestRecord.encoding -cne 'UTF-8' -or
            [string]$renderManifestRecord.securityTestStatus -cne 'PASS' -or
            @('claimChainRef','rendererReleaseRef','templateRef','outputArtifactRef','outputArtifactAttestationRef','safeLinkPolicyRef','privacyReleaseRef','securityTestRef','generatedByIdentityRef' | Where-Object { [string]$renderManifestRecord.$_ -cnotmatch '^private://' }).Count -gt 0 -or
            @('claimChainDigest','rendererReleaseDigest','templateDigest','outputArtifactDigest','outputArtifactAttestationDigest','safeLinkPolicyDigest','privacyReleaseDigest','securityTestDigest' | Where-Object { -not (Test-Sha256Token $renderManifestRecord.$_) }).Count -gt 0 -or
            [string]$renderManifestRecord.generatedByIdentityRef -ceq [string]$Request.writeIdentityRef -or
            -not $renderGeneratedTimeValid -or -not $decisionRenderedTimeValid -or
            $renderGeneratedAt -lt $decisionRenderedAt -or $renderGeneratedAt -gt $monitorApprovedAt) {
            Add-BlueprintError -Errors $Errors -Code 'RENDER_MANIFEST_BINDING_INVALID' -Message 'Leadership render manifest must bind the exact semantic release, decision, source-record set, renderer/template, immutable output attestation, safe-link/privacy/security controls, and deterministic generation chronology.'
        }
        if ([string]$ValidationProfile -ceq 'PRODUCTION') {
            Add-BlueprintError -Errors $Errors -Code 'RENDER_OUTPUT_ATTESTATION_PRIVATE_VERIFICATION_REQUIRED' -Message 'The public validator cannot retrieve the private rendered artifact and trusted attestation bytes needed to recompute its output digest; production remains HOLD.'
        }
    }
    if ([string]$monitor.finalVerdictRef -cne [string]$Authorization.finalVerdictRef -or
        ($null -ne $FinalVerdictRecord -and [string]$monitor.finalVerdictDigest -cne [string]$FinalVerdictRecord.contentDigest) -or
        [string]$monitor.fleetVerdictPointer -cne ([string]$Authorization.finalVerdictRef + '#/fleetVerdict') -or
        -not ([string]$monitor.personaVerdictPointer).StartsWith(([string]$Authorization.finalVerdictRef + '#/personaVerdicts/'), [System.StringComparison]::Ordinal) -or
        [string]$monitor.procurementEnvelopePointer -cne [string]$Authorization.procurementEnvelopeRef -or
        [string]$monitor.requalificationTriggersPointer -cne ([string]$Authorization.finalVerdictRef + '#/requalificationTriggers')) {
        Add-BlueprintError -Errors $Errors -Code 'ROLLOUT_MONITORING_VERDICT_BINDING_MISMATCH' -Message 'Rollout monitoring verdict, persona, procurement, or requalification pointers differ from the authorized Phase 5 decision.'
    }
    elseif ($null -ne $FinalVerdictRecord) {
        $personaPointerPath = ([string]$monitor.personaVerdictPointer).Split('#', 2)[1]
        $personaPointerFound = $false
        $monitoredPersonaVerdict = Get-JsonPointerValue -Document $FinalVerdictRecord.payload -Pointer $personaPointerPath -Found ([ref]$personaPointerFound)
        if (-not $personaPointerFound -or $monitoredPersonaVerdict -isnot [pscustomobject] -or
            [string]$monitoredPersonaVerdict.persona -cne [string]$Request.personaId -or
            [string]$monitoredPersonaVerdict.verdict -cnotin @('QUALIFY', 'QUALIFY_WITH_CONDITIONS') -or
            [string]$FinalVerdictRecord.procurementDisposition -cnotin @('APPROVED', 'APPROVED_WITH_CONDITIONS')) {
            Add-BlueprintError -Errors $Errors -Code 'ROLLOUT_MONITORING_VERDICT_BINDING_MISMATCH' -Message 'Rollout monitoring does not resolve to the deployable selected persona and procurement disposition.'
        }
        else {
            $expectedDecision = Get-ExpectedRecommendation -VerdictPayload $FinalVerdictRecord.payload -PersonaVerdict $monitoredPersonaVerdict -VerdictRef ([string]$monitor.finalVerdictRef)
            if ([string]$expectedDecision.Action -cnotin @('BUY', 'BUY_WITH_CONDITIONS') -or
                [string]$monitor.decisionAction -cne [string]$expectedDecision.Action -or
                ($null -ne $decisionRecord -and
                    ([string]$decisionRecord.decisionAction -cne [string]$expectedDecision.Action -or
                     [string]$decisionRecord.renderedStatement -cne [string]$expectedDecision.Statement))) {
                Add-BlueprintError -Errors $Errors -Code 'ROLLOUT_MONITORING_DECISION_NOT_DETERMINISTIC' -Message 'Production rollout must use the exact deterministic BUY or BUY_WITH_CONDITIONS action and statement derived from the selected verdict.'
            }
        }
    }

    if ($null -ne $PlanRecord) {
        if ([string]$monitor.reviewedPlanRef -cne [string]$Request.reviewedPlanRef -or
            [string]$monitor.reviewedPlanDigest -cne [string]$Request.reviewedPlanDigest -or
            [string]$monitor.sourceCommit -cne [string]$PlanRecord.sourceCommit -or
            [string]$monitor.atmosRenderDigest -cne [string]$PlanRecord.atmosRenderDigest -or
            [string]$monitor.atmosStackRenderRef -cne [string]$PlanRecord.atmosStackRenderRef -or
            [string]$monitor.atmosStackRenderDigest -cne [string]$PlanRecord.atmosStackRenderDigest -or
            [string]$monitor.desiredStateRevision -cne [string]$Request.desiredStateRevision -or
            [string]$monitor.packageDigest -cne [string]$Request.packageDigest -or
            [string]$monitor.packageVerificationRef -cne [string]$Request.packageVerificationRef -or
            [string]$monitor.packageVerificationDigest -cne [string]$Request.packageVerificationDigest -or
            [string]$monitor.targetRing -cne [string]$Request.targetRing -or
            [string]$monitor.targetScopeRef -cne [string]$Request.targetScopeRef -or
            [string]$monitor.targetMembershipDigest -cne [string]$Request.targetMembershipDigest -or
            -not (Test-CanonicalValueEqual $monitor.targetPopulation $Request.targetPopulation) -or
            [string]$monitor.sourceCommit -cnotmatch '^[0-9a-f]{40}([0-9a-f]{24})?$' -or
            -not (Test-Sha256Token $monitor.atmosRenderDigest)) {
            Add-BlueprintError -Errors $Errors -Code 'ROLLOUT_MONITORING_PLAN_BINDING_MISMATCH' -Message 'Rollout monitoring must bind the exact reviewed Git, Atmos, Terraform, package, ring, scope, and membership inputs.'
        }
    }

    $typedQueryPack = Resolve-CanonicalRecord -RecordMap $RecordMap -Reference $monitor.queryPackRef -ExpectedTypes @('query-pack-record') -Context 'rollout typed query pack' -Errors $Errors
    Test-RequiredProperties -Object $monitor.queryPack -Names @('artifactRef', 'digest', 'version', 'sourceToolRefs', 'metricIds') -Context 'rollout monitoring query pack' -Errors $Errors
    $querySources = @($monitor.queryPack.sourceToolRefs)
    $queryMetrics = @($monitor.queryPack.metricIds)
    if ([string]$monitor.queryPack.artifactRef -cnotmatch '^private://' -or
        -not (Test-Sha256Token $monitor.queryPack.digest) -or
        -not (Test-ValuePresent $monitor.queryPack.version) -or $queryMetrics.Count -eq 0 -or
        @($querySources | Group-Object -CaseSensitive | Where-Object Count -gt 1).Count -gt 0 -or
        @($queryMetrics | Group-Object -CaseSensitive | Where-Object Count -gt 1).Count -gt 0) {
        Add-BlueprintError -Errors $Errors -Code 'ROLLOUT_MONITORING_QUERY_PACK_INVALID' -Message 'The telemetry query pack must be private, versioned, SHA-256 bound, and contain unique sources and metrics.'
    }
    if ($null -ne $typedQueryPack) {
        Test-RequiredProperties -Object $typedQueryPack -Names @(
            'schemaVersion','recordStage','status','artifactRef','digest','version','sourceToolRefs','metricIds','ownerRole','approvedAt','expiresAt'
        ) -Context 'rollout typed query pack' -Errors $Errors
        [DateTimeOffset]$queryApprovedAt = [DateTimeOffset]::MinValue
        [DateTimeOffset]$queryExpiresAt = [DateTimeOffset]::MinValue
        if ([string]$typedQueryPack.contentDigest -cne [string]$monitor.queryPackDigest -or
            [string]$typedQueryPack.schemaVersion -cne '1.0.0' -or [string]$typedQueryPack.recordStage -cne 'TELEMETRY_QUERY_PACK' -or
            [string]$typedQueryPack.status -cne 'APPROVED' -or
            [string]$typedQueryPack.artifactRef -cne [string]$monitor.queryPack.artifactRef -or
            [string]$typedQueryPack.digest -cne [string]$monitor.queryPack.digest -or
            [string]$typedQueryPack.version -cne [string]$monitor.queryPack.version -or
            -not (Test-CanonicalValueEqual @($typedQueryPack.sourceToolRefs) @($monitor.queryPack.sourceToolRefs)) -or
            -not (Test-CanonicalValueEqual @($typedQueryPack.metricIds) @($monitor.queryPack.metricIds)) -or
            -not [OperationsBlueprint.StrictRfc3339]::TryParse([string]$typedQueryPack.approvedAt, [ref]$queryApprovedAt) -or
            -not [OperationsBlueprint.StrictRfc3339]::TryParse([string]$typedQueryPack.expiresAt, [ref]$queryExpiresAt) -or
            $queryApprovedAt -gt $monitorApprovedAt -or $queryExpiresAt -le $EvaluationTime) {
            Add-BlueprintError -Errors $Errors -Code 'ROLLOUT_MONITORING_TYPED_DEPENDENCY_MISMATCH' -Message 'Rollout query pack does not resolve to the exact current typed artifact, digest, version, source, and metric set.'
        }
    }
    $requiredMonitoringSources = @('systrack', 'microsoft-graph-readback')
    foreach ($sourceToolRef in $requiredMonitoringSources) {
        if ($querySources -cnotcontains $sourceToolRef) {
            Add-BlueprintError -Errors $Errors -Code 'ROLLOUT_MONITORING_SOURCE_SET_INCOMPLETE' -Message "Rollout monitoring query pack omits $sourceToolRef."
        }
    }
    $registryToolIds = if ($null -ne $Registry) { @($Registry.bindings | ForEach-Object { [string]$_.toolId }) } else { @() }
    foreach ($sourceToolRef in $querySources) {
        if ($registryToolIds -cnotcontains [string]$sourceToolRef) {
            Add-BlueprintError -Errors $Errors -Code 'ROLLOUT_MONITORING_SOURCE_SET_INCOMPLETE' -Message "Rollout monitoring references unknown tool $sourceToolRef."
        }
    }

    $telemetryCohort = Resolve-CanonicalRecord -RecordMap $RecordMap -Reference $monitor.telemetryCohortRef -ExpectedTypes @('cohort-record') -Context 'rollout telemetry cohort' -Errors $Errors
    $telemetryBaseline = Resolve-CanonicalRecord -RecordMap $RecordMap -Reference $monitor.telemetryBaselineRef -ExpectedTypes @('telemetry-baseline-record') -Context 'rollout telemetry baseline' -Errors $Errors
    $coveragePolicy = Resolve-CanonicalRecord -RecordMap $RecordMap -Reference $monitor.coveragePolicyRef -ExpectedTypes @('coverage-policy-record') -Context 'rollout coverage policy' -Errors $Errors
    $monitorThresholdPolicy = Resolve-CanonicalRecord -RecordMap $RecordMap -Reference $monitor.thresholdPolicyRef -ExpectedTypes @('threshold-policy') -Context 'rollout threshold policy' -Errors $Errors
    if ($null -ne $telemetryBaseline) {
        Test-RequiredProperties -Object $telemetryBaseline -Names @(
            'schemaVersion','recordStage','status','cohortRef','cohortDigest','queryPackRef','queryPackDigest',
            'thresholdPolicyRef','thresholdPolicyDigest','evidenceReleaseRef','evidenceReleaseDigest',
            'coverageStatus','observedAt','freshnessBinding'
        ) -Context 'rollout telemetry baseline' -Errors $Errors
        [DateTimeOffset]$baselineObservedAt = [DateTimeOffset]::MinValue
        $baselineEvidenceRelease = Resolve-CanonicalRecord -RecordMap $RecordMap -Reference $telemetryBaseline.evidenceReleaseRef -ExpectedTypes @('evidence-release') -Context 'rollout baseline evidence release' -Errors $Errors
        if ([string]$telemetryBaseline.contentDigest -cne [string]$monitor.telemetryBaselineDigest -or
            [string]$telemetryBaseline.schemaVersion -cne '1.0.0' -or [string]$telemetryBaseline.recordStage -cne 'TELEMETRY_BASELINE' -or
            [string]$telemetryBaseline.status -cne 'ISSUED' -or
            [string]$telemetryBaseline.cohortRef -cne [string]$monitor.telemetryCohortRef -or
            [string]$telemetryBaseline.cohortDigest -cne [string]$monitor.telemetryCohortDigest -or
            ($null -ne $telemetryCohort -and [string]$telemetryCohort.contentDigest -cne [string]$monitor.telemetryCohortDigest) -or
            [string]$telemetryBaseline.queryPackRef -cne [string]$monitor.queryPackRef -or
            [string]$telemetryBaseline.queryPackDigest -cne [string]$monitor.queryPackDigest -or
            [string]$telemetryBaseline.thresholdPolicyRef -cne [string]$monitor.thresholdPolicyRef -or
            [string]$telemetryBaseline.thresholdPolicyDigest -cne [string]$monitor.thresholdPolicyDigest -or
            ($null -ne $baselineEvidenceRelease -and [string]$baselineEvidenceRelease.contentDigest -cne [string]$telemetryBaseline.evidenceReleaseDigest) -or
            [string]$telemetryBaseline.coverageStatus -cne 'PASS' -or
            -not [OperationsBlueprint.StrictRfc3339]::TryParse([string]$telemetryBaseline.observedAt, [ref]$baselineObservedAt) -or
            $baselineObservedAt -gt $monitorApprovedAt) {
            Add-BlueprintError -Errors $Errors -Code 'ROLLOUT_MONITORING_BASELINE_INVALID' -Message 'Rollout telemetry baseline must be the exact current typed cohort/query/policy/evidence binding observed before monitoring approval.'
        }

        $baselineFreshness = $telemetryBaseline.freshnessBinding
        $baselineFreshnessValid = $baselineFreshness -is [pscustomobject]
        if ($baselineFreshnessValid) {
            Test-RequiredProperties -Object $baselineFreshness -Names @(
                'observedAt','admittedAt','policyRef','maxAgeDays','dependencySnapshotRef',
                'dependencySnapshotDigest','dependencyStatus'
            ) -Context 'rollout telemetry-baseline freshness binding' -Errors $Errors
            [DateTimeOffset]$freshnessObservedAt = [DateTimeOffset]::MinValue
            [DateTimeOffset]$freshnessAdmittedAt = [DateTimeOffset]::MinValue
            $freshnessTimesValid = [OperationsBlueprint.StrictRfc3339]::TryParse([string]$baselineFreshness.observedAt, [ref]$freshnessObservedAt) -and
                [OperationsBlueprint.StrictRfc3339]::TryParse([string]$baselineFreshness.admittedAt, [ref]$freshnessAdmittedAt)
            $freshnessMaxAgeValid = ($baselineFreshness.maxAgeDays -is [int] -or $baselineFreshness.maxAgeDays -is [long])
            if ($freshnessMaxAgeValid) {
                $freshnessMaxAgeValid = [int64]$baselineFreshness.maxAgeDays -ge 1 -and
                    [int64]$baselineFreshness.maxAgeDays -le 3650
            }
            [int64]$effectiveFreshnessMaxAgeDays = if ($freshnessMaxAgeValid) {
                [int64]$baselineFreshness.maxAgeDays
            }
            else { 1 }

            $freshnessPolicy = Resolve-CanonicalRecord -RecordMap $RecordMap -Reference $baselineFreshness.policyRef `
                -ExpectedTypes @('threshold-policy') -Context 'rollout telemetry-baseline freshness policy' -Errors $Errors
            $freshnessDependency = Resolve-CanonicalRecord -RecordMap $RecordMap -Reference $baselineFreshness.dependencySnapshotRef `
                -ExpectedTypes @('candidate-manifest','platform-baseline-record') -Context 'rollout telemetry-baseline dependency snapshot' -Errors $Errors
            $policyParts = ([string]$baselineFreshness.policyRef).Split('#', 2)
            $policyValueFound = $false
            $policyValue = if ($null -ne $freshnessPolicy -and $policyParts.Count -eq 2) {
                Get-JsonPointerValue -Document $freshnessPolicy.payload -Pointer $policyParts[1] -Found ([ref]$policyValueFound)
            }
            else { $null }
            $dependencyParts = ([string]$baselineFreshness.dependencySnapshotRef).Split('#', 2)
            $dependencyValueFound = $false
            $dependencyValue = if ($null -ne $freshnessDependency -and $dependencyParts.Count -eq 2) {
                Get-JsonPointerValue -Document $freshnessDependency.payload -Pointer $dependencyParts[1] -Found ([ref]$dependencyValueFound)
            }
            else { $null }
            $policyAgeMatches = $policyValueFound -and
                ($policyValue -is [int] -or $policyValue -is [long]) -and
                $freshnessMaxAgeValid -and [int64]$policyValue -eq $effectiveFreshnessMaxAgeDays
            $dependencyDigestMatches = $dependencyValueFound -and
                (Test-Sha256Token $baselineFreshness.dependencySnapshotDigest) -and
                (Get-CanonicalPayloadDigest -Payload $dependencyValue) -ceq [string]$baselineFreshness.dependencySnapshotDigest
            $baselineFreshnessValid = $freshnessTimesValid -and $freshnessMaxAgeValid -and
                $freshnessObservedAt -eq $baselineObservedAt -and
                $freshnessObservedAt -le $freshnessAdmittedAt -and
                $freshnessAdmittedAt -le $monitorApprovedAt -and
                $freshnessAdmittedAt -le $EvaluationTime -and
                ($EvaluationTime - $freshnessObservedAt).TotalDays -le $effectiveFreshnessMaxAgeDays -and
                [string]$baselineFreshness.dependencyStatus -ceq 'MATCH' -and
                $null -ne $freshnessPolicy -and
                [string]$freshnessPolicy.recordId -ceq ([string]$monitor.thresholdPolicyRef).Split('#', 2)[0] -and
                $policyAgeMatches -and $dependencyDigestMatches
        }
        if (-not $baselineFreshnessValid) {
            Add-BlueprintError -Errors $Errors -Code 'ROLLOUT_MONITORING_BASELINE_FRESHNESS_INVALID' -Message 'Rollout telemetry baseline freshness must resolve its exact threshold-policy age and dependency snapshot, remain MATCH, and satisfy observation, admission, approval, and evaluation chronology.'
        }
    }
    if ($null -ne $coveragePolicy) {
        Test-RequiredProperties -Object $coveragePolicy -Names @('schemaVersion','recordStage','status','thresholdPolicyRef','thresholdPolicyDigest','sourceFloors','ownerRole','approvedAt','expiresAt') -Context 'rollout coverage policy' -Errors $Errors
        [DateTimeOffset]$coverageApprovedAt = [DateTimeOffset]::MinValue
        [DateTimeOffset]$coverageExpiresAt = [DateTimeOffset]::MinValue
        if ([string]$coveragePolicy.contentDigest -cne [string]$monitor.coveragePolicyDigest -or
            [string]$coveragePolicy.schemaVersion -cne '1.0.0' -or [string]$coveragePolicy.recordStage -cne 'COVERAGE_POLICY' -or
            [string]$coveragePolicy.status -cne 'APPROVED' -or
            [string]$coveragePolicy.thresholdPolicyRef -cne [string]$monitor.thresholdPolicyRef -or
            [string]$coveragePolicy.thresholdPolicyDigest -cne [string]$monitor.thresholdPolicyDigest -or
            -not (Test-CanonicalValueEqual @($coveragePolicy.sourceFloors) @($monitor.coverageFloors)) -or
            -not [OperationsBlueprint.StrictRfc3339]::TryParse([string]$coveragePolicy.approvedAt, [ref]$coverageApprovedAt) -or
            -not [OperationsBlueprint.StrictRfc3339]::TryParse([string]$coveragePolicy.expiresAt, [ref]$coverageExpiresAt) -or
            $coverageApprovedAt -gt $monitorApprovedAt -or $coverageExpiresAt -le $EvaluationTime) {
            Add-BlueprintError -Errors $Errors -Code 'ROLLOUT_MONITORING_TYPED_DEPENDENCY_MISMATCH' -Message 'Rollout coverage policy does not resolve to the exact current threshold-bound source floors.'
        }
    }
    if ($null -ne $monitorThresholdPolicy -and [string]$monitorThresholdPolicy.contentDigest -cne [string]$monitor.thresholdPolicyDigest) {
        Add-BlueprintError -Errors $Errors -Code 'ROLLOUT_MONITORING_TYPED_DEPENDENCY_MISMATCH' -Message 'Rollout threshold-policy digest differs from the canonical frozen policy.'
    }

    foreach ($sourceToolRef in $requiredMonitoringSources) {
        $sourceFloors = @($monitor.coverageFloors | Where-Object { [string]$_.sourceToolRef -ceq $sourceToolRef })
        if ($sourceFloors.Count -ne 1) {
            Add-BlueprintError -Errors $Errors -Code 'ROLLOUT_MONITORING_COVERAGE_FLOOR_INVALID' -Message "Rollout monitoring requires exactly one frozen coverage floor for $sourceToolRef."
        }
    }
    foreach ($floor in @($monitor.coverageFloors)) {
        Test-RequiredProperties -Object $floor -Names @('sourceToolRef', 'minimumCoveragePercent', 'thresholdPolicyRef', 'thresholdPointer') -Context 'rollout coverage floor' -Errors $Errors
        $floorValueValid = ($floor.minimumCoveragePercent -is [int] -or $floor.minimumCoveragePercent -is [long]) -and
            [int64]$floor.minimumCoveragePercent -ge 1 -and [int64]$floor.minimumCoveragePercent -le 100
        $floorPolicy = Resolve-CanonicalRecord -RecordMap $RecordMap -Reference $floor.thresholdPolicyRef -ExpectedTypes @('threshold-policy') -Context 'rollout coverage threshold policy' -Errors $Errors
        $floorPointerFound = $false
        $frozenFloor = if ($null -ne $floorPolicy -and [string]$floor.thresholdPointer -cmatch '^#/.+') {
            Get-JsonPointerValue -Document $floorPolicy.payload -Pointer ([string]$floor.thresholdPointer).Substring(1) -Found ([ref]$floorPointerFound)
        }
        else { $null }
        if (-not $floorValueValid -or $querySources -cnotcontains [string]$floor.sourceToolRef) {
            Add-BlueprintError -Errors $Errors -Code 'ROLLOUT_MONITORING_COVERAGE_FLOOR_INVALID' -Message 'Each monitoring coverage floor must be a bounded integer for a bound source.'
        }
        if (-not $floorPointerFound -or [string]$frozenFloor -cne [string]$floor.minimumCoveragePercent -or
            [string]$floor.thresholdPolicyRef -cne [string]$monitor.thresholdPolicyRef) {
            Add-BlueprintError -Errors $Errors -Code 'ROLLOUT_MONITORING_THRESHOLD_BINDING_MISMATCH' -Message 'Each monitoring coverage floor must equal its exact frozen threshold-policy pointer.'
        }
    }

    $requiredSignalClasses = @(
        'REVIEW_RESPONSE', 'MONITOR_HEALTH_DEADMAN', 'INTUNE_DRIFT', 'TARGET_MEMBERSHIP',
        'SYSTRACK_FLEET_HEALTH', 'SERVICENOW_INCIDENT_REPAIR', 'EVIDENCE_FRESHNESS',
        'EXCEPTION_EXPIRATION', 'VENDOR_PRODUCT_CHANGE', 'IAC_DRIFT'
    )
    if (@($monitor.signals).Count -ne $requiredSignalClasses.Count) {
        Add-BlueprintError -Errors $Errors -Code 'ROLLOUT_MONITORING_SIGNAL_CLASS_SET_INCOMPLETE' -Message 'Rollout monitoring requires exactly one governed entry for each of the ten frozen signal classes.'
    }
    $ownerRoles = if ($null -ne $Registry) { @($Registry.bindings | ForEach-Object { [string]$_.ownerRole } | Select-Object -Unique) } else { @() }
    foreach ($signalGroup in @($monitor.signals | Where-Object { [string]$_.applicabilityStatus -ceq 'ACTIVE' } | Group-Object -Property signalId -CaseSensitive)) {
        if ($signalGroup.Count -gt 1) {
            Add-BlueprintError -Errors $Errors -Code 'ROLLOUT_MONITORING_SIGNAL_INVALID' -Message 'Rollout monitoring signal IDs must be ordinally unique.'
        }
    }
    foreach ($signalClass in $requiredSignalClasses) {
        if (@($monitor.signals | Where-Object { [string]$_.signalClass -ceq $signalClass }).Count -ne 1) {
            Add-BlueprintError -Errors $Errors -Code 'ROLLOUT_MONITORING_SIGNAL_CLASS_SET_INCOMPLETE' -Message "Rollout monitoring must contain $signalClass exactly once."
        }
    }
    foreach ($signal in @($monitor.signals)) {
        Test-RequiredProperties -Object $signal -Names @('signalClass', 'applicabilityStatus') -Context 'governed rollout signal' -Errors $Errors
        if ([string]$signal.signalClass -cnotin $requiredSignalClasses) {
            Add-BlueprintError -Errors $Errors -Code 'ROLLOUT_MONITORING_SIGNAL_CLASS_SET_INCOMPLETE' -Message 'Rollout monitoring contains an unknown signal class.'
            continue
        }
        if ([string]$signal.applicabilityStatus -ceq 'ACTIVE') {
            Test-RequiredProperties -Object $signal -Names @(
                'signalId', 'sourceToolRef', 'metricId', 'thresholdPolicyRef', 'thresholdPointer',
                'comparison', 'evaluationWindowMinutes', 'cadenceMinutes', 'missingDisposition',
                'breachDisposition', 'ownerRole', 'alertRouteRef'
            ) -Context 'active rollout monitoring signal' -Errors $Errors
            $signalNumbersValid = ($signal.evaluationWindowMinutes -is [int] -or $signal.evaluationWindowMinutes -is [long]) -and
                ($signal.cadenceMinutes -is [int] -or $signal.cadenceMinutes -is [long]) -and
                [int64]$signal.evaluationWindowMinutes -ge 1 -and [int64]$signal.cadenceMinutes -ge 1 -and
                [int64]$signal.cadenceMinutes -le [int64]$signal.evaluationWindowMinutes
            $signalPolicy = Resolve-CanonicalRecord -RecordMap $RecordMap -Reference $signal.thresholdPolicyRef -ExpectedTypes @('threshold-policy') -Context 'rollout signal threshold policy' -Errors $Errors
            $signalThresholdFound = $false
            if ($null -ne $signalPolicy -and [string]$signal.thresholdPointer -cmatch '^#/.+') {
                [void](Get-JsonPointerValue -Document $signalPolicy.payload -Pointer ([string]$signal.thresholdPointer).Substring(1) -Found ([ref]$signalThresholdFound))
            }
            if (-not $signalThresholdFound -or [string]$signal.thresholdPolicyRef -cne [string]$monitor.thresholdPolicyRef) {
                Add-BlueprintError -Errors $Errors -Code 'ROLLOUT_MONITORING_THRESHOLD_BINDING_MISMATCH' -Message 'Every active rollout signal threshold must resolve from the exact frozen threshold policy.'
            }
            if (-not (Test-NonBlankString $signal.signalId) -or $querySources -cnotcontains [string]$signal.sourceToolRef -or
                $queryMetrics -cnotcontains [string]$signal.metricId -or
                [string]$signal.comparison -cnotin @('GT', 'GTE', 'LT', 'LTE', 'EQ', 'NEQ', 'OUTSIDE_RANGE') -or
                -not $signalNumbersValid -or [string]$signal.missingDisposition -cnotin @('HOLD', 'INCONCLUSIVE') -or
                [string]$signal.breachDisposition -cnotin @('HOLD', 'ROLLBACK', 'REQUALIFY')) {
                Add-BlueprintError -Errors $Errors -Code 'ROLLOUT_MONITORING_SIGNAL_INVALID' -Message 'An active rollout signal has an unknown metric/source, unbound threshold, invalid timing, or unsafe disposition.'
            }
            if ([string]$signal.ownerRole -cnotmatch '^ROLE_[A-Z0-9_]+$' -or
                $ownerRoles -cnotcontains [string]$signal.ownerRole -or [string]$signal.alertRouteRef -cnotmatch '^private://') {
                Add-BlueprintError -Errors $Errors -Code 'ROLLOUT_MONITORING_OWNER_INVALID' -Message 'Every active rollout signal requires a registered canonical owner role and private alert route.'
            }
        }
        elseif ([string]$signal.applicabilityStatus -ceq 'NOT_APPLICABLE') {
            Test-RequiredProperties -Object $signal -Names @(
                'ownerRole', 'approverRole', 'approvalRef', 'approvalDigest', 'rationale', 'approvedAt', 'expiresAt'
            ) -Context 'not-applicable rollout signal' -Errors $Errors
            $notApplicableApproval = Resolve-CanonicalRecord -RecordMap $RecordMap -Reference $signal.approvalRef -ExpectedTypes @('approval-record') -Context 'not-applicable signal approval' -Errors $Errors
            [DateTimeOffset]$notApplicableApprovedAt = [DateTimeOffset]::MinValue
            [DateTimeOffset]$notApplicableExpiresAt = [DateTimeOffset]::MinValue
            $approvalScopeValid = $false
            if ($null -ne $notApplicableApproval) {
                Test-RequiredProperties -Object $notApplicableApproval -Names @(
                    'status','requestedStage','planDigest','targetScopeRef','managedObjectType',
                    'requesterPrincipalRef','approvalEntries'
                ) -Context 'not-applicable signal scoped approval' -Errors $Errors
                $expectedSignalApprovalObjectType = 'ROLLOUT_SIGNAL_NOT_APPLICABLE::' +
                    [string]$monitor.recordId + '::' + [string]$monitor.personaId + '::' + [string]$signal.signalClass
                $approvalEntries = @($notApplicableApproval.approvalEntries)
                $matchingApproverEntries = @($approvalEntries | Where-Object {
                    [string]$_.roleId -ceq [string]$signal.approverRole
                })
                $approvalEntriesValid = $approvalEntries.Count -ge 4 -and
                    @($approvalEntries | Group-Object -Property roleId -CaseSensitive | Where-Object Count -gt 1).Count -eq 0 -and
                    @($approvalEntries | Group-Object -Property principalRef -CaseSensitive | Where-Object Count -gt 1).Count -eq 0
                foreach ($approvalEntry in $approvalEntries) {
                    Test-RequiredProperties -Object $approvalEntry -Names @('roleId','principalRef','decision','approvedAt','expiresAt') -Context 'not-applicable signal approval entry' -Errors $Errors
                    [DateTimeOffset]$entryApprovedAt = [DateTimeOffset]::MinValue
                    [DateTimeOffset]$entryExpiresAt = [DateTimeOffset]::MinValue
                    if ([string]$approvalEntry.roleId -cnotmatch '^ROLE_[A-Z0-9_]+$' -or
                        $ownerRoles -cnotcontains [string]$approvalEntry.roleId -or
                        [string]$approvalEntry.principalRef -cnotmatch '^private://' -or
                        [string]$approvalEntry.decision -cne 'APPROVED' -or
                        -not [OperationsBlueprint.StrictRfc3339]::TryParse([string]$approvalEntry.approvedAt, [ref]$entryApprovedAt) -or
                        -not [OperationsBlueprint.StrictRfc3339]::TryParse([string]$approvalEntry.expiresAt, [ref]$entryExpiresAt) -or
                        $entryApprovedAt -gt $monitorApprovedAt -or $entryExpiresAt -le $EvaluationTime -or
                        $entryExpiresAt -le $entryApprovedAt) {
                        $approvalEntriesValid = $false
                    }
                }
                $selectedApproverChronologyValid = $false
                if ($matchingApproverEntries.Count -eq 1) {
                    [DateTimeOffset]$selectedApprovedAt = [DateTimeOffset]::MinValue
                    [DateTimeOffset]$selectedExpiresAt = [DateTimeOffset]::MinValue
                    $selectedApproverChronologyValid =
                        [OperationsBlueprint.StrictRfc3339]::TryParse([string]$matchingApproverEntries[0].approvedAt, [ref]$selectedApprovedAt) -and
                        [OperationsBlueprint.StrictRfc3339]::TryParse([string]$matchingApproverEntries[0].expiresAt, [ref]$selectedExpiresAt) -and
                        [OperationsBlueprint.StrictRfc3339]::TryParse([string]$signal.approvedAt, [ref]$notApplicableApprovedAt) -and
                        [OperationsBlueprint.StrictRfc3339]::TryParse([string]$signal.expiresAt, [ref]$notApplicableExpiresAt) -and
                        $selectedApprovedAt -eq $notApplicableApprovedAt -and
                        $selectedExpiresAt -eq $notApplicableExpiresAt -and
                        [string]$matchingApproverEntries[0].principalRef -cne [string]$notApplicableApproval.requesterPrincipalRef
                }
                $approvalScopeValid = [string]$notApplicableApproval.contentDigest -ceq [string]$signal.approvalDigest -and
                    [string]$notApplicableApproval.status -ceq 'APPROVED' -and
                    [string]$notApplicableApproval.requestedStage -ceq 'PRODUCTION' -and
                    [string]$notApplicableApproval.planDigest -ceq [string]$monitor.reviewedPlanDigest -and
                    [string]$notApplicableApproval.targetScopeRef -ceq [string]$monitor.targetScopeRef -and
                    [string]$notApplicableApproval.managedObjectType -ceq $expectedSignalApprovalObjectType -and
                    [string]$notApplicableApproval.requesterPrincipalRef -cmatch '^private://' -and
                    $approvalEntriesValid -and $matchingApproverEntries.Count -eq 1 -and
                    $selectedApproverChronologyValid
            }
            if ([string]$signal.signalClass -cin @('REVIEW_RESPONSE','MONITOR_HEALTH_DEADMAN') -or
                [string]$signal.ownerRole -cnotmatch '^ROLE_[A-Z0-9_]+$' -or
                $ownerRoles -cnotcontains [string]$signal.ownerRole -or
                [string]$signal.approverRole -cnotmatch '^ROLE_[A-Z0-9_]+$' -or
                $ownerRoles -cnotcontains [string]$signal.approverRole -or
                [string]$signal.ownerRole -ceq [string]$signal.approverRole -or
                -not (Test-NonBlankString $signal.rationale) -or
                -not (Test-Sha256Token $signal.approvalDigest) -or
                -not $approvalScopeValid -or
                -not [OperationsBlueprint.StrictRfc3339]::TryParse([string]$signal.approvedAt, [ref]$notApplicableApprovedAt) -or
                -not [OperationsBlueprint.StrictRfc3339]::TryParse([string]$signal.expiresAt, [ref]$notApplicableExpiresAt) -or
                $notApplicableApprovedAt -gt $monitorApprovedAt -or $notApplicableExpiresAt -le $EvaluationTime -or
                $notApplicableExpiresAt -le $notApplicableApprovedAt) {
                Add-BlueprintError -Errors $Errors -Code 'ROLLOUT_SIGNAL_NOT_APPLICABLE_INVALID' -Message 'A NOT_APPLICABLE signal requires a distinct owner/approver, current typed approval, rationale, expiration, and may not suppress review-response or dead-man monitoring.'
            }
        }
        else {
            Add-BlueprintError -Errors $Errors -Code 'ROLLOUT_MONITORING_SIGNAL_INVALID' -Message 'Every governed rollout signal must be ACTIVE or NOT_APPLICABLE.'
        }
    }
    $reviewResponseSignal = @($monitor.signals | Where-Object { [string]$_.signalClass -ceq 'REVIEW_RESPONSE' -and [string]$_.applicabilityStatus -ceq 'ACTIVE' })
    $deadmanSignal = @($monitor.signals | Where-Object { [string]$_.signalClass -ceq 'MONITOR_HEALTH_DEADMAN' -and [string]$_.applicabilityStatus -ceq 'ACTIVE' })
    $deadmanCadenceValid = ($monitor.independentDeadmanCadenceMinutes -is [int] -or $monitor.independentDeadmanCadenceMinutes -is [long]) -and
        [int64]$monitor.independentDeadmanCadenceMinutes -ge 1
    if ([string]$monitor.primaryAlertRef -cnotmatch '^private://' -or -not (Test-Sha256Token $monitor.primaryAlertDigest) -or
        [string]$monitor.independentDeadmanRef -cnotmatch '^private://' -or -not (Test-Sha256Token $monitor.independentDeadmanDigest) -or
        [string]$monitor.primaryAlertRef -ceq [string]$monitor.independentDeadmanRef -or
        [string]$monitor.independentDeadmanOwnerRole -cnotmatch '^ROLE_[A-Z0-9_]+$' -or
        $ownerRoles -cnotcontains [string]$monitor.independentDeadmanOwnerRole -or
        [string]$monitor.independentDeadmanOwnerRole -ceq [string]$monitor.ownerRole -or
        -not $deadmanCadenceValid -or $reviewResponseSignal.Count -ne 1 -or $deadmanSignal.Count -ne 1 -or
        ($reviewResponseSignal.Count -eq 1 -and [string]$reviewResponseSignal[0].alertRouteRef -cne [string]$monitor.primaryAlertRef) -or
        ($deadmanSignal.Count -eq 1 -and
            ([string]$deadmanSignal[0].alertRouteRef -cne [string]$monitor.independentDeadmanRef -or
             [string]$deadmanSignal[0].ownerRole -cne [string]$monitor.independentDeadmanOwnerRole -or
             [string]$deadmanSignal[0].cadenceMinutes -cne [string]$monitor.independentDeadmanCadenceMinutes))) {
        Add-BlueprintError -Errors $Errors -Code 'ROLLOUT_ALERT_AND_DEADMAN_BINDING_INVALID' -Message 'Rollout monitoring requires distinct primary-alert and independently owned dead-man paths bound to active governed signals and an exact positive cadence.'
    }
    foreach ($sourceToolRef in $requiredMonitoringSources) {
        if (@($monitor.signals | Where-Object { [string]$_.applicabilityStatus -ceq 'ACTIVE' -and [string]$_.sourceToolRef -ceq $sourceToolRef }).Count -eq 0) {
            Add-BlueprintError -Errors $Errors -Code 'ROLLOUT_MONITORING_SOURCE_SET_INCOMPLETE' -Message "Rollout monitoring has no governed signal for $sourceToolRef."
        }
    }
    if ([string]$monitor.ownerRole -cnotmatch '^ROLE_[A-Z0-9_]+$' -or $ownerRoles -cnotcontains [string]$monitor.ownerRole) {
        Add-BlueprintError -Errors $Errors -Code 'ROLLOUT_MONITORING_OWNER_INVALID' -Message 'The rollout monitoring record requires a registered canonical owner role.'
    }

    $requalificationPlan = Resolve-CanonicalRecord -RecordMap $RecordMap -Reference $monitor.requalificationPlanRef -ExpectedTypes @('requalification-plan-record') -Context 'rollout requalification plan' -Errors $Errors
    if ($null -ne $requalificationPlan) {
        Test-RequiredProperties -Object $requalificationPlan -Names @(
            'schemaVersion','recordStage','status','verdictRef','verdictDigest','requalificationTriggersPointer',
            'thresholdPolicyRef','thresholdPolicyDigest','stopConditionsRef','stopConditionsDigest',
            'rollbackRef','rollbackDigest','triggerActions','ownerRole','alertRouteRef','approvedAt','expiresAt'
        ) -Context 'rollout requalification plan' -Errors $Errors
        [DateTimeOffset]$requalApprovedAt = [DateTimeOffset]::MinValue
        [DateTimeOffset]$requalExpiresAt = [DateTimeOffset]::MinValue
        $triggerActions = @($requalificationPlan.triggerActions)
        $triggerActionsValid = $triggerActions.Count -gt 0 -and
            @($triggerActions | Group-Object -Property triggerId -CaseSensitive | Where-Object Count -gt 1).Count -eq 0
        foreach ($triggerAction in $triggerActions) {
            Test-RequiredProperties -Object $triggerAction -Names @('triggerId','triggerPointer','action','ownerRole','alertRouteRef') -Context 'requalification trigger action' -Errors $Errors
            if (-not (Test-NonBlankString $triggerAction.triggerId) -or
                -not ([string]$triggerAction.triggerPointer).StartsWith(([string]$monitor.finalVerdictRef + '#/requalificationTriggers/'), [StringComparison]::Ordinal) -or
                [string]$triggerAction.action -cnotin @('HOLD','DELTA_QUALIFICATION','FULL_REQUALIFICATION','ROLLBACK') -or
                [string]$triggerAction.ownerRole -cnotmatch '^ROLE_[A-Z0-9_]+$' -or
                [string]$triggerAction.alertRouteRef -cnotmatch '^private://') { $triggerActionsValid = $false }
        }
        if ([string]$requalificationPlan.contentDigest -cne [string]$monitor.requalificationPlanDigest -or
            [string]$requalificationPlan.schemaVersion -cne '1.0.0' -or [string]$requalificationPlan.recordStage -cne 'REQUALIFICATION_PLAN' -or
            [string]$requalificationPlan.status -cne 'APPROVED' -or
            [string]$requalificationPlan.verdictRef -cne [string]$monitor.finalVerdictRef -or
            [string]$requalificationPlan.verdictDigest -cne [string]$monitor.finalVerdictDigest -or
            [string]$requalificationPlan.requalificationTriggersPointer -cne [string]$monitor.requalificationTriggersPointer -or
            [string]$requalificationPlan.thresholdPolicyRef -cne [string]$monitor.thresholdPolicyRef -or
            [string]$requalificationPlan.thresholdPolicyDigest -cne [string]$monitor.thresholdPolicyDigest -or
            [string]$requalificationPlan.stopConditionsRef -cne [string]$monitor.stopConditionsRef -or
            [string]$requalificationPlan.stopConditionsDigest -cne [string]$monitor.stopConditionsDigest -or
            [string]$requalificationPlan.rollbackRef -cne [string]$monitor.rollbackRef -or
            [string]$requalificationPlan.rollbackDigest -cne [string]$monitor.rollbackDigest -or
            -not $triggerActionsValid -or [string]$requalificationPlan.ownerRole -cnotmatch '^ROLE_[A-Z0-9_]+$' -or
            [string]$requalificationPlan.alertRouteRef -cnotmatch '^private://' -or
            -not [OperationsBlueprint.StrictRfc3339]::TryParse([string]$requalificationPlan.approvedAt, [ref]$requalApprovedAt) -or
            -not [OperationsBlueprint.StrictRfc3339]::TryParse([string]$requalificationPlan.expiresAt, [ref]$requalExpiresAt) -or
            $requalApprovedAt -gt $monitorApprovedAt -or $requalExpiresAt -le $EvaluationTime) {
            Add-BlueprintError -Errors $Errors -Code 'ROLLOUT_MONITORING_TYPED_DEPENDENCY_MISMATCH' -Message 'Requalification plan is not current or does not bind the exact verdict triggers, threshold policy, stop set, rollback, owned actions, and alert route.'
        }
    }

    if ([string]$monitor.stopConditionsRef -cne [string]$Authorization.stopConditionsRef -or
        [string]$monitor.stopConditionsDigest -cne [string]$Authorization.stopConditionsDigest -or
        [string]$monitor.rollbackRef -cne [string]$Authorization.rollbackRef -or
        [string]$monitor.rollbackDigest -cne [string]$Authorization.rollbackDigest -or
        $null -eq $StopConditionsRecord -or $null -eq $RollbackRecord -or
        [string]$StopConditionsRecord.monitoringQueryPackRef -cne [string]$monitor.queryPackRef -or
        [string]$StopConditionsRecord.monitoringQueryPackDigest -cne [string]$monitor.queryPackDigest -or
        [string]$StopConditionsRecord.telemetryBaselineRef -cne [string]$monitor.telemetryBaselineRef -or
        [string]$StopConditionsRecord.telemetryBaselineDigest -cne [string]$monitor.telemetryBaselineDigest -or
        [string]$StopConditionsRecord.coveragePolicyRef -cne [string]$monitor.coveragePolicyRef -or
        [string]$StopConditionsRecord.coveragePolicyDigest -cne [string]$monitor.coveragePolicyDigest -or
        [string]$StopConditionsRecord.thresholdPolicyRef -cne [string]$monitor.thresholdPolicyRef -or
        [string]$StopConditionsRecord.thresholdPolicyDigest -cne [string]$monitor.thresholdPolicyDigest -or
        @($monitor.signals | Where-Object { [string]$_.cadenceMinutes -ceq [string]$StopConditionsRecord.cadenceMinutes }).Count -eq 0) {
        Add-BlueprintError -Errors $Errors -Code 'ROLLOUT_MONITORING_RESPONSE_BINDING_MISMATCH' -Message 'Rollout monitoring must use the same query pack, baseline, policies, cadence, stop conditions, and rollback as the approved response plan.'
    }
}

function Get-ActivationDecision {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]$Request,
        $Registry,
        [object[]]$RecordIndex = @(),
        $Readback,
        [DateTimeOffset]$EvaluationTime = [DateTimeOffset]::UtcNow,
        [ValidateSet('TEST', 'PRODUCTION')][string]$ValidationProfile = 'PRODUCTION'
    )

    $ValidationProfile = ([string]$ValidationProfile).ToUpperInvariant()
    $errors = New-Object System.Collections.ArrayList
    if ([string]$ValidationProfile -ceq 'PRODUCTION' -and
        [Math]::Abs(([DateTimeOffset]::UtcNow - $EvaluationTime).TotalMinutes) -gt 5) {
        Add-BlueprintError -Errors $errors -Code 'PRODUCTION_EVALUATION_TIME_UNTRUSTED' -Message 'Production activation evaluation time must remain within five minutes of the validator host trusted UTC clock.'
    }
    if ($null -eq $Request) {
        Add-BlueprintError -Errors $errors -Code 'NULL_ACTIVATION_REQUEST' -Message 'Activation request is null.'
        return New-BlueprintResult -Errors $errors -State 'BLOCKED'
    }
    foreach ($inputBinding in @(
            @{ Name = 'activation request'; Value = $Request },
            @{ Name = 'control-plane registry'; Value = $Registry },
            @{ Name = 'independent readback'; Value = $Readback }
        )) {
        if ($null -ne $inputBinding.Value -and -not (Test-CanonicalJsonRuntimeDomain -Value $inputBinding.Value)) {
            Add-BlueprintError -Errors $errors -Code 'CANONICAL_JSON_RUNTIME_DOMAIN_INVALID' -Message "$($inputBinding.Name) contains a value outside the frozen cross-host JSON runtime domain."
        }
    }
    if (@($errors | Where-Object { [string]$_.code -ceq 'CANONICAL_JSON_RUNTIME_DOMAIN_INVALID' }).Count -gt 0) {
        return New-BlueprintResult -Errors $errors -State $(if ($ValidationProfile -ceq 'TEST') { 'TEST_FIXTURE_BLOCKED_NON_PROMOTABLE' } else { 'BLOCKED' })
    }

    if ($null -eq $Registry) {
        Add-BlueprintError -Errors $errors -Code 'CONTROL_PLANE_REGISTRY_REQUIRED' -Message 'Activation evaluation requires a validated private tool registry.'
    }
    else {
        $registryResult = Test-ToolRegistry -Registry $Registry -EvaluationTime $EvaluationTime
        if (-not $registryResult.Valid) {
            Add-BlueprintError -Errors $errors -Code 'CONTROL_PLANE_REGISTRY_INVALID' -Message "Private tool registry failed validation: $(@($registryResult.ReasonCodes) -join ', ')."
        }
        elseif ([string]$Registry.activation.state -cne 'ACTIVE') {
            Add-BlueprintError -Errors $errors -Code 'CONTROL_PLANE_NOT_ACTIVE' -Message 'The checked binding is not an active private control plane.'
        }
    }

    $requiredRequestFields = @(
        'requestedStage', 'desiredStateRevision', 'graphWriteRevision',
        'reviewedPlanRef', 'reviewedPlanDigest', 'packageDigest', 'packageVerificationRef',
        'packageVerificationDigest', 'packageRevocationFreshnessPolicyRef',
        'packageRevocationFreshnessPolicyDigest', 'packageRevocationCheckMaxAgeMinutes',
        'targetMembershipDigest', 'targetPopulation', 'targetRing',
        'targetScopeRef', 'tenantBoundaryRef', 'targetEnvironmentRef',
        'managedObjectType', 'managedObjectRefs', 'managedObjectSetDigest',
        'consumptionLedgerRef', 'consumptionLedgerPolicyRef', 'consumptionLedgerPolicyDigest',
        'independentReadbackPolicyRef', 'independentReadbackPolicyDigest',
        'authorizationTtlPolicyRef', 'authorizationTtlPolicyDigest', 'authorizationMaxTtlMinutes',
        'authorizationRevocationFreshnessPolicyRef', 'authorizationRevocationFreshnessPolicyDigest',
        'authorizationRevocationCheckMaxAgeMinutes',
        'writerToolRef', 'writeIdentityRef', 'applyOperatorIdentityRef',
        'manifestRef', 'personaId', 'requesterPrincipalRef',
        'transportOwnershipRecordRef', 'transportOwnershipRecordDigest', 'transportSelectionStatus',
        'roleBindingRef', 'roleBindingDigest', 'roleBindingReadbackRef', 'roleBindingReadbackDigest',
        'writeAuthorizationRef', 'writeAuthorizationDigest',
        'writeOperationId', 'writeOperationRef', 'writeCompletedAt', 'readbackMaxAgeMinutes',
        'protectedApprovalRef', 'approvalRecordDigest', 'approvalExpiresAt',
        'approvalSetStatus', 'approvalRoleIds', 'approvalSetScopeRef', 'approvalSetPlanDigest',
        'privateActivationRecordRef', 'privateActivationRecordDigest', 'authorization'
    )
    Test-RequiredProperties -Object $Request -Names $requiredRequestFields -Context 'activation request' -Errors $errors
    Test-AllowedProperties -Object $Request -Names @(
        $requiredRequestFields + @(
            'transportExceptionRef', 'transportExceptionDigest', 'transportExceptionExpiresAt',
            'rolloutMonitoringRef', 'rolloutMonitoringRecordDigest'
        )
    ) -Context 'activation request' -Errors $errors
    if ($Request.requestedStage -cnotin @('PILOT', 'PRODUCTION')) {
        Add-BlueprintError -Errors $errors -Code 'INVALID_REQUESTED_STAGE' -Message 'Requested stage must be PILOT or PRODUCTION.'
    }
    if (([string]$Request.requestedStage -ceq 'PILOT' -and [string]$Request.targetRing -cne 'AUTHORIZED_PILOT') -or
        ([string]$Request.requestedStage -ceq 'PRODUCTION' -and [string]$Request.targetRing -cnotin @('PERSONA_QUALIFIED', 'BROAD'))) {
        Add-BlueprintError -Errors $errors -Code 'TARGET_RING_INVALID' -Message 'Pilot and production requests must name an exact permitted promotion ring.'
    }
    if ([string]$Request.writerToolRef -cnotin @('msgraph-terraform-provider', 'microsoft-graph-write')) {
        Add-BlueprintError -Errors $errors -Code 'UNAUTHORIZED_WRITER' -Message 'Only the qualified Terraform-provider transport or explicit direct Graph exception may carry Intune desired state.'
    }
    if ([string]$Request.transportSelectionStatus -cne 'APPROVED_OBJECT_TYPE_OWNER') {
        Add-BlueprintError -Errors $errors -Code 'TRANSPORT_OWNERSHIP_NOT_APPROVED' -Message 'The requested object type lacks one approved transport owner.'
    }
    if ([string]$Request.writerToolRef -ceq 'microsoft-graph-write') {
        [DateTimeOffset]$transportExceptionExpiresAt = [DateTimeOffset]::MinValue
        if ([string]$Request.transportExceptionRef -notmatch '^private://' -or
            -not (Test-Sha256Token $Request.transportExceptionDigest) -or
            -not [OperationsBlueprint.StrictRfc3339]::TryParse([string]$Request.transportExceptionExpiresAt, [ref]$transportExceptionExpiresAt) -or
            $transportExceptionExpiresAt -le $EvaluationTime) {
            Add-BlueprintError -Errors $errors -Code 'DIRECT_GRAPH_EXCEPTION_INVALID' -Message 'The direct Graph path requires an explicit, scoped, unexpired private provider-gap exception.'
        }
    }
    elseif ((Test-ValuePresent $Request.transportExceptionRef) -or
        (Test-ValuePresent $Request.transportExceptionDigest) -or
        (Test-ValuePresent $Request.transportExceptionExpiresAt)) {
        Add-BlueprintError -Errors $errors -Code 'DIRECT_GRAPH_EXCEPTION_FORBIDDEN' -Message 'Terraform-provider transport may not carry a direct-Graph provider-gap exception.'
    }
    if ([string]$Request.desiredStateRevision -cne [string]$Request.graphWriteRevision) {
        Add-BlueprintError -Errors $errors -Code 'AUTHORIZED_REVISION_MISMATCH' -Message 'Graph write revision differs from the reviewed desired-state revision.'
    }
    if ([string]$Request.requesterPrincipalRef -ceq [string]$Request.writeIdentityRef) {
        Add-BlueprintError -Errors $errors -Code 'REQUESTER_WRITE_IDENTITY_NOT_SEPARATE' -Message 'The requesting principal and protected write identity must be independently bound.'
    }
    foreach ($digestName in @('desiredStateRevision', 'graphWriteRevision', 'reviewedPlanDigest', 'packageDigest',
        'packageVerificationDigest', 'targetMembershipDigest', 'managedObjectSetDigest',
        'packageRevocationFreshnessPolicyDigest', 'consumptionLedgerPolicyDigest',
        'independentReadbackPolicyDigest', 'authorizationTtlPolicyDigest',
        'authorizationRevocationFreshnessPolicyDigest', 'writeAuthorizationDigest',
        'transportOwnershipRecordDigest', 'roleBindingDigest', 'roleBindingReadbackDigest',
        'approvalRecordDigest', 'privateActivationRecordDigest')) {
        if (-not (Test-Sha256Token $Request.$digestName)) {
            Add-BlueprintError -Errors $errors -Code 'INVALID_ACTIVATION_DIGEST' -Message "$digestName must be a SHA-256 token."
        }
    }
    if ([string]$Request.approvalSetStatus -cne 'APPROVED' -or
        [string]$Request.approvalSetScopeRef -cne [string]$Request.targetScopeRef -or
        [string]$Request.approvalSetPlanDigest -cne [string]$Request.reviewedPlanDigest) {
        Add-BlueprintError -Errors $errors -Code 'APPROVAL_SET_BINDING_MISMATCH' -Message 'The composite approval set must approve the exact reviewed plan and target scope.'
    }
    $expectedManagedObjectSetDigest = Get-ManagedObjectSetDigest -ManagedObjectRefs $Request.managedObjectRefs
    if (@($Request.managedObjectRefs).Count -eq 0 -or
        @($Request.managedObjectRefs | Where-Object { $_ -isnot [string] -or [string]$_ -cnotmatch '^private://' }).Count -gt 0 -or
        @($Request.managedObjectRefs | Group-Object -CaseSensitive | Where-Object Count -gt 1).Count -gt 0 -or
        [string]$Request.managedObjectSetDigest -cne [string]$expectedManagedObjectSetDigest) {
        Add-BlueprintError -Errors $errors -Code 'MANAGED_OBJECT_SET_INVALID' -Message 'Activation requires a nonempty unique private managed-object set whose canonical digest matches caller intent.'
    }
    $requiredApprovalRoles = @(
        'ROLE_PROTECTED_ENVIRONMENT_APPROVER', 'ROLE_INTUNE_CHANGE_APPROVER',
        'ROLE_QUALIFICATION_AUTHORITY', 'ROLE_PRIVACY_APPROVER'
    )
    if ([string]$Request.requestedStage -ceq 'PRODUCTION') { $requiredApprovalRoles += 'ROLE_PROCUREMENT_APPROVER' }
    foreach ($requiredApprovalRole in $requiredApprovalRoles) {
        if (@($Request.approvalRoleIds) -cnotcontains $requiredApprovalRole) {
            Add-BlueprintError -Errors $errors -Code 'APPROVAL_ROLE_MISSING' -Message "Composite approval set lacks $requiredApprovalRole."
        }
    }
    foreach ($group in @(@($Request.approvalRoleIds) | Group-Object -CaseSensitive)) {
        if ($group.Count -gt 1) {
            Add-BlueprintError -Errors $errors -Code 'DUPLICATE_APPROVAL_ROLE' -Message "Composite approval set repeats $($group.Name)."
        }
    }
    if ([string]$Request.protectedApprovalRef -notmatch '^private://' -or
        [string]$Request.reviewedPlanRef -notmatch '^private://' -or
        [string]$Request.writeIdentityRef -notmatch '^private://' -or
        [string]$Request.requesterPrincipalRef -notmatch '^private://' -or
        [string]$Request.writeOperationRef -notmatch '^private://' -or
        [string]$Request.writeAuthorizationRef -notmatch '^private://' -or
        [string]$Request.consumptionLedgerRef -notmatch '^private://' -or
        [string]$Request.consumptionLedgerPolicyRef -notmatch '^private://' -or
        [string]$Request.independentReadbackPolicyRef -notmatch '^private://' -or
        [string]$Request.authorizationTtlPolicyRef -notmatch '^private://' -or
        [string]$Request.authorizationRevocationFreshnessPolicyRef -notmatch '^private://' -or
        [string]$Request.packageRevocationFreshnessPolicyRef -notmatch '^private://' -or
        [string]$Request.applyOperatorIdentityRef -notmatch '^private://' -or
        [string]$Request.transportOwnershipRecordRef -notmatch '^private://' -or
        [string]$Request.roleBindingRef -notmatch '^private://' -or
        [string]$Request.roleBindingReadbackRef -notmatch '^private://' -or
        [string]$Request.privateActivationRecordRef -notmatch '^private://' -or
        [string]$Request.tenantBoundaryRef -notmatch '^private://' -or
        [string]$Request.targetEnvironmentRef -notmatch '^private://' -or
        [string]$Request.targetScopeRef -notmatch '^private://') {
        Add-BlueprintError -Errors $errors -Code 'PRIVATE_APPROVAL_OR_IDENTITY_REQUIRED' -Message 'Protected approval, write identity, per-object transport ownership, and activation record must resolve inside the private boundary.'
    }
    if ($null -ne $Registry -and $Registry.activation.state -ceq 'ACTIVE') {
        if ([string]$Request.privateActivationRecordRef -cne [string]$Registry.activation.activationRecordRef -or
            [string]$Request.privateActivationRecordDigest -cne [string]$Registry.activation.activationRecordDigest) {
            Add-BlueprintError -Errors $errors -Code 'PRIVATE_ACTIVATION_BINDING_MISMATCH' -Message 'Request does not match the active private control-plane record.'
        }
    }
    [DateTimeOffset]$approvalExpiresAt = [DateTimeOffset]::MinValue
    if (-not [OperationsBlueprint.StrictRfc3339]::TryParse([string]$Request.approvalExpiresAt, [ref]$approvalExpiresAt) -or $approvalExpiresAt -le $EvaluationTime) {
        Add-BlueprintError -Errors $errors -Code 'PROTECTED_APPROVAL_EXPIRED_OR_INVALID' -Message 'Protected approval must be valid and unexpired.'
    }
    [DateTimeOffset]$writeCompletedAt = [DateTimeOffset]::MinValue
    if (-not [OperationsBlueprint.StrictRfc3339]::TryParse([string]$Request.writeCompletedAt, [ref]$writeCompletedAt) -or $writeCompletedAt -gt $EvaluationTime) {
        Add-BlueprintError -Errors $errors -Code 'WRITE_TIME_INVALID' -Message 'Write completion time is invalid or in the future.'
    }
    $readbackMaxAgeValid = ($Request.readbackMaxAgeMinutes -is [int] -or $Request.readbackMaxAgeMinutes -is [long])
    if ($readbackMaxAgeValid) {
        $readbackMaxAgeValid = [int64]$Request.readbackMaxAgeMinutes -ge 1 -and
            [int64]$Request.readbackMaxAgeMinutes -le 1440
    }
    [int64]$effectiveReadbackMaxAgeMinutes = if ($readbackMaxAgeValid) {
        [int64]$Request.readbackMaxAgeMinutes
    }
    else { 1440 }
    if (-not $readbackMaxAgeValid) {
        Add-BlueprintError -Errors $errors -Code 'READBACK_MAX_AGE_INVALID' -Message 'Readback maximum age must be a positive frozen integer.'
    }
    $authorizationMaxTtlValid = ($Request.authorizationMaxTtlMinutes -is [int] -or $Request.authorizationMaxTtlMinutes -is [long]) -and
        [int64]$Request.authorizationMaxTtlMinutes -ge 1
    $authorizationRevocationMaxAgeValid = ($Request.authorizationRevocationCheckMaxAgeMinutes -is [int] -or $Request.authorizationRevocationCheckMaxAgeMinutes -is [long]) -and
        [int64]$Request.authorizationRevocationCheckMaxAgeMinutes -ge 1
    $packageRevocationMaxAgeValid = ($Request.packageRevocationCheckMaxAgeMinutes -is [int] -or $Request.packageRevocationCheckMaxAgeMinutes -is [long]) -and
        [int64]$Request.packageRevocationCheckMaxAgeMinutes -ge 1
    if (-not $authorizationMaxTtlValid -or -not $authorizationRevocationMaxAgeValid -or -not $packageRevocationMaxAgeValid) {
        Add-BlueprintError -Errors $errors -Code 'SECURITY_FRESHNESS_POLICY_VALUE_INVALID' -Message 'Authorization TTL and authorization/package revocation maximum ages must be positive frozen integer minutes.'
    }
    [int64]$effectiveAuthorizationMaxTtlMinutes = if ($authorizationMaxTtlValid) { [int64]$Request.authorizationMaxTtlMinutes } else { 0 }
    [int64]$effectiveAuthorizationRevocationMaxAgeMinutes = if ($authorizationRevocationMaxAgeValid) { [int64]$Request.authorizationRevocationCheckMaxAgeMinutes } else { 0 }
    [int64]$effectivePackageRevocationMaxAgeMinutes = if ($packageRevocationMaxAgeValid) { [int64]$Request.packageRevocationCheckMaxAgeMinutes } else { 0 }

    $recordMap = Get-CanonicalRecordMap -RecordIndex $RecordIndex -Errors $errors -Context 'activation evaluation' `
        -EvaluationTime $EvaluationTime -ValidationProfile $ValidationProfile

    $selectedTransportOwnership = $null
    if ($null -eq $Registry -or $null -eq $Registry.intuneTransportOwnership) {
        Add-BlueprintError -Errors $errors -Code 'TRANSPORT_OWNERSHIP_MAP_REQUIRED' -Message 'Activation requires a private non-overlapping Intune object-type ownership map.'
    }
    else {
        $ownershipEntries = @($Registry.intuneTransportOwnership.objectTypeOwnership)
        if ($ownershipEntries.Count -eq 0) {
            Add-BlueprintError -Errors $errors -Code 'TRANSPORT_OWNERSHIP_MAP_EMPTY' -Message 'An empty public transport map cannot authorize any managed object type.'
        }
        foreach ($ownershipEntry in $ownershipEntries) {
            Test-RequiredProperties -Object $ownershipEntry -Names @(
                'managedObjectType', 'targetScopeRef', 'writerToolRef', 'selectionStatus'
            ) -Context 'private transport ownership entry' -Errors $errors
            Test-AllowedProperties -Object $ownershipEntry -Names @(
                'managedObjectType', 'targetScopeRef', 'writerToolRef', 'selectionStatus', 'exceptionRef', 'exceptionDigest'
            ) -Context 'private transport ownership entry' -Errors $errors
            if ([string]$ownershipEntry.targetScopeRef -notmatch '^private://' -or
                [string]$ownershipEntry.writerToolRef -cnotin @('msgraph-terraform-provider', 'microsoft-graph-write') -or
                [string]$ownershipEntry.selectionStatus -cne 'APPROVED_OBJECT_TYPE_OWNER') {
                Add-BlueprintError -Errors $errors -Code 'TRANSPORT_OWNERSHIP_ENTRY_INVALID' -Message 'Every private ownership entry requires an approved writer and bounded private scope.'
            }
        }
        foreach ($ownershipGroup in @($ownershipEntries | Group-Object -Property {
            ([string]$_.managedObjectType) + [char]0 + ([string]$_.targetScopeRef)
        } -CaseSensitive)) {
            if ($ownershipGroup.Count -ne 1) {
                Add-BlueprintError -Errors $errors -Code 'TRANSPORT_OWNERSHIP_OVERLAP' -Message 'A managed object type and scope has more than one transport owner.'
            }
        }
        $matchingOwnership = @($ownershipEntries | Where-Object {
            [string]$_.managedObjectType -ceq [string]$Request.managedObjectType -and
            [string]$_.targetScopeRef -ceq [string]$Request.targetScopeRef
        })
        if ($matchingOwnership.Count -ne 1) {
            Add-BlueprintError -Errors $errors -Code 'TRANSPORT_OWNERSHIP_RECORD_MISMATCH' -Message 'The requested object type and scope do not resolve to exactly one entry in the approved private transport map.'
        }
        else {
            $selectedTransportOwnership = $matchingOwnership[0]
            if ([string]$selectedTransportOwnership.writerToolRef -cne [string]$Request.writerToolRef -or
                [string]$selectedTransportOwnership.selectionStatus -cne [string]$Request.transportSelectionStatus -or
                ([string]$Request.writerToolRef -ceq 'microsoft-graph-write' -and
                    ([string]$selectedTransportOwnership.exceptionRef -cne [string]$Request.transportExceptionRef -or
                     [string]$selectedTransportOwnership.exceptionDigest -cne [string]$Request.transportExceptionDigest)) -or
                ([string]$Request.writerToolRef -ceq 'msgraph-terraform-provider' -and
                    ((Test-ValuePresent $selectedTransportOwnership.exceptionRef) -or
                     (Test-ValuePresent $selectedTransportOwnership.exceptionDigest)))) {
                Add-BlueprintError -Errors $errors -Code 'TRANSPORT_OWNERSHIP_RECORD_MISMATCH' -Message 'The request differs from the selected writer or exception in the approved private transport map.'
            }
        }
    }

    $transportRecord = Resolve-CanonicalRecord -RecordMap $recordMap -Reference $Request.transportOwnershipRecordRef -ExpectedTypes @('transport-ownership-record') -Context 'transport ownership' -Errors $errors
    $manifestRecord = Resolve-CanonicalRecord -RecordMap $recordMap -Reference $Request.manifestRef -ExpectedTypes @('candidate-manifest') -Context 'activation candidate manifest' -Errors $errors
    $planRecord = Resolve-CanonicalRecord -RecordMap $recordMap -Reference $Request.reviewedPlanRef -ExpectedTypes @('reviewed-plan-record') -Context 'reviewed plan' -Errors $errors
    $approvalRecord = Resolve-CanonicalRecord -RecordMap $recordMap -Reference $Request.protectedApprovalRef -ExpectedTypes @('approval-record') -Context 'composite approval set' -Errors $errors
    $activationRecord = Resolve-CanonicalRecord -RecordMap $recordMap -Reference $Request.privateActivationRecordRef -ExpectedTypes @('activation-record') -Context 'private activation record' -Errors $errors
    $writeAuthorizationRecord = Resolve-CanonicalRecord -RecordMap $recordMap -Reference $Request.writeAuthorizationRef -ExpectedTypes @('write-authorization-record') -Context 'pre-write authorization' -Errors $errors
    $writeOperationRecord = Resolve-CanonicalRecord -RecordMap $recordMap -Reference $Request.writeOperationRef -ExpectedTypes @('write-operation-record') -Context 'write operation' -Errors $errors
    $authorizationTtlPolicyRecord = Test-SecurityFreshnessPolicyBinding -RecordMap $recordMap `
        -Reference $Request.authorizationTtlPolicyRef -Digest $Request.authorizationTtlPolicyDigest `
        -ExpectedKind 'AUTHORIZATION_TTL' -ExpectedMaximumAgeMinutes $effectiveAuthorizationMaxTtlMinutes `
        -ExpectedTenantBoundaryRef ([string]$Request.tenantBoundaryRef) `
        -ExpectedTargetEnvironmentRef ([string]$Request.targetEnvironmentRef) `
        -ExpectedRoleBindingRef ([string]$Request.roleBindingRef) -ExpectedRoleBindingDigest ([string]$Request.roleBindingDigest) `
        -ExpectedRoleBindingReadbackRef ([string]$Request.roleBindingReadbackRef) -ExpectedRoleBindingReadbackDigest ([string]$Request.roleBindingReadbackDigest) `
        -EvaluationTime $EvaluationTime -Errors $errors
    $authorizationRevocationPolicyRecord = Test-SecurityFreshnessPolicyBinding -RecordMap $recordMap `
        -Reference $Request.authorizationRevocationFreshnessPolicyRef -Digest $Request.authorizationRevocationFreshnessPolicyDigest `
        -ExpectedKind 'AUTHORIZATION_REVOCATION' -ExpectedMaximumAgeMinutes $effectiveAuthorizationRevocationMaxAgeMinutes `
        -ExpectedTenantBoundaryRef ([string]$Request.tenantBoundaryRef) `
        -ExpectedTargetEnvironmentRef ([string]$Request.targetEnvironmentRef) `
        -ExpectedRoleBindingRef ([string]$Request.roleBindingRef) -ExpectedRoleBindingDigest ([string]$Request.roleBindingDigest) `
        -ExpectedRoleBindingReadbackRef ([string]$Request.roleBindingReadbackRef) -ExpectedRoleBindingReadbackDigest ([string]$Request.roleBindingReadbackDigest) `
        -EvaluationTime $EvaluationTime -Errors $errors
    $packageRevocationPolicyRecord = Test-SecurityFreshnessPolicyBinding -RecordMap $recordMap `
        -Reference $Request.packageRevocationFreshnessPolicyRef -Digest $Request.packageRevocationFreshnessPolicyDigest `
        -ExpectedKind 'PACKAGE_REVOCATION' -ExpectedMaximumAgeMinutes $effectivePackageRevocationMaxAgeMinutes `
        -ExpectedTenantBoundaryRef ([string]$Request.tenantBoundaryRef) `
        -ExpectedTargetEnvironmentRef ([string]$Request.targetEnvironmentRef) `
        -ExpectedRoleBindingRef ([string]$Request.roleBindingRef) -ExpectedRoleBindingDigest ([string]$Request.roleBindingDigest) `
        -ExpectedRoleBindingReadbackRef ([string]$Request.roleBindingReadbackRef) -ExpectedRoleBindingReadbackDigest ([string]$Request.roleBindingReadbackDigest) `
        -EvaluationTime $EvaluationTime -Errors $errors
    $readbackFreshnessPolicyRecord = Test-SecurityFreshnessPolicyBinding -RecordMap $recordMap `
        -Reference $Request.independentReadbackPolicyRef -Digest $Request.independentReadbackPolicyDigest `
        -ExpectedKind 'READBACK_FRESHNESS' -ExpectedMaximumAgeMinutes $effectiveReadbackMaxAgeMinutes `
        -ExpectedTenantBoundaryRef ([string]$Request.tenantBoundaryRef) `
        -ExpectedTargetEnvironmentRef ([string]$Request.targetEnvironmentRef) `
        -ExpectedRoleBindingRef ([string]$Request.roleBindingRef) -ExpectedRoleBindingDigest ([string]$Request.roleBindingDigest) `
        -ExpectedRoleBindingReadbackRef ([string]$Request.roleBindingReadbackRef) -ExpectedRoleBindingReadbackDigest ([string]$Request.roleBindingReadbackDigest) `
        -EvaluationTime $EvaluationTime -Errors $errors
    $securityFreshnessPolicyRefs = @(
        [string]$Request.authorizationTtlPolicyRef,
        [string]$Request.authorizationRevocationFreshnessPolicyRef,
        [string]$Request.packageRevocationFreshnessPolicyRef,
        [string]$Request.independentReadbackPolicyRef
    )
    if (@($securityFreshnessPolicyRefs | Group-Object -CaseSensitive | Where-Object Count -gt 1).Count -gt 0) {
        Add-BlueprintError -Errors $errors -Code 'SECURITY_FRESHNESS_POLICY_SET_INVALID' -Message 'Authorization TTL, authorization revocation, package revocation, and readback freshness must resolve four distinct canonical policy records.'
    }
    $packageVerificationRecord = Test-PackageVerificationBinding -RecordMap $recordMap `
        -Reference $Request.packageVerificationRef -Digest $Request.packageVerificationDigest `
        -ExpectedPackageDigest ([string]$Request.packageDigest) `
        -ExpectedRevocationFreshnessPolicyRef ([string]$Request.packageRevocationFreshnessPolicyRef) `
        -ExpectedRevocationFreshnessPolicyDigest ([string]$Request.packageRevocationFreshnessPolicyDigest) `
        -MaximumRevocationAgeMinutes $effectivePackageRevocationMaxAgeMinutes `
        -EvaluationTime $EvaluationTime -Errors $errors
    if ($null -ne $packageRevocationPolicyRecord -and $null -ne $packageVerificationRecord) {
        [DateTimeOffset]$packagePolicyApprovedAt = [DateTimeOffset]::MinValue
        [DateTimeOffset]$packagePolicyRevocationCheckedAt = [DateTimeOffset]::MinValue
        if (-not [OperationsBlueprint.StrictRfc3339]::TryParse([string]$packageRevocationPolicyRecord.approvedAt, [ref]$packagePolicyApprovedAt) -or
            -not [OperationsBlueprint.StrictRfc3339]::TryParse([string]$packageVerificationRecord.revocationCheckedAt, [ref]$packagePolicyRevocationCheckedAt) -or
            $packagePolicyApprovedAt -gt $packagePolicyRevocationCheckedAt) {
            Add-BlueprintError -Errors $errors -Code 'SECURITY_FRESHNESS_POLICY_CHRONOLOGY_INVALID' -Message 'Package revocation evidence cannot predate its authenticated freshness policy approval.'
        }
    }
    $directoryPopulationReadback = Test-TargetPopulationBinding -TargetPopulation $Request.targetPopulation `
        -RecordMap $recordMap -ExpectedTargetScopeRef ([string]$Request.targetScopeRef) `
        -ExpectedTenantBoundaryRef ([string]$Request.tenantBoundaryRef) `
        -ExpectedTargetEnvironmentRef ([string]$Request.targetEnvironmentRef) `
        -ExpectedTargetMembershipDigest ([string]$Request.targetMembershipDigest) `
        -ExpectedTargetRing ([string]$Request.targetRing) -ExpectedPersonaId ([string]$Request.personaId) `
        -ExpectedReadbackPolicyRef ([string]$Request.independentReadbackPolicyRef) `
        -WriteIdentityRef ([string]$Request.writeIdentityRef) -EvaluationTime $EvaluationTime `
        -MaximumAgeMinutes $effectiveReadbackMaxAgeMinutes `
        -Context 'activation request' -Errors $errors
    $roleBindingReadbackForClosure = Resolve-CanonicalRecord -RecordMap $recordMap `
        -Reference $Request.roleBindingReadbackRef -ExpectedTypes @('role-binding-readback-record') `
        -Context 'activation role-binding readback' -Errors $errors
    [int64]$roleBindingReadbackMaximumAge = if ($null -ne $roleBindingReadbackForClosure -and
        ($roleBindingReadbackForClosure.maxAgeMinutes -is [int] -or $roleBindingReadbackForClosure.maxAgeMinutes -is [long]) -and
        [int64]$roleBindingReadbackForClosure.maxAgeMinutes -gt 0) {
        [int64]$roleBindingReadbackForClosure.maxAgeMinutes
    }
    else { 0 }
    $roleBindingClosure = if ($null -ne $roleBindingReadbackForClosure -and $roleBindingReadbackMaximumAge -gt 0) {
        Test-RoleBindingClosure -RecordMap $recordMap `
            -RoleBindingRef ([string]$Request.roleBindingRef) -RoleBindingDigest ([string]$Request.roleBindingDigest) `
            -RoleBindingReadbackRef ([string]$Request.roleBindingReadbackRef) `
            -RoleBindingReadbackDigest ([string]$Request.roleBindingReadbackDigest) `
            -ExpectedTenantBoundaryRef ([string]$Request.tenantBoundaryRef) `
            -ExpectedTargetEnvironmentRef ([string]$Request.targetEnvironmentRef) `
            -ExpectedReadbackPolicyRef ([string]$roleBindingReadbackForClosure.readbackPolicyRef) `
            -ExpectedReadbackPolicyDigest ([string]$roleBindingReadbackForClosure.readbackPolicyDigest) `
            -ExpectedReadbackMaximumAgeMinutes $roleBindingReadbackMaximumAge `
            -EvaluationTime $EvaluationTime -Errors $errors
    }
    else { $null }
    $roleBindingBootstrapPolicyRecord = if ($null -ne $roleBindingReadbackForClosure) {
        Resolve-CanonicalRecord -RecordMap $recordMap -Reference $roleBindingReadbackForClosure.readbackPolicyRef `
            -ExpectedTypes @('security-freshness-policy-record') `
            -Context 'role-binding bootstrap freshness policy' -Errors $errors
    }
    else { $null }
    if ($null -ne $roleBindingClosure -and $null -ne $roleBindingBootstrapPolicyRecord) {
        [DateTimeOffset]$rolePolicyApprovedAt = [DateTimeOffset]::MinValue
        [DateTimeOffset]$roleObservedAt = [DateTimeOffset]::MinValue
        if (-not [OperationsBlueprint.StrictRfc3339]::TryParse([string]$roleBindingBootstrapPolicyRecord.approvedAt, [ref]$rolePolicyApprovedAt) -or
            -not [OperationsBlueprint.StrictRfc3339]::TryParse([string]$roleBindingClosure.Readback.observedAt, [ref]$roleObservedAt) -or
            $rolePolicyApprovedAt -gt $roleObservedAt) {
            Add-BlueprintError -Errors $errors -Code 'SECURITY_FRESHNESS_POLICY_CHRONOLOGY_INVALID' -Message 'Role-binding readback cannot predate approval of its authenticated readback-freshness policy.'
        }
    }

    if ($null -ne $transportRecord) {
        $expectedTransportPolicyDigest = Get-CanonicalPayloadDigest -Payload $Registry.intuneTransportOwnership
        Test-RequiredProperties -Object $transportRecord -Names @(
            'managedObjectType', 'targetScopeRef', 'writerToolRef', 'selectionStatus', 'governancePolicyDigest'
        ) -Context 'transport ownership record' -Errors $errors
        if ([string]$transportRecord.contentDigest -cne [string]$Request.transportOwnershipRecordDigest -or
            [string]$transportRecord.managedObjectType -cne [string]$Request.managedObjectType -or
            [string]$transportRecord.targetScopeRef -cne [string]$Request.targetScopeRef -or
            [string]$transportRecord.writerToolRef -cne [string]$Request.writerToolRef -or
            [string]$transportRecord.selectionStatus -cne 'APPROVED_OBJECT_TYPE_OWNER' -or
            [string]$transportRecord.governancePolicyDigest -cne [string]$expectedTransportPolicyDigest) {
            Add-BlueprintError -Errors $errors -Code 'TRANSPORT_OWNERSHIP_RECORD_MISMATCH' -Message 'Typed transport ownership does not bind the exact object type, scope, selected writer, and approved ownership map.'
        }
        if ([string]$Request.writerToolRef -ceq 'microsoft-graph-write') {
            Test-RequiredProperties -Object $transportRecord -Names @('exceptionRef','exceptionDigest') -Context 'direct Graph transport ownership' -Errors $errors
            if ([string]$transportRecord.exceptionRef -cne [string]$Request.transportExceptionRef -or
                [string]$transportRecord.exceptionDigest -cne [string]$Request.transportExceptionDigest) {
                Add-BlueprintError -Errors $errors -Code 'TRANSPORT_OWNERSHIP_RECORD_MISMATCH' -Message 'Direct Graph ownership does not bind the evaluated exception record.'
            }
        }
        elseif ((Test-ValuePresent $transportRecord.exceptionRef) -or (Test-ValuePresent $transportRecord.exceptionDigest)) {
            Add-BlueprintError -Errors $errors -Code 'DIRECT_GRAPH_EXCEPTION_FORBIDDEN' -Message 'Terraform-provider transport ownership may not retain a direct-Graph exception.'
        }
    }

    if ($null -ne $planRecord) {
        Test-RequiredProperties -Object $planRecord -Names @(
            'status', 'sourceCommit', 'desiredStateRevision', 'graphWriteRevision', 'atmosRenderDigest',
            'atmosStackRenderRef', 'atmosStackRenderDigest',
            'providerLockDigest', 'moduleLockDigest', 'variableSetDigest', 'observedStateSnapshotDigest',
            'policyResultsDigest',
            'packageDigest', 'packageVerificationRef', 'packageVerificationDigest',
            'targetMembershipDigest', 'targetPopulation', 'targetRing', 'targetScopeRef', 'managedObjectType',
            'writerToolRef', 'rollbackRef', 'tenantBoundaryRef', 'targetEnvironmentRef', 'planExpiresAt'
        ) -Context 'reviewed plan record' -Errors $errors
        if ([string]$Request.writerToolRef -ceq 'microsoft-graph-write') {
            Test-RequiredProperties -Object $planRecord -Names @('transportExceptionRef','transportExceptionDigest') -Context 'direct Graph reviewed plan' -Errors $errors
            if ([string]$planRecord.transportExceptionRef -cne [string]$Request.transportExceptionRef -or
                [string]$planRecord.transportExceptionDigest -cne [string]$Request.transportExceptionDigest) {
                Add-BlueprintError -Errors $errors -Code 'DIRECT_GRAPH_EXCEPTION_BINDING_MISMATCH' -Message 'Direct Graph reviewed plan does not bind the exact scoped provider-gap exception and digest.'
            }
        }
        elseif ((Test-ValuePresent $planRecord.transportExceptionRef) -or (Test-ValuePresent $planRecord.transportExceptionDigest)) {
            Add-BlueprintError -Errors $errors -Code 'DIRECT_GRAPH_EXCEPTION_FORBIDDEN' -Message 'Terraform-provider reviewed plans may not retain a direct-Graph exception.'
        }
        $planAtmosStackRender = Resolve-CanonicalRecord -RecordMap $recordMap -Reference $planRecord.atmosStackRenderRef `
            -ExpectedTypes @('atmos-stack-render-record') -Context 'reviewed-plan Atmos stack render' -Errors $errors
        [DateTimeOffset]$planExpiresAt = [DateTimeOffset]::MinValue
        if ([string]$planRecord.contentDigest -cne [string]$Request.reviewedPlanDigest -or
            [string]$planRecord.status -cne 'APPROVED' -or
            [string]$planRecord.desiredStateRevision -cne [string]$Request.desiredStateRevision -or
            [string]$planRecord.graphWriteRevision -cne [string]$Request.graphWriteRevision -or
            [string]$planRecord.packageDigest -cne [string]$Request.packageDigest -or
            [string]$planRecord.packageVerificationRef -cne [string]$Request.packageVerificationRef -or
            [string]$planRecord.packageVerificationDigest -cne [string]$Request.packageVerificationDigest -or
            [string]$planRecord.targetMembershipDigest -cne [string]$Request.targetMembershipDigest -or
            -not (Test-CanonicalValueEqual $planRecord.targetPopulation $Request.targetPopulation) -or
            [string]$planRecord.targetRing -cne [string]$Request.targetRing -or
            [string]$planRecord.targetScopeRef -cne [string]$Request.targetScopeRef -or
            [string]$planRecord.managedObjectType -cne [string]$Request.managedObjectType -or
            [string]$planRecord.writerToolRef -cne [string]$Request.writerToolRef -or
            ([string]$Request.writerToolRef -ceq 'microsoft-graph-write' -and
                ([string]$planRecord.transportExceptionRef -cne [string]$Request.transportExceptionRef -or
                 [string]$planRecord.transportExceptionDigest -cne [string]$Request.transportExceptionDigest)) -or
            ([string]$Request.writerToolRef -ceq 'msgraph-terraform-provider' -and
                ((Test-ValuePresent $planRecord.transportExceptionRef) -or
                 (Test-ValuePresent $planRecord.transportExceptionDigest))) -or
            [string]$planRecord.rollbackRef -cne [string]$Request.authorization.rollbackRef -or
            [string]$planRecord.sourceCommit -cnotmatch '^[0-9a-f]{40}([0-9a-f]{24})?$' -or
            -not (Test-Sha256Token $planRecord.atmosRenderDigest) -or
            $null -eq $planAtmosStackRender -or
            ($null -ne $planAtmosStackRender -and
                ([string]$planAtmosStackRender.contentDigest -cne [string]$planRecord.atmosStackRenderDigest -or
                 [string]$planAtmosStackRender.sourceCommit -cne [string]$planRecord.sourceCommit -or
                 [string]$planAtmosStackRender.tenantBoundaryRef -cne [string]$Request.tenantBoundaryRef -or
                 [string]$planAtmosStackRender.targetEnvironmentRef -cne [string]$Request.targetEnvironmentRef -or
                 [string]$planAtmosStackRender.renderedOutputDigest -cne [string]$planRecord.atmosRenderDigest)) -or
            -not (Test-Sha256Token $planRecord.providerLockDigest) -or
            -not (Test-Sha256Token $planRecord.moduleLockDigest) -or
            -not (Test-Sha256Token $planRecord.variableSetDigest) -or
            -not (Test-Sha256Token $planRecord.observedStateSnapshotDigest) -or
            -not (Test-Sha256Token $planRecord.policyResultsDigest) -or
            [string]$planRecord.tenantBoundaryRef -cne [string]$Request.tenantBoundaryRef -or
            [string]$planRecord.targetEnvironmentRef -cne [string]$Request.targetEnvironmentRef -or
            -not [OperationsBlueprint.StrictRfc3339]::TryParse([string]$planRecord.planExpiresAt, [ref]$planExpiresAt) -or $planExpiresAt -le $EvaluationTime) {
            Add-BlueprintError -Errors $errors -Code 'REVIEWED_PLAN_RECORD_MISMATCH' -Message 'Reviewed plan does not bind the exact desired state, composition, locks, variables, observation, package, scope, transport, rollback, tenant, and validity window.'
        }
    }

    [DateTimeOffset]$latestApprovalAt = [DateTimeOffset]::MinValue
    if ($null -ne $approvalRecord) {
        Test-RequiredProperties -Object $approvalRecord -Names @(
            'status', 'requestedStage', 'planDigest', 'targetScopeRef', 'managedObjectType',
            'requesterPrincipalRef', 'approvalEntries'
        ) -Context 'composite approval record' -Errors $errors
        if ([string]$approvalRecord.contentDigest -cne [string]$Request.approvalRecordDigest -or
            [string]$approvalRecord.status -cne 'APPROVED' -or
            [string]$approvalRecord.requestedStage -cne [string]$Request.requestedStage -or
            [string]$approvalRecord.planDigest -cne [string]$Request.reviewedPlanDigest -or
            [string]$approvalRecord.targetScopeRef -cne [string]$Request.targetScopeRef -or
            [string]$approvalRecord.managedObjectType -cne [string]$Request.managedObjectType -or
            [string]$approvalRecord.requesterPrincipalRef -cne [string]$Request.requesterPrincipalRef) {
            Add-BlueprintError -Errors $errors -Code 'APPROVAL_RECORD_BINDING_MISMATCH' -Message 'Composite approval record does not approve this stage, plan, scope, object type, and requester.'
        }
        $approvalEntries = @($approvalRecord.approvalEntries)
        $entryRoles = @($approvalEntries | ForEach-Object { [string]$_.roleId })
        if ($entryRoles.Count -ne @($Request.approvalRoleIds).Count) {
            Add-BlueprintError -Errors $errors -Code 'APPROVAL_SET_BINDING_MISMATCH' -Message 'Request approvalRoleIds do not match the retained composite approval set.'
        }
        foreach ($entryRole in $entryRoles) {
            if (@($Request.approvalRoleIds) -cnotcontains $entryRole -or $entryRole -cnotmatch '^ROLE_[A-Z0-9_]+$') {
                Add-BlueprintError -Errors $errors -Code 'APPROVAL_SET_BINDING_MISMATCH' -Message "Approval role $entryRole is absent from the request or is not canonical."
            }
        }
        $earliestApprovalExpiry = [DateTimeOffset]::MaxValue
        foreach ($requiredApprovalRole in $requiredApprovalRoles) {
            $entry = @($approvalEntries | Where-Object { [string]$_.roleId -ceq $requiredApprovalRole })
            if ($entry.Count -ne 1) {
                Add-BlueprintError -Errors $errors -Code 'APPROVAL_ROLE_MISSING' -Message "Typed approval set does not contain exactly one $requiredApprovalRole entry."
                continue
            }
            [DateTimeOffset]$entryExpiresAt = [DateTimeOffset]::MinValue
            [DateTimeOffset]$entryApprovedAt = [DateTimeOffset]::MinValue
            if ([string]$entry[0].decision -cne 'APPROVED' -or
                [string]$entry[0].principalRef -notmatch '^private://' -or
                [string]$entry[0].principalRef -ceq [string]$Request.requesterPrincipalRef -or
                [string]$entry[0].principalRef -ceq [string]$Request.writeIdentityRef -or
                -not [OperationsBlueprint.StrictRfc3339]::TryParse([string]$entry[0].approvedAt, [ref]$entryApprovedAt) -or $entryApprovedAt -gt $EvaluationTime -or
                -not [OperationsBlueprint.StrictRfc3339]::TryParse([string]$entry[0].expiresAt, [ref]$entryExpiresAt) -or $entryExpiresAt -le $EvaluationTime) {
                Add-BlueprintError -Errors $errors -Code 'APPROVAL_PRINCIPAL_OR_VALIDITY_INVALID' -Message "$requiredApprovalRole is not independently and currently approved."
            }
            else {
                if ($entryExpiresAt -lt $earliestApprovalExpiry) { $earliestApprovalExpiry = $entryExpiresAt }
                if ($entryApprovedAt -gt $latestApprovalAt) { $latestApprovalAt = $entryApprovedAt }
            }
        }
        [DateTimeOffset]$requestApprovalExpiry = [DateTimeOffset]::MinValue
        if (-not [OperationsBlueprint.StrictRfc3339]::TryParse([string]$Request.approvalExpiresAt, [ref]$requestApprovalExpiry) -or
            $earliestApprovalExpiry -ne [DateTimeOffset]::MaxValue -and $requestApprovalExpiry -ne $earliestApprovalExpiry) {
            Add-BlueprintError -Errors $errors -Code 'APPROVAL_EXPIRY_BINDING_MISMATCH' -Message 'Request approval expiry must equal the earliest retained approval-entry expiry.'
        }
        foreach ($principalGroup in @($approvalEntries | Group-Object -Property principalRef -CaseSensitive)) {
            if ($principalGroup.Count -gt 1) {
                Add-BlueprintError -Errors $errors -Code 'APPROVAL_PRINCIPAL_NOT_DISTINCT' -Message "Approval principal $($principalGroup.Name) holds multiple approval roles for one operation."
            }
        }
    }

    if ($null -ne $activationRecord) {
        Test-RequiredProperties -Object $activationRecord -Names @(
            'state', 'registryVersion', 'roleBindingRef', 'roleBindingDigest',
            'roleBindingReadbackRef', 'roleBindingReadbackDigest', 'transportOwnershipRef',
            'tenantBoundaryRef', 'targetEnvironmentRef', 'expiresAt'
        ) -Context 'private activation record' -Errors $errors
        [DateTimeOffset]$activationExpiresAt = [DateTimeOffset]::MinValue
        if ([string]$activationRecord.contentDigest -cne [string]$Request.privateActivationRecordDigest -or
            [string]$activationRecord.state -cne 'ACTIVE' -or
            [string]$activationRecord.registryVersion -cne [string]$Registry.registryVersion -or
            [string]$activationRecord.transportOwnershipRef -cne [string]$Request.transportOwnershipRecordRef -or
            [string]$activationRecord.roleBindingRef -cne [string]$Request.roleBindingRef -or
            [string]$activationRecord.roleBindingDigest -cne [string]$Request.roleBindingDigest -or
            [string]$activationRecord.roleBindingReadbackRef -cne [string]$Request.roleBindingReadbackRef -or
            [string]$activationRecord.roleBindingReadbackDigest -cne [string]$Request.roleBindingReadbackDigest -or
            [string]$activationRecord.tenantBoundaryRef -cne [string]$Request.tenantBoundaryRef -or
            [string]$activationRecord.targetEnvironmentRef -cne [string]$Request.targetEnvironmentRef -or
            -not [OperationsBlueprint.StrictRfc3339]::TryParse([string]$activationRecord.expiresAt, [ref]$activationExpiresAt) -or $activationExpiresAt -le $EvaluationTime) {
            Add-BlueprintError -Errors $errors -Code 'PRIVATE_ACTIVATION_RECORD_MISMATCH' -Message 'Private activation record is not current or bound to the exact registry, roles, transport ownership, and environment.'
        }
    }

    [DateTimeOffset]$writeAuthorizationIssuedAt = [DateTimeOffset]::MinValue
    [DateTimeOffset]$writeAuthorizationNotBefore = [DateTimeOffset]::MinValue
    [DateTimeOffset]$writeAuthorizationExpiresAt = [DateTimeOffset]::MinValue
    if ($null -ne $writeAuthorizationRecord) {
        $writeAuthorizationFields = @(
            'schemaVersion', 'recordStage', 'status', 'authorizationId', 'authorizationNonce', 'maxUses',
            'authorizedOperationId', 'consumptionLedgerRef', 'consumptionLedgerPolicyRef',
            'consumptionLedgerPolicyDigest',
            'requestedStage', 'requestDigest', 'approvalRef', 'approvalDigest', 'activationRef',
            'activationDigest', 'roleBindingRef', 'roleBindingDigest', 'roleBindingReadbackRef',
            'roleBindingReadbackDigest', 'pilotAuthorizationRef', 'pilotAuthorizationDigest', 'stopConditionsRef',
            'stopConditionsDigest', 'rollbackRef', 'rollbackDigest', 'reviewedPlanRef', 'reviewedPlanDigest',
            'transportOwnershipRef', 'transportOwnershipDigest', 'packageVerificationRef',
            'packageVerificationDigest', 'independentReadbackPolicyRef', 'independentReadbackPolicyDigest', 'readbackMaxAgeMinutes',
            'authorizationTtlPolicyRef', 'authorizationTtlPolicyDigest', 'authorizationMaxTtlMinutes',
            'authorizationRevocationFreshnessPolicyRef', 'authorizationRevocationFreshnessPolicyDigest',
            'authorizationRevocationCheckMaxAgeMinutes',
            'writerToolRef', 'writeIdentityRef', 'applyOperatorIdentityRef', 'managedObjectType',
            'managedObjectRefs', 'managedObjectSetDigest',
            'tenantBoundaryRef', 'targetEnvironmentRef', 'targetScopeRef', 'desiredStateRevision', 'packageDigest', 'targetMembershipDigest',
            'targetPopulation', 'issuedByRole', 'issuedByPrincipalRef', 'authorizationSubjectDigest',
            'authorizationArtifactRef', 'authorizationArtifactDigest', 'issuerSignatureRef',
            'issuerSignatureDigest', 'issuerSignatureStatus', 'revocationStatus', 'revocationEvidenceRef',
            'revocationEvidenceDigest', 'revocationCheckedAt', 'issuedAt', 'notBefore', 'expiresAt', 'singleUse'
        )
        if ([string]$Request.requestedStage -ceq 'PRODUCTION') {
            $writeAuthorizationFields += @(
                'rolloutMonitoringRef', 'rolloutMonitoringDigest', 'semanticValidationRef',
                'semanticValidationDigest', 'decisionClaimRef', 'decisionClaimDigest'
            )
        }
        if ([string]$Request.writerToolRef -ceq 'microsoft-graph-write') {
            $writeAuthorizationFields += @('transportExceptionRef','transportExceptionDigest')
        }
        Test-RequiredProperties -Object $writeAuthorizationRecord -Names $writeAuthorizationFields -Context 'pre-write authorization record' -Errors $errors
        $expectedRequestDigest = Get-WriteAuthorizationRequestDigest -Request $Request
        if ([string]$writeAuthorizationRecord.requestDigest -cne [string]$expectedRequestDigest) {
            Add-BlueprintError -Errors $errors -Code 'WRITE_AUTHORIZATION_REQUEST_DIGEST_MISMATCH' -Message 'Pre-write authorization does not bind the exact current activation-request intent.'
        }
        if ([string]$Request.writerToolRef -ceq 'microsoft-graph-write' -and
            ([string]$writeAuthorizationRecord.transportExceptionRef -cne [string]$Request.transportExceptionRef -or
             [string]$writeAuthorizationRecord.transportExceptionDigest -cne [string]$Request.transportExceptionDigest)) {
            Add-BlueprintError -Errors $errors -Code 'DIRECT_GRAPH_EXCEPTION_BINDING_MISMATCH' -Message 'Direct Graph write authorization does not bind the exact scoped provider-gap exception and digest.'
        }
        elseif ([string]$Request.writerToolRef -ceq 'msgraph-terraform-provider' -and
            ((Test-ValuePresent $writeAuthorizationRecord.transportExceptionRef) -or
             (Test-ValuePresent $writeAuthorizationRecord.transportExceptionDigest))) {
            Add-BlueprintError -Errors $errors -Code 'DIRECT_GRAPH_EXCEPTION_FORBIDDEN' -Message 'Terraform-provider write authorization may not retain a direct-Graph exception.'
        }
        $authorizationTimesValid = [OperationsBlueprint.StrictRfc3339]::TryParse([string]$writeAuthorizationRecord.issuedAt, [ref]$writeAuthorizationIssuedAt) -and
            [OperationsBlueprint.StrictRfc3339]::TryParse([string]$writeAuthorizationRecord.notBefore, [ref]$writeAuthorizationNotBefore) -and
            [OperationsBlueprint.StrictRfc3339]::TryParse([string]$writeAuthorizationRecord.expiresAt, [ref]$writeAuthorizationExpiresAt)
        [DateTimeOffset]$writeAuthorizationRevocationCheckedAt = [DateTimeOffset]::MinValue
        $authorizationRevocationTimeValid = [OperationsBlueprint.StrictRfc3339]::TryParse(
            [string]$writeAuthorizationRecord.revocationCheckedAt,
            [ref]$writeAuthorizationRevocationCheckedAt
        )
        [DateTimeOffset]$packageVerifiedAt = [DateTimeOffset]::MinValue
        $packageVerifiedTimeValid = $null -ne $packageVerificationRecord -and
            [OperationsBlueprint.StrictRfc3339]::TryParse([string]$packageVerificationRecord.verifiedAt, [ref]$packageVerifiedAt)
        [DateTimeOffset]$authorizationDirectoryReadbackAt = [DateTimeOffset]::MinValue
        $authorizationDirectoryChronologyValid = $null -ne $directoryPopulationReadback -and
            [OperationsBlueprint.StrictRfc3339]::TryParse([string]$directoryPopulationReadback.collectedAt, [ref]$authorizationDirectoryReadbackAt) -and
            $authorizationDirectoryReadbackAt -le $writeAuthorizationIssuedAt -and
            ($writeAuthorizationIssuedAt - $authorizationDirectoryReadbackAt).TotalMinutes -le $effectiveReadbackMaxAgeMinutes
        [DateTimeOffset]$authorizationRoleReadbackAt = [DateTimeOffset]::MinValue
        $authorizationRoleReadbackChronologyValid = $null -ne $roleBindingClosure -and
            [OperationsBlueprint.StrictRfc3339]::TryParse([string]$roleBindingClosure.Readback.observedAt, [ref]$authorizationRoleReadbackAt) -and
            $authorizationRoleReadbackAt -le $writeAuthorizationIssuedAt -and
            ($writeAuthorizationIssuedAt - $authorizationRoleReadbackAt).TotalMinutes -le $effectiveReadbackMaxAgeMinutes
        [DateTimeOffset]$readbackPolicyApprovedAt = [DateTimeOffset]::MinValue
        $readbackPolicyChronologyValid = $null -ne $readbackFreshnessPolicyRecord -and
            [OperationsBlueprint.StrictRfc3339]::TryParse([string]$readbackFreshnessPolicyRecord.approvedAt, [ref]$readbackPolicyApprovedAt) -and
            $readbackPolicyApprovedAt -le $writeAuthorizationIssuedAt
        $expectedAuthorizationSubjectDigest = Get-WriteAuthorizationSubjectDigest -Authorization $writeAuthorizationRecord
        $authorizationIssuerAttestationValid =
            [string]$writeAuthorizationRecord.issuedByRole -ceq 'ROLE_PROTECTED_ENVIRONMENT_APPROVER' -and
            [string]$writeAuthorizationRecord.issuedByPrincipalRef -cmatch '^private://' -and
            [string]$writeAuthorizationRecord.authorizationSubjectDigest -ceq $expectedAuthorizationSubjectDigest -and
            [string]$writeAuthorizationRecord.authorizationArtifactRef -cmatch '^private://' -and
            [string]$writeAuthorizationRecord.authorizationArtifactDigest -ceq $expectedAuthorizationSubjectDigest -and
            [string]$writeAuthorizationRecord.issuerSignatureRef -cmatch '^private://' -and
            (Test-Sha256Token $writeAuthorizationRecord.issuerSignatureDigest) -and
            [string]$writeAuthorizationRecord.issuerSignatureStatus -ceq 'VERIFIED'
        if (-not $authorizationIssuerAttestationValid) {
            Add-BlueprintError -Errors $errors -Code 'WRITE_AUTHORIZATION_ISSUER_ATTESTATION_INVALID' -Message 'Pre-write authorization must carry a verified protected-environment issuer signature over the recomputed exact authorization subject and artifact.'
        }
        if ([string]$writeAuthorizationRecord.contentDigest -cne [string]$Request.writeAuthorizationDigest -or
            [string]$writeAuthorizationRecord.schemaVersion -cne '1.0.0' -or
            [string]$writeAuthorizationRecord.recordStage -cne 'PRE_WRITE_AUTHORIZATION' -or
            [string]$writeAuthorizationRecord.status -cne 'ISSUED' -or
            -not (Test-NonBlankString $writeAuthorizationRecord.authorizationId) -or
            -not (Test-NonBlankString $writeAuthorizationRecord.authorizationNonce) -or
            [string]$writeAuthorizationRecord.authorizationNonce -ceq [string]$writeAuthorizationRecord.authorizationId -or
            ($writeAuthorizationRecord.maxUses -isnot [int] -and $writeAuthorizationRecord.maxUses -isnot [long]) -or
            [int64]$writeAuthorizationRecord.maxUses -ne 1 -or
            [string]$writeAuthorizationRecord.authorizedOperationId -cne [string]$Request.writeOperationId -or
            [string]$writeAuthorizationRecord.consumptionLedgerRef -cne [string]$Request.consumptionLedgerRef -or
            [string]$writeAuthorizationRecord.consumptionLedgerPolicyRef -cne [string]$Request.consumptionLedgerPolicyRef -or
            [string]$writeAuthorizationRecord.consumptionLedgerPolicyDigest -cne [string]$Request.consumptionLedgerPolicyDigest -or
            [string]$writeAuthorizationRecord.requestedStage -cne [string]$Request.requestedStage -or
            [string]$writeAuthorizationRecord.requestDigest -cne [string]$expectedRequestDigest -or
            [string]$writeAuthorizationRecord.approvalRef -cne [string]$Request.protectedApprovalRef -or
            [string]$writeAuthorizationRecord.approvalDigest -cne [string]$Request.approvalRecordDigest -or
            [string]$writeAuthorizationRecord.activationRef -cne [string]$Request.privateActivationRecordRef -or
            [string]$writeAuthorizationRecord.activationDigest -cne [string]$Request.privateActivationRecordDigest -or
            [string]$writeAuthorizationRecord.roleBindingRef -cne [string]$Request.roleBindingRef -or
            [string]$writeAuthorizationRecord.roleBindingDigest -cne [string]$Request.roleBindingDigest -or
            [string]$writeAuthorizationRecord.roleBindingReadbackRef -cne [string]$Request.roleBindingReadbackRef -or
            [string]$writeAuthorizationRecord.roleBindingReadbackDigest -cne [string]$Request.roleBindingReadbackDigest -or
            [string]$writeAuthorizationRecord.pilotAuthorizationRef -cne [string]$Request.authorization.pilotAuthorizationRef -or
            [string]$writeAuthorizationRecord.pilotAuthorizationDigest -cne [string]$Request.authorization.pilotAuthorizationDigest -or
            [string]$writeAuthorizationRecord.stopConditionsRef -cne [string]$Request.authorization.stopConditionsRef -or
            [string]$writeAuthorizationRecord.stopConditionsDigest -cne [string]$Request.authorization.stopConditionsDigest -or
            [string]$writeAuthorizationRecord.rollbackRef -cne [string]$Request.authorization.rollbackRef -or
            [string]$writeAuthorizationRecord.rollbackDigest -cne [string]$Request.authorization.rollbackDigest -or
            [string]$writeAuthorizationRecord.reviewedPlanRef -cne [string]$Request.reviewedPlanRef -or
            [string]$writeAuthorizationRecord.reviewedPlanDigest -cne [string]$Request.reviewedPlanDigest -or
            [string]$writeAuthorizationRecord.transportOwnershipRef -cne [string]$Request.transportOwnershipRecordRef -or
            [string]$writeAuthorizationRecord.transportOwnershipDigest -cne [string]$Request.transportOwnershipRecordDigest -or
            ([string]$Request.writerToolRef -ceq 'microsoft-graph-write' -and
                ([string]$writeAuthorizationRecord.transportExceptionRef -cne [string]$Request.transportExceptionRef -or
                 [string]$writeAuthorizationRecord.transportExceptionDigest -cne [string]$Request.transportExceptionDigest)) -or
            ([string]$Request.writerToolRef -ceq 'msgraph-terraform-provider' -and
                ((Test-ValuePresent $writeAuthorizationRecord.transportExceptionRef) -or
                 (Test-ValuePresent $writeAuthorizationRecord.transportExceptionDigest))) -or
            [string]$writeAuthorizationRecord.packageVerificationRef -cne [string]$Request.packageVerificationRef -or
            [string]$writeAuthorizationRecord.packageVerificationDigest -cne [string]$Request.packageVerificationDigest -or
            [string]$writeAuthorizationRecord.independentReadbackPolicyRef -cne [string]$Request.independentReadbackPolicyRef -or
            [string]$writeAuthorizationRecord.independentReadbackPolicyDigest -cne [string]$Request.independentReadbackPolicyDigest -or
            [string]$writeAuthorizationRecord.readbackMaxAgeMinutes -cne [string]$Request.readbackMaxAgeMinutes -or
            [string]$writeAuthorizationRecord.authorizationTtlPolicyRef -cne [string]$Request.authorizationTtlPolicyRef -or
            [string]$writeAuthorizationRecord.authorizationTtlPolicyDigest -cne [string]$Request.authorizationTtlPolicyDigest -or
            [string]$writeAuthorizationRecord.authorizationMaxTtlMinutes -cne [string]$Request.authorizationMaxTtlMinutes -or
            [string]$writeAuthorizationRecord.authorizationRevocationFreshnessPolicyRef -cne [string]$Request.authorizationRevocationFreshnessPolicyRef -or
            [string]$writeAuthorizationRecord.authorizationRevocationFreshnessPolicyDigest -cne [string]$Request.authorizationRevocationFreshnessPolicyDigest -or
            [string]$writeAuthorizationRecord.authorizationRevocationCheckMaxAgeMinutes -cne [string]$Request.authorizationRevocationCheckMaxAgeMinutes -or
            [string]$writeAuthorizationRecord.writerToolRef -cne [string]$Request.writerToolRef -or
            [string]$writeAuthorizationRecord.writeIdentityRef -cne [string]$Request.writeIdentityRef -or
            [string]$writeAuthorizationRecord.applyOperatorIdentityRef -cne [string]$Request.applyOperatorIdentityRef -or
            [string]$writeAuthorizationRecord.managedObjectType -cne [string]$Request.managedObjectType -or
            -not (Test-CanonicalValueEqual @($writeAuthorizationRecord.managedObjectRefs) @($Request.managedObjectRefs)) -or
            [string]$writeAuthorizationRecord.managedObjectSetDigest -cne [string]$Request.managedObjectSetDigest -or
            [string]$writeAuthorizationRecord.managedObjectSetDigest -cne [string]$expectedManagedObjectSetDigest -or
            [string]$writeAuthorizationRecord.tenantBoundaryRef -cne [string]$Request.tenantBoundaryRef -or
            [string]$writeAuthorizationRecord.targetEnvironmentRef -cne [string]$Request.targetEnvironmentRef -or
            [string]$writeAuthorizationRecord.targetScopeRef -cne [string]$Request.targetScopeRef -or
            [string]$writeAuthorizationRecord.desiredStateRevision -cne [string]$Request.desiredStateRevision -or
            [string]$writeAuthorizationRecord.packageDigest -cne [string]$Request.packageDigest -or
            [string]$writeAuthorizationRecord.targetMembershipDigest -cne [string]$Request.targetMembershipDigest -or
            -not (Test-CanonicalValueEqual $writeAuthorizationRecord.targetPopulation $Request.targetPopulation) -or
            -not $authorizationIssuerAttestationValid -or
            [string]$writeAuthorizationRecord.revocationStatus -cne 'NOT_REVOKED' -or
            [string]$writeAuthorizationRecord.revocationEvidenceRef -cnotmatch '^private://' -or
            -not (Test-Sha256Token $writeAuthorizationRecord.revocationEvidenceDigest) -or
            $writeAuthorizationRecord.singleUse -ne $true -or -not $authorizationTimesValid -or
            -not $authorizationRevocationTimeValid -or
            -not $authorizationDirectoryChronologyValid -or
            -not $authorizationRoleReadbackChronologyValid -or
            -not $readbackPolicyChronologyValid -or
            $writeAuthorizationRevocationCheckedAt -gt $writeAuthorizationIssuedAt -or
            $writeAuthorizationIssuedAt -gt $writeAuthorizationNotBefore -or
            $writeAuthorizationNotBefore -gt $EvaluationTime -or
            $writeAuthorizationExpiresAt -le $EvaluationTime -or
            ($latestApprovalAt -ne [DateTimeOffset]::MinValue -and $writeAuthorizationIssuedAt -lt $latestApprovalAt) -or
            ($packageVerifiedTimeValid -and $packageVerifiedAt -gt $writeAuthorizationIssuedAt)) {
            Add-BlueprintError -Errors $errors -Code 'PREWRITE_AUTHORIZATION_BINDING_INVALID' -Message 'Pre-write authorization must be current, single-use, approval-after, package-verified, and bind the exact nonce, operation, stage, plan, transport, package, scope, population, identity, gates, and request digest.'
        }
        $authorizationTtlFieldsValid = $authorizationMaxTtlValid -and
            ($writeAuthorizationRecord.authorizationMaxTtlMinutes -is [int] -or $writeAuthorizationRecord.authorizationMaxTtlMinutes -is [long]) -and
            [int64]$writeAuthorizationRecord.authorizationMaxTtlMinutes -eq $effectiveAuthorizationMaxTtlMinutes -and
            [string]$writeAuthorizationRecord.authorizationTtlPolicyRef -ceq [string]$Request.authorizationTtlPolicyRef -and
            [string]$writeAuthorizationRecord.authorizationTtlPolicyDigest -ceq [string]$Request.authorizationTtlPolicyDigest -and
            [string]$writeAuthorizationRecord.authorizationTtlPolicyRef -cmatch '^private://' -and
            (Test-Sha256Token $writeAuthorizationRecord.authorizationTtlPolicyDigest)
        [DateTimeOffset]$authorizationTtlPolicyApprovedAt = [DateTimeOffset]::MinValue
        $authorizationTtlPolicyChronologyValid = $null -ne $authorizationTtlPolicyRecord -and
            [OperationsBlueprint.StrictRfc3339]::TryParse([string]$authorizationTtlPolicyRecord.approvedAt, [ref]$authorizationTtlPolicyApprovedAt) -and
            $authorizationTtlPolicyApprovedAt -le $writeAuthorizationIssuedAt
        if (-not $authorizationTtlFieldsValid -or -not $authorizationTimesValid -or
            -not $authorizationTtlPolicyChronologyValid -or
            ($writeAuthorizationExpiresAt - $writeAuthorizationIssuedAt).TotalMinutes -gt $effectiveAuthorizationMaxTtlMinutes) {
            Add-BlueprintError -Errors $errors -Code 'AUTHORIZATION_TTL_POLICY_VIOLATION' -Message 'Authorization validity must bind the frozen TTL policy and not exceed its exact maximum.'
        }
        $authorizationRevocationPolicyValid = $authorizationRevocationMaxAgeValid -and
            ($writeAuthorizationRecord.authorizationRevocationCheckMaxAgeMinutes -is [int] -or $writeAuthorizationRecord.authorizationRevocationCheckMaxAgeMinutes -is [long]) -and
            [int64]$writeAuthorizationRecord.authorizationRevocationCheckMaxAgeMinutes -eq $effectiveAuthorizationRevocationMaxAgeMinutes -and
            [string]$writeAuthorizationRecord.authorizationRevocationFreshnessPolicyRef -ceq [string]$Request.authorizationRevocationFreshnessPolicyRef -and
            [string]$writeAuthorizationRecord.authorizationRevocationFreshnessPolicyDigest -ceq [string]$Request.authorizationRevocationFreshnessPolicyDigest -and
            [string]$writeAuthorizationRecord.authorizationRevocationFreshnessPolicyRef -cmatch '^private://' -and
            (Test-Sha256Token $writeAuthorizationRecord.authorizationRevocationFreshnessPolicyDigest)
        [DateTimeOffset]$authorizationRevocationPolicyApprovedAt = [DateTimeOffset]::MinValue
        $authorizationRevocationPolicyChronologyValid = $null -ne $authorizationRevocationPolicyRecord -and
            [OperationsBlueprint.StrictRfc3339]::TryParse([string]$authorizationRevocationPolicyRecord.approvedAt, [ref]$authorizationRevocationPolicyApprovedAt) -and
            $authorizationRevocationPolicyApprovedAt -le $writeAuthorizationRevocationCheckedAt
        if (-not $authorizationRevocationPolicyValid -or -not $authorizationRevocationTimeValid -or
            -not $authorizationRevocationPolicyChronologyValid -or
            ($EvaluationTime - $writeAuthorizationRevocationCheckedAt).TotalMinutes -gt $effectiveAuthorizationRevocationMaxAgeMinutes) {
            Add-BlueprintError -Errors $errors -Code 'AUTHORIZATION_REVOCATION_EVIDENCE_STALE_OR_POLICY_MISMATCH' -Message 'Authorization revocation evidence must bind the frozen freshness policy and remain within its exact maximum age.'
        }
        if ([string]$Request.requestedStage -ceq 'PRODUCTION') {
            $authorizationMonitor = Resolve-CanonicalRecord -RecordMap $recordMap -Reference $writeAuthorizationRecord.rolloutMonitoringRef -ExpectedTypes @('rollout-monitoring-record') -Context 'write authorization rollout monitoring' -Errors $errors
            $authorizationSemantic = Resolve-CanonicalRecord -RecordMap $recordMap -Reference $writeAuthorizationRecord.semanticValidationRef -ExpectedTypes @('semantic-validation-record') -Context 'write authorization semantic validation' -Errors $errors
            $authorizationDecision = Resolve-CanonicalRecord -RecordMap $recordMap -Reference $writeAuthorizationRecord.decisionClaimRef -ExpectedTypes @('decision-claim-record') -Context 'write authorization decision claim' -Errors $errors
            $authorizationRender = if ($null -ne $authorizationMonitor) {
                Resolve-CanonicalRecord -RecordMap $recordMap -Reference $authorizationMonitor.renderManifestRef -ExpectedTypes @('render-manifest-record') -Context 'write authorization leadership render manifest' -Errors $errors
            }
            else { $null }
            if ([string]$writeAuthorizationRecord.rolloutMonitoringRef -cne [string]$Request.rolloutMonitoringRef -or
                [string]$writeAuthorizationRecord.rolloutMonitoringDigest -cne [string]$Request.rolloutMonitoringRecordDigest -or
                ($null -ne $authorizationMonitor -and
                    ([string]$authorizationMonitor.semanticValidationRef -cne [string]$writeAuthorizationRecord.semanticValidationRef -or
                     [string]$authorizationMonitor.decisionClaimRef -cne [string]$writeAuthorizationRecord.decisionClaimRef -or
                     -not (Test-Sha256Token $authorizationMonitor.renderManifestDigest))) -or
                ($null -ne $authorizationSemantic -and [string]$authorizationSemantic.contentDigest -cne [string]$writeAuthorizationRecord.semanticValidationDigest) -or
                ($null -ne $authorizationDecision -and
                    ([string]$authorizationDecision.contentDigest -cne [string]$writeAuthorizationRecord.decisionClaimDigest -or
                     [string]$authorizationDecision.decisionAction -cnotin @('BUY', 'BUY_WITH_CONDITIONS'))) -or
                ($null -ne $authorizationRender -and
                    [string]$authorizationRender.contentDigest -cne [string]$authorizationMonitor.renderManifestDigest)) {
                Add-BlueprintError -Errors $errors -Code 'PRODUCTION_WRITE_AUTHORIZATION_DECISION_MISMATCH' -Message 'Production write authorization must bind the exact rollout monitor, passing semantic decision, and deterministic BUY or BUY_WITH_CONDITIONS claim.'
            }
        }
        $authorizationNonceOwners = @($recordMap.Values | Where-Object {
            [string]$_.recordType -ceq 'write-authorization-record' -and
            [string]$_.authorizationNonce -ceq [string]$writeAuthorizationRecord.authorizationNonce
        })
        $authorizationConsumers = @($recordMap.Values | Where-Object {
            [string]$_.recordType -ceq 'write-operation-record' -and
            ([string]$_.writeAuthorizationRef -ceq [string]$Request.writeAuthorizationRef -or
             [string]$_.authorizationId -ceq [string]$writeAuthorizationRecord.authorizationId -or
             [string]$_.authorizationNonce -ceq [string]$writeAuthorizationRecord.authorizationNonce -or
             ($null -ne $writeOperationRecord -and
              [string]$_.authorizationConsumptionRef -ceq [string]$writeOperationRecord.authorizationConsumptionRef))
        })
        if ($authorizationNonceOwners.Count -ne 1 -or $authorizationConsumers.Count -ne 1) {
            Add-BlueprintError -Errors $errors -Code 'WRITE_AUTHORIZATION_REPLAY_OR_REUSE' -Message 'A single-use authorization nonce must bind exactly one retained write operation.'
        }
    }

    $authorizationConsumptionRecord = $null
    [DateTimeOffset]$authorizationConsumedAt = [DateTimeOffset]::MinValue
    if ($null -ne $writeOperationRecord -and (Test-ValuePresent $writeOperationRecord.authorizationConsumptionRef)) {
        $authorizationConsumptionRecord = Resolve-CanonicalRecord -RecordMap $recordMap `
            -Reference $writeOperationRecord.authorizationConsumptionRef `
            -ExpectedTypes @('authorization-consumption-record') `
            -Context 'authoritative authorization consumption' -Errors $errors
    }
    if ($null -ne $authorizationConsumptionRecord) {
        Test-RequiredProperties -Object $authorizationConsumptionRecord -Names @(
            'schemaVersion', 'recordStage', 'status', 'consumptionLedgerRef',
            'consumptionLedgerPolicyRef', 'consumptionLedgerPolicyDigest', 'ledgerAuthorityIdentityRef',
            'ledgerAuthorityRole', 'authorizationRef', 'authorizationDigest', 'authorizationId',
            'authorizationNonce', 'authorizedOperationId', 'managedObjectSetDigest', 'maxUses',
            'authorizationUseCount', 'consumptionLedgerSequence', 'previousLedgerEntryDigest',
            'consumptionLedgerDigest', 'replayCheckStatus', 'atomicCommitEvidenceRef',
            'atomicCommitEvidenceDigest', 'consumedAt', 'independentReadbackPolicyRef',
            'independentReadbackPolicyDigest'
        ) -Context 'authoritative authorization-consumption record' -Errors $errors
        $consumptionTimeValid = [OperationsBlueprint.StrictRfc3339]::TryParse(
            [string]$authorizationConsumptionRecord.consumedAt,
            [ref]$authorizationConsumedAt
        )
        $consumptionSequenceValid = ($authorizationConsumptionRecord.consumptionLedgerSequence -is [int] -or
            $authorizationConsumptionRecord.consumptionLedgerSequence -is [long]) -and
            [int64]$authorizationConsumptionRecord.consumptionLedgerSequence -ge 1
        if ([string]$authorizationConsumptionRecord.schemaVersion -cne '1.0.0' -or
            [string]$authorizationConsumptionRecord.recordStage -cne 'AUTHORIZATION_CONSUMPTION' -or
            [string]$authorizationConsumptionRecord.status -cne 'COMMITTED' -or
            [string]$authorizationConsumptionRecord.consumptionLedgerRef -cne [string]$Request.consumptionLedgerRef -or
            [string]$authorizationConsumptionRecord.consumptionLedgerPolicyRef -cne [string]$Request.consumptionLedgerPolicyRef -or
            [string]$authorizationConsumptionRecord.consumptionLedgerPolicyDigest -cne [string]$Request.consumptionLedgerPolicyDigest -or
            [string]$authorizationConsumptionRecord.ledgerAuthorityIdentityRef -cnotmatch '^private://' -or
            [string]$authorizationConsumptionRecord.ledgerAuthorityIdentityRef -ceq [string]$Request.writeIdentityRef -or
            [string]$authorizationConsumptionRecord.ledgerAuthorityIdentityRef -ceq [string]$Request.requesterPrincipalRef -or
            [string]$authorizationConsumptionRecord.ledgerAuthorityRole -cne 'ROLE_AUTHORIZATION_LEDGER_OWNER' -or
            [string]$authorizationConsumptionRecord.authorizationRef -cne [string]$Request.writeAuthorizationRef -or
            [string]$authorizationConsumptionRecord.authorizationDigest -cne [string]$Request.writeAuthorizationDigest -or
            ($null -ne $writeAuthorizationRecord -and [string]$authorizationConsumptionRecord.authorizationId -cne [string]$writeAuthorizationRecord.authorizationId) -or
            ($null -ne $writeAuthorizationRecord -and [string]$authorizationConsumptionRecord.authorizationNonce -cne [string]$writeAuthorizationRecord.authorizationNonce) -or
            [string]$authorizationConsumptionRecord.authorizedOperationId -cne [string]$Request.writeOperationId -or
            [string]$authorizationConsumptionRecord.managedObjectSetDigest -cne [string]$Request.managedObjectSetDigest -or
            ($authorizationConsumptionRecord.maxUses -isnot [int] -and $authorizationConsumptionRecord.maxUses -isnot [long]) -or
            [int64]$authorizationConsumptionRecord.maxUses -ne 1 -or
            ($authorizationConsumptionRecord.authorizationUseCount -isnot [int] -and $authorizationConsumptionRecord.authorizationUseCount -isnot [long]) -or
            [int64]$authorizationConsumptionRecord.authorizationUseCount -ne 1 -or
            -not $consumptionSequenceValid -or
            -not (Test-Sha256Token $authorizationConsumptionRecord.previousLedgerEntryDigest) -or
            -not (Test-Sha256Token $authorizationConsumptionRecord.consumptionLedgerDigest) -or
            [string]$authorizationConsumptionRecord.previousLedgerEntryDigest -ceq [string]$authorizationConsumptionRecord.consumptionLedgerDigest -or
            [string]$authorizationConsumptionRecord.replayCheckStatus -cne 'NOT_REUSED' -or
            [string]$authorizationConsumptionRecord.atomicCommitEvidenceRef -cnotmatch '^private://' -or
            -not (Test-Sha256Token $authorizationConsumptionRecord.atomicCommitEvidenceDigest) -or
            [string]$authorizationConsumptionRecord.independentReadbackPolicyRef -cne [string]$Request.independentReadbackPolicyRef -or
            [string]$authorizationConsumptionRecord.independentReadbackPolicyDigest -cne [string]$Request.independentReadbackPolicyDigest -or
            -not $consumptionTimeValid -or
            ($null -ne $writeAuthorizationRecord -and $authorizationConsumedAt -lt $writeAuthorizationNotBefore) -or
            ($null -ne $writeAuthorizationRecord -and $authorizationConsumedAt -ge $writeAuthorizationExpiresAt) -or
            ($null -ne $writeAuthorizationRecord -and $authorizationConsumedAt -lt $writeAuthorizationRevocationCheckedAt) -or
            $authorizationConsumedAt -gt $EvaluationTime) {
            Add-BlueprintError -Errors $errors -Code 'AUTHORIZATION_CONSUMPTION_RECORD_INVALID' -Message 'Authorization consumption must be a current ledger-authority-attested atomic commit bound to the exact authorization ID, digest, nonce, operation, one-use limit, object set, ledger policy, replay result, readback policy, and validity window.'
        }
        $sameNonceConsumptions = @($recordMap.Values | Where-Object {
            [string]$_.recordType -ceq 'authorization-consumption-record' -and
            [string]$_.authorizationNonce -ceq [string]$authorizationConsumptionRecord.authorizationNonce -and
            [string]$_.status -ceq 'COMMITTED'
        })
        $sameLedgerSequence = @($recordMap.Values | Where-Object {
            [string]$_.recordType -ceq 'authorization-consumption-record' -and
            [string]$_.consumptionLedgerRef -ceq [string]$authorizationConsumptionRecord.consumptionLedgerRef -and
            [string]$_.consumptionLedgerSequence -ceq [string]$authorizationConsumptionRecord.consumptionLedgerSequence -and
            [string]$_.status -ceq 'COMMITTED'
        })
        if ($sameNonceConsumptions.Count -ne 1 -or $sameLedgerSequence.Count -ne 1) {
            Add-BlueprintError -Errors $errors -Code 'WRITE_AUTHORIZATION_REPLAY_OR_REUSE' -Message 'The authoritative ledger reports an omitted, duplicate, or replayed authorization nonce or sequence.'
        }
        if ($consumptionSequenceValid -and [int64]$authorizationConsumptionRecord.consumptionLedgerSequence -gt 1) {
            $expectedPreviousSequence = [int64]$authorizationConsumptionRecord.consumptionLedgerSequence - 1
            $previousLedgerEntries = @($recordMap.Values | Where-Object {
                [string]$_.recordType -ceq 'authorization-consumption-record' -and
                [string]$_.consumptionLedgerRef -ceq [string]$authorizationConsumptionRecord.consumptionLedgerRef -and
                [string]$_.status -ceq 'COMMITTED' -and
                [string]$_.consumptionLedgerSequence -ceq [string]$expectedPreviousSequence -and
                [string]$_.consumptionLedgerDigest -ceq [string]$authorizationConsumptionRecord.previousLedgerEntryDigest
            })
            if ($previousLedgerEntries.Count -ne 1) {
                Add-BlueprintError -Errors $errors -Code 'AUTHORIZATION_LEDGER_CHAIN_INVALID' -Message 'The authoritative consumption record omits or breaks the immediately previous monotonic ledger entry.'
            }
        }
    }
    elseif ($null -ne $writeOperationRecord) {
        Add-BlueprintError -Errors $errors -Code 'AUTHORIZATION_CONSUMPTION_RECORD_REQUIRED' -Message 'A caller-supplied record index cannot prove single use; the write operation must resolve one ledger-authority-attested authorization-consumption record.'
    }

    if ($null -ne $writeOperationRecord) {
        $writeOperationFields = @(
            'operationId', 'status', 'writeAuthorizationRef', 'writeAuthorizationDigest', 'authorizationId',
            'authorizationNonce', 'maxUses', 'authorizationConsumptionRef', 'authorizationConsumptionDigest',
            'consumptionLedgerRef', 'consumptionLedgerDigest', 'consumptionLedgerSequence', 'replayCheckStatus',
            'reviewedPlanRef', 'reviewedPlanDigest', 'roleBindingRef', 'roleBindingDigest',
            'roleBindingReadbackRef', 'roleBindingReadbackDigest', 'transportOwnershipRef', 'transportOwnershipDigest',
            'packageVerificationRef', 'packageVerificationDigest',
            'writerToolRef', 'writeIdentityRef', 'applyOperatorIdentityRef', 'managedObjectType', 'managedObjectRefs',
            'managedObjectSetDigest', 'tenantBoundaryRef', 'targetEnvironmentRef', 'targetScopeRef',
            'desiredStateRevision', 'packageDigest', 'targetMembershipDigest', 'targetPopulation',
            'startedAt', 'consumedAt', 'mutationStartedAt', 'preNetworkAtomicCommitEvidenceRef',
            'preNetworkAtomicCommitEvidenceDigest', 'authorizationUseCount', 'independentReadbackPolicyRef',
            'independentReadbackPolicyDigest', 'readbackMaxAgeMinutes', 'expectedReadbackKind', 'completedAt'
        )
        if ([string]$Request.writerToolRef -ceq 'microsoft-graph-write') {
            $writeOperationFields += @('transportExceptionRef','transportExceptionDigest')
        }
        Test-RequiredProperties -Object $writeOperationRecord -Names $writeOperationFields -Context 'write operation record' -Errors $errors
        if ([string]$Request.writerToolRef -ceq 'microsoft-graph-write' -and
            ([string]$writeOperationRecord.transportExceptionRef -cne [string]$Request.transportExceptionRef -or
             [string]$writeOperationRecord.transportExceptionDigest -cne [string]$Request.transportExceptionDigest)) {
            Add-BlueprintError -Errors $errors -Code 'DIRECT_GRAPH_EXCEPTION_BINDING_MISMATCH' -Message 'Direct Graph write operation does not bind the exact scoped provider-gap exception and digest.'
        }
        elseif ([string]$Request.writerToolRef -ceq 'msgraph-terraform-provider' -and
            ((Test-ValuePresent $writeOperationRecord.transportExceptionRef) -or
             (Test-ValuePresent $writeOperationRecord.transportExceptionDigest))) {
            Add-BlueprintError -Errors $errors -Code 'DIRECT_GRAPH_EXCEPTION_FORBIDDEN' -Message 'Terraform-provider write operation may not retain a direct-Graph exception.'
        }
        [DateTimeOffset]$writeStartedAt = [DateTimeOffset]::MinValue
        [DateTimeOffset]$operationConsumedAt = [DateTimeOffset]::MinValue
        [DateTimeOffset]$mutationStartedAt = [DateTimeOffset]::MinValue
        [DateTimeOffset]$retainedWriteCompletedAt = [DateTimeOffset]::MinValue
        $writeChronologyValid = [OperationsBlueprint.StrictRfc3339]::TryParse([string]$writeOperationRecord.startedAt, [ref]$writeStartedAt) -and
            [OperationsBlueprint.StrictRfc3339]::TryParse([string]$writeOperationRecord.consumedAt, [ref]$operationConsumedAt) -and
            [OperationsBlueprint.StrictRfc3339]::TryParse([string]$writeOperationRecord.mutationStartedAt, [ref]$mutationStartedAt) -and
            [OperationsBlueprint.StrictRfc3339]::TryParse([string]$writeOperationRecord.completedAt, [ref]$retainedWriteCompletedAt)
        $preMutationConsumptionValid = $writeChronologyValid -and
            $writeStartedAt -le $operationConsumedAt -and
            $operationConsumedAt -le $mutationStartedAt -and
            $mutationStartedAt -le $retainedWriteCompletedAt -and
            [string]$writeOperationRecord.preNetworkAtomicCommitEvidenceRef -cmatch '^private://' -and
            (Test-Sha256Token $writeOperationRecord.preNetworkAtomicCommitEvidenceDigest) -and
            $null -ne $authorizationConsumptionRecord -and
            [string]$writeOperationRecord.preNetworkAtomicCommitEvidenceRef -ceq [string]$authorizationConsumptionRecord.atomicCommitEvidenceRef -and
            [string]$writeOperationRecord.preNetworkAtomicCommitEvidenceDigest -ceq [string]$authorizationConsumptionRecord.atomicCommitEvidenceDigest
        if (-not $preMutationConsumptionValid) {
            Add-BlueprintError -Errors $errors -Code 'WRITE_AUTHORIZATION_NOT_CONSUMED_BEFORE_MUTATION' -Message 'The authoritative atomic authorization consumption must be committed and exactly bound before the first protected network mutation.'
        }
        if ([string]$writeOperationRecord.operationId -cne [string]$Request.writeOperationId -or
            [string]$writeOperationRecord.status -cne 'COMPLETED' -or
            [string]$writeOperationRecord.writeAuthorizationRef -cne [string]$Request.writeAuthorizationRef -or
            [string]$writeOperationRecord.writeAuthorizationDigest -cne [string]$Request.writeAuthorizationDigest -or
            ($null -ne $writeAuthorizationRecord -and [string]$writeOperationRecord.authorizationId -cne [string]$writeAuthorizationRecord.authorizationId) -or
            ($null -ne $writeAuthorizationRecord -and [string]$writeOperationRecord.authorizationNonce -cne [string]$writeAuthorizationRecord.authorizationNonce) -or
            ($writeOperationRecord.maxUses -isnot [int] -and $writeOperationRecord.maxUses -isnot [long]) -or
            [int64]$writeOperationRecord.maxUses -ne 1 -or
            $null -eq $authorizationConsumptionRecord -or
            ($null -ne $authorizationConsumptionRecord -and [string]$writeOperationRecord.authorizationConsumptionRef -cne [string]$authorizationConsumptionRecord.recordId) -or
            ($null -ne $authorizationConsumptionRecord -and [string]$writeOperationRecord.authorizationConsumptionDigest -cne [string]$authorizationConsumptionRecord.contentDigest) -or
            ($null -ne $authorizationConsumptionRecord -and [string]$writeOperationRecord.consumptionLedgerRef -cne [string]$authorizationConsumptionRecord.consumptionLedgerRef) -or
            ($null -ne $authorizationConsumptionRecord -and [string]$writeOperationRecord.consumptionLedgerDigest -cne [string]$authorizationConsumptionRecord.consumptionLedgerDigest) -or
            ($null -ne $authorizationConsumptionRecord -and [string]$writeOperationRecord.consumptionLedgerSequence -cne [string]$authorizationConsumptionRecord.consumptionLedgerSequence) -or
            [string]$writeOperationRecord.replayCheckStatus -cne 'NOT_REUSED' -or
            [string]$writeOperationRecord.reviewedPlanRef -cne [string]$Request.reviewedPlanRef -or
            [string]$writeOperationRecord.reviewedPlanDigest -cne [string]$Request.reviewedPlanDigest -or
            [string]$writeOperationRecord.roleBindingRef -cne [string]$Request.roleBindingRef -or
            [string]$writeOperationRecord.roleBindingDigest -cne [string]$Request.roleBindingDigest -or
            [string]$writeOperationRecord.roleBindingReadbackRef -cne [string]$Request.roleBindingReadbackRef -or
            [string]$writeOperationRecord.roleBindingReadbackDigest -cne [string]$Request.roleBindingReadbackDigest -or
            [string]$writeOperationRecord.transportOwnershipRef -cne [string]$Request.transportOwnershipRecordRef -or
            [string]$writeOperationRecord.transportOwnershipDigest -cne [string]$Request.transportOwnershipRecordDigest -or
            ([string]$Request.writerToolRef -ceq 'microsoft-graph-write' -and
                ([string]$writeOperationRecord.transportExceptionRef -cne [string]$Request.transportExceptionRef -or
                 [string]$writeOperationRecord.transportExceptionDigest -cne [string]$Request.transportExceptionDigest)) -or
            ([string]$Request.writerToolRef -ceq 'msgraph-terraform-provider' -and
                ((Test-ValuePresent $writeOperationRecord.transportExceptionRef) -or
                 (Test-ValuePresent $writeOperationRecord.transportExceptionDigest))) -or
            [string]$writeOperationRecord.packageVerificationRef -cne [string]$Request.packageVerificationRef -or
            [string]$writeOperationRecord.packageVerificationDigest -cne [string]$Request.packageVerificationDigest -or
            [string]$writeOperationRecord.writerToolRef -cne [string]$Request.writerToolRef -or
            [string]$writeOperationRecord.writeIdentityRef -cne [string]$Request.writeIdentityRef -or
            [string]$writeOperationRecord.applyOperatorIdentityRef -cne [string]$Request.applyOperatorIdentityRef -or
            [string]$writeOperationRecord.managedObjectType -cne [string]$Request.managedObjectType -or
            -not (Test-CanonicalValueEqual @($writeOperationRecord.managedObjectRefs) @($Request.managedObjectRefs)) -or
            [string]$writeOperationRecord.managedObjectSetDigest -cne [string]$Request.managedObjectSetDigest -or
            [string]$writeOperationRecord.managedObjectSetDigest -cne [string]$expectedManagedObjectSetDigest -or
            [string]$writeOperationRecord.tenantBoundaryRef -cne [string]$Request.tenantBoundaryRef -or
            [string]$writeOperationRecord.targetEnvironmentRef -cne [string]$Request.targetEnvironmentRef -or
            [string]$writeOperationRecord.targetScopeRef -cne [string]$Request.targetScopeRef -or
            [string]$writeOperationRecord.desiredStateRevision -cne [string]$Request.desiredStateRevision -or
            [string]$writeOperationRecord.packageDigest -cne [string]$Request.packageDigest -or
            [string]$writeOperationRecord.targetMembershipDigest -cne [string]$Request.targetMembershipDigest -or
            -not (Test-CanonicalValueEqual $writeOperationRecord.targetPopulation $Request.targetPopulation) -or
            [string]$writeOperationRecord.independentReadbackPolicyRef -cne [string]$Request.independentReadbackPolicyRef -or
            [string]$writeOperationRecord.independentReadbackPolicyDigest -cne [string]$Request.independentReadbackPolicyDigest -or
            [string]$writeOperationRecord.readbackMaxAgeMinutes -cne [string]$Request.readbackMaxAgeMinutes -or
            [string]$writeOperationRecord.expectedReadbackKind -cne 'INTUNE_POST_WRITE' -or
            [string]$writeOperationRecord.completedAt -cne [string]$Request.writeCompletedAt -or
            -not $preMutationConsumptionValid -or
            ($writeAuthorizationRecord -ne $null -and $writeStartedAt -lt $writeAuthorizationNotBefore) -or
            ($writeAuthorizationRecord -ne $null -and $writeStartedAt -ge $writeAuthorizationExpiresAt) -or
            $operationConsumedAt -lt $writeStartedAt -or $operationConsumedAt -gt $mutationStartedAt -or
            $mutationStartedAt -gt $retainedWriteCompletedAt -or
            ($null -ne $authorizationConsumptionRecord -and [string]$writeOperationRecord.consumedAt -cne [string]$authorizationConsumptionRecord.consumedAt) -or
            ($writeOperationRecord.authorizationUseCount -isnot [int] -and $writeOperationRecord.authorizationUseCount -isnot [long]) -or
            [int64]$writeOperationRecord.authorizationUseCount -ne 1 -or
            ($writeAuthorizationRecord -ne $null -and $operationConsumedAt -lt $writeAuthorizationRevocationCheckedAt) -or
            $retainedWriteCompletedAt -gt $EvaluationTime -or
            ($writeAuthorizationRecord -ne $null -and $retainedWriteCompletedAt -ge $writeAuthorizationExpiresAt) -or
            ($approvalExpiresAt -ne [DateTimeOffset]::MinValue -and $retainedWriteCompletedAt -ge $approvalExpiresAt) -or
            ($latestApprovalAt -ne [DateTimeOffset]::MinValue -and $writeStartedAt -lt $latestApprovalAt)) {
            Add-BlueprintError -Errors $errors -Code 'WRITE_OPERATION_RECORD_MISMATCH' -Message 'Typed write operation does not bind and chronologically consume the exact single-use authorization, plan, transport, package verification, identity, object, scope, revision, population, membership, and completion time.'
        }
    }

    $transportExceptionRecord = $null
    if ([string]$Request.writerToolRef -ceq 'microsoft-graph-write') {
        $transportExceptionRecord = Resolve-CanonicalRecord -RecordMap $recordMap -Reference $Request.transportExceptionRef -ExpectedTypes @('exception-record') -Context 'direct Graph transport exception' -Errors $errors
        if ($null -ne $transportExceptionRecord) {
            Test-RequiredProperties -Object $transportExceptionRecord -Names @(
                'status', 'managedObjectType', 'targetScopeRef', 'writerToolRef', 'providerGapRef',
                'reason', 'ownerRole', 'ownerPrincipalRef', 'compensatingControlRefs',
                'closureEvidenceRef', 'expiresAt'
            ) -Context 'direct Graph transport exception' -Errors $errors
            if ([string]$transportExceptionRecord.contentDigest -cne [string]$Request.transportExceptionDigest -or
                [string]$transportExceptionRecord.status -cne 'APPROVED' -or
                [string]$transportExceptionRecord.managedObjectType -cne [string]$Request.managedObjectType -or
                [string]$transportExceptionRecord.targetScopeRef -cne [string]$Request.targetScopeRef -or
                [string]$transportExceptionRecord.writerToolRef -cne 'microsoft-graph-write' -or
                [string]$transportExceptionRecord.expiresAt -cne [string]$Request.transportExceptionExpiresAt -or
                [string]$transportExceptionRecord.ownerRole -cne 'ROLE_GRAPH_AUTOMATION_OWNER' -or
                [string]$transportExceptionRecord.ownerPrincipalRef -notmatch '^private://' -or
                [string]$transportExceptionRecord.providerGapRef -notmatch '^private://' -or
                [string]$transportExceptionRecord.closureEvidenceRef -notmatch '^private://' -or
                -not (Test-ValuePresent $transportExceptionRecord.reason) -or
                -not (Test-ValuePresent $transportExceptionRecord.compensatingControlRefs)) {
                Add-BlueprintError -Errors $errors -Code 'DIRECT_GRAPH_EXCEPTION_BINDING_MISMATCH' -Message 'Direct Graph exception digest and payload are not bound to this object type, scope, named owner, provider gap, controls, closure evidence, and expiration.'
            }
            foreach ($controlRef in @($transportExceptionRecord.compensatingControlRefs)) {
                $controlRecord = Resolve-CanonicalRecord -RecordMap $recordMap -Reference $controlRef -ExpectedTypes @('compensating-control-record') -Context 'direct Graph compensating control' -Errors $errors
                if ($null -eq $controlRecord) { continue }
                Test-RequiredProperties -Object $controlRecord -Names @(
                    'status', 'sourceExceptionRef', 'ownerRole', 'targetScopeRef', 'managedObjectType', 'expiresAt'
                ) -Context "direct Graph compensating control $($controlRecord.recordId)" -Errors $errors
                [DateTimeOffset]$controlExpiresAt = [DateTimeOffset]::MinValue
                if ([string]$controlRecord.status -cne 'ACTIVE' -or
                    [string]$controlRecord.sourceExceptionRef -cne [string]$Request.transportExceptionRef -or
                    [string]$controlRecord.ownerRole -cnotmatch '^ROLE_[A-Z0-9_]+$' -or
                    [string]$controlRecord.targetScopeRef -cne [string]$Request.targetScopeRef -or
                    [string]$controlRecord.managedObjectType -cne [string]$Request.managedObjectType -or
                    -not [OperationsBlueprint.StrictRfc3339]::TryParse([string]$controlRecord.expiresAt, [ref]$controlExpiresAt) -or
                    $controlExpiresAt -le $EvaluationTime) {
                    Add-BlueprintError -Errors $errors -Code 'DIRECT_GRAPH_COMPENSATING_CONTROL_INVALID' -Message "$($controlRecord.recordId) is not active and bound to the exact direct-Graph exception, owner, object, and scope."
                }
            }
        }
    }

    $authorization = $Request.authorization
    Test-RequiredProperties -Object $authorization -Names @(
        'phase2Status', 'phase3Verdict', 'pilotAuthorizationRef', 'pilotAuthorizationDigest',
        'stopConditionsRef', 'stopConditionsDigest', 'rollbackRef', 'rollbackDigest',
        'componentIdentityStatus'
    ) -Context 'activation authorization' -Errors $errors
    Test-AllowedProperties -Object $authorization -Names @(
        'phase2Status', 'phase3Verdict', 'pilotAuthorizationRef', 'pilotAuthorizationDigest',
        'stopConditionsRef', 'stopConditionsDigest', 'rollbackRef', 'rollbackDigest',
        'componentIdentityStatus', 'pilotCompletionStatus', 'finalVerdictRef',
        'fleetVerdict', 'personaVerdict', 'procurementEnvelopeRef', 'deltaQualificationStatus',
        'conditionsStatus', 'conditionRecordRefs'
    ) -Context 'activation authorization' -Errors $errors
    foreach ($authorizationDigestName in @('pilotAuthorizationDigest', 'stopConditionsDigest', 'rollbackDigest')) {
        if (-not (Test-Sha256Token $authorization.$authorizationDigestName)) {
            Add-BlueprintError -Errors $errors -Code 'ACTIVATION_GATE_DIGEST_INVALID' -Message "$authorizationDigestName must be a SHA-256 token."
        }
    }
    if ($authorization.phase2Status -cne 'PASS') {
        Add-BlueprintError -Errors $errors -Code 'PHASE2_NOT_APPROVED' -Message 'Current Phase 2 compatibility/security approval is required.'
    }
    if ($authorization.phase3Verdict -cnotin @('QUALIFY', 'QUALIFY_WITH_CONDITIONS')) {
        Add-BlueprintError -Errors $errors -Code 'PHASE3_NOT_APPROVED' -Message 'Phase 3 provisional approval is required.'
    }
    foreach ($pair in @(
        @{ Name = 'pilotAuthorizationRef'; Code = 'PILOT_AUTHORIZATION_MISSING' },
        @{ Name = 'stopConditionsRef'; Code = 'STOP_CONDITIONS_MISSING' },
        @{ Name = 'rollbackRef'; Code = 'ROLLBACK_MISSING' }
    )) {
        $property = $authorization.PSObject.Properties[$pair.Name]
        if ($null -eq $property -or -not (Test-ValuePresent $property.Value)) {
            Add-BlueprintError -Errors $errors -Code $pair.Code -Message "$($pair.Name) is required."
        }
        else {
            $expectedType = switch ($pair.Name) {
                'pilotAuthorizationRef' { 'pilot-authorization-record' }
                'stopConditionsRef' { 'stop-conditions-record' }
                default { 'rollback-record' }
            }
            [void](Resolve-CanonicalRecord -RecordMap $recordMap -Reference $property.Value -ExpectedTypes @($expectedType) -Context $pair.Name -Errors $errors)
        }
    }

    $pilotAuthorizationRecord = Resolve-CanonicalRecord -RecordMap $recordMap -Reference $authorization.pilotAuthorizationRef -ExpectedTypes @('pilot-authorization-record') -Context 'pilot authorization semantics' -Errors $errors
    $stopConditionsRecord = Resolve-CanonicalRecord -RecordMap $recordMap -Reference $authorization.stopConditionsRef -ExpectedTypes @('stop-conditions-record') -Context 'stop conditions semantics' -Errors $errors
    $rollbackRecord = Resolve-CanonicalRecord -RecordMap $recordMap -Reference $authorization.rollbackRef -ExpectedTypes @('rollback-record') -Context 'rollback semantics' -Errors $errors
    [DateTimeOffset]$pilotAuthorizedAt = [DateTimeOffset]::MinValue
    [DateTimeOffset]$pilotAuthorizationExpiresAt = [DateTimeOffset]::MinValue
    [DateTimeOffset]$phase2ApprovedAt = [DateTimeOffset]::MinValue
    [DateTimeOffset]$phase2ExpiresAt = [DateTimeOffset]::MinValue
    [DateTimeOffset]$phase3ImmutableAt = [DateTimeOffset]::MinValue
    $pilotAuthorizationTimesValid = $false
    $phase2TimesValid = $false
    $phase3TimeValid = $false
    if ($null -ne $pilotAuthorizationRecord) {
        Test-RequiredProperties -Object $pilotAuthorizationRecord -Names @(
            'status', 'manifestRef', 'manifestDigest', 'personaId', 'phase2Status',
            'phase2ApprovalRef', 'phase2ApprovalDigest', 'phase3Verdict', 'phase3VerdictRef',
            'phase3VerdictDigest', 'testPlanRef', 'testPlanDigest', 'thresholdPolicyRef',
            'thresholdPolicyDigest', 'evidenceReleaseBindings', 'stopConditionsRef',
            'stopConditionsDigest', 'rollbackRef', 'rollbackDigest', 'targetScopeRef',
            'authorizedAt', 'expiresAt'
        ) -Context 'pilot authorization record' -Errors $errors
        $pilotAuthorizationTimesValid = [OperationsBlueprint.StrictRfc3339]::TryParse([string]$pilotAuthorizationRecord.authorizedAt, [ref]$pilotAuthorizedAt) -and
            [OperationsBlueprint.StrictRfc3339]::TryParse([string]$pilotAuthorizationRecord.expiresAt, [ref]$pilotAuthorizationExpiresAt)
        $phase2ApprovalRecord = Resolve-CanonicalRecord -RecordMap $recordMap -Reference $pilotAuthorizationRecord.phase2ApprovalRef -ExpectedTypes @('phase2-approval-record') -Context 'typed Phase 2 compatibility and security approval' -Errors $errors
        $phase3VerdictRecord = Resolve-CanonicalRecord -RecordMap $recordMap -Reference $pilotAuthorizationRecord.phase3VerdictRef -ExpectedTypes @('verdict-record') -Context 'portable Phase 3 provisional verdict' -Errors $errors
        $pilotTestPlan = Resolve-CanonicalRecord -RecordMap $recordMap -Reference $pilotAuthorizationRecord.testPlanRef -ExpectedTypes @('test-plan') -Context 'pilot frozen test plan' -Errors $errors
        $pilotThresholdPolicy = Resolve-CanonicalRecord -RecordMap $recordMap -Reference $pilotAuthorizationRecord.thresholdPolicyRef -ExpectedTypes @('threshold-policy') -Context 'pilot frozen threshold policy' -Errors $errors
        if ([string]$pilotAuthorizationRecord.contentDigest -cne [string]$authorization.pilotAuthorizationDigest -or
            [string]$pilotAuthorizationRecord.status -cne 'AUTHORIZED' -or
            [string]$pilotAuthorizationRecord.manifestRef -cne [string]$Request.manifestRef -or
            ($null -ne $manifestRecord -and [string]$pilotAuthorizationRecord.manifestDigest -cne [string]$manifestRecord.contentDigest) -or
            [string]$pilotAuthorizationRecord.personaId -cne [string]$Request.personaId -or
            [string]$pilotAuthorizationRecord.phase2Status -cne [string]$authorization.phase2Status -or
            [string]$pilotAuthorizationRecord.phase3Verdict -cne [string]$authorization.phase3Verdict -or
            [string]$pilotAuthorizationRecord.stopConditionsRef -cne [string]$authorization.stopConditionsRef -or
            [string]$pilotAuthorizationRecord.stopConditionsDigest -cne [string]$authorization.stopConditionsDigest -or
            [string]$pilotAuthorizationRecord.rollbackRef -cne [string]$authorization.rollbackRef -or
            [string]$pilotAuthorizationRecord.rollbackDigest -cne [string]$authorization.rollbackDigest -or
            [string]$pilotAuthorizationRecord.targetScopeRef -cne [string]$Request.targetScopeRef -or
            -not $pilotAuthorizationTimesValid -or
            $pilotAuthorizedAt -gt $EvaluationTime -or $pilotAuthorizationExpiresAt -le $EvaluationTime -or
            $pilotAuthorizationExpiresAt -le $pilotAuthorizedAt) {
            Add-BlueprintError -Errors $errors -Code 'PILOT_AUTHORIZATION_RECORD_MISMATCH' -Message 'Pilot authorization does not bind the exact current Phase 2/3 releases, frozen plan/policy, manifest, persona, scope, stop conditions, rollback, and validity.'
        }
        $requiredPilotEvidenceReleaseRefs = New-Object System.Collections.ArrayList
        if ($null -ne $phase2ApprovalRecord) {
            $phase2Fields = @(
                'schemaVersion', 'recordStage', 'status', 'manifestRef', 'manifestDigest',
                'phase0TestPlanRef', 'phase0TestPlanDigest', 'phase0ThresholdPolicyRef',
                'phase0ThresholdPolicyDigest', 'phase2EvidenceReleaseRef', 'phase2EvidenceReleaseDigest',
                'compatibilityMatrixRef', 'compatibilityMatrixDigest', 'testPackRef', 'testPackDigest',
                'testPackVersion', 'platformBaselineRef', 'platformBaselineDigest',
                'compatibilityApproval', 'securityApproval', 'exceptionRefs', 'exceptionSetDigest',
                'exceptionStatus', 'approvedAt', 'expiresAt'
            )
            Test-RequiredProperties -Object $phase2ApprovalRecord -Names @($phase2Fields | Where-Object { $_ -cne 'exceptionRefs' }) -Context 'typed Phase 2 approval' -Errors $errors
            if ($null -eq $phase2ApprovalRecord.PSObject.Properties['exceptionRefs']) {
                Add-BlueprintError -Errors $errors -Code 'MISSING_REQUIRED_FIELD' -Message 'Typed Phase 2 approval requires exceptionRefs, which may be an empty array only when exceptionStatus is NONE.'
            }
            $phase2Manifest = Resolve-CanonicalRecord -RecordMap $recordMap -Reference $phase2ApprovalRecord.manifestRef -ExpectedTypes @('candidate-manifest') -Context 'Phase 2 manifest' -Errors $errors
            $phase2TestPlan = Resolve-CanonicalRecord -RecordMap $recordMap -Reference $phase2ApprovalRecord.phase0TestPlanRef -ExpectedTypes @('test-plan') -Context 'Phase 2 frozen test plan' -Errors $errors
            $phase2ThresholdPolicy = Resolve-CanonicalRecord -RecordMap $recordMap -Reference $phase2ApprovalRecord.phase0ThresholdPolicyRef -ExpectedTypes @('threshold-policy') -Context 'Phase 2 frozen threshold policy' -Errors $errors
            $phase2EvidenceRelease = Resolve-CanonicalRecord -RecordMap $recordMap -Reference $phase2ApprovalRecord.phase2EvidenceReleaseRef -ExpectedTypes @('evidence-release') -Context 'Phase 2 evidence release' -Errors $errors
            $phase2PlatformBaseline = Resolve-CanonicalRecord -RecordMap $recordMap -Reference $phase2ApprovalRecord.platformBaselineRef -ExpectedTypes @('platform-baseline-record') -Context 'Phase 2 platform baseline' -Errors $errors
            $phase2TimesValid = [OperationsBlueprint.StrictRfc3339]::TryParse([string]$phase2ApprovalRecord.approvedAt, [ref]$phase2ApprovedAt) -and
                [OperationsBlueprint.StrictRfc3339]::TryParse([string]$phase2ApprovalRecord.expiresAt, [ref]$phase2ExpiresAt)
            [string[]]$sortedPhase2ExceptionRefs = @()
            if (@($phase2ApprovalRecord.exceptionRefs).Count -gt 0) {
                $sortedPhase2ExceptionRefs = [string[]]@($phase2ApprovalRecord.exceptionRefs | ForEach-Object { [string]$_ })
                [Array]::Sort($sortedPhase2ExceptionRefs, [StringComparer]::Ordinal)
            }
            $expectedPhase2ExceptionSetDigest = Get-CanonicalPayloadDigest -Payload ([pscustomobject]@{ exceptionRefs = @($sortedPhase2ExceptionRefs) })
            $approvalEntries = @($phase2ApprovalRecord.compatibilityApproval, $phase2ApprovalRecord.securityApproval)
            $phase2ApprovalEntriesValid = $true
            foreach ($phase2ApprovalEntry in $approvalEntries) {
                Test-RequiredProperties -Object $phase2ApprovalEntry -Names @(
                    'decision', 'roleId', 'principalRef', 'approvalArtifactRef', 'approvalArtifactDigest',
                    'signatureRef', 'signatureDigest', 'approvedAt'
                ) -Context 'Phase 2 approval entry' -Errors $errors
                [DateTimeOffset]$phase2EntryApprovedAt = [DateTimeOffset]::MinValue
                if ([string]$phase2ApprovalEntry.decision -cne 'APPROVED' -or
                    [string]$phase2ApprovalEntry.roleId -cnotmatch '^ROLE_[A-Z0-9_]+$' -or
                    [string]$phase2ApprovalEntry.principalRef -cnotmatch '^private://' -or
                    [string]$phase2ApprovalEntry.approvalArtifactRef -cnotmatch '^private://' -or
                    -not (Test-Sha256Token $phase2ApprovalEntry.approvalArtifactDigest) -or
                    [string]$phase2ApprovalEntry.signatureRef -cnotmatch '^private://' -or
                    -not (Test-Sha256Token $phase2ApprovalEntry.signatureDigest) -or
                    -not [OperationsBlueprint.StrictRfc3339]::TryParse([string]$phase2ApprovalEntry.approvedAt, [ref]$phase2EntryApprovedAt) -or
                    ($phase2TimesValid -and $phase2EntryApprovedAt -gt $phase2ApprovedAt)) {
                    $phase2ApprovalEntriesValid = $false
                }
            }
            if ([string]$phase2ApprovalRecord.compatibilityApproval.roleId -cne 'ROLE_QUALIFICATION_AUTHORITY' -or
                [string]$phase2ApprovalRecord.securityApproval.roleId -cne 'ROLE_SECURITY_APPROVER' -or
                [string]$phase2ApprovalRecord.compatibilityApproval.principalRef -ceq [string]$phase2ApprovalRecord.securityApproval.principalRef -or
                [string]$phase2ApprovalRecord.compatibilityApproval.roleId -ceq [string]$phase2ApprovalRecord.securityApproval.roleId) {
                $phase2ApprovalEntriesValid = $false
            }
            if (-not $phase2ApprovalEntriesValid) {
                Add-BlueprintError -Errors $errors -Code 'PHASE2_APPROVAL_SEPARATION_INVALID' -Message 'Phase 2 requires distinct current qualification and security approvals, private principals, signed artifacts, and approval-before-issuance chronology.'
            }
            $phase2ExceptionSetValid = [string]$phase2ApprovalRecord.exceptionSetDigest -ceq [string]$expectedPhase2ExceptionSetDigest -and
                @($phase2ApprovalRecord.exceptionRefs | Group-Object -CaseSensitive | Where-Object Count -gt 1).Count -eq 0 -and
                (([string]$phase2ApprovalRecord.exceptionStatus -ceq 'NONE' -and @($phase2ApprovalRecord.exceptionRefs).Count -eq 0) -or
                 ([string]$phase2ApprovalRecord.exceptionStatus -ceq 'CURRENT_APPROVED' -and @($phase2ApprovalRecord.exceptionRefs).Count -gt 0))
            foreach ($phase2ExceptionRef in @($phase2ApprovalRecord.exceptionRefs)) {
                $phase2Exception = Resolve-CanonicalRecord -RecordMap $recordMap -Reference $phase2ExceptionRef -ExpectedTypes @('exception-record') -Context 'Phase 2 exception' -Errors $errors
                [DateTimeOffset]$phase2ExceptionExpiresAt = [DateTimeOffset]::MinValue
                if ($null -eq $phase2Exception -or [string]$phase2Exception.status -cne 'APPROVED' -or
                    -not [OperationsBlueprint.StrictRfc3339]::TryParse([string]$phase2Exception.expiresAt, [ref]$phase2ExceptionExpiresAt) -or
                    $phase2ExceptionExpiresAt -le $EvaluationTime) { $phase2ExceptionSetValid = $false }
            }
            if (-not $phase2ExceptionSetValid) {
                Add-BlueprintError -Errors $errors -Code 'PHASE2_EXCEPTION_SET_INVALID' -Message 'Phase 2 exception status, current records, unique membership, or recomputed set digest is invalid.'
            }
            if ([string]$phase2ApprovalRecord.contentDigest -cne [string]$pilotAuthorizationRecord.phase2ApprovalDigest -or
                [string]$phase2ApprovalRecord.schemaVersion -cne '1.0.0' -or
                [string]$phase2ApprovalRecord.recordStage -cne 'PHASE2_COMPATIBILITY_SECURITY_APPROVAL' -or
                [string]$phase2ApprovalRecord.status -cne 'APPROVED' -or
                [string]$phase2ApprovalRecord.manifestRef -cne [string]$Request.manifestRef -or
                ($null -ne $phase2Manifest -and [string]$phase2ApprovalRecord.manifestDigest -cne [string]$phase2Manifest.contentDigest) -or
                [string]$phase2ApprovalRecord.phase0TestPlanRef -cne [string]$pilotAuthorizationRecord.testPlanRef -or
                [string]$phase2ApprovalRecord.phase0TestPlanDigest -cne [string]$pilotAuthorizationRecord.testPlanDigest -or
                ($null -ne $phase2TestPlan -and [string]$phase2ApprovalRecord.phase0TestPlanDigest -cne [string]$phase2TestPlan.contentDigest) -or
                [string]$phase2ApprovalRecord.phase0ThresholdPolicyRef -cne [string]$pilotAuthorizationRecord.thresholdPolicyRef -or
                [string]$phase2ApprovalRecord.phase0ThresholdPolicyDigest -cne [string]$pilotAuthorizationRecord.thresholdPolicyDigest -or
                ($null -ne $phase2ThresholdPolicy -and [string]$phase2ApprovalRecord.phase0ThresholdPolicyDigest -cne [string]$phase2ThresholdPolicy.contentDigest) -or
                ($null -ne $phase2EvidenceRelease -and [string]$phase2ApprovalRecord.phase2EvidenceReleaseDigest -cne [string]$phase2EvidenceRelease.contentDigest) -or
                ($null -ne $phase2PlatformBaseline -and [string]$phase2ApprovalRecord.platformBaselineDigest -cne [string]$phase2PlatformBaseline.contentDigest) -or
                [string]$phase2ApprovalRecord.compatibilityMatrixRef -cnotmatch '^private://' -or
                -not (Test-Sha256Token $phase2ApprovalRecord.compatibilityMatrixDigest) -or
                [string]$phase2ApprovalRecord.testPackRef -cnotmatch '^private://' -or
                -not (Test-Sha256Token $phase2ApprovalRecord.testPackDigest) -or
                -not (Test-NonBlankString $phase2ApprovalRecord.testPackVersion) -or
                -not $phase2TimesValid -or $phase2ApprovedAt -gt $pilotAuthorizedAt -or
                $phase2ExpiresAt -le $EvaluationTime -or $phase2ExpiresAt -le $phase2ApprovedAt) {
                Add-BlueprintError -Errors $errors -Code 'PHASE2_APPROVAL_RECORD_MISMATCH' -Message 'Phase 2 approval must bind the exact manifest, frozen plan/policy, evidence release, compatibility matrix, test pack, platform baseline, distinct approvals, exceptions, and validity window.'
            }
            if ($null -ne $phase2EvidenceRelease) {
                Test-EvidenceReleaseBinding -ReleaseRecord $phase2EvidenceRelease -EvidenceRecords @() -RecordMap $recordMap `
                    -EvaluationTime $EvaluationTime -ConsumerRecord $phase2ApprovalRecord -Manifest $phase2Manifest `
                    -Phase0TestPlan $phase2TestPlan -ThresholdPolicy $phase2ThresholdPolicy `
                    -ValidationProfile $ValidationProfile `
                    -Context 'pilot Phase 2' -Errors $errors
                if ([string]$phase2EvidenceRelease.testPlanRef -cne [string]$pilotAuthorizationRecord.testPlanRef -or
                    [string]$phase2EvidenceRelease.testPlanDigest -cne [string]$pilotAuthorizationRecord.testPlanDigest -or
                    [string]$phase2EvidenceRelease.thresholdPolicyRef -cne [string]$pilotAuthorizationRecord.thresholdPolicyRef -or
                    [string]$phase2EvidenceRelease.thresholdPolicyDigest -cne [string]$pilotAuthorizationRecord.thresholdPolicyDigest -or
                    [string]$phase2EvidenceRelease.testPackVersion -cne [string]$phase2ApprovalRecord.testPackVersion) {
                    Add-BlueprintError -Errors $errors -Code 'PILOT_GATE_EVIDENCE_BINDING_MISMATCH' -Message 'Phase 2 evidence release does not bind the exact frozen plan, threshold policy, and approved test-pack version.'
                }
                [void]$requiredPilotEvidenceReleaseRefs.Add([string]$phase2ApprovalRecord.phase2EvidenceReleaseRef)
            }
        }
        if ($null -ne $phase3VerdictRecord) {
            Test-RequiredProperties -Object $phase3VerdictRecord -Names @(
                'schemaVersion', 'recordStage', 'status', 'immutableAt', 'manifestRef',
                'provisionalLabVerdict', 'pilotAuthorization', 'evidenceReleases'
            ) -Context 'portable Phase 3 verdict' -Errors $errors
            $phase3TimeValid = [OperationsBlueprint.StrictRfc3339]::TryParse([string]$phase3VerdictRecord.immutableAt, [ref]$phase3ImmutableAt)
            if ([string]$phase3VerdictRecord.contentDigest -cne [string]$pilotAuthorizationRecord.phase3VerdictDigest -or
                [string]$phase3VerdictRecord.schemaVersion -cne '2.0.1' -or
                [string]$phase3VerdictRecord.recordStage -cne 'pilot-authorization' -or
                [string]$phase3VerdictRecord.status -cne 'approved-and-immutable' -or
                [string]$phase3VerdictRecord.manifestRef -cne [string]$Request.manifestRef -or
                [string]$phase3VerdictRecord.provisionalLabVerdict -cne [string]$authorization.phase3Verdict -or
                [string]$phase3VerdictRecord.pilotAuthorization.status -cne 'AUTHORIZED' -or
                @($phase3VerdictRecord.evidenceReleases).Count -eq 0 -or
                @($phase3VerdictRecord.evidenceReleases | Group-Object -CaseSensitive | Where-Object Count -gt 1).Count -gt 0 -or
                -not $phase3TimeValid -or
                $phase3ImmutableAt -gt $pilotAuthorizedAt -or
                ($phase2TimesValid -and $phase3TimeValid -and $phase3ImmutableAt -lt $phase2ApprovedAt)) {
                Add-BlueprintError -Errors $errors -Code 'PHASE3_VERDICT_RECORD_MISMATCH' -Message 'Phase 3 must resolve to the exact immutable portable pilot verdict, qualifying provisional disposition, manifest, and pre-pilot chronology.'
            }
            foreach ($phase3EvidenceReleaseRef in @($phase3VerdictRecord.evidenceReleases)) {
                [void]$requiredPilotEvidenceReleaseRefs.Add([string]$phase3EvidenceReleaseRef)
            }
        }
        if (($null -ne $pilotTestPlan -and [string]$pilotTestPlan.contentDigest -cne [string]$pilotAuthorizationRecord.testPlanDigest) -or
            ($null -ne $pilotThresholdPolicy -and [string]$pilotThresholdPolicy.contentDigest -cne [string]$pilotAuthorizationRecord.thresholdPolicyDigest)) {
            Add-BlueprintError -Errors $errors -Code 'PILOT_GATE_EVIDENCE_BINDING_MISMATCH' -Message 'Pilot plan or threshold-policy digest differs from its canonical frozen record.'
        }
        $releaseBindings = @($pilotAuthorizationRecord.evidenceReleaseBindings)
        $requiredReleaseSet = [System.Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal)
        foreach ($requiredPilotReleaseRef in @($requiredPilotEvidenceReleaseRefs)) {
            if (Test-NonBlankString $requiredPilotReleaseRef) { [void]$requiredReleaseSet.Add([string]$requiredPilotReleaseRef) }
        }
        [string[]]$requiredReleaseRefs = @($requiredReleaseSet)
        [Array]::Sort($requiredReleaseRefs, [StringComparer]::Ordinal)
        if ($releaseBindings.Count -ne $requiredReleaseRefs.Count -or
            @($releaseBindings | Group-Object -Property recordRef -CaseSensitive | Where-Object Count -gt 1).Count -gt 0) {
            Add-BlueprintError -Errors $errors -Code 'PILOT_GATE_EVIDENCE_SET_INCOMPLETE' -Message 'Pilot authorization requires the exact unique evidence-release set used by the typed Phase 2 approval and portable Phase 3 verdict.'
        }
        foreach ($binding in $releaseBindings) {
            Test-RequiredProperties -Object $binding -Names @('recordRef', 'contentDigest') -Context 'pilot evidence release binding' -Errors $errors
            $boundRelease = Resolve-CanonicalRecord -RecordMap $recordMap -Reference $binding.recordRef -ExpectedTypes @('evidence-release') -Context 'pilot evidence release binding' -Errors $errors
            if ($null -ne $boundRelease) {
                $releaseConsumer = if ($null -ne $phase2ApprovalRecord -and
                    [string]$boundRelease.recordId -ceq [string]$phase2ApprovalRecord.phase2EvidenceReleaseRef) {
                    $phase2ApprovalRecord
                }
                elseif ($null -ne $phase3VerdictRecord -and
                    @($phase3VerdictRecord.evidenceReleases) -ccontains [string]$boundRelease.recordId) {
                    $phase3VerdictRecord
                }
                else { $pilotAuthorizationRecord }
                $cacheAdmissionSemanticsAlreadyValidated = $null -ne $phase2ApprovalRecord -and
                    [string]$boundRelease.recordId -ceq [string]$phase2ApprovalRecord.phase2EvidenceReleaseRef
                Test-EvidenceReleaseBinding -ReleaseRecord $boundRelease -EvidenceRecords @() -RecordMap $recordMap `
                    -EvaluationTime $EvaluationTime -ConsumerRecord $releaseConsumer -Manifest $manifestRecord `
                    -Phase0TestPlan $pilotTestPlan -ThresholdPolicy $pilotThresholdPolicy `
                    -ValidationProfile $ValidationProfile `
                    -CacheAdmissionSemanticsAlreadyValidated:$cacheAdmissionSemanticsAlreadyValidated `
                    -Context 'pilot Phase 2/3' -Errors $errors
            }
            if ($null -ne $boundRelease -and
                ([string]$boundRelease.contentDigest -cne [string]$binding.contentDigest -or
                 [string]$boundRelease.testPlanRef -cne [string]$pilotAuthorizationRecord.testPlanRef -or
                 [string]$boundRelease.testPlanDigest -cne [string]$pilotAuthorizationRecord.testPlanDigest -or
                 [string]$boundRelease.thresholdPolicyRef -cne [string]$pilotAuthorizationRecord.thresholdPolicyRef -or
                 [string]$boundRelease.thresholdPolicyDigest -cne [string]$pilotAuthorizationRecord.thresholdPolicyDigest)) {
                Add-BlueprintError -Errors $errors -Code 'PILOT_GATE_EVIDENCE_BINDING_MISMATCH' -Message 'Pilot evidence-release binding digest differs from the canonical release.'
            }
        }
        foreach ($requiredReleaseRef in $requiredReleaseRefs) {
            if (@($releaseBindings | Where-Object { [string]$_.recordRef -ceq $requiredReleaseRef }).Count -ne 1) {
                Add-BlueprintError -Errors $errors -Code 'PILOT_GATE_EVIDENCE_SET_INCOMPLETE' -Message 'Pilot evidence-release bindings omit or duplicate a release used by Phase 2 or Phase 3.'
            }
        }
    }
    if ($null -ne $stopConditionsRecord) {
        Test-RequiredProperties -Object $stopConditionsRecord -Names @(
            'schemaVersion', 'recordStage', 'status', 'manifestRef', 'personaId', 'targetScopeRef',
            'managedObjectType', 'conditionSetDigest', 'conditionRefs', 'conditionCount',
            'monitoringQueryPackRef', 'monitoringQueryPackDigest', 'telemetryBaselineRef',
            'telemetryBaselineDigest', 'coveragePolicyRef', 'coveragePolicyDigest',
            'thresholdPolicyRef', 'thresholdPolicyDigest', 'cadenceMinutes', 'alertOwnerRole',
            'alertRouteRef', 'approvedAt', 'expiresAt'
        ) -Context 'stop conditions record' -Errors $errors
        [DateTimeOffset]$stopSetApprovedAt = [DateTimeOffset]::MinValue
        [DateTimeOffset]$stopSetExpiresAt = [DateTimeOffset]::MinValue
        $conditionRefs = @($stopConditionsRecord.conditionRefs)
        [string[]]$sortedConditionRefs = @()
        if ($conditionRefs.Count -gt 0) {
            $sortedConditionRefs = [string[]]$conditionRefs
            [Array]::Sort($sortedConditionRefs, [StringComparer]::Ordinal)
        }
        $expectedConditionSetDigest = Get-CanonicalPayloadDigest -Payload ([pscustomobject]@{ conditionRefs = @($sortedConditionRefs) })
        $stopQueryPack = Resolve-CanonicalRecord -RecordMap $recordMap -Reference $stopConditionsRecord.monitoringQueryPackRef -ExpectedTypes @('query-pack-record') -Context 'stop-condition query pack' -Errors $errors
        $stopTelemetryBaseline = Resolve-CanonicalRecord -RecordMap $recordMap -Reference $stopConditionsRecord.telemetryBaselineRef -ExpectedTypes @('telemetry-baseline-record') -Context 'stop-condition telemetry baseline' -Errors $errors
        $stopCoveragePolicy = Resolve-CanonicalRecord -RecordMap $recordMap -Reference $stopConditionsRecord.coveragePolicyRef -ExpectedTypes @('coverage-policy-record') -Context 'stop-condition coverage policy' -Errors $errors
        $stopThresholdPolicy = Resolve-CanonicalRecord -RecordMap $recordMap -Reference $stopConditionsRecord.thresholdPolicyRef -ExpectedTypes @('threshold-policy') -Context 'stop-condition threshold policy' -Errors $errors
        if ([string]$stopConditionsRecord.contentDigest -cne [string]$authorization.stopConditionsDigest -or
            [string]$stopConditionsRecord.schemaVersion -cne '1.0.0' -or
            [string]$stopConditionsRecord.recordStage -cne 'STOP_CONDITION_SET' -or
            [string]$stopConditionsRecord.status -cne 'APPROVED' -or
            [string]$stopConditionsRecord.manifestRef -cne [string]$Request.manifestRef -or
            [string]$stopConditionsRecord.personaId -cne [string]$Request.personaId -or
            [string]$stopConditionsRecord.targetScopeRef -cne [string]$Request.targetScopeRef -or
            [string]$stopConditionsRecord.managedObjectType -cne [string]$Request.managedObjectType -or
            $conditionRefs.Count -eq 0 -or
            @($conditionRefs | Where-Object { -not (Test-NonBlankString $_) }).Count -gt 0 -or
            @($conditionRefs | Group-Object -CaseSensitive | Where-Object Count -gt 1).Count -gt 0 -or
            ($stopConditionsRecord.conditionCount -isnot [int] -and $stopConditionsRecord.conditionCount -isnot [long]) -or
            [int64]$stopConditionsRecord.conditionCount -ne $conditionRefs.Count -or
            [string]$stopConditionsRecord.conditionSetDigest -cne [string]$expectedConditionSetDigest -or
            ($null -ne $stopQueryPack -and [string]$stopQueryPack.contentDigest -cne [string]$stopConditionsRecord.monitoringQueryPackDigest) -or
            ($null -ne $stopTelemetryBaseline -and [string]$stopTelemetryBaseline.contentDigest -cne [string]$stopConditionsRecord.telemetryBaselineDigest) -or
            ($null -ne $stopCoveragePolicy -and [string]$stopCoveragePolicy.contentDigest -cne [string]$stopConditionsRecord.coveragePolicyDigest) -or
            ($null -ne $stopThresholdPolicy -and [string]$stopThresholdPolicy.contentDigest -cne [string]$stopConditionsRecord.thresholdPolicyDigest) -or
            ($stopConditionsRecord.cadenceMinutes -isnot [int] -and $stopConditionsRecord.cadenceMinutes -isnot [long]) -or
            [int64]$stopConditionsRecord.cadenceMinutes -lt 1 -or
            [string]$stopConditionsRecord.alertOwnerRole -cnotmatch '^ROLE_[A-Z0-9_]+$' -or
            [string]$stopConditionsRecord.alertRouteRef -cnotmatch '^private://' -or
            -not [OperationsBlueprint.StrictRfc3339]::TryParse([string]$stopConditionsRecord.approvedAt, [ref]$stopSetApprovedAt) -or
            -not [OperationsBlueprint.StrictRfc3339]::TryParse([string]$stopConditionsRecord.expiresAt, [ref]$stopSetExpiresAt) -or
            $stopSetApprovedAt -gt $EvaluationTime -or
            ($pilotAuthorizationTimesValid -and $stopSetApprovedAt -gt $pilotAuthorizedAt) -or
            $stopSetExpiresAt -le $EvaluationTime) {
            Add-BlueprintError -Errors $errors -Code 'STOP_CONDITIONS_RECORD_MISMATCH' -Message 'Stop conditions do not bind a nonempty, digest-recomputed, current executable set for this manifest, persona, object, scope, typed query/baseline/policies, cadence, and alert route.'
        }
        foreach ($conditionRef in $conditionRefs) {
            $stopCondition = Resolve-CanonicalRecord -RecordMap $recordMap -Reference $conditionRef -ExpectedTypes @('stop-condition-record') -Context 'executable stop condition' -Errors $errors
            if ($null -eq $stopCondition) { continue }
            Test-RequiredProperties -Object $stopCondition -Names @(
                'schemaVersion', 'recordStage', 'status', 'stopConditionsRef', 'stopConditionsDigest',
                'conditionSetDigest', 'conditionId', 'signalId', 'sourceToolRef', 'metricId',
                'thresholdPolicyRef', 'thresholdPolicyDigest', 'thresholdPointer', 'comparison',
                'evaluationWindowMinutes', 'cadenceMinutes', 'missingDisposition', 'breachDisposition',
                'rollbackRef', 'rollbackDigest', 'requalificationPlanRef', 'requalificationPlanDigest',
                'ownerRole', 'alertRouteRef', 'approvedAt', 'expiresAt'
            ) -Context 'executable stop condition record' -Errors $errors
            $conditionPolicy = Resolve-CanonicalRecord -RecordMap $recordMap -Reference $stopCondition.thresholdPolicyRef -ExpectedTypes @('threshold-policy') -Context 'stop condition threshold policy' -Errors $errors
            $conditionRequalification = Resolve-CanonicalRecord -RecordMap $recordMap -Reference $stopCondition.requalificationPlanRef -ExpectedTypes @('requalification-plan-record') -Context 'stop condition requalification plan' -Errors $errors
            $thresholdFound = $false
            if ($null -ne $conditionPolicy -and [string]$stopCondition.thresholdPointer -cmatch '^#/.+') {
                [void](Get-JsonPointerValue -Document $conditionPolicy.payload -Pointer ([string]$stopCondition.thresholdPointer).Substring(1) -Found ([ref]$thresholdFound))
            }
            [DateTimeOffset]$conditionApprovedAt = [DateTimeOffset]::MinValue
            [DateTimeOffset]$conditionExpiresAt = [DateTimeOffset]::MinValue
            $knownToolIds = if ($null -ne $Registry) { @($Registry.bindings | ForEach-Object { [string]$_.toolId }) } else { @() }
            if ([string]$stopCondition.schemaVersion -cne '1.0.0' -or
                [string]$stopCondition.recordStage -cne 'STOP_CONDITION' -or [string]$stopCondition.status -cne 'APPROVED' -or
                [string]$stopCondition.stopConditionsRef -cne [string]$authorization.stopConditionsRef -or
                [string]$stopCondition.stopConditionsDigest -cne [string]$stopConditionsRecord.contentDigest -or
                [string]$stopCondition.conditionSetDigest -cne [string]$expectedConditionSetDigest -or
                -not (Test-NonBlankString $stopCondition.conditionId) -or -not (Test-NonBlankString $stopCondition.signalId) -or
                $knownToolIds -cnotcontains [string]$stopCondition.sourceToolRef -or -not (Test-NonBlankString $stopCondition.metricId) -or
                [string]$stopCondition.thresholdPolicyRef -cne [string]$stopConditionsRecord.thresholdPolicyRef -or
                ($null -ne $conditionPolicy -and [string]$stopCondition.thresholdPolicyDigest -cne [string]$conditionPolicy.contentDigest) -or
                -not $thresholdFound -or [string]$stopCondition.comparison -cnotin @('GT','GTE','LT','LTE','EQ','NEQ','OUTSIDE_RANGE') -or
                ($stopCondition.evaluationWindowMinutes -isnot [int] -and $stopCondition.evaluationWindowMinutes -isnot [long]) -or
                ($stopCondition.cadenceMinutes -isnot [int] -and $stopCondition.cadenceMinutes -isnot [long]) -or
                [int64]$stopCondition.evaluationWindowMinutes -lt 1 -or [int64]$stopCondition.cadenceMinutes -lt 1 -or
                [int64]$stopCondition.cadenceMinutes -gt [int64]$stopCondition.evaluationWindowMinutes -or
                [int64]$stopCondition.cadenceMinutes -ne [int64]$stopConditionsRecord.cadenceMinutes -or
                [string]$stopCondition.missingDisposition -cnotin @('HOLD','INCONCLUSIVE') -or
                [string]$stopCondition.breachDisposition -cnotin @('HOLD','ROLLBACK','REQUALIFY') -or
                [string]$stopCondition.rollbackRef -cne [string]$authorization.rollbackRef -or
                [string]$stopCondition.rollbackDigest -cne [string]$authorization.rollbackDigest -or
                ($null -ne $conditionRequalification -and [string]$stopCondition.requalificationPlanDigest -cne [string]$conditionRequalification.contentDigest) -or
                [string]$stopCondition.ownerRole -cnotmatch '^ROLE_[A-Z0-9_]+$' -or [string]$stopCondition.alertRouteRef -cnotmatch '^private://' -or
                -not [OperationsBlueprint.StrictRfc3339]::TryParse([string]$stopCondition.approvedAt, [ref]$conditionApprovedAt) -or
                -not [OperationsBlueprint.StrictRfc3339]::TryParse([string]$stopCondition.expiresAt, [ref]$conditionExpiresAt) -or
                $conditionApprovedAt -gt $EvaluationTime -or $conditionExpiresAt -le $EvaluationTime) {
                Add-BlueprintError -Errors $errors -Code 'STOP_CONDITION_NOT_EXECUTABLE' -Message 'A stop-condition member is stale, unresolved, unowned, unsafe, or not executable against its exact source, metric, threshold, cadence, rollback, and requalification plan.'
            }
        }
    }
    if ($null -ne $rollbackRecord) {
        Test-RequiredProperties -Object $rollbackRecord -Names @(
            'status', 'targetScopeRef', 'managedObjectType', 'desiredStateRevision', 'packageDigest',
            'priorKnownGoodReadbackRef', 'priorKnownGoodReadbackDigest',
            'priorKnownGoodDesiredStateRevision', 'priorKnownGoodPackageDigest',
            'priorKnownGoodTargetMembershipDigest', 'rollbackArtifactRef', 'rollbackArtifactDigest',
            'rollbackArtifactAttestationRef', 'rollbackArtifactAttestationDigest',
            'postRollbackReadbackPolicyRef', 'postRollbackReadbackPolicyDigest',
            'postRollbackReadbackMaxAgeMinutes', 'ownerRole', 'approvedAt', 'expiresAt'
        ) -Context 'rollback record' -Errors $errors
        $priorReadback = Resolve-CanonicalRecord -RecordMap $recordMap -Reference $rollbackRecord.priorKnownGoodReadbackRef -ExpectedTypes @('readback-record') -Context 'prior known-good rollback readback' -Errors $errors
        [DateTimeOffset]$rollbackApprovedAt = [DateTimeOffset]::MinValue
        [DateTimeOffset]$rollbackExpiresAt = [DateTimeOffset]::MinValue
        if ([string]$rollbackRecord.contentDigest -cne [string]$authorization.rollbackDigest -or
            [string]$rollbackRecord.status -cne 'APPROVED' -or
            [string]$rollbackRecord.targetScopeRef -cne [string]$Request.targetScopeRef -or
            [string]$rollbackRecord.managedObjectType -cne [string]$Request.managedObjectType -or
            [string]$rollbackRecord.desiredStateRevision -cne [string]$Request.desiredStateRevision -or
            [string]$rollbackRecord.packageDigest -cne [string]$Request.packageDigest -or
            -not (Test-Sha256Token $rollbackRecord.priorKnownGoodDesiredStateRevision) -or
            -not (Test-Sha256Token $rollbackRecord.priorKnownGoodPackageDigest) -or
            -not (Test-Sha256Token $rollbackRecord.priorKnownGoodTargetMembershipDigest) -or
            [string]$rollbackRecord.rollbackArtifactRef -cnotmatch '^private://' -or -not (Test-Sha256Token $rollbackRecord.rollbackArtifactDigest) -or
            [string]$rollbackRecord.rollbackArtifactAttestationRef -cnotmatch '^private://' -or -not (Test-Sha256Token $rollbackRecord.rollbackArtifactAttestationDigest) -or
            [string]$rollbackRecord.postRollbackReadbackPolicyRef -cnotmatch '^private://' -or -not (Test-Sha256Token $rollbackRecord.postRollbackReadbackPolicyDigest) -or
            ($rollbackRecord.postRollbackReadbackMaxAgeMinutes -isnot [int] -and $rollbackRecord.postRollbackReadbackMaxAgeMinutes -isnot [long]) -or
            [int64]$rollbackRecord.postRollbackReadbackMaxAgeMinutes -lt 1 -or [int64]$rollbackRecord.postRollbackReadbackMaxAgeMinutes -gt 1440 -or
            [string]$rollbackRecord.ownerRole -cnotmatch '^ROLE_[A-Z0-9_]+$' -or
            -not [OperationsBlueprint.StrictRfc3339]::TryParse([string]$rollbackRecord.approvedAt, [ref]$rollbackApprovedAt) -or
            -not [OperationsBlueprint.StrictRfc3339]::TryParse([string]$rollbackRecord.expiresAt, [ref]$rollbackExpiresAt) -or
            $rollbackApprovedAt -gt $EvaluationTime -or
            ($pilotAuthorizationTimesValid -and $rollbackApprovedAt -gt $pilotAuthorizedAt) -or
            $rollbackExpiresAt -le $EvaluationTime) {
            Add-BlueprintError -Errors $errors -Code 'ROLLBACK_RECORD_MISMATCH' -Message 'Rollback does not bind this exact scope/current state and a current attested artifact, prior known-good revision/package/membership/readback, owner, and post-rollback readback policy.'
        }
        if ($null -ne $priorReadback) {
            Test-RequiredProperties -Object $priorReadback -Names @(
                'schemaVersion', 'recordStage', 'status', 'readbackKind', 'writeAuthorizationRef',
                'writeAuthorizationDigest', 'authorizationId', 'authorizationNonce',
                'authorizationConsumptionRef', 'authorizationConsumptionDigest', 'consumptionLedgerDigest',
                'consumptionLedgerSequence', 'replayCheckStatus', 'consumedAt', 'writeOperationRef',
                'writeOperationDigest', 'writeOperationId', 'independentReadbackPolicyRef',
                'independentReadbackPolicyDigest', 'managedObjectType', 'targetScopeRef',
                'observedStateRevision', 'observedPackageDigest', 'targetMembershipDigest',
                'assignmentMatched', 'deviceStateMatched', 'collectedAt'
            ) -Context 'prior known-good rollback readback' -Errors $errors
            $priorConsumption = Resolve-CanonicalRecord -RecordMap $recordMap -Reference $priorReadback.authorizationConsumptionRef -ExpectedTypes @('authorization-consumption-record') -Context 'prior known-good authorization consumption' -Errors $errors
            $priorWriteOperation = Resolve-CanonicalRecord -RecordMap $recordMap -Reference $priorReadback.writeOperationRef -ExpectedTypes @('write-operation-record') -Context 'prior known-good write operation' -Errors $errors
            [DateTimeOffset]$priorReadbackAt = [DateTimeOffset]::MinValue
            if ([string]$priorReadback.contentDigest -cne [string]$rollbackRecord.priorKnownGoodReadbackDigest -or
                [string]$priorReadback.schemaVersion -cne '1.0.0' -or
                [string]$priorReadback.readbackKind -cne 'INTUNE_POST_WRITE' -or
                [string]$priorReadback.recordStage -cne 'INTUNE_POST_WRITE_READBACK' -or
                [string]$priorReadback.status -cne 'VERIFIED' -or
                [string]$priorReadback.targetScopeRef -cne [string]$Request.targetScopeRef -or
                [string]$priorReadback.managedObjectType -cne [string]$Request.managedObjectType -or
                [string]$priorReadback.observedStateRevision -cne [string]$rollbackRecord.priorKnownGoodDesiredStateRevision -or
                [string]$priorReadback.observedPackageDigest -cne [string]$rollbackRecord.priorKnownGoodPackageDigest -or
                [string]$priorReadback.targetMembershipDigest -cne [string]$rollbackRecord.priorKnownGoodTargetMembershipDigest -or
                [string]$priorReadback.replayCheckStatus -cne 'NOT_REUSED' -or
                ($priorReadback.consumptionLedgerSequence -isnot [int] -and $priorReadback.consumptionLedgerSequence -isnot [long]) -or
                [int64]$priorReadback.consumptionLedgerSequence -lt 1 -or
                -not (Test-Sha256Token $priorReadback.consumptionLedgerDigest) -or
                [string]$priorReadback.independentReadbackPolicyRef -cnotmatch '^private://' -or
                -not (Test-Sha256Token $priorReadback.independentReadbackPolicyDigest) -or
                ($null -ne $priorConsumption -and
                    ([string]$priorConsumption.contentDigest -cne [string]$priorReadback.authorizationConsumptionDigest -or
                     [string]$priorConsumption.status -cne 'COMMITTED' -or
                     [string]$priorConsumption.authorizationRef -cne [string]$priorReadback.writeAuthorizationRef -or
                     [string]$priorConsumption.authorizationDigest -cne [string]$priorReadback.writeAuthorizationDigest -or
                     [string]$priorConsumption.authorizationNonce -cne [string]$priorReadback.authorizationNonce -or
                     [string]$priorConsumption.consumptionLedgerDigest -cne [string]$priorReadback.consumptionLedgerDigest -or
                     [string]$priorConsumption.consumptionLedgerSequence -cne [string]$priorReadback.consumptionLedgerSequence -or
                     [string]$priorConsumption.consumedAt -cne [string]$priorReadback.consumedAt -or
                     [string]$priorConsumption.independentReadbackPolicyRef -cne [string]$priorReadback.independentReadbackPolicyRef -or
                     [string]$priorConsumption.independentReadbackPolicyDigest -cne [string]$priorReadback.independentReadbackPolicyDigest)) -or
                ($null -ne $priorWriteOperation -and
                    ([string]$priorWriteOperation.contentDigest -cne [string]$priorReadback.writeOperationDigest -or
                     [string]$priorWriteOperation.operationId -cne [string]$priorReadback.writeOperationId -or
                     [string]$priorWriteOperation.status -cne 'COMPLETED' -or
                     [string]$priorWriteOperation.desiredStateRevision -cne [string]$rollbackRecord.priorKnownGoodDesiredStateRevision -or
                     [string]$priorWriteOperation.packageDigest -cne [string]$rollbackRecord.priorKnownGoodPackageDigest -or
                     [string]$priorWriteOperation.targetMembershipDigest -cne [string]$rollbackRecord.priorKnownGoodTargetMembershipDigest)) -or
                $priorReadback.assignmentMatched -ne $true -or $priorReadback.deviceStateMatched -ne $true -or
                -not [OperationsBlueprint.StrictRfc3339]::TryParse([string]$priorReadback.collectedAt, [ref]$priorReadbackAt) -or
                $priorReadbackAt -gt $rollbackApprovedAt) {
                Add-BlueprintError -Errors $errors -Code 'ROLLBACK_PRIOR_KNOWN_GOOD_INVALID' -Message 'Rollback prior known-good readback is not verified, earlier than approval, or bound to the exact prior revision, package, membership, scope, and object.'
            }
        }
    }

    $hasConditionalVerdict = [string]$authorization.phase3Verdict -ceq 'QUALIFY_WITH_CONDITIONS'

    if ($Request.requestedStage -ceq 'PRODUCTION') {
        $finalVerdictRecord = $null
        Test-RequiredProperties -Object $authorization -Names @(
            'pilotCompletionStatus', 'finalVerdictRef', 'fleetVerdict', 'personaVerdict',
            'procurementEnvelopeRef', 'deltaQualificationStatus'
        ) -Context 'production authorization' -Errors $errors
        if ($authorization.pilotCompletionStatus -cne 'COMPLETE') {
            Add-BlueprintError -Errors $errors -Code 'PILOT_NOT_COMPLETE' -Message 'Production requires completed pilot evidence.'
        }
        if (-not (Test-ValuePresent $authorization.finalVerdictRef)) {
            Add-BlueprintError -Errors $errors -Code 'FINAL_VERDICT_MISSING' -Message 'Production requires a Phase 5 final verdict.'
        }
        else { $finalVerdictRecord = Resolve-CanonicalRecord -RecordMap $recordMap -Reference $authorization.finalVerdictRef -ExpectedTypes @('verdict-record') -Context 'final verdict' -Errors $errors }
        if ($authorization.fleetVerdict -cnotin @('QUALIFY', 'QUALIFY_WITH_CONDITIONS')) {
            Add-BlueprintError -Errors $errors -Code 'FLEET_VERDICT_BLOCKS' -Message 'Fleet verdict blocks production.'
        }
        if ($authorization.personaVerdict -cnotin @('QUALIFY', 'QUALIFY_WITH_CONDITIONS')) {
            Add-BlueprintError -Errors $errors -Code 'PERSONA_VERDICT_BLOCKS' -Message 'Persona verdict blocks production for the requested persona.'
        }
        if ([string]$authorization.fleetVerdict -ceq 'QUALIFY_WITH_CONDITIONS' -or
            [string]$authorization.personaVerdict -ceq 'QUALIFY_WITH_CONDITIONS' -or
            ($null -ne $finalVerdictRecord -and [string]$finalVerdictRecord.procurementDisposition -ceq 'APPROVED_WITH_CONDITIONS')) {
            $hasConditionalVerdict = $true
        }
        if (-not (Test-ValuePresent $authorization.procurementEnvelopeRef)) {
            Add-BlueprintError -Errors $errors -Code 'PROCUREMENT_ENVELOPE_MISSING' -Message 'Production requires a locked procurement envelope.'
        }
        else {
            [void](Resolve-CanonicalRecord -RecordMap $recordMap -Reference $authorization.procurementEnvelopeRef -ExpectedTypes @('verdict-record') -Context 'procurement envelope' -Errors $errors)
            if ([string]$authorization.procurementEnvelopeRef -cne ([string]$authorization.finalVerdictRef + '#/procurementEnvelope')) {
                Add-BlueprintError -Errors $errors -Code 'PROCUREMENT_ENVELOPE_VERDICT_MISMATCH' -Message 'Production procurement envelope must be the exact envelope in the final verdict.'
            }
        }
        if ($null -ne $finalVerdictRecord) {
            Test-RequiredProperties -Object $finalVerdictRecord -Names @(
                'schemaVersion', 'recordStage', 'status', 'manifestRef', 'pilotCompletion',
                'fleetVerdict', 'personaVerdicts', 'procurementEnvelope', 'procurementDisposition'
            ) -Context 'production final verdict' -Errors $errors
            $personaMatches = @($finalVerdictRecord.personaVerdicts | Where-Object { [string]$_.persona -ceq [string]$Request.personaId })
            if ([string]$finalVerdictRecord.schemaVersion -cne '2.0.1' -or
                [string]$finalVerdictRecord.recordStage -cne 'phase5-final' -or
                [string]$finalVerdictRecord.status -cne 'approved-and-immutable' -or
                [string]$finalVerdictRecord.manifestRef -cne [string]$Request.manifestRef -or
                [string]$finalVerdictRecord.pilotCompletion.status -cne 'COMPLETED' -or
                [string]$finalVerdictRecord.fleetVerdict -cne [string]$authorization.fleetVerdict -or
                $personaMatches.Count -ne 1 -or
                ($personaMatches.Count -eq 1 -and [string]$personaMatches[0].verdict -cne [string]$authorization.personaVerdict)) {
                Add-BlueprintError -Errors $errors -Code 'FINAL_VERDICT_RECORD_MISMATCH' -Message 'Production request claims differ from the retained final verdict, pilot completion, manifest, or selected persona.'
            }
            if ([string]$finalVerdictRecord.procurementDisposition -cnotin @('APPROVED', 'APPROVED_WITH_CONDITIONS') -or
                @($finalVerdictRecord.procurementEnvelope.substitutionAssessments | Where-Object {
                    [string]$_.identityStatus -ceq 'UNKNOWN' -or [string]$_.disposition -cin @('HOLD', 'DELTA_QUALIFICATION_REQUIRED')
                }).Count -gt 0) {
                Add-BlueprintError -Errors $errors -Code 'FINAL_PROCUREMENT_ENVELOPE_BLOCKS' -Message 'Final verdict procurement envelope is blocked by disposition, unknown identity, or pending delta qualification.'
            }
        }
        if ($authorization.deltaQualificationStatus -cnotin @('NOT_REQUIRED', 'COMPLETE')) {
            Add-BlueprintError -Errors $errors -Code 'DELTA_QUALIFICATION_NOT_COMPLETE' -Message 'Unknown, pending, or incomplete delta qualification blocks production.'
        }
        Test-RolloutMonitoringBinding -Request $Request -Authorization $authorization -RecordMap $recordMap `
            -PlanRecord $planRecord -FinalVerdictRecord $finalVerdictRecord `
            -StopConditionsRecord $stopConditionsRecord -RollbackRecord $rollbackRecord `
            -Registry $Registry -EvaluationTime $EvaluationTime -ValidationProfile $ValidationProfile -Errors $errors
    }

    if ($authorization.componentIdentityStatus -cne 'KNOWN') {
        Add-BlueprintError -Errors $errors -Code 'UNKNOWN_COMPONENT_IDENTITY' -Message 'Unknown component identity produces HOLD at every activation stage.'
    }

    [string[]]$requiredFinalConditionIds = @()
    if ($Request.requestedStage -ceq 'PRODUCTION' -and $null -ne $finalVerdictRecord) {
        $conditionIdValues = @($finalVerdictRecord.conditions | ForEach-Object { [string]$_.conditionId })
        if (@($conditionIdValues | Where-Object { [string]::IsNullOrWhiteSpace([string]$_) }).Count -gt 0 -or
            @($conditionIdValues | Group-Object -CaseSensitive | Where-Object Count -gt 1).Count -gt 0) {
            Add-BlueprintError -Errors $errors -Code 'FINAL_CONDITION_SET_INVALID' -Message 'Final verdict condition identifiers must be nonblank and ordinally unique.'
        }
        $requiredFinalConditionIds = [string[]]@($conditionIdValues | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_) })
        $procurementConditional = [string]$finalVerdictRecord.procurementDisposition -ceq 'APPROVED_WITH_CONDITIONS'
        if (($procurementConditional -or
             [string]$authorization.fleetVerdict -ceq 'QUALIFY_WITH_CONDITIONS' -or
             [string]$authorization.personaVerdict -ceq 'QUALIFY_WITH_CONDITIONS') -and
            $requiredFinalConditionIds.Count -eq 0) {
            Add-BlueprintError -Errors $errors -Code 'CONDITIONAL_VERDICT_WITHOUT_COMPLETE_CONDITIONS' -Message 'Fleet, persona, and procurement conditional dispositions require a nonempty final-verdict condition set.'
        }
    }

    if ($hasConditionalVerdict) {
        if ([string]$authorization.conditionsStatus -cne 'CURRENT_WITH_ACTIVE_CONTROLS' -or
            -not (Test-ValuePresent $authorization.conditionRecordRefs)) {
            Add-BlueprintError -Errors $errors -Code 'CONDITIONAL_VERDICT_BINDING_MISSING' -Message 'Every conditional verdict requires current, scoped, owned, unexpired condition records.'
        }
        else {
            $boundConditionIds = New-Object System.Collections.ArrayList
            foreach ($conditionRef in @($authorization.conditionRecordRefs)) {
                $conditionRecord = Resolve-CanonicalRecord -RecordMap $recordMap -Reference $conditionRef -ExpectedTypes @('condition-record') -Context 'conditional verdict' -Errors $errors
                if ($null -eq $conditionRecord) { continue }
                Test-RequiredProperties -Object $conditionRecord -Names @(
                    'ownerRole', 'sourceDecisionRef', 'sourceConditionId', 'targetScopeRef',
                    'personaId', 'managedObjectType', 'conditionState', 'compensatingControlRefs', 'expiresAt'
                ) -Context "condition record $($conditionRecord.recordId)" -Errors $errors
                if (Test-NonBlankString $conditionRecord.sourceConditionId) {
                    [void]$boundConditionIds.Add([string]$conditionRecord.sourceConditionId)
                }
                [DateTimeOffset]$conditionExpiresAt = [DateTimeOffset]::MinValue
                if ([string]$conditionRecord.conditionState -cnotin @('ACTIVE', 'SATISFIED') -or
                    [string]$conditionRecord.ownerRole -cnotmatch '^ROLE_[A-Z0-9_]+$' -or
                    [string]$conditionRecord.sourceDecisionRef -cne $(if ($Request.requestedStage -ceq 'PRODUCTION') { [string]$authorization.finalVerdictRef } else { [string]$authorization.pilotAuthorizationRef }) -or
                    [string]$conditionRecord.targetScopeRef -cne [string]$Request.targetScopeRef -or
                    [string]$conditionRecord.personaId -cne [string]$Request.personaId -or
                    [string]$conditionRecord.managedObjectType -cne [string]$Request.managedObjectType -or
                    -not (Test-ValuePresent $conditionRecord.compensatingControlRefs) -or
                    -not [OperationsBlueprint.StrictRfc3339]::TryParse([string]$conditionRecord.expiresAt, [ref]$conditionExpiresAt) -or
                    $conditionExpiresAt -le $EvaluationTime) {
                    Add-BlueprintError -Errors $errors -Code 'CONDITIONAL_VERDICT_BINDING_INVALID' -Message "$($conditionRecord.recordId) is not current and bound to this decision, persona, object, scope, owner, and compensating controls."
                }
                if ($Request.requestedStage -ceq 'PRODUCTION' -and $personaMatches.Count -eq 1 -and
                    @($personaMatches[0].conditionRefs) -cnotcontains [string]$conditionRecord.sourceConditionId) {
                    Add-BlueprintError -Errors $errors -Code 'CONDITION_NOT_IN_FINAL_VERDICT' -Message "$($conditionRecord.recordId) does not correspond to a selected-persona condition in the final verdict."
                }
                foreach ($controlRef in @($conditionRecord.compensatingControlRefs)) {
                    $controlRecord = Resolve-CanonicalRecord -RecordMap $recordMap -Reference $controlRef -ExpectedTypes @('compensating-control-record') -Context 'condition compensating control' -Errors $errors
                    if ($null -eq $controlRecord) { continue }
                    Test-RequiredProperties -Object $controlRecord -Names @(
                        'status', 'targetScopeRef', 'personaId', 'managedObjectType', 'expiresAt'
                    ) -Context "compensating control $($controlRecord.recordId)" -Errors $errors
                    [DateTimeOffset]$controlExpiresAt = [DateTimeOffset]::MinValue
                    if ([string]$controlRecord.status -cne 'ACTIVE' -or
                        [string]$controlRecord.targetScopeRef -cne [string]$Request.targetScopeRef -or
                        [string]$controlRecord.personaId -cne [string]$Request.personaId -or
                        [string]$controlRecord.managedObjectType -cne [string]$Request.managedObjectType -or
                        -not [OperationsBlueprint.StrictRfc3339]::TryParse([string]$controlRecord.expiresAt, [ref]$controlExpiresAt) -or
                        $controlExpiresAt -le $EvaluationTime) {
                        Add-BlueprintError -Errors $errors -Code 'COMPENSATING_CONTROL_INVALID' -Message "$($controlRecord.recordId) is not active for this exact persona, object, and scope."
                    }
                }
            }
            if ($Request.requestedStage -ceq 'PRODUCTION') {
                if (@($boundConditionIds | Group-Object -CaseSensitive | Where-Object Count -gt 1).Count -gt 0 -or
                    @($boundConditionIds).Count -ne $requiredFinalConditionIds.Count) {
                    Add-BlueprintError -Errors $errors -Code 'FINAL_CONDITION_SET_BINDING_MISMATCH' -Message 'Production condition records must bind the exact complete final-verdict condition set once each.'
                }
                foreach ($requiredConditionId in $requiredFinalConditionIds) {
                    if (@($boundConditionIds) -cnotcontains [string]$requiredConditionId) {
                        Add-BlueprintError -Errors $errors -Code 'FINAL_CONDITION_SET_BINDING_MISMATCH' -Message 'Production condition records omit a final-verdict condition.'
                    }
                }
                foreach ($boundConditionId in @($boundConditionIds)) {
                    if ($requiredFinalConditionIds -cnotcontains [string]$boundConditionId) {
                        Add-BlueprintError -Errors $errors -Code 'FINAL_CONDITION_SET_BINDING_MISMATCH' -Message 'Production condition records include a condition outside the final verdict.'
                    }
                }
            }
        }
    }

    if ($null -eq $Readback) {
        Add-BlueprintError -Errors $errors -Code 'PRIVATE_ACTIVATION_IMPLEMENTATION_REQUIRED' -Message 'This public validator can identify blockers but cannot issue write authorization.'
        return New-BlueprintResult -Errors $errors -State $(if ([string]$ValidationProfile -ceq 'TEST') { 'TEST_FIXTURE_BLOCKED_NON_PROMOTABLE' } else { 'BLOCKED' })
    }

    Test-RequiredProperties -Object $Readback -Names @(
        'schemaVersion', 'recordStage', 'status', 'readbackKind', 'readerToolRef', 'readIdentityRef',
        'readbackRecordRef', 'readbackRecordDigest', 'writeAuthorizationRef', 'writeAuthorizationDigest',
        'authorizationId', 'authorizationNonce', 'authorizationConsumptionRef', 'authorizationConsumptionDigest',
        'authorizationConsumptionReadbackRef', 'authorizationConsumptionReadbackDigest',
        'consumptionLedgerDigest', 'consumptionLedgerSequence', 'replayCheckStatus', 'consumedAt',
        'writeOperationRef', 'writeOperationDigest', 'writeOperationId', 'reviewedPlanRef', 'reviewedPlanDigest',
        'roleBindingRef', 'roleBindingDigest', 'roleBindingReadbackRef', 'roleBindingReadbackDigest',
        'packageVerificationRef', 'packageVerificationDigest',
        'independentReadbackPolicyRef', 'independentReadbackPolicyDigest', 'readbackMaxAgeMinutes',
        'writerToolRef', 'writeIdentityRef', 'applyOperatorIdentityRef', 'tenantBoundaryRef', 'targetEnvironmentRef', 'managedObjectType',
        'httpStatus', 'responseBodyPresent', 'observedStateRevision', 'observedPackageDigest',
        'targetMembershipDigest', 'targetScopeRef', 'targetPopulation',
        'assignmentMatched', 'deviceStateMatched', 'collectedAt'
    ) -Context 'activation readback' -Errors $errors
    Test-AllowedProperties -Object $Readback -Names @(
        'schemaVersion', 'recordStage', 'status', 'readbackKind', 'readerToolRef', 'readIdentityRef',
        'readbackRecordRef', 'readbackRecordDigest', 'writeAuthorizationRef', 'writeAuthorizationDigest',
        'authorizationId', 'authorizationNonce', 'authorizationConsumptionRef', 'authorizationConsumptionDigest',
        'authorizationConsumptionReadbackRef', 'authorizationConsumptionReadbackDigest',
        'consumptionLedgerDigest', 'consumptionLedgerSequence', 'replayCheckStatus', 'consumedAt',
        'writeOperationRef', 'writeOperationDigest', 'writeOperationId', 'reviewedPlanRef', 'reviewedPlanDigest',
        'roleBindingRef', 'roleBindingDigest', 'roleBindingReadbackRef', 'roleBindingReadbackDigest',
        'packageVerificationRef', 'packageVerificationDigest',
        'independentReadbackPolicyRef', 'independentReadbackPolicyDigest', 'readbackMaxAgeMinutes',
        'writerToolRef', 'writeIdentityRef', 'applyOperatorIdentityRef', 'tenantBoundaryRef', 'targetEnvironmentRef', 'managedObjectType',
        'transportExceptionRef', 'transportExceptionDigest',
        'httpStatus', 'responseBodyPresent', 'observedStateRevision', 'observedPackageDigest',
        'targetMembershipDigest', 'targetScopeRef', 'targetPopulation',
        'assignmentMatched', 'deviceStateMatched', 'collectedAt'
    ) -Context 'activation readback' -Errors $errors
    if ([string]$Request.writerToolRef -ceq 'microsoft-graph-write') {
        Test-RequiredProperties -Object $Readback -Names @('transportExceptionRef','transportExceptionDigest') -Context 'direct Graph activation readback' -Errors $errors
        if ([string]$Readback.transportExceptionRef -cne [string]$Request.transportExceptionRef -or
            [string]$Readback.transportExceptionDigest -cne [string]$Request.transportExceptionDigest) {
            Add-BlueprintError -Errors $errors -Code 'DIRECT_GRAPH_EXCEPTION_BINDING_MISMATCH' -Message 'Direct Graph readback does not bind the exact scoped provider-gap exception and digest.'
        }
    }
    elseif ((Test-ValuePresent $Readback.transportExceptionRef) -or (Test-ValuePresent $Readback.transportExceptionDigest)) {
        Add-BlueprintError -Errors $errors -Code 'DIRECT_GRAPH_EXCEPTION_FORBIDDEN' -Message 'Terraform-provider readback may not retain a direct-Graph exception.'
    }
    if ([string]$Readback.schemaVersion -cne '1.0.0' -or
        [string]$Readback.recordStage -cne 'INTUNE_POST_WRITE_READBACK' -or
        [string]$Readback.status -cne 'VERIFIED' -or
        [string]$Readback.readbackKind -cne 'INTUNE_POST_WRITE' -or
        [string]$Readback.readerToolRef -cne 'microsoft-graph-readback') {
        Add-BlueprintError -Errors $errors -Code 'UNAUTHORIZED_READBACK_TOOL' -Message 'Independent Microsoft Graph readback is required.'
    }
    if ([string]$Readback.readIdentityRef -notmatch '^private://' -or [string]$Readback.readIdentityRef -ceq [string]$Request.writeIdentityRef) {
        Add-BlueprintError -Errors $errors -Code 'READBACK_IDENTITY_NOT_INDEPENDENT' -Message 'Readback requires a distinct private read identity.'
    }
    if (-not (Test-Sha256Token $Readback.readbackRecordDigest)) {
        Add-BlueprintError -Errors $errors -Code 'INVALID_READBACK_DIGEST' -Message 'Readback record requires a SHA-256 token.'
    }
    $authorizationConsumptionReadbackRecord = $null
    [DateTimeOffset]$authorizationConsumptionObservedAt = [DateTimeOffset]::MinValue
    if (Test-ValuePresent $Readback.authorizationConsumptionReadbackRef) {
        $authorizationConsumptionReadbackRecord = Resolve-CanonicalRecord -RecordMap $recordMap `
            -Reference $Readback.authorizationConsumptionReadbackRef `
            -ExpectedTypes @('authorization-consumption-ledger-readback-record') `
            -Context 'independent authorization-consumption ledger readback' -Errors $errors
    }
    if ($null -eq $authorizationConsumptionReadbackRecord) {
        Add-BlueprintError -Errors $errors -Code 'AUTHORIZATION_CONSUMPTION_READBACK_REQUIRED' -Message 'Activation requires an independently attested readback of the authoritative authorization-consumption ledger.'
    }
    else {
        Test-RequiredProperties -Object $authorizationConsumptionReadbackRecord -Names @(
            'schemaVersion','recordStage','status','consumptionRecordRef','consumptionRecordDigest',
            'consumptionLedgerRef','ledgerAuthorityIdentityRef','authorizationRef','authorizationDigest',
            'authorizationId','authorizationNonce','authorizedOperationId','writeOperationRef',
            'writeOperationDigest','writeOperationId','consumptionLedgerSequence',
            'previousLedgerEntryDigest','resultingLedgerDigest','atomicCommitEvidenceRef',
            'atomicCommitEvidenceDigest','readerToolRef','readIdentityRef','observationArtifactRef',
            'observationArtifactDigest','observationArtifactAttestationRef',
            'observationArtifactAttestationDigest','observationArtifactAttestationStatus',
            'observedAt','maxAgeMinutes','readbackPolicyRef','readbackPolicyDigest',
            'chainStatus','replayStatus','consistencyStatus'
        ) -Context 'independent authorization-consumption ledger readback' -Errors $errors
        $observerTimeValid = [OperationsBlueprint.StrictRfc3339]::TryParse(
            [string]$authorizationConsumptionReadbackRecord.observedAt,
            [ref]$authorizationConsumptionObservedAt
        )
        $observerAgeValid = ($authorizationConsumptionReadbackRecord.maxAgeMinutes -is [int] -or
            $authorizationConsumptionReadbackRecord.maxAgeMinutes -is [long]) -and
            [int64]$authorizationConsumptionReadbackRecord.maxAgeMinutes -eq $effectiveReadbackMaxAgeMinutes
        if ([string]$authorizationConsumptionReadbackRecord.contentDigest -cne [string]$Readback.authorizationConsumptionReadbackDigest -or
            [string]$authorizationConsumptionReadbackRecord.schemaVersion -cne '1.0.0' -or
            [string]$authorizationConsumptionReadbackRecord.recordStage -cne 'AUTHORIZATION_CONSUMPTION_LEDGER_READBACK' -or
            [string]$authorizationConsumptionReadbackRecord.status -cne 'VERIFIED' -or
            $null -eq $authorizationConsumptionRecord -or
            ($null -ne $authorizationConsumptionRecord -and [string]$authorizationConsumptionReadbackRecord.consumptionRecordRef -cne [string]$authorizationConsumptionRecord.recordId) -or
            ($null -ne $authorizationConsumptionRecord -and [string]$authorizationConsumptionReadbackRecord.consumptionRecordDigest -cne [string]$authorizationConsumptionRecord.contentDigest) -or
            ($null -ne $authorizationConsumptionRecord -and [string]$authorizationConsumptionReadbackRecord.consumptionLedgerRef -cne [string]$authorizationConsumptionRecord.consumptionLedgerRef) -or
            ($null -ne $authorizationConsumptionRecord -and [string]$authorizationConsumptionReadbackRecord.ledgerAuthorityIdentityRef -cne [string]$authorizationConsumptionRecord.ledgerAuthorityIdentityRef) -or
            [string]$authorizationConsumptionReadbackRecord.authorizationRef -cne [string]$Request.writeAuthorizationRef -or
            [string]$authorizationConsumptionReadbackRecord.authorizationDigest -cne [string]$Request.writeAuthorizationDigest -or
            ($null -ne $writeAuthorizationRecord -and [string]$authorizationConsumptionReadbackRecord.authorizationId -cne [string]$writeAuthorizationRecord.authorizationId) -or
            ($null -ne $writeAuthorizationRecord -and [string]$authorizationConsumptionReadbackRecord.authorizationNonce -cne [string]$writeAuthorizationRecord.authorizationNonce) -or
            [string]$authorizationConsumptionReadbackRecord.authorizedOperationId -cne [string]$Request.writeOperationId -or
            [string]$authorizationConsumptionReadbackRecord.writeOperationRef -cne [string]$Request.writeOperationRef -or
            ($null -ne $writeOperationRecord -and [string]$authorizationConsumptionReadbackRecord.writeOperationDigest -cne [string]$writeOperationRecord.contentDigest) -or
            [string]$authorizationConsumptionReadbackRecord.writeOperationId -cne [string]$Request.writeOperationId -or
            ($null -ne $authorizationConsumptionRecord -and [string]$authorizationConsumptionReadbackRecord.consumptionLedgerSequence -cne [string]$authorizationConsumptionRecord.consumptionLedgerSequence) -or
            ($null -ne $authorizationConsumptionRecord -and [string]$authorizationConsumptionReadbackRecord.previousLedgerEntryDigest -cne [string]$authorizationConsumptionRecord.previousLedgerEntryDigest) -or
            ($null -ne $authorizationConsumptionRecord -and [string]$authorizationConsumptionReadbackRecord.resultingLedgerDigest -cne [string]$authorizationConsumptionRecord.consumptionLedgerDigest) -or
            ($null -ne $authorizationConsumptionRecord -and [string]$authorizationConsumptionReadbackRecord.atomicCommitEvidenceRef -cne [string]$authorizationConsumptionRecord.atomicCommitEvidenceRef) -or
            ($null -ne $authorizationConsumptionRecord -and [string]$authorizationConsumptionReadbackRecord.atomicCommitEvidenceDigest -cne [string]$authorizationConsumptionRecord.atomicCommitEvidenceDigest) -or
            [string]$authorizationConsumptionReadbackRecord.readerToolRef -cne 'authorization-consumption-ledger-readback' -or
            [string]$authorizationConsumptionReadbackRecord.readIdentityRef -cnotmatch '^private://' -or
            [string]$authorizationConsumptionReadbackRecord.observationArtifactRef -cnotmatch '^private://' -or
            -not (Test-Sha256Token $authorizationConsumptionReadbackRecord.observationArtifactDigest) -or
            [string]$authorizationConsumptionReadbackRecord.observationArtifactAttestationRef -cnotmatch '^private://' -or
            -not (Test-Sha256Token $authorizationConsumptionReadbackRecord.observationArtifactAttestationDigest) -or
            [string]$authorizationConsumptionReadbackRecord.observationArtifactAttestationStatus -cne 'VERIFIED' -or
            [string]$authorizationConsumptionReadbackRecord.readbackPolicyRef -cne [string]$Request.independentReadbackPolicyRef -or
            [string]$authorizationConsumptionReadbackRecord.readbackPolicyDigest -cne [string]$Request.independentReadbackPolicyDigest -or
            [string]$authorizationConsumptionReadbackRecord.chainStatus -cne 'PASS' -or
            [string]$authorizationConsumptionReadbackRecord.replayStatus -cne 'PASS' -or
            [string]$authorizationConsumptionReadbackRecord.consistencyStatus -cne 'PASS' -or
            -not $observerAgeValid -or -not $observerTimeValid -or
            ($null -ne $writeOperationRecord -and $authorizationConsumptionObservedAt -lt $retainedWriteCompletedAt) -or
            $authorizationConsumptionObservedAt -gt $EvaluationTime -or
            ($EvaluationTime - $authorizationConsumptionObservedAt).TotalMinutes -gt $effectiveReadbackMaxAgeMinutes) {
            Add-BlueprintError -Errors $errors -Code 'AUTHORIZATION_CONSUMPTION_READBACK_INVALID' -Message 'Independent ledger readback must be fresh, authenticated, non-replayed, chain-consistent, and bind the exact ledger authority, commit evidence, authorization, nonce, operation, sequence, prior entry, resulting digest, and readback policy.'
        }
    }
    if ([string]$Readback.writeOperationId -cne [string]$Request.writeOperationId) {
        Add-BlueprintError -Errors $errors -Code 'READBACK_OPERATION_MISMATCH' -Message 'Readback does not bind the evaluated write operation.'
    }
    if ([string]$Readback.writeOperationRef -cne [string]$Request.writeOperationRef -or
        ($null -ne $writeOperationRecord -and [string]$Readback.writeOperationDigest -cne [string]$writeOperationRecord.contentDigest)) {
        Add-BlueprintError -Errors $errors -Code 'READBACK_OPERATION_MISMATCH' -Message 'Readback operation reference or digest differs from the retained write operation.'
    }
    if ([string]$Readback.writeAuthorizationRef -cne [string]$Request.writeAuthorizationRef -or
        [string]$Readback.writeAuthorizationDigest -cne [string]$Request.writeAuthorizationDigest -or
        ($null -ne $writeAuthorizationRecord -and [string]$Readback.authorizationId -cne [string]$writeAuthorizationRecord.authorizationId) -or
        ($null -ne $writeAuthorizationRecord -and [string]$Readback.authorizationNonce -cne [string]$writeAuthorizationRecord.authorizationNonce) -or
        $null -eq $authorizationConsumptionRecord -or
        ($null -ne $authorizationConsumptionRecord -and [string]$Readback.authorizationConsumptionRef -cne [string]$authorizationConsumptionRecord.recordId) -or
        ($null -ne $authorizationConsumptionRecord -and [string]$Readback.authorizationConsumptionDigest -cne [string]$authorizationConsumptionRecord.contentDigest) -or
        $null -eq $authorizationConsumptionReadbackRecord -or
        ($null -ne $authorizationConsumptionReadbackRecord -and [string]$Readback.authorizationConsumptionReadbackRef -cne [string]$authorizationConsumptionReadbackRecord.recordId) -or
        ($null -ne $authorizationConsumptionReadbackRecord -and [string]$Readback.authorizationConsumptionReadbackDigest -cne [string]$authorizationConsumptionReadbackRecord.contentDigest) -or
        ($null -ne $authorizationConsumptionRecord -and [string]$Readback.consumptionLedgerDigest -cne [string]$authorizationConsumptionRecord.consumptionLedgerDigest) -or
        ($null -ne $authorizationConsumptionRecord -and [string]$Readback.consumptionLedgerSequence -cne [string]$authorizationConsumptionRecord.consumptionLedgerSequence) -or
        [string]$Readback.replayCheckStatus -cne 'NOT_REUSED' -or
        ($null -ne $authorizationConsumptionRecord -and [string]$Readback.consumedAt -cne [string]$authorizationConsumptionRecord.consumedAt) -or
        [string]$Readback.reviewedPlanRef -cne [string]$Request.reviewedPlanRef -or
        [string]$Readback.reviewedPlanDigest -cne [string]$Request.reviewedPlanDigest -or
        [string]$Readback.roleBindingRef -cne [string]$Request.roleBindingRef -or
        [string]$Readback.roleBindingDigest -cne [string]$Request.roleBindingDigest -or
        [string]$Readback.roleBindingReadbackRef -cne [string]$Request.roleBindingReadbackRef -or
        [string]$Readback.roleBindingReadbackDigest -cne [string]$Request.roleBindingReadbackDigest -or
        [string]$Readback.packageVerificationRef -cne [string]$Request.packageVerificationRef -or
        [string]$Readback.packageVerificationDigest -cne [string]$Request.packageVerificationDigest -or
        [string]$Readback.independentReadbackPolicyRef -cne [string]$Request.independentReadbackPolicyRef -or
        [string]$Readback.independentReadbackPolicyDigest -cne [string]$Request.independentReadbackPolicyDigest -or
        [string]$Readback.readbackMaxAgeMinutes -cne [string]$Request.readbackMaxAgeMinutes -or
        [string]$Readback.writerToolRef -cne [string]$Request.writerToolRef -or
        [string]$Readback.writeIdentityRef -cne [string]$Request.writeIdentityRef -or
        [string]$Readback.applyOperatorIdentityRef -cne [string]$Request.applyOperatorIdentityRef -or
        [string]$Readback.tenantBoundaryRef -cne [string]$Request.tenantBoundaryRef -or
        [string]$Readback.targetEnvironmentRef -cne [string]$Request.targetEnvironmentRef -or
        [string]$Readback.managedObjectType -cne [string]$Request.managedObjectType -or
        ([string]$Request.writerToolRef -ceq 'microsoft-graph-write' -and
            ([string]$Readback.transportExceptionRef -cne [string]$Request.transportExceptionRef -or
             [string]$Readback.transportExceptionDigest -cne [string]$Request.transportExceptionDigest)) -or
        ([string]$Request.writerToolRef -ceq 'msgraph-terraform-provider' -and
            ((Test-ValuePresent $Readback.transportExceptionRef) -or
             (Test-ValuePresent $Readback.transportExceptionDigest)))) {
        Add-BlueprintError -Errors $errors -Code 'READBACK_PROVENANCE_CLOSURE_MISMATCH' -Message 'Readback does not bind the exact authorization nonce, reviewed plan, and verified package used by the write.'
    }
    $readbackRecord = Resolve-CanonicalRecord -RecordMap $recordMap -Reference $Readback.readbackRecordRef -ExpectedTypes @('readback-record') -Context 'readback record' -Errors $errors
    $effectiveReadback = $Readback
    if ($null -ne $readbackRecord) {
        Test-RequiredProperties -Object $readbackRecord -Names @(
            'schemaVersion', 'recordStage', 'status', 'readbackKind', 'readerToolRef', 'readIdentityRef',
            'writeAuthorizationRef', 'writeAuthorizationDigest', 'authorizationId', 'authorizationNonce',
            'authorizationConsumptionRef', 'authorizationConsumptionDigest', 'consumptionLedgerDigest',
            'authorizationConsumptionReadbackRef', 'authorizationConsumptionReadbackDigest',
            'consumptionLedgerSequence', 'replayCheckStatus', 'consumedAt',
            'writeOperationRef', 'writeOperationDigest',
            'writeOperationId', 'writerToolRef', 'writeIdentityRef', 'managedObjectType',
            'reviewedPlanRef', 'reviewedPlanDigest', 'roleBindingRef', 'roleBindingDigest',
            'roleBindingReadbackRef', 'roleBindingReadbackDigest', 'packageVerificationRef', 'packageVerificationDigest',
            'independentReadbackPolicyRef', 'independentReadbackPolicyDigest', 'readbackMaxAgeMinutes',
            'applyOperatorIdentityRef', 'tenantBoundaryRef', 'targetEnvironmentRef',
            'httpStatus', 'responseBodyPresent', 'observedStateRevision', 'observedPackageDigest',
            'targetMembershipDigest', 'targetScopeRef', 'targetPopulation',
            'assignmentMatched', 'deviceStateMatched', 'collectedAt'
        ) -Context 'retained readback record' -Errors $errors
        if ([string]$Request.writerToolRef -ceq 'microsoft-graph-write') {
            Test-RequiredProperties -Object $readbackRecord -Names @('transportExceptionRef','transportExceptionDigest') -Context 'direct Graph retained readback record' -Errors $errors
        }
        if ([string]$readbackRecord.contentDigest -cne [string]$Readback.readbackRecordDigest -or
            [string]$readbackRecord.schemaVersion -cne [string]$Readback.schemaVersion -or
            [string]$readbackRecord.recordStage -cne [string]$Readback.recordStage -or
            [string]$readbackRecord.status -cne [string]$Readback.status -or
            [string]$readbackRecord.readbackKind -cne [string]$Readback.readbackKind -or
            [string]$readbackRecord.writeOperationRef -cne [string]$Request.writeOperationRef -or
            [string]$readbackRecord.writeOperationDigest -cne [string]$writeOperationRecord.contentDigest -or
            [string]$readbackRecord.writeOperationId -cne [string]$Request.writeOperationId -or
            [string]$readbackRecord.writeAuthorizationRef -cne [string]$Request.writeAuthorizationRef -or
            [string]$readbackRecord.writeAuthorizationDigest -cne [string]$Request.writeAuthorizationDigest -or
            ($null -ne $writeAuthorizationRecord -and [string]$readbackRecord.authorizationId -cne [string]$writeAuthorizationRecord.authorizationId) -or
            ($null -ne $writeAuthorizationRecord -and [string]$readbackRecord.authorizationNonce -cne [string]$writeAuthorizationRecord.authorizationNonce) -or
            ($null -ne $authorizationConsumptionRecord -and [string]$readbackRecord.authorizationConsumptionRef -cne [string]$authorizationConsumptionRecord.recordId) -or
            ($null -ne $authorizationConsumptionRecord -and [string]$readbackRecord.authorizationConsumptionDigest -cne [string]$authorizationConsumptionRecord.contentDigest) -or
            ($null -ne $authorizationConsumptionReadbackRecord -and [string]$readbackRecord.authorizationConsumptionReadbackRef -cne [string]$authorizationConsumptionReadbackRecord.recordId) -or
            ($null -ne $authorizationConsumptionReadbackRecord -and [string]$readbackRecord.authorizationConsumptionReadbackDigest -cne [string]$authorizationConsumptionReadbackRecord.contentDigest) -or
            ($null -ne $authorizationConsumptionRecord -and [string]$readbackRecord.consumptionLedgerDigest -cne [string]$authorizationConsumptionRecord.consumptionLedgerDigest) -or
            ($null -ne $authorizationConsumptionRecord -and [string]$readbackRecord.consumptionLedgerSequence -cne [string]$authorizationConsumptionRecord.consumptionLedgerSequence) -or
            [string]$readbackRecord.replayCheckStatus -cne [string]$Readback.replayCheckStatus -or
            [string]$readbackRecord.consumedAt -cne [string]$Readback.consumedAt -or
            [string]$readbackRecord.reviewedPlanRef -cne [string]$Request.reviewedPlanRef -or
            [string]$readbackRecord.reviewedPlanDigest -cne [string]$Request.reviewedPlanDigest -or
            [string]$readbackRecord.roleBindingRef -cne [string]$Request.roleBindingRef -or
            [string]$readbackRecord.roleBindingDigest -cne [string]$Request.roleBindingDigest -or
            [string]$readbackRecord.roleBindingReadbackRef -cne [string]$Request.roleBindingReadbackRef -or
            [string]$readbackRecord.roleBindingReadbackDigest -cne [string]$Request.roleBindingReadbackDigest -or
            [string]$readbackRecord.packageVerificationRef -cne [string]$Request.packageVerificationRef -or
            [string]$readbackRecord.packageVerificationDigest -cne [string]$Request.packageVerificationDigest -or
            [string]$readbackRecord.independentReadbackPolicyRef -cne [string]$Request.independentReadbackPolicyRef -or
            [string]$readbackRecord.independentReadbackPolicyDigest -cne [string]$Request.independentReadbackPolicyDigest -or
            [string]$readbackRecord.readbackMaxAgeMinutes -cne [string]$Request.readbackMaxAgeMinutes -or
            [string]$readbackRecord.applyOperatorIdentityRef -cne [string]$Request.applyOperatorIdentityRef -or
            [string]$readbackRecord.tenantBoundaryRef -cne [string]$Request.tenantBoundaryRef -or
            [string]$readbackRecord.targetEnvironmentRef -cne [string]$Request.targetEnvironmentRef -or
            ([string]$Request.writerToolRef -ceq 'microsoft-graph-write' -and
                ([string]$readbackRecord.transportExceptionRef -cne [string]$Request.transportExceptionRef -or
                 [string]$readbackRecord.transportExceptionDigest -cne [string]$Request.transportExceptionDigest)) -or
            ([string]$Request.writerToolRef -ceq 'msgraph-terraform-provider' -and
                ((Test-ValuePresent $readbackRecord.transportExceptionRef) -or
                 (Test-ValuePresent $readbackRecord.transportExceptionDigest))) -or
            [string]$readbackRecord.writerToolRef -cne [string]$Request.writerToolRef -or
            [string]$readbackRecord.writeIdentityRef -cne [string]$Request.writeIdentityRef -or
            [string]$readbackRecord.managedObjectType -cne [string]$Request.managedObjectType -or
            [string]$readbackRecord.readerToolRef -cne [string]$Readback.readerToolRef -or
            [string]$readbackRecord.readIdentityRef -cne [string]$Readback.readIdentityRef -or
            [string]$readbackRecord.httpStatus -cne [string]$Readback.httpStatus -or
            [string]$readbackRecord.responseBodyPresent -cne [string]$Readback.responseBodyPresent -or
            [string]$readbackRecord.observedStateRevision -cne [string]$Readback.observedStateRevision -or
            [string]$readbackRecord.observedPackageDigest -cne [string]$Readback.observedPackageDigest -or
            [string]$readbackRecord.targetMembershipDigest -cne [string]$Readback.targetMembershipDigest -or
            [string]$readbackRecord.targetScopeRef -cne [string]$Readback.targetScopeRef -or
            -not (Test-CanonicalValueEqual $readbackRecord.targetPopulation $Readback.targetPopulation) -or
            [string]$readbackRecord.assignmentMatched -cne [string]$Readback.assignmentMatched -or
            [string]$readbackRecord.deviceStateMatched -cne [string]$Readback.deviceStateMatched -or
            [string]$readbackRecord.collectedAt -cne [string]$Readback.collectedAt) {
            Add-BlueprintError -Errors $errors -Code 'READBACK_RECORD_BINDING_MISMATCH' -Message 'Caller readback differs from the verified retained record or its exact write operation, transport, identity, object, scope, revision, package, membership, state, or time.'
        }
        $effectiveReadback = $readbackRecord
    }

    # Separation of duties is evaluated once across the whole operation, not
    # as independent pairwise checks that can miss a transitive overlap.
    $operationPrincipals = New-Object System.Collections.ArrayList
    foreach ($principalBinding in @(
        [pscustomobject]@{ role = 'requester'; requiredRole = 'ROLE_EVALUATION_OWNER'; value = [string]$Request.requesterPrincipalRef },
        [pscustomobject]@{ role = 'write-identity'; requiredRole = 'ROLE_GRAPH_AUTOMATION_OWNER'; value = [string]$Request.writeIdentityRef },
        [pscustomobject]@{ role = 'apply-operator'; requiredRole = 'ROLE_IAC_APPLY_OPERATOR'; value = [string]$Request.applyOperatorIdentityRef },
        [pscustomobject]@{ role = 'graph-read-identity'; requiredRole = 'ROLE_ENDPOINT_TELEMETRY_OWNER'; value = [string]$Readback.readIdentityRef },
        [pscustomobject]@{ role = 'directory-read-identity'; requiredRole = 'ROLE_DIRECTORY_READBACK_OWNER'; value = [string]$directoryPopulationReadback.readIdentityRef },
        [pscustomobject]@{ role = 'ledger-authority'; requiredRole = 'ROLE_AUTHORIZATION_LEDGER_OWNER'; value = [string]$authorizationConsumptionRecord.ledgerAuthorityIdentityRef },
        [pscustomobject]@{ role = 'ledger-observer'; requiredRole = 'ROLE_AUTHORIZATION_LEDGER_VERIFIER'; value = [string]$authorizationConsumptionReadbackRecord.readIdentityRef },
        [pscustomobject]@{ role = 'package-signer'; requiredRole = 'ROLE_SUPPLY_CHAIN_OWNER'; value = [string]$packageVerificationRecord.signerIdentityRef },
        [pscustomobject]@{ role = 'package-verifier'; requiredRole = 'ROLE_SECURITY_APPROVER'; value = [string]$packageVerificationRecord.verifierIdentityRef },
        [pscustomobject]@{ role = 'role-binding-source'; requiredRole = 'ROLE_IAC_PLATFORM_OWNER'; value = [string]$roleBindingClosure.RoleBinding.sourceIdentityRef },
        [pscustomobject]@{ role = 'role-binding-reader'; requiredRole = 'ROLE_DIRECTORY_READBACK_OWNER'; value = [string]$roleBindingClosure.Readback.readIdentityRef },
        [pscustomobject]@{ role = 'authorization-issuer'; requiredRole = 'ROLE_PROTECTED_ENVIRONMENT_APPROVER'; value = [string]$writeAuthorizationRecord.issuedByPrincipalRef },
        [pscustomobject]@{ role = 'identity-root-ceremony-operator'; requiredRole = 'ROLE_IDENTITY_SECURITY_APPROVER'; canonicalPrincipal = $true; value = [string]$roleBindingClosure.RootAuthority.ceremonyOperatorIdentityRef },
        [pscustomobject]@{ role = 'identity-root-reader'; requiredRole = 'ROLE_DIRECTORY_READBACK_OWNER'; canonicalPrincipal = $true; value = [string]$roleBindingClosure.RootAuthority.independentReadIdentityRef }
    )) {
        if (Test-NonBlankString $principalBinding.value) { [void]$operationPrincipals.Add($principalBinding) }
    }
    if ($null -ne $roleBindingClosure -and $null -ne $roleBindingClosure.RootAuthority) {
        foreach ($keyBinding in @($roleBindingClosure.RootAuthority.authorityKeyBindings)) {
            if (Test-NonBlankString $keyBinding.keyCustodianPrincipalId) {
                [void]$operationPrincipals.Add([pscustomobject]@{
                    role = 'identity-root-key-custodian'
                    requiredRole = ''
                    canonicalPrincipal = $true
                    value = [string]$keyBinding.keyCustodianPrincipalId
                })
            }
        }
    }
    if ($null -ne $approvalRecord) {
        foreach ($entry in @($approvalRecord.approvalEntries)) {
            if (Test-NonBlankString $entry.principalRef) {
                [void]$operationPrincipals.Add([pscustomobject]@{ role = 'approval'; requiredRole = [string]$entry.roleId; value = [string]$entry.principalRef })
            }
        }
    }
    if ($null -ne $phase2ApprovalRecord) {
        foreach ($entry in @($phase2ApprovalRecord.compatibilityApproval, $phase2ApprovalRecord.securityApproval)) {
            if (Test-NonBlankString $entry.principalRef) {
                [void]$operationPrincipals.Add([pscustomobject]@{ role = 'phase2-approval'; requiredRole = [string]$entry.roleId; value = [string]$entry.principalRef })
            }
        }
    }
    if ($null -ne $roleBindingClosure -and $null -ne $roleBindingClosure.Approval) {
        if (Test-NonBlankString $roleBindingClosure.Approval.approverPrincipalRef) {
            [void]$operationPrincipals.Add([pscustomobject]@{
                role = 'role-binding-approval'
                requiredRole = [string]$roleBindingClosure.Approval.approverRole
                canonicalPrincipal = $true
                value = [string]$roleBindingClosure.Approval.approverPrincipalRef
            })
        }
    }
    if ($null -ne $transportExceptionRecord -and (Test-NonBlankString $transportExceptionRecord.ownerPrincipalRef)) {
        [void]$operationPrincipals.Add([pscustomobject]@{ role = 'direct-graph-exception-owner'; requiredRole = [string]$transportExceptionRecord.ownerRole; value = [string]$transportExceptionRecord.ownerPrincipalRef })
    }
    foreach ($policyRecord in @($authorizationTtlPolicyRecord, $authorizationRevocationPolicyRecord, $packageRevocationPolicyRecord, $readbackFreshnessPolicyRecord)) {
        if ($null -ne $policyRecord -and (Test-NonBlankString $policyRecord.approvedByPrincipalRef)) {
            [void]$operationPrincipals.Add([pscustomobject]@{
                role = 'security-policy-approval'
                requiredRole = [string]$policyRecord.approvedByRole
                canonicalPrincipal = $true
                value = [string]$policyRecord.approvedByPrincipalRef
            })
        }
    }
    if (Test-ValuePresent $Request.rolloutMonitoringRef) {
        $principalMonitor = $recordMap[[string]$Request.rolloutMonitoringRef]
        foreach ($signal in @($principalMonitor.signals | Where-Object { [string]$_.applicabilityStatus -ceq 'NOT_APPLICABLE' })) {
            $signalApproval = $recordMap[[string]$signal.approvalRef]
            foreach ($entry in @($signalApproval.approvalEntries)) {
                if (Test-NonBlankString $entry.principalRef) {
                    [void]$operationPrincipals.Add([pscustomobject]@{ role = 'monitoring-approval'; requiredRole = [string]$entry.roleId; value = [string]$entry.principalRef })
                }
            }
        }
    }
    $principalSet = [System.Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
    $principalOverlap = $false
    foreach ($principalBinding in @($operationPrincipals)) {
        if ($principalBinding.canonicalPrincipal -eq $true) {
            $canonicalPrincipalId = [string]$principalBinding.value
            if ($canonicalPrincipalId -cnotmatch '^private://canonical-principals/sha256/[0-9a-f]{64}$' -or
                -not $principalSet.Add($canonicalPrincipalId)) { $principalOverlap = $true }
            continue
        }
        if ($null -eq $roleBindingClosure -or
            -not $roleBindingClosure.AliasMap.ContainsKey([string]$principalBinding.value)) {
            Add-BlueprintError -Errors $errors -Code 'ROLE_BINDING_ALIAS_UNRESOLVED_OR_AMBIGUOUS' -Message "Operation role alias for $($principalBinding.role) does not resolve exactly once to an immutable canonical principal identifier."
            continue
        }
        if (-not $roleBindingClosure.RoleMap.ContainsKey([string]$principalBinding.value) -or
            [string]$roleBindingClosure.RoleMap[[string]$principalBinding.value] -cne [string]$principalBinding.requiredRole) {
            Add-BlueprintError -Errors $errors -Code 'ROLE_BINDING_SEMANTIC_ROLE_MISMATCH' -Message "Operation actor $($principalBinding.role) is not bound to its exact frozen semantic role."
            continue
        }
        $canonicalPrincipalId = [string]$roleBindingClosure.AliasMap[[string]$principalBinding.value]
        if ($canonicalPrincipalId -cnotmatch '^private://canonical-principals/sha256/[0-9a-f]{64}$' -or -not $principalSet.Add($canonicalPrincipalId)) {
            $principalOverlap = $true
        }
    }
    if ($principalOverlap) {
        Add-BlueprintError -Errors $errors -Code 'OPERATION_PRINCIPAL_SEPARATION_VIOLATION' -Message 'Requester, write operator, independent readers, ledger authority and observer, and every operation approval principal must be distinct; no principal-overlap exception is modeled by this contract.'
    }

    [DateTimeOffset]$readbackCollectedAt = [DateTimeOffset]::MinValue
    $readbackTimeValid = [OperationsBlueprint.StrictRfc3339]::TryParse([string]$effectiveReadback.collectedAt, [ref]$readbackCollectedAt)
    if (-not $readbackTimeValid -or $readbackCollectedAt -le $writeCompletedAt -or $readbackCollectedAt -gt $EvaluationTime -or
        ($authorizationConsumptionObservedAt -ne [DateTimeOffset]::MinValue -and $readbackCollectedAt -lt $authorizationConsumptionObservedAt) -or
        ($EvaluationTime - $readbackCollectedAt).TotalMinutes -gt $effectiveReadbackMaxAgeMinutes) {
        Add-BlueprintError -Errors $errors -Code 'READBACK_TIME_INVALID' -Message 'Readback must be fresh, after the bound write, and not in the future.'
    }
    if (($effectiveReadback.httpStatus -isnot [int] -and $effectiveReadback.httpStatus -isnot [long]) -or [int64]$effectiveReadback.httpStatus -ne 200) {
        Add-BlueprintError -Errors $errors -Code 'GRAPH_READBACK_FAILED' -Message 'Graph readback did not return an exact 200 response.'
    }
    if ($effectiveReadback.responseBodyPresent -isnot [bool] -or -not $effectiveReadback.responseBodyPresent) {
        Add-BlueprintError -Errors $errors -Code 'READBACK_BODY_MISSING' -Message 'HTTP success without a readback body is incomplete.'
    }
    if ([string]$effectiveReadback.observedStateRevision -cne [string]$Request.desiredStateRevision) {
        Add-BlueprintError -Errors $errors -Code 'READBACK_REVISION_MISMATCH' -Message 'Observed and authorized revisions differ.'
    }
    if ([string]$effectiveReadback.observedPackageDigest -cne [string]$Request.packageDigest) {
        Add-BlueprintError -Errors $errors -Code 'READBACK_PACKAGE_MISMATCH' -Message 'Observed and authorized package digests differ.'
    }
    if ([string]$effectiveReadback.targetMembershipDigest -cne [string]$Request.targetMembershipDigest) {
        Add-BlueprintError -Errors $errors -Code 'READBACK_MEMBERSHIP_MISMATCH' -Message 'Observed and authorized membership snapshots differ.'
    }
    if ([string]$effectiveReadback.targetScopeRef -cne [string]$Request.targetScopeRef) {
        Add-BlueprintError -Errors $errors -Code 'READBACK_SCOPE_MISMATCH' -Message 'Observed and authorized scopes differ.'
    }
    if (-not (Test-CanonicalValueEqual $effectiveReadback.targetPopulation $Request.targetPopulation)) {
        Add-BlueprintError -Errors $errors -Code 'READBACK_TARGET_POPULATION_MISMATCH' -Message 'Observed readback population differs from the authorized ceiling, count, exclusions, composition, rule, and directory snapshot.'
    }
    if ($effectiveReadback.assignmentMatched -isnot [bool] -or -not $effectiveReadback.assignmentMatched -or
        $effectiveReadback.deviceStateMatched -isnot [bool] -or -not $effectiveReadback.deviceStateMatched) {
        Add-BlueprintError -Errors $errors -Code 'READBACK_STATE_MISMATCH' -Message 'Assignment or device readback does not match.'
    }

    Add-BlueprintError -Errors $errors -Code 'PRIVATE_ACTIVATION_IMPLEMENTATION_REQUIRED' -Message 'This public validator cannot establish authenticated private readback or issue an active state.'
    return New-BlueprintResult -Errors $errors -State $(if ([string]$ValidationProfile -ceq 'TEST') { 'TEST_FIXTURE_BLOCKED_NON_PROMOTABLE' } else { 'BLOCKED' })
}

function Test-BlueprintFileManifest {
    [CmdletBinding()]
    param([Parameter(Mandatory = $true)][string]$BlueprintRoot)

    $errors = New-Object System.Collections.ArrayList
    $expectedFiles = @(
        '.gitattributes',
        'control-matrix.json',
        'GOVERNANCE_AND_IAC_OPERATING_MODEL.md',
        'LEADERSHIP_DECISION_PACKET_TEMPLATE.md',
        'leadership-claim-chain.json',
        'operations-record-contracts.schema.json',
        'OperationsBlueprint.Tests.ps1',
        'private-activation-checklist.md',
        'README.md',
        'Test-OperationsBlueprint.ps1',
        'tool-registry.json'
    )
    try {
        $blueprintRootItem = Get-Item -LiteralPath $BlueprintRoot -Force -ErrorAction Stop
        if (-not $blueprintRootItem.PSIsContainer -or
            (([IO.FileAttributes]$blueprintRootItem.Attributes -band [IO.FileAttributes]::ReparsePoint) -ne 0)) {
            Add-BlueprintError -Errors $errors -Code 'BLUEPRINT_REPARSE_POINT_FORBIDDEN' -Message 'Blueprint root must be one regular directory, not a reparse point or link.'
            return New-BlueprintResult -Errors $errors -State 'BLOCKED'
        }
        if (-not (Test-TrustedWindowsPathBoundary -Path $blueprintRootItem.FullName)) {
            Add-BlueprintError -Errors $errors -Code 'BLUEPRINT_PATH_TRUST_BOUNDARY_INVALID' -Message 'Blueprint root must be on a fixed NTFS or ReFS volume with case sensitivity disabled on its complete non-reparse directory chain.'
            return New-BlueprintResult -Errors $errors -State 'BLOCKED'
        }
    }
    catch {
        Add-BlueprintError -Errors $errors -Code 'BLUEPRINT_DIRECTORY_UNREADABLE' -Message 'The blueprint directory could not be enumerated.'
        return New-BlueprintResult -Errors $errors -State 'BLOCKED'
    }
    $manifestPath = Join-Path $BlueprintRoot 'BLUEPRINT_MANIFEST.sha256'
    try {
        $allowedDirectoryEntries = @($expectedFiles) + 'BLUEPRINT_MANIFEST.sha256'
        foreach ($entry in @(Get-ChildItem -LiteralPath $BlueprintRoot -Force -ErrorAction Stop)) {
            if ((([IO.FileAttributes]$entry.Attributes -band [IO.FileAttributes]::ReparsePoint) -ne 0)) {
                Add-BlueprintError -Errors $errors -Code 'BLUEPRINT_REPARSE_POINT_FORBIDDEN' -Message "$($entry.Name) must be one regular in-directory file, not a reparse point or link."
            }
            if ($entry.PSIsContainer -or $allowedDirectoryEntries -cnotcontains [string]$entry.Name) {
                Add-BlueprintError -Errors $errors -Code 'BLUEPRINT_DIRECTORY_ENTRY_UNEXPECTED' -Message "Blueprint directory contains unmanifested or nested entry $($entry.Name)."
            }
        }
    }
    catch {
        Add-BlueprintError -Errors $errors -Code 'BLUEPRINT_DIRECTORY_UNREADABLE' -Message 'The blueprint directory could not be enumerated.'
    }
    if (-not (Test-Path -LiteralPath $manifestPath -PathType Leaf)) {
        Add-BlueprintError -Errors $errors -Code 'BLUEPRINT_MANIFEST_MISSING' -Message 'BLUEPRINT_MANIFEST.sha256 is required.'
        return New-BlueprintResult -Errors $errors -State 'BLOCKED'
    }
    $manifestItem = Get-Item -LiteralPath $manifestPath -Force -ErrorAction SilentlyContinue
    if ($null -eq $manifestItem -or
        (([IO.FileAttributes]$manifestItem.Attributes -band [IO.FileAttributes]::ReparsePoint) -ne 0)) {
        Add-BlueprintError -Errors $errors -Code 'BLUEPRINT_REPARSE_POINT_FORBIDDEN' -Message 'BLUEPRINT_MANIFEST.sha256 must be one regular in-directory file, not a reparse point or link.'
        return New-BlueprintResult -Errors $errors -State 'BLOCKED'
    }

    $entries = @{}
    try {
        $manifestLines = @(Get-Content -LiteralPath $manifestPath)
        foreach ($line in $manifestLines) {
            $match = [regex]::Match(
                [string]$line,
                '\A([0-9a-f]{64})  \./([^/\\]+)\z',
                [System.Text.RegularExpressions.RegexOptions]::CultureInvariant
            )
            if (-not $match.Success) {
                Add-BlueprintError -Errors $errors -Code 'BLUEPRINT_MANIFEST_MALFORMED' -Message 'Every manifest line must be lowercase SHA-256, two spaces, and an exact ./filename.'
                continue
            }
            $name = [string]$match.Groups[2].Value
            if ($entries.ContainsKey($name)) {
                Add-BlueprintError -Errors $errors -Code 'BLUEPRINT_MANIFEST_DUPLICATE' -Message "Manifest repeats $name."
                continue
            }
            $entries[$name] = [string]$match.Groups[1].Value
        }
    }
    catch {
        Add-BlueprintError -Errors $errors -Code 'BLUEPRINT_MANIFEST_UNREADABLE' -Message 'The blueprint manifest could not be read or parsed.'
        return New-BlueprintResult -Errors $errors -State 'BLOCKED'
    }

    foreach ($name in $expectedFiles) {
        if (-not $entries.ContainsKey($name)) {
            Add-BlueprintError -Errors $errors -Code 'BLUEPRINT_MANIFEST_ENTRY_MISSING' -Message "Manifest omits $name."
            continue
        }
        $path = Join-Path $BlueprintRoot $name
        if (-not (Test-Path -LiteralPath $path -PathType Leaf)) {
            Add-BlueprintError -Errors $errors -Code 'BLUEPRINT_FILE_MISSING' -Message "$name is missing."
            continue
        }
        $fileItem = Get-Item -LiteralPath $path -Force -ErrorAction SilentlyContinue
        if ($null -eq $fileItem -or
            (([IO.FileAttributes]$fileItem.Attributes -band [IO.FileAttributes]::ReparsePoint) -ne 0)) {
            Add-BlueprintError -Errors $errors -Code 'BLUEPRINT_REPARSE_POINT_FORBIDDEN' -Message "$name must be one regular in-directory file, not a reparse point or link."
            continue
        }
        if (-not (Test-TrustedWindowsPathBoundary -Path $path -RequireLeaf)) {
            Add-BlueprintError -Errors $errors -Code 'BLUEPRINT_PATH_TRUST_BOUNDARY_INVALID' -Message "$name is outside the fixed, case-insensitive, non-reparse Windows filesystem trust boundary."
            continue
        }
        try {
            $actualHash = ([string](Get-FileHash -LiteralPath $path -Algorithm SHA256).Hash).ToLowerInvariant()
            if ($actualHash -cne [string]$entries[$name]) {
                Add-BlueprintError -Errors $errors -Code 'BLUEPRINT_FILE_HASH_MISMATCH' -Message "$name differs from BLUEPRINT_MANIFEST.sha256."
            }
        }
        catch {
            Add-BlueprintError -Errors $errors -Code 'BLUEPRINT_FILE_HASH_UNAVAILABLE' -Message "$name could not be hashed."
        }
    }

    foreach ($name in @($entries.Keys)) {
        if ($expectedFiles -cnotcontains [string]$name) {
            Add-BlueprintError -Errors $errors -Code 'BLUEPRINT_MANIFEST_ENTRY_UNEXPECTED' -Message "Manifest contains unexpected file $name."
        }
    }
    if ($entries.Count -ne $expectedFiles.Count) {
        Add-BlueprintError -Errors $errors -Code 'BLUEPRINT_MANIFEST_FILE_COUNT_MISMATCH' -Message "Manifest must cover exactly $($expectedFiles.Count) functional files and exclude itself."
    }

    $state = if ($errors.Count -eq 0) { 'VALID' } else { 'BLOCKED' }
    $result = New-BlueprintResult -Errors $errors -State $state
    $result.Allowed = $false
    return $result
}

function Test-OperationsBlueprintBundle {
    [CmdletBinding()]
    param([Parameter(Mandatory = $true)][string]$BlueprintRoot)

    $errors = New-Object System.Collections.ArrayList
    $registry = $null
    $matrix = $null
    $chain = $null
    $operationsContracts = $null
    $manifestResult = Test-BlueprintFileManifest -BlueprintRoot $BlueprintRoot
    foreach ($error in @($manifestResult.Errors)) { [void]$errors.Add($error) }
    foreach ($item in @(
        @{ Name = 'tool-registry.json'; Variable = 'registry' },
        @{ Name = 'control-matrix.json'; Variable = 'matrix' },
        @{ Name = 'leadership-claim-chain.json'; Variable = 'chain' },
        @{ Name = 'operations-record-contracts.schema.json'; Variable = 'operationsContracts' }
    )) {
        $path = Join-Path $BlueprintRoot $item.Name
        try {
            $rawJson = Get-Content -LiteralPath $path -Raw
            foreach ($duplicate in @(Get-DuplicateJsonPropertyNames -JsonText $rawJson)) {
                Add-BlueprintError -Errors $errors -Code 'DUPLICATE_JSON_PROPERTY' -Message "$($item.Name) repeats or case-collides property $($duplicate.Name) at $($duplicate.Path)."
            }
            $trimmedJson = ([string]$rawJson).TrimStart()
            $parsedItems = @($rawJson | ConvertFrom-Json)
            if (-not $trimmedJson.StartsWith('{', [System.StringComparison]::Ordinal) -or
                $parsedItems.Count -ne 1 -or $null -eq $parsedItems[0] -or
                $parsedItems[0] -isnot [pscustomobject]) {
                Add-BlueprintError -Errors $errors -Code 'BLUEPRINT_FILE_INVALID_SHAPE' -Message "$($item.Name) must contain one JSON object."
            }
            elseif (-not (Test-CanonicalJsonRuntimeDomain -Value $parsedItems[0])) {
                Add-BlueprintError -Errors $errors -Code 'CANONICAL_JSON_RUNTIME_DOMAIN_INVALID' -Message "$($item.Name) contains a value outside the frozen cross-host JSON runtime domain."
            }
            else {
                Set-Variable -Name $item.Variable -Value $parsedItems[0]
            }
        }
        catch {
            Add-BlueprintError -Errors $errors -Code 'BLUEPRINT_FILE_INVALID' -Message "$($item.Name) could not be read as one valid JSON object."
        }
    }

    if ($null -ne $registry) {
        $result = Test-ToolRegistry -Registry $registry
        foreach ($error in @($result.Errors)) { [void]$errors.Add($error) }
    }
    if ($null -ne $matrix -and $null -ne $registry) {
        $result = Test-ControlMatrix -Matrix $matrix -Registry $registry
        foreach ($error in @($result.Errors)) { [void]$errors.Add($error) }
    }
    if ($null -ne $chain) {
        $result = Test-LeadershipClaimChain -Chain $chain
        foreach ($error in @($result.Errors)) { [void]$errors.Add($error) }
    }
    if ($null -ne $operationsContracts -and
        ([string]$operationsContracts.'$schema' -cne 'https://json-schema.org/draft/2020-12/schema' -or
         [string]$operationsContracts.'$id' -cne 'urn:laptop-qual:operations-record-contracts:1.0.0' -or
         [string]$operationsContracts.type -cne 'array')) {
        Add-BlueprintError -Errors $errors -Code 'OPERATIONS_CONTRACT_SCHEMA_IDENTITY_INVALID' -Message 'Operations record contracts must remain the declared non-normative Draft 2020-12 array schema.'
    }

    if ($null -ne $registry -and (Test-ValuePresent $registry.immutableRelease.gitTreeId)) {
        if (@(Get-UnsafeGitEnvironmentVariableNames).Count -gt 0) {
            Add-BlueprintError -Errors $errors -Code 'UNSAFE_GIT_ENVIRONMENT' -Message 'Repository selection, object replacement, configuration injection, helper execution, and dynamic-loader Git environment overrides are forbidden during immutable-release verification.'
        }
        if ([string]::IsNullOrWhiteSpace([string](Get-TrustedGitApplication))) {
            Add-BlueprintError -Errors $errors -Code 'TRUSTED_GIT_PIN_INVALID' -Message 'Immutable-release verification requires an absolute external Git executable and complete runtime root whose bytes match the lowercase executable and runtime-tree SHA-256 pins.'
        }
        $current = Get-Location
        try {
            $candidate = [IO.DirectoryInfo]::new((Resolve-Path -LiteralPath $BlueprintRoot).Path)
            while ($null -ne $candidate -and -not (Test-Path -LiteralPath (Join-Path $candidate.FullName '.git') -PathType Any)) {
                $candidate = $candidate.Parent
            }
            if ($null -eq $candidate) {
                Add-BlueprintError -Errors $errors -Code 'IMMUTABLE_RELEASE_UNVERIFIED' -Message 'Git repository root was not found.'
            }
            else {
                Set-Location -LiteralPath $candidate.FullName
                $treeResult = Invoke-GitRead -Arguments @('rev-parse', "HEAD:$($registry.immutableRelease.path)")
                $tree = @($treeResult.Lines)
                if ($treeResult.ExitCode -ne 0 -or $tree.Count -ne 1) {
                    Add-BlueprintError -Errors $errors -Code 'IMMUTABLE_RELEASE_UNVERIFIED' -Message 'Current immutable release tree could not be resolved.'
                }
                elseif ([string]$tree[0] -cne [string]$registry.immutableRelease.gitTreeId) {
                    Add-BlueprintError -Errors $errors -Code 'IMMUTABLE_RELEASE_CHANGED' -Message 'v2.0.1 differs from its pinned Git tree.'
                }
                else {
                    $treeFilesResult = Invoke-GitRead -Arguments @('ls-tree', '-r', '--name-only', $tree[0])
                    $treeFiles = @($treeFilesResult.Lines)
                    if ($treeFilesResult.ExitCode -ne 0 -or $treeFiles.Count -ne [int]$registry.immutableRelease.fileCount) {
                        Add-BlueprintError -Errors $errors -Code 'IMMUTABLE_RELEASE_FILE_COUNT_MISMATCH' -Message 'Pinned v2.0.1 tree does not have the declared file count.'
                    }
                    if ($treeFilesResult.ExitCode -eq 0) {
                        try {
                            $releaseFilesystemRoot = [IO.Path]::GetFullPath((Join-Path $candidate.FullName ([string]$registry.immutableRelease.path)))
                            if (-not (Test-TrustedWindowsPathBoundary -Path $releaseFilesystemRoot)) {
                                Add-BlueprintError -Errors $errors -Code 'IMMUTABLE_RELEASE_PATH_TRUST_BOUNDARY_INVALID' -Message 'The immutable release must remain on a fixed NTFS or ReFS volume with case sensitivity disabled on its complete directory chain.'
                                throw 'immutable release path boundary is not trusted'
                            }
                            $releaseItems = @(Get-ChildItem -LiteralPath $releaseFilesystemRoot -Force -Recurse -ErrorAction Stop)
                            $hasReparsePoint = @($releaseItems | Where-Object {
                                ([IO.FileAttributes]$_.Attributes -band [IO.FileAttributes]::ReparsePoint) -ne 0
                            }).Count -gt 0
                            [string[]]$filesystemFiles = @(
                                $releaseItems | Where-Object { -not $_.PSIsContainer } | ForEach-Object {
                                    ([IO.Path]::GetFullPath($_.FullName).Substring($releaseFilesystemRoot.Length)).TrimStart(
                                        [IO.Path]::DirectorySeparatorChar,
                                        [IO.Path]::AltDirectorySeparatorChar
                                    ).Replace([IO.Path]::DirectorySeparatorChar, '/')
                                }
                            )
                            [string[]]$committedFiles = @($treeFiles | ForEach-Object { ([string]$_).Replace('\', '/') })
                            [Array]::Sort($filesystemFiles, [StringComparer]::Ordinal)
                            [Array]::Sort($committedFiles, [StringComparer]::Ordinal)
                            if ($hasReparsePoint -or -not (Test-CanonicalValueEqual $filesystemFiles $committedFiles)) {
                                Add-BlueprintError -Errors $errors -Code 'IMMUTABLE_RELEASE_FILESYSTEM_INVENTORY_MISMATCH' -Message 'The on-disk immutable subtree contains a missing, extra, ignored, or reparse-point entry outside the committed Git tree inventory.'
                            }
                            $treeObjectsResult = Invoke-GitRead -Arguments @('ls-tree', '-r', $tree[0])
                            $treeObjectMap = [System.Collections.Generic.Dictionary[string,string]]::new([StringComparer]::Ordinal)
                            $treeObjectsValid = $treeObjectsResult.ExitCode -eq 0
                            foreach ($treeObjectLine in @($treeObjectsResult.Lines)) {
                                $treeObjectMatch = [regex]::Match(
                                    [string]$treeObjectLine,
                                    '^[0-9]{6} blob ([0-9a-f]{40}|[0-9a-f]{64})\t(.+)$',
                                    [Text.RegularExpressions.RegexOptions]::CultureInvariant
                                )
                                if (-not $treeObjectMatch.Success -or
                                    $treeObjectMap.ContainsKey([string]$treeObjectMatch.Groups[2].Value)) {
                                    $treeObjectsValid = $false
                                    continue
                                }
                                $treeObjectMap.Add(
                                    [string]$treeObjectMatch.Groups[2].Value,
                                    [string]$treeObjectMatch.Groups[1].Value
                                )
                            }
                            if ($treeObjectMap.Count -ne $committedFiles.Count) { $treeObjectsValid = $false }
                            foreach ($committedFile in $committedFiles) {
                                if (-not $treeObjectMap.ContainsKey([string]$committedFile)) {
                                    $treeObjectsValid = $false
                                    continue
                                }
                                $absoluteFile = [IO.Path]::GetFullPath((Join-Path $releaseFilesystemRoot ([string]$committedFile)))
                                $releasePrefix = $releaseFilesystemRoot.TrimEnd(
                                    [IO.Path]::DirectorySeparatorChar,
                                    [IO.Path]::AltDirectorySeparatorChar
                                ) + [IO.Path]::DirectorySeparatorChar
                                $releasePathComparison = if (Test-IsWindowsRuntime) {
                                    [StringComparison]::OrdinalIgnoreCase
                                }
                                else { [StringComparison]::Ordinal }
                                if (-not $absoluteFile.StartsWith($releasePrefix, $releasePathComparison)) {
                                    $treeObjectsValid = $false
                                    continue
                                }
                                $absoluteFileItem = Get-Item -LiteralPath $absoluteFile -Force -ErrorAction Stop
                                if ($absoluteFileItem.PSIsContainer -or
                                    (([IO.FileAttributes]$absoluteFileItem.Attributes -band [IO.FileAttributes]::ReparsePoint) -ne 0) -or
                                    -not (Test-TrustedWindowsPathBoundary -Path $absoluteFile -RequireLeaf)) {
                                    $treeObjectsValid = $false
                                    continue
                                }
                                $expectedObjectId = [string]$treeObjectMap[[string]$committedFile]
                                $worktreeObjectId = Get-GitBlobObjectIdFromFile -Path $absoluteFile -ObjectIdLength $expectedObjectId.Length
                                if ([string]::IsNullOrWhiteSpace($worktreeObjectId) -or
                                    $worktreeObjectId -cne $expectedObjectId) {
                                    $treeObjectsValid = $false
                                }
                            }
                            if (-not $treeObjectsValid) {
                                Add-BlueprintError -Errors $errors -Code 'IMMUTABLE_RELEASE_CONTENT_MISMATCH' -Message 'One or more immutable-release worktree bytes do not match the exact blob objects in the pinned Git tree.'
                            }
                        }
                        catch {
                            Add-BlueprintError -Errors $errors -Code 'IMMUTABLE_RELEASE_FILESYSTEM_INVENTORY_MISMATCH' -Message 'The on-disk immutable subtree inventory could not be independently enumerated.'
                        }
                    }
                }

                $baselineResult = Invoke-GitRead -Arguments @('rev-parse', "$($registry.immutableRelease.baselineCommit):$($registry.immutableRelease.path)")
                $baselineLines = @($baselineResult.Lines)
                if ($baselineResult.ExitCode -ne 0 -or $baselineLines.Count -ne 1 -or
                    [string]$baselineLines[0] -cne [string]$registry.immutableRelease.gitTreeId) {
                    Add-BlueprintError -Errors $errors -Code 'IMMUTABLE_RELEASE_BASELINE_MISMATCH' -Message 'Declared baseline commit does not resolve to the pinned v2.0.1 tree.'
                }
                $baselineAncestorResult = Invoke-GitRead -Arguments @(
                    'merge-base', '--is-ancestor', [string]$registry.immutableRelease.baselineCommit, 'HEAD'
                )
                if ($baselineAncestorResult.ExitCode -ne 0) {
                    Add-BlueprintError -Errors $errors -Code 'IMMUTABLE_RELEASE_BASELINE_NOT_ANCESTOR' -Message 'Declared immutable-release baseline is not an ancestor of the exact repository HEAD being verified.'
                }
                $releaseCommitResult = Invoke-GitRead -Arguments @(
                    'log', '--no-show-signature', '-n', '1', '--format=%H', 'HEAD', '--', [string]$registry.immutableRelease.path
                )
                $releaseCommitLines = @($releaseCommitResult.Lines)
                if ($releaseCommitResult.ExitCode -ne 0 -or $releaseCommitLines.Count -ne 1 -or
                    [string]$releaseCommitLines[0] -cne [string]$registry.immutableRelease.baselineCommit) {
                    Add-BlueprintError -Errors $errors -Code 'IMMUTABLE_RELEASE_BASELINE_COMMIT_MISMATCH' -Message 'Declared baseline commit is not the repository commit that most recently established the pinned immutable release subtree.'
                }
            }
        }
        finally {
            Set-Location -LiteralPath $current.Path
        }
    }

    # The public bundle cannot activate a tenant. Never surface a caller-controlled
    # registry declaration as the effective control-plane state, including when
    # validation has already blocked the bundle.
    $activationState = 'HOLD'
    $bundleState = if ($errors.Count -eq 0) { 'VALID' } else { 'BLOCKED' }
    $bundleResult = New-BlueprintResult -Errors $errors -State $bundleState
    # This checked-in function validates public blueprint shape and provenance
    # only. Private authenticated orchestration owns every authorization.
    $bundleResult.Allowed = $false
    $bundleResult | Add-Member -NotePropertyName ActivationState -NotePropertyValue $activationState
    return $bundleResult
}

if (-not $LoadFunctionsOnly) {
    $result = Test-OperationsBlueprintBundle -BlueprintRoot $BlueprintRoot
    $result | ConvertTo-Json -Depth 8
    if (-not $result.Valid) { exit 1 }
}
